local S = {}
S.__helpers = {}

-- ================================================================
-- EXECUTOR CHECK
-- ================================================================
S.executorName = "Unknown"
S.executorVersion = nil
S.isXenoExecutor = false
S.isSolaraExecutor = false
S.isVolcanoExecutor = false
S.isUnsupportedExecutor = false
S.executorCheckAvailable = false

S.__helpers.checkExecutor = function()
    local detected = nil
    local version = nil

    -- Prefer identifyexecutor because it can also return a build/version string.
    if type(identifyexecutor) == "function" then
        local ok, name, build = pcall(identifyexecutor)
        if ok and name ~= nil and tostring(name) ~= "" then
            detected = name
            version = build
            S.executorCheckAvailable = true
        end
    end

    -- Fallback for executors that expose getexecutorname instead.
    if (detected == nil or tostring(detected) == "")
        and type(getexecutorname) == "function" then
        local ok, name = pcall(getexecutorname)
        if ok and name ~= nil and tostring(name) ~= "" then
            detected = name
            S.executorCheckAvailable = true
        end
    end

    S.executorName = tostring(detected or "Unknown")
    S.executorVersion = version ~= nil and tostring(version) or nil

    local normalizedName = S.executorName:lower()
    local firstToken = normalizedName:match("^%s*(%S+)") or ""
    S.isXenoExecutor = firstToken == "xeno" or normalizedName:find("xeno", 1, true) ~= nil
    S.isSolaraExecutor = firstToken == "solara" or normalizedName:find("solara", 1, true) ~= nil
    -- Volcano is the intended executor name; block it before UI setup.
    S.isVolcanoExecutor = firstToken == "volcano"
        or normalizedName:find("volcano", 1, true) ~= nil
    S.isUnsupportedExecutor = S.isXenoExecutor or S.isSolaraExecutor or S.isVolcanoExecutor

    return S.executorName, S.executorVersion, S.isUnsupportedExecutor
end

S.__helpers.checkExecutor()

-- Xeno, Solara, and Volcano are intentionally blocked before
-- services are initialized, old GUI instances are cleaned up, or any UI is created.
-- This early main-chunk return prevents all subsequent UI generation.
if S.isUnsupportedExecutor then
    print("Your executor is not support")
    return
end

