-- Consolidated local visual folders. World-space parts stay in Workspace,
-- while CoreGui highlight folders stay in CoreGui; both are grouped beneath
-- an E1LU4SAKEN root because Roblox does not render Workspace parts from CoreGui
-- (or CoreGui adornments from Workspace).
S.ROOT_FOLDER_NAME = "E1LU4SAKEN"
S.__helpers.getWorldRootFolder = function()
    local folder = workspace:FindFirstChild(S.ROOT_FOLDER_NAME)
    if folder and not folder:IsA("Folder") then
        return workspace
    end
    if not folder then
        folder = Instance.new("Folder")
        folder.Name = S.ROOT_FOLDER_NAME
        folder.Parent = workspace
    end
    return folder
end
S.__helpers.getCoreGuiRootFolder = function()
    local folder = S.CoreGui:FindFirstChild(S.ROOT_FOLDER_NAME)
    if folder and not folder:IsA("Folder") then
        return S.CoreGui
    end
    if not folder then
        folder = Instance.new("Folder")
        folder.Name = S.ROOT_FOLDER_NAME
        folder.Parent = S.CoreGui
    end
    return folder
end

S.__helpers.clearLegacyESPProxyOverlays = function()
    local root = workspace:FindFirstChild(S.ROOT_FOLDER_NAME)
    if not root then return end

    local folder = root:FindFirstChild("E1LU4HUB_NeonESPVisuals")
    if folder and folder:IsA("Folder") then
        pcall(function() folder:Destroy() end)
    end
end
S.__helpers.clearLegacyESPProxyOverlays()

S.neonESPHitboxPartOverlays = setmetatable({}, {__mode = "k"})
S.neonESPOverlayFolder = nil
S.neonESPOverlayRenderConnection = nil
S.neonESPOverlayId = 0

S.__helpers.getNeonESPOverlayFolder = function()
    local root = S.__helpers.getWorldRootFolder()
    local folder = S.neonESPOverlayFolder
    if not folder or not folder.Parent then
        folder = root:FindFirstChild("E1LU4HUB_NeonESPOverlays")
        if folder and not folder:IsA("Folder") then return nil end
        if not folder then
            folder = Instance.new("Folder")
            folder.Name = "E1LU4HUB_NeonESPOverlays"
            folder.Parent = root
        end
        S.neonESPOverlayFolder = folder
    end
    return folder
end

S.__helpers.createNeonESPProxyPart = function(sourcePart, parent, proxyName, color, transparency)
    if not sourcePart or not sourcePart:IsA("BasePart") or not parent then
        return nil
    end
    local ok, proxy = pcall(function() return sourcePart:Clone() end)
    if not ok or not proxy or not proxy:IsA("BasePart") then return nil end

    for _, child in ipairs(proxy:GetDescendants()) do
        if not child:IsA("DataModelMesh") then
            pcall(function() child:Destroy() end)
        else
            pcall(function() child.TextureId = "" end)
        end
    end
    pcall(function()
        if proxy:IsA("MeshPart") then proxy.TextureID = "" end
        proxy.Name = proxyName or ("NeonESP_" .. sourcePart.Name)
        proxy.Anchored = true
        proxy.CanCollide = false
        proxy.CanTouch = false
        proxy.CanQuery = false
        proxy.CastShadow = false
        proxy.Massless = true
        -- Keep the source material so ForceField fill and Neon edges remain distinct.
        proxy.Material = sourcePart.Material
        proxy.MaterialVariant = ""
        proxy.Reflectance = 0
        proxy.Color = color or sourcePart.Color
        proxy.Transparency = math.clamp(tonumber(transparency) or 0, 0, 1)
        proxy.LocalTransparencyModifier = 0
        proxy.Parent = parent
    end)
    if not proxy.Parent then
        pcall(function() proxy:Destroy() end)
        return nil
    end
    return proxy
end

S.__helpers.removeNeonESPHitboxPartOverlay = function(sourcePart)
    local overlays = S.neonESPHitboxPartOverlays
    local state = overlays and overlays[sourcePart]
    if not state then return end
    overlays[sourcePart] = nil
    if state.destroyingConnection then
        pcall(function() state.destroyingConnection:Disconnect() end)
    end
    if state.folder and state.folder.Parent then
        pcall(function() state.folder:Destroy() end)
    end
    if next(overlays) == nil and S.neonESPOverlayRenderConnection then
        pcall(function() S.neonESPOverlayRenderConnection:Disconnect() end)
        S.neonESPOverlayRenderConnection = nil
        local folder = S.neonESPOverlayFolder
        if folder and folder.Parent and #folder:GetChildren() == 0 then
            pcall(function() folder:Destroy() end)
            S.neonESPOverlayFolder = nil
        end
    end
end

S.__helpers.ensureNeonESPOverlayRender = function()
    if S.neonESPOverlayRenderConnection then return end
    S.neonESPOverlayRenderConnection = S.RunService.RenderStepped:Connect(function()
        for sourcePart, overlay in pairs(S.neonESPHitboxPartOverlays) do
            if not sourcePart or not sourcePart.Parent
                or not overlay.proxy or not overlay.proxy.Parent then
                S.__helpers.removeNeonESPHitboxPartOverlay(sourcePart)
            else
                pcall(function()
                    overlay.proxy.CFrame = sourcePart.CFrame
                    overlay.proxy.Size = sourcePart.Size + Vector3.new(0.01, 0.01, 0.01)
                    overlay.proxy.Color = sourcePart.Color
                    -- Mirror the source material (ForceField fill / Neon outline).
                    overlay.proxy.Material = sourcePart.Material
                    overlay.proxy.Transparency = overlay.transparency
                end)
            end
        end
    end)
end

S.__helpers.addNeonESPHitboxPartOverlay = function(sourcePart, transparency)
    if not sourcePart or not sourcePart:IsA("BasePart") or not sourcePart.Parent then
        return false
    end
    local overlays = S.neonESPHitboxPartOverlays
    local existing = overlays[sourcePart]
    if existing and existing.proxy and existing.proxy.Parent then
        existing.transparency = math.clamp(tonumber(transparency) or existing.transparency, 0, 1)
        return true
    elseif existing then
        S.__helpers.removeNeonESPHitboxPartOverlay(sourcePart)
    end

    local overlayRoot = S.__helpers.getNeonESPOverlayFolder()
    if not overlayRoot then return false end
    S.neonESPOverlayId += 1
    local overlayFolder = Instance.new("Folder")
    overlayFolder.Name = "HitboxPrediction_" .. tostring(S.neonESPOverlayId)
    overlayFolder.Parent = overlayRoot
    local desiredTransparency = math.clamp(tonumber(transparency) or 0, 0, 1)
    local proxy = S.__helpers.createNeonESPProxyPart(
        sourcePart,
        overlayFolder,
        "NeonHitboxPrediction_" .. sourcePart.Name,
        sourcePart.Color,
        desiredTransparency
    )
    if not proxy then
        pcall(function() overlayFolder:Destroy() end)
        return false
    end

    local state = {folder = overlayFolder, proxy = proxy, transparency = desiredTransparency}
    overlays[sourcePart] = state
    pcall(function()
        state.destroyingConnection = sourcePart.Destroying:Connect(function()
            S.__helpers.removeNeonESPHitboxPartOverlay(sourcePart)
        end)
    end)
    S.__helpers.ensureNeonESPOverlayRender()
    return true
end

S.__helpers.detectCurrentDevice = function()
    local platformName = ""
    pcall(function() platformName = tostring(S.GuiService:GetPlatform()):lower() end)
    if platformName:find("xbox", 1, true) or platformName:find("playstation", 1, true)
        or platformName:find("ps4", 1, true) or platformName:find("ps5", 1, true)
        or platformName:find("nintendo", 1, true) or platformName:find("switch", 1, true) then
        return "Console"
    end
    if platformName:find("ios", 1, true) or platformName:find("android", 1, true)
        or platformName:find("mobile", 1, true) then
        return "Mobile"
    end
    if S.UserInputService.TouchEnabled and not S.UserInputService.KeyboardEnabled then
        return "Mobile"
    end
    if S.UserInputService.KeyboardEnabled then
        return "PC"
    end
    if S.UserInputService.GamepadEnabled and not S.UserInputService.TouchEnabled then
        return "Console"
    end
    local inputName = ""
    pcall(function() inputName = S.UserInputService:GetLastInputType().Name:lower() end)
    if inputName == "touch" then return "Mobile" end
    if inputName:find("gamepad", 1, true) then return "Console" end
    return "PC"
end
S.initialDetectedDevice = S.__helpers.detectCurrentDevice()
S.initialDeviceIsPC = S.initialDetectedDevice == "PC"
S.deviceSpoofCurrent = S.initialDetectedDevice

-- Early role helpers are available to Heartbeat callbacks created near the top
-- of this file, before the later role-folder utilities are initialized.
S.__helpers.getLocalRole = function()
    local character = S.lp and S.lp.Character
    if not character then return nil end
    local playersFolder = workspace:FindFirstChild("Players")
    local survivorsFolder = playersFolder and playersFolder:FindFirstChild("Survivors")
    local killersFolder = playersFolder and playersFolder:FindFirstChild("Killers")
    if survivorsFolder and character:IsDescendantOf(survivorsFolder) then
        return "Survivor"
    end
    if killersFolder and character:IsDescendantOf(killersFolder) then
        return "Killer"
    end
    return nil
end
S.__helpers.isLocalRole = function(expectedRole)
    return S.__helpers.getLocalRole() == expectedRole
end

-- Guest-only combat features must run only while the local character's exact
-- model name is Guest1337. Keep this independent from role detection so other
-- role-gated features are not affected.
S.__helpers.isLocalGuest1337 = function()
    local character = S.lp and S.lp.Character
    return character ~= nil and character.Name == "Guest1337"
end

