S.__helpers.connect = function(signal, callback)
    local connection = signal:Connect(callback)
    table.insert(S.connections, connection)
    return connection
end

S.__helpers.disconnectAll = function()
    for _, connection in ipairs(S.connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end

    table.clear(S.connections)
end


-- ================================================================
-- SHOW CHAT
-- Keep the TextChatService chat window enabled while the option is ON.
-- ================================================================
S.isShowChatEnabled = false
S.showChatBoundConfig = nil

S.getChatWindowConfiguration = function()
    local ok, config = pcall(function()
        return S.TextChatService:FindFirstChild("ChatWindowConfiguration")
            or S.TextChatService:FindFirstChildOfClass("ChatWindowConfiguration")
    end)
    if ok then return config end
    return nil
end

S.bindShowChatConfiguration = function(config)
    if not config then return end
    if S.showChatBoundConfig == config then
        if S.isShowChatEnabled then
            pcall(function() config.Enabled = true end)
        end
        return
    end
    S.showChatBoundConfig = config
    if S.isShowChatEnabled then
        pcall(function() config.Enabled = true end)
    end
    S.__helpers.connect(config:GetPropertyChangedSignal("Enabled"), function()
        if S.isShowChatEnabled and config.Parent and config.Enabled ~= true then
            pcall(function() config.Enabled = true end)
        end
    end)
end

S.applyShowChatState = function(value)
    S.isShowChatEnabled = value == true
    local config = S.getChatWindowConfiguration()
    if config then
        pcall(function() config.Enabled = S.isShowChatEnabled end)
        S.bindShowChatConfiguration(config)
    end
end

S.__helpers.connect(S.TextChatService.ChildAdded, function(child)
    if child.Name == "ChatWindowConfiguration" then
        S.bindShowChatConfiguration(child)
    end
end)
S.bindShowChatConfiguration(S.getChatWindowConfiguration())


-- Fullbright: snapshot and restore lighting values and existing part shadows.
S.isFullBrightEnabled = false
S.fullBrightLighting = game:GetService("Lighting")
S.fullBrightOriginalLighting = nil
S.fullBrightPartShadows = setmetatable({}, {__mode = "k"})
S.fullBrightConnections = {}
S.__helpers.applyFullBright = function()
    if not S.isFullBrightEnabled then return end
    local lighting = S.fullBrightLighting
    pcall(function()
        lighting.Ambient = Color3.fromRGB(255, 255, 255)
        lighting.OutdoorAmbient = Color3.fromRGB(255, 255, 255)
        lighting.Brightness = 2
        lighting.ClockTime = 14
        lighting.FogEnd = 100000
        lighting.GlobalShadows = false
    end)
    local function disableShadow(instance)
        if instance:IsA("BasePart") then
            if S.fullBrightPartShadows[instance] == nil then
                S.fullBrightPartShadows[instance] = instance.CastShadow
            end
            pcall(function() instance.CastShadow = false end)
        end
    end
    for _, instance in ipairs(workspace:GetDescendants()) do disableShadow(instance) end
end
S.setFullBright = function(enabled)
    enabled = enabled == true
    if enabled == S.isFullBrightEnabled then
        if enabled then S.__helpers.applyFullBright() end
        return
    end
    local lighting = S.fullBrightLighting
    if enabled then
        S.fullBrightOriginalLighting = {}
        for _, property in ipairs({"Ambient", "OutdoorAmbient", "Brightness", "ClockTime", "FogEnd", "GlobalShadows"}) do
            local ok, value = pcall(function() return lighting[property] end)
            if ok then S.fullBrightOriginalLighting[property] = value end
        end
        S.isFullBrightEnabled = true
        S.__helpers.applyFullBright()
        table.insert(S.fullBrightConnections, workspace.DescendantAdded:Connect(function(instance)
            if not S.isFullBrightEnabled or not instance:IsA("BasePart") then return end
            if S.fullBrightPartShadows[instance] == nil then
                S.fullBrightPartShadows[instance] = instance.CastShadow
            end
            pcall(function() instance.CastShadow = false end)
        end))
        table.insert(S.fullBrightConnections, lighting.ChildAdded:Connect(function()
            if S.isFullBrightEnabled then task.defer(S.__helpers.applyFullBright) end
        end))
    else
        S.isFullBrightEnabled = false
        for _, connection in ipairs(S.fullBrightConnections) do pcall(function() connection:Disconnect() end) end
        table.clear(S.fullBrightConnections)
        if S.fullBrightOriginalLighting then
            for property, value in pairs(S.fullBrightOriginalLighting) do
                pcall(function() lighting[property] = value end)
            end
        end
        S.fullBrightOriginalLighting = nil
        for part, original in pairs(S.fullBrightPartShadows) do
            if part and part.Parent then pcall(function() part.CastShadow = original end) end
            S.fullBrightPartShadows[part] = nil
        end
    end
end

