S.AUTO_BLOCK_USE_HITBOX_GRACE_BY_KILLER = {
    c00lkidd = 0.3,
    slasher = 0.4,
    sixer = 0.5,
    nosferatu = 0.5,
    noli = 0.5,
    oneXoneXone = 0.6,
    johnDoe = 0.6,
    azure = 0.5,
}
S.__helpers.getAutoBlockUseHitboxGraceSeconds = function(killer)
    local fallback = tonumber(S.AUTO_BLOCK_USE_HITBOX_GRACE_SECONDS) or 0.5
    if not killer then return fallback end

    local name = tostring(killer.Name or ""):lower():gsub("[%s_%-]", "")
    local durations = S.AUTO_BLOCK_USE_HITBOX_GRACE_BY_KILLER or {}
    if name:find("c00lkidd", 1, true) or name:find("coolkidd", 1, true) then
        return tonumber(durations.c00lkidd) or fallback
    elseif name:find("slasher", 1, true) then
        return tonumber(durations.slasher) or fallback
    elseif name:find("sixer", 1, true) then
        return tonumber(durations.sixer) or fallback
    elseif name:find("nosferatu", 1, true) or name:find("nosuferatu", 1, true) then
        return tonumber(durations.nosferatu) or fallback
    elseif name:find("noli", 1, true) then
        return tonumber(durations.noli) or fallback
    elseif name:find("1x1x1", 1, true) then
        return tonumber(durations.oneXoneXone) or fallback
    elseif name:find("johndoe", 1, true) then
        return tonumber(durations.johnDoe) or fallback
    elseif name:find("azure", 1, true) then
        return tonumber(durations.azure) or fallback
    end
    return fallback
end
