-- Auto Punch and Hitbox Drag can both request character-facing control.
-- A shared owner map ensures one feature cannot restore AutoRotate while another
-- feature is still using the lock.
S.aimAutoRotateLockOwners = {}
S.aimAutoRotateLockHumanoid = nil
S.aimAutoRotateOriginalValue = nil
S.__helpers.setAimAutoRotateLock = function(owner, enabled, humanoid)
    if owner == nil then return end
    local owners = S.aimAutoRotateLockOwners

    if enabled then
        if owners[owner] then
            local existingHumanoid = owners[owner]
            if existingHumanoid and existingHumanoid.Parent then
                pcall(function() existingHumanoid.AutoRotate = false end)
            end
            return
        end
        if next(owners) == nil then
            S.aimAutoRotateLockHumanoid = humanoid
            S.aimAutoRotateOriginalValue = humanoid and humanoid.AutoRotate
        end
        local lockTarget = humanoid or S.aimAutoRotateLockHumanoid
        owners[owner] = lockTarget
        if lockTarget and lockTarget.Parent then
            pcall(function() lockTarget.AutoRotate = false end)
        end
        return
    end

    owners[owner] = nil
    if next(owners) == nil then
        local originalHumanoid = S.aimAutoRotateLockHumanoid
        local originalValue = S.aimAutoRotateOriginalValue
        if originalHumanoid and originalHumanoid.Parent and originalValue ~= nil then
            pcall(function() originalHumanoid.AutoRotate = originalValue end)
        end
        S.aimAutoRotateLockHumanoid = nil
        S.aimAutoRotateOriginalValue = nil
    else
        for _, lockedHumanoid in pairs(owners) do
            if lockedHumanoid and lockedHumanoid.Parent then
                pcall(function() lockedHumanoid.AutoRotate = false end)
            end
        end
    end
end

