-- KEY INPUT SYSTEM
--
--   LMB         -> MouseButton1
--   RMB         -> MouseButton2
--   LeftShift   -> Enum.KeyCode.LeftShift
--   RightShift  -> Enum.KeyCode.RightShift
--   Space       -> Enum.KeyCode.Space
--   E           -> Enum.KeyCode.E
--   R           -> Enum.KeyCode.R
-- ================================================================

S.__helpers.normalizeKeyName = function(keyName)
    if keyName == nil then
        return nil
    end

    local value = tostring(keyName)

    value = value:gsub("^%s+", "")
    value = value:gsub("%s+$", "")

    if value == "" then
        return nil
    end

    local upper = value:upper()

    if upper == "LMB"
        or upper == "MOUSE1"
        or upper == "LEFTMOUSE"
        or upper == "LEFTCLICK"
        or upper == "MOUSEBUTTON1" then

        return "LMB"
    end

    if upper == "RMB"
        or upper == "MOUSE2"
        or upper == "RIGHTMOUSE"
        or upper == "RIGHTCLICK"
        or upper == "MOUSEBUTTON2" then

        return "RMB"
    end

    return value
end

S.__helpers.getKeyCodeFromName = function(keyName)
    local normalized =
        S.__helpers.normalizeKeyName(keyName)

    if not normalized then
        return nil
    end

    if normalized == "LMB"
        or normalized == "RMB" then

        return nil
    end

    local keyCode

    pcall(function()
        keyCode =
            Enum.KeyCode[normalized]
    end)

    if keyCode then
        return keyCode
    end

    local lowerName =
        normalized:lower()

    for _, enumItem in ipairs(
        Enum.KeyCode:GetEnumItems()
    ) do
        if enumItem.Name:lower() ==
            lowerName then

            return enumItem
        end
    end

    return nil
end

-- ================================================================
-- KEY INPUT DISPLAY NAME
-- UIに表示するための名前
-- ================================================================

S.__helpers.getKeyDisplayName = function(keyName)
    local normalized =
        S.__helpers.normalizeKeyName(keyName)

    if not normalized then
        return "NONE"
    end

    if normalized == "LMB" then
        return "LMB"
    end

    if normalized == "RMB" then
        return "RMB"
    end

    local keyCode =
        S.__helpers.getKeyCodeFromName(normalized)

    if keyCode then
        return keyCode.Name
    end

    return normalized
end

S.__helpers.inputMatchesConfiguredKey = function(input, keyName)
    local normalized = S.__helpers.normalizeKeyName(keyName)
    if not normalized or not input then
        return false
    end

    if normalized == "LMB" then
        return input.UserInputType == Enum.UserInputType.MouseButton1
    end

    if normalized == "RMB" then
        return input.UserInputType == Enum.UserInputType.MouseButton2
    end

    if input.UserInputType ~= Enum.UserInputType.Keyboard then
        return false
    end

    local keyCode = S.__helpers.getKeyCodeFromName(normalized)
    return keyCode ~= nil and input.KeyCode == keyCode
end

