S.__helpers.getMyRoot = function()
    local character = S.lp.Character

    return character
        and character:FindFirstChild(
            "HumanoidRootPart"
        )
end


-- ================================================================
-- EXTENDED FOV
-- Applies to PlayerData when available and falls back to CurrentCamera.
-- The original values are restored when the feature is turned OFF.
-- ================================================================
S.extendedFOV = 80
S.extendedFOVMin = 10
S.extendedFOVMax = 120
S.extendedFOVStep = 5
S.isExtendedFOVEnabled = false
S.extendedFOVOriginalSetting = nil
S.extendedFOVOriginalSettingValue = nil
S.extendedFOVOriginalCamera = nil
S.extendedFOVOriginalCameraValue = nil

S.getExtendedFOVSetting = function()
    local playerData = S.lp and S.lp:FindFirstChild("PlayerData")
    if not playerData then return nil end
    local setting = playerData:FindFirstChild("FieldOfView", true)
        or playerData:FindFirstChild("FOV", true)
    if setting and setting:IsA("NumberValue") then return setting end
    return nil
end

S.setExtendedFOV = function(value)
    local numericValue = tonumber(value) or S.extendedFOV
    numericValue = S.extendedFOVMin + math.floor(
        ((numericValue - S.extendedFOVMin) / S.extendedFOVStep) + 0.5
    ) * S.extendedFOVStep
    S.extendedFOV = numericValue
    if S.isExtendedFOVEnabled then
        local fovSetting = S.getExtendedFOVSetting()
        if fovSetting then pcall(function() fovSetting.Value = numericValue end) end
        local camera = workspace.CurrentCamera
        if camera then pcall(function() camera.FieldOfView = numericValue end) end
    end
    return numericValue
end

S.setExtendedFOVEnabled = function(enabled)
    enabled = enabled == true
    if enabled == S.isExtendedFOVEnabled then return end
    if enabled then
        S.extendedFOVOriginalSetting = S.getExtendedFOVSetting()
        S.extendedFOVOriginalSettingValue = nil
        if S.extendedFOVOriginalSetting then
            pcall(function() S.extendedFOVOriginalSettingValue = S.extendedFOVOriginalSetting.Value end)
        end
        S.extendedFOVOriginalCamera = workspace.CurrentCamera
        S.extendedFOVOriginalCameraValue = nil
        if S.extendedFOVOriginalCamera then
            pcall(function() S.extendedFOVOriginalCameraValue = S.extendedFOVOriginalCamera.FieldOfView end)
        end
        S.isExtendedFOVEnabled = true
        S.setExtendedFOV(S.extendedFOV)
    else
        S.isExtendedFOVEnabled = false
        if S.extendedFOVOriginalSetting and S.extendedFOVOriginalSetting.Parent
            and S.extendedFOVOriginalSettingValue ~= nil then
            pcall(function() S.extendedFOVOriginalSetting.Value = S.extendedFOVOriginalSettingValue end)
        end
        if S.extendedFOVOriginalCamera and S.extendedFOVOriginalCameraValue ~= nil then
            pcall(function() S.extendedFOVOriginalCamera.FieldOfView = S.extendedFOVOriginalCameraValue end)
        end
        S.extendedFOVOriginalSetting = nil
        S.extendedFOVOriginalSettingValue = nil
        S.extendedFOVOriginalCamera = nil
        S.extendedFOVOriginalCameraValue = nil
    end
end

-- ================================================================
-- STRETCH (ported from the companion script)
-- Smoothly scales the camera's vertical axis while enabled.
-- ================================================================
S.isStretchEnabled = false
S.stretchAmount = 0
S.stretchSmoothed = 0
S.stretchRenderStepName = "E1LU4HUB_Stretch"

S.setStretchAmount = function(value)
    local number = tonumber(value)
    if not number then number = S.stretchAmount end
    S.stretchAmount = math.clamp(number, 0, 180)
    return S.stretchAmount
end

S.setStretchEnabled = function(enabled)
    enabled = enabled == true
    if S.isStretchEnabled == enabled then return end
    S.isStretchEnabled = enabled

    if enabled then
        S.stretchSmoothed = 0
        pcall(function()
            S.RunService:UnbindFromRenderStep(S.stretchRenderStepName)
            S.RunService:BindToRenderStep(
                S.stretchRenderStepName,
                Enum.RenderPriority.Last.Value + 1,
                function(deltaTime)
                    if not S.isStretchEnabled then return end
                    local camera = workspace.CurrentCamera
                    if not camera then return end

                    local dt = tonumber(deltaTime) or (1 / 60)
                    local alpha = math.clamp(dt * 10, 0, 1)
                    S.stretchSmoothed = S.stretchSmoothed
                        + ((S.stretchAmount - S.stretchSmoothed) * alpha)
                    if math.abs(S.stretchSmoothed) > 0.001 then
                        local verticalScale = 1 - (S.stretchSmoothed / 200)
                        camera.CFrame = camera.CFrame * CFrame.new(
                            0, 0, 0,
                            1, 0, 0,
                            0, verticalScale, 0,
                            0, 0, 1
                        )
                    end
                end
            )
        end)
    else
        pcall(function()
            S.RunService:UnbindFromRenderStep(S.stretchRenderStepName)
        end)
        S.stretchSmoothed = 0
    end
end

-- ================================================================
-- ForsakenPlus resolves ability remotes from Modules/Network/Network and
-- prefers firing the real ability button when firesignal is available.
S.__helpers.getMainUI = function()
    local playerGui = S.lp:FindFirstChildOfClass("PlayerGui")
    return playerGui and playerGui:FindFirstChild("MainUI")
end

-- ================================================================
S.__helpers.fireAbility = function(abilityName)
    local function resolveAbilityRemote()
        local modules = S.ReplicatedStorage:FindFirstChild("Modules")
        local networkFolder = modules and modules:FindFirstChild("Network", true)
        local nestedNetwork = networkFolder and networkFolder:FindFirstChild("Network")
        local remote = nestedNetwork
            and (nestedNetwork:FindFirstChildOfClass("RemoteEvent")
                or nestedNetwork:FindFirstChild("RemoteEvent"))
        remote = remote or (networkFolder
            and (networkFolder:FindFirstChildOfClass("RemoteEvent")
                or networkFolder:FindFirstChild("RemoteEvent")))

        if not remote and modules then
            for _, descendant in ipairs(modules:GetDescendants()) do
                if descendant:IsA("RemoteEvent") then
                    remote = descendant
                    break
                end
            end
        end
        return remote
    end

    local function activateAbilityButton(name)
        local mainUI = S.__helpers.getMainUI()
        local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
        local button = abilityContainer and abilityContainer:FindFirstChild(name)
        if not button or not button:IsA("GuiButton") then
            return false
        end

        local fireSignal = firesignal
        if type(fireSignal) ~= "function" then
            pcall(function() fireSignal = fire_signal end)
        end
        if type(fireSignal) ~= "function" then
            pcall(function() fireSignal = getgenv().firesignal end)
        end
        if type(fireSignal) ~= "function" then
            pcall(function() fireSignal = getgenv().fire_signal end)
        end
        if type(fireSignal) ~= "function" then
            return false
        end

        local ok = pcall(fireSignal, button.MouseButton1Click)
        if ok then
            return true
        end
        ok = pcall(fireSignal, button.Activated)
        return ok
    end

    local function activateAbilityRemote(name)
        local remote = resolveAbilityRemote()
        if not remote then
            return false
        end

        local officialGame = game.GameId == 6331902150 or game.GameId == 7464167604
        if officialGame then
            local ok = pcall(function()
                remote:FireServer("UseActorAbility", {name})
            end)
            return ok
        end

        -- Match the source script: try both payload shapes in non-official variants.
        local stringOK = pcall(function()
            remote:FireServer("UseActorAbility", name)
        end)
        local tableOK = pcall(function()
            remote:FireServer("UseActorAbility", {name})
        end)
        return stringOK or tableOK
    end

    if abilityName == "Block" then
        -- Full source-style Block activation: try Modules.Network.Network.RemoteEvent
        -- with the encoded payload first, then fall back to the ability button / usual remote.
        local modules = S.ReplicatedStorage:FindFirstChild("Modules")
        local network = modules and modules:FindFirstChild("Network")
        local nestedNetwork = network and network:FindFirstChild("Network")
        local sourceRemote = nestedNetwork and (
            nestedNetwork:FindFirstChildOfClass("RemoteEvent")
            or nestedNetwork:FindFirstChild("RemoteEvent")
        )

        if sourceRemote and buffer and type(buffer.fromstring) == "function" then
            local ok = pcall(function()
                sourceRemote:FireServer(
                    "UseActorAbility",
                    {buffer.fromstring("\3\5\0\0\0Block")})
            end)
            if ok then
                return true
            end
        end

        local buttonOK = activateAbilityButton("Block")
        local remoteOK = activateAbilityRemote("Block")
        return buttonOK or remoteOK
    end

    -- Keep the original handling for every other ability unchanged in scope.
    local mainUI = S.__helpers.getMainUI()
    local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
    local button = abilityContainer and abilityContainer:FindFirstChild(abilityName)

    if button and type(firesignal) == "function"
        and button:IsA("GuiButton") then
        local ok = pcall(function()
            firesignal(button.MouseButton1Click)
        end)
        if ok then
            return true
        end
    end

    local networkFolder = S.ReplicatedStorage:FindFirstChild("Modules")
    local network = networkFolder
        and networkFolder:FindFirstChild("Network", true)
    local networkModule = network
        and (network:FindFirstChild("Network") or network)
    local remote = networkModule
        and networkModule:FindFirstChildOfClass("RemoteEvent")

    if remote then
        local ok = pcall(function()
            remote:FireServer("UseActorAbility", {abilityName})
        end)
        if ok then
            return true
        end

        ok = pcall(function()
            remote:FireServer("UseActorAbility", abilityName)
        end)
        if ok then
            return true
        end
    end

    return false
end

-- ================================================================
-- FORSAKENPLUS ANIMATION-TYPE RESOLUTION
-- Mirrors ForsakenPlus.GetAnimationType by reading the game's
-- Assets/*/Config modules. The old v11 ID table remains as a fallback.
-- ================================================================

S.forsakenAnimationTypeCache = {}
S.forsakenAnimationCacheBuilt = false

S.__helpers.buildForsakenAnimationTypeCache = function()
    if S.forsakenAnimationCacheBuilt then
        return
    end

    S.forsakenAnimationCacheBuilt = true

    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    if not assets then
        return
    end

    for _, groupName in ipairs({"Killers", "Survivors", "Skins"}) do
        local group = assets:FindFirstChild(groupName)
        if group then
            for _, configModule in ipairs(group:GetDescendants()) do
                if configModule:IsA("ModuleScript")
                    and configModule.Name == "Config"
                    and not (configModule.Parent and configModule.Parent:IsA("Model")) then

                    local ok, configData = pcall(require, configModule)
                    if ok and type(configData) == "table" then
                        local animationData = configData.Animations
                        if type(animationData) == "table" then
                            for animType, animId in pairs(animationData) do
                                local function cacheId(value)
                                    local id = tostring(value):match("%d+")
                                    if id and not S.forsakenAnimationTypeCache[id] then
                                        S.forsakenAnimationTypeCache[id] = tostring(animType):lower()
                                    end
                                end

                                if type(animId) == "table" then
                                    for _, nestedId in pairs(animId) do
                                        if type(nestedId) == "string"
                                            or type(nestedId) == "number" then
                                            cacheId(nestedId)
                                        end
                                    end
                                elseif type(animId) == "string"
                                    or type(animId) == "number" then
                                    cacheId(animId)
                                end
                            end
                        end
                    end
                end
            end
        end
    end
end

