S.__helpers.isIgnoredAutoBlockAbility = function(value)
    local normalized = tostring(value or ""):lower():gsub("[^%w]", "")
    if normalized == "" then
        return false
    end

    local ignored = S.FORSAKEN_IGNORED_AUTOBLOCK_ABILITIES
    if ignored[normalized] then
        return true
    end

    -- Configs may append a phase/action suffix (for example, "BeheadStart").
    for abilityName in pairs(ignored) do
        if normalized:find(abilityName, 1, true) then
            return true
        end
    end

    return false
end

