S.__helpers.isPlayingIgnoredAutoCloneAbility = function(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
    if not animator then return false end

    local ok, tracks = pcall(function()
        return animator:GetPlayingAnimationTracks()
    end)
    if not ok or type(tracks) ~= "table" then return false end

    for _, activeTrack in ipairs(tracks) do
        local animation = activeTrack and activeTrack.Animation
        local animationName = animation and tostring(animation.Name or "") or ""
        local trackName = activeTrack and tostring(activeTrack.Name or "") or ""
        local animationType
        if animation then
            animationType = S.__helpers.getForsakenAnimationType(
                tostring(animation.AnimationId or "")
            )
        end
        if S.__helpers.isIgnoredAutoCloneAbility(animationType)
            or S.__helpers.isIgnoredAutoCloneAbility(animationName)
            or S.__helpers.isIgnoredAutoCloneAbility(trackName) then
            return true
        end
    end
    return false
end

-- Sound/animation signals must ignore utility abilities so they are not
-- misclassified as attacks by Auto Block.
-- Sound detection has no action-name payload of its own. When an excluded
-- ability animation is currently playing, suppress its sound-triggered signal
-- for Auto Block sound-trigger filtering.
S.__helpers.isPlayingIgnoredAutoBlockAbility = function(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
    if not animator then
        return false
    end

    local ok, tracks = pcall(function()
        return animator:GetPlayingAnimationTracks()
    end)
    if not ok or type(tracks) ~= "table" then
        return false
    end

    for _, activeTrack in ipairs(tracks) do
        local animation = activeTrack and activeTrack.Animation
        local animationName = animation and tostring(animation.Name or "") or ""
        local trackName = activeTrack and tostring(activeTrack.Name or "") or ""
        local animationType
        if animation then
            animationType = S.__helpers.getForsakenAnimationType(
                tostring(animation.AnimationId or "")
            )
        end
        if S.__helpers.isIgnoredAutoBlockAbility(animationType)
            or S.__helpers.isIgnoredAutoBlockAbility(animationName)
            or S.__helpers.isIgnoredAutoBlockAbility(trackName) then
            return true
        end
    end

    return false
end

-- Build the source-style animation map asynchronously so the first attack
-- does not have to pay the full Config-module scan cost.
task.spawn(S.__helpers.buildForsakenAnimationTypeCache)

-- Hitbox Drag shares the same utility-ability exclusions as Auto Block.
S.FORSAKEN_IGNORED_AUTOBLOCK_HITBOXDRAG_ABILITIES = S.FORSAKEN_IGNORED_AUTOBLOCK_ABILITIES
S.__helpers.isIgnoredAutoBlockHitboxDragAbility = S.__helpers.isIgnoredAutoBlockAbility
S.__helpers.isPlayingIgnoredAutoBlockHitboxDragAbility = S.__helpers.isPlayingIgnoredAutoBlockAbility

S.FORSAKEN_BLOCKABLE_ATTACKS = {
    slash = true,
    enragedslash = true,
    stab = true,
    attack = true,
    punch = true,
    swing = true,
    golemslash = true,
}

S.__helpers.getForsakenBlockableAnimation = function(track)
    if not track or not track.Animation then
        return nil
    end

    local animationId = tostring(track.Animation.AnimationId or "")
    local animType = S.__helpers.getForsakenAnimationType(animationId)
    local id = animationId:match("%d+")

    -- Auto Block intentionally use the same attack
    -- classification: ForsakenPlus action-name detection first, then the
    -- existing known animation-ID fallback.
    local isBlockable = animType
        and S.FORSAKEN_BLOCKABLE_ATTACKS[tostring(animType):lower()]
        or (id and S.animationIds[id] == true)

    if not isBlockable then
        return nil
    end

    return animType or id
end

-- Source-compatible Auto Block detection catalog, kept separate from the
-- shared Forsaken animation cache so this replacement affects only the
-- Animation Detection / Sounds Detection recognition paths.
S.SOURCE_AUTOBLOCK_ATTACK_ORDER = {
    "slash", "enragedslash", "stab", "attack", "punch", "swing", "golemslash", "hit",
}
S.SOURCE_AUTOBLOCK_ATTACK_TYPES = {
    slash = true,
    enragedslash = true,
    stab = true,
    attack = true,
    punch = true,
    swing = true,
    golemslash = true,
    hit = true,
}
S.SourceAutoBlockDetectionCatalog = {
    animations = {},
    sounds = {},
    ready = false,
    building = false,
}

S.__helpers.buildSourceAutoBlockDetectionCatalog = function()
    local catalog = S.SourceAutoBlockDetectionCatalog
    if catalog.ready or catalog.building then
        return catalog.ready
    end

    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    if not assets then
        return false
    end

    catalog.building = true
    catalog.animations = {}
    catalog.sounds = {}
    local allAnimations = catalog.animations
    local allSounds = catalog.sounds

    for _, groupName in ipairs({"Killers", "Survivors", "Skins"}) do
        local group = assets:FindFirstChild(groupName)
        if group then
            for _, configModule in ipairs(group:GetDescendants()) do
                if configModule:IsA("ModuleScript")
                    and configModule.Name == "Config"
                    and not (configModule.Parent and configModule.Parent:IsA("Model")) then
                    local ok, configData = pcall(require, configModule)
                    if ok and type(configData) == "table" then
                        local animationData = configData.Animations
                        local displayName = configData.DisplayName
                        if type(animationData) == "table" and displayName ~= nil then
                            local soundData = {}
                            if type(configData.Sounds) == "table" then
                                for soundName, soundValue in pairs(configData.Sounds) do
                                    soundData[soundName] = soundValue
                                end
                            end
                            if type(configData.Voicelines) == "table" then
                                for soundName, soundValue in pairs(configData.Voicelines) do
                                    soundData[soundName] = soundValue
                                end
                            end

                            local chosenName = tostring(displayName)
                            if chosenName:find("Milestone", 1, true) then
                                local parent = configModule.Parent
                                local grandparent = parent and parent.Parent
                                local baseName = grandparent and grandparent.Name
                                    or (parent and parent.Name)
                                    or chosenName
                                chosenName = string.format(
                                    "%s %s",
                                    baseName,
                                    chosenName:gsub("Milestone ", "")
                                )
                            end

                            allAnimations[chosenName] = animationData
                            allSounds[chosenName] = soundData
                        end
                    end
                end
            end
        end
    end

    -- ForsakenPlus also supplements animation lookup with animation tables
    -- discovered through getgc in non-main-game variants.
    if game.GameId ~= 6331902150 and type(getgc) == "function" then
        local ok, gcObjects = pcall(getgc, true)
        if ok and type(gcObjects) == "table" then
            for index, value in pairs(gcObjects) do
                if type(value) == "table" and rawget(value, "Idle") and rawget(value, "Run") then
                    local count = 0
                    for _ in pairs(value) do
                        count += 1
                        if count > 3 then break end
                    end
                    if count > 3 then
                        allAnimations["GC_" .. tostring(index)] = value
                    end
                end
            end
        end
    end

    catalog.ready = true
    catalog.building = false
    return true
end

S.__helpers.ensureSourceAutoBlockDetectionCatalog = function()
    local catalog = S.SourceAutoBlockDetectionCatalog
    if not catalog.ready and not catalog.building then
        S.__helpers.buildSourceAutoBlockDetectionCatalog()
    end
    if not catalog.ready and catalog.building then
        local deadline = os.clock() + 2
        while catalog.building and not catalog.ready and os.clock() < deadline do
            task.wait(0.025)
        end
    end
    return catalog.ready
end

S.__helpers.getSourceAutoBlockAnimationType = function(animationId)
    local catalog = S.SourceAutoBlockDetectionCatalog
    S.__helpers.ensureSourceAutoBlockDetectionCatalog()

    local requestedId = tostring(animationId or "")
    if requestedId == "" then return nil end

    -- Mirrors ForsakenPlus.GetAnimationType: inspect each Config animation
    -- type and any nested variant IDs, returning the first matching type.
    for characterName, animationData in pairs(catalog.animations) do
        if type(animationData) == "table" then
            for animationType, animationValue in pairs(animationData) do
                if type(animationValue) == "table" then
                    for variantName, variantId in pairs(animationValue) do
                        if type(variantId) == "string"
                            and variantId:find(requestedId, 1, true) then
                            return tostring(animationType), characterName, variantName
                        end
                    end
                elseif type(animationValue) == "string"
                    and animationValue:find(requestedId, 1, true) then
                    return tostring(animationType), characterName
                end
            end
        end
    end
    return nil
end

S.__helpers.matchSourceAutoBlockSound = function(sound)
    if not sound or not sound:IsA("Sound") then
        return false
    end

    local catalog = S.SourceAutoBlockDetectionCatalog
    S.__helpers.ensureSourceAutoBlockDetectionCatalog()

    local rawId = tostring(sound.SoundId or "")
    local numericId = rawId:match("(%d+)") or rawId
    local isOfficialGame = game.GameId == 6331902150
        or game.GameId == 7464167604
        or game.GameId == 7919224306

    -- In non-official variants ForsakenPlus first accepts attack-like Sound names.
    if not isOfficialGame then
        local lowerName = tostring(sound.Name or ""):lower()
        for _, attackType in ipairs(S.SOURCE_AUTOBLOCK_ATTACK_ORDER) do
            if lowerName:find(attackType, 1, true) then
                return true, attackType
            end
        end
    end

    local sources = isOfficialGame
        and {catalog.sounds}
        or {catalog.sounds, catalog.animations}
    local lastType, lastCharacter, lastVariant

    for _, sourceCatalog in ipairs(sources) do
        for characterName, characterData in pairs(sourceCatalog) do
            if type(characterData) == "table" then
                for soundType, soundValue in pairs(characterData) do
                    if type(soundValue) == "table" then
                        for variantName, variantValue in pairs(soundValue) do
                            local matches = type(variantValue) == "string"
                                and (variantValue:find(rawId, 1, true) ~= nil
                                    or variantValue:match("(%d+)") == numericId)
                            if matches and type(variantName) == "string"
                                and S.SOURCE_AUTOBLOCK_ATTACK_TYPES[variantName:lower()] then
                                return true, tostring(soundType), characterName, variantName
                            elseif matches then
                                lastType, lastCharacter, lastVariant = soundType, characterName, variantName
                            end
                        end
                    else
                        local matches = type(soundValue) == "string"
                            and (soundValue:find(rawId, 1, true) ~= nil
                                or soundValue:match("(%d+)") == numericId)
                        if matches and type(soundType) == "string"
                            and S.SOURCE_AUTOBLOCK_ATTACK_TYPES[soundType:lower()] then
                            return true, tostring(soundType), characterName
                        elseif matches then
                            lastType, lastCharacter, lastVariant = soundType, characterName, nil
                        end
                    end
                end
            end
        end
    end

    return false, lastType, lastCharacter, lastVariant
end

-- Build the source catalog before the first combat signal when possible.
task.spawn(S.__helpers.buildSourceAutoBlockDetectionCatalog)


-- ================================================================
-- AUTO BLOCK
-- ================================================================

-- Facing Check detection and the source-style vision cone share the same angle.
-- The visual cone has its own independent range, matching the supplied source.
S.facingCheckAngleDegrees = 85
-- Keep the Facing Check cone range independent from Auto Block's detection radius.
S.facingCheckESPRange = 16
S.__helpers.getFacingCheckHalfAngle = function()
    local angle = tonumber(S.facingCheckAngleDegrees) or 85
    angle = math.clamp(angle, 1, 200)
    return math.rad(angle / 2)
end

S.isKillerFacingTarget = function(killerRoot, targetRoot, range)
    if not S.isFacingCheckEnabled then
        return true
    end
    if not killerRoot or not killerRoot.Parent or not targetRoot or not targetRoot.Parent then
        return false
    end

    range = math.max(0.1, tonumber(range) or tonumber(S.autoBlockDetectionRange) or 16)
    local look = killerRoot.CFrame.LookVector
    local forward = Vector3.new(look.X, 0, look.Z)
    if forward.Magnitude < 0.001 then
        return false
    end
    forward = forward.Unit

    local offset = targetRoot.Position - killerRoot.Position
    local horizontalOffset = Vector3.new(offset.X, 0, offset.Z)
    local distance = horizontalOffset.Magnitude
    if distance > range then
        return false
    end
    if distance < 0.05 then
        return true
    end

    local towardTarget = horizontalOffset / distance
    return forward:Dot(towardTarget) >= math.cos(S.__helpers.getFacingCheckHalfAngle())
end

-- Auto Block detection relies on attack signals, range, and optional facing checks;
-- it no longer spawns a temporary hitbox part or checks QueryHitbox overlap.
-- Keep the shake limited to actual Auto Block activation attempts, and modify only
-- the camera CFrame (never the character's facing or the mouse behavior).
S.__helpers.shakeAutoBlockCamera = function()
    if not S.isShakeCameraEnabled
        or not S.isAutoBlockEnabled
        or not S.__helpers.isLocalRole("Survivor")
        or not S.__helpers.isLocalGuest1337()
        or S.autoBlockCameraShakeActive then
        return false
    end

    -- Start the shake only when the game's existing Block cooldown check says
    -- Block is ready. This prevents shake attempts while Block is already cooling
    -- down. The shake is horizontal only and lasts 0.1 seconds with one full cycle.
    local readyCheck = S.__helpers.isV2AbilityReady
    if type(readyCheck) ~= "function" then
        return false
    end
    local readyOk, blockReady = pcall(readyCheck, "Block")
    if not readyOk or blockReady ~= true then
        return false
    end

    local camera = workspace.CurrentCamera
    if not camera then return false end

    local bindingName = S.AUTO_BLOCK_CAMERA_SHAKE_BINDING
    S.autoBlockCameraShakeActive = true
    local startedAt = os.clock()
    local duration = 0.1
    -- Strong, horizontal-only left-right shake: one full cycle in 0.1 seconds.
    -- Yaw changes only; pitch and roll are not modified.
    local shakeAmplitude = 8.0
    local shakeFrequency = 10.0

    local function stopShake()
        pcall(function()
            S.RunService:UnbindFromRenderStep(bindingName)
        end)
        S.autoBlockCameraShakeActive = false
    end

    pcall(function()
        S.RunService:UnbindFromRenderStep(bindingName)
    end)
    local ok = pcall(function()
        S.RunService:BindToRenderStep(
            bindingName,
            Enum.RenderPriority.Camera.Value + 1,
            function()
                if not S.isShakeCameraEnabled
                    or not S.isAutoBlockEnabled
                    or not S.__helpers.isLocalRole("Survivor")
                    or not S.__helpers.isLocalGuest1337() then
                    stopShake()
                    return
                end

                local currentCamera = workspace.CurrentCamera
                if not currentCamera then
                    stopShake()
                    return
                end

                local elapsed = os.clock() - startedAt
                if elapsed >= duration then
                    stopShake()
                    return
                end

                -- One complete left-right oscillation in the 0.1-second shake window.
                local yaw = math.sin(elapsed * math.pi * 2 * shakeFrequency) * shakeAmplitude

                -- Apply a local yaw after Roblox's normal camera update. This keeps
                -- the position, mouse, and character transform untouched.
                currentCamera.CFrame = currentCamera.CFrame * CFrame.Angles(0, math.rad(yaw), 0)
            end
        )
    end)
    if not ok then
        S.autoBlockCameraShakeActive = false
        return false
    end
    return true
end

-- Shared prediction geometry for the optional Use Hitbox Auto Block mode.
S.__helpers.getHitboxPredictionBox = function(attackerCharacter)
    if not attackerCharacter or not attackerCharacter.Parent
        or not attackerCharacter:IsA("Model") then
        return nil, nil
    end
    local root = attackerCharacter:FindFirstChild("HumanoidRootPart")
    if not root or not root:IsA("BasePart") then return nil, nil end

    local sourceHitbox = attackerCharacter:FindFirstChild("QueryHitbox")
    local sourceCFrame = sourceHitbox and sourceHitbox:IsA("BasePart")
        and sourceHitbox.CFrame or root.CFrame
    local velocity = root.AssemblyLinearVelocity
    local predictionTime = 0.16
    local predictedPosition = sourceCFrame.Position
        + Vector3.new(velocity.X, math.clamp(velocity.Y, -8, 8), velocity.Z) * predictionTime
    local hitboxDistance = math.clamp(tonumber(S.autoBlockHitboxDistance) or 3.5, 0, 10)
    local boxCFrame = CFrame.new(predictedPosition)
        * (sourceCFrame - sourceCFrame.Position) * CFrame.new(0, 0, -hitboxDistance)
    local baseSize = S.HITBOX_PREDICTION_BASE_SIZE or (Vector3.new(5.2, 6, 5.65) * 2.2)
    local multiplier = math.clamp(tonumber(S.autoBlockHitboxSizeMultiplier) or 1.0, 0.25, 3.0)
    return boxCFrame, baseSize * multiplier
end

-- True only when at least one local-character BasePart overlaps the predicted
-- oriented box. A root-point OBB check is retained as a safe query fallback.
S.__helpers.isLocalCharacterInsidePredictionHitbox = function(attackerCharacter)
    local localCharacter = S.lp and S.lp.Character
    if not localCharacter or not localCharacter.Parent then return false end
    local boxCFrame, boxSize = S.__helpers.getHitboxPredictionBox(attackerCharacter)
    if not boxCFrame or not boxSize then return false end

    local overlapParams = OverlapParams.new()
    overlapParams.FilterType = Enum.RaycastFilterType.Include
    overlapParams.FilterDescendantsInstances = {localCharacter}
    overlapParams.MaxParts = 0
    local ok, overlappingParts = pcall(function()
        return workspace:GetPartBoundsInBox(boxCFrame, boxSize, overlapParams)
    end)
    if ok and type(overlappingParts) == "table" and #overlappingParts > 0 then
        return true
    end

    local localRoot = localCharacter:FindFirstChild("HumanoidRootPart")
    if not localRoot or not localRoot:IsA("BasePart") then return false end
    local localPoint = boxCFrame:PointToObjectSpace(localRoot.Position)
    return math.abs(localPoint.X) <= boxSize.X * 0.5
        and math.abs(localPoint.Y) <= boxSize.Y * 0.5
        and math.abs(localPoint.Z) <= boxSize.Z * 0.5
end

-- Shared, side-effect-free gate for the final Auto Block action.
-- Use Hitbox replaces the normal distance and Facing Check gates entirely.
S.__helpers.canFireAutoBlockAbility = function(targetRoot)
    if not S.isAutoBlockEnabled
        or not S.__helpers.isLocalRole("Survivor")
        or not S.__helpers.isLocalGuest1337()
        or S.autoBlockCooldown
        or not targetRoot or not targetRoot.Parent
        or not targetRoot:IsA("BasePart") then
        return false
    end

    local character = S.lp and S.lp.Character
    local localRoot = character and character:FindFirstChild("HumanoidRootPart")
    if not localRoot or not localRoot.Parent then
        return false
    end

    if S.isAutoBlockUseHitboxEnabled then
        local attackerCharacter = targetRoot:FindFirstAncestorOfClass("Model")
        if not attackerCharacter
            or not S.__helpers.isLocalCharacterInsidePredictionHitbox(attackerCharacter) then
            return false
        end
    else
        -- Default mode keeps the original horizontal range and Facing Check rules.
        local offset = targetRoot.Position - localRoot.Position
        local distance = Vector3.new(offset.X, 0, offset.Z).Magnitude
        local range = math.max(0.1, tonumber(S.autoBlockDetectionRange) or 16)
        if distance > range then
            return false
        end
        if S.isFacingCheckEnabled
            and not S.isKillerFacingTarget(targetRoot, localRoot, range) then
            return false
        end
    end

    local readyCheck = S.__helpers.isV2AbilityReady
    if type(readyCheck) ~= "function" then
        return false
    end
    local readyOk, blockReady = pcall(readyCheck, "Block")
    if not readyOk or blockReady ~= true then
        return false
    end

    return true
end

S.__helpers.fireAutoBlockAbility = function(targetRoot)
    -- Do not queue a second Block while a delayed request is already waiting.
    if S.autoBlockPending or not S.__helpers.canFireAutoBlockAbility(targetRoot) then
        return false
    end

    local function performBlock()
        -- This short internal guard stops several detection signals in the same
        -- frame from sending duplicate Block attempts.
        S.autoBlockCooldown = true
        S.__helpers.shakeAutoBlockCamera()
        local fireOk, fired = pcall(S.__helpers.fireAbility, "Block")
        if not fireOk or fired ~= true then
            S.autoBlockCooldown = false
            return false
        end
        task.delay(0.12, function()
            S.autoBlockCooldown = false
        end)

        -- Anti Bait and Hitbox Drag share the successful Auto Block trigger.
        -- Local animations alone do not activate either feature.
        if S.isAntiBaitEnabled and type(S.__helpers.triggerAntiBait) == "function" then
            S.__helpers.triggerAntiBait("Auto Block Success")
        end
        if S.isHitboxDragEnabled and type(S.__helpers.scheduleHitboxDrag) == "function" then
            S.__helpers.scheduleHitboxDrag("Auto Block Success")
        end
        return true
    end

    local delaySeconds = math.clamp(tonumber(S.autoBlockDelay) or 0, 0, 5)
    if delaySeconds <= 0 then
        return performBlock()
    end

    -- Reserve a single pending request. Re-check role, range, facing, and the
    -- Block cooldown when the delay expires before actually sending the ability.
    S.autoBlockPendingToken = (tonumber(S.autoBlockPendingToken) or 0) + 1
    local pendingToken = S.autoBlockPendingToken
    S.autoBlockPending = true
    task.delay(delaySeconds, function()
        if S.autoBlockPendingToken ~= pendingToken then return end
        S.autoBlockPending = false
        if not S.__helpers.canFireAutoBlockAbility(targetRoot) then return end
        performBlock()
    end)
    return true
end

-- Compatibility wrapper; validation is centralized in fireAutoBlockAbility.
S.__helpers.instantBlock = function(targetRoot)
    return S.__helpers.fireAutoBlockAbility(targetRoot) == true
end

-- Auto Block no longer probes for QueryHitbox overlap. The mode detectors use
-- attack signals plus range/facing checks and then attempt Block directly.

-- E1LU4SAKEN Auto Block V2 processing, adapted to E1LHUB's shared attack classifier.

-- E1LU4SAKEN Auto Block V2 processing, adapted to E1LHUB's shared attack classifier.
S.__helpers.isV2AbilityReady = function(abilityName)
    local mainUI = S.__helpers.getMainUI()
    local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
    local button = abilityContainer and abilityContainer:FindFirstChild(abilityName)
    -- Read the game's cooldown UI only. Block fails closed if its state cannot
    -- be read; the existing fallback for other abilities is preserved.
    -- CooldownTime text and the Clipping fill are both checked because some UI
    -- versions show only the fill while an ability is cooling down.
    if not button then return false end

    local foundCooldownState = false
    local cooldown = button:FindFirstChild("CooldownTime", true)
    if cooldown and cooldown:IsA("TextLabel") then
        foundCooldownState = true
        local text = tostring(cooldown.Text or ""):gsub("%s+", "")
        if text ~= "" then
            local numericText = text:gsub("[^%d%.%-]", "")
            local remaining = tonumber(numericText)
            if remaining == nil or remaining > 0.01 then
                return false
            end
        end
    end

    local clipping = button:FindFirstChild("Clipping", true)
    if clipping and clipping:IsA("GuiObject") then
        foundCooldownState = true
        -- In this game's ability UI, a visible partial Clipping fill indicates
        -- that the ability has not recharged yet. A full fill is ready.
        if clipping.Visible and (tonumber(clipping.Size.Y.Scale) or 0) < 0.99 then
            return false
        end
    end

    if tostring(abilityName) == "Block" or tostring(abilityName) == "Slash" then
        -- Auto Slash also requires an observable cooldown state. If Slash's
        -- ability widget / cooldown indicator is missing, do not send requests.
        return foundCooldownState
    end
    -- Preserve prior readiness behavior for abilities other than Block.
    return true
end

-- READY (green) is shown only while Auto Block itself is enabled. This remains
-- a visual-only check: it does not fire Block or impose the Guest1337 role gate.
S.__helpers.canShowHitboxPredictionReady = function(targetRoot)
    if S.isAutoBlockEnabled ~= true then
        return false
    end
    if not targetRoot or not targetRoot.Parent
        or not targetRoot:IsA("BasePart") then
        return false
    end

    local character = S.lp and S.lp.Character
    local localRoot = character and character:FindFirstChild("HumanoidRootPart")
    if not localRoot or not localRoot.Parent then
        return false
    end

    local offset = targetRoot.Position - localRoot.Position
    local distance = Vector3.new(offset.X, 0, offset.Z).Magnitude
    local range = math.max(0.1, tonumber(S.autoBlockDetectionRange) or 16)
    if distance > range then
        return false
    end

    if S.isFacingCheckEnabled
        and not S.isKillerFacingTarget(targetRoot, localRoot, range) then
        return false
    end

    local readyCheck = S.__helpers.isV2AbilityReady
    if type(readyCheck) ~= "function" then
        return false
    end
    local readyOk, blockReady = pcall(readyCheck, "Block")
    return readyOk and blockReady == true
end

-- ================================================================
-- HITBOX PREDICTION ESP
-- Draw a short-lived, velocity-predicted attack box using the selected
-- Auto Block Detection source. ESP-only mode never activates Block.
-- ================================================================
-- Resolve normal and READY opacity independently. READY keeps its original
-- default transparency unless its dedicated controls are explicitly edited.
S.__helpers.getHitboxPredictionTransparency = function(isReadyGreen, isOutline)
    local value
    if isReadyGreen and isOutline then
        if S.hitboxPredictionReadyOutlineTransparencyControlInitialized
            and tonumber(S.HITBOX_PREDICTION_READY_OUTLINE_TRANSPARENCY) ~= nil then
            value = S.HITBOX_PREDICTION_READY_OUTLINE_TRANSPARENCY
        else
            -- Keep the READY outline at its independent 12% default;
            -- normal (white) outline transparency defaults to 80%.
            value = S.HITBOX_PREDICTION_READY_DEFAULT_OUTLINE_TRANSPARENCY
                or S.HITBOX_PREDICTION_DEFAULT_OUTLINE_TRANSPARENCY
        end
    elseif isReadyGreen and not isOutline then
        value = S.HITBOX_PREDICTION_READY_FILL_TRANSPARENCY
    elseif not isOutline then
        -- The normal (white) Show Hitbox fill uses HITBOX_TRANSPARENCY.
        -- Its initial value is 0.4; the fill control mirrors its edits back
        -- into this value so both names stay synchronized.
        value = tonumber(S.HITBOX_TRANSPARENCY)
        if value == nil then
            value = S.HITBOX_PREDICTION_FILL_TRANSPARENCY
        end
    else
        value = S.HITBOX_PREDICTION_OUTLINE_TRANSPARENCY
    end
    value = tonumber(value)
    if value == nil then
        value = isOutline
            and S.HITBOX_PREDICTION_DEFAULT_OUTLINE_TRANSPARENCY
            or S.HITBOX_PREDICTION_DEFAULT_FILL_TRANSPARENCY
    end
    -- Normal fill transparency is independent from Auto Block's separate
    -- Use Hitbox transparency setting. READY (green) retains its own controls.
    return math.clamp(value, 0, 1)
end

S.__helpers.applyHitboxPredictionTransparency = function(object, isReadyGreen)
    if not object or not object:IsA("BasePart") then return end

    local transparency
    if object.Name == "HitboxPredictionESP" then
        transparency = S.__helpers.getHitboxPredictionTransparency(isReadyGreen, false)
    elseif object.Name == "HitboxPredictionESP_Edge" then
        transparency = S.__helpers.getHitboxPredictionTransparency(isReadyGreen, true)
    else
        return
    end

    -- Normal outlines are visible immediately; their single edge set follows
    -- the Killer instead of being recreated as stationary snapshots.

    -- Normal Show Hitbox renders directly. READY keeps its existing proxy visuals.
    local overlayCreated = false
    if isReadyGreen then
        overlayCreated = S.__helpers.addNeonESPHitboxPartOverlay
            and S.__helpers.addNeonESPHitboxPartOverlay(object, transparency)
    elseif S.__helpers.removeNeonESPHitboxPartOverlay then
        S.__helpers.removeNeonESPHitboxPartOverlay(object)
    end
    pcall(function()
        object.Transparency = overlayCreated and 1 or transparency
        object.LocalTransparencyModifier = 0
    end)
    S.hitboxPredictionActiveParts = S.hitboxPredictionActiveParts
        or setmetatable({}, {__mode = "k"})
    S.hitboxPredictionActiveParts[object] = true
end

S.__helpers.updateHitboxPredictionESPTransparency = function()
    local activeParts = S.hitboxPredictionActiveParts
    if activeParts then
        for object in pairs(activeParts) do
            if object and object.Parent then
                S.__helpers.applyHitboxPredictionTransparency(
                    object,
                    object:GetAttribute("HitboxPredictionReady") == true
                )
            else
                activeParts[object] = nil
            end
        end
    end

    -- Also sweep the dedicated folder as a recovery path for any parts created
    -- by an earlier script revision or retained during a hot reload.
    local rootFolder = workspace:FindFirstChild(S.ROOT_FOLDER_NAME)
    local folder = rootFolder and rootFolder:FindFirstChild(S.HITBOX_PREDICTION_FOLDER_NAME)
    if folder then
        for _, object in ipairs(folder:GetDescendants()) do
            if object:IsA("BasePart")
                and (object.Name == "HitboxPredictionESP"
                    or object.Name == "HitboxPredictionESP_Edge") then
                S.__helpers.applyHitboxPredictionTransparency(
                    object,
                    object:GetAttribute("HitboxPredictionReady") == true
                )
            end
        end
    end
    if S.__helpers.refreshHitboxPreview then
        pcall(S.__helpers.refreshHitboxPreview)
    end
end

-- Re-apply existing Hitbox visuals after legacy proxy cleanup: normal Show Hitbox
-- returns to its source part, while READY rebuilds/reuses its preserved visuals.
S.__helpers.updateHitboxPredictionESPTransparency()

-- Resolve and apply the currently configured color from the READY attribute.
-- Keeping this separate from transparency makes color-picker edits immediately
-- visible on already-running prediction boxes as well as newly-created boxes.
S.__helpers.applyHitboxPredictionESPColor = function(object, isReadyGreen)
    if not object or not object:IsA("BasePart") then return end
    if object.Name ~= "HitboxPredictionESP"
        and object.Name ~= "HitboxPredictionESP_Edge" then
        return
    end

    local selectedColor
    if isReadyGreen then
        selectedColor = S.HITBOX_PREDICTION_READY_COLOR
        if typeof(selectedColor) ~= "Color3" then
            selectedColor = Color3.fromRGB(0, 255, 90)
        end
    else
        selectedColor = S.HITBOX_PREDICTION_ESP_COLOR
        if typeof(selectedColor) ~= "Color3" then
            selectedColor = Color3.fromRGB(255, 255, 255)
        end
    end

    pcall(function()
        object.Color = selectedColor
        -- Filled hitbox volumes use ForceField; only their edge parts stay Neon.
        object.Material = object.Name == "HitboxPredictionESP"
            and (S.HITBOX_PREDICTION_NORMAL_MATERIAL or Enum.Material.ForceField)
            or (S.HITBOX_PREDICTION_OUTLINE_MATERIAL or Enum.Material.Neon)
        object.Reflectance = 0
    end)
end

S.__helpers.updateHitboxPredictionESPColor = function()
    local activeParts = S.hitboxPredictionActiveParts
    if activeParts then
        for object in pairs(activeParts) do
            if object and object.Parent then
                S.__helpers.applyHitboxPredictionESPColor(
                    object,
                    object:GetAttribute("HitboxPredictionReady") == true
                )
            else
                activeParts[object] = nil
            end
        end
    end

    -- Recovery sweep for any live parts not present in the active reference set.
    local rootFolder = workspace:FindFirstChild(S.ROOT_FOLDER_NAME)
    local folder = rootFolder and rootFolder:FindFirstChild(S.HITBOX_PREDICTION_FOLDER_NAME)
    if folder then
        for _, object in ipairs(folder:GetDescendants()) do
            if object:IsA("BasePart") then
                S.__helpers.applyHitboxPredictionESPColor(
                    object,
                    object:GetAttribute("HitboxPredictionReady") == true
                )
            end
        end
    end
    if S.__helpers.refreshHitboxPreview then
        pcall(S.__helpers.refreshHitboxPreview)
    end
end

S.__helpers.showHitboxPredictionESP = function(character, animType, track)
    if not S.isHitboxPredictionESPEnabled or not character or not character.Parent
        or not S.isCharacterInRoleFolder(character, "Killers") then
        return false
    end

    local root = character:FindFirstChild("HumanoidRootPart")
    if not root or not root:IsA("BasePart") then return false end

    local readyLatched = false
    if type(S.__helpers.canShowHitboxPredictionReady) == "function" then
        local readyOk, readyNow = pcall(S.__helpers.canShowHitboxPredictionReady, root)
        readyLatched = readyOk and readyNow == true
    end

    -- READY keeps its original one-moving-visual-at-a-time behavior. Apply that
    -- guard ONLY to READY: a still-visible READY visual must never block normal
    -- fill snapshots. Normal fills accumulate in normalGroup while one outline
    -- remains attached to the Killer until the group's final expiry.
    S.hitboxPredictionActiveByCharacter = S.hitboxPredictionActiveByCharacter
        or setmetatable({}, {__mode = "k"})
    if readyLatched then
        local previousVisual = S.hitboxPredictionActiveByCharacter[character]
        if previousVisual then
            local previousIsAlive = false
            for _, oldObject in ipairs(previousVisual) do
                if oldObject and oldObject.Parent then
                    previousIsAlive = true
                    break
                end
            end
            if previousIsAlive then
                return false
            end
            S.hitboxPredictionActiveByCharacter[character] = nil
        end
    end

    local normalGroup
    if not readyLatched then
        S.hitboxPredictionNormalGroups = S.hitboxPredictionNormalGroups
            or setmetatable({}, {__mode = "k"})
        normalGroup = S.hitboxPredictionNormalGroups[character]
        if not normalGroup then
            normalGroup = {
                visuals = {},
                expiresAt = 0,
                running = false,
                outlineParts = {},
                outlineOffsets = {},
                outlineReady = false,
            }
            S.hitboxPredictionNormalGroups[character] = normalGroup
        end
    end

    local currentVisual = {}
    if readyLatched then
        S.hitboxPredictionActiveByCharacter[character] = currentVisual
    end

    -- Always apply the detailed Hitbox settings to the ESP, regardless of the
    -- Use Hitbox Auto Block toggle. Their defaults reproduce the original
    -- standalone ESP geometry; enabling Use Hitbox only changes Block gating.
    -- Place the prediction box IN FRONT of the Killer (local -Z).
    local _, configuredSize = S.__helpers.getHitboxPredictionBox(character)
    local boxSize = configuredSize or S.HITBOX_PREDICTION_BASE_SIZE or (Vector3.new(5.2, 6, 5.65) * 2.2)
    local boxOffset = CFrame.new(
        0, 0, -math.clamp(tonumber(S.autoBlockHitboxDistance) or 3.5, 0, 10)
    )
    local rootFolder = S.__helpers.getWorldRootFolder()
    local folder = rootFolder:FindFirstChild(S.HITBOX_PREDICTION_FOLDER_NAME)
    if not folder then
        folder = Instance.new("Folder")
        folder.Name = S.HITBOX_PREDICTION_FOLDER_NAME
        folder.Parent = rootFolder
    end

    local part = Instance.new("Part")
    part.Name = "HitboxPredictionESP"
    part.Size = boxSize
    part.Anchored = true
    part.CanCollide = false
    part.CanTouch = false
    part.CanQuery = false
    part.CastShadow = false
    part.Material = S.HITBOX_PREDICTION_NORMAL_MATERIAL or Enum.Material.ForceField
    part.Reflectance = 0
    part.Color = readyLatched
        and (S.HITBOX_PREDICTION_READY_COLOR or Color3.fromRGB(0, 255, 90))
        or (S.HITBOX_PREDICTION_ESP_COLOR or Color3.fromRGB(255, 255, 255))
    part:SetAttribute("HitboxPredictionReady", readyLatched)
    part.Parent = folder
    table.insert(currentVisual, part)
    -- Apply after parenting so the first rendered frame starts in the correct
    -- state; a READY box never flashes white before the first update.
    S.__helpers.applyHitboxPredictionTransparency(part, readyLatched)

    local edgeThickness = 0.035
    local edgeParts = {}
    local edgeOffsets = {}
    local function addPredictionEdge(size, offset)
        local edge = Instance.new("Part")
        edge.Name = "HitboxPredictionESP_Edge"
        edge.Size = size
        edge.Anchored = true
        edge.CanCollide = false
        edge.CanTouch = false
        edge.CanQuery = false
        edge.CastShadow = false
        edge.Material = S.HITBOX_PREDICTION_OUTLINE_MATERIAL or Enum.Material.Neon
        edge.Reflectance = 0
        edge.Color = readyLatched
            and (S.HITBOX_PREDICTION_READY_COLOR or Color3.fromRGB(0, 255, 90))
            or (S.HITBOX_PREDICTION_ESP_COLOR or Color3.fromRGB(255, 255, 255))
        edge:SetAttribute("HitboxPredictionReady", readyLatched)
        edge.Parent = folder
        if readyLatched then
            table.insert(currentVisual, edge)
        end
        S.__helpers.applyHitboxPredictionTransparency(edge, readyLatched)
        table.insert(edgeParts, edge)
        table.insert(edgeOffsets, offset)
    end

    -- READY retains its own edge set. Normal mode keeps one outline set for the
    -- Killer and moves it every frame; later detections do not clone more edges.
    local shouldCreateEdges = readyLatched
    if not readyLatched then
        local hasActiveOutline = false
        for _, existingEdge in ipairs(normalGroup.outlineParts or {}) do
            if existingEdge and existingEdge.Parent then
                hasActiveOutline = true
                break
            end
        end
        shouldCreateEdges = not hasActiveOutline
    end

    if shouldCreateEdges then
        for _, ySign in ipairs({-1, 1}) do
            for _, zSign in ipairs({-1, 1}) do
                addPredictionEdge(
                    Vector3.new(boxSize.X, edgeThickness, edgeThickness),
                    CFrame.new(0, ySign * boxSize.Y / 2, zSign * boxSize.Z / 2)
                )
            end
        end
        for _, xSign in ipairs({-1, 1}) do
            for _, zSign in ipairs({-1, 1}) do
                addPredictionEdge(
                    Vector3.new(edgeThickness, boxSize.Y, edgeThickness),
                    CFrame.new(xSign * boxSize.X / 2, 0, zSign * boxSize.Z / 2)
                )
            end
        end
        for _, xSign in ipairs({-1, 1}) do
            for _, ySign in ipairs({-1, 1}) do
                addPredictionEdge(
                    Vector3.new(edgeThickness, edgeThickness, boxSize.Z),
                    CFrame.new(xSign * boxSize.X / 2, ySign * boxSize.Y / 2, 0)
                )
            end
        end
        if not readyLatched then
            normalGroup.outlineParts = edgeParts
            normalGroup.outlineOffsets = edgeOffsets
        end
    end

    local function getPredictedCFrame()
        local sourceHitbox = character:FindFirstChild("QueryHitbox")
        local sourceCFrame = sourceHitbox and sourceHitbox:IsA("BasePart")
            and sourceHitbox.CFrame or root.CFrame
        local velocity = root.AssemblyLinearVelocity
        local predictionTime = 0.16
        local predictedPosition = sourceCFrame.Position
            + Vector3.new(velocity.X, math.clamp(velocity.Y, -8, 8), velocity.Z) * predictionTime
        return CFrame.new(predictedPosition)
            * (sourceCFrame - sourceCFrame.Position) * boxOffset
    end

    -- Normal fill uses the standalone hitbox's continuous-part display:
    -- create a fresh frozen fill part each Heartbeat and let each part remain
    -- for one normal display window. READY stays a single 0.3s snapshot.
    local duration = readyLatched and 0.3 or 0.38
    local normalFillTemplate = nil
    if not readyLatched then
        S.Debris = S.Debris or game:GetService("Debris")
        -- Only the first detection in a group needs the reusable template.
        -- Every detection still gets its own visible fill part and lifetime.
        if not normalGroup.running then
            normalFillTemplate = part:Clone()
            normalFillTemplate.Parent = nil
        end
        S.Debris:AddItem(part, duration)
    end
    local visualCreatedAt = os.clock()
    local initialCFrame = getPredictedCFrame()
    part.CFrame = initialCFrame
    for edgeIndex, edge in ipairs(edgeParts) do
        edge.CFrame = initialCFrame * edgeOffsets[edgeIndex]
    end

    if not readyLatched then
        -- Normal fill snapshots keep their existing short display window. The
        -- outline is separate: one edge set follows the Killer for this group.
        table.insert(normalGroup.visuals, {
            part = part,
            root = root,
            readyLatched = false,
        })
        normalGroup.expiresAt = visualCreatedAt + duration

        if not normalGroup.running then
            normalGroup.running = true
            task.spawn(function()
                -- Keep emitting frozen normal-fill parts every Heartbeat,
                -- matching the continuous display of the reference hitbox.
                -- This is separate from the existing outline/update loop so
                -- its refresh timing remains unchanged.
                local fillHeartbeatConnection = S.RunService.Heartbeat:Connect(function()
                    if not S.isHitboxPredictionESPEnabled or not character.Parent
                        or not root.Parent or os.clock() >= normalGroup.expiresAt then
                        return
                    end
                    if not folder or not folder.Parent or not normalFillTemplate then
                        return
                    end

                    local snapshotPart = normalFillTemplate:Clone()
                    snapshotPart:SetAttribute("HitboxPredictionReady", false)
                    snapshotPart.CFrame = getPredictedCFrame()
                    snapshotPart.Parent = folder
                    S.__helpers.applyHitboxPredictionESPColor(snapshotPart, false)
                    S.__helpers.applyHitboxPredictionTransparency(snapshotPart, false)
                    table.insert(normalGroup.visuals, {
                        part = snapshotPart,
                        root = root,
                        readyLatched = false,
                    })
                    S.Debris:AddItem(snapshotPart, duration)
                end)

                while S.isHitboxPredictionESPEnabled and character.Parent and root.Parent do
                    local now = os.clock()
                    local remaining = normalGroup.expiresAt - now
                    if remaining <= 0 then break end
                    local predictedCFrame = getPredictedCFrame()

                    -- Keep the normal outline attached to the Killer's current
                    -- predicted attack volume instead of generating edge snapshots.
                    for edgeIndex, edge in ipairs(normalGroup.outlineParts or {}) do
                        local edgeOffset = normalGroup.outlineOffsets
                            and normalGroup.outlineOffsets[edgeIndex]
                        if edge and edge.Parent and edgeOffset then
                            pcall(function() edge.CFrame = predictedCFrame * edgeOffset end)
                        end
                    end

                    -- Fill snapshots remain independent; READY color latching is
                    -- preserved for each normal fill visual as before.
                    for _, visual in ipairs(normalGroup.visuals) do
                        local visualPart = visual.part
                        local visualRoot = visual.root
                        if visualPart and visualPart.Parent and visualRoot and visualRoot.Parent then
                            if not visual.readyLatched
                                and type(S.__helpers.canShowHitboxPredictionReady) == "function" then
                                local readyOk, readyNow = pcall(
                                    S.__helpers.canShowHitboxPredictionReady,
                                    visualRoot
                                )
                                if readyOk and readyNow == true then
                                    visual.readyLatched = true
                                end
                            end

                            local canBlock = visual.readyLatched
                            if canBlock then
                                normalGroup.outlineReady = true
                            end
                            visualPart:SetAttribute("HitboxPredictionReady", canBlock)
                            S.__helpers.applyHitboxPredictionESPColor(visualPart, canBlock)
                            S.__helpers.applyHitboxPredictionTransparency(visualPart, canBlock)
                        end
                    end

                    -- A normal outline changes to READY green only after the
                    -- existing readiness check latches true; it is never delayed.
                    local outlineReady = normalGroup.outlineReady == true
                    for _, edge in ipairs(normalGroup.outlineParts or {}) do
                        if edge and edge.Parent then
                            edge:SetAttribute("HitboxPredictionReady", outlineReady)
                            S.__helpers.applyHitboxPredictionESPColor(edge, outlineReady)
                            S.__helpers.applyHitboxPredictionTransparency(edge, outlineReady)
                        end
                    end

                    task.wait(math.min(0.025, remaining))
                end

                -- The normal fill snapshots outlive the emission window by
                -- their own Debris lifetime, just like the reference hitbox.
                -- Only the attached outline is cleared at the group's expiry.
                if fillHeartbeatConnection then
                    pcall(function() fillHeartbeatConnection:Disconnect() end)
                end
                pcall(function()
                    if normalFillTemplate then normalFillTemplate:Destroy() end
                end)
                table.clear(normalGroup.visuals)
                for _, edge in ipairs(normalGroup.outlineParts or {}) do
                    if S.hitboxPredictionActiveParts and edge then
                        S.hitboxPredictionActiveParts[edge] = nil
                    end
                    pcall(function()
                        if edge then edge:Destroy() end
                    end)
                end
                table.clear(normalGroup.outlineParts)
                table.clear(normalGroup.outlineOffsets)
                normalGroup.running = false
                if S.hitboxPredictionNormalGroups
                    and S.hitboxPredictionNormalGroups[character] == normalGroup then
                    S.hitboxPredictionNormalGroups[character] = nil
                end
            end)
        end
        return true
    end

    -- READY (green) is pinned to the predicted CFrame captured at creation.
    -- Do not refresh the part or its edges from the Killer's live position.
    task.spawn(function()
        local started = os.clock()
        while part.Parent and S.isHitboxPredictionESPEnabled
            and character.Parent and os.clock() - started < duration do
            local canBlock = readyLatched
            part:SetAttribute("HitboxPredictionReady", canBlock)
            S.__helpers.applyHitboxPredictionESPColor(part, canBlock)
            S.__helpers.applyHitboxPredictionTransparency(part, canBlock)
            for _, edge in ipairs(edgeParts) do
                if edge.Parent then
                    edge:SetAttribute("HitboxPredictionReady", canBlock)
                    S.__helpers.applyHitboxPredictionESPColor(edge, canBlock)
                    S.__helpers.applyHitboxPredictionTransparency(edge, canBlock)
                end
            end
            task.wait(0.025)
        end
        if S.hitboxPredictionActiveParts then
            S.hitboxPredictionActiveParts[part] = nil
            for _, edge in ipairs(edgeParts) do
                S.hitboxPredictionActiveParts[edge] = nil
            end
        end
        if S.hitboxPredictionActiveByCharacter
            and S.hitboxPredictionActiveByCharacter[character] == currentVisual then
            S.hitboxPredictionActiveByCharacter[character] = nil
        end
        pcall(function()
            part:Destroy()
            for _, edge in ipairs(edgeParts) do edge:Destroy() end
        end)
    end)
    return true
end

S.__helpers.triggerHitboxPredictionESP = function(character, animType, track)
    if not S.isHitboxPredictionESPEnabled or not character or not character.Parent
        or not S.isCharacterInRoleFolder(character, "Killers") then
        return false
    end

    local now = os.clock()
    local isAnimationDetection = S.autoBlockDetectionMode == "Animation Detection"
    local cooldownStates = S.hitboxPredictionCooldownState
        or setmetatable({}, {__mode = "k"})
    S.hitboxPredictionCooldownState = cooldownStates
    local cooldownState = cooldownStates[character]
    if not cooldownState then
        cooldownState = {lastGeneratedAt = -math.huge}
        cooldownStates[character] = cooldownState
    end

    -- Apply the same 0.4s per-Killer cooldown in every detection mode.
    -- This throttles detection callbacks only; each successful generation keeps
    -- its original overlapping snapshots and complete display lifetime.
    if now - (tonumber(cooldownState.lastGeneratedAt) or -math.huge)
        < (tonumber(S.HITBOX_PREDICTION_DETECTION_COOLDOWN) or 0.4) then
        return false
    end

    local lastDetected = S.hitboxPredictionLastDetected[character]
    -- Deduplicate repeated callbacks for the same animation track, rather than
    -- suppressing a distinct attack animation that starts shortly afterward.
    if track ~= nil then
        if type(lastDetected) == "table"
            and lastDetected.track == track
            and now - (tonumber(lastDetected.time) or 0) < 0.14 then
            return false
        end
        S.hitboxPredictionLastDetected[character] = {time = now, track = track}
    else
        if type(lastDetected) == "number" and now - lastDetected < 0.14 then
            return false
        end
        S.hitboxPredictionLastDetected[character] = now
    end

    local resolvedType = animType
    local resolvedTrack = track
    if not resolvedTrack then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator then
            local ok, playingTracks = pcall(function()
                return animator:GetPlayingAnimationTracks()
            end)
            if ok and type(playingTracks) == "table" then
                for _, candidateTrack in ipairs(playingTracks) do
                    local candidateType = S.__helpers.getForsakenBlockableAnimation(candidateTrack)
                    if candidateType
                        and not S.__helpers.isIgnoredAutoBlockAbility(candidateType)
                        and not S.__helpers.isIgnoredAutoBlockAbility(candidateTrack.Name) then
                        resolvedTrack = candidateTrack
                        resolvedType = candidateType
                        break
                    end
                end
            end
        end
    end
    if (resolvedType == nil or tostring(resolvedType) == "") and resolvedTrack then
        resolvedType = S.__helpers.getForsakenBlockableAnimation(resolvedTrack)
    end
    if resolvedType == nil or tostring(resolvedType) == "" then
        resolvedType = "attack"
    end
    -- Animation Detection already filters the exact AnimationPlayed track
    -- before calling this helper. Do not let an unrelated, still-playing
    -- utility animation on the same Killer suppress that valid attack ESP.
    local ignoredTrackIsPlaying = not (isAnimationDetection and track ~= nil)
        and S.__helpers.isPlayingIgnoredAutoBlockAbility(character)
    if S.__helpers.isIgnoredAutoBlockAbility(resolvedType)
        or (resolvedTrack and S.__helpers.isIgnoredAutoBlockAbility(resolvedTrack.Name))
        or ignoredTrackIsPlaying then
        return false
    end
    local shown = S.__helpers.showHitboxPredictionESP(character, resolvedType, resolvedTrack)
    if shown and cooldownState then
        cooldownState.lastGeneratedAt = now
    end
    return shown
end

-- ================================================================
-- SOURCE-STYLE AUTO BLOCK (FULL REPLACEMENT)
-- Triggers from Killer AbilityLastUsed / AbilitiesUsed attributes, then checks
-- the short-lived hitbox in front of the Killer, matching the supplied source.
-- ================================================================
S.sourceAutoBlockState = {
    killer = nil,
    abilityLastUsed = nil,
    abilitiesUsed = nil,
    suppressNextBlock = false,
}

-- Auto Block signal handling without spawning/checking a temporary hitbox part.
-- Ability/sound signals activate Block directly after the source has identified
-- the relevant attacker; this avoids the old GetPartsInPart hitbox-presence scan.
S.__helpers.sourceAutoBlockHitbox = function(killer)
    if not S.__helpers.isLocalRole("Survivor")
        or not S.__helpers.isLocalGuest1337()
        or not S.isAutoBlockEnabled or not killer or not killer.Parent then
        return false
    end

    local root = killer:FindFirstChild("HumanoidRootPart")
        or killer:FindFirstChild("RootPart")
    if not root or not root:IsA("BasePart") then
        return false
    end

    -- With Use Hitbox enabled, non-Animation Detection modes retain the
    -- detected Killer for its configured grace period. Poll the predicted
    -- volume during that window so entering it shortly after the signal can
    -- still trigger Block. Animation Detection keeps its separate live loop.
    if S.isAutoBlockUseHitboxEnabled
        and S.autoBlockDetectionMode ~= "Animation Detection" then
        local graceWindows = S.autoBlockUseHitboxGraceWindows
            or setmetatable({}, {__mode = "k"})
        S.autoBlockUseHitboxGraceWindows = graceWindows

        local graceState = graceWindows[killer]
        if not graceState then
            graceState = {deadline = 0, running = false}
            graceWindows[killer] = graceState
        end
        graceState.deadline = os.clock()
            + S.__helpers.getAutoBlockUseHitboxGraceSeconds(killer)

        if graceState.running then
            return true
        end
        graceState.running = true

        task.spawn(function()
            while graceWindows[killer] == graceState
                and os.clock() <= graceState.deadline
                and killer.Parent
                and S.isAutoBlockEnabled
                and S.isAutoBlockUseHitboxEnabled
                and S.autoBlockDetectionMode ~= "Animation Detection"
                and S.__helpers.isLocalRole("Survivor")
                and S.__helpers.isLocalGuest1337() do
                local currentRoot = killer:FindFirstChild("HumanoidRootPart")
                    or killer:FindFirstChild("RootPart")
                local humanoid = killer:FindFirstChildOfClass("Humanoid")
                if currentRoot and currentRoot:IsA("BasePart")
                    and (not humanoid or humanoid.Health > 0) then
                    -- instantBlock re-checks the predicted-box overlap, Block
                    -- readiness, role, and cooldown in one centralized gate.
                    if S.__helpers.instantBlock(currentRoot) then
                        break
                    end
                end
                task.wait(0.025)
            end

            graceState.running = false
            if graceWindows[killer] == graceState then
                graceWindows[killer] = nil
            end
        end)
        return true
    end

    return S.__helpers.instantBlock(root)
end

S.__helpers.processSourceStyleAutoBlock = function()
    local state = S.sourceAutoBlockState
    local localCanAutoBlock = S.isAutoBlockEnabled == true
        and S.__helpers.isLocalRole("Survivor")
        and S.__helpers.isLocalGuest1337()
    if not S.isHitboxPredictionESPEnabled and not localCanAutoBlock then
        state.killer = nil
        state.abilityLastUsed = nil
        state.abilitiesUsed = nil
        state.suppressNextBlock = false
        return
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local killersFolder = playersFolder
        and (playersFolder:FindFirstChild("Killers") or playersFolder:FindFirstChild("killers"))
    local killer
    if killersFolder then
        for _, candidate in ipairs(killersFolder:GetChildren()) do
            if candidate:IsA("Model") then
                killer = candidate
                break
            end
        end
    end

    if not killer then
        state.killer = nil
        state.abilityLastUsed = nil
        state.abilitiesUsed = nil
        state.suppressNextBlock = false
        return
    end

    local abilityLastUsed = tonumber(killer:GetAttribute("AbilityLastUsed")) or 0
    local abilitiesUsed = tonumber(killer:GetAttribute("AbilitiesUsed")) or 0

    if state.killer ~= killer or state.abilityLastUsed == nil or state.abilitiesUsed == nil then
        state.killer = killer
        state.abilityLastUsed = abilityLastUsed
        state.abilitiesUsed = abilitiesUsed
        state.suppressNextBlock = false
        return
    end

    local newAbilityLastUsed = abilityLastUsed > state.abilityLastUsed
    if abilitiesUsed > state.abilitiesUsed then
        state.suppressNextBlock = true
    end

    if newAbilityLastUsed then
        if state.suppressNextBlock then
            state.suppressNextBlock = false
        else
            task.spawn(function()
                if not killer.Parent then return end
                if S.isHitboxPredictionESPEnabled then
                    S.__helpers.triggerHitboxPredictionESP(killer)
                end
                if S.isAutoBlockEnabled then
                    S.__helpers.sourceAutoBlockHitbox(killer)
                end
            end)
        end
    end

    state.abilityLastUsed = abilityLastUsed
    state.abilitiesUsed = abilitiesUsed
end

S.__helpers.connect(S.RunService.Heartbeat, function()
    if S.autoBlockDetectionMode == "Animation + Sounds detection" then
        S.__helpers.processSourceStyleAutoBlock()
    else
        local state = S.sourceAutoBlockState
        state.killer = nil
        state.abilityLastUsed = nil
        state.abilitiesUsed = nil
        state.suppressNextBlock = false
    end
end)

S.__helpers.runPlusBlockAutoBlockDetection = function(attacker, animType, track)
    local mode = S.autoBlockDetectionMode
    local localCanAutoBlock = S.isAutoBlockEnabled == true
        and S.__helpers.isLocalRole("Survivor")
        and S.__helpers.isLocalGuest1337()
    if (not S.isHitboxPredictionESPEnabled and not localCanAutoBlock)
        or mode ~= "Animation Detection"
        or not attacker or not attacker.Parent then
        return false
    end

    local localCharacter = S.lp and S.lp.Character
    if not localCharacter or not S.isCharacterInRoleFolder(attacker, "Killers") then
        return false
    end

    local attackType = tostring(animType or ""):lower():gsub("[%s_%-]", "")
    local trackStarted = os.clock()
    local maxWindow = 0.31
    if attackType:find("massinfection", 1, true) then maxWindow = 1.4 end
    if attackType:find("entanglement", 1, true) then maxWindow = 0.4 end
    if track and tonumber(track.Length) and track.Length > 0 then
        maxWindow = math.min(math.max(track.Length, maxWindow), 2.5)
    end

    local function attackerStillAttacking()
        if not attacker.Parent then return false end
        if track == nil then return os.clock() - trackStarted <= 0.35 end
        local ok, playing = pcall(function() return track.IsPlaying end)
        return ok and playing and os.clock() - trackStarted <= maxWindow
    end

    while attackerStillAttacking()
        and (S.isHitboxPredictionESPEnabled
            or (S.isAutoBlockEnabled and S.__helpers.isLocalRole("Survivor")
                and S.__helpers.isLocalGuest1337())) do
        local currentMode = S.autoBlockDetectionMode
        local canAutoBlockNow = S.isAutoBlockEnabled == true
            and S.__helpers.isLocalRole("Survivor")
            and S.__helpers.isLocalGuest1337()
        if (not S.isHitboxPredictionESPEnabled and not canAutoBlockNow)
            or currentMode ~= "Animation Detection"
            or localCharacter ~= (S.lp and S.lp.Character) then
            return false
        end

        local localRoot = localCharacter:FindFirstChild("HumanoidRootPart")
        local attackerRoot = attacker:FindFirstChild("HumanoidRootPart")
        local attackerHumanoid = attacker:FindFirstChildOfClass("Humanoid")
        if not localRoot or not attackerRoot or not attackerHumanoid or attackerHumanoid.Health <= 0 then
            return false
        end

        local offset = attackerRoot.Position - localRoot.Position
        local distance = Vector3.new(offset.X, 0, offset.Z).Magnitude
        local range = math.max(0.1, tonumber(S.autoBlockDetectionRange) or 16)
        local facingAllowed = not S.isFacingCheckEnabled
            or distance <= (tonumber(S.AUTO_BLOCK_CLOSE_RANGE) or 4)
            or S.isKillerFacingTarget(attackerRoot, localRoot, range)

        -- Animation Detection already generated its one Hitbox Prediction ESP
        -- set from the AnimationPlayed event. Do not regenerate it from this
        -- per-frame attack-window loop; this loop now only evaluates Auto Block.

        -- Use Hitbox bypasses legacy range / Facing Check limits and waits until
        -- the local character overlaps the exact predicted ESP volume instead.
        local blockCondition = false
        if localCanAutoBlock then
            if S.isAutoBlockUseHitboxEnabled then
                blockCondition = S.__helpers.isLocalCharacterInsidePredictionHitbox(attacker)
            else
                blockCondition = distance <= range and facingAllowed
            end
        end
        if blockCondition then
            if S.isAutoBlockEnabled and S.__helpers.isLocalRole("Survivor")
                and S.__helpers.isLocalGuest1337() then
                S.__helpers.fireAutoBlockAbility(attackerRoot)
            end
            return true
        end
        task.wait()
    end
    return false
end

-- Cache E1LU4SAKEN-style swing sounds as one of the combined detection signals.
task.spawn(function()
    local function addSoundId(value)
        if type(value) == "string" or type(value) == "number" then
            local id = tostring(value):match("%d+")
            if id then S.AutoBlockV2.soundIds[id] = true end
        elseif type(value) == "table" then
            addSoundId(value.SoundId or value.ID or value.Id)
        end
    end
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local searchRoots = {}
    if assets then
        local killers = assets:FindFirstChild("Killers")
        local skins = assets:FindFirstChild("Skins")
        local killerSkins = skins and skins:FindFirstChild("Killers")
        if killers then table.insert(searchRoots, killers) end
        if killerSkins then table.insert(searchRoots, killerSkins) end
    end
    local desiredNames = {Swing = true, SlashGround = true, SlashExtended = true, Slash = true}
    for _, root in ipairs(searchRoots) do
        for _, moduleScript in ipairs(root:GetDescendants()) do
            if moduleScript:IsA("ModuleScript") and moduleScript.Name == "Config" then
                local ok, config = pcall(require, moduleScript)
                if ok and type(config) == "table" and type(config.Sounds) == "table" then
                    for soundName in pairs(desiredNames) do
                        addSoundId(config.Sounds[soundName])
                    end
                end
            end
        end
    end
end)

local function bindAutoBlockV2Sound(sound)
    if not sound or not sound:IsA("Sound") then return end
    local function handleSoundEvent()
        local v2 = S.AutoBlockV2
        local id = tostring(sound.SoundId or ""):match("%d+")
        local isAutoCloneSound = id ~= nil and v2.soundIds[id] == true
        local shouldRunSourceSoundDetection =
            (S.isAutoBlockEnabled or S.isHitboxPredictionESPEnabled)
            and S.autoBlockDetectionMode == "Sounds Detection"
        if not isAutoCloneSound and not shouldRunSourceSoundDetection then return end
        if v2.soundDebounce[sound] and os.clock() - v2.soundDebounce[sound] < 0.18 then
            return
        end

        -- The source only evaluates sounds attached to a Killer. Resolve that
        -- ancestor first so the full Config catalog is not scanned for map/UI audio.
        local ancestor = sound.Parent
        local attacker
        while ancestor and ancestor ~= workspace do
            if ancestor:IsA("Model") and S.isCharacterInRoleFolder(ancestor, "Killers") then
                attacker = ancestor
                break
            end
            ancestor = ancestor.Parent
        end
        if not attacker then return end

        local sourceSoundMatched, sourceSoundType = false, nil
        if shouldRunSourceSoundDetection then
            sourceSoundMatched, sourceSoundType = S.__helpers.matchSourceAutoBlockSound(sound)
        end
        if not isAutoCloneSound and not sourceSoundMatched then return end

        -- Preserve the original Auto Clone detector: it still uses only its
        -- existing cached swing-sound IDs and is independent of Auto Block.
        if isAutoCloneSound and v2.autoClone
            and type(S.__helpers.tryAutoClone) == "function" then
            local localCharacter = S.lp and S.lp.Character
            local localName = localCharacter and tostring(localCharacter.Name or ""):lower():gsub("%s+", "") or ""
            local lastCloneSound = v2.cloneSoundDebounce[sound]
            if localName == "007n7" and S.__helpers.isLocalRole("Survivor")
                and not v2.cloneSoundPending[sound]
                and (not lastCloneSound or os.clock() - lastCloneSound >= 1.0) then
                v2.cloneSoundPending[sound] = true
                task.spawn(function()
                    local attemptOK, cloned = pcall(S.__helpers.tryAutoClone, attacker, "sound")
                    v2.cloneSoundPending[sound] = nil
                    if attemptOK and cloned == true then
                        v2.cloneSoundDebounce[sound] = os.clock()
                    end
                end)
            end
        end

        -- Sounds Detection is now based solely on the source's SoundMatchingType:
        -- Config.Sounds + Config.Voicelines, plus Config.Animations in non-official
        -- variants and the source's non-official Sound.Name fallback.
        if shouldRunSourceSoundDetection and sourceSoundMatched then
            if S.__helpers.isPlayingIgnoredAutoBlockAbility(attacker) then
                return
            end
            local localCanAutoBlock = S.isAutoBlockEnabled == true
                and S.__helpers.isLocalRole("Survivor")
                and S.__helpers.isLocalGuest1337()
            if not S.isHitboxPredictionESPEnabled and not localCanAutoBlock then
                return
            end
            v2.soundDebounce[sound] = os.clock()
            if S.isHitboxPredictionESPEnabled then
                S.__helpers.triggerHitboxPredictionESP(attacker, sourceSoundType)
            end
            if localCanAutoBlock then
                task.spawn(S.__helpers.sourceAutoBlockHitbox, attacker)
            end
        end
    end

    -- Keep the current event coverage: newly-added, already-playing and
    -- subsequently-played Sound instances all pass through the new matcher.
    S.__helpers.connect(sound.Played, handleSoundEvent)
    S.__helpers.connect(sound:GetPropertyChangedSignal("IsPlaying"), function()
        if sound.IsPlaying then handleSoundEvent() end
    end)
    if sound.IsPlaying then handleSoundEvent() end
end
for _, object in ipairs(workspace:GetDescendants()) do
    if object:IsA("Sound") then bindAutoBlockV2Sound(object) end
end
S.__helpers.connect(workspace.DescendantAdded, function(object)
    if object:IsA("Sound") then bindAutoBlockV2Sound(object) end
end)

-- File 2 Hitbox Drag is registered to the local block-animation and physical
-- Hitbox detectors in the Auto Block section below.

S.__helpers.bindCombatAnimator = function(character)
    if not character or character == S.lp.Character then
        return
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
    if not animator then
        return
    end

    if animator:GetAttribute("ELSGUI_CombatBound") then
        return
    end
    animator:SetAttribute("ELSGUI_CombatBound", true)

    S.__helpers.connect(animator.AnimationPlayed, function(track)
        if not (S.AutoBlockV2 and S.AutoBlockV2.enabled)
            and not S.isHitboxPredictionESPEnabled then
            return
        end

        -- Some Killer rigs inside workspace.Players.Killers are not returned by
        -- Players:GetPlayerFromCharacter. Keep the normal player gate for the
        -- other combat features, but allow Animation Detection ESP to process a
        -- valid Killer-folder model directly.
        local animationPlayersFolder = workspace:FindFirstChild("Players")
        local animationKillersFolder = animationPlayersFolder
            and animationPlayersFolder:FindFirstChild("Killers")
        local isHitboxPredictionKiller = S.isHitboxPredictionESPEnabled
            and S.autoBlockDetectionMode == "Animation Detection"
            and animationKillersFolder ~= nil
            and character:IsDescendantOf(animationKillersFolder)
        if not S.Players:GetPlayerFromCharacter(character) and not isHitboxPredictionKiller then
            return
        end

        local animType = S.__helpers.getForsakenBlockableAnimation(track)
        local isRecognizedAttack = animType ~= nil
        local sourceAnimType = track and track.Animation
            and S.__helpers.getForsakenAnimationType(tostring(track.Animation.AnimationId or ""))
        local animationName = track and track.Animation and tostring(track.Animation.Name or "") or ""
        local nameKey = animationName:lower()
        local nameLooksLikeAttack = nameKey:find("attack", 1, true) ~= nil
            or nameKey:find("slash", 1, true) ~= nil
            or nameKey:find("stab", 1, true) ~= nil
            or nameKey:find("swing", 1, true) ~= nil
            or nameKey:find("strike", 1, true) ~= nil
            or nameKey:find("punch", 1, true) ~= nil
            or nameKey:find("knife", 1, true) ~= nil
            or nameKey:find("ability", 1, true) ~= nil
            or nameKey == "m1"
            or nameKey:find("basicattack", 1, true) ~= nil

        local function isV2AttackName(value)
            local normalized = tostring(value or ""):lower():gsub("[%s_%-]", "")
            return normalized:find("slash", 1, true) ~= nil
                or normalized:find("attack", 1, true) ~= nil
                or normalized:find("stab", 1, true) ~= nil
                or normalized:find("swing", 1, true) ~= nil
                or normalized:find("strike", 1, true) ~= nil
                or normalized:find("punch", 1, true) ~= nil
                or normalized:find("knife", 1, true) ~= nil
                or normalized:find("ability", 1, true) ~= nil
                or normalized:find("entanglement", 1, true) ~= nil
                or normalized:find("massinfection", 1, true) ~= nil
                or normalized:find("voidrush", 1, true) ~= nil
                or normalized:find("corruptnature", 1, true) ~= nil
                or normalized:find("walkspeedoverride", 1, true) ~= nil
                or normalized:find("uppercut", 1, true) ~= nil
                or normalized == "m1"
                or normalized:find("basicattack", 1, true) ~= nil
        end

        -- Prioritize a Config action type only when it is attack-like. If the Config
        -- classifies a known legacy attack ID incorrectly or has no entry, keep that
        -- attack available to V2 via the legacy recognition or the animation name.
        local attackTypeForV2
        if sourceAnimType and isV2AttackName(sourceAnimType) then
            attackTypeForV2 = sourceAnimType
        elseif isRecognizedAttack then
            if type(animType) == "string" and not animType:match("^%d+$") and isV2AttackName(animType) then
                attackTypeForV2 = animType
            else
                attackTypeForV2 = "attack"
            end
        elseif nameLooksLikeAttack then
            attackTypeForV2 = animationName ~= "" and animationName or "attack"
        end
        local isV2AttackType = isV2AttackName(attackTypeForV2)
        local isIgnoredAutoBlockAbility =
            S.__helpers.isIgnoredAutoBlockAbility(sourceAnimType)
            or S.__helpers.isIgnoredAutoBlockAbility(animType)
            or S.__helpers.isIgnoredAutoBlockAbility(animationName)
            or S.__helpers.isIgnoredAutoBlockAbility(track and track.Name)

        -- Auto Block Animation Detection now uses the exact Config-driven
        -- GetAnimationType classification from fetched (1).lua. Other combat
        -- features continue using their existing animation classifiers above.
        local sourceAutoBlockAnimType
        local sourceAutoBlockAnimMatched = false
        if S.autoBlockDetectionMode == "Animation Detection" and track and track.Animation then
            sourceAutoBlockAnimType = S.__helpers.getSourceAutoBlockAnimationType(
                tostring(track.Animation.AnimationId or "")
            )
            sourceAutoBlockAnimMatched = sourceAutoBlockAnimType ~= nil
                and S.SOURCE_AUTOBLOCK_ATTACK_TYPES[tostring(sourceAutoBlockAnimType):lower()] == true
        end

        local localCanAutoBlock = S.isAutoBlockEnabled == true
            and S.__helpers.isLocalRole("Survivor")
            and S.__helpers.isLocalGuest1337()
        local isIgnoredSourceAutoBlockAnimation =
            S.__helpers.isIgnoredAutoBlockAbility(sourceAutoBlockAnimType)
            or S.__helpers.isIgnoredAutoBlockAbility(animationName)
            or S.__helpers.isIgnoredAutoBlockAbility(track and track.Name)

        -- A source-recognized blockable animation creates the existing ESP
        -- preview directly from AnimationPlayed, without changing its renderer.
        if S.isHitboxPredictionESPEnabled
            and S.autoBlockDetectionMode == "Animation Detection"
            and sourceAutoBlockAnimMatched
            and not isIgnoredSourceAutoBlockAnimation
            and S.isCharacterInRoleFolder(character, "Killers") then
            S.__helpers.triggerHitboxPredictionESP(character, sourceAutoBlockAnimType, track)
        end

        -- Keep the current range / Facing Check and Block ability path intact;
        -- only the signal classifier above has been replaced.
        if (localCanAutoBlock or S.isHitboxPredictionESPEnabled)
            and S.autoBlockDetectionMode == "Animation Detection"
            and sourceAutoBlockAnimMatched
            and not isIgnoredSourceAutoBlockAnimation
            and S.isCharacterInRoleFolder(character, "Killers") then
            task.spawn(
                S.__helpers.runPlusBlockAutoBlockDetection,
                character,
                sourceAutoBlockAnimType,
                track
            )
        end

        -- Auto Clone is handled by the File 2 sound/hitbox detector below,
        -- rather than by this animation-classifier callback.

        if not animType then
            return
        end

    end)
end

-- Track both sides of the character -> Humanoid -> Animator chain. Some Killer
-- models are inserted into workspace.Players.Killers before their Humanoid is
-- parented; watching only Humanoid.ChildAdded in that case permanently misses the
-- Animator and therefore every Animation Detection Hitbox Prediction ESP event.
S.combatCharacterHumanoidWatchers = setmetatable({}, {__mode = "k"})
S.combatHumanoidAnimatorWatchers = setmetatable({}, {__mode = "k"})
S.__helpers.bindCombatCharacter = function(character)
    if not character or character == S.lp.Character then
        return
    end

    local function bindHumanoid(humanoid)
        if not humanoid or not humanoid:IsA("Humanoid") then
            return
        end

        S.__helpers.bindCombatAnimator(character)
        if S.combatHumanoidAnimatorWatchers[humanoid] then
            return
        end
        S.combatHumanoidAnimatorWatchers[humanoid] = true
        S.__helpers.connect(humanoid.ChildAdded, function(child)
            if child:IsA("Animator") then
                S.__helpers.bindCombatAnimator(character)
            end
        end)
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if humanoid then
        bindHumanoid(humanoid)
    end

    -- Also catch the Humanoid itself being added after the Killer model. The
    -- weak-key guard prevents duplicate listeners if this character is rebound.
    if not S.combatCharacterHumanoidWatchers[character] then
        S.combatCharacterHumanoidWatchers[character] = true
        S.__helpers.connect(character.ChildAdded, function(child)
            if child:IsA("Humanoid") then
                bindHumanoid(child)
            end
        end)
    end
end


-- Bind current killer/other-player characters to the fast animation path.
do
    local killerFolder = workspace:FindFirstChild("Players")
        and workspace.Players:FindFirstChild("Killers")

    if killerFolder then
        for _, character in ipairs(killerFolder:GetChildren()) do
            S.__helpers.bindCombatCharacter(character)
        end

        S.__helpers.connect(killerFolder.ChildAdded, function(character)
            task.defer(function()
                S.__helpers.bindCombatCharacter(character)
            end)
        end)
    end

    for _, player in ipairs(S.Players:GetPlayers()) do
        if player ~= S.lp then
            if player.Character then
                S.__helpers.bindCombatCharacter(player.Character)
            end

            S.__helpers.connect(player.CharacterAdded, function(character)
                S.__helpers.bindCombatCharacter(character)
            end)
        end
    end

    S.__helpers.connect(S.Players.PlayerAdded, function(player)
        S.__helpers.connect(player.CharacterAdded, function(character)
            S.__helpers.bindCombatCharacter(character)
        end)
    end)
end

-- AUTO PUNCH
-- Uses File 2's successful Guest1337 parry event and Overheal gate for activation.
-- Retains File 1's custom Punch Aimbot aim processing and controls.
-- ================================================================

S.__helpers.getClosestForsakenKiller = function(maxDistance, useFOV)
    local playersFolder = workspace:FindFirstChild("Players")
    local killerFolder = playersFolder and playersFolder:FindFirstChild("Killers")
    local localRoot = S.__helpers.getMyRoot()
    if not killerFolder or not localRoot then
        return nil, nil
    end

    local camera = useFOV and workspace.CurrentCamera or nil
    if useFOV and not camera then
        return nil, nil
    end
    local viewportSize = camera and camera.ViewportSize or nil
    local screenCenter = viewportSize
        and Vector2.new(viewportSize.X * 0.5, viewportSize.Y * 0.5)
        or nil
    local fovRadius = tonumber(S.PUNCH_AIMBOT_FOV_RADIUS) or 120

    local selectedKiller
    local distance = maxDistance or 55

    for _, killer in ipairs(killerFolder:GetDescendants()) do
        if killer:IsA("Model") then
            local player = S.Players:GetPlayerFromCharacter(killer)
            local root = killer:FindFirstChild("HumanoidRootPart")
            if player and root then
                local killerHumanoid = killer:FindFirstChildOfClass("Humanoid")
                if killerHumanoid and killerHumanoid.Health > 0 then
                    local currentDistance = (root.Position - localRoot.Position).Magnitude
                    local insideFOV = true
                    if useFOV then
                        local projectedPosition, onScreen = camera:WorldToViewportPoint(root.Position)
                        if not onScreen or projectedPosition.Z <= 0 then
                            insideFOV = false
                        else
                            local screenOffset = Vector2.new(
                                projectedPosition.X,
                                projectedPosition.Y
                            ) - screenCenter
                            insideFOV = screenOffset.Magnitude <= fovRadius
                        end
                    end

                    if insideFOV and currentDistance < distance then
                        distance = currentDistance
                        selectedKiller = killer
                    end
                end
            end
        end
    end

    return selectedKiller, distance
end

S.autoPunchTriggerBusy = false
S.autoPunchRemoteEvent = nil
S.autoPunchRemoteConnection = nil
S.AutoPunchIndicatorBoundUIs = setmetatable({}, {__mode = "k"})
S.AutoPunchIndicatorBoundContainers = setmetatable({}, {__mode = "k"})

S.__helpers.getAutoPunchRemoteEvent = function()
    local modules = S.ReplicatedStorage:FindFirstChild("Modules")
    local networkFolder = modules and modules:FindFirstChild("Network")
    local network = networkFolder and (networkFolder:FindFirstChild("Network") or networkFolder)
    local remote = network and (network:FindFirstChildOfClass("RemoteEvent") or network:FindFirstChild("RemoteEvent"))
    if remote and remote:IsA("RemoteEvent") then return remote end

    local deepNetwork = modules and modules:FindFirstChild("Network", true)
    local nestedNetwork = deepNetwork and deepNetwork:FindFirstChild("Network")
    remote = nestedNetwork and (nestedNetwork:FindFirstChildOfClass("RemoteEvent") or nestedNetwork:FindFirstChild("RemoteEvent"))
    if remote and remote:IsA("RemoteEvent") then return remote end
    return nil
end

S.__helpers.updateAutoPunchIndicator = function()
    local mainUI = S.__helpers.getMainUI()
    local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
    local punchButton = abilityContainer and abilityContainer:FindFirstChild("Punch")
    local autoImage = punchButton and punchButton:FindFirstChild("AutoImage")
    if autoImage then
        -- Never show the AUTO badge above the Punch button.
        autoImage.Visible = false
    end
end

S.__helpers.setupAutoPunchIndicator = function(abilityContainer)
    if not abilityContainer or abilityContainer.Name ~= "AbilityContainer" then return end
    if S.AutoPunchIndicatorBoundContainers[abilityContainer] then
        S.__helpers.updateAutoPunchIndicator()
        return
    end
    S.AutoPunchIndicatorBoundContainers[abilityContainer] = true

    local function setupPunchButton(punchButton)
        if not punchButton or punchButton.Name ~= "Punch" then return end
        local autoImage = punchButton:FindFirstChild("AutoImage")
        if autoImage then
            autoImage.Visible = false
        end
        S.__helpers.updateAutoPunchIndicator()
    end

    setupPunchButton(abilityContainer:FindFirstChild("Punch"))
    S.__helpers.connect(abilityContainer.ChildAdded, function(child)
        if child.Name == "Punch" then
            task.defer(setupPunchButton, child)
        end
    end)
end

S.__helpers.bindAutoPunchUI = function()
    local mainUI = S.__helpers.getMainUI()
    if not mainUI or S.AutoPunchIndicatorBoundUIs[mainUI] then
        S.__helpers.updateAutoPunchIndicator()
        return
    end
    S.AutoPunchIndicatorBoundUIs[mainUI] = true
    S.__helpers.setupAutoPunchIndicator(mainUI:FindFirstChild("AbilityContainer"))
    S.__helpers.connect(mainUI.ChildAdded, function(child)
        if child.Name == "AbilityContainer" then
            S.__helpers.setupAutoPunchIndicator(child)
        end
    end)
end

S.__helpers.runAutoPunchOnParry = function(character, remote)
    if S.autoPunchTriggerBusy then return end
    S.autoPunchTriggerBusy = true

    task.spawn(function()
        local shiftLockCharacter = character
        local originalShiftLockMovement
        local shiftLockMovementApplied = false
        local function restoreAutoPunchShiftLockMovement()
            if not shiftLockMovementApplied then return end
            if shiftLockCharacter and shiftLockCharacter.Parent then
                pcall(function()
                    shiftLockCharacter:SetAttribute(
                        "DisableShiftLockMovement",
                        originalShiftLockMovement
                    )
                end)
            end
            shiftLockMovementApplied = false
        end

        local ok, err = pcall(function()
            task.wait(0.1)
            if not S.isAutoPunchEnabled
                or character ~= S.lp.Character
                or not S.__helpers.isLocalRole("Survivor")
                or not S.__helpers.isLocalGuest1337()
                or not character or not character.Parent then
                return
            end

            local humanoid = character:FindFirstChildOfClass("Humanoid")
            local overheal = humanoid and humanoid:GetAttribute("Overheal")
            local speedMultipliers = character:FindFirstChild("SpeedMultipliers")
            local fovMultipliers = character:FindFirstChild("FOVMultipliers")
            if not humanoid or humanoid.Health <= 0
                or type(overheal) ~= "number" or overheal < 10
                or not speedMultipliers
                or not S.__helpers.getClosestForsakenKiller(55) then
                return
            end

            -- File 2 holds shift-lock movement during Punch activation; keep that
            -- behavior while restoring the pre-existing attribute value afterward.
            originalShiftLockMovement = character:GetAttribute("DisableShiftLockMovement")
            local shiftLockSetOK = pcall(function()
                character:SetAttribute("DisableShiftLockMovement", true)
            end)
            shiftLockMovementApplied = shiftLockSetOK

            local function fireAutoPunchAbility(useActorAbility)
                local mainUI = S.__helpers.getMainUI()
                local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
                local punchButton = abilityContainer and abilityContainer:FindFirstChild("Punch")

                local fireSignal = firesignal
                if type(fireSignal) ~= "function" then
                    pcall(function() fireSignal = fire_signal end)
                end
                if type(fireSignal) ~= "function" and type(getgenv) == "function" then
                    pcall(function() fireSignal = getgenv().firesignal or getgenv().fire_signal end)
                end

                if type(fireSignal) == "function" and punchButton then
                    pcall(function() fireSignal(punchButton.MouseButton1Down) end)
                    local clickOK = pcall(function() fireSignal(punchButton.MouseButton1Click) end)
                    if clickOK then return true end
                end

                useActorAbility = useActorAbility or S.__helpers.getAutoPunchRemoteEvent()
                if not useActorAbility then return false end
                local officialGame = game.GameId == 6331902150
                    or game.GameId == 7464167604 or game.GameId == 7919224306
                local tableOK = pcall(function()
                    useActorAbility:FireServer("UseActorAbility", {[1] = "Punch"})
                end)
                if officialGame then return tableOK end
                local stringOK = pcall(function()
                    useActorAbility:FireServer("UseActorAbility", "Punch")
                end)
                return tableOK or stringOK
            end

            local aimEnabled = S.isPunchAimbotEnabled == true
                and S.__helpers.isLocalGuest1337()
            local selectedVelocity
            local localRoot = character:FindFirstChild("HumanoidRootPart")
            local localHumanoid = character:FindFirstChildOfClass("Humanoid")
            local cameraTarget
            local cameraHeartbeatConnection
            local originalDisableShiftLock = originalShiftLockMovement
            local autoPunchShiftLockHold = shiftLockMovementApplied
            local characterAimApplied = false
            local shiftLockMovementDisabled = false
            local cameraShiftLockApplied = false
            local cameraShiftLockHumanoid = nil
            local cameraAimLockOwner = {}
            local aimWindowExpired = false

            local function setCharacterAimMovementLock(enabled)
                if not character or not character.Parent then return end
                if enabled then
                    if not shiftLockMovementDisabled then
                        pcall(function()
                            character:SetAttribute("DisableShiftLockMovement", true)
                        end)
                        shiftLockMovementDisabled = true
                    end
                elseif shiftLockMovementDisabled then
                    pcall(function()
                        character:SetAttribute(
                            "DisableShiftLockMovement",
                            autoPunchShiftLockHold and true or originalDisableShiftLock
                        )
                    end)
                    shiftLockMovementDisabled = false
                end
            end

            local function setCameraShiftLock(enabled)
                if enabled then
                    if cameraShiftLockApplied then return end
                    local humanoid = localHumanoid
                    if not humanoid or not humanoid.Parent then return end
                    cameraShiftLockHumanoid = humanoid
                    S.__helpers.setAimAutoRotateLock(cameraAimLockOwner, true, humanoid)
                    cameraShiftLockApplied = true
                elseif cameraShiftLockApplied then
                    S.__helpers.setAimAutoRotateLock(cameraAimLockOwner, false, cameraShiftLockHumanoid)
                    cameraShiftLockHumanoid = nil
                    cameraShiftLockApplied = false
                end
            end

            local function stopPunchAimbotAim()
                if aimWindowExpired then return end
                aimWindowExpired = true
                if cameraHeartbeatConnection then
                    pcall(function()
                        cameraHeartbeatConnection:Disconnect()
                    end)
                    cameraHeartbeatConnection = nil
                end
                if cameraTarget then
                    -- Unbind Character-mode's render-step aim when its window ends.
                    pcall(function()
                        S.RunService:UnbindFromRenderStep(cameraTarget)
                    end)
                    cameraTarget = nil
                end
                setCharacterAimMovementLock(false)
                setCameraShiftLock(false)
                -- Camera mode must not change the character's velocity. Only clean up
                -- velocity if this aim window actually applied Character-mode turning.
                if aimEnabled and characterAimApplied and localRoot and localRoot.Parent then
                    pcall(function() localRoot.Velocity = Vector3.zero end)
                end
            end

            if aimEnabled then
                -- Keep the current Auto Punch trigger and 0.5-second aim window.
                -- Camera mode follows the reference file's Heartbeat-based control:
                -- rotate the root horizontally, zero angular rotation, and point the
                -- camera at the selected target. Do not lock/reposition the mouse.
                S.punchAimbotAimToken = (S.punchAimbotAimToken or 0) + 1

                local function updatePunchAimbotAim()
                    if aimWindowExpired then return end
                    if not S.isAutoPunchEnabled or not S.isPunchAimbotEnabled
                        or character ~= S.lp.Character
                        or not S.__helpers.isLocalRole("Survivor")
                        or not S.__helpers.isLocalGuest1337()
                        or not character.Parent then
                        stopPunchAimbotAim()
                        return
                    end

                    local root = character:FindFirstChild("HumanoidRootPart")
                    if not root then
                        stopPunchAimbotAim()
                        return
                    end

                    -- Use FOV adds a screen-space ring filter. When OFF, retain the
                    -- original nearest-killer selection and 55-stud range exactly.
                    local useFOV = S.isPunchAimbotUseFOV == true
                    local currentKiller = S.__helpers.getClosestForsakenKiller(55, useFOV)
                    local currentKillerRoot = currentKiller
                        and currentKiller:FindFirstChild("HumanoidRootPart")
                    if not currentKillerRoot or not currentKillerRoot.Parent then
                        if useFOV then
                            -- Keep the 0.5s aim window alive so a target entering the
                            -- ring can be acquired on a later frame.
                            setCharacterAimMovementLock(false)
                            setCameraShiftLock(false)
                            return
                        end
                        stopPunchAimbotAim()
                        return
                    end

                    if S.punchAimbotMode == "Camera" then
                        setCharacterAimMovementLock(false)
                        setCameraShiftLock(true)

                        local direction = currentKillerRoot.Position - root.Position
                        local horizontalDirection = Vector3.new(direction.X, 0, direction.Z)
                        if horizontalDirection.Magnitude >= 0.05 then
                            pcall(function()
                                -- Match the reference script's horizontal character-facing
                                -- behavior without changing the character's movement velocity.
                                root.CFrame = CFrame.new(
                                    root.Position,
                                    root.Position + horizontalDirection.Unit
                                )
                                root.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end

                        local camera = workspace.CurrentCamera
                        if camera then
                            pcall(function()
                                camera.CFrame = CFrame.new(
                                    camera.CFrame.Position,
                                    currentKillerRoot.Position
                                )
                            end)
                        end
                    else
                        -- Character mode remains unchanged: move the character toward
                        -- the target while leaving camera and mouse control alone.
                        setCameraShiftLock(false)
                        setCharacterAimMovementLock(true)
                        local selectedPosition = Vector3.new(
                            currentKillerRoot.Position.X,
                            root.Position.Y,
                            currentKillerRoot.Position.Z
                        )
                        if (selectedPosition - root.Position).Magnitude < 0.05 then
                            return
                        end
                        local targetCFrame = CFrame.new(root.Position, selectedPosition)

                        pcall(function()
                            character:SetPrimaryPartCFrame(targetCFrame)
                        end)
                        characterAimApplied = true

                        if not selectedVelocity then
                            root.Velocity = targetCFrame.LookVector * 32
                            selectedVelocity = root.Velocity
                        else
                            selectedVelocity = root.Velocity:Lerp(
                                selectedVelocity,
                                0.8
                            )
                            root.Velocity = selectedVelocity
                        end
                    end
                end

                if S.punchAimbotMode == "Camera" then
                    -- The reference file updates camera/body facing on Heartbeat.
                    cameraHeartbeatConnection = S.RunService.Heartbeat:Connect(updatePunchAimbotAim)
                else
                    -- Preserve the existing Character-mode RenderStep timing.
                    cameraTarget = "ELSGUI_AutoPunchCameraAim_" .. tostring(S.punchAimbotAimToken)
                    S.RunService:BindToRenderStep(
                        cameraTarget,
                        Enum.RenderPriority.Camera.Value + 1,
                        updatePunchAimbotAim
                    )
                end

                -- Do not change activation duration: the aim window still lasts 0.5s.
                task.delay(0.5, stopPunchAimbotAim)
            end

            fireAutoPunchAbility(remote)

            local timeout = os.clock() + 1.25
            repeat
                task.wait(0.1)
            until
                os.clock() >= timeout
                or not S.isAutoPunchEnabled
                or character ~= S.lp.Character
                or not S.__helpers.isLocalRole("Survivor")
                or not S.__helpers.isLocalGuest1337()
                or (fovMultipliers
                    and fovMultipliers:FindFirstChild("HitRegistered"))
                or not speedMultipliers:FindFirstChild("PunchAbility")

            if aimEnabled then
                stopPunchAimbotAim()
            elseif cameraTarget then
                pcall(function()
                    S.RunService:UnbindFromRenderStep(cameraTarget)
                end)
                cameraTarget = nil
            end

            task.wait(0.2)
            autoPunchShiftLockHold = false
            restoreAutoPunchShiftLockMovement()
        end)

        -- Ensure the File 2 movement lock is restored even if activation errors.
        restoreAutoPunchShiftLockMovement()
        S.autoPunchTriggerBusy = false
        if not ok then
            warn("[E1LU4HUB Auto Punch] " .. tostring(err))
        end
    end)
end

S.__helpers.bindAutoPunchRemote = function()
    local remote = S.__helpers.getAutoPunchRemoteEvent()
    if not remote then return false end
    if S.autoPunchRemoteEvent == remote and S.autoPunchRemoteConnection then
        return true
    end

    if S.autoPunchRemoteConnection then
        pcall(function() S.autoPunchRemoteConnection:Disconnect() end)
        S.autoPunchRemoteConnection = nil
    end

    local ok, connection = pcall(function()
        return remote.OnClientEvent:Connect(function(...)
            local args = {...}
            if args[1] ~= (S.lp.Name .. "1337ParryIcon")
                or type(args[2]) ~= "table" or args[2][1] ~= true then
                return
            end

            local character = S.lp and S.lp.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local overheal = humanoid and humanoid:GetAttribute("Overheal")
            if not S.isAutoPunchEnabled
                or not character
                or not S.__helpers.isLocalRole("Survivor")
                or not S.__helpers.isLocalGuest1337()
                or type(overheal) ~= "number" or overheal < 10
                or not S.__helpers.getClosestForsakenKiller(55) then
                return
            end

            S.__helpers.runAutoPunchOnParry(character, remote)
        end)
    end)
    if not ok or not connection then return false end

    S.autoPunchRemoteEvent = remote
    S.autoPunchRemoteConnection = connection
    table.insert(S.connections, connection)
    return true
end

