S.isCharacterInRoleFolder = function(character, roleName)
    if not character then
        return false
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local roleFolder = playersFolder and playersFolder:FindFirstChild(roleName)
    return roleFolder ~= nil and character:IsDescendantOf(roleFolder)
end

