-- Anti Bait uses the same entry condition as Hitbox Drag: a successful Auto Block.
-- Repeated successes extend the active window instead of creating overlapping timers.
S.__helpers.triggerAntiBait = function(triggerSource)
    if not S.isAntiBaitEnabled then return false end

    S.antiBaitToken = (tonumber(S.antiBaitToken) or 0) + 1
    local token = S.antiBaitToken
    S.antiBaitActive = true
    local activeDuration = math.max(0.05, tonumber(S.hitboxDragDuration) or 0.4)

    task.delay(activeDuration, function()
        if S.antiBaitToken == token then
            S.antiBaitActive = false
        end
    end)
    return true
end

-- File 2's nearest-Killer selection, with health/root validation added so a
-- removed or dead rig cannot hold a Hitbox Drag session open.
S.__helpers.getNearestHitboxDragKiller = function()
    local localCharacter = S.lp and S.lp.Character
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    if not localRoot then return nil end

    local playersFolder = workspace:FindFirstChild("Players")
    local killersFolder = playersFolder and playersFolder:FindFirstChild("Killers")
    if not killersFolder then return nil end

    local closest, closestDistance = nil, math.huge
    for _, killer in ipairs(killersFolder:GetChildren()) do
        if killer:IsA("Model") then
            local root = killer:FindFirstChild("HumanoidRootPart")
                or killer.PrimaryPart
                or killer:FindFirstChildWhichIsA("BasePart", true)
            local humanoid = killer:FindFirstChildOfClass("Humanoid")
            if root and (not humanoid or humanoid.Health > 0) then
                local distance = (root.Position - localRoot.Position).Magnitude
                if distance < closestDistance then
                    closest, closestDistance = killer, distance
                end
            end
        end
    end
    return closest
end

S.__helpers.getHitboxDragTargetRoot = function(killerModel)
    if not killerModel then return nil end
    return killerModel:FindFirstChild("HumanoidRootPart")
        or killerModel.PrimaryPart
        or killerModel:FindFirstChildWhichIsA("BasePart", true)
end

-- File 2's short target-facing window (used after Clone and Hitbox Drag).
-- The shared AutoRotate owner manager prevents restoring rotation while another
-- aim feature is still holding the same Humanoid.
S.__helpers.stopFile2Aim = function(owner)
    if owner ~= "AutoClone" and owner ~= "HitboxDrag" then return end
    S.file2AimTokens[owner] = (tonumber(S.file2AimTokens[owner]) or 0) + 1
    local character = S.lp and S.lp.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    S.__helpers.setAimAutoRotateLock(owner, false, humanoid)
end

S.__helpers.startFile2Aim = function(fallbackSeconds, owner)
    if owner ~= "AutoClone" and owner ~= "HitboxDrag" then return false end
    S.file2AimTokens[owner] = (tonumber(S.file2AimTokens[owner]) or 0) + 1
    local token = S.file2AimTokens[owner]
    local fallback = math.max(0.05, tonumber(fallbackSeconds) or 0.4)

    task.spawn(function()
        local character = S.lp and S.lp.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not character or not humanoid or not root then return end

        S.__helpers.setAimAutoRotateLock(owner, true, humanoid)
        local startedAt = os.clock()
        local seenChargeAnimation = false
        while S.file2AimTokens[owner] == token
            and S.lp.Character == character
            and humanoid.Parent and humanoid.Health > 0
            and root.Parent do
            if owner == "AutoClone" and not S.AutoBlockV2.autoClone then break end
            if owner == "HitboxDrag" and not S.isHitboxDragEnabled then break end

            local killer = S.__helpers.getNearestHitboxDragKiller()
            local targetRoot = S.__helpers.getHitboxDragTargetRoot(killer)
            if targetRoot and targetRoot.Parent then
                local prediction = 4
                local predictedPosition = targetRoot.Position + targetRoot.CFrame.LookVector * prediction
                local flatTarget = Vector3.new(predictedPosition.X, root.Position.Y, predictedPosition.Z)
                if (flatTarget - root.Position).Magnitude > 0.001 then
                    pcall(function() root.CFrame = CFrame.lookAt(root.Position, flatTarget) end)
                end
            end

            local chargePlaying = false
            if animator then
                local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
                if ok and tracks then
                    for _, track in ipairs(tracks) do
                        local animationId
                        pcall(function()
                            animationId = tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                        end)
                        if animationId == "106014898538300" then
                            chargePlaying = true
                            seenChargeAnimation = true
                            break
                        end
                    end
                end
            end
            if seenChargeAnimation and not chargePlaying then break end
            if not seenChargeAnimation and os.clock() - startedAt >= fallback then break end
            S.RunService.Heartbeat:Wait()
        end
        if S.file2AimTokens[owner] == token then
            S.__helpers.setAimAutoRotateLock(owner, false, humanoid)
        end
    end)
    return true
end

-- Resolve the independently configurable delay for the detected Killer.
-- Unknown Killer rigs keep a zero-second delay.
S.__helpers.getHitboxDragKillerDelay = function(killerCharacter)
    if not killerCharacter then return 0 end
    local name = tostring(killerCharacter.Name or ""):lower():gsub("[%s_%-]", "")
    local delays = S.hitboxDragKillerDelays or {}

    if name:find("c00lkidd", 1, true) or name:find("coolkidd", 1, true) then
        return math.max(0, tonumber(delays.c00lkidd) or 0)
    elseif name:find("slasher", 1, true) then
        return math.max(0, tonumber(delays.slasher) or 0)
    elseif name:find("johndoe", 1, true) then
        return math.max(0, tonumber(delays.johnDoe) or 0)
    elseif name:find("noli", 1, true) then
        return math.max(0, tonumber(delays.noli) or 0)
    elseif name:find("1x1x1", 1, true) then
        return math.max(0, tonumber(delays.oneXOneXOne) or 0)
    elseif name:find("sixer", 1, true) then
        return math.max(0, tonumber(delays.sixer) or 0)
    elseif name:find("nosferatu", 1, true) or name:find("nosuferatu", 1, true) then
        return math.max(0, tonumber(delays.nosferatu) or 0)
    elseif name:find("azure", 1, true) then
        return math.max(0, tonumber(delays.azure) or 0)
    end

    return 0
end

-- Replaced movement body: a short horizontal BodyVelocity pull toward the nearest
-- Killer, using File 2's stop distance, movement lock, and 0.4-second timeout.
S.hitboxDrag = function(killerModel, triggerSource)
    if not S.isHitboxDragEnabled or S.hitboxDragCooldown or S.hitboxDragPending then
        return false
    end
    if not S.__helpers.isLocalRole("Survivor") then return false end
    if not killerModel or not killerModel.Parent
        or not S.isCharacterInRoleFolder(killerModel, "Killers") then
        return false
    end

    -- Use only the editable delay assigned to this specific Killer.
    local killerStartupDelay = S.__helpers.getHitboxDragKillerDelay(killerModel)
    if killerStartupDelay > 0 then
        S.hitboxDragPending = true
        S.hitboxDragPendingToken = (tonumber(S.hitboxDragPendingToken) or 0) + 1
        local pendingToken = S.hitboxDragPendingToken
        local originalKillerCharacter = killerModel
        task.wait(killerStartupDelay)

        -- Turning either feature off invalidates this pending request. Recheck
        -- that the exact same Killer model still exists before starting movement.
        if S.hitboxDragPendingToken ~= pendingToken then
            return false
        end
        S.hitboxDragPending = false
        if not S.isHitboxDragEnabled
            or S.hitboxDragCooldown
            or not S.__helpers.isLocalRole("Survivor")
            or not originalKillerCharacter.Parent
            or not S.isCharacterInRoleFolder(originalKillerCharacter, "Killers") then
            return false
        end
        killerModel = originalKillerCharacter
    end

    local character = S.lp and S.lp.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local targetRoot = S.__helpers.getHitboxDragTargetRoot(killerModel)
    if not root or not humanoid or humanoid.Health <= 0 or not targetRoot then
        return false
    end

    S.hitboxDragToken = (tonumber(S.hitboxDragToken) or 0) + 1
    local token = S.hitboxDragToken
    S.hitboxDragCooldown = true
    S.isHitboxDragActive = true
    S.hitboxDragTriggerMode = tostring(triggerSource or "File2")

    local originalWalkSpeed = humanoid.WalkSpeed
    local originalJumpPower = humanoid.JumpPower
    local originalPlatformStand = humanoid.PlatformStand
    local dragSpeed = math.max(0, tonumber(S.hitboxDragSpeed) or 5.6)
    local bodyVelocity = Instance.new("BodyVelocity")
    bodyVelocity.MaxForce = Vector3.new(1e5, 0, 1e5)
    bodyVelocity.Velocity = Vector3.zero
    bodyVelocity.Parent = root

    local cleaned = false
    local heartbeatConnection
    local function cleanup()
        if cleaned then return end
        cleaned = true
        if heartbeatConnection then
            pcall(function() heartbeatConnection:Disconnect() end)
            heartbeatConnection = nil
        end
        if bodyVelocity and bodyVelocity.Parent then
            pcall(function() bodyVelocity:Destroy() end)
        end
        if humanoid and humanoid.Parent then
            pcall(function()
                humanoid.WalkSpeed = originalWalkSpeed
                humanoid.JumpPower = originalJumpPower
                humanoid.PlatformStand = originalPlatformStand
            end)
        end
        local currentSession = S.hitboxDragSession
        if currentSession and currentSession.token == token then
            S.hitboxDragSession = nil
            S.hitboxDragCooldown = false
            S.isHitboxDragActive = false
            S.hitboxDragTriggerMode = nil
        end
    end

    S.hitboxDragSession = {token = token, cleanup = cleanup, bodyVelocity = bodyVelocity}
    task.spawn(S.__helpers.startFile2Aim, 0.4, "HitboxDrag")
    pcall(function()
        humanoid.WalkSpeed = 0
        humanoid.JumpPower = 0
        humanoid.PlatformStand = false
    end)

    heartbeatConnection = S.RunService.Heartbeat:Connect(function()
        if cleaned or S.hitboxDragToken ~= token
            or not S.isHitboxDragEnabled
            or not character.Parent or S.lp.Character ~= character
            or not killerModel.Parent or not root.Parent
            or not humanoid.Parent or humanoid.Health <= 0 then
            cleanup()
            return
        end

        targetRoot = S.__helpers.getHitboxDragTargetRoot(killerModel)
        if not targetRoot or not targetRoot.Parent then
            cleanup()
            return
        end

        local toTarget = targetRoot.Position - root.Position
        local distance = toTarget.Magnitude
        local horizontal = Vector3.new(toTarget.X, 0, toTarget.Z)
        if horizontal.Magnitude > 0.01 then
            local direction = horizontal.Unit
            bodyVelocity.Velocity = Vector3.new(
                direction.X * dragSpeed,
                bodyVelocity.Velocity.Y,
                direction.Z * dragSpeed
            )
        else
            bodyVelocity.Velocity = Vector3.new(0, bodyVelocity.Velocity.Y, 0)
        end

        if distance <= 2.0 then
            cleanup()
        end
    end)

    task.delay(math.max(0.05, tonumber(S.hitboxDragDuration) or 0.4), cleanup)
    return true
end

-- Queue one trigger only; the Killer-specific delay is applied inside hitboxDrag
-- after the target Killer has been resolved.
S.__helpers.scheduleHitboxDrag = function(triggerSource)
    if not S.isHitboxDragEnabled or S.hitboxDragCooldown or S.hitboxDragPending then
        return false
    end
    S.hitboxDragPendingToken = (tonumber(S.hitboxDragPendingToken) or 0) + 1
    local token = S.hitboxDragPendingToken
    S.hitboxDragPending = true
    task.spawn(function()
        if S.hitboxDragPendingToken ~= token then return end
        S.hitboxDragPending = false
        if not S.isHitboxDragEnabled or S.hitboxDragCooldown then return end
        local nearestKiller = S.__helpers.getNearestHitboxDragKiller()
        if nearestKiller then
            S.hitboxDrag(nearestKiller, triggerSource)
        end
    end)
    return true
end

-- Hitbox Drag has no independent animation or nearby-hitbox trigger.
-- Its only entry point is the successful Auto Block path in fireAutoBlockAbility.

-- JJSploit ModuleScript compatibility layer (v8)
-- Prefer a normal game-script thread identity so Roblox itself performs
-- the require and returns the real cached module table.
-- ================================================================

S.__executorModuleCache = {}
S.__executorModuleLoading = {}
S.__identitySetter = nil
S.__identityGetter = nil

S.__helpers.__findIdentityAPI = function()
    if type(setthreadidentity) == "function" then
        S.__identitySetter = setthreadidentity
        if type(getthreadidentity) == "function" then
            S.__identityGetter = getthreadidentity
        end
        return true
    end

    if type(setidentity) == "function" then
        S.__identitySetter = setidentity
        if type(getidentity) == "function" then
            S.__identityGetter = getidentity
        end
        return true
    end

    return false
end

S.__helpers.__findIdentityAPI()

S.__helpers.__requireAtGameIdentity = function(moduleScript)
    -- JJSploit can execute this file as an executor script, but attempting
    -- to force a Roblox ModuleScript through a changed thread identity can
    -- execute Network/ActorNetwork twice and produce a cyclic-table error.
    -- Keep the real require path disabled here; runtime-function discovery
    -- below is safer.
    return false, nil
end

S.__helpers.__executorRequire = function(moduleScript)
    if not moduleScript or typeof(moduleScript) ~= "Instance"
        or not moduleScript:IsA("ModuleScript") then
        local ok, result = pcall(require, moduleScript)
        if ok then
            return result
        end
        return nil
    end

    if S.__executorModuleCache[moduleScript] ~= nil then
        return S.__executorModuleCache[moduleScript]
    end

    if S.__executorModuleLoading[moduleScript] then
        return S.__executorModuleCache[moduleScript]
    end

    -- First try the real Roblox require. This is the important path: it
    -- gives us the same module state the game itself is using.
    local directOk, directResult = S.__helpers.__requireAtGameIdentity(moduleScript)
    if directOk then
        S.__executorModuleCache[moduleScript] = directResult
        return directResult
    end

    -- Fallback for executors that expose decompile/loadstring.
    if type(decompile) ~= "function" or type(loadstring) ~= "function"
        or type(getfenv) ~= "function" then
        return nil
    end

    S.__executorModuleLoading[moduleScript] = true

    local okSource, source = pcall(decompile, moduleScript)
    if not okSource or type(source) ~= "string" or source == "" then
        S.__executorModuleLoading[moduleScript] = nil
        return nil
    end

    local okChunk, chunk = pcall(
        loadstring,
        source,
        "=" .. moduleScript:GetFullName()
    )

    if not okChunk or type(chunk) ~= "function" then
        S.__executorModuleLoading[moduleScript] = nil
        return nil
    end

    local chunkEnv = getfenv(chunk)
    if type(chunkEnv) ~= "table" then
        S.__executorModuleLoading[moduleScript] = nil
        return nil
    end

    local oldRequire = chunkEnv.require
    local oldScript = chunkEnv.script
    chunkEnv.require = S.__helpers.__executorRequire
    chunkEnv.script = moduleScript

    local okRun, result = pcall(chunk)

    chunkEnv.require = oldRequire
    chunkEnv.script = oldScript
    S.__executorModuleLoading[moduleScript] = nil

    if not okRun then
        return nil
    end

    S.__executorModuleCache[moduleScript] = result
    return result
end

S.SprintingModule = require(
    S.ReplicatedStorage
        :WaitForChild("Systems")
        :WaitForChild("Character")
        :WaitForChild("Game")
        :WaitForChild("Sprinting")
)

S.__helpers.installNoSprintTweeningHook = function()
    if S.noSprintTweeningHookInstalled then
        return S.noSprintTweeningHookAvailable
    end

    -- Match the source script's interception point, but keep it narrowly scoped
    -- to TweenService:Create calls targeting the game's Sprinting.__speedMultiplier.
    if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false
    end

    local originalNamecall
    local wrapper = function(self, ...)
        local methodName
        pcall(function() methodName = getnamecallmethod() end)
        if S.isNoSprintTweeningEnabled == true
            and self == S.TweenService
            and methodName == "Create" then
            local target, tweenInfo, goals = ...
            local sprintModule = S.SprintingModule
            local speedMultiplier = sprintModule and sprintModule.__speedMultiplier
            if speedMultiplier ~= nil and target == speedMultiplier then
                return originalNamecall(self, target, TweenInfo.new(0), goals)
            end
        end
        return originalNamecall(self, ...)
    end

    if type(newcclosure) == "function" then
        local okClosure, closure = pcall(newcclosure, wrapper)
        if okClosure and type(closure) == "function" then
            wrapper = closure
        end
    end

    local ok, oldFunction = pcall(function()
        return hookmetamethod(game, "__namecall", wrapper)
    end)
    if ok and type(oldFunction) == "function" then
        originalNamecall = oldFunction
        S.noSprintTweeningHookInstalled = true
        S.noSprintTweeningHookAvailable = true
        return true
    end

    return false
end

S.__helpers.setNoSprintTweening = function(enabled)
    S.isNoSprintTweeningEnabled = enabled == true
    if not S.isNoSprintTweeningEnabled then
        return true
    end
    local installed = S.__helpers.installNoSprintTweeningHook()
    if not installed then
        S.isNoSprintTweeningEnabled = false
        if type(S.__helpers.notify) == "function" then
            S.__helpers.notify("No Sprint Tweening", "This executor does not expose the required hook API.", 4)
        end
        return false
    end
    return true
end

