-- Auto Punch FOV ring lives on a layer below the hub UI but above the game HUD.
S.__helpers.createPunchFOVRing = function()
    local oldRingGui = S.guiParent:FindFirstChild("E1LU4HUB_AutoPunchFOVRing")
    if oldRingGui then
        pcall(function() oldRingGui:Destroy() end)
    end

    local ringGui = Instance.new("ScreenGui")
    ringGui.Name = "E1LU4HUB_AutoPunchFOVRing"
    ringGui.ResetOnSpawn = false
    ringGui.IgnoreGuiInset = true
    ringGui.DisplayOrder = math.max(0, (tonumber(S.screenGui.DisplayOrder) or 1) - 1)
    ringGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    ringGui.Enabled = true
    ringGui.Parent = S.guiParent
    S.punchFOVScreenGui = ringGui

    local ring = Instance.new("Frame")
    ring.Name = "FOVRing"
    ring.AnchorPoint = Vector2.new(0.5, 0.5)
    ring.Position = UDim2.fromScale(0.5, 0.5)
    local diameter = (tonumber(S.PUNCH_AIMBOT_FOV_RADIUS) or 120) * 2
    ring.Size = UDim2.fromOffset(diameter, diameter)
    ring.BackgroundTransparency = 1
    ring.BorderSizePixel = 0
    ring.Visible = false
    ring.Active = false
    ring.ZIndex = 1
    ring.Parent = ringGui

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(1, 0)
    corner.Parent = ring

    local stroke = Instance.new("UIStroke")
    stroke.Name = "FOVRingStroke"
    stroke.Color = S.PUNCH_FOV_RING_COLOR
    stroke.Thickness = 0.6
    stroke.Transparency = 0.08
    stroke.Parent = ring

    S.punchFOVRing = ring
    S.punchFOVRingStroke = stroke
end

S.__helpers.updatePunchFOVRingVisibility = function()
    if S.punchFOVRing and S.punchFOVRing.Parent then
        -- Show the ring whenever Use FOV is enabled, even while Auto Punch
        -- Aimbot itself is disabled, so the user can preview the selected area.
        S.punchFOVRing.Visible = S.isPunchAimbotUseFOV == true
    end
end

S.__helpers.setPunchFOVRingRadius = function(value)
    local radius = tonumber(value) or 120
    radius = math.clamp(radius, 20, 500)
    S.PUNCH_AIMBOT_FOV_RADIUS = radius

    if S.punchFOVRing and S.punchFOVRing.Parent then
        local diameter = radius * 2
        S.punchFOVRing.Size = UDim2.fromOffset(diameter, diameter)
    end
    return radius
end

S.__helpers.setPunchFOVRingColor = function(color)
    if typeof(color) == "Color3" then
        S.PUNCH_FOV_RING_COLOR = color
    else
        S.PUNCH_FOV_RING_COLOR = Color3.fromRGB(255, 255, 255)
    end
    if S.punchFOVRingStroke and S.punchFOVRingStroke.Parent then
        S.punchFOVRingStroke.Color = S.PUNCH_FOV_RING_COLOR
    end
end

S.__helpers.createPunchFOVRing()

