S.__helpers.getNotificationSidebarIcon = function(titleText)
    local title = tostring(titleText or ""):lower()
    local iconMap = {
        {"config", "rbxassetid://7734053495"},
        {"setting", "rbxassetid://7734053495"},
        {"ui color", "rbxassetid://7734053495"},
        {"stamina", "rbxassetid://7733655755"},
        {"visual", "rbxassetid://7733774602"},
        {"esp", "rbxassetid://7733774602"},
        {"survivor", "rbxassetid://7743876054"},
        {"killer", "rbxassetid://10734975692"},
        {"auto block", "rbxassetid://7734056608"},
        {"block", "rbxassetid://7734056608"},
        {"punch", "rbxassetid://10734975692"},
        {"aimbot", "rbxassetid://10734975692"},
        {"stab", "rbxassetid://121406454377051"},
        {"studs", "rbxassetid://121406454377051"},
        {"anti", "rbxassetid://10723426595"},
        {"music", "rbxassetid://7734020554"},
        {"animation", "rbxassetid://7734037784"},
        {"skin changer", "rbxassetid://7734056672"},
        {"game", "rbxassetid://7733799795"},
        {"clip", "rbxassetid://7733799795"},
        {"generator", "rbxassetid://7733799795"},
        {"item", "rbxassetid://7733799795"},
        {"tp ", "rbxassetid://7733799795"},
    }
    for _, entry in ipairs(iconMap) do
        if title:find(entry[1], 1, true) then
