    return "rbxassetid://7733964719" -- Info sidebar icon as the general notification icon.
end

S.__helpers.notify = function(titleText, messageText, duration, accentOverride)
    -- Config loads can invoke legacy feature callbacks that call notify directly,
    -- bypassing notifyCategorizedControl. Suppress all such callback toasts while
    -- the config transaction is applying; the final "Config Loaded" toast is
    -- emitted after S.__configApplying is restored and remains visible.
    if S.__configApplying == true then return nil end

    local screen = S.screenGui
    if not screen or not screen.Parent then return nil end

    S.notificationSequence = (S.notificationSequence or 0) + 1
    local customAccent = typeof(accentOverride) == "Color3" and accentOverride or nil
    -- Match the notification card's fill and opacity to the E1LU4HUB window.
    -- Keep its decorative outline and countdown bar tied to UI COLOR instead.
    local windowBackground = (S.mainFrame and S.mainFrame.BackgroundColor3) or S.NOTIFICATION_DEFAULT_COLOR
    local windowTransparency = (S.mainFrame and tonumber(S.mainFrame.BackgroundTransparency)) or 0.12
    local uiAccent = S.uiAccentColor or S.NOTIFICATION_DEFAULT_COLOR
    -- Explicit success accents (UI loaded / Auto Block enabled) color the full toast accent.
    local toastAccent = customAccent or uiAccent
    local iconAccent = toastAccent
    local lifetime = math.max(1.2, tonumber(duration) or 3.8)
    local serial = S.notificationSequence

    local toast = Instance.new("Frame")
    toast.Name = "E1LU4HUB_Toast_" .. tostring(serial)
    toast.AnchorPoint = Vector2.new(1, 0)
    toast.Position = UDim2.new(1, 430, 0, 12)
    toast.Size = UDim2.new(0, 398, 0, 88)
    toast.BackgroundColor3 = windowBackground
    toast.BackgroundTransparency = windowTransparency
    toast.BorderSizePixel = 0
    toast.ClipsDescendants = true
    toast.ZIndex = 800
    toast.Parent = screen

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 13)
    corner.Parent = toast

    local stroke = Instance.new("UIStroke")
    stroke.Color = toastAccent
    stroke.Thickness = 1
    stroke.Transparency = 0.18
    stroke.Parent = toast

    -- Compact sidebar-style icon tile with a small notification accent dot.
    local iconTile = Instance.new("Frame")
    iconTile.Name = "NotificationIconTile"
    iconTile.Position = UDim2.new(0, 24, 0, 23)
    iconTile.Size = UDim2.fromOffset(42, 42)
    iconTile.BackgroundColor3 = iconAccent
    iconTile.BackgroundTransparency = 0.84
    iconTile.BorderSizePixel = 0
    iconTile.ZIndex = 801
    iconTile.Parent = toast

    local iconTileCorner = Instance.new("UICorner")
    iconTileCorner.CornerRadius = UDim.new(0, 10)
    iconTileCorner.Parent = iconTile

    local iconTileStroke = Instance.new("UIStroke")
    iconTileStroke.Name = "NotificationIconTileStroke"
    iconTileStroke.Color = iconAccent
    iconTileStroke.Thickness = 1
    iconTileStroke.Transparency = 0.48
    iconTileStroke.Parent = iconTile

    local icon = Instance.new("ImageLabel")
    icon.Name = "NotificationIcon"
    icon.AnchorPoint = Vector2.new(0.5, 0.5)
    icon.Position = UDim2.fromScale(0.5, 0.5)
    icon.Size = UDim2.fromOffset(20, 20)
    icon.BackgroundTransparency = 1
    icon.BorderSizePixel = 0
    icon.Image = S.__helpers.getNotificationSidebarIcon(titleText)
    icon.ImageColor3 = iconAccent
    icon.ScaleType = Enum.ScaleType.Fit
    icon.ZIndex = 802
    icon.Parent = iconTile

    local iconBadge = Instance.new("Frame")
    iconBadge.Name = "NotificationIconBadge"
    iconBadge.Position = UDim2.new(0, 58, 0, 19)
    iconBadge.Size = UDim2.fromOffset(8, 8)
    iconBadge.BackgroundColor3 = iconAccent
    iconBadge.BorderSizePixel = 0
    iconBadge.ZIndex = 803
    iconBadge.Parent = toast

    local iconBadgeCorner = Instance.new("UICorner")
    iconBadgeCorner.CornerRadius = UDim.new(1, 0)
    iconBadgeCorner.Parent = iconBadge

    local heading = Instance.new("TextLabel")
    heading.Name = "NotificationTitle"
    heading.BackgroundTransparency = 1
    heading.Position = UDim2.new(0, 80, 0, 15)
    heading.Size = UDim2.new(1, -126, 0, 22)
    heading.Font = Enum.Font.GothamBold
    heading.Text = tostring(titleText or "Notification")
    heading.TextColor3 = Color3.fromRGB(250, 245, 249)
    heading.TextSize = 14
    heading.TextXAlignment = Enum.TextXAlignment.Left
    heading.TextTruncate = Enum.TextTruncate.AtEnd
    heading.ZIndex = 801
    heading.Parent = toast

    local body = Instance.new("TextLabel")
    body.Name = "NotificationMessage"
    body.BackgroundTransparency = 1
    body.Position = UDim2.new(0, 80, 0, 39)
    body.Size = UDim2.new(1, -97, 0, 30)
    body.Font = Enum.Font.Gotham
    body.Text = tostring(messageText or "")
    body.TextColor3 = customAccent or Color3.fromRGB(184, 157, 177)
    body.TextSize = 12
    body.TextXAlignment = Enum.TextXAlignment.Left
    body.TextYAlignment = Enum.TextYAlignment.Top
    body.TextWrapped = true
    body.ZIndex = 801
    body.Parent = toast

    local closeButton = Instance.new("TextButton")
    closeButton.Name = "NotificationClose"
    closeButton.BackgroundTransparency = 1
    closeButton.Position = UDim2.new(1, -34, 0, 9)
    closeButton.Size = UDim2.new(0, 25, 0, 25)
    closeButton.Text = "×"
    closeButton.TextColor3 = Color3.fromRGB(187, 151, 170)
    closeButton.Font = Enum.Font.Gotham
    closeButton.TextSize = 20
    closeButton.AutoButtonColor = false
    closeButton.ZIndex = 802
    closeButton.Parent = toast

    local progress = Instance.new("Frame")
    progress.Name = "NotificationProgress"
    progress.AnchorPoint = Vector2.new(0, 1)
    progress.Position = UDim2.new(0, 0, 1, 0)
    progress.Size = UDim2.new(1, 0, 0, 3)
    progress.BackgroundColor3 = toastAccent
    progress.BackgroundTransparency = 0.12
    progress.BorderSizePixel = 0
    progress.ZIndex = 802
    progress.Parent = toast

    local state = {
        frame = toast,
        stroke = stroke,
        icon = icon,
        iconTile = iconTile,
        iconTileStroke = iconTileStroke,
        iconBadge = iconBadge,
        progress = progress,
        body = body,
        iconAccent = iconAccent,
        accentOverride = customAccent,
        closed = false,
    }
    table.insert(S.notificationToasts, state)

    local function reflow()
        for index, item in ipairs(S.notificationToasts) do
            if item.frame and item.frame.Parent then
                local target = UDim2.new(1, -12, 0, 10 + (index - 1) * 96)
                local tween = S.TweenService:Create(
                    item.frame,
                    TweenInfo.new(0.24, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {Position = target}
                )
                tween:Play()
            end
        end
    end

    local function dismiss()
        if state.closed then return end
        state.closed = true
        for index, item in ipairs(S.notificationToasts) do
            if item == state then
                table.remove(S.notificationToasts, index)
                break
            end
        end
        if toast and toast.Parent then
            local yOffset = toast.Position.Y.Offset
            local exitTween = S.TweenService:Create(
                toast,
                TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
                {Position = UDim2.new(1, 430, 0, yOffset), BackgroundTransparency = 1}
            )
            pcall(function() S.TweenService:Create(stroke, TweenInfo.new(0.16), {Transparency = 1}):Play() end)
            pcall(function() S.TweenService:Create(progress, TweenInfo.new(0.16), {BackgroundTransparency = 1}):Play() end)
            for _, object in ipairs(toast:GetDescendants()) do
                if object:IsA("TextLabel") or object:IsA("TextButton") then
                    pcall(function()
                        S.TweenService:Create(object, TweenInfo.new(0.16), {TextTransparency = 1}):Play()
                    end)
                elseif object:IsA("ImageLabel") then
                    pcall(function()
                        S.TweenService:Create(object, TweenInfo.new(0.16), {ImageTransparency = 1}):Play()
                    end)
                elseif object:IsA("Frame") and (object.Name == "NotificationIconTile" or object.Name == "NotificationIconBadge") then
                    pcall(function()
                        S.TweenService:Create(object, TweenInfo.new(0.16), {BackgroundTransparency = 1}):Play()
                    end)
                elseif object:IsA("UIStroke") then
                    pcall(function()
                        S.TweenService:Create(object, TweenInfo.new(0.16), {Transparency = 1}):Play()
                    end)
                end
            end
            exitTween:Play()
            task.delay(0.23, function()
                if toast and toast.Parent then toast:Destroy() end
            end)
        end
        reflow()
    end

    closeButton.Activated:Connect(dismiss)
    reflow()

    pcall(function()
        S.TweenService:Create(
            progress,
            TweenInfo.new(lifetime, Enum.EasingStyle.Linear, Enum.EasingDirection.Out),
            {Size = UDim2.new(0, 0, 0, 3)}
        ):Play()
    end)
    task.delay(lifetime, dismiss)
    return toast
end

-- Route action notifications only for the categories that require them.
-- Controls are moved into their final category pages after construction, so
-- resolve the page from the live ancestry when the user interacts with a control.
S.__helpers.getNotificationCategoryForControl = function(control)
    local node = control
    while node do
        if node.Name == "Page_Misc" then return "Misc" end
        if node.Name == "Page_Fun" then return "Fun" end
        if node.Name == "Page_SkinChanger" then return "Skin Changer" end
        if node.Name == "Page_Animation" then return "Animation" end
        node = node.Parent
    end
    return nil
end

S.__helpers.notifyCategorizedControl = function(control, titleText, messageText, duration)
    -- Config application invokes feature callbacks internally; do not emit per-feature
    -- notifications while applying saved states (especially OFF -> OFF).
    if S.__configApplying == true then return end
    if not S.__helpers.getNotificationCategoryForControl(control) then return end
    if type(S.__helpers.notify) == "function" then
        S.__helpers.notify(titleText or "E1LU4 HUB", messageText or "Updated.", duration or 3.2)
    end
end

