S.__helpers.updateMinimizedRestoreButton = function()
    -- Main content stays at the highest PlayerGui layer. The restore button has
    -- its own CoreGui ScreenGui so it also layers above ordinary game HUDs.
    if S.screenGui and S.screenGui.Parent then
        pcall(function() S.screenGui.DisplayOrder = 2147483647 end)
    end
    if S.restoreScreenGui and S.restoreScreenGui.Parent then
        pcall(function()
            S.restoreScreenGui.DisplayOrder = 2147483647
            S.restoreScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
            S.restoreScreenGui.Enabled = true
        end)
    end
    if S.minimizedRestoreButton then
        pcall(function() S.minimizedRestoreButton.ZIndex = 2147483647 end)
        -- Keep the compact restore arrow available on every device while the main window is hidden.
        local mainVisible = S.mainFrame ~= nil and S.mainFrame.Visible == true
        S.minimizedRestoreButton.Visible = (S.initialDeviceIsPC ~= true)
            and not S.hideRestoreButtonForHotkey
    end
end

