-- One close path for every floating selector. Popups live under ScreenGui rather
-- than MainFrame, so they must be closed explicitly when the main UI is hidden.
S.__helpers.closeAllSelectionPopups = function()
    if S.espColorPickerUI and type(S.espColorPickerUI.close) == "function" then
        pcall(S.espColorPickerUI.close)
    end
    if S.__helpers.closeRightDropdownPopup then
        pcall(S.__helpers.closeRightDropdownPopup)
    end
    if S.__helpers.closeSkinChangerPopup then
        pcall(S.__helpers.closeSkinChangerPopup)
    end

    local screen = S.screenGui
    if not screen or not screen.Parent then return end
    for _, popupName in ipairs({
        "PlopSpooferSelectionPopup",
        "PlopSpooferMultiSelectionPopup",
        "E1LU4HUB_RightDropdownPopup",
        "SkinChangerSelectionPopup",
        "E1LU4HUBConfigListPopup",
    }) do
        local popup = screen:FindFirstChild(popupName)
        if popup then pcall(function() popup:Destroy() end) end
    end
end

S.__helpers.hasOpenSelectionPopup = function()
    local screen = S.screenGui
    if not screen then return false end
    if S.espColorPickerUI and S.espColorPickerUI.frame
        and S.espColorPickerUI.frame.Parent and S.espColorPickerUI.frame.Visible then
        return true
    end
    for _, popupName in ipairs({
        "PlopSpooferSelectionPopup",
        "PlopSpooferMultiSelectionPopup",
        "E1LU4HUB_RightDropdownPopup",
        "SkinChangerSelectionPopup",
        "E1LU4HUBConfigListPopup",
    }) do
        local popup = screen:FindFirstChild(popupName)
        if popup and popup.Visible ~= false then return true end
    end
    return false
end

S.__helpers.isPointInsideGuiObject = function(guiObject, position)
    if not guiObject or not guiObject:IsA("GuiObject") or guiObject.Visible == false then
        return false
    end
    local topLeft = guiObject.AbsolutePosition
    local size = guiObject.AbsoluteSize
    return position.X >= topLeft.X and position.Y >= topLeft.Y
        and position.X <= topLeft.X + size.X and position.Y <= topLeft.Y + size.Y
end

S.__helpers.isInsideOpenSelectionPopup = function(position)
    local screen = S.screenGui
    if not screen then return false end
    local popupTargets = {
        {"ESPColorPicker", nil},
        {"E1LU4HUB_RightDropdownPopup", nil},
        {"SkinChangerSelectionPopup", nil},
        {"PlopSpooferSelectionPopup", "SelectionPanel"},
        {"PlopSpooferMultiSelectionPopup", "SelectionPanel"},
        {"E1LU4HUBConfigListPopup", "ConfigListPanel"},
    }
    for _, targetInfo in ipairs(popupTargets) do
        local popup = screen:FindFirstChild(targetInfo[1])
        if popup and popup.Visible ~= false then
            local target = targetInfo[2] and popup:FindFirstChild(targetInfo[2]) or popup
            if S.__helpers.isPointInsideGuiObject(target, position) then
                return true
            end
        end
    end
    return false
end

S.__helpers.isPopupOpenerAtPosition = function(position)
    local screen = S.screenGui
    if not screen then return false end
    for _, object in ipairs(screen:GetDescendants()) do
        if object:IsA("GuiObject") and object:GetAttribute("E1LU4HUB_PopupOpener") == true
            and object.Visible ~= false
            and S.__helpers.isPointInsideGuiObject(object, position) then
            return true
        end
    end
    return false
end

-- Tapping anywhere outside an open selector (including the main window) closes
-- it. The selector's own content and its opener buttons keep their normal action.
S.__helpers.connect(S.UserInputService.InputBegan, function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then
        return
    end
    if not S.__helpers.hasOpenSelectionPopup() then return end
    local clickPosition = Vector2.new(input.Position.X, input.Position.Y)
    task.defer(function()
        if not S.__helpers.hasOpenSelectionPopup() then return end
        if S.__helpers.isInsideOpenSelectionPopup(clickPosition) then return end

        -- Full-screen selection sheets cover the controls beneath them. Any tap
        -- outside their actual panel is therefore an outside tap, not an opener.
        local screen = S.screenGui
        local hasFullScreenSheet = screen and (
            screen:FindFirstChild("PlopSpooferSelectionPopup")
            or screen:FindFirstChild("PlopSpooferMultiSelectionPopup")
            or screen:FindFirstChild("E1LU4HUBConfigListPopup")
        )
        if not hasFullScreenSheet and S.__helpers.isPopupOpenerAtPosition(clickPosition) then
            return
        end
        S.__helpers.closeAllSelectionPopups()
    end)
end)

S.__helpers.captureMainFrameOpacity = function()
    local records = {}
    local function capture(obj, property)
        local ok, value = pcall(function() return obj[property] end)
        if ok and type(value) == "number" then
            records[obj] = records[obj] or {}
            records[obj][property] = value
        end
    end
    local function captureObject(obj)
        if obj:IsA("GuiObject") then capture(obj, "BackgroundTransparency") end
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            capture(obj, "TextTransparency")
            capture(obj, "TextStrokeTransparency")
        end
        if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then capture(obj, "ImageTransparency") end
        if obj:IsA("UIStroke") then capture(obj, "Transparency") end
    end
    captureObject(S.mainFrame)
    for _, obj in ipairs(S.mainFrame:GetDescendants()) do captureObject(obj) end
    return records
end

S.__helpers.applyMainFrameVisibility = function(visible)
    visible = visible == true
    if not visible and S.__helpers.closeAllSelectionPopups then
        S.__helpers.closeAllSelectionPopups()
    end
    local frame = S.mainFrame
    if not frame or not frame.Parent then return end
    S.__helpers.mainFrameVisibilityToken += 1
    local token = S.__helpers.mainFrameVisibilityToken
    local tweenInfo = TweenInfo.new(0.22, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)

    if visible then
        if not S.__helpers.mainFrameOpacityBaseline then
            frame.Visible = true
            S.__helpers.updateMinimizedRestoreButton()
            return
        end
        local baseline = S.__helpers.mainFrameOpacityBaseline
        local basePosition = S.__helpers.mainFrameLastPosition or frame.Position
        frame.Position = UDim2.new(basePosition.X.Scale, basePosition.X.Offset, basePosition.Y.Scale, basePosition.Y.Offset - 14)
        for obj, properties in pairs(baseline) do
            if obj and obj.Parent then
                for property in pairs(properties) do
                    pcall(function() obj[property] = 1 end)
                end
            end
        end
        frame.Visible = true
        S.__helpers.updateMinimizedRestoreButton()
        for obj, properties in pairs(baseline) do
            if obj and obj.Parent then
                local goal = {}
                for property, originalValue in pairs(properties) do goal[property] = originalValue end
                if next(goal) then
                    pcall(function() S.TweenService:Create(obj, tweenInfo, goal):Play() end)
                end
            end
        end
        pcall(function()
            S.TweenService:Create(frame, tweenInfo, {Position = basePosition}):Play()
        end)
    else
        if not frame.Visible then
            S.__helpers.updateMinimizedRestoreButton()
            return
        end
        S.__helpers.mainFrameLastPosition = frame.Position
        if not S.__helpers.mainFrameOpacityBaseline then
            S.__helpers.mainFrameOpacityBaseline = S.__helpers.captureMainFrameOpacity()
        end
        local baseline = S.__helpers.mainFrameOpacityBaseline
        local targetPosition = UDim2.new(frame.Position.X.Scale, frame.Position.X.Offset, frame.Position.Y.Scale, frame.Position.Y.Offset - 14)
        for obj, properties in pairs(baseline) do
            if obj and obj.Parent then
                local goal = {}
                for property in pairs(properties) do goal[property] = 1 end
                if next(goal) then pcall(function() S.TweenService:Create(obj, tweenInfo, goal):Play() end) end
            end
        end
        local mainTween = S.TweenService:Create(frame, tweenInfo, {
            Position = targetPosition,
        })
        mainTween.Completed:Connect(function()
            if token ~= S.__helpers.mainFrameVisibilityToken then return end
            frame.Visible = false
            frame.Position = S.__helpers.mainFrameLastPosition or frame.Position
            for obj, properties in pairs(baseline) do
                if obj and obj.Parent then
                    for property, originalValue in pairs(properties) do
                        pcall(function() obj[property] = originalValue end)
                    end
                end
            end
            S.__helpers.updateMinimizedRestoreButton()
        end)
        mainTween:Play()
    end
end

S.__helpers.setMainFrameVisible = function(value)
    -- Explicit mouse actions retain the normal restore-button behavior on non-PC devices.
    S.hideRestoreButtonForHotkey = false
    S.__helpers.applyMainFrameVisibility(value == true)
end

-- The compact keybind panel lives in the independent restore layer, not inside
-- MainFrame, so B can hide the menu without hiding the list.
S.keybindPanel = nil
S.keybindRowsContainer = nil
S.keybindListHiddenByP = false
S.__helpers.getActiveKeybindRows = function()
    local rows = {
        {label = "Menu Toggle", key = S.menuToggleKey or "B"},
    }
    if S.isTPGeneratorHotkeyEnabled == true then
        table.insert(rows, {label = "TP to Generator", key = S.tpGeneratorKey or "Z"})
    end
    if S.isAutoBlockToggleEnabled == true then
        table.insert(rows, {label = "Auto Block Toggle", key = S.autoBlockToggleKey or "Q"})
    end
    if S.fakeBlockEnabled == true then
        table.insert(rows, {label = "Fake Block", key = S.fakeBlockKey or "F"})
    end

    -- Every enabled Fun action that has a configurable key is listed here.
    -- Toggle-only looping emotes have no action key, so they are intentionally omitted.
    for _, state in ipairs(S.funEmoteButtonOrder or {}) do
        if state and state.enabled == true
            and state.definition and state.definition.toggleOnly ~= true
            and state.key ~= nil then
            local emoteKey = S.__helpers.normalizeKeyName(state.key)
            if emoteKey and tostring(emoteKey):upper() ~= "P" then
                local label = tostring(state.definition.label or state.definition.id or "Fun Action")
                label = label:lower():gsub("^%l", string.upper)
                table.insert(rows, {label = label, key = emoteKey})
            end
        end
    end

    -- P belongs only to the panel visibility shortcut, never to this list.
    local visibleRows = {}
    for _, entry in ipairs(rows) do
        local normalized = S.__helpers.normalizeKeyName(entry.key)
        if not normalized or tostring(normalized):upper() ~= "P" then
            table.insert(visibleRows, entry)
        end
    end
    return visibleRows
end

S.__helpers.refreshKeybindList = function()
    local panel = S.keybindPanel
    local rowsContainer = S.keybindRowsContainer
    if not panel or not panel.Parent or not rowsContainer then return end

    for _, child in ipairs(rowsContainer:GetChildren()) do
        if child:IsA("Frame") then child:Destroy() end
    end

    local rows = S.__helpers.getActiveKeybindRows()
    local rowHeight = 25
    rowsContainer.Size = UDim2.new(1, -12, 0, #rows * rowHeight + 3)
    panel.Size = UDim2.new(0, 204, 0, math.max(165, 48 + #rows * rowHeight + 8))

    for index, entry in ipairs(rows) do
        local row = Instance.new("Frame")
        row.Name = "KeybindRow_" .. tostring(index)
        row.Size = UDim2.new(1, 0, 0, rowHeight)
        row.BackgroundTransparency = 1
        row.BorderSizePixel = 0
        row.LayoutOrder = index
        row.ZIndex = 2147483647
        row.Parent = rowsContainer

        local nameLabel = Instance.new("TextLabel")
        nameLabel.Name = "ActionName"
        nameLabel.Position = UDim2.new(0, 3, 0, 0)
        nameLabel.Size = UDim2.new(1, -48, 1, 0)
        nameLabel.BackgroundTransparency = 1
        nameLabel.Text = tostring(entry.label)
        nameLabel.TextColor3 = Color3.fromRGB(224, 218, 221)
        nameLabel.TextSize = 10
        nameLabel.Font = Enum.Font.Gotham
        nameLabel.TextXAlignment = Enum.TextXAlignment.Left
        nameLabel.TextTruncate = Enum.TextTruncate.AtEnd
        nameLabel.ZIndex = 2147483647
        nameLabel.Parent = row

        local keyLabel = Instance.new("TextLabel")
        keyLabel.Name = "KeyName"
        keyLabel.AnchorPoint = Vector2.new(1, 0)
        keyLabel.Position = UDim2.new(1, -3, 0, 0)
        keyLabel.Size = UDim2.new(0, 42, 1, 0)
        keyLabel.BackgroundTransparency = 1
        keyLabel.Text = "[" .. tostring(S.__helpers.getKeyDisplayName(entry.key)) .. "]"
        keyLabel.TextColor3 = S.uiAccentColor or Color3.fromRGB(235, 220, 225)
        keyLabel.TextSize = 10
        keyLabel.Font = Enum.Font.GothamBold
        keyLabel.TextXAlignment = Enum.TextXAlignment.Right
        keyLabel.ZIndex = 2147483647
        keyLabel.Parent = row
    end
end

S.__helpers.isAnyKeybindListening = function()
    if not S.screenGui then return false end
    for _, object in ipairs(S.screenGui:GetDescendants()) do
        if object.Name == "KeybindContainer" and object:GetAttribute("Listening") == true then
            return true
        end
    end
    return false
end

S.__helpers.connect(S.UserInputService.InputBegan, function(input, gameProcessed)
    if gameProcessed then return end
    if S.__helpers.isAnyKeybindListening and S.__helpers.isAnyKeybindListening() then return end

    -- B is the permanent Menu Toggle. It changes only the main window; the
    -- keybind panel remains visible independently on startup-detected PC devices.
    if input.KeyCode == Enum.KeyCode.B then
        S.__helpers.applyMainFrameVisibility(not (S.mainFrame and S.mainFrame.Visible))
        return
    end

    -- P hides/restores both the main UI and the keybind panel. It is independent
    -- from B, which never hides the panel.
    if input.KeyCode == Enum.KeyCode.P then
        S.keybindListHiddenByP = not S.keybindListHiddenByP
        S.executorStatusHiddenByP = S.keybindListHiddenByP
        S.hideRestoreButtonForHotkey = S.keybindListHiddenByP
        S.__helpers.applyMainFrameVisibility(not S.keybindListHiddenByP)
        if S.keybindPanel then
            S.keybindPanel.Visible = not S.keybindListHiddenByP
        end
        if S.__helpers.updateExecutorStatusVisibility then S.__helpers.updateExecutorStatusVisibility() end
        S.__helpers.updateMinimizedRestoreButton()
    end
end)

