S.dragging , S.dragInput , S.dragStart , S.startPos = nil, nil, nil, nil
S.resizeHandle = nil
S.isResizingMainFrame = false
S.resizeHandleHovered = false
S.resizeDragStartPosition = nil
S.resizeStartSize = nil

S.__helpers.isInputOverResizeHandle = function(position)
    local handle = S.resizeHandle
    if not handle or not handle.Parent or not handle.Visible then return false end
    local handlePosition = handle.AbsolutePosition
    local handleSize = handle.AbsoluteSize
    return position.X >= handlePosition.X - 2
        and position.X <= handlePosition.X + handleSize.X + 2
        and position.Y >= handlePosition.Y - 2
        and position.Y <= handlePosition.Y + handleSize.Y + 2
end

S.__helpers.updateMainFrameResize = function(input)
    local frame = S.mainFrame
    if not S.isResizingMainFrame or not frame or not frame.Parent
        or not S.resizeDragStartPosition or not S.resizeStartSize or not input then
        return
    end
    local viewport = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
        or Vector2.new(1920, 1080)
    local minWidth = math.min(680, math.max(320, viewport.X - 16))
    local minHeight = math.min(420, math.max(280, viewport.Y - 16))
    local topLeft = frame.AbsolutePosition

    -- Keep enough room for the minimum size if the user moved the window to an edge.
    local maxLeft = math.max(8, viewport.X - minWidth - 8)
    local maxTop = math.max(8, viewport.Y - minHeight - 8)
    local targetLeft = math.clamp(topLeft.X, 8, maxLeft)
    local targetTop = math.clamp(topLeft.Y, 8, maxTop)
    if math.abs(targetLeft - topLeft.X) > 0.5 or math.abs(targetTop - topLeft.Y) > 0.5 then
        frame.Position = UDim2.fromOffset(targetLeft, targetTop)
        topLeft = frame.AbsolutePosition
    end

    local maxWidth = math.max(minWidth, math.min(1600, viewport.X - topLeft.X - 8))
    local maxHeight = math.max(minHeight, math.min(1000, viewport.Y - topLeft.Y - 8))
    local pointerPosition = Vector2.new(input.Position.X, input.Position.Y)
    local delta = pointerPosition - S.resizeDragStartPosition
    local width = math.clamp(S.resizeStartSize.X + delta.X, minWidth, maxWidth)
    local height = math.clamp(S.resizeStartSize.Y + delta.Y, minHeight, maxHeight)
    frame.Size = UDim2.fromOffset(math.floor(width + 0.5), math.floor(height + 0.5))
end

-- Do not let a click inside Hitbox Preview start or continue moving the main UI.
-- Use the rendered card bounds so this also works before MouseEnter has fired,
-- and respect the visible area of the parent scrolling page.
S.__helpers.isInputOverHitboxPreview = function(position)
    local preview = S.hitboxPreview
    local card = preview and preview.card or S.hitboxPreviewCard
    if not card or not card.Parent or not card.Visible then return false end

    local pointer = position
    if not pointer then
        local ok, mousePosition = pcall(function()
            return S.UserInputService:GetMouseLocation()
        end)
        if not ok or not mousePosition then return false end
        pointer = mousePosition
    end

    local function contains(guiObject)
        if not guiObject or not guiObject.Parent then return false end
        local topLeft = guiObject.AbsolutePosition
        local size = guiObject.AbsoluteSize
        return pointer.X >= topLeft.X and pointer.X <= topLeft.X + size.X
            and pointer.Y >= topLeft.Y and pointer.Y <= topLeft.Y + size.Y
    end

    -- Hitbox Preview is inside the page ScrollingFrame; ignore its off-screen
    -- clipped area so it cannot unexpectedly block dragging elsewhere.
    if S.contentFrame and S.contentFrame:IsA("ScrollingFrame")
        and not contains(S.contentFrame) then
        return false
    end
    return contains(card)
end

S.__helpers.updateDrag = function(input)
    if not S.dragStart or not S.startPos then return end
    if S.__helpers.isInputOverHitboxPreview
        and S.__helpers.isInputOverHitboxPreview(input.Position) then
        S.dragging = false
        S.dragInput = nil
        return
    end

    local delta = input.Position - S.dragStart

    S.mainFrame.Position = UDim2.new(
        S.startPos.X.Scale,
        S.startPos.X.Offset + delta.X,
        S.startPos.Y.Scale,
        S.startPos.Y.Offset + delta.Y
    )
end

S.__helpers.connect(S.mainFrame.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then

        if S.__helpers.isInputOverResizeHandle(input.Position) then return end
        if S.__helpers.isInputOverHitboxPreview
            and S.__helpers.isInputOverHitboxPreview(input.Position) then
            S.dragging = false
            S.dragInput = nil
            return
        end
        S.dragging = true
        S.dragStart = input.Position
        S.startPos = S.mainFrame.Position

        S.__helpers.connect(input.Changed, function()
            if input.UserInputState == Enum.UserInputState.End then
                S.dragging = false
            end
        end)
    end
end)

S.__helpers.connect(S.mainFrame.InputChanged, function(input)
    if S.isResizingMainFrame then return end
    if input.UserInputType == Enum.UserInputType.MouseMovement
        or input.UserInputType == Enum.UserInputType.Touch then
        if S.__helpers.isInputOverResizeHandle(input.Position) then return end
        S.dragInput = input
    end
end)

S.__helpers.connect(S.UserInputService.InputChanged, function(input)
    if S.isResizingMainFrame then
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            S.__helpers.updateMainFrameResize(input)
        end
        return
    end
    if input == S.dragInput and S.dragging then
        S.__helpers.updateDrag(input)
    end
end)

S.__helpers.connect(S.UserInputService.InputEnded, function(input)
    if not S.isResizingMainFrame then return end
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        S.isResizingMainFrame = false
        S.resizeDragStartPosition = nil
        S.resizeStartSize = nil
        S.dragging = false
        S.__helpers.setResizeHandleHover(S.__helpers.isInputOverResizeHandle(S.UserInputService:GetMouseLocation()))
    end
end)

-- ================================================================
-- PART 4: UI PARTS CREATION HELPER FUNCTIONS
-- ================================================================
-- ================================================================
-- TEXT-ART HIDE BUTTON
-- Hideボタンは画像を使わず、文字・記号の猫アートで描画します。
-- ================================================================
S.__helpers.hexToBytes = function(hex)
    hex = tostring(hex):gsub("%s", "")
    local out = {}
    for i = 1, #hex, 2 do
        out[#out + 1] = string.char(tonumber(hex:sub(i, i + 1), 16))
    end
    return table.concat(out)
end

-- Shared emblem image used by every script-created ImageLabel.
-- The image bytes are embedded so the script does not depend on an external file.
-- All image assets created by E1LU4HUB are stored together in this folder.
S.UI_ASSET_FOLDER = "E1LU4HUB"
S.__helpers.ensureUIAssetFolder = function()
    local folder = S.UI_ASSET_FOLDER
    if type(isfolder) == "function" then
        local ok, exists = pcall(isfolder, folder)
        if ok and exists == true then return true end
    end
    if type(makefolder) == "function" then
        pcall(makefolder, folder)
    end
    if type(isfolder) == "function" then
        local ok, exists = pcall(isfolder, folder)
        if ok and exists == true then return true end
    end
    -- A number of executors do not expose isfolder; let writefile validate the path.
    return type(makefolder) == "function"
end
S.__helpers.removeLegacyRootImage = function(oldPath, newPath)
    if type(isfile) ~= "function" or type(delfile) ~= "function" then return end
    local oldOK, oldExists = pcall(isfile, oldPath)
    local newOK, newExists = pcall(isfile, newPath)
    if oldOK and oldExists == true and newOK and newExists == true then
        pcall(delfile, oldPath)
    end
end

