S.autoBlockButtonImageUris = nil
S.__helpers.getAutoBlockButtonImage = function(enabled)
    if not S.autoBlockButtonImageUris then
        S.__helpers.ensureUIAssetFolder()
        local files = {
            on = {S.AUTO_BLOCK_ON_IMAGE_FILE, S.AUTO_BLOCK_ON_IMAGE_HEX},
            off = {S.AUTO_BLOCK_OFF_IMAGE_FILE, S.AUTO_BLOCK_OFF_IMAGE_HEX},
        }
        local uris = {on = "", off = ""}
        for key, item in pairs(files) do
            local path, imageHex = item[1], item[2]
            if type(writefile) == "function" then
                pcall(function()
                    writefile(path, S.__helpers.hexToBytes(imageHex))
                end)
            end
            local asset = ""
            pcall(function()
                if type(getcustomasset) == "function" then
                    asset = getcustomasset(path)
                elseif type(getsynasset) == "function" then
                    asset = getsynasset(path)
                end
            end)
            if type(asset) == "string" then uris[key] = asset end
        end
        S.autoBlockButtonImageUris = uris
    end
    local key = enabled == true and "on" or "off"
    return S.autoBlockButtonImageUris[key] or ""
end

S.ensureEmbeddedUIImageFile = function()
    S.__helpers.ensureUIAssetFolder()
    if type(writefile) ~= "function" then
        return false
    end
    local ok = pcall(function()
        writefile(S.UI_IMAGE_FILE, S.__helpers.hexToBytes(S.UI_IMAGE_HEX))
    end)
    if ok then
        S.__helpers.removeLegacyRootImage("E1LU4HUB_emblem.png", S.UI_IMAGE_FILE)
        S.__helpers.removeLegacyRootImage("OWERE1LU4_emblem.png", S.UI_IMAGE_FILE)
    end
    return ok
end

S.ensureEmbeddedResizeHandleFile = function()
    S.__helpers.ensureUIAssetFolder()
    if type(writefile) ~= "function" then return false end
    local ok = pcall(function()
        writefile(S.RESIZE_HANDLE_IMAGE_FILE, S.__helpers.hexToBytes(S.RESIZE_HANDLE_IMAGE_HEX))
    end)
    if ok then
        S.__helpers.removeLegacyRootImage("ResizeHandle.png", S.RESIZE_HANDLE_IMAGE_FILE)
    end
    return ok
end

S.__helpers.getEmbeddedUIImage = function()
    S.ensureEmbeddedUIImageFile()
    local imageUri = ""
    pcall(function()
        if type(getcustomasset) == "function" then
            imageUri = getcustomasset(S.UI_IMAGE_FILE)
        elseif type(getsynasset) == "function" then
            imageUri = getsynasset(S.UI_IMAGE_FILE)
        end
    end)
    return imageUri or ""
end

S.__helpers.getEmbeddedResizeHandleImage = function()
    S.ensureEmbeddedResizeHandleFile()
    local imageUri = ""
    pcall(function()
        if type(getcustomasset) == "function" then
            imageUri = getcustomasset(S.RESIZE_HANDLE_IMAGE_FILE)
        elseif type(getsynasset) == "function" then
            imageUri = getsynasset(S.RESIZE_HANDLE_IMAGE_FILE)
        end
    end)
    return imageUri or ""
end

-- Resolve the title-bar emblem after the embedded image helper is initialized.
if S.titleIconLabel and S.titleIconLabel:IsA("ImageLabel") then
    S.titleIconLabel.Image = S.__helpers.getEmbeddedUIImage()
end

-- Create/overwrite the new asset immediately so image overlays can use it too.
S.ensureEmbeddedUIImageFile()

-- UI accent color: 初期設定は白。UI COLORから一括変更。
S.uiAccentColors = {
    Color3.fromRGB(170, 80, 255),
    Color3.fromRGB(70, 130, 255),
    Color3.fromRGB(255, 80, 170),
    Color3.fromRGB(80, 210, 120),
    Color3.fromRGB(255, 165, 60),
    Color3.fromRGB(255, 255, 255),
    Color3.fromRGB(70, 220, 220),
}
S.uiAccentColorIndex = 6
S.uiAccentColor = S.uiAccentColors[S.uiAccentColorIndex]
S.uiToggleBoxes = {}
S.configToggleRegistry = S.configToggleRegistry or {}
S.configNumericRegistry = S.configNumericRegistry or {}
S.configDropdownRegistry = S.configDropdownRegistry or {}
S.configColorRegistry = S.configColorRegistry or {}
S.__helpers.applyUIAccentColor = function()
    S.uiAccentColor = S.uiAccentColors[S.uiAccentColorIndex]

    if S.titleLabel then
        S.titleLabel.TextColor3 = S.uiAccentColor
    end
    -- The restore button keeps the main UI's dark fill; only its outline follows UI COLOR.
    if S.minimizedRestoreStroke and S.minimizedRestoreStroke.Parent then
        S.minimizedRestoreStroke.Color = S.uiAccentColor
    end

    for _, box in ipairs(S.uiToggleBoxes) do
        if box and box.Parent then
            local state = box.Parent:GetAttribute("ToggleState")
            box.BackgroundColor3 = state and S.uiAccentColor or Color3.fromRGB(48, 47, 56)
        end
    end

    -- Sidebar mode reparents controls from the hidden legacy content frame
    -- into per-category pages. Scan the full main frame so every slider fill
    -- updates immediately when UI COLOR changes, regardless of its page.
    local accentRoot = S.screenGui or S.mainFrame or S.contentFrame
    if accentRoot then
        for _, obj in ipairs(accentRoot:GetDescendants()) do
            if obj:IsA("TextLabel") and (obj.Name == "SectionHeader" or obj.Name == "FoldoutLabel" or obj.Name == "LMSStatusLabel" or obj.Name == "CurrentPageHeading") then
                obj.TextColor3 = S.uiAccentColor
            elseif obj:IsA("TextButton") and obj.Name:sub(1, 4) == "Nav_" then
                obj.TextColor3 = obj:GetAttribute("Selected") and S.uiAccentColor or Color3.fromRGB(160, 158, 168)
            elseif obj:IsA("ImageLabel") and obj.Name == "NavIcon" then
                local navParent = obj.Parent
                local isSelected = navParent and navParent:GetAttribute("Selected") == true
                local iconColor = isSelected and S.uiAccentColor or Color3.fromRGB(170, 168, 178)
                obj.ImageColor3 = iconColor
                for _, iconChild in ipairs(obj:GetChildren()) do
                    if iconChild:IsA("Frame") and iconChild.Name == "NavIconStroke" then
                        iconChild.BackgroundColor3 = iconColor
                    end
                end
            elseif obj:IsA("ImageButton") and obj.Name == "ResizeHandleIcon" then
                obj.ImageColor3 = S.resizeHandleHovered and S.uiAccentColor or Color3.fromRGB(170, 168, 178)
            elseif obj:IsA("TextLabel") and obj.Name == "NavTitle" then
                local navParent = obj.Parent
                local isSelected = navParent and navParent:GetAttribute("Selected") == true
                obj.TextColor3 = isSelected and Color3.fromRGB(246, 245, 250) or Color3.fromRGB(211, 209, 219)
            elseif obj:IsA("Frame") and obj.Name == "NavSelectedIndicator" then
                obj.BackgroundColor3 = S.uiAccentColor
                obj.Visible = obj.Parent and obj.Parent:GetAttribute("Selected") == true
            elseif obj:IsA("Frame") and obj.Name == "SliderFill" then
                obj.BackgroundColor3 = S.uiAccentColor
            elseif obj:IsA("ScrollingFrame") and obj.Name == "CategoryButtons" then
                obj.ScrollBarImageColor3 = S.uiAccentColor
            elseif obj:IsA("GuiObject") and obj:GetAttribute("SkinChangerAccentFill") == true then
                obj.BackgroundColor3 = S.uiAccentColor
            elseif (obj:IsA("TextLabel") or obj:IsA("TextButton"))
                and obj:GetAttribute("SkinChangerAccentText") == true then
                obj.TextColor3 = S.uiAccentColor
            elseif obj:IsA("UIStroke") and obj:GetAttribute("SkinChangerAccentStroke") == true then
                obj.Color = S.uiAccentColor
            elseif obj:IsA("UIStroke") and (obj.Parent and obj.Parent.Name == "UIColorButton") then
                obj.Color = S.uiAccentColor
            end
        end
    end

    -- Keep the independent PC keybind panel visually synchronized with E1LU4HUB UI COLOR.
    if S.keybindPanel and S.keybindPanel.Parent then
        S.keybindPanel.BackgroundColor3 = (S.mainFrame and S.mainFrame.BackgroundColor3) or Color3.fromRGB(26, 25, 30)
        S.keybindPanel.BackgroundTransparency = (S.mainFrame and tonumber(S.mainFrame.BackgroundTransparency)) or 0.12
        if S.keybindPanelStroke then S.keybindPanelStroke.Color = S.uiAccentColor end
        if S.keybindPanelDivider then S.keybindPanelDivider.BackgroundColor3 = S.uiAccentColor end
        if S.keybindPanelTitle then S.keybindPanelTitle.TextColor3 = S.uiAccentColor end
        if S.keybindRowsContainer then
            for _, row in ipairs(S.keybindRowsContainer:GetChildren()) do
                local keyLabel = row:FindFirstChild("KeyName")
                if keyLabel and keyLabel:IsA("TextLabel") then
                    keyLabel.TextColor3 = S.uiAccentColor
                end
            end
        end
    end

    -- Keep the ESP picker visually on the same surface and accent palette as the hub.
    local pickerApi = S.espColorPickerUI
    local pickerFrame = pickerApi and pickerApi.frame
    if pickerFrame and pickerFrame.Parent then
        pickerFrame.BackgroundColor3 = (S.mainFrame and S.mainFrame.BackgroundColor3) or Color3.fromRGB(26, 25, 30)
        pickerFrame.BackgroundTransparency = (S.mainFrame and S.mainFrame.BackgroundTransparency) or 0.12
        local pickerTitle = pickerFrame:FindFirstChild("PickerTitle")
        if pickerTitle then pickerTitle.TextColor3 = S.uiAccentColor end
        local hueMarker = pickerFrame:FindFirstChild("HueStrip") and pickerFrame.HueStrip:FindFirstChild("HueMarker")
        if hueMarker then hueMarker.BackgroundColor3 = S.uiAccentColor end
        local selectedMarker = pickerFrame:FindFirstChild("SaturationValue")
            and pickerFrame.SaturationValue:FindFirstChild("SelectedColorMarker")
        local selectedMarkerStroke = selectedMarker and selectedMarker:FindFirstChildOfClass("UIStroke")
        if selectedMarkerStroke then selectedMarkerStroke.Color = S.uiAccentColor end
    end

    -- Toast fill follows the E1LU4HUB window background and transparency.
    -- The thin outline and countdown bar use UI COLOR; Save Config keeps its green icon.
    for _, toastState in ipairs(S.notificationToasts or {}) do
        if toastState.frame and toastState.frame.Parent then
            toastState.frame.BackgroundColor3 = (S.mainFrame and S.mainFrame.BackgroundColor3) or S.NOTIFICATION_DEFAULT_COLOR
            toastState.frame.BackgroundTransparency = (S.mainFrame and tonumber(S.mainFrame.BackgroundTransparency)) or 0.12
            local toastAccent = toastState.accentOverride or S.uiAccentColor or S.NOTIFICATION_DEFAULT_COLOR
            if toastState.stroke then toastState.stroke.Color = toastAccent end
            if toastState.progress then toastState.progress.BackgroundColor3 = toastAccent end
            if toastState.body then
                toastState.body.TextColor3 = toastState.accentOverride or Color3.fromRGB(184, 157, 177)
            end
            local iconAccent = toastAccent
            if toastState.icon then toastState.icon.ImageColor3 = iconAccent end
            if toastState.iconTile then toastState.iconTile.BackgroundColor3 = iconAccent end
            if toastState.iconTileStroke then toastState.iconTileStroke.Color = iconAccent end
            if toastState.iconBadge then toastState.iconBadge.BackgroundColor3 = iconAccent end
        end
    end

end

S.__helpers.cycleUIAccentColor = function()
    S.uiAccentColorIndex = (S.uiAccentColorIndex % #S.uiAccentColors) + 1
    S.__helpers.applyUIAccentColor()
end

S.__helpers.createCoolActionButton = function(labelText, callback)
    local button = Instance.new("TextButton")
    button.Name = "ActionButton"
    button.Size = UDim2.new(0.92, 0, 0, 32)
    button.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
    button.BorderSizePixel = 0
    button.AutoButtonColor = true
    button.Text = labelText
    button.TextColor3 = Color3.new(1, 1, 1)
    button.Font = Enum.Font.GothamBold
    button.TextSize = 11
    button.TextXAlignment = Enum.TextXAlignment.Left
    button.Parent = S.contentFrame

    local textPadding = Instance.new("UIPadding")
    textPadding.PaddingLeft = UDim.new(0, 10)
    textPadding.Parent = button

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 4)
    corner.Parent = button

    S.__helpers.connect(button.MouseButton1Click, function()
        local ok, err = pcall(callback)
        if not ok then
            warn("[ELHUB Action Button] " .. tostring(err))
            S.__helpers.notifyCategorizedControl(button, labelText or "Action", "Action failed.", 3.2)
        else
            S.__helpers.notifyCategorizedControl(button, labelText or "Action", "Action activated.", 3.2)
        end
    end)
    return button
end

S.__helpers.createCoolToggle = function(text, initialState, callback)
    local btn = Instance.new("TextButton")
    btn.Name = "Toggle"
    btn.Size = UDim2.new(0.92, 0, 0, 32)
    btn.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
    btn.BackgroundTransparency = 0 -- Feature buttons remain fully opaque.
    btn.Text = ""
    btn.AutoButtonColor = false
    btn.Parent = S.contentFrame

    local btnCorner = Instance.new("UICorner")
    btnCorner.CornerRadius = UDim.new(0, 4)
    btnCorner.Parent = btn

    -- ON/OFF表示は従来のチェック表示をそのまま維持。
    local box = Instance.new("Frame")
    box.Name = "CheckBox"
    box.Size = UDim2.new(0, 12, 0, 12)
    box.Position = UDim2.new(0, 10, 0.5, -6)
    box.BorderSizePixel = 1
    box.BorderColor3 = Color3.fromRGB(67, 65, 75)
    box.BackgroundColor3 = initialState
        and S.uiAccentColor
        or Color3.fromRGB(48, 47, 56)
    box.Parent = btn

    local boxCorner = Instance.new("UICorner")
    boxCorner.CornerRadius = UDim.new(0, 2)
    boxCorner.Parent = box

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.Size = UDim2.new(1, -36, 1, 0)
    label.Position = UDim2.new(0, 30, 0, 0)
    label.Text = text
    label.TextColor3 = Color3.new(1, 1, 1)
    label.Font = Enum.Font.GothamBold
    label.TextSize = 12
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.BackgroundTransparency = 1
    label.Parent = btn

    local state = initialState
    local requiredRole = S.activeFeatureRole
    btn:SetAttribute("ToggleState", initialState)
    table.insert(S.uiToggleBoxes, box)

    -- The toggle represents the user's saved preference, not the current role.
    -- Role-specific execution is checked by each feature's runtime handler, so
    -- the user can configure Survivor/Killer features from either role or lobby.
    local function applyToggleState(requestedState)
        local nextState = requestedState == true

        state = nextState
        btn:SetAttribute("ToggleState", state)
        box.BackgroundColor3 = state
            and S.uiAccentColor
            or Color3.fromRGB(48, 47, 56)

        if type(callback) == "function" then
            pcall(callback, state)
        end
        return state
    end

    table.insert(S.configToggleRegistry, {
        button = btn,
        box = box,
        callback = applyToggleState,
        label = text,
        requiredRole = requiredRole,
    })

    S.__helpers.connect(btn.MouseButton1Click, function()
        local newState = applyToggleState(not btn:GetAttribute("ToggleState"))
        S.__helpers.notifyCategorizedControl(
            btn,
            tostring(text or "Feature"),
            newState and "Enabled." or "Disabled.",
            3.2
        )
    end)

    return btn, box
end

S.__helpers.setCoolToggleValue = function(button, value)
    if not button then return false end
    for _, entry in ipairs(S.configToggleRegistry or {}) do
        if entry.button == button and type(entry.callback) == "function" then
            entry.callback(value == true)
            return true
        end
    end
    return false
end

S.__helpers.createNumericControl = function(labelText, defaultValue, minValue, maxValue, step, callback, parent)
    local container = Instance.new("Frame")
    container.Name = "NumericControlContainer"
    container.Size = parent and UDim2.new(1, 0, 0, 64) or UDim2.new(0.82, 0, 0, 64)
    container.BackgroundTransparency = 1
    if parent then container.LayoutOrder = #parent:GetChildren() end
    container.Parent = parent or S.contentFrame

    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(0.58, 0, 0, 22)
    lbl.Position = UDim2.new(0, 0, 0, 0)
    lbl.Text = labelText
    lbl.TextColor3 = Color3.fromRGB(175, 173, 183)
    lbl.Font = Enum.Font.Gotham
    lbl.TextSize = 11
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.BackgroundTransparency = 1
    lbl.Parent = container

    local box = Instance.new("TextBox")
    box.Name = "ValueBox"
    box.Size = UDim2.new(0, 58, 0, 22)
    box.Position = UDim2.new(1, -58, 0, 0)
    box.BackgroundColor3 = Color3.fromRGB(48, 47, 56)
    box.Text = tostring(defaultValue)
    box.TextColor3 = Color3.new(1, 1, 1)
    box.Font = Enum.Font.Gotham
    box.TextSize = 11
    box.ClearTextOnFocus = false
    box.Parent = container

    local boxCorner = Instance.new("UICorner")
    boxCorner.CornerRadius = UDim.new(0, 3)
    boxCorner.Parent = box

    local bg = Instance.new("Frame")
    bg.Name = "SliderBackground"
    bg.Size = UDim2.new(1, 0, 0, 6)
    bg.Position = UDim2.new(0, 0, 0, 34)
    bg.BackgroundColor3 = Color3.fromRGB(48, 47, 56)
    bg.BorderSizePixel = 0
    bg.Active = true
    bg.Parent = container

    local bgCorner = Instance.new("UICorner")
    bgCorner.CornerRadius = UDim.new(0, 3)
    bgCorner.Parent = bg

    local fill = Instance.new("Frame")
    fill.Name = "SliderFill"
    fill.BackgroundColor3 = S.uiAccentColor
    fill.BorderSizePixel = 0
    fill.Parent = bg

    local fillCorner = Instance.new("UICorner")
    fillCorner.CornerRadius = UDim.new(0, 3)
    fillCorner.Parent = fill

    local function formatValue(value)
        if step and step < 1 then
            local decimals = 0
            local temp = step
            while temp < 1 and decimals < 6 do
                temp = temp * 10
                decimals = decimals + 1
            end
            return string.format("%." .. decimals .. "f", value)
        end
        return tostring(math.floor(value + 0.5))
    end

    -- Manual TextBox input may go beyond the slider's visual min/max.
    -- Dragging the slider itself remains bounded by minValue/maxValue.
    local function setValue(value, allowOutOfRange)
        value = tonumber(value)
        if not value or value ~= value or value == math.huge or value == -math.huge then
            value = defaultValue
        end

        if not allowOutOfRange then
            value = math.clamp(value, minValue, maxValue)
        end

        if step and step > 0 then
            value = minValue + math.floor(((value - minValue) / step) + 0.5) * step
            if not allowOutOfRange then
                value = math.clamp(value, minValue, maxValue)
            end
        end

        local ratio = 0
        if maxValue > minValue then
            ratio = (value - minValue) / (maxValue - minValue)
        end
        -- The thumb/fill can only be drawn within the slider, but the actual
        -- value sent to the feature callback is not capped for typed input.
        ratio = math.clamp(ratio, 0, 1)

        fill.Size = UDim2.new(ratio, 0, 1, 0)
        box.Text = formatValue(value)
        local appliedValue = callback(value)
        -- A callback may return a stricter effective value (for example, a
        -- game property with its own hard limit). Keep the text/fill truthful.
        if type(appliedValue) == "number" and appliedValue == appliedValue
            and appliedValue ~= math.huge and appliedValue ~= -math.huge then
            box.Text = formatValue(appliedValue)
            local appliedRatio = 0
            if maxValue > minValue then
                appliedRatio = (appliedValue - minValue) / (maxValue - minValue)
            end
            fill.Size = UDim2.new(math.clamp(appliedRatio, 0, 1), 0, 1, 0)
        end
    end

    local function updateFromInput(input)
        if bg.AbsoluteSize.X <= 0 then return end

        local ratio = math.clamp(
            (input.Position.X - bg.AbsolutePosition.X) / bg.AbsoluteSize.X,
            0,
            1
        )

        local value = minValue + ratio * (maxValue - minValue)
        setValue(value)
    end

    S.__helpers.connect(box.FocusLost, function()
        local value = tonumber(box.Text)
        if value then
            setValue(value, true)
        else
            setValue(defaultValue)
        end
        -- Numeric edits intentionally do not raise toast notifications.
    end)

    local sliding = false

    S.__helpers.connect(bg.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            sliding = true
            updateFromInput(input)
        end
    end)

    S.__helpers.connect(S.UserInputService.InputChanged, function(input)
        if not sliding then return end

        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            updateFromInput(input)
        end
    end)

    S.__helpers.connect(S.UserInputService.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            local wasSliding = sliding
            sliding = false
            -- Numeric slider edits intentionally do not raise toast notifications.
        end
    end)

    setValue(defaultValue)
    table.insert(S.configNumericRegistry, {
        container = container,
        box = box,
        label = labelText,
        setValue = setValue,
        getValue = function() return tonumber(box.Text) or defaultValue end,
    })
    return container, box
end

-- Per-ESP color picker matching the compact HSV picker reference:
-- saturation/value square, vertical hue rail, HEX/RGB fields, and clipboard buttons.
S.__helpers.getCharacter = function()
    return S.lp.Character or S.lp.CharacterAdded:Wait()
end

S.__helpers.getKillerFolder = function()
    local playersFolder = workspace:FindFirstChild("Players")
    return playersFolder and playersFolder:FindFirstChild("Killers")
end

S.getFirstValidKillerModel = function()
    local killerFolder = S.__helpers.getKillerFolder()
    if not killerFolder then return nil end

    for _, inst in ipairs(killerFolder:GetChildren()) do
        if inst:IsA("Model") then
            local hum = inst:FindFirstChildOfClass("Humanoid")
            local hrp = inst:FindFirstChild("HumanoidRootPart")

            if hum and hrp and hum.Health > 0 then
                return inst
            end
        end
    end

    return nil
end

-- ================================================================
-- AUTO BLOCK RANGE ESP
-- The Auto Block range is drawn as an outline-only ground ring around the
-- nearest living killer. Facing Check adds its own outline-only vision cone.
-- ================================================================
S.__helpers.getRangeESPFolder = function()
    -- Keep exactly one shared root folder. Older script executions may have
    -- left an untracked ESP folder behind, which otherwise looks like a second
    -- Auto Block Range ESP after the next toggle/update.
    local rootFolder = S.__helpers.getWorldRootFolder()
    local folder = nil
    for _, child in ipairs(rootFolder:GetChildren()) do
        if child.Name == S.RANGE_ESP_FOLDER_NAME then
            if child:IsA("Folder") and not folder then
                folder = child
            else
                pcall(function() child:Destroy() end)
            end
        end
    end
    if not folder then
        folder = Instance.new("Folder")
        folder.Name = S.RANGE_ESP_FOLDER_NAME
        folder.Parent = rootFolder
    end
    for _, child in ipairs(folder:GetChildren()) do
        if child.Name == "HitboxDragRangeESP_Outline" then
            pcall(function() child:Destroy() end)
        end
    end
    return folder
end

S.__helpers.destroyRangeESPVisual = function(kind)
    local record = S.rangeESPParts and S.rangeESPParts[kind]
    if record and record.folder then
        pcall(function() record.folder:Destroy() end)
    end
    if S.rangeESPParts then S.rangeESPParts[kind] = nil end
end

S.__helpers.makeRangeESPLine = function(parent, name, color, thickness, transparency)
    local line = Instance.new("Part")
    line.Name = name
    line.Anchored = true
    line.CanCollide = false
    line.CanTouch = false
    line.CanQuery = false
    line.CastShadow = false
    line.Material = Enum.Material.Neon
    line.Color = color
    line.Transparency = transparency or 0.08
    line.Size = Vector3.new(thickness, thickness, 1)
    line.Parent = parent
    return line
end

S.__helpers.placeRangeESPLine = function(line, fromPoint, toPoint, color, thickness, transparency)
    local delta = toPoint - fromPoint
    line.Color = color
    line.Transparency = transparency or 0.08
    line.Size = Vector3.new(thickness, thickness, math.max(0.05, delta.Magnitude))
    line.CFrame = CFrame.lookAt((fromPoint + toPoint) * 0.5, toPoint, Vector3.new(0, 1, 0))
end

S.__helpers.ensureRangeESPCircle = function(kind)
    kind = kind or "autoBlock"
    if kind ~= "autoBlock" then return nil end
    local record = S.rangeESPParts[kind]
    if record and record.folder and record.folder.Parent and #record.lines == 48 then
        return record
    end
    S.__helpers.destroyRangeESPVisual(kind)
    local rootFolder = S.__helpers.getRangeESPFolder()
    local folderName = "AutoBlockRangeESP_Outline"
    -- Remove orphaned copies from earlier script runs before making a new ring.
    for _, child in ipairs(rootFolder:GetChildren()) do
        if child.Name == folderName then
            pcall(function() child:Destroy() end)
        end
    end
    local folder = Instance.new("Folder")
    folder.Name = folderName
    folder.Parent = rootFolder
    record = {folder = folder, lines = {}}
    for index = 1, 48 do
        record.lines[index] = S.__helpers.makeRangeESPLine(
            folder, "RangeLine" .. tostring(index), Color3.fromRGB(255, 0, 0), 0.11, 0.08
        )
    end
    S.rangeESPParts[kind] = record
    return record
end

S.__helpers.ensureFacingCheckESP = function()
    local record = S.rangeESPParts.facingCheck
    if record and record.folder and record.folder.Parent
        and #record.lines == 4 and #record.markers == 3
        and record.closeRangeFill and record.closeRangeFill.Parent then
        return record
    end
    S.__helpers.destroyRangeESPVisual("facingCheck")
    local rootFolder = S.__helpers.getRangeESPFolder()
    -- Prevent duplicate vision-cone folders left by a previous execution.
    for _, child in ipairs(rootFolder:GetChildren()) do
        if child.Name == "FacingCheckVisionConeESP" then
            pcall(function() child:Destroy() end)
        end
    end
    local folder = Instance.new("Folder")
    folder.Name = "FacingCheckVisionConeESP"
    folder.Parent = rootFolder
    record = {folder = folder, lines = {}, markers = {}, closeRangeFill = nil}

    -- Keep the close-range indicator circular (radius 3 studs / diameter 6).
    -- Its CFrame is refreshed from the current killer root every rendered frame.
    local closeRangeFill = Instance.new("Part")
    closeRangeFill.Name = "FacingCheckCloseRangeFill"
    closeRangeFill.Shape = Enum.PartType.Cylinder
    closeRangeFill.Size = Vector3.new(0.1, 6, 6)
    closeRangeFill.Anchored = true
    closeRangeFill.CanCollide = false
    closeRangeFill.CanTouch = false
    closeRangeFill.CanQuery = false
    closeRangeFill.CastShadow = false
    closeRangeFill.Material = Enum.Material.Neon
    closeRangeFill.Color = Color3.fromRGB(255, 0, 0)
    closeRangeFill.Transparency = 0.3
    closeRangeFill.Parent = folder
    record.closeRangeFill = closeRangeFill

    for index = 1, 4 do
        record.lines[index] = S.__helpers.makeRangeESPLine(
            folder, "VisionLine" .. tostring(index), Color3.fromRGB(255, 0, 0), 0.1, 0.3
        )
    end
    for index = 1, 3 do
        local marker = Instance.new("Part")
        marker.Name = "VisionPoint" .. tostring(index)
        marker.Shape = Enum.PartType.Ball
        marker.Size = Vector3.new(1, 1, 1)
        marker.Anchored = true
        marker.CanCollide = false
        marker.CanTouch = false
        marker.CanQuery = false
        marker.CastShadow = false
        marker.Transparency = 0.5
        marker.Color = Color3.fromRGB(255, 0, 0)
        marker.Parent = folder
        record.markers[index] = marker
    end
    S.rangeESPParts.facingCheck = record
    return record
end

S.__helpers.updateRangeESP = function()
    if not S.__helpers.isLocalRole("Survivor") then
        S.__helpers.destroyRangeESPVisual("autoBlock")
        S.__helpers.destroyRangeESPVisual("facingCheck")
        return
    end

    local localRoot = S.__helpers.getMyRoot()
    local killerFolder = S.__helpers.getKillerFolder()
    if not localRoot or not localRoot.Parent or not killerFolder then
        S.__helpers.destroyRangeESPVisual("autoBlock")
        S.__helpers.destroyRangeESPVisual("facingCheck")
        return
    end

    local closestRoot, closestDistance = nil, math.huge
    for _, killer in ipairs(killerFolder:GetChildren()) do
        if killer:IsA("Model") then
            local humanoid = killer:FindFirstChildOfClass("Humanoid")
            local root = killer:FindFirstChild("HumanoidRootPart")
            if humanoid and humanoid.Health > 0 and root then
                local offset = root.Position - localRoot.Position
                local distance = Vector3.new(offset.X, 0, offset.Z).Magnitude
                if distance < closestDistance then
                    closestRoot, closestDistance = root, distance
                end
            end
        end
    end

    if not closestRoot or not closestRoot.Parent then
        S.__helpers.destroyRangeESPVisual("autoBlock")
        S.__helpers.destroyRangeESPVisual("facingCheck")
        return
    end

    local origin = closestRoot.Position - Vector3.new(0, 2.5, 0)
    local function drawCircle(kind, range, color)
        local record = S.__helpers.ensureRangeESPCircle(kind)
        for index = 1, 48 do
            local angleA = ((index - 1) / 48) * math.pi * 2
            local angleB = (index / 48) * math.pi * 2
            local fromPoint = origin + Vector3.new(math.cos(angleA) * range, 0, math.sin(angleA) * range)
            local toPoint = origin + Vector3.new(math.cos(angleB) * range, 0, math.sin(angleB) * range)
            S.__helpers.placeRangeESPLine(record.lines[index], fromPoint, toPoint, color, 0.11, 0.08)
        end
    end

    -- The Facing Check cone replaces the normal Auto Block ring while enabled.
    -- Drawing both at once made the Auto Block Range ESP appear doubled.
    if S.isAutoBlockRangeESPEnabled and not S.isFacingCheckEnabled then
        local range = math.max(0.1, tonumber(S.autoBlockDetectionRange) or 16)
        local color = closestDistance <= range and Color3.fromRGB(0, 255, 80) or Color3.fromRGB(255, 0, 0)
        drawCircle("autoBlock", range, color)
    else
        S.__helpers.destroyRangeESPVisual("autoBlock")
    end

    if not S.isAutoBlockRangeESPEnabled or not S.isFacingCheckEnabled then
        S.__helpers.destroyRangeESPVisual("facingCheck")
        return
    end

    local visionRange = math.max(0.1, tonumber(S.facingCheckESPRange) or 16)
    local halfAngle = S.__helpers.getFacingCheckHalfAngle()
    local localOffset = localRoot.Position - closestRoot.Position
    local closeDistance = Vector3.new(localOffset.X, 0, localOffset.Z).Magnitude
    local insideCloseRange = closeDistance <= (tonumber(S.AUTO_BLOCK_CLOSE_RANGE) or 4)
    local insideCone = S.isKillerFacingTarget(closestRoot, localRoot, visionRange)
    -- When the 4-stud disc is green, the whole cone turns green as well.
    local coneIsGreen = insideCone or insideCloseRange
    local coneColor = coneIsGreen and Color3.fromRGB(0, 255, 80) or Color3.fromRGB(255, 0, 0)
    local cone = S.__helpers.ensureFacingCheckESP()
    local coneColorFill = coneIsGreen
        and Color3.fromRGB(0, 255, 80) or Color3.fromRGB(255, 0, 0)
    local look3D = closestRoot.CFrame.LookVector
    local look = Vector3.new(look3D.X, 0, look3D.Z)
    if look.Magnitude < 0.001 then look = Vector3.new(0, 0, -1) else look = look.Unit end
    local side = Vector3.new(-look.Z, 0, look.X)
    local originCone = origin

    -- Keep this close-range indicator as a full 3-stud-radius circle.
    -- Updating its CFrame every RenderStepped keeps it centered on the killer
    -- while the killer moves or turns; it is not a sector or a world-space leftover.
    cone.closeRangeFill.Color = coneColorFill
    cone.closeRangeFill.Transparency = 0.3
    cone.closeRangeFill.Material = Enum.Material.Neon
    cone.closeRangeFill.CFrame = CFrame.new(originCone + Vector3.new(0, 0.04, 0))
        * CFrame.Angles(0, 0, math.rad(90))

    local forwardOffset = look * math.cos(halfAngle)
    local sideOffset = side * math.sin(halfAngle)
    local centerPoint = originCone + look * visionRange
    local leftPoint = originCone + (forwardOffset + sideOffset).Unit * visionRange
    local rightPoint = originCone + (forwardOffset - sideOffset).Unit * visionRange
    local points = {centerPoint, leftPoint, rightPoint}
    for index, point in ipairs(points) do
        local marker = cone.markers[index]
        marker.Position = point
        marker.Color = coneColor
    end
    local endpoints = {
        {originCone, leftPoint}, {originCone, rightPoint},
        {leftPoint, centerPoint}, {centerPoint, rightPoint},
    }
    for index, pair in ipairs(endpoints) do
        S.__helpers.placeRangeESPLine(cone.lines[index], pair[1], pair[2], coneColor, 0.1, 0.3)
    end
end

-- Update the world-space ESP every rendered frame. This keeps the circular
-- close-range indicator and facing-check lines locked to the killer while moving.
S.__helpers.connect(S.RunService.RenderStepped, function()
    S.__helpers.updateRangeESP()
end)

-- ================================================================
-- ================================================================
-- AUTO GENERATOR runtime and UI are installed in the Automation page below.

-- VERSION 1 KEYBIND HELPER
-- ================================================================
S.__helpers.createKeybind = function(
    labelText,
    defaultKey,
    callback
)
    local container =
        Instance.new("Frame")

    container.Name =
        "KeybindContainer"

    container.Size =
        UDim2.new(0.92, 0, 0, 32)

    container.BackgroundTransparency = 1
    container.Parent = S.contentFrame

    local lbl =
        Instance.new("TextLabel")

    lbl.Size =
        UDim2.new(0.62, 0, 1, 0)

    lbl.Text = labelText

    lbl.TextColor3 =
        Color3.fromRGB(
            175,
            173,
            183
        )

    lbl.Font =
        Enum.Font.Gotham

    lbl.TextSize = 11

    lbl.TextXAlignment =
        Enum.TextXAlignment.Left

    lbl.BackgroundTransparency = 1

    lbl.Parent = container

    local button =
        Instance.new("TextButton")

    button.Name =
        "KeyButton"

    button.Size =
        UDim2.new(0, 70, 0, 22)

    button.Position =
        UDim2.new(
            1,
            -70,
            0.5,
            -11
        )

    button.BackgroundColor3 =
        Color3.fromRGB(
            36,
            35,
            42
        )

    local currentKey =
        S.__helpers.normalizeKeyName(
            defaultKey
        )

    if not currentKey then
        currentKey = "NONE"
    end

    button.Text =
        S.__helpers.getKeyDisplayName(
            currentKey
        )

    button.TextColor3 =
        Color3.new(1, 1, 1)

    button.Font =
        Enum.Font.GothamBold

    button.TextSize = 11

    button.AutoButtonColor = false

    button.Parent = container

    local corner =
        Instance.new("UICorner")

    corner.CornerRadius =
        UDim.new(0, 3)

    corner.Parent = button

    local listening = false
    local keyConnection = nil

    -- ============================================================
    -- キー待機を完全終了
    -- ============================================================

    local function stopListening()
        listening = false
        container:SetAttribute("Listening", false)

        if keyConnection then
            pcall(function()
                keyConnection:Disconnect()
            end)

            keyConnection = nil
        end
    end

    local function finishListening(value)
        if not listening then
            return
        end

        local normalized =
            S.__helpers.normalizeKeyName(
                value
            )

        if not normalized then
            return
        end

        -- P is reserved exclusively for hiding/showing the UI and keybind list.
        -- Never allow it to become a feature key or appear in the keybind panel.
        if tostring(normalized):upper() == "P" then
            stopListening()
            button.Text = S.__helpers.getKeyDisplayName(currentKey)
            if S.__helpers.notify then
                S.__helpers.notify("Keybind", "P is reserved for the UI hide/show shortcut.", 3)
            end
            return
        end

        stopListening()

        currentKey =
            normalized

        button.Text =
            S.__helpers.getKeyDisplayName(
                currentKey
            )

        if callback then
            callback(currentKey)
        end
    end

    S.__helpers.connect(
        button.MouseButton1Click,
        function()
            if listening then
                return
            end

            listening = true
            container:SetAttribute("Listening", true)

            button.Text = "..."

            -- 念のため既存接続を削除
            if keyConnection then
                pcall(function()
                    keyConnection:Disconnect()
                end)

                keyConnection = nil
            end

            keyConnection =
                S.UserInputService.InputBegan:Connect(
                    function(
                        input,
                        gameProcessed
                    )
                        if not listening then
                            return
                        end

                        -- ==================================================
                        -- LMB
                        -- ==================================================

                        if input.UserInputType ==
                            Enum.UserInputType.MouseButton1 then

                            finishListening(
                                "LMB"
                            )

                            return
                        end

                        -- ==================================================
                        -- RMB
                        -- ==================================================

                        if input.UserInputType ==
                            Enum.UserInputType.MouseButton2 then

                            finishListening(
                                "RMB"
                            )

                            return
                        end

                        -- ==================================================
                        -- keyboard
                        -- ==================================================

                        if input.UserInputType ==
                            Enum.UserInputType.Keyboard then

                            local keyCode =
                                input.KeyCode

                            if not keyCode
                                or keyCode ==
                                Enum.KeyCode.Unknown then

                                return
                            end

                            finishListening(
                                keyCode.Name
                            )

                            return
                        end
                    end
                )
        end
    )

    if callback then
        callback(currentKey)
    end

    return container, button
end

-- Section header helper
-- The original file calls createSectionHeader() but did not define it,
-- which caused the UI to stop at the first section with "attempt to call a nil value".
S.__helpers.createSectionHeader = function(text)
    local normalizedHeader = tostring(text or ""):upper():gsub("%s+", " ")
    normalizedHeader = normalizedHeader:gsub("^%s*(.-)%s*$", "%1")

    local survivorHeaders = {
        ["GUEST1337"] = true, ["007N7"] = true,
        ["CHANCE"] = true,
        ["ANIMATION HITBOX"] = true,
        ["SHEDLETSKY AIMBOT"] = true,
        ["VEERONICA"] = true,
        ["DUSEKKAR"] = true,
        ["ELIOT"] = true,
        ["JANE DOE"] = true,
        ["JANE DOE SURVIVOR"] = true,
        ["AUTO UNDETECT"] = true,
        ["AUTO SLASH"] = true,
        ["AUTO BLOCK / AUTO PUNCH"] = true,
        ["SURVIVOR ESP"] = true,
        ["HITBOX DRAG"] = true,
        ["AUTO PUNCH"] = true,
    }
    local killerHeaders = {
        ["SIXER"] = true,
        ["AUTO M1"] = true,
        ["AIMBOT"] = true,
        ["ANTI-BACKSTAB"] = true,
        ["AUTO DODGE"] = true,
        ["AZURE"] = true,
        ["SLASHER"] = true,
        ["C00LKIDD"] = true,
        ["NOLI"] = true,
        ["NOSFERATU"] = true,
        ["JOHN DOE"] = true,
        ["KILLER ESP"] = true,
    }
    local twoTimeHeaders = {
        ["AUTO STUDS"] = true,
        ["TWO TIME"] = true,
        ["AUTO BACKSTAB"] = true,
        ["DASH STAB"] = true,
        ["TWO TIME BACKSTAB"] = true,
        ["TWO TIME GLIDESTAB"] = true,
    }

    if survivorHeaders[normalizedHeader] or twoTimeHeaders[normalizedHeader] then
        S.activeFeatureRole = "Survivor"
    elseif killerHeaders[normalizedHeader] then
        S.activeFeatureRole = "Killer"
    else
        -- Non-role-specific sections clear the previous section's requirement.
        S.activeFeatureRole = nil
    end

    local header = Instance.new("TextLabel")
    header.Name = "SectionHeader"
    header.Size = UDim2.new(0.92, 0, 0, 24)
    header.BackgroundTransparency = 1
    header.BorderSizePixel = 0
    header.Text = text
    header.TextColor3 = S.uiAccentColor
    header.Font = Enum.Font.GothamBold
    header.TextSize = 11
    header.TextXAlignment = Enum.TextXAlignment.Left
    header.TextYAlignment = Enum.TextYAlignment.Center
    header.Parent = S.contentFrame

    return header
end

-- PART 5: PLAYER / ITEM / GENERATOR ESP SYSTEM LOGIC
-- One shared font source for Center Stamina Number and every custom ESP text.
-- Changing the Font dropdown updates this source, so all existing and future ESP
-- labels follow the same actual font as Center Stamina Number (Font + FontFace).
S.ESP_TEXT_FONT_NAME = "GothamBold"
S.espTextFontTargets = setmetatable({}, {__mode = "k"})

S.__helpers.applyESPTextFont = function(object)
    if not object or not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then
        return
    end

    -- Keep a weak registry so labels created outside the main ScreenGui can also
    -- be refreshed when the user changes the selected font.
    S.espTextFontTargets[object] = true
    local fontEnum = Enum.Font[S.ESP_TEXT_FONT_NAME or "GothamBold"] or Enum.Font.GothamBold
    pcall(function() object.Font = fontEnum end)
    pcall(function() object.FontFace = Font.fromEnum(fontEnum) end)
end

S.__helpers.setESPTextFont = function(fontName)
    local fontEnum = Enum.Font[fontName]
    if not fontEnum then return false end

    S.ESP_TEXT_FONT_NAME = fontName
    for object in pairs(S.espTextFontTargets) do
        if object and object.Parent
            and (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then
            pcall(function() object.Font = fontEnum end)
            pcall(function() object.FontFace = Font.fromEnum(fontEnum) end)
        else
            S.espTextFontTargets[object] = nil
        end
    end
    return true
end

