S.__helpers.getPlayerRole = function(player, character)
    if not player or player == S.lp or not character then
        return nil
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local killersFolder = playersFolder and playersFolder:FindFirstChild("Killers")
    local survivorsFolder = playersFolder and playersFolder:FindFirstChild("Survivors")

    local current = character
    while current and current ~= workspace do
        if killersFolder and current == killersFolder then
            return "Killer"
        end
        if survivorsFolder and current == survivorsFolder then
            return "Survivor"
        end
        current = current.Parent
    end

    local parent = character.Parent
    if parent then
        if parent.Name == "Killers" then
            return "Killer"
        elseif parent.Name == "Survivors" then
            return "Survivor"
        end
    end

    return nil
end

S.__helpers.getPlayerESPHighlightName = function(player)
    return "Player_" .. tostring(player.UserId)
end

S.playerESPEntries = S.playerESPEntries or {}

S.__helpers.getPlayerCharacterDisplayName = function(player, character)
    if not character then
        return "Loading..."
    end

    local characterValue = character:FindFirstChild("CharacterName", true)
        or character:FindFirstChild("SelectedCharacter", true)
    if characterValue and characterValue:IsA("ValueBase") then
        local value = characterValue.Value
        if typeof(value) == "Instance" then
            value = value.Name
        end
        local valueText = tostring(value)
        if valueText ~= "" then
            return valueText
        end
    end

    local attributeName = character:GetAttribute("CharacterName")
        or character:GetAttribute("SelectedCharacter")
    if type(attributeName) == "string" and attributeName ~= "" then
        return attributeName
    end

    if player and character.Name ~= player.Name
        and not character.Name:find("Player", 1, true) then
        return character.Name
    end

    return "Character"
end

