S.cooldownESPModuleCache = setmetatable({}, {__mode = "k"})

S.__helpers.requireCooldownESPModule = function(moduleScript)
    if not moduleScript or not moduleScript:IsA("ModuleScript") then
        return nil
    end
    local cached = S.cooldownESPModuleCache[moduleScript]
    if cached ~= nil then
        return cached
    end
    local ok, result = pcall(require, moduleScript)
    if ok and type(result) == "table" then
        S.cooldownESPModuleCache[moduleScript] = result
        return result
    end
    S.cooldownESPModuleCache[moduleScript] = false
    return nil
end

S.__helpers.getCooldownESPAnimationIds = function(animationTable, selectors, abilityName)
    local ids = {}
    local seen = {}
    if type(animationTable) ~= "table" then return ids end

    local function addAnimation(value)
        local animationId
        if typeof(value) == "Instance" and value:IsA("Animation") then
            animationId = value.AnimationId
        elseif type(value) == "string" or type(value) == "number" then
            animationId = tostring(value)
        end
        local digits = animationId and tostring(animationId):match("%d+")
        if digits and not seen[digits] then
            seen[digits] = true
            table.insert(ids, digits)
        end
    end

    local function addNested(value)
        if typeof(value) == "Instance" then
            addAnimation(value)
        elseif type(value) == "table" then
            for _, nested in pairs(value) do addNested(nested) end
        else
            addAnimation(value)
        end
    end

    local selectorList = type(selectors) == "table" and selectors
        or (type(selectors) == "string" and {selectors} or {})
    for _, selector in ipairs(selectorList) do
        if type(selector) == "string" then
            local value = animationTable[selector]
            if value == nil and selector:find(".", 1, true) then
                value = animationTable
                for part in selector:gmatch("[^%.]+") do
                    if type(value) == "table" then
                        value = value[part]
                    else
                        value = nil
                        break
                    end
                end
            end
            if value ~= nil then addNested(value) end
        end
    end

    -- Skin/actor animation tables sometimes store nested names rather than the
    -- exact keys. Match only relevant key names to avoid collecting unrelated IDs.
    if #ids == 0 then
        local terms = {}
        if type(abilityName) == "string" and abilityName ~= "" then
            table.insert(terms, abilityName:lower())
        end
        for _, selector in ipairs(selectorList) do
            if type(selector) == "string" and selector ~= "" then
                local selectorTerm = selector:lower():gsub(".*%.", "")
                table.insert(terms, selectorTerm)
            end
        end
        for key, value in pairs(animationTable) do
            local keyText = tostring(key):lower()
            local matches = false
            for _, term in ipairs(terms) do
                if term ~= "" and (keyText:find(term, 1, true) or term:find(keyText, 1, true)) then
                    matches = true
                    break
                end
            end
            if matches then addNested(value) end
        end
    end

    return ids
end

S.__helpers.getCooldownESPAbilities = function(character, role)
    if not character then return {} end
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    if not assets then return {} end

    local folderName = role == "Killer" and "Killers" or "Survivors"
    local actorName = tostring(character:GetAttribute("CharacterName") or character.Name)
    local actorRoot = assets:FindFirstChild(folderName)
    local actorFolder = actorRoot and actorRoot:FindFirstChild(actorName)
    local configModule = actorFolder and actorFolder:FindFirstChild("Config")
    local behaviorModule = actorFolder and actorFolder:FindFirstChild("Behavior")
    local config = S.__helpers.requireCooldownESPModule(configModule)
    local behavior = S.__helpers.requireCooldownESPModule(behaviorModule)
    if type(behavior) ~= "table" or type(behavior.Abilities) ~= "table" then
        return {}
    end

    local skinConfig
    local skinName = tostring(character:GetAttribute("SkinName") or "")
    if skinName ~= "" then
        local skins = assets:FindFirstChild("Skins")
        local skinRoleFolder = skins and skins:FindFirstChild(folderName)
        local skinActorFolder = skinRoleFolder and skinRoleFolder:FindFirstChild(actorName)
        local skinFolder = skinActorFolder and skinActorFolder:FindFirstChild(skinName)
        skinConfig = S.__helpers.requireCooldownESPModule(skinFolder and skinFolder:FindFirstChild("Config"))
    end

    local skinAnimationTable = type(skinConfig) == "table" and skinConfig.Animations or nil
    local baseAnimationTable = type(config) == "table" and config.Animations or nil
    local abilityMap = S.COOLDOWN_ESP_ABILITY_MAP[actorName]
    if not abilityMap then
        for mapName, mappedAbilities in pairs(S.COOLDOWN_ESP_ABILITY_MAP) do
            if tostring(mapName):lower() == actorName:lower() then
                abilityMap = mappedAbilities
                break
            end
        end
    end

    local result = {}
    local function addAbility(name, definition, mapped)
        if type(definition) ~= "table" then return end
        local animationSelectors = mapped and mapped.Anim or nil
        local animationIds = S.__helpers.getCooldownESPAnimationIds(
            skinAnimationTable, animationSelectors, name
        )
        if #animationIds == 0 then
            animationIds = S.__helpers.getCooldownESPAnimationIds(
                baseAnimationTable, animationSelectors, name
            )
        end
        local customTrigger = mapped and mapped.CustomTrigger or nil
        if #animationIds == 0 and not customTrigger and not (mapped and mapped.AlwaysShow) then return end

        local cooldown
        if typeof(definition.Cooldown) == "number" then
            cooldown = definition.Cooldown
        elseif type(config) == "table" then
            local cooldownKey = mapped and mapped.CooldownKey
            cooldown = (cooldownKey and tonumber(config[cooldownKey]))
                or tonumber(config[name .. "Cooldown"])
        end
        cooldown = tonumber(cooldown) or 0
        if cooldown <= 0 and not (mapped and mapped.AlwaysShow) then return end

        table.insert(result, {
            Name = tostring(name),
            Icon = tostring(definition.Icon or ""),
            Cooldown = math.max(0, cooldown),
            AnimIds = animationIds,
            CustomTrigger = customTrigger,
            AlwaysShow = mapped and mapped.AlwaysShow == true or false,
        })
    end

    if type(abilityMap) == "table" then
        for _, mapped in ipairs(abilityMap) do
            local ability = behavior.Abilities[mapped.Name]
            if ability then addAbility(mapped.Name, ability, mapped) end
        end
    else
        for name, ability in pairs(behavior.Abilities) do
            addAbility(name, ability, nil)
        end
    end

    return result
end

S.__helpers.removePlayerCooldownESP = function(entry)
    if not entry then return end
    local state = entry.cooldownESP
    if state then
        if state.animationConnection then
            pcall(function() state.animationConnection:Disconnect() end)
        end
        if state.animatorAddedConnection then
            pcall(function() state.animatorAddedConnection:Disconnect() end)
        end
        if state.billboard and state.billboard.Parent then
            pcall(function() state.billboard:Destroy() end)
        end
    end
    entry.cooldownESP = nil
end

S.__helpers.createPlayerCooldownESP = function(entry)
    if not entry or not entry.character or not entry.root then return end
    S.__helpers.removePlayerCooldownESP(entry)
    if not S.isCooldownESPEnabled then return end

    local abilities = S.__helpers.getCooldownESPAbilities(entry.character, entry.role)
    if #abilities == 0 then return end

    local billboardName = "PlayerCooldown_BB_" .. tostring(entry.player.UserId)
    local staleBillboard = entry.root:FindFirstChild(billboardName)
    if staleBillboard then staleBillboard:Destroy() end
    local billboard = Instance.new("BillboardGui")
    billboard.Name = billboardName
    billboard.Size = UDim2.new(0, math.min(300, math.max(36, #abilities * 36)), 0, 42)
    billboard.Adornee = entry.root
    billboard.AlwaysOnTop = true
    billboard.LightInfluence = 0
    billboard.MaxDistance = math.huge
    billboard.StudsOffset = Vector3.new(0, 5.2, 0)
    billboard.ZIndexBehavior = Enum.ZIndexBehavior.Global

    local container = Instance.new("Frame")
    container.Name = "AbilityContainer"
    container.Size = UDim2.new(1, 0, 1, 0)
    container.BackgroundTransparency = 1
    container.Parent = billboard

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Horizontal
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    layout.VerticalAlignment = Enum.VerticalAlignment.Center
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 2)
    layout.Parent = container

    local state = {
        billboard = billboard,
        abilities = {},
        character = entry.character,
        root = entry.root,
        humanoid = entry.humanoid,
    }

    for index, ability in ipairs(abilities) do
        local frame = Instance.new("Frame")
        frame.Name = "Ability_" .. tostring(index)
        frame.Size = UDim2.new(0, 34, 0, 40)
        frame.BackgroundTransparency = 1
        frame.LayoutOrder = index
        frame.Visible = ability.AlwaysShow == true
        frame.Parent = container

        local nameLabel = Instance.new("TextLabel")
        nameLabel.Name = "AbilityName"
        nameLabel.Size = UDim2.new(1, 0, 0, 9)
        nameLabel.BackgroundTransparency = 1
        nameLabel.Text = ability.Name
        nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
        nameLabel.TextStrokeTransparency = 0.2
        nameLabel.Font = Enum.Font.GothamBold
        nameLabel.TextSize = 7
        nameLabel.TextTruncate = Enum.TextTruncate.AtEnd
        nameLabel.Parent = frame

        local icon = Instance.new("ImageLabel")
        icon.Name = "AbilityIcon"
        icon.Size = UDim2.new(0, 22, 0, 22)
        icon.Position = UDim2.new(0.5, -11, 0, 9)
        icon.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
        icon.BackgroundTransparency = 0.25
        icon.Image = ability.Icon
        icon.ScaleType = Enum.ScaleType.Fit
        icon.Parent = frame
        local iconCorner = Instance.new("UICorner")
        iconCorner.CornerRadius = UDim.new(0, 4)
        iconCorner.Parent = icon

        local timer = Instance.new("TextLabel")
        timer.Name = "CooldownTimer"
        timer.Size = UDim2.new(1, 0, 0, 11)
        timer.Position = UDim2.new(0, 0, 1, -10)
        timer.BackgroundTransparency = 1
        timer.Text = ""
        timer.TextColor3 = Color3.fromRGB(255, 255, 255)
        timer.TextStrokeTransparency = 0
        timer.Font = Enum.Font.GothamBlack
        timer.TextSize = 10
        timer.Parent = frame

        table.insert(state.abilities, {
            name = ability.Name,
            cooldown = ability.Cooldown,
            animIds = ability.AnimIds,
            alwaysShow = ability.AlwaysShow,
            customTrigger = ability.CustomTrigger,
            lastTriggerActive = false,
            frame = frame,
            timer = timer,
            endsAt = 0,
        })
    end

    state.onAnimationPlayed = function(track)
        local animation = track and track.Animation
        local animationId = animation and tostring(animation.AnimationId or ""):match("%d+")
        if not animationId then return end
        local now = os.clock()
        for _, ability in ipairs(state.abilities) do
            if ability.cooldown > 0 and now >= ability.endsAt then
                for _, candidateId in ipairs(ability.animIds) do
                    if candidateId == animationId then
                        ability.endsAt = now + ability.cooldown
                        break
                    end
                end
            end
        end
    end

    local animator = entry.humanoid and entry.humanoid:FindFirstChildOfClass("Animator")
    if animator then
        state.animationConnection = animator.AnimationPlayed:Connect(state.onAnimationPlayed)
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            state.onAnimationPlayed(track)
        end
    elseif entry.humanoid then
        state.animatorAddedConnection = entry.humanoid.ChildAdded:Connect(function(child)
            if child:IsA("Animator") and not state.animationConnection then
                state.animationConnection = child.AnimationPlayed:Connect(state.onAnimationPlayed)
            end
        end)
    end

    billboard.Parent = entry.root
    entry.cooldownESP = state
end

S.__helpers.updatePlayerCooldownESP = function()
    if not S.isCooldownESPEnabled then return end
    local now = os.clock()
    for _, entry in pairs(S.playerESPEntries) do
        local state = entry.cooldownESP
        if state then
            for _, ability in ipairs(state.abilities) do
                if ability.customTrigger then
                    local triggerValue = state.character:GetAttribute(ability.customTrigger)
                    if triggerValue == nil then
                        local triggerObject = state.character:FindFirstChild(ability.customTrigger, true)
                        if triggerObject and triggerObject:IsA("BoolValue") then
                            triggerValue = triggerObject.Value
                        end
                    end
                    local triggerActive = triggerValue == true
                    if triggerActive and not ability.lastTriggerActive
                        and ability.cooldown > 0 and now >= ability.endsAt then
                        ability.endsAt = now + ability.cooldown
                    end
                    ability.lastTriggerActive = triggerActive
                end

                local remaining = math.max(0, ability.endsAt - now)
                if remaining > 0 then
                    ability.frame.Visible = true
                    ability.timer.Text = string.format("%.1f", remaining)
                else
                    ability.frame.Visible = ability.alwaysShow == true
                    ability.timer.Text = ""
                end
            end
        end
    end
end

S.__helpers.connect(S.RunService.RenderStepped, S.__helpers.updatePlayerCooldownESP)

-- Keep the existing BillboardGui canvas and its exact scale/offset values.
-- The attachment follows BasePart:GetRenderCFrame(), avoiding visible stepping
-- when the replicated physics CFrame and the locally rendered CFrame differ.
S.__helpers.updatePlayerESPBillboardRender = function(deltaTime)
    local dt = math.clamp(tonumber(deltaTime) or (1 / 60), 0, 0.1)
    local healthAlpha = 1 - math.exp(-dt * 30)
    local now = os.clock()

    for _, entry in pairs(S.playerESPEntries) do
        local root = entry.root
        local attachment = entry.renderAttachment
        if root and root.Parent and attachment and attachment.Parent == root then
            local renderCFrame
            local ok = pcall(function()
                renderCFrame = root:GetRenderCFrame()
            end)
            if ok and renderCFrame then
                pcall(function()
                    -- Follow only the rendered world position. Keeping the
                    -- attachment rotation neutral prevents the shared BillboardGui
                    -- (including the Killer HP fill) from inheriting sideways yaw
                    -- or tilt from the character while preserving its exact UI size.
                    attachment.CFrame = root.CFrame:ToObjectSpace(CFrame.new(renderCFrame.Position))
                end)
            end
        end

        local fill = entry.billboard
            and entry.billboard:FindFirstChild("PlayerHPBarFill", true)
        if fill and fill:IsA("Frame") then
            -- Keep the last valid ratio when the replicated health briefly reports
            -- zero. A real zero-health state is accepted after it remains stable.
            local targetRatio = tonumber(entry.hpTargetRatio)
            if targetRatio == nil or targetRatio ~= targetRatio then
                targetRatio = tonumber(entry.hpDisplayedRatio) or 1
            end
            targetRatio = math.clamp(targetRatio, 0, 1)

            local displayedRatio = tonumber(entry.hpDisplayedRatio)
            if targetRatio <= 0 and displayedRatio and displayedRatio > 0 then
                entry.hpZeroSince = entry.hpZeroSince or now
                if now - entry.hpZeroSince < 0.12 then
                    targetRatio = displayedRatio
                else
                    entry.hpTargetRatio = 0
                end
            else
                entry.hpZeroSince = nil
            end

            if displayedRatio == nil then
                displayedRatio = targetRatio
            else
                displayedRatio = displayedRatio + (targetRatio - displayedRatio) * healthAlpha
                if math.abs(targetRatio - displayedRatio) < 0.001 then
                    displayedRatio = targetRatio
                end
            end
            entry.hpDisplayedRatio = displayedRatio

            -- Keep the existing fill geometry exactly; only write Size when its
            -- health ratio actually changes, avoiding needless per-frame redraws.
            if entry.hpFillObject ~= fill then
                entry.hpFillObject = fill
                entry.hpLastAppliedRatio = nil
                entry.hpLastAppliedColor = nil
            end

            local hpFillColor = displayedRatio <= 0.4
                and S.PLAYER_HP_BAR_LOW_COLOR
                or S.PLAYER_HP_BAR_HEALTHY_COLOR
            if entry.hpLastAppliedColor ~= hpFillColor then
                fill.BackgroundColor3 = hpFillColor
                local fillStroke = fill:FindFirstChild("PlayerHPBarFillStroke")
                if fillStroke and fillStroke:IsA("UIStroke") then
                    fillStroke.Color = Color3.fromRGB(0, 0, 0)
                end
                entry.hpLastAppliedColor = hpFillColor
            end

            if entry.hpLastAppliedRatio == nil
                or math.abs(displayedRatio - entry.hpLastAppliedRatio) >= 0.0005 then
                fill.Size = UDim2.new(0.56, 0, displayedRatio * 0.97, 0)
                entry.hpLastAppliedRatio = displayedRatio
            end
        end
    end
end
S.__helpers.connect(S.RunService.RenderStepped, S.__helpers.updatePlayerESPBillboardRender)

S.__helpers.refreshPlayerESPText = function(entry)
    if not entry or not entry.character or not entry.character.Parent then
        return
    end

    local role = entry.role or S.__helpers.getPlayerRole(entry.player, entry.character)
    -- Text ESP uses the same role classification as Survivor/Killer ESP, but
    -- its own toggles work independently of the main Highlight ESP toggles.
    local showCharacterText = (role == "Survivor" and S.isSurvivorCharacterTextESPEnabled)
        or (role == "Killer" and S.isKillerCharacterTextESPEnabled)
    local showHPBar = (role == "Survivor" and S.isSurvivorHPBarESPEnabled)
        or (role == "Killer" and S.isKillerHPBarESPEnabled)

    local characterLabel = entry.billboard and entry.billboard:FindFirstChild("PlayerCharacterText", true)
    -- Remove legacy percentage labels immediately, including instances left by an earlier run.
    local stalePercentLabel = entry.billboard
        and entry.billboard:FindFirstChild("PlayerHPBarPercent", true)
    if stalePercentLabel then
        pcall(function() stalePercentLabel:Destroy() end)
    end
    local deviceIcon = entry.deviceIcon
        or (entry.billboard and entry.billboard:FindFirstChild("PlayerDeviceIcon", true))
    if deviceIcon then
        local characterLabel = entry.billboard
            and entry.billboard:FindFirstChild("PlayerCharacterText", true)
        local textRow = characterLabel and characterLabel.Parent
        if textRow then
            -- Reassert sibling order so the device stays immediately to the
            -- right of the character label even after an ESP refresh.
            characterLabel.LayoutOrder = 1
            deviceIcon.Parent = textRow
            deviceIcon.LayoutOrder = 2
        end
        local deviceName = tostring(entry.player and entry.player:GetAttribute("Device") or "Unknown")
        deviceIcon.Image = S.DEVICE_ESP_IMAGES[deviceName] or S.DEVICE_ESP_IMAGES.Unknown
        deviceIcon.Visible = S.isDeviceESPEnabled == true
    end
    if characterLabel then
        S.__helpers.applyESPTextFont(characterLabel)
        local textParts = {}
        if showCharacterText then
            table.insert(textParts, S.__helpers.getPlayerCharacterDisplayName(
                entry.player, entry.character
            ))
        end
        characterLabel.Text = table.concat(textParts, " | ")
        characterLabel.Visible = #textParts > 0
    end

    -- Reference-style HP bar. The percentage readout is intentionally removed.
    -- The black track remains visible around the green health fill.
    local humanoid = entry.humanoid
    local maxHealth = humanoid and humanoid.Parent
        and (tonumber(humanoid.MaxHealth) or 0) or 0
    local currentHealth = humanoid and humanoid.Parent
        and (tonumber(humanoid.Health) or 0) or 0
    local hasValidMaxHealth = maxHealth > 0 and maxHealth == maxHealth
    local healthRatio = hasValidMaxHealth
        and math.clamp(currentHealth / maxHealth, 0, 1) or nil
    local hasCachedHealth = tonumber(entry.hpTargetRatio) ~= nil
        or tonumber(entry.hpDisplayedRatio) ~= nil
    local canShowHPBar = showHPBar and (hasValidMaxHealth or hasCachedHealth)
    local hpBarBackground = entry.billboard
        and entry.billboard:FindFirstChild("PlayerHPBarBackground", true)

    -- Publish only valid health samples. The render updater briefly holds a
    -- zero sample so a one-frame replication dip cannot empty the green fill.
    if healthRatio ~= nil then
        entry.hpTargetRatio = healthRatio
        if healthRatio > 0 then
            entry.hpZeroSince = nil
        end
    end
    if entry.hpDisplayedRatio == nil and entry.hpTargetRatio ~= nil then
        entry.hpDisplayedRatio = math.clamp(tonumber(entry.hpTargetRatio) or 0, 0, 1)
    end
    if hpBarBackground then
        hpBarBackground.Visible = canShowHPBar == true
    end
end

S.__helpers.refreshAllPlayerESPText = function()
    for _, entry in pairs(S.playerESPEntries) do
        S.__helpers.refreshPlayerESPText(entry)
    end
end

S.__helpers.updatePlayerDistanceESP = function()
    local localCharacter = S.lp and S.lp.Character
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    for _, entry in pairs(S.playerESPEntries) do
        local role = entry.role or S.__helpers.getPlayerRole(entry.player, entry.character)
        -- Distance uses the shared Survivor/Killer role classification, while
        -- remaining independent from the main Highlight ESP toggles.
        local roleDistanceEnabled = (role == "Survivor" and S.isSurvivorDistanceTextESPEnabled)
            or (role == "Killer" and S.isKillerDistanceTextESPEnabled)
        local billboard = entry.distanceBillboard
        local label = billboard and billboard:FindFirstChild("PlayerDistanceText")
        local targetRoot = entry.root
        if roleDistanceEnabled and label and label.Parent and localRoot and targetRoot and targetRoot.Parent then
            local distance = (targetRoot.Position - localRoot.Position).Magnitude
            label.Text = string.format("%.0f studs", distance)
            label.Visible = true
        elseif label then
            label.Visible = false
        end
    end
end

S.__helpers.connect(S.RunService.RenderStepped, S.__helpers.updatePlayerDistanceESP)

S.__helpers.removePlayerESP = function(player)
    if not player then return end

    local key = tostring(player.UserId)
    local entry = S.playerESPEntries[key]
    if entry then
        if entry.healthConnection then
            pcall(function() entry.healthConnection:Disconnect() end)
        end
        if entry.maxHealthConnection then
            pcall(function() entry.maxHealthConnection:Disconnect() end)
        end
        if entry.deviceConnection then
            pcall(function() entry.deviceConnection:Disconnect() end)
        end
        S.__helpers.removePlayerCooldownESP(entry)
        if entry.billboard then
            pcall(function() entry.billboard:Destroy() end)
        end
        if entry.renderAttachment then
            pcall(function() entry.renderAttachment:Destroy() end)
            entry.renderAttachment = nil
        end
        if entry.distanceBillboard and entry.distanceBillboard ~= entry.billboard then
            pcall(function() entry.distanceBillboard:Destroy() end)
        end
        S.playerESPEntries[key] = nil
    end

    local rootFolder = S.CoreGui:FindFirstChild(S.ROOT_FOLDER_NAME)
    local folder = rootFolder and rootFolder:FindFirstChild(S.ESP_FOLDER_NAME)
    local highlight = folder
        and folder:FindFirstChild(S.__helpers.getPlayerESPHighlightName(player))
    if highlight then
        highlight:Destroy()
    end

    -- Clean up labels left by earlier runs of this script.
    local character = player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if root then
        for _, staleName in ipairs({
            "PlayerHP_BB_" .. key,
            "Player_BB_" .. key,
            "PlayerDistance_BB_" .. key,
            "PlayerCooldown_BB_" .. key,
            S.PLAYER_ESP_RENDER_ATTACHMENT_PREFIX .. key,
        }) do
            local staleBillboard = root:FindFirstChild(staleName)
            if staleBillboard then
                staleBillboard:Destroy()
            end
        end
    end
end

S.__helpers.addPlayerESP = function(player)
    -- Never apply any player ESP to the local player.
    if not player or player == S.lp or not player.Parent then
        return
    end

    local character = player.Character
    if not character or not character.Parent then
        S.__helpers.removePlayerESP(player)
        return
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or humanoid.Health <= 0 or not root then
        S.__helpers.removePlayerESP(player)
        return
    end

    local role = S.__helpers.getPlayerRole(player, character)
    -- Main Highlight ESP and each text ESP use the same Killer/Survivor role
    -- classification, but their individual enablement states are independent.
    local playerESPEnabled = (role == "Killer" and S.isKillerESPEnabled)
        or (role == "Survivor" and S.isSurvivorESPEnabled)
    local hpBarESPEnabled = (role == "Killer" and S.isKillerHPBarESPEnabled)
        or (role == "Survivor" and S.isSurvivorHPBarESPEnabled)
    local characterTextESPEnabled = (role == "Killer" and S.isKillerCharacterTextESPEnabled)
        or (role == "Survivor" and S.isSurvivorCharacterTextESPEnabled)
    local distanceESPEnabled = (role == "Killer" and S.isKillerDistanceTextESPEnabled)
        or (role == "Survivor" and S.isSurvivorDistanceTextESPEnabled)
    local anyTextESPEnabled = hpBarESPEnabled or characterTextESPEnabled or distanceESPEnabled
        or S.isDeviceESPEnabled or S.isCooldownESPEnabled

    if not playerESPEnabled and not anyTextESPEnabled then
        S.__helpers.removePlayerESP(player)
        return
    end

    local key = tostring(player.UserId)
    local existingEntry = S.playerESPEntries[key]
    if existingEntry
        and (existingEntry.character ~= character or existingEntry.root ~= root) then
        S.__helpers.removePlayerESP(player)
    end

    local folder = S.__helpers.getESPFolder()
    local id = S.__helpers.getPlayerESPHighlightName(player)
    local oldHighlight = folder:FindFirstChild(id)
    if oldHighlight then
        oldHighlight:Destroy()
    end

    local isKiller = role == "Killer"
    if playerESPEnabled then
        local highlight = Instance.new("Highlight")
        highlight.Name = id
        highlight.Adornee = character
        highlight.FillColor = isKiller and S.KILLER_ESP_FILL_COLOR or S.SURVIVOR_ESP_FILL_COLOR
        highlight.OutlineColor = isKiller and S.KILLER_ESP_OUTLINE_COLOR or S.SURVIVOR_ESP_OUTLINE_COLOR
        highlight.FillTransparency = isKiller
            and S.KILLER_ESP_FILL_TRANSPARENCY or S.SURVIVOR_ESP_FILL_TRANSPARENCY
        highlight.OutlineTransparency = isKiller
            and S.KILLER_ESP_OUTLINE_TRANSPARENCY or S.SURVIVOR_ESP_OUTLINE_TRANSPARENCY
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.Parent = folder
    end

    -- Character name, HP bar, and distance are arranged in this shared billboard.
    local billboardName = "PlayerHP_BB_" .. key
    local billboard = root:FindFirstChild(billboardName)
    if not billboard or not billboard:IsA("BillboardGui") then
        billboard = Instance.new("BillboardGui")
        billboard.Name = billboardName
        billboard.AlwaysOnTop = true
        billboard.ZIndexBehavior = Enum.ZIndexBehavior.Global
        billboard.Parent = root
    end

    -- World-scaled reference canvas. Unlike pixel-offset BillboardGuis, this
    -- scales with the character on screen, so ESP elements do not spread apart
    -- or become oversized relative to the character at longer distances.
    -- Match the reference crop's approximately 145:121 canvas ratio.
    billboard.Size = UDim2.new(8.7, 0, 7.2, 0)
    local renderAttachmentName = S.PLAYER_ESP_RENDER_ATTACHMENT_PREFIX .. key
    local renderAttachment = root:FindFirstChild(renderAttachmentName)
    if not renderAttachment or not renderAttachment:IsA("Attachment") then
        if renderAttachment then renderAttachment:Destroy() end
        renderAttachment = Instance.new("Attachment")
        renderAttachment.Name = renderAttachmentName
        renderAttachment.Parent = root
    end
    billboard.Adornee = renderAttachment
    billboard.StudsOffset = Vector3.new(0, 0.5, 0)
    billboard.MaxDistance = math.huge
    billboard.LightInfluence = 0
    billboard.AlwaysOnTop = true
    billboard.ZIndexBehavior = Enum.ZIndexBehavior.Global

    local textRow = billboard:FindFirstChild("PlayerESPTextRow")
    if not textRow then
        textRow = Instance.new("Frame")
        textRow.Name = "PlayerESPTextRow"
        textRow.Parent = billboard
    end
    -- A full-canvas transparent frame. Its children use scale-only geometry.
    textRow.BackgroundTransparency = 1
    textRow.BorderSizePixel = 0
    textRow.ClipsDescendants = false
    textRow.Position = UDim2.new(0, 0, 0, 0)
    textRow.Size = UDim2.new(1, 0, 1, 0)

    local rowLayout = textRow:FindFirstChild("HorizontalRow")
    if rowLayout then
        rowLayout:Destroy()
    end

    local legacyHPText = billboard:FindFirstChild("PlayerHPText", true)
    if legacyHPText then
        pcall(function() legacyHPText:Destroy() end)
    end

    local label = billboard:FindFirstChild("PlayerCharacterText", true)
    if not label then
        label = Instance.new("TextLabel")
        label.Name = "PlayerCharacterText"
        label.Parent = textRow
    else
        label.Parent = textRow
    end
    label.AutomaticSize = Enum.AutomaticSize.None
    label.Position = UDim2.new(0.28, 0, 0.067, 0)
    label.Size = UDim2.new(0.50, 0, 0.067, 0)
    label.BackgroundTransparency = 1
    label.BorderSizePixel = 0
    label.LayoutOrder = 1
    label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextYAlignment = Enum.TextYAlignment.Center
    label.TextStrokeTransparency = 0.2
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.ZIndex = 100
    S.__helpers.applyESPTextFont(label)
    label.TextSize = 11
    label.TextScaled = true
    label.TextWrapped = false

    -- Slim vertical HP bar at the left of the player, matching the supplied reference.
    -- The dark outer track stays visible while the health fill grows upward and changes color at 40%.
    local hpBarBackground = billboard:FindFirstChild("PlayerHPBarBackground", true)
    if not hpBarBackground or not hpBarBackground:IsA("Frame") then
        if hpBarBackground then hpBarBackground:Destroy() end
        hpBarBackground = Instance.new("Frame")
        hpBarBackground.Name = "PlayerHPBarBackground"
        hpBarBackground.Parent = billboard
    else
        hpBarBackground.Parent = billboard
    end
    hpBarBackground.AnchorPoint = Vector2.new(0, 0)
    -- Reference placement: about 14 px from the left, 17 px from the top.
    -- The outer track is approximately 2 px wide and 108 px high at the
    -- supplied screenshot scale; the green fill remains inset inside it.
    hpBarBackground.Position = UDim2.new(0.096, 0, 0.14, 0)
    hpBarBackground.Size = UDim2.new(0.015, 0, 0.66, 0)
    hpBarBackground.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    hpBarBackground.BackgroundTransparency = 0
    hpBarBackground.BorderSizePixel = 0
    hpBarBackground.ClipsDescendants = true
    hpBarBackground.ZIndex = 100
    hpBarBackground.Visible = false

    local hpBarCorner = hpBarBackground:FindFirstChild("PlayerHPBarCorner")
    if not hpBarCorner or not hpBarCorner:IsA("UICorner") then
        if hpBarCorner then hpBarCorner:Destroy() end
        hpBarCorner = Instance.new("UICorner")
        hpBarCorner.Name = "PlayerHPBarCorner"
        hpBarCorner.Parent = hpBarBackground
    end
    hpBarCorner.CornerRadius = UDim.new(0, 0)

    local oldHPBarStroke = hpBarBackground:FindFirstChild("PlayerHPBarStroke")
    if oldHPBarStroke then oldHPBarStroke:Destroy() end

    local hpBarFill = hpBarBackground:FindFirstChild("PlayerHPBarFill")
    if not hpBarFill or not hpBarFill:IsA("Frame") then
        if hpBarFill then hpBarFill:Destroy() end
        hpBarFill = Instance.new("Frame")
        hpBarFill.Name = "PlayerHPBarFill"
        hpBarFill.Parent = hpBarBackground
    end
    hpBarFill.AnchorPoint = Vector2.new(0.5, 1)
    -- Keep the health fill centered inside the slightly widened black track.
    hpBarFill.Position = UDim2.new(0.5, 0, 0.985, 0)
    hpBarFill.Size = UDim2.new(0.56, 0, 0.97, 0)
    local initialMaxHealth = tonumber(humanoid.MaxHealth) or 0
    local initialHealthRatio = initialMaxHealth > 0
        and math.clamp((tonumber(humanoid.Health) or 0) / initialMaxHealth, 0, 1)
        or 1
    hpBarFill.BackgroundColor3 = initialHealthRatio <= 0.4
        and S.PLAYER_HP_BAR_LOW_COLOR
        or S.PLAYER_HP_BAR_HEALTHY_COLOR
    hpBarFill.BackgroundTransparency = 0
    hpBarFill.BorderSizePixel = 0
    hpBarFill.ZIndex = 101

    local hpBarFillCorner = hpBarFill:FindFirstChild("PlayerHPBarFillCorner")
    if not hpBarFillCorner or not hpBarFillCorner:IsA("UICorner") then
        if hpBarFillCorner then hpBarFillCorner:Destroy() end
        hpBarFillCorner = Instance.new("UICorner")
        hpBarFillCorner.Name = "PlayerHPBarFillCorner"
        hpBarFillCorner.Parent = hpBarFill
    end
    hpBarFillCorner.CornerRadius = UDim.new(0, 0)

    -- A 1-pixel black UIStroke outlines the green fill without changing
    -- the HP bar geometry.
    local hpFillStroke = hpBarFill:FindFirstChild("PlayerHPBarFillStroke")
    if not hpFillStroke or not hpFillStroke:IsA("UIStroke") then
        if hpFillStroke then hpFillStroke:Destroy() end
        hpFillStroke = Instance.new("UIStroke")
        hpFillStroke.Name = "PlayerHPBarFillStroke"
        hpFillStroke.Parent = hpBarFill
    end
    hpFillStroke.Color = Color3.fromRGB(0, 0, 0)
    hpFillStroke.Thickness = 1
    hpFillStroke.Transparency = 0
    hpFillStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    hpFillStroke.LineJoinMode = Enum.LineJoinMode.Miter

    local oldGradient = hpBarFill:FindFirstChild("PlayerHPBarGradient")
    if oldGradient then oldGradient:Destroy() end

    -- The percentage text is not part of the reference; remove it completely.
    local oldPercentLabel = billboard:FindFirstChild("PlayerHPBarPercent", true)
    if oldPercentLabel then oldPercentLabel:Destroy() end

    local deviceIcon = textRow:FindFirstChild("PlayerDeviceIcon")
    if not deviceIcon then
        deviceIcon = Instance.new("ImageLabel")
        deviceIcon.Name = "PlayerDeviceIcon"
    end
    -- Device icon is anchored in the upper-right corner of the same world-scaled canvas.
    deviceIcon.Parent = textRow
    deviceIcon.LayoutOrder = 2
    deviceIcon.AnchorPoint = Vector2.new(0, 0)
    deviceIcon.Position = UDim2.new(0.745, 0, 0.167, 0)
    deviceIcon.Size = UDim2.new(0.15, 0, 0.19, 0)
    deviceIcon.BackgroundTransparency = 1
    deviceIcon.BorderSizePixel = 0
    deviceIcon.ScaleType = Enum.ScaleType.Fit
    deviceIcon.ZIndex = 100
    deviceIcon.Visible = S.isDeviceESPEnabled
    local detectedDevice = tostring(player:GetAttribute("Device") or "Unknown")
    deviceIcon.Image = S.DEVICE_ESP_IMAGES[detectedDevice] or S.DEVICE_ESP_IMAGES.Unknown

    local textColor = isKiller and S.KILLER_ESP_FILL_COLOR or S.SURVIVOR_ESP_FILL_COLOR
    label.TextColor3 = textColor

    -- Distance text is centered just below the player, at the reference image height.
    local distanceBillboardName = "PlayerDistance_BB_" .. key
    local distanceBillboard = root:FindFirstChild(distanceBillboardName)
    if not distanceBillboard or not distanceBillboard:IsA("BillboardGui") then
        if distanceBillboard then
            distanceBillboard:Destroy()
        end
        distanceBillboard = Instance.new("BillboardGui")
        distanceBillboard.Name = distanceBillboardName
        distanceBillboard.Parent = root
    end
    distanceBillboard.Adornee = root
    distanceBillboard.AlwaysOnTop = true
    distanceBillboard.ZIndexBehavior = Enum.ZIndexBehavior.Global
    -- Compact label, centered just below the character as in the reference.
    distanceBillboard.Size = UDim2.new(0, 64, 0, 14)
    distanceBillboard.StudsOffset = Vector3.new(0, -5, 0)
    distanceBillboard.MaxDistance = math.huge

    local distanceLabel = distanceBillboard:FindFirstChild("PlayerDistanceText")
    if not distanceLabel then
        distanceLabel = Instance.new("TextLabel")
        distanceLabel.Name = "PlayerDistanceText"
        distanceLabel.Parent = distanceBillboard
    end
    distanceLabel.AnchorPoint = Vector2.new(0, 0)
    distanceLabel.Position = UDim2.new(0, 0, 0, 0)
    distanceLabel.Size = UDim2.new(1, 0, 1, 0)
    distanceLabel.BackgroundTransparency = 1
    distanceLabel.BorderSizePixel = 0
    distanceLabel.Text = "-- studs"
    distanceLabel.TextStrokeTransparency = 0
    distanceLabel.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    distanceLabel.TextXAlignment = Enum.TextXAlignment.Center
    distanceLabel.TextYAlignment = Enum.TextYAlignment.Center
    distanceLabel.ZIndex = 100
    S.__helpers.applyESPTextFont(distanceLabel)
    distanceLabel.TextSize = 9
    distanceLabel.TextScaled = false
    distanceLabel.TextWrapped = false
    distanceLabel.TextColor3 = Color3.fromRGB(145, 145, 145)
    distanceLabel.Visible = distanceESPEnabled == true

    local currentEntry = S.playerESPEntries[key]
    if not currentEntry or currentEntry.humanoid ~= humanoid then
        if currentEntry and currentEntry.healthConnection then
            pcall(function() currentEntry.healthConnection:Disconnect() end)
        end
        if currentEntry and currentEntry.maxHealthConnection then
            pcall(function() currentEntry.maxHealthConnection:Disconnect() end)
        end

        currentEntry = {
            player = player,
            character = character,
            root = root,
            humanoid = humanoid,
            role = role,
            billboard = billboard,
            distanceBillboard = distanceBillboard,
            deviceIcon = deviceIcon,
        }
        currentEntry.healthConnection = humanoid.HealthChanged:Connect(function()
            if player.Character == character and character.Parent then
                S.__helpers.refreshPlayerESPText(currentEntry)
            end
        end)
        currentEntry.maxHealthConnection = humanoid:GetPropertyChangedSignal("MaxHealth"):Connect(function()
            if player.Character == character and character.Parent then
                S.__helpers.refreshPlayerESPText(currentEntry)
            end
        end)
        S.playerESPEntries[key] = currentEntry
    else
        currentEntry.player = player
        currentEntry.character = character
        currentEntry.root = root
        currentEntry.humanoid = humanoid
        currentEntry.role = role
        currentEntry.billboard = billboard
        currentEntry.distanceBillboard = distanceBillboard
        currentEntry.deviceIcon = deviceIcon
    end

    currentEntry.renderAttachment = renderAttachment

    if currentEntry.deviceConnection then
        -- Keep one attribute listener per current player ESP entry.
    else
        currentEntry.deviceConnection = player:GetAttributeChangedSignal("Device"):Connect(function()
            if player.Character == currentEntry.character and currentEntry.character.Parent then
                S.__helpers.refreshPlayerESPText(currentEntry)
            end
        end)
    end

    S.__helpers.refreshPlayerESPText(currentEntry)
    if S.isCooldownESPEnabled then
        S.__helpers.createPlayerCooldownESP(currentEntry)
    else
        S.__helpers.removePlayerCooldownESP(currentEntry)
    end
end

S.__helpers.clearAllPlayerESP = function()
    for _, player in ipairs(S.Players:GetPlayers()) do
        S.__helpers.removePlayerESP(player)
    end
    local rootFolder = S.CoreGui:FindFirstChild(S.ROOT_FOLDER_NAME)
    local folder = rootFolder and rootFolder:FindFirstChild(S.ESP_FOLDER_NAME)
    if folder then
        folder:ClearAllChildren()
    end
end

S.__helpers.updateAllPlayerESP = function()
    S.__helpers.clearAllPlayerESP()

    for _, player in ipairs(S.Players:GetPlayers()) do
        S.__helpers.addPlayerESP(player)
    end
end

S.__helpers.setupPlayerESP = function(player)
    if player == S.lp then return end

    S.__helpers.connect(player.CharacterAdded, function(character)
        task.wait(0.25)

        if player.Parent and character.Parent then
            S.__helpers.addPlayerESP(player)
        end
    end)

    S.__helpers.connect(player.CharacterRemoving, function()
        S.__helpers.removePlayerESP(player)
    end)

    task.defer(function()
        task.wait(0.5)
        if player.Parent then
            S.__helpers.addPlayerESP(player)
        end
    end)
end

for _, player in ipairs(S.Players:GetPlayers()) do
    S.__helpers.setupPlayerESP(player)
end

S.__helpers.connect(S.Players.PlayerAdded, function(player)
    S.__helpers.setupPlayerESP(player)

    task.wait(0.25)
    if player.Parent then
        S.__helpers.addPlayerESP(player)
    end
end)

S.__helpers.connect(S.Players.PlayerRemoving, function(player)
    S.__helpers.removePlayerESP(player)
end)

-- ------------------------------------------------
-- NATIVE ESP HIGHLIGHT
-- Use Roblox Highlight directly for both fill and outline.
-- ------------------------------------------------
S.__helpers.createReferenceESPBox = function(parent, name, adornee, fillColor, outlineColor, fillTransparency)
    if not parent or not adornee then return nil end
    local highlight = Instance.new("Highlight")
    highlight.Name = name
    highlight.Adornee = adornee
    highlight.FillColor = fillColor or Color3.fromRGB(190, 194, 160)
    highlight.OutlineColor = outlineColor or fillColor or Color3.fromRGB(190, 194, 160)
    highlight.FillTransparency = math.clamp(tonumber(fillTransparency) or 0.38, 0, 1)
    highlight.OutlineTransparency = 0.08
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Enabled = true
    highlight.Parent = parent
    return highlight
end

-- ------------------------------------------------
-- ITEM ESP
-- ------------------------------------------------

S.itemESPEntries = {}
S.__helpers.getItemESPId = function(tool)
    local id
    pcall(function()
        id = tool:GetDebugId()
    end)
    if not id then
        id = tostring(tool)
    end
    return id
end

S.__helpers.getItemESPPart = function(object)
    if not object or not object.Parent then
        return nil
    end

    -- ForsakenPlus stores loose Gears as Models with a Root BasePart.
    if object:IsA("Model") and object.Name == "Gear" then
        local root = object:FindFirstChild("Root")
        if root and root:IsA("BasePart") then
            return root
        end
    end

    return object:FindFirstChild("Handle")
        or object:FindFirstChildWhichIsA("BasePart", true)
end

S.__helpers.isItemToolCandidate = function(object)
    if not object or not object.Parent or not object:IsDescendantOf(workspace) then
        return false
    end

    if object:IsA("Tool") then
        -- BlueFlag and RedFlag are intentionally excluded from Item ESP.
        local itemName = tostring(object.Name):lower()
        if itemName == "blueflag" or itemName == "redflag" then
            return false
        end

        -- Do not label tools currently equipped by a character.
        local parent = object.Parent
        if parent and parent:FindFirstChildOfClass("Humanoid") then
            return false
        end
        return true
    end

    -- Match the uploaded ForsakenPlus source: map Gears are Models named
    -- "Gear" with a Root part, under workspace.Map.Ingame.Map.
    if object:IsA("Model") and object.Name == "Gear" then
        local map = workspace:FindFirstChild("Map")
        local ingame = map and map:FindFirstChild("Ingame")
        local gameMap = ingame and ingame:FindFirstChild("Map")
        local root = object:FindFirstChild("Root")
        return gameMap ~= nil
            and object:IsDescendantOf(gameMap)
            and root ~= nil
            and root:IsA("BasePart")
    end

    return false
end

S.__helpers.removeItemESP = function(tool)
    if not tool then return end
    local id = S.__helpers.getItemESPId(tool)
    local entry = S.itemESPEntries[id]

    if entry then
        if entry.box then
            pcall(function() entry.box:Destroy() end)
        elseif entry.highlight then
            pcall(function() entry.highlight:Destroy() end)
        end
        if entry.billboard then
            pcall(function() entry.billboard:Destroy() end)
        end
        if entry.parentConnection then
            pcall(function() entry.parentConnection:Disconnect() end)
        end
        S.itemESPEntries[id] = nil
    end

    local rootFolder = S.CoreGui:FindFirstChild(S.ROOT_FOLDER_NAME)
    local folder = rootFolder and rootFolder:FindFirstChild(S.ITEM_ESP_FOLDER_NAME)
    local oldBox = folder and folder:FindFirstChild(id)
    if oldBox then
        oldBox:Destroy()
    end

    local part = entry and entry.part or S.__helpers.getItemESPPart(tool)
    local billboard = part and part:FindFirstChild("Item_BB_" .. id)
    if billboard then
        billboard:Destroy()
    end
end

S.__helpers.addItemESP = function(tool)
    if not S.isItemESPEnabled or not S.__helpers.isItemToolCandidate(tool) then
        S.__helpers.removeItemESP(tool)
        return
    end

    local targetPart = S.__helpers.getItemESPPart(tool)
    if not targetPart then
        S.__helpers.removeItemESP(tool)
        return
    end

    local id = S.__helpers.getItemESPId(tool)
    S.__helpers.removeItemESP(tool)

    local folder = S.__helpers.getItemESPFolder()
    -- Tools are not PVInstances, so adorn the Handle/base part; map Gear Models
    -- use their model bounds, matching the translucent 3D box in the reference.
    local itemAdornee = tool:IsA("Model") and tool or targetPart
    local box = S.__helpers.createReferenceESPBox(
        folder,
        id,
        itemAdornee,
        S.ITEM_ESP_FILL_COLOR,
        S.ITEM_ESP_OUTLINE_COLOR,
        0.38
    )

    -- Small item-name label above the Handle/base part.
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "Item_BB_" .. id
    billboard.Size = UDim2.new(0, 110, 0, 24)
    billboard.AlwaysOnTop = true
    billboard.ZIndexBehavior = Enum.ZIndexBehavior.Global
    billboard.Adornee = targetPart
    billboard.StudsOffset = Vector3.new(0, 2, 0)
    billboard.Parent = targetPart

    local label = Instance.new("TextLabel")
    label.Name = "ItemText"
    label.Size = UDim2.new(1, 0, 1, 0)
    label.BackgroundTransparency = 1
    label.BorderSizePixel = 0
    S.__helpers.applyESPTextFont(label)
    -- Match Item ESP text size to Generator ESP text size.
    label.TextSize = S.GENERATOR_TEXT_SIZE
    label.TextScaled = false
    label.TextWrapped = true
    label.TextStrokeTransparency = 0.2
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextYAlignment = Enum.TextYAlignment.Center
    label.TextColor3 = S.ITEM_ESP_FILL_COLOR
    label.Text = tool.Name
    label.Visible = S.isItemESPTextEnabled
    label.ZIndex = 100
    label.Parent = billboard

    local parentConnection = tool:GetPropertyChangedSignal("Parent"):Connect(function()
        if not tool.Parent or not S.isItemESPEnabled then
            S.__helpers.removeItemESP(tool)
        elseif S.__helpers.isItemToolCandidate(tool) then
            S.__helpers.addItemESP(tool)
        else
            S.__helpers.removeItemESP(tool)
        end
    end)

    S.itemESPEntries[id] = {
        tool = tool,
        part = targetPart,
        box = box,
        billboard = billboard,
        parentConnection = parentConnection,
    }
end

S.__helpers.clearAllItemESP = function()
    -- Billboards are parented to item parts rather than the ESP folder, so destroy
    -- each entry explicitly before clearing the ESP box folder.
    for _, entry in pairs(S.itemESPEntries) do
        if entry.parentConnection then
            pcall(function() entry.parentConnection:Disconnect() end)
        end
        if entry.billboard then
            pcall(function() entry.billboard:Destroy() end)
        end
        if entry.box then
            pcall(function() entry.box:Destroy() end)
        elseif entry.highlight then
            pcall(function() entry.highlight:Destroy() end)
        end
    end
    table.clear(S.itemESPEntries)

    local rootFolder = S.CoreGui:FindFirstChild(S.ROOT_FOLDER_NAME)
    local folder = rootFolder and rootFolder:FindFirstChild(S.ITEM_ESP_FOLDER_NAME)
    if folder then
        folder:ClearAllChildren()
    end
end

S.__helpers.updateAllItemESP = function()
    S.__helpers.clearAllItemESP()
    if not S.isItemESPEnabled then
        return
    end

    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("Tool") or (object:IsA("Model") and object.Name == "Gear") then
            S.__helpers.addItemESP(object)
        end
    end
end

S.__helpers.connect(workspace.DescendantAdded, function(object)
    if not S.isItemESPEnabled then
        return
    end

    if object:IsA("Tool") or (object:IsA("Model") and object.Name == "Gear") then
        task.defer(function()
            if S.isItemESPEnabled and object.Parent then
                S.__helpers.addItemESP(object)

                if not S.__helpers.getItemESPPart(object) then
                    for _ = 1, 10 do
                        task.wait(0.1)
                        if not S.isItemESPEnabled or not object.Parent then
                            break
                        end
                        if S.__helpers.getItemESPPart(object) then
                            S.__helpers.addItemESP(object)
                            break
                        end
                    end
                end
            end
        end)
    elseif object:IsA("BasePart") then
        local itemObject = object:FindFirstAncestorOfClass("Tool")
        if not itemObject then
            local ancestor = object.Parent
            while ancestor and ancestor ~= workspace do
                if ancestor:IsA("Model") and ancestor.Name == "Gear" then
                    itemObject = ancestor
                    break
                end
                ancestor = ancestor.Parent
            end
        end
        if itemObject then
            task.defer(function()
                if S.isItemESPEnabled and itemObject.Parent and object.Parent then
                    S.__helpers.addItemESP(itemObject)
                end
            end)
        end
    end
end)

S.__helpers.connect(workspace.DescendantRemoving, function(object)
    if object:IsA("Tool") or (object:IsA("Model") and object.Name == "Gear") then
        S.__helpers.removeItemESP(object)
    elseif object:IsA("BasePart") then
        local ancestor = object.Parent
        while ancestor and ancestor ~= workspace do
            if ancestor:IsA("Model") and ancestor.Name == "Gear" then
                if object.Name == "Root" then
                    S.__helpers.removeItemESP(ancestor)
                end
                break
            end
            ancestor = ancestor.Parent
        end
    end
end)

-- ------------------------------------------------
-- GENERATOR ESP
-- ------------------------------------------------

S.generatorESPEntries = {}
S.__helpers.getGeneratorESPFolder = function()
    local rootFolder = S.__helpers.getWorldRootFolder()
    local folder = rootFolder:FindFirstChild(S.GENERATOR_ESP_FOLDER_NAME)

    if not folder then
        folder = Instance.new("Folder")
        folder.Name = S.GENERATOR_ESP_FOLDER_NAME
        folder.Parent = rootFolder
    end

    return folder
end

S.__helpers.getGeneratorESPTextGui = function()
    local playerGui = S.lp:FindFirstChildOfClass("PlayerGui")
        or S.lp:WaitForChild("PlayerGui")
    local gui = playerGui:FindFirstChild(S.GENERATOR_TEXT_GUI_NAME)

    if not gui then
        gui = Instance.new("ScreenGui")
        gui.Name = S.GENERATOR_TEXT_GUI_NAME
        gui.IgnoreGuiInset = true
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 9999
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui.Parent = playerGui
    end

    return gui
end

S.__helpers.getGeneratorESPId = function(generator)
    local id

    pcall(function()
        id = generator:GetDebugId()
    end)

    if not id then
        id = tostring(generator)
    end

    return id
end

S.__helpers.getGeneratorWorldPosition = function(generator)
    if not generator or not generator.Parent then
        return nil
    end

    if generator:IsA("BasePart") then
        return generator.Position
    end

    if generator:IsA("Model") then
        local primary = generator.PrimaryPart

        if primary then
            return primary.Position
        end

        local ok, pivot = pcall(function()
            return generator:GetPivot()
        end)

        if ok and pivot then
            return pivot.Position
        end
    end

    return nil
end

S.generatorProgressSourceCache = setmetatable({}, {__mode = "k"})
S.generatorProgressState = setmetatable({}, {__mode = "k"})

S.__helpers.getGeneratorProgressSourcePriority = function(name)
    local normalized = tostring(name or ""):lower():gsub("[^%w]", "")
    if normalized == "progress" then
        return 1
    elseif normalized == "generatorprogress"
        or normalized == "currentprogress"
        or normalized == "repairprogress"
        or normalized == "currentrepairprogress" then
        return 2
    elseif normalized:find("progress", 1, true) then
        return 3
    elseif normalized == "completionpercentage"
        or normalized == "percentage"
        or normalized == "percent"
        or normalized == "percentcomplete"
        or normalized == "completedpercentage"
        or normalized == "repairpercentage"
        or normalized == "repairpercent"
        or normalized == "completionpercent"
        or normalized == "currentcompletion" then
        return 4
    elseif normalized:find("percentage", 1, true)
        or normalized:find("percent", 1, true)
        or normalized:find("repairprogress", 1, true)
        or normalized:find("completion", 1, true) then
        return 5
    end
    return nil
end

S.__helpers.isGeneratorCompletionName = function(name)
    local normalized = tostring(name or ""):lower():gsub("[^%w]", "")
    return normalized == "done"
        or normalized == "isdone"
        or normalized == "complete"
        or normalized == "iscomplete"
        or normalized == "completed"
        or normalized == "iscompleted"
        or normalized == "finished"
        or normalized == "isfinished"
        or normalized == "repaired"
        or normalized == "isrepaired"
end

S.__helpers.isGeneratorCompletionValue = function(value)
    if value == true then
        return true
    elseif type(value) == "number" then
        return value >= 1
    elseif type(value) == "string" then
        local normalized = value:lower():gsub("^%s+", ""):gsub("%s+$", "")
        return normalized == "true"
            or normalized == "yes"
            or normalized == "done"
            or normalized == "complete"
            or normalized == "completed"
            or normalized == "finished"
            or normalized == "repaired"
    end
    return false
end

S.__helpers.buildGeneratorProgressSources = function(generator)
    local sources = {}
    local completionSources = {}
    if not generator or not generator.Parent then
        return {scannedAt = os.clock(), sources = sources, completionSources = completionSources}
    end

    local instances = {generator}
    for _, descendant in ipairs(generator:GetDescendants()) do
        table.insert(instances, descendant)
    end

    for depth, instance in ipairs(instances) do
        local okAttributes, attributes = pcall(function()
            return instance:GetAttributes()
        end)
        if okAttributes and type(attributes) == "table" then
            local instancePriority = S.__helpers.getGeneratorProgressSourcePriority(instance.Name)
            for attributeName, attributeValue in pairs(attributes) do
                local priority = S.__helpers.getGeneratorProgressSourcePriority(attributeName)
                -- Some maps store the numeric progress in an attribute with a
                -- generic key (for example Value/Amount) on a Progress container.
                if not priority and instancePriority and tonumber(attributeValue) ~= nil then
                    priority = instancePriority
                end
                if priority then
                    table.insert(sources, {
                        object = instance,
                        kind = "attribute",
                        key = attributeName,
                        priority = priority,
                        depth = depth,
                    })
                elseif S.__helpers.isGeneratorCompletionName(attributeName) then
                    table.insert(completionSources, {
                        object = instance,
                        kind = "attribute",
                        key = attributeName,
                        depth = depth,
                    })
                end
            end
        end

        if instance:IsA("ValueBase") then
            local priority = S.__helpers.getGeneratorProgressSourcePriority(instance.Name)
            -- Also accept a generic Value/Amount NumberValue below a Progress,
            -- RepairProgress, or Completion container.
            if not priority and instance.Parent then
                priority = S.__helpers.getGeneratorProgressSourcePriority(instance.Parent.Name)
            end
            if priority then
                table.insert(sources, {
                    object = instance,
                    kind = "value",
                    priority = priority,
                    depth = depth,
                })
            elseif S.__helpers.isGeneratorCompletionName(instance.Name) then
                table.insert(completionSources, {
                    object = instance,
                    kind = "value",
                    depth = depth,
                })
            end
        end
    end

    table.sort(sources, function(a, b)
        if a.priority ~= b.priority then
            return a.priority < b.priority
        end
        return a.depth < b.depth
    end)
    table.sort(completionSources, function(a, b)
        return a.depth < b.depth
    end)
    return {
        scannedAt = os.clock(),
        sources = sources,
        completionSources = completionSources,
    }
end

S.__helpers.coerceGeneratorPercent = function(rawValue)
    local value
    if type(rawValue) == "string" then
        local cleaned = rawValue:gsub("%%", ""):gsub("^%s+", ""):gsub("%s+$", "")
        value = tonumber(cleaned)
    else
        value = tonumber(rawValue)
    end

    if not value or value ~= value or value == math.huge or value == -math.huge then
        return nil
    end
    if value < 0 then
        return nil
    end
    if value <= 1.0001 then
        value = value * 100
    end
    return math.clamp(value, 0, 100)
end

S.__helpers.readDirectGeneratorProgress = function(generator)
    if not generator then return nil end

    -- Match the source script's live generator UI: BarUI.Bar.Size.X.Scale
    -- stores progress as a 0..1 fraction, including 1 when completed.
    local barUI = nil
    pcall(function()
        barUI = generator:FindFirstChild("BarUI", true)
    end)
    local bar = barUI and barUI:FindFirstChild("Bar")
    if bar then
        local ok, scale = pcall(function()
            return bar.Size.X.Scale
        end)
        if ok then
            local value = S.__helpers.coerceGeneratorPercent(scale)
            if value ~= nil then return value end
        end
    end

    -- Also support a progress bar nested under a UI container with a different
    -- hierarchy, as long as the bar is a GuiObject and has a meaningful X scale.
    if not bar then
        for _, descendant in ipairs(generator:GetDescendants()) do
            if descendant.Name == "Bar" and descendant:IsA("GuiObject") then
                local ok, scale = pcall(function()
                    return descendant.Size.X.Scale
                end)
                if ok then
                    local value = S.__helpers.coerceGeneratorPercent(scale)
                    if value ~= nil then return value end
                end
            end
        end
    end

    -- Keep the direct Progress child and Progress attribute fallback too.
    local progressObject = nil
    pcall(function()
        progressObject = generator:FindFirstChild("Progress")
    end)
    if progressObject then
        local ok, rawValue = pcall(function() return progressObject.Value end)
        if ok then
            local value = S.__helpers.coerceGeneratorPercent(rawValue)
            if value ~= nil then return value end
        end
    end

    local ok, rawAttribute = pcall(function() return generator:GetAttribute("Progress") end)
    if ok then
        local value = S.__helpers.coerceGeneratorPercent(rawAttribute)
        if value ~= nil then return value end
    end

    return nil
end

S.__helpers.readGeneratorPercentFromText = function(generator)
    if not generator then return nil end
    for _, instance in ipairs(generator:GetDescendants()) do
        if instance:IsA("TextLabel") or instance:IsA("TextButton") then
            local labelName = tostring(instance.Name):lower()
            local textValue = tostring(instance.Text or "")
            local numberText = textValue:match("([%d%.]+)%s*%%")
            if not numberText and (
                labelName:find("progress", 1, true)
                or labelName:find("percent", 1, true)
                or labelName:find("repair", 1, true)
            ) then
                numberText = textValue:match("^%s*([%d%.]+)%s*$")
            end
            if numberText then
                local value = S.__helpers.coerceGeneratorPercent(numberText)
                if value ~= nil then return value end
            end
        end
    end
    return nil
end

S.__helpers.getGeneratorProgress = function(generator)
    if not generator or not generator.Parent then
        local state = generator and S.generatorProgressState[generator]
        return state and state.lastProgress or nil, state and state.completed == true or false
    end

    local now = os.clock()
    local state = S.generatorProgressState[generator]
    if not state then
        state = {
            lastProgress = nil,
            lastProgressAt = nil,
            sourceSeen = false,
            noSourceSince = nil,
            completed = false,
        }
        S.generatorProgressState[generator] = state
    end

    -- Re-scan periodically, and immediately if a cached source was removed from
    -- the generator. Some maps create progress values only after interaction.
    local cache = S.generatorProgressSourceCache[generator]
    local refresh = not cache or now - (cache.scannedAt or 0) > 0.75
    if cache and not refresh then
        for _, source in ipairs(cache.sources or {}) do
            local object = source.object
            local belongs = object == generator
            if not belongs and object then
                local ok, result = pcall(function() return object:IsDescendantOf(generator) end)
                belongs = ok and result
            end
            if not belongs then
                refresh = true
                break
            end
        end
        if not refresh then
            for _, source in ipairs(cache.completionSources or {}) do
                local object = source.object
                local belongs = object == generator
                if not belongs and object then
                    local ok, result = pcall(function() return object:IsDescendantOf(generator) end)
                    belongs = ok and result
                end
                if not belongs then
                    refresh = true
                    break
                end
            end
        end
    end
    if refresh then
        cache = S.__helpers.buildGeneratorProgressSources(generator)
        S.generatorProgressSourceCache[generator] = cache
    end

    -- Prefer an explicit completion flag when the game exposes one.
    local explicitlyCompleted = false
    for _, source in ipairs(cache.completionSources or {}) do
        local ok, rawValue = pcall(function()
            if source.kind == "attribute" then
                return source.object:GetAttribute(source.key)
            end
            return source.object.Value
        end)
        if ok and S.__helpers.isGeneratorCompletionValue(rawValue) then
            explicitlyCompleted = true
            state.completed = true
            break
        end
    end

    -- Start with the original direct lookup so existing Generator models that
    -- expose Progress exactly as before keep working.
    local currentProgress = S.__helpers.readDirectGeneratorProgress(generator)

    if currentProgress == nil then
        for _, source in ipairs(cache.sources or {}) do
            local object = source.object
            local belongs = object == generator
            if not belongs and object then
                local ok, result = pcall(function() return object:IsDescendantOf(generator) end)
                belongs = ok and result
            end
            if belongs then
                local ok, rawValue = pcall(function()
                    if source.kind == "attribute" then
                        return object:GetAttribute(source.key)
                    end
                    return object.Value
                end)
                if ok then
                    currentProgress = S.__helpers.coerceGeneratorPercent(rawValue)
                    if currentProgress ~= nil then break end
                end
            end
        end
    end

    -- Some maps put a progress value/attribute on the immediate parent container
    -- instead of on the Generator model. Only check clearly named progress sources
    -- there, rather than adopting arbitrary numeric siblings.
    if currentProgress == nil then
        local parent = generator.Parent
        if parent then
            local okAttributes, attributes = pcall(function() return parent:GetAttributes() end)
            if okAttributes and type(attributes) == "table" then
                for attributeName, rawValue in pairs(attributes) do
                    if S.__helpers.getGeneratorProgressSourcePriority(attributeName) then
                        currentProgress = S.__helpers.coerceGeneratorPercent(rawValue)
                        if currentProgress ~= nil then break end
                    end
                end
            end
            if currentProgress == nil then
                for _, sibling in ipairs(parent:GetChildren()) do
                    if sibling ~= generator then
                        local priority = S.__helpers.getGeneratorProgressSourcePriority(sibling.Name)
                        if priority then
                            if sibling:IsA("ValueBase") then
                                currentProgress = S.__helpers.coerceGeneratorPercent(sibling.Value)
                            else
                                local valueChild = sibling:FindFirstChildWhichIsA("ValueBase", true)
                                if valueChild then
                                    currentProgress = S.__helpers.coerceGeneratorPercent(valueChild.Value)
                                end
                            end
                            if currentProgress ~= nil then break end
                        end
                    end
                end
            end
        end
    end

    -- As a last fallback, use a percentage currently rendered inside the generator
    -- model (some variants expose progress only in a label rather than a Value).
    if currentProgress == nil then
        currentProgress = S.__helpers.readGeneratorPercentFromText(generator)
    end

    if currentProgress ~= nil then
        state.sourceSeen = true
        state.noSourceSince = nil
        state.lastProgress = currentProgress
        state.lastProgressAt = now
        -- A fresh, low progress value means this is active again rather than done.
        if explicitlyCompleted or currentProgress >= 99.95 then
            state.completed = true
        else
            state.completed = false
        end
    elseif state.sourceSeen and not explicitlyCompleted then
        state.noSourceSince = state.noSourceSince or now
        -- When the game removes its progress value on completion, keep the last
        -- reading briefly, then treat the vanished source as a completed generator.
        if now - state.noSourceSince >= 1.5 then
            state.completed = true
        end
    end

    -- Return the last observed progress while the game swaps/removes its progress
    -- object, so the ESP doesn't fall back to (?%) after a generator is finished.
    return currentProgress or state.lastProgress, state.completed == true
end

S.__helpers.isGeneratorESPObject = function(instance)
    if not instance then
        return false
    end

    -- Keep the existing exact-name FakeGenerator treatment.
    if instance.Name == "FakeGenerator" then
        return instance:IsA("Model") or instance:IsA("BasePart")
    end

    -- The reference identifies real generators as Models named "Generator"
    -- that contain a Main part, under Ingame/Map. This avoids accidentally
    -- highlighting nested generator parts, UI objects, or unrelated name matches.
    if not instance:IsA("Model") or instance.Name ~= "Generator" then
        return false
    end

    local main = instance:FindFirstChild("Main")
    if not main or not main:IsA("BasePart") then
        return false
    end

    local _, gameMap = S.getIngameFolders()
    if not gameMap then
        return false
    end

    local ok, insideMap = pcall(function()
        return instance:IsDescendantOf(gameMap)
    end)
    return ok and insideMap
end

S.__helpers.getGeneratorESPColors = function(generator)
    -- A user-selected color overrides the normal/fake/completed palette.
    if typeof(S.GENERATOR_ESP_COLOR_OVERRIDE) == "Color3" then
        local customColor = S.GENERATOR_ESP_COLOR_OVERRIDE
        return customColor, customColor:Lerp(Color3.fromRGB(255, 255, 255), 0.35)
    end

    -- Keep FakeGenerator's prior red treatment. Normal generators change color
    -- dynamically as their progress reaches completion.
    if generator and generator.Name == "FakeGenerator" then
        return Color3.fromRGB(150, 0, 0), Color3.fromRGB(255, 90, 90)
    end

    local progress, completed = S.__helpers.getGeneratorProgress(generator)
    if completed or (progress ~= nil and progress >= 99.95) then
        return Color3.fromRGB(0, 180, 70), Color3.fromRGB(100, 255, 140)
    end

    return Color3.fromRGB(255, 145, 0), Color3.fromRGB(255, 195, 85)
end

-- Puzzle Icons Over Generator(s): use the source file's puzzle icon assets,
-- sized small and tinted to the same fill color currently used by Generator ESP.
-- Generator Icon ESP: display the matching puzzle icon above each real generator.
-- FakeGenerator models are intentionally excluded, matching the supplied icon implementation.
S.__helpers.getGeneratorPuzzleIconAsset = function(generator)
    if not generator or generator.Name == "FakeGenerator" then
        return nil
    end

    local puzzle = generator:GetAttribute("Puzzle")
    if puzzle == nil then
        return nil
    end

    local puzzleName = tostring(puzzle)
    local direct = S.GENERATOR_PUZZLE_ICON_IDS[puzzleName]
    if direct then
        return direct
    end

    local normalized = puzzleName:lower():gsub("[^%w]", "")
    if normalized:find("connect", 1, true) then
        return S.GENERATOR_PUZZLE_ICON_IDS.ConnectServerMinigame
    elseif normalized:find("gear", 1, true) then
        return S.GENERATOR_PUZZLE_ICON_IDS.GearServerMinigame
    elseif normalized:find("flow", 1, true) then
        return S.GENERATOR_PUZZLE_ICON_IDS.FlowServerMinigame
    elseif normalized:find("lock", 1, true) then
        return S.GENERATOR_PUZZLE_ICON_IDS.LockServerMinigame
    end

    return nil
end

S.__helpers.createGeneratorPuzzleIcon = function(generator, id)
    if not S.isGeneratorESPEnabled or not S.isGeneratorPuzzleIconsEnabled then
        return nil
    end

    local assetId = S.__helpers.getGeneratorPuzzleIconAsset(generator)
    local target = generator and (generator:IsA("BasePart") and generator
        or generator:FindFirstChild("Main")
        or generator.PrimaryPart)
    if not assetId or not target or not target:IsA("BasePart") then
        return nil
    end

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "E1LU4HUB_GeneratorPuzzleIcon_" .. id
    billboard.Size = UDim2.fromOffset(20, 20)
    billboard.StudsOffset = Vector3.new(0, 4.6, 0)
    billboard.AlwaysOnTop = true
    billboard.LightInfluence = 0
    billboard.MaxDistance = S.GENERATOR_TEXT_MAX_DISTANCE
    billboard.Adornee = target

    local image = Instance.new("ImageLabel")
    image.Name = "PuzzleIcon"
    image.Size = UDim2.fromScale(1, 1)
    image.Position = UDim2.fromScale(0, 0)
    image.BackgroundTransparency = 1
    image.BorderSizePixel = 0
    image.ScaleType = Enum.ScaleType.Fit
    image.Image = "rbxassetid://" .. tostring(assetId)
    local fillColor = S.__helpers.getGeneratorESPColors(generator)
    image.ImageColor3 = fillColor
    image.Parent = billboard

    billboard.Parent = S.lp:FindFirstChildOfClass("PlayerGui") or S.lp:WaitForChild("PlayerGui")
    return billboard
end

S.__helpers.getGeneratorESPText = function(generator)
    if typeof(S.GENERATOR_ESP_COLOR_OVERRIDE) == "Color3" then
        local customColor = S.GENERATOR_ESP_COLOR_OVERRIDE
        if generator and generator.Name == "FakeGenerator" then
            return "Fake Generator", customColor
        end
        local progress, completed = S.__helpers.getGeneratorProgress(generator)
        if completed or (progress ~= nil and progress >= 99.95) then
            return "Generator | Done", customColor
        elseif progress ~= nil then
            return string.format("Generator | %d%%", math.floor(progress + 0.5)), customColor
        end
        return "Generator | ?%", customColor
    end

    -- Fake generators use red text so they are easy to identify.
    if generator and generator.Name == "FakeGenerator" then
        return "Fake Generator", S.GENERATOR_FAKE_TEXT_COLOR
    end

    local progress, completed = S.__helpers.getGeneratorProgress(generator)
    -- Completed generators use green text; unfinished progress remains white.
    if completed or (progress ~= nil and progress >= 99.95) then
        return "Generator | Done", S.GENERATOR_DONE_TEXT_COLOR
    end

    if progress ~= nil then
        return string.format(
            "Generator | %d%%",
            math.floor(progress + 0.5)
        ), S.GENERATOR_TEXT_COLOR
    end

    return "Generator | ?%", S.GENERATOR_TEXT_COLOR
end

S.__helpers.removeGeneratorESP = function(generator)
    if not generator then
        return
    end
    local id = S.__helpers.getGeneratorESPId(generator)
    local entry = S.generatorESPEntries[id]

    if entry then
        if entry.box then
            pcall(function() entry.box:Destroy() end)
        elseif entry.highlight then
            pcall(function() entry.highlight:Destroy() end)
        end
        if entry.label then
            pcall(function() entry.label:Destroy() end)
        end
        if entry.puzzleIcon then
            pcall(function() entry.puzzleIcon:Destroy() end)
        end
        S.generatorESPEntries[id] = nil
    else
        local rootFolder = workspace:FindFirstChild(S.ROOT_FOLDER_NAME)
    local folder = rootFolder and rootFolder:FindFirstChild(S.GENERATOR_ESP_FOLDER_NAME)
        if folder then
            local oldBox = folder:FindFirstChild(id)
            if oldBox then
                pcall(function() oldBox:Destroy() end)
            end
        end
    end
end

S.__helpers.addGeneratorESP = function(generator)
    if not S.isGeneratorESPEnabled
        or not S.__helpers.isGeneratorESPObject(generator) then
        return
    end

    local id = S.__helpers.getGeneratorESPId(generator)

    S.__helpers.removeGeneratorESP(generator)

    local folder = S.__helpers.getGeneratorESPFolder()

    local fillColor, outlineColor = S.__helpers.getGeneratorESPColors(generator)
    local box = S.__helpers.createReferenceESPBox(
        folder,
        id,
        generator,
        fillColor,
        outlineColor,
        0.38
    )

    local textGui = S.__helpers.getGeneratorESPTextGui()
    local label = Instance.new("TextLabel")
    label.Name = id
    label.AnchorPoint = Vector2.new(0.5, 1)
    label.Size = UDim2.fromOffset(190, 24)
    label.Position = UDim2.fromOffset(0, 0)
    label.BackgroundTransparency = 1
    label.BorderSizePixel = 0
    label.TextStrokeTransparency = 0
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    S.__helpers.applyESPTextFont(label)
    label.TextSize = S.GENERATOR_TEXT_SIZE
    label.TextXAlignment = Enum.TextXAlignment.Center
    label.TextYAlignment = Enum.TextYAlignment.Center
    label.Visible = false

    local labelText, labelColor = S.__helpers.getGeneratorESPText(generator)
    label.Text = labelText
    label.TextColor3 = labelColor
    label.Parent = textGui

    local puzzleIcon = S.__helpers.createGeneratorPuzzleIcon(generator, id)

    S.generatorESPEntries[id] = {
        generator = generator,
        box = box,
        label = label,
        puzzleIcon = puzzleIcon,
    }
end

S.__helpers.clearAllGeneratorESP = function()
    -- Puzzle icon BillboardGuis live under PlayerGui, so clear them explicitly.
    for _, entry in pairs(S.generatorESPEntries) do
        if entry.puzzleIcon then
            pcall(function() entry.puzzleIcon:Destroy() end)
            entry.puzzleIcon = nil
        end
    end

    local rootFolder = workspace:FindFirstChild(S.ROOT_FOLDER_NAME)
        local folder = rootFolder and rootFolder:FindFirstChild(S.GENERATOR_ESP_FOLDER_NAME)

    if folder then
        folder:ClearAllChildren()
    end

    local textGui = (S.lp:FindFirstChildOfClass("PlayerGui") or S.lp:WaitForChild("PlayerGui")):FindFirstChild(S.GENERATOR_TEXT_GUI_NAME)

    if textGui then
        textGui:ClearAllChildren()
    end

    table.clear(S.generatorESPEntries)
    table.clear(S.generatorProgressSourceCache)
    table.clear(S.generatorProgressState)
end

S.__helpers.updateAllGeneratorESP = function()
    if not S.isGeneratorESPEnabled then
        S.__helpers.clearAllGeneratorESP()
        return
    end

    S.__helpers.clearAllGeneratorESP()

    for _, obj in ipairs(workspace:GetDescendants()) do
        if S.__helpers.isGeneratorESPObject(obj) then
            S.__helpers.addGeneratorESP(obj)
        end
    end
end

S.__helpers.updateGeneratorESPTextPositions = function()
    if not S.isGeneratorESPEnabled then
        return
    end

    local camera = workspace.CurrentCamera

    if not camera then
        return
    end

    for id, entry in pairs(S.generatorESPEntries) do
        local generator = entry.generator
        local label = entry.label

        if not generator
            or not generator.Parent
            or not label
            or not label.Parent then

            if entry.box then
                pcall(function() entry.box:Destroy() end)
            elseif entry.highlight then
                pcall(function() entry.highlight:Destroy() end)
            end
            if entry.label then
                pcall(function() entry.label:Destroy() end)
            end
            if entry.puzzleIcon then
                pcall(function() entry.puzzleIcon:Destroy() end)
            end
            S.generatorESPEntries[id] = nil
            if generator then
                S.generatorProgressSourceCache[generator] = nil
                S.generatorProgressState[generator] = nil
            end
        else
            local position = S.__helpers.getGeneratorWorldPosition(generator)
            local labelText, labelColor = S.__helpers.getGeneratorESPText(generator)

            label.Text = labelText
            label.TextColor3 = labelColor
            label.Visible = S.isGeneratorESPTextEnabled

            -- Keep the matte fill and outline synchronized with generator progress.
            if entry.box and entry.box.Parent then
                local fillColor, outlineColor = S.__helpers.getGeneratorESPColors(generator)
                entry.box.FillColor = fillColor
                entry.box.OutlineColor = outlineColor
            end

            -- Some maps assign the Puzzle attribute shortly after the generator spawns.
            if not entry.puzzleIcon and S.isGeneratorPuzzleIconsEnabled then
                entry.puzzleIcon = S.__helpers.createGeneratorPuzzleIcon(generator, id)
            end
            if entry.puzzleIcon and entry.puzzleIcon.Parent then
                local fillColor = S.__helpers.getGeneratorESPColors(generator)
                local puzzleImage = entry.puzzleIcon:FindFirstChild("PuzzleIcon")
                if puzzleImage and puzzleImage:IsA("ImageLabel") then
                    puzzleImage.ImageColor3 = fillColor
                end
                entry.puzzleIcon.Enabled = S.isGeneratorESPEnabled
                    and S.isGeneratorPuzzleIconsEnabled
            end

            if position then
                local screenPosition, onScreen =
                    camera:WorldToViewportPoint(position)

                label.Position = UDim2.fromOffset(
                    screenPosition.X,
                    screenPosition.Y
                )

                -- Keep the text tied to the generator body's on-screen bounds,
                -- rather than showing it merely because its center projects on-screen.
                local bodyOnScreen = false
                local ok, boundsCFrame, boundsSize = pcall(function()
                    if generator:IsA("Model") then
                        return generator:GetBoundingBox()
                    elseif generator:IsA("BasePart") then
                        return generator.CFrame, generator.Size
                    end
                    return nil, nil
                end)

                if ok and boundsCFrame and boundsSize then
                    local half = boundsSize * 0.5
                    local minX, minY = math.huge, math.huge
                    local maxX, maxY = -math.huge, -math.huge
                    local hasFrontCorner = false

                    for _, sx in ipairs({-1, 1}) do
                        for _, sy in ipairs({-1, 1}) do
                            for _, sz in ipairs({-1, 1}) do
                                local corner = boundsCFrame:PointToWorldSpace(
                                    Vector3.new(half.X * sx, half.Y * sy, half.Z * sz)
                                )
                                local projected = camera:WorldToViewportPoint(corner)
                                if projected.Z > 0 then
                                    hasFrontCorner = true
                                    minX = math.min(minX, projected.X)
                                    minY = math.min(minY, projected.Y)
                                    maxX = math.max(maxX, projected.X)
                                    maxY = math.max(maxY, projected.Y)
                                end
                            end
                        end
                    end

                    local viewport = camera.ViewportSize
                    bodyOnScreen = hasFrontCorner
                        and maxX >= 0 and maxY >= 0
                        and minX <= viewport.X and minY <= viewport.Y
                else
                    bodyOnScreen = onScreen and screenPosition.Z > 0
                end

                local cameraDistance = (camera.CFrame.Position - position).Magnitude
                -- The position updater runs every frame, so the text toggle must
                -- be part of the final visibility condition or this assignment can
                -- show labels again after the toggle callback hides them.
                label.Visible =
                    S.isGeneratorESPTextEnabled
                    and bodyOnScreen
                    and onScreen
                    and screenPosition.Z > 0
                    and cameraDistance <= S.GENERATOR_TEXT_MAX_DISTANCE

            else
                label.Visible = false
            end
        end
    end
end

S.__helpers.connect(workspace.DescendantAdded, function(obj)
    if not S.isGeneratorESPEnabled or not S.__helpers.isGeneratorESPObject(obj) then
        return
    end

    task.wait(0.1)

    if S.isGeneratorESPEnabled and obj.Parent
        and S.__helpers.isGeneratorESPObject(obj) then
        S.__helpers.addGeneratorESP(obj)
    end
end)

S.__helpers.connect(workspace.DescendantRemoving, function(obj)
    if S.__helpers.isGeneratorESPObject(obj) then
        S.__helpers.removeGeneratorESP(obj)
        S.generatorProgressSourceCache[obj] = nil
        S.generatorProgressState[obj] = nil
    end
end)

S.__helpers.connect(S.RunService.RenderStepped, S.__helpers.updateGeneratorESPTextPositions)

