S.autoStandContainer = nil
S.autoRunContainer = nil
S.behindStudsBox = nil
S.pingToggleBtn = nil


-- ================================================================
-- E1LU4 HUB PORTED FEATURES (File 2 modules, File 1 base)
-- ================================================================
-- Direct ability activation for automation features.
-- This path never looks up a GuiButton and never fires MouseButton1Click/Activated.
-- It invokes the game's UseActorAbility RemoteEvent directly; the server remains
-- responsible for validating character, ability, and cooldown state.
S.__helpers.fireAbilityDirect = function(abilityName)
    if type(abilityName) ~= "string" or abilityName == "" then
        return false
    end

    local modules = S.ReplicatedStorage:FindFirstChild("Modules")
    local networkFolder = modules and modules:FindFirstChild("Network", true)
    local networkModule = networkFolder
        and (networkFolder:FindFirstChild("Network") or networkFolder)
    local remote = networkModule
        and (networkModule:FindFirstChildOfClass("RemoteEvent")
            or networkModule:FindFirstChild("RemoteEvent"))

    if not remote and S.getForsakenNetworkRemote then
        local ok, result = pcall(S.getForsakenNetworkRemote)
        if ok then remote = result end
    end
    if not remote or not remote:IsA("RemoteEvent") then
        return false
    end

    local ok = pcall(function()
        if abilityName == "Slash" or abilityName == "Clone" then
            -- File 2 sends Clone using the same length-prefixed buffer payload.
            local payload = buffer.fromstring(
                string.pack("<Bi4", 3, #abilityName) .. abilityName
            )
            remote:FireServer("UseActorAbility", {payload})
        else
            remote:FireServer("UseActorAbility", {abilityName})
        end
    end)
    return ok
end

-- File 2 Auto Clone: direct Clone activation from detected Killer swing sounds.
-- It remains independent of the Auto Block master switch.
S.__helpers.tryAutoClone = function(attacker, triggerSource)
    local v2 = S.AutoBlockV2
    if not v2 or not v2.autoClone then return false end

    local localCharacter = S.lp and S.lp.Character
    local localName = localCharacter and tostring(localCharacter.Name or ""):lower():gsub("%s+", "") or ""
    if localName ~= "007n7"
        or not S.__helpers.isLocalRole("Survivor")
        or not localCharacter
        or not S.isCharacterInRoleFolder(localCharacter, "Survivors") then
        return false
    end

    if not attacker or not attacker.Parent
        or not S.isCharacterInRoleFolder(attacker, "Killers") then
        return false
    end
    local attackerPlayer = S.Players:GetPlayerFromCharacter(attacker)
    if not attackerPlayer or attackerPlayer == S.lp then return false end

    if S.__helpers.isPlayingIgnoredAutoCloneAbility(attacker) then
        return false
    end

    local localRoot = localCharacter:FindFirstChild("HumanoidRootPart")
    local attackerRoot = attacker:FindFirstChild("HumanoidRootPart")
    if not localRoot or not attackerRoot then return false end

    -- Match File 2's audio prediction and range grace window before attempting Clone.
    local range = math.max(0.1, tonumber(S.autoBlockDetectionRange) or 18)
    local velocity = attackerRoot.AssemblyLinearVelocity or attackerRoot.Velocity or Vector3.zero
    local predictedPosition = attackerRoot.Position + velocity * 0.08
    local predictedDistance = (predictedPosition - localRoot.Position).Magnitude
    local currentDistance = (attackerRoot.Position - localRoot.Position).Magnitude
    if predictedDistance > range and currentDistance > range + 3 then
        return false
    end

    -- File 2's wall check excludes both participating character models.
    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.FilterDescendantsInstances = {localCharacter, attacker}
    rayParams.IgnoreWater = true
    local rayDirection = attackerRoot.Position - localRoot.Position
    local rayResult = workspace:Raycast(localRoot.Position, rayDirection, rayParams)
    if rayResult then return false end

    if S.isFacingCheckEnabled
        and not S.isKillerFacingTarget(attackerRoot, localRoot, range) then
        return false
    end

    local now = os.clock()
    if now - (tonumber(v2.lastActionAt) or 0) < 0.35 then return false end
    local readyCheck = S.__helpers.isV2AbilityReady
    if type(readyCheck) ~= "function" then return false end
    local readyOK, cloneReady = pcall(readyCheck, "Clone")
    if not readyOK or cloneReady ~= true then return false end

    local delayMs = math.max(0, tonumber(v2.delayMs) or 0)
    if delayMs > 0 then task.wait(delayMs / 1000) end

    if not v2.autoClone or localCharacter ~= S.lp.Character
        or not attacker.Parent
        or not S.isCharacterInRoleFolder(attacker, "Killers") then
        return false
    end
    local readyAgainOK, cloneReadyAgain = pcall(readyCheck, "Clone")
    if not readyAgainOK or cloneReadyAgain ~= true then return false end

    local fireOK, fired = pcall(S.__helpers.fireAbilityDirect, "Clone")
    if not fireOK or fired ~= true then return false end
    v2.lastActionAt = os.clock()
    task.spawn(S.__helpers.startFile2Aim, 0.4, "AutoClone")
    return true
end

-- Keep a compatibility wrapper for any later modules that still call the old name.
S.__helpers.runAutoBlockV2Attack = function(attacker, animType, track, detectionInfo)
    detectionInfo = type(detectionInfo) == "table" and detectionInfo or {}
    if detectionInfo.v2 ~= true then return false end
    if S.__helpers.isIgnoredAutoCloneAbility(animType) then return false end
    return S.__helpers.tryAutoClone(attacker, "Animation Compatibility")
end

