-- FORSAKENPLUS CHARACTER HELPERS
-- Added features: Better Void Rush, controllable c00lkidd dash, and
-- Jane Doe Auto Hatchet (automatically started; role and cooldown checks still apply).
-- ================================================================

S.BetterVoidRush = {enabled = false, applied = false, originals = {}}
S.__helpers.getNoliConfigTable = function()
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local killers = assets and assets:FindFirstChild("Killers")
    if not killers then return nil end

    local noli = killers:FindFirstChild("Noli")
    if not noli then
        for _, item in ipairs(killers:GetDescendants()) do
            if item:IsA("Model") and item.Name:lower():find("noli", 1, true) then
                noli = item
                break
            end
        end
    end
    if not noli then return nil end

    local configModule = noli:FindFirstChild("Config", true)
    if not configModule or not configModule:IsA("ModuleScript") then return nil end
    -- Prefer Roblox's cached require result so edits affect the same Config table
    -- the running game uses; only use the executor-compatible loader as fallback.
    local ok, config = pcall(require, configModule)
    if ok and type(config) == "table" then return config end
    if type(S.__helpers.__executorRequire) == "function" then
        local fallbackOK, fallbackConfig = pcall(S.__helpers.__executorRequire, configModule)
        if fallbackOK and type(fallbackConfig) == "table" then return fallbackConfig end
    end
    return nil
end

S.__helpers.setBetterVoidRush = function(enabled)
    local state = S.BetterVoidRush
    state.enabled = enabled == true

    local function restoreOriginals()
        for parent, entries in pairs(state.originals) do
            for key, original in pairs(entries) do
                pcall(function() parent[key] = original end)
            end
        end
        table.clear(state.originals)
        state.applied = false
    end

    -- Keep the toggle ON while off-role, but do not modify Killer configuration.
    -- Restore any prior values immediately if the local role changed away.
    if not state.enabled or not S.__helpers.isLocalRole("Killer") then
        restoreOriginals()
        return
    end
    if state.applied then return end
    state.applied = true

    local function applyConfig(config)
        if not state.enabled or not S.__helpers.isLocalRole("Killer")
            or type(config) ~= "table" then
            return false
        end
        local wanted = {
            InitialTurnDuration = 0.005,
            TurnSpeed = 10000,
            InitialTurnMult = 1000,
        }
        local seen = {}
        local found = 0
        local function scan(tbl)
            if type(tbl) ~= "table" or seen[tbl] then return end
            seen[tbl] = true
            for key, value in pairs(tbl) do
                if type(key) == "string" and type(value) == "number" then
                    for name, replacement in pairs(wanted) do
                        if key:find(name, 1, true) and not key:find("OG", 1, true) then
                            state.originals[tbl] = state.originals[tbl] or {}
                            if state.originals[tbl][key] == nil then
                                state.originals[tbl][key] = value
                            end
                            tbl[key] = replacement
                            found += 1
                            break
                        end
                    end
                elseif type(value) == "table" then
                    scan(value)
                end
            end
        end
        scan(config)
        return found > 0
    end

    local config = S.__helpers.getNoliConfigTable()
    if config then
        applyConfig(config)
    else
        task.spawn(function()
            for _ = 1, 40 do
                if not state.enabled or not S.__helpers.isLocalRole("Killer") then
                    return
                end
                task.wait(0.25)
                local retryConfig = S.__helpers.getNoliConfigTable()
                if retryConfig and applyConfig(retryConfig) then return end
            end
        end)
    end
end

S.C00lkiddDashControl = {
    enabled = false,
    originals = setmetatable({}, {__mode = "k"}),
    hinderedOriginals = setmetatable({}, {__mode = "k"}),
    responsiveness = 100,
}

S.__helpers.restoreC00lkiddDash = function()
    local state = S.C00lkiddDashControl
    for velocity, original in pairs(state.originals) do
        if velocity and velocity.Parent then
            pcall(function() velocity.LineDirection = original end)
        end
        state.originals[velocity] = nil
    end
    for item, original in pairs(state.hinderedOriginals) do
        if item and item.Parent then
            pcall(function() item.Value = original end)
        end
        state.hinderedOriginals[item] = nil
    end
end

S.__helpers.setC00lkiddDashControl = function(enabled)
    -- Preserve the selected state off-role; Heartbeat applies it only as Killer.
    S.C00lkiddDashControl.enabled = enabled == true
    if not S.C00lkiddDashControl.enabled or not S.__helpers.isLocalRole("Killer") then
        S.__helpers.restoreC00lkiddDash()
    end
end

S.__helpers.connect(S.RunService.Heartbeat, function()
    local state = S.C00lkiddDashControl
    if not state.enabled or not S.__helpers.isLocalRole("Killer") then
        if state.enabled then S.__helpers.restoreC00lkiddDash() end
        return
    end

    local character = S.lp and S.lp.Character
    local parentName = character and character.Parent and character.Parent.Name:lower() or ""
    local characterName = character and character.Name:gsub("0", "O"):lower() or ""
    local isCoolkidd = character and parentName:find("killer", 1, true)
        and (characterName:find("coolkid", 1, true) or characterName:find("c00lkidd", 1, true))
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not isCoolkidd or not root or not humanoid then
        S.__helpers.restoreC00lkiddDash()
        return
    end

    local speedMultipliers = character:FindFirstChild("SpeedMultipliers")
    if speedMultipliers then
        for _, multiplier in ipairs(speedMultipliers:GetChildren()) do
            if multiplier.Name == "HinderedMovement" and multiplier:IsA("NumberValue") and multiplier.Value == 0 then
                if state.hinderedOriginals[multiplier] == nil then
                    state.hinderedOriginals[multiplier] = multiplier.Value
                end
                multiplier.Value = 0.005
            end
        end
    end

    for _, child in ipairs(root:GetChildren()) do
        if child:IsA("LinearVelocity") then
            local okDirection, currentDirection = pcall(function() return child.LineDirection end)
            if okDirection and typeof(currentDirection) == "Vector3" then
                if state.originals[child] == nil then
                    state.originals[child] = currentDirection
                end
                local original = state.originals[child]
                local magnitude = original.Magnitude
                local move = humanoid.MoveDirection
                local flatMove = Vector3.new(move.X, 0, move.Z)
                local desired
                if flatMove.Magnitude > 0.001 then
                    desired = flatMove.Unit
                else
                    local camera = workspace.CurrentCamera
                    local look = camera and camera.CFrame.LookVector or root.CFrame.LookVector
                    local flatLook = Vector3.new(look.X, 0, look.Z)
                    if flatLook.Magnitude > 0.001 then
                        desired = flatLook.Unit
                        pcall(function()
                            root.CFrame = root.CFrame:Lerp(CFrame.lookAt(root.Position, root.Position + desired), 0.05)
                        end)
                    end
                end
                if desired then
                    pcall(function()
                        local alpha = math.clamp((tonumber(state.responsiveness) or 100) / 1000, 0, 1)
                        child.LineDirection = currentDirection:Lerp(desired * magnitude, alpha)
                    end)
                end
            end
        end
    end
end)

S.JaneDoeAutoHatchet = {
    enabled = false,
    connection = nil,
    lastFire = 0,
    range = 13,
    minimumLevel = 2,
    accumulator = 0,
}

S.__helpers.getJaneDoeHatchetLevel = function(rootPart)
    if not rootPart then return 0 end
    local resonance = S.ReplicatedStorage:FindFirstChild("Resonance", true)
    local levels = resonance and resonance:FindFirstChild("ParticleHolder", true)
    if not levels then return 0 end
    local level = 0
    for _, attachment in ipairs(levels:GetChildren()) do
        if attachment:IsA("Attachment") then
            local number = tonumber(attachment.Name:match("%d+"))
            if number and number > level then
                local matches = true
                for _, effect in ipairs(attachment:GetChildren()) do
                    if not rootPart:FindFirstChild(effect.Name) then
                        matches = false
                        break
                    end
                end
                if matches then level = number end
            end
        end
    end
    return level
end

S.__helpers.findReadyJaneDoeHatchet = function()
    local mainUI = S.__helpers.getMainUI()
    local container = mainUI and mainUI:FindFirstChild("AbilityContainer")
    if not container then return nil end
    for _, ability in ipairs(container:GetChildren()) do
        if ability.Name == "Hatchet" or ability.Name == "Axe" then
            local clipping = ability:FindFirstChild("Clipping")
            if clipping and clipping.Visible and clipping.Size.Y.Scale >= 0.99 then
                return ability
            end
        end
    end
    return nil
end

S.__helpers.getClosestPlayerKillerForJane = function(maxDistance, localRoot)
    local playersFolder = workspace:FindFirstChild("Players")
    local killerFolder = playersFolder and playersFolder:FindFirstChild("Killers")
    if not killerFolder or not localRoot then return nil, nil end
    local selected, shortest = nil, maxDistance or 13
    for _, killer in ipairs(killerFolder:GetChildren()) do
        local player = S.Players:GetPlayerFromCharacter(killer)
        local root = killer:FindFirstChild("HumanoidRootPart")
        local humanoid = killer:FindFirstChildOfClass("Humanoid")
        if player and root and humanoid and humanoid.Health > 0 then
            local distance = (root.Position - localRoot.Position).Magnitude
            if distance <= shortest then
                shortest, selected = distance, killer
            end
        end
    end
    return selected, shortest
end

S.JaneDoeAutoHatchet.setEnabled = function(enabled)
    local state = S.JaneDoeAutoHatchet
    state.token = (state.token or 0) + 1
    state.enabled = enabled == true
    if state.connection then
        pcall(function() state.connection:Disconnect() end)
        state.connection = nil
    end
    if not state.enabled then
        state.busy = false
        return
    end

    state.accumulator = 0
    state.busy = false
    state.connection = S.RunService.Heartbeat:Connect(function(dt)
        if not state.enabled or state.busy then return end
        state.accumulator = state.accumulator + (tonumber(dt) or 0)
        if state.accumulator < 0.1 then return end
        state.accumulator = 0

        local character = S.lp and S.lp.Character
        local parent = character and character.Parent
        local parentName = parent and tostring(parent.Name):lower() or ""
        local characterName = character and tostring(character.Name):lower() or ""
        if not character or not parentName:find("survi", 1, true)
            or not characterName:find("jane", 1, true)
            or character:GetAttribute("DoingActionPower")
            or character:GetAttribute("DisableShiftLockMovement") then
            return
        end

        local root = character:FindFirstChild("HumanoidRootPart")
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local ability = S.__helpers.findReadyJaneDoeHatchet()
        if not root or not humanoid or humanoid.Health <= 0 or not ability
            or os.clock() - state.lastFire < 1.8 then
            return
        end

        -- Auto Hatchet source behavior: require a nearby player-controlled killer,
        -- resonance at/above the threshold, and no InvincibleFX on the target.
        local killer, distance = S.__helpers.getClosestPlayerKillerForJane(state.range, root)
        local killerRoot = killer and killer:FindFirstChild("HumanoidRootPart")
        if not killerRoot or not distance or distance > state.range
            or S.__helpers.getJaneDoeHatchetLevel(killerRoot) < state.minimumLevel
            or killerRoot:FindFirstChild("InvincibleFX") then
            return
        end

        state.busy = true
        local operationToken = state.token
        task.spawn(function()
            local oldDisableShiftLock = character:GetAttribute("DisableShiftLockMovement")
            local previousVelocity = nil
            local rootForCleanup = root
            local fired = false

            local function faceCurrentTarget()
                if not state.enabled or state.token ~= operationToken
                    or not character.Parent or character ~= (S.lp and S.lp.Character) then
                    return false
                end
                local currentRoot = character:FindFirstChild("HumanoidRootPart")
                local currentTargetRoot = killer and killer.Parent and killer:FindFirstChild("HumanoidRootPart")
                if not currentRoot or not currentTargetRoot then return false end
                local targetPosition = Vector3.new(
                    currentTargetRoot.Position.X,
                    currentRoot.Position.Y,
                    currentTargetRoot.Position.Z
                )
                pcall(function() currentRoot.CFrame = CFrame.lookAt(currentRoot.Position, targetPosition) end)
                return true
            end

            local runOk, runErr = pcall(function()
                if not faceCurrentTarget() then return end
                if S.JaneDoeAssists then
                    S.JaneDoeAssists.axeActionUntil = os.clock() + 1.3
                    if S.JaneDoeAssists.axeLockEnabled then
                        S.JaneDoeAssists.axeLockUntil = os.clock() + (tonumber(S.JaneDoeAssists.axeLockDuration) or 1.7)
                    end
                end

                character:SetAttribute("DoingActionPower", true)
                fired = S.__helpers.fireAbilityDirect(ability.Name)
                if not fired then return end
                state.lastFire = os.clock()

                -- First face the target for 0.6s, as in the source AutoHatchet loop.
                local faceUntil = os.clock() + 0.6
                while state.enabled and state.token == operationToken and os.clock() < faceUntil do
                    if not faceCurrentTarget() then break end
                    task.wait(1 / 30)
                end

                if state.enabled and state.token == operationToken
                    and character.Parent and character == (S.lp and S.lp.Character)
                    and rootForCleanup.Parent then
                    character:SetAttribute("DisableShiftLockMovement", true)
                    local timeout = workspace.DistributedGameTime + 1
                    local fovMultipliers = character:FindFirstChild("FOVMultipliers")
                    repeat
                        if not state.enabled or state.token ~= operationToken or not faceCurrentTarget() then break end
                        local currentRoot = character:FindFirstChild("HumanoidRootPart")
                        if currentRoot and killer and killer.Parent then
                            local currentTargetRoot = killer:FindFirstChild("HumanoidRootPart")
                            if currentTargetRoot then
                                local direction = Vector3.new(
                                    currentTargetRoot.Position.X - currentRoot.Position.X,
                                    0,
                                    currentTargetRoot.Position.Z - currentRoot.Position.Z
                                )
                                if direction.Magnitude > 0.001 then
                                    if not previousVelocity then
                                        previousVelocity = direction.Unit * 45
                                        currentRoot.AssemblyLinearVelocity = previousVelocity
                                    else
                                        local accuracy = 0.8
                                        previousVelocity = currentRoot.AssemblyLinearVelocity:Lerp(previousVelocity, accuracy)
                                        currentRoot.AssemblyLinearVelocity = previousVelocity
                                    end
                                end
                            end
                        end
                        if fovMultipliers and fovMultipliers:FindFirstChild("HitRegistered") then break end
                        task.wait(0.05)
                    until workspace.DistributedGameTime > timeout

                    local finalRoot = character:FindFirstChild("HumanoidRootPart")
                    if finalRoot then
                        pcall(function() finalRoot.AssemblyLinearVelocity = finalRoot.AssemblyLinearVelocity * 0.15 end)
                    end
                    task.wait(0.1)
                end
            end)

            -- Always restore attributes modified by this routine, even if an API call fails
            -- or the feature is switched off mid-action.
            pcall(function()
                if character and character.Parent then
                    character:SetAttribute("DisableShiftLockMovement", oldDisableShiftLock)
                    character:SetAttribute("DoingActionPower", nil)
                end
            end)
            if not runOk then
                warn("Jane Doe Auto Hatchet failed: " .. tostring(runErr))
            end
            if state.token == operationToken then
                state.busy = false
            end
        end)
    end)
end

-- ================================================================
-- JANE DOE AIMBOT / AXE LOCK-ON (adapted from source file #3)
-- Aimbot intercepts Jane Doe GetMousePosition/GetCameraCF requests with
-- velocity prediction. Axe Lock-On faces the nearest killer during the
-- configured window after an Axe/Hatchet action. Other RF requests are passed
-- through to the callback that was active before installation.
-- ================================================================
S.JaneDoeAssists = {
    aimbotEnabled = false,
    axeLockEnabled = false,
    crystalActionUntil = 0,
    axeActionUntil = 0,
    axeLockUntil = 0,
    axeLockDuration = 1.7,
    axeLockHumanoid = nil,
    axeOriginalAutoRotate = nil,
    aimOffset = -0.3,
    prediction = 0.6,
    killerMotionData = {},
    dispatcher = {
        hooks = {},
        installed = false,
        originalCallback = nil,
        activeRemote = nil,
    },
    axeRemoteConnection = nil,
}

-- Jane Doe Crystal controls (ported from Nyxsaken's Crystal callback hook).
-- Instant Throw sets both charge limits to 0.01s; Infinite Hold sets a large,
-- finite MaximumHoldTime. Each touched Config table is backed up once and restored
-- independently when its corresponding option is switched OFF.
S.JaneDoeInstantThrow = {
    enabled = false,
    infiniteHoldEnabled = false,
    hookInstalled = false,
    originalCallback = nil,
    backups = setmetatable({}, {__mode = "k"}),
}

S.__helpers.applyJaneDoeCrystalConfig = function(config)
    local state = S.JaneDoeInstantThrow
    if type(config) ~= "table" then return false end

    local ok = pcall(function()
        local originalReadonly = nil
        if type(isreadonly) == "function" then
            local readOnlyOK, readOnlyValue = pcall(isreadonly, config)
            if readOnlyOK then originalReadonly = readOnlyValue == true end
        end
        if type(setreadonly) == "function" then
            pcall(setreadonly, config, false)
        end

        local backup = state.backups[config]
        if not backup then
            backup = {
                min = rawget(config, "MinChargeTime"),
                max = rawget(config, "MaxChargeTime"),
                hold = rawget(config, "MaximumHoldTime"),
                readonly = originalReadonly,
            }
            state.backups[config] = backup
        end

        if state.enabled then
            rawset(config, "MinChargeTime", 0.01)
            rawset(config, "MaxChargeTime", 0.01)
        else
            rawset(config, "MinChargeTime", backup.min)
            rawset(config, "MaxChargeTime", backup.max)
        end

        if state.infiniteHoldEnabled then
            -- A large finite value avoids inf/NaN in the game's charge math.
            rawset(config, "MaximumHoldTime", 1e9)
        else
            rawset(config, "MaximumHoldTime", backup.hold)
        end

        if originalReadonly ~= nil and type(setreadonly) == "function" then
            pcall(setreadonly, config, originalReadonly)
        end
    end)
    return ok
end

S.__helpers.restoreJaneDoeCrystalConfig = function()
    local state = S.JaneDoeInstantThrow
    for config, backup in pairs(state.backups) do
        pcall(function()
            if type(setreadonly) == "function" then pcall(setreadonly, config, false) end
            rawset(config, "MinChargeTime", backup.min)
            rawset(config, "MaxChargeTime", backup.max)
            rawset(config, "MaximumHoldTime", backup.hold)
            if backup.readonly ~= nil and type(setreadonly) == "function" then
                pcall(setreadonly, config, backup.readonly)
            end
        end)
        state.backups[config] = nil
    end
end

S.__helpers.applyJaneDoeCrystalInstantThrow = function()
    local state = S.JaneDoeInstantThrow
    local behaviorModule = nil
    pcall(function()
        local assets = S.ReplicatedStorage:FindFirstChild("Assets")
        local survivors = assets and assets:FindFirstChild("Survivors")
        local janeDoe = survivors and survivors:FindFirstChild("JaneDoe")
        behaviorModule = janeDoe and janeDoe:FindFirstChild("Behavior")
    end)
    if not behaviorModule or not behaviorModule:IsA("ModuleScript")
        or type(hookfunction) ~= "function" then
        return false
    end

    local ok, behavior = pcall(require, behaviorModule)
    if not ok or type(behavior) ~= "table" then return false end
    local crystal = behavior.Abilities and behavior.Abilities.Crystal
    if not crystal or type(crystal.Callback) ~= "function" then return false end

    if not state.hookInstalled then
        local originalCallback = crystal.Callback
        local previousCallback = nil
        local hookOK, hookedOriginal = pcall(function()
            return hookfunction(originalCallback, function(actor, context, ...)
                if state.enabled or state.infiniteHoldEnabled then
                    pcall(function()
                        local config = type(actor) == "table"
                            and type(actor.Config) == "table"
                            and actor.Config.Crystal
                        if type(config) == "table" then
                            S.__helpers.applyJaneDoeCrystalConfig(config)
                        end
                    end)
                end
                local callbackToCall = previousCallback or originalCallback
                return callbackToCall(actor, context, ...)
            end)
        end)
        if not hookOK or type(hookedOriginal) ~= "function" then
            return false
        end
        previousCallback = hookedOriginal
        state.originalCallback = hookedOriginal
        state.hookInstalled = true
    end

    -- Re-apply the current combination to any config already seen by the hook.
    for config in pairs(state.backups) do
        S.__helpers.applyJaneDoeCrystalConfig(config)
    end
    return true
end

S.__helpers.setJaneDoeInstantThrow = function(enabled)
    local state = S.JaneDoeInstantThrow
    state.enabled = enabled == true
    if state.enabled or state.infiniteHoldEnabled then
        local ok = S.__helpers.applyJaneDoeCrystalInstantThrow()
        if not ok then
            warn("[E1LU4HUB] Jane Doe Crystal callback hook is unavailable")
        end
    end
    if not state.enabled and not state.infiniteHoldEnabled then
        S.__helpers.restoreJaneDoeCrystalConfig()
    else
        for config in pairs(state.backups) do
            S.__helpers.applyJaneDoeCrystalConfig(config)
        end
    end
    return state.hookInstalled
end

S.__helpers.setJaneDoeInfiniteCrystalHold = function(enabled)
    local state = S.JaneDoeInstantThrow
    state.infiniteHoldEnabled = enabled == true
    if state.enabled or state.infiniteHoldEnabled then
        local ok = S.__helpers.applyJaneDoeCrystalInstantThrow()
        if not ok then
            warn("[E1LU4HUB] Jane Doe Crystal callback hook is unavailable")
        end
    end
    if not state.enabled and not state.infiniteHoldEnabled then
        S.__helpers.restoreJaneDoeCrystalConfig()
    else
        for config in pairs(state.backups) do
            S.__helpers.applyJaneDoeCrystalConfig(config)
        end
    end
    return state.hookInstalled
end

S.__helpers.isLocalJaneDoe = function()
    local character = S.lp and S.lp.Character
    if not character or not S.__helpers.isLocalRole("Survivor") then
        return false
    end
    return tostring(character.Name or ""):lower():find("jane", 1, true) ~= nil
end

S.__helpers.getJaneNetworkRemote = function(remoteName)
    local modules = S.ReplicatedStorage:FindFirstChild("Modules")
    local network = modules and modules:FindFirstChild("Network")
    local networkModule = network and network:FindFirstChild("Network")
    return networkModule and networkModule:FindFirstChild(remoteName)
end

S.__helpers.getJaneKillerVelocity = function(rootPart)
    if not rootPart then return Vector3.zero end
    local state = S.JaneDoeAssists
    local now = os.clock()
    local position = rootPart.Position
    local data = state.killerMotionData[rootPart]
    if not data then
        state.killerMotionData[rootPart] = {
            lastPos = position,
            lastTime = now,
            velocity = Vector3.zero,
        }
        return Vector3.zero
    end
    local elapsed = now - (data.lastTime or now)
    if elapsed <= 0 then return data.velocity or Vector3.zero end
    local velocity = (position - data.lastPos) / elapsed
    data.lastPos = position
    data.lastTime = now
    data.velocity = velocity
    return velocity
end

S.__helpers.buildJaneAimCameraCF = function(myRoot, killerRoot, projectileSpeed, gravity)
    local ok, result = pcall(function()
        local camera = workspace.CurrentCamera
        if not camera then return nil end
        local humanoid = myRoot.Parent and myRoot.Parent:FindFirstChildOfClass("Humanoid")
        local hipHeight = humanoid and humanoid.HipHeight or 1.35
        local offsetY = (hipHeight + myRoot.Size.Y / 2) / 2
        local spawnPosition = myRoot.Position + Vector3.new(0, offsetY, 0)
        local velocity = S.__helpers.getJaneKillerVelocity(killerRoot)
        local predicted = killerRoot.Position + velocity * (tonumber(S.JaneDoeAssists.prediction) or 0.6)
        local target = predicted + Vector3.new(0, tonumber(S.JaneDoeAssists.aimOffset) or -0.3, 0)
        local delta = target - spawnPosition
        local flatVector = Vector3.new(delta.X, 0, delta.Z)
        local horizontalDistance, verticalDistance = flatVector.Magnitude, delta.Y
        if horizontalDistance < 0.01 then
            local direction = verticalDistance >= 0 and Vector3.new(0, 1, 0) or Vector3.new(0, -1, 0)
            return CFrame.new(camera.CFrame.Position, camera.CFrame.Position + direction)
        end
        local flatDirection = flatVector.Unit
        local speed = tonumber(projectileSpeed) or 250
        local grav = tonumber(gravity) or 40
        local speedSquared = speed * speed
        local discriminant = speedSquared * speedSquared
            - grav * (grav * horizontalDistance * horizontalDistance + 2 * verticalDistance * speedSquared)
        local theta = discriminant < 0
            and math.atan2(verticalDistance, horizontalDistance)
            or math.atan2(speedSquared - math.sqrt(discriminant), grav * horizontalDistance)
        local tangent = math.tan(theta)
        local denominator = 3 + tangent
        local alpha = math.abs(denominator) < 0.0001
            and -math.pi / 2
            or math.atan2(3 * tangent - 1, denominator)
        local yaw = CFrame.new(camera.CFrame.Position, camera.CFrame.Position + flatDirection)
        return yaw * CFrame.Angles(alpha, 0, 0)
    end)
    return ok and result or nil
end

S.__helpers.getJaneAimbotTarget = function(maxDistance)
    local character = S.lp and S.lp.Character
    local localRoot = character and character:FindFirstChild("HumanoidRootPart")
    if not localRoot then return nil, nil end
    local target, distance = S.__helpers.getClosestForsakenKiller(maxDistance or 125)
    if not target then return nil, nil end
    local targetRoot = target:FindFirstChild("HumanoidRootPart")
    if not targetRoot then return nil, nil end
    return target, distance
end

S.JaneDoeAssists.dispatcher.register = function(self, id, callback)
    self.hooks[id] = callback
end
S.JaneDoeAssists.dispatcher.unregister = function(self, id)
    self.hooks[id] = nil
end
S.JaneDoeAssists.dispatcher.install = function(self, remoteFunction)
    if self.installed or not remoteFunction then return self.installed end
    self.activeRemote = remoteFunction
    local gotCallback = false
    if typeof(getcallbackvalue) == "function" then
        gotCallback = pcall(function()
            self.originalCallback = getcallbackvalue(remoteFunction, "OnClientInvoke")
        end)
    end
    if not gotCallback or self.originalCallback == nil then
        local ok, callback = pcall(function() return remoteFunction.OnClientInvoke end)
        if ok then self.originalCallback = callback end
    end

    local dispatcher = self
    local assigned = pcall(function()
        remoteFunction.OnClientInvoke = function(requestName, ...)
            if requestName == "GetMousePosition" or requestName == "GetCameraCF" then
                for _, hook in pairs(dispatcher.hooks) do
                    local ok, result = pcall(hook, requestName, ...)
                    if ok and result ~= nil then return result end
                end
            end
            if dispatcher.originalCallback then
                local ok, result = pcall(dispatcher.originalCallback, requestName, ...)
                if ok then return result end
            end
            return nil
        end
    end)
    self.installed = assigned
    if not assigned then
        self.activeRemote = nil
        self.originalCallback = nil
    end
    return assigned
end
S.JaneDoeAssists.dispatcher.uninstall = function(self)
    if not self.installed then return end
    local remoteFunction = self.activeRemote
    local callback = self.originalCallback
    if remoteFunction then
        pcall(function() remoteFunction.OnClientInvoke = callback end)
    end
    self.hooks = {}
    self.originalCallback = nil
    self.installed = false
    self.activeRemote = nil
end

S.__helpers.installJaneAimbotHook = function()
    local state = S.JaneDoeAssists
    local dispatcher = state.dispatcher
    local remoteFunction = S.__helpers.getJaneNetworkRemote("RemoteFunction")
    if not remoteFunction then return false end
    if not dispatcher:install(remoteFunction) then return false end
    dispatcher:register("jane_doe_silent_aim", function(requestName)
        if not state.aimbotEnabled or not S.__helpers.isLocalJaneDoe() then return nil end
        local character = S.lp and S.lp.Character
        local myRoot = character and character:FindFirstChild("HumanoidRootPart")
        if not myRoot then return nil end
        local target, distance = S.__helpers.getJaneAimbotTarget(125)
        local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
        if not targetRoot or (distance and distance > 125) then return nil end
        if requestName == "GetMousePosition" then
            local velocity = S.__helpers.getJaneKillerVelocity(targetRoot)
            return targetRoot.Position + velocity * (tonumber(state.prediction) or 0.6)
                + Vector3.new(0, tonumber(state.aimOffset) or -0.3, 0)
        elseif requestName == "GetCameraCF" then
            return S.__helpers.buildJaneAimCameraCF(myRoot, targetRoot, 250, 40)
        end
        return nil
    end)
    return true
end

S.__helpers.setJaneAimbot = function(enabled)
    local state = S.JaneDoeAssists
    state.aimbotEnabled = enabled == true
    if state.aimbotEnabled then
        S.__helpers.installJaneAimbotHook()
    else
        state.dispatcher:unregister("jane_doe_silent_aim")
        if next(state.dispatcher.hooks) == nil then
            state.dispatcher:uninstall()
        end
    end
end

S.__helpers.restoreJaneAxeLockRotation = function()
    local state = S.JaneDoeAssists
    if state.axeLockHumanoid and state.axeLockHumanoid.Parent
        and state.axeOriginalAutoRotate ~= nil then
        pcall(function() state.axeLockHumanoid.AutoRotate = state.axeOriginalAutoRotate end)
    end
    state.axeLockHumanoid = nil
    state.axeOriginalAutoRotate = nil
end

S.__helpers.setJaneAxeLock = function(enabled)
    local state = S.JaneDoeAssists
    state.axeLockEnabled = enabled == true
    if not state.axeLockEnabled then
        state.axeLockUntil = 0
        S.__helpers.restoreJaneAxeLockRotation()
        if state.axeRemoteConnection then
            pcall(function() state.axeRemoteConnection:Disconnect() end)
            state.axeRemoteConnection = nil
        end
    end
end

-- The source file's Axe listener looks for the Axe ability remote event.
-- Input E is also handled directly so lock-on works even if that event is not
-- echoed back to the client.
S.__helpers.connect(S.UserInputService.InputBegan, function(input)
    if not S.__helpers.isLocalJaneDoe() then return end
    local state = S.JaneDoeAssists
    if input.KeyCode == Enum.KeyCode.Q then
        state.crystalActionUntil = os.clock() + 2.1
    elseif input.KeyCode == Enum.KeyCode.E then
        state.axeActionUntil = os.clock() + 1.35
        if state.axeLockEnabled then
            state.axeLockUntil = os.clock() + (tonumber(state.axeLockDuration) or 1.7)
        end
    end
end)
S.__helpers.connect(S.UserInputService.InputEnded, function(input)
    if not S.__helpers.isLocalJaneDoe() then return end
    local state = S.JaneDoeAssists
    if input.KeyCode == Enum.KeyCode.Q then
        state.crystalActionUntil = os.clock() + 0.25
    elseif input.KeyCode == Enum.KeyCode.E then
        state.axeActionUntil = math.max(state.axeActionUntil or 0, os.clock() + 0.65)
    end
end)

-- Re-attempt the silent-aim hook if the network RemoteFunction is not ready yet.
S.__helpers.connect(S.RunService.Heartbeat, function(dt)
    local state = S.JaneDoeAssists
    if state.aimbotEnabled and not state.dispatcher.installed then
        S.__helpers.installJaneAimbotHook()
    end

    if not state.axeLockEnabled or os.clock() > (state.axeLockUntil or 0)
        or not S.__helpers.isLocalJaneDoe() then
        S.__helpers.restoreJaneAxeLockRotation()
        return
    end
    local character = S.lp and S.lp.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid then
        S.__helpers.restoreJaneAxeLockRotation()
        return
    end
    if state.axeLockHumanoid ~= humanoid then
        S.__helpers.restoreJaneAxeLockRotation()
        state.axeLockHumanoid = humanoid
        state.axeOriginalAutoRotate = humanoid.AutoRotate
        pcall(function() humanoid.AutoRotate = false end)
    end
    local target = S.__helpers.getClosestForsakenKiller(125)
    local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
    if not targetRoot then
        S.__helpers.restoreJaneAxeLockRotation()
        return
    end
    local targetPosition = Vector3.new(targetRoot.Position.X, root.Position.Y, targetRoot.Position.Z)
    local desired = CFrame.lookAt(root.Position, targetPosition, Vector3.new(0, 1, 0))
    local alpha = math.clamp((tonumber(dt) or 1 / 60) * 42, 0, 1)
    pcall(function() root.CFrame = root.CFrame:Lerp(desired, alpha) end)
end)

S.__helpers.connect(S.RunService.Heartbeat, function()
    local state = S.JaneDoeAssists
    if state.axeLockEnabled and not state.axeRemoteConnection then
        local remote = S.__helpers.getJaneNetworkRemote("RemoteEvent")
        if remote then
            local ok, connection = pcall(function()
                return remote.OnClientEvent:Connect(function(...)
                    if not state.axeLockEnabled or not S.__helpers.isLocalJaneDoe() then return end
                    local args = {...}
                    if args[1] == "UseActorAbility" and args[2] and args[2][1] then
                        local bufferOk, raw = pcall(function() return buffer.tostring(args[2][1]) end)
                        if bufferOk and raw and raw:lower():find("axe", 1, true) then
                            state.axeActionUntil = os.clock() + (tonumber(state.axeLockDuration) or 1.7)
                            state.axeLockUntil = state.axeActionUntil
                        end
                    end
                end)
            end)
            if ok then state.axeRemoteConnection = connection end
        end
    elseif not state.axeLockEnabled and state.axeRemoteConnection then
        pcall(function() state.axeRemoteConnection:Disconnect() end)
        state.axeRemoteConnection = nil
    end
end)

-- Shared ForsakenPlus network resolver used by Auto Escape.
S.getForsakenNetworkRemote = function()
    local modules = S.ReplicatedStorage:FindFirstChild("Modules")
    local network = modules and modules:FindFirstChild("Network", true)
    local networkModule = network and (network:FindFirstChild("Network") or network)
    return networkModule and networkModule:FindFirstChildOfClass("RemoteEvent")
end


