S.AutoRagingPace = S.AutoRagingPace or {
    enabled = false,
    radius = 18,
    cooldown = 0.8,
    lastFire = 0,
    spamDuration = 3,
    detectionCooldown = 5,
    workerToken = 0,
    ragingPaceAnimations = {
        ["116618003477002"] = true,
        ["119462383658044"] = true,
        ["131696603025265"] = true,
        ["121255898612475"] = true,
        ["133491532453922"] = true,
        ["103601716322988"] = true,
        ["86371356500204"] = true,
        ["72722244508749"] = true,
        ["87259391926321"] = true,
        ["96959123077498"] = true,
    },
    errorAnimations = {
        ["116618003477002"] = true,
