    },
    ragingPaceActiveCooldowns = {},
    errorActiveCooldowns = {},
    connections = {},
}
S.AutoRagingPace.disconnect = function()
    local state = S.AutoRagingPace
    for _, connection in ipairs(state.connections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(state.connections)
end
S.AutoRagingPace.hasNearbySurvivor = function(radius)
    local character = S.lp and S.lp.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local playersFolder = workspace:FindFirstChild("Players")
    local survivors = playersFolder and playersFolder:FindFirstChild("Survivors")
    if not root or not survivors then return false end
    for _, survivor in ipairs(survivors:GetChildren()) do
        if survivor:IsA("Model") and survivor ~= character then
            local humanoid = survivor:FindFirstChildOfClass("Humanoid")
            local theirRoot = survivor:FindFirstChild("HumanoidRootPart")
            if humanoid and humanoid.Health > 0 and theirRoot
                and (theirRoot.Position - root.Position).Magnitude <= radius then
                return true
            end
        end
    end
    return false
end
S.AutoRagingPace.fire = function(radiusOverride)
    local state = S.AutoRagingPace
    if not state.enabled or not S.__helpers.isLocalRole("Killer") then return false end
    if os.clock() - state.lastFire < state.cooldown then return false end
    if not S.AutoRagingPace.hasNearbySurvivor(tonumber(radiusOverride) or state.radius) then return false end
    local character = S.lp and S.lp.Character
    if not character then return false end
    local characterName = tostring(character.Name):lower():gsub("%s+", "")
    local ability
    if characterName == "slasher" then
        ability = "RagingPace"
    elseif characterName == "johndoe" then
        ability = "404Error"
    else
        return false
    end
    -- Keep the existing ability cooldown/readiness guard before firing.
    local readyCheck = S.__helpers and S.__helpers.isV2AbilityReady
    if type(readyCheck) ~= "function" then return false end
    local readyOK, isReady = pcall(readyCheck, ability)
    if not readyOK or isReady ~= true then return false end
    local fired = false
    if S.__helpers.fireCursedsakenAbilityDirect then
        fired = S.__helpers.fireCursedsakenAbilityDirect(ability) == true
    else
        local remote = S.getForsakenNetworkRemote and S.getForsakenNetworkRemote()
        if remote and remote:IsA("RemoteEvent") and type(buffer) == "table" and type(buffer.fromstring) == "function" then
            local packedOK, payload = pcall(function()
                return buffer.fromstring(string.pack("<Bi4", 3, #ability) .. ability)
            end)
            if packedOK and payload then
                fired = pcall(function() remote:FireServer("UseActorAbility", {payload}) end)
            end
        end
    end
    if fired then state.lastFire = os.clock() end
    return fired
end
S.AutoRagingPace.checkAnimations = function()
    local state = S.AutoRagingPace
    if not state.enabled or not S.__helpers.isLocalRole("Killer") then return end

    local localCharacter = S.lp and S.lp.Character
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    if not localCharacter or not localRoot then return end

    local characterName = tostring(localCharacter.Name):lower():gsub("%s+", "")
    local animationSet
    local cooldowns
    if characterName == "slasher" then
        animationSet = state.ragingPaceAnimations
        cooldowns = state.ragingPaceActiveCooldowns
    elseif characterName == "johndoe" then
        animationSet = state.errorAnimations
        cooldowns = state.errorActiveCooldowns
    else
        return
    end

    local currentTime = os.clock()
    for _, player in ipairs(S.Players:GetPlayers()) do
        if player ~= S.lp then
            local targetCharacter = player.Character
            local targetRoot = targetCharacter and targetCharacter:FindFirstChild("HumanoidRootPart")
            local targetHumanoid = targetCharacter and targetCharacter:FindFirstChildOfClass("Humanoid")
            if targetRoot and targetHumanoid and targetHumanoid.Health > 0
                and (targetRoot.Position - localRoot.Position).Magnitude <= state.radius
                and (not cooldowns[player]
                    or currentTime - cooldowns[player] >= state.detectionCooldown) then

                for _, track in ipairs(targetHumanoid:GetPlayingAnimationTracks()) do
                    local animation = track and track.Animation
                    local animationId = animation and tostring(animation.AnimationId or ""):match("%d+")
                    if animationId and animationSet[animationId] == true then
                        cooldowns[player] = currentTime
                        local workerToken = state.workerToken
                        task.spawn(function()
                            local startedAt = os.clock()
                            while state.enabled
                                and workerToken == state.workerToken
                                and os.clock() - startedAt < state.spamDuration do
                                -- fire() still applies E1LU4HUB's own ability cooldown,
                                -- range check, role check, readiness check and remote call.
                                S.AutoRagingPace.fire(state.radius)
                                task.wait(0.05)
                            end
                        end)
                        break
                    end
                end
            end
        end
    end
end
S.AutoRagingPace.setEnabled = function(enabled)
    local state = S.AutoRagingPace
    state.enabled = enabled == true
    state.workerToken += 1
    S.AutoRagingPace.disconnect()
    if not state.enabled then return true end

    local ok, connection = pcall(function()
        return S.RunService.Heartbeat:Connect(S.AutoRagingPace.checkAnimations)
    end)
    if ok and connection then
        table.insert(state.connections, connection)
        return true
    end
    state.enabled = false
    return false
end

S.AzureQTE = S.AzureQTE or {
    auto = false,
    infinite = false,
    method = "Instance",
    module = nil,
    originalNew = nil,
    wrapper = nil,
    manualConnection = nil,
    manualLastClick = 0,
    manualBusy = false,
}
S.AzureAim = S.AzureAim or {
    tentacles = false,
    unearthing = false,
    hooks = {},
}
S.AzureAim.hooks = S.AzureAim.hooks or {}
S.isAzureTentaclesAimEnabled = false
S.isAzureUnearthingAimEnabled = false
S.AzureAim.restoreHooks = function()
    local state = S.AzureAim
    for key, hookState in pairs(state.hooks or {}) do
        if hookState and hookState.entry and hookState.entry.Callback == hookState.wrapper then
            pcall(function() hookState.entry.Callback = hookState.original end)
        end
        state.hooks[key] = nil
    end
end
S.AzureAim.syncHooks = function()
    local state = S.AzureAim
    S.AzureAim.restoreHooks()
    if not state.tentacles and not state.unearthing then return true end

    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local killers = assets and assets:FindFirstChild("Killers")
    local azure = killers and killers:FindFirstChild("Azure")
    local behaviorScript = azure and azure:FindFirstChild("Behavior")
    if not behaviorScript or not behaviorScript:IsA("ModuleScript") then return false end
    local ok, behavior = pcall(require, behaviorScript)
    if not ok or type(behavior) ~= "table" or type(behavior.Abilities) ~= "table" then return false end

    local abilityNames = {}
    if state.tentacles then
        table.insert(abilityNames, "Grab")
        table.insert(abilityNames, "Unravel")
    end
    if state.unearthing then table.insert(abilityNames, "Blossom") end

    for _, abilityName in ipairs(abilityNames) do
        local entry = behavior.Abilities[abilityName]
        local original = type(entry) == "table" and entry.Callback
        if type(original) == "function" then
            local wrapper
            wrapper = function(actor, action, ...)
                local results = table.pack(original(actor, action, ...))
                local character = S.lp and S.lp.Character
                local isLocalActor = actor == character
                if type(actor) == "table" then
                    isLocalActor = isLocalActor or actor.Rig == character or actor.Player == S.lp
                end
                if isLocalActor then
                    if abilityName == "Blossom" then
                        if action == "Golem" and state.unearthing then
                            S.__helpers.startE1LU4SAKENAim("AzureUnearthing", "Survivors", 220, 1.8, nil, false)
                        elseif action == "Plant" then
                            S.E1LU4SAKENAimTokens.AzureUnearthing = (S.E1LU4SAKENAimTokens.AzureUnearthing or 0) + 1
                        end
                    elseif state.tentacles then
                        S.__helpers.startE1LU4SAKENAim("AzureTentacles", "Survivors", 220, 2.2, nil, false)
                    end
                end
                return table.unpack(results, 1, results.n)
            end
            entry.Callback = wrapper
            state.hooks[abilityName] = {entry = entry, original = original, wrapper = wrapper}
        end
    end
    return true
end

S.AzureQTE.getActiveQTE = function()
    local playerGui = S.lp and (S.lp:FindFirstChildOfClass("PlayerGui") or S.lp:FindFirstChild("PlayerGui"))
    if not playerGui then return nil end
    for _, guiName in ipairs({"TemporaryUI", "MainUI"}) do
        local gui = playerGui:FindFirstChild(guiName)
        local qte = gui and gui:FindFirstChild("QTE")
        if qte and qte:IsA("GuiObject") and qte.Visible then
            return qte
        end
    end
    local qte = playerGui:FindFirstChild("QTE")
    if qte and qte:IsA("GuiObject") and qte.Visible then
        return qte
    end
    return nil
end
S.AzureQTE.clickActiveQTE = function(qte)
    local state = S.AzureQTE
    if state.manualBusy or not qte or not qte.Parent then return false end
    if not qte:IsA("GuiObject") or not qte.Visible then return false end

    local clickTarget = qte:FindFirstChild("ClickArea", true)
    if not (clickTarget and clickTarget:IsA("GuiObject") and clickTarget.Visible) then
        clickTarget = nil
        for _, descendant in ipairs(qte:GetDescendants()) do
            if descendant:IsA("ImageButton") or descendant:IsA("TextButton") then
                if descendant.Visible then
                    clickTarget = descendant
                    break
                end
            end
        end
    end
    if not clickTarget then clickTarget = qte end
    if not clickTarget:IsA("GuiObject") or not clickTarget.Visible then return false end

    local position = clickTarget.AbsolutePosition
    local size = clickTarget.AbsoluteSize
    if size.X <= 0 or size.Y <= 0 then return false end
    local x, y = position.X + size.X / 2, position.Y + size.Y / 2
    local input = S.VirtualInputManager
    if not input then return false end

    state.manualBusy = true
    state.manualLastClick = os.clock()
    task.spawn(function()
        local touchMode = S.UserInputService.TouchEnabled and not S.UserInputService.MouseEnabled
        if touchMode then
            pcall(function() input:SendTouchEvent(1, 0, x, y) end)
            task.wait(0.01)
            pcall(function() input:SendTouchEvent(1, 2, x, y) end)
        else
            pcall(function() input:SendMouseButtonEvent(x, y, 0, true, game, 1) end)
            task.wait(0.01)
            pcall(function() input:SendMouseButtonEvent(x, y, 0, false, game, 1) end)
        end
        state.manualBusy = false
    end)
    return true
end
S.AzureQTE.startManual = function()
    local state = S.AzureQTE
    if state.manualConnection then return end
    state.manualConnection = S.__helpers.connect(S.RunService.Heartbeat, function()
        if not state.auto or state.method ~= "Manual" then
            if state.manualConnection then
                state.manualConnection:Disconnect()
                state.manualConnection = nil
            end
            return
        end
        if os.clock() - state.manualLastClick < 0.14 then return end
        local qte = S.AzureQTE.getActiveQTE()
        if qte then S.AzureQTE.clickActiveQTE(qte) end
    end)
end
S.AzureQTE.stopManual = function()
    local state = S.AzureQTE
    if state.manualConnection then
        pcall(function() state.manualConnection:Disconnect() end)
        state.manualConnection = nil
    end
    state.manualBusy = false
end
S.AzureQTE.getModule = function()
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local killers = assets and assets:FindFirstChild("Killers")
    local azure = killers and killers:FindFirstChild("Azure")
    if not azure then return nil end
    local candidate = azure:FindFirstChild("cl_ConstructQTE", true)
    if candidate and candidate:IsA("ModuleScript") then
        local ok, result = pcall(require, candidate)
        if ok and type(result) == "table" and type(result.new) == "function" then return result end
    end
    return nil
end
S.AzureQTE.refresh = function()
    local state = S.AzureQTE
    local manualAuto = state.auto and state.method == "Manual"
    if manualAuto then
        S.AzureQTE.startManual()
    else
        S.AzureQTE.stopManual()
    end

    -- Manual mode clicks the visible QTE widget. The constructor hook remains
    -- installed only for Instance auto-completion or Infinite Attempts.
    local needsInstanceHook = state.infinite or (state.auto and state.method == "Instance")
    if not needsInstanceHook then
        if state.module and state.originalNew and state.wrapper then
            pcall(function()
                if state.module.new == state.wrapper then state.module.new = state.originalNew end
            end)
        end
        state.module, state.originalNew, state.wrapper = nil, nil, nil
        return true
    end
    if not state.module then state.module = S.AzureQTE.getModule() end
    local module = state.module
    if not module then
        warn("[E1LU4HUB] Azure QTE: cl_ConstructQTE module was not found")
        return false
    end
    if state.wrapper and module.new == state.wrapper then return true end
    local original = module.new
    if type(original) ~= "function" then return false end
    state.originalNew = original
    local wrapper
    wrapper = function(...)
        local qte = original(...)
        if qte then
            if state.infinite then pcall(function() qte.FailedAttempts = -math.huge end) end
            if state.auto and state.method == "Instance" then
                task.defer(function()
                    task.wait(0.12)
                    if state.auto and state.method == "Instance" and qte and type(qte.AddProgress) == "function" then
                        pcall(function() qte:AddProgress(100) end)
                    end
                end)
            end
        end
        return qte
    end
    state.wrapper = wrapper
    local ok = pcall(function() module.new = wrapper end)
    return ok
end

S.NosferatuExtras = S.NosferatuExtras or {
    hookEnabled = false,
    hookCooldown = 0.3,
    hookToken = 0,
    unlimitedFly = false,
    diveControl = false,
    cataclysmControl = false,
    diveAimEnabled = false,
    diveAimConnection = nil,
    diveAimTrack = nil,
    diveAimHumanoid = nil,
    diveAimOriginalAutoRotate = nil,
    animationConnection = nil,
    originals = {
        fly = setmetatable({}, {__mode = "k"}),
        dive = setmetatable({}, {__mode = "k"}),
        cataclysm = setmetatable({}, {__mode = "k"}),
    },
}
S.NosferatuExtras.getConfigTables = function()
    local result, seen = {}, {}
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local killers = assets and assets:FindFirstChild("Killers")
    local nosferatu = killers and killers:FindFirstChild("Nosferatu")
    local configModule = nosferatu and nosferatu:FindFirstChild("Config")
    if configModule and configModule:IsA("ModuleScript") then
        local ok, config = pcall(require, configModule)
        if ok and type(config) == "table" then table.insert(result, config); seen[config] = true end
    end
    if type(getgc) == "function" then
        pcall(function()
            for _, object in pairs(getgc(true)) do
                if type(object) == "table" and not seen[object]
                    and (rawget(object, "AscentFlight") or rawget(object, "AscentBite") or rawget(object, "Spire")) then
                    table.insert(result, object); seen[object] = true
                elseif type(object) == "table" and not seen[object] and type(rawget(object, "Config")) == "table" then
                    local config = rawget(object, "Config")
                    if config.AscentFlight or config.AscentBite or config.Spire then
                        table.insert(result, config); seen[config] = true
                    end
                end
            end
        end)
    end
    return result
end
S.NosferatuExtras.setValue = function(feature, target, property, value)
    local bucket = S.NosferatuExtras.originals[feature]
    if not bucket or type(target) ~= "table" then return end
    local saved = bucket[target]
    if not saved then saved = {}; bucket[target] = saved end
    if saved[property] == nil then
        local ok, original = pcall(function() return target[property] end)
        if ok then saved[property] = {value = original, wasNil = original == nil} end
    end
    pcall(function() target[property] = value end)
end
S.NosferatuExtras.restore = function(feature)
    local bucket = S.NosferatuExtras.originals[feature]
    if not bucket then return end
    for target, props in pairs(bucket) do
        for property, original in pairs(props) do
            pcall(function()
                if original.wasNil then target[property] = nil else target[property] = original.value end
            end)
        end
    end
    S.NosferatuExtras.originals[feature] = setmetatable({}, {__mode = "k"})
end
S.NosferatuExtras.applyConfig = function()
    local state = S.NosferatuExtras
    if not state.unlimitedFly then S.NosferatuExtras.restore("fly") end
    if not state.diveControl then S.NosferatuExtras.restore("dive") end
    if not state.cataclysmControl then S.NosferatuExtras.restore("cataclysm") end
    for _, config in ipairs(S.NosferatuExtras.getConfigTables()) do
        if state.unlimitedFly and type(config.AscentFlight) == "table" then
            S.NosferatuExtras.setValue("fly", config.AscentFlight, "Duration", 999999)
        end
        if state.diveControl then
            if type(config.AscentBite) == "table" then
                S.NosferatuExtras.setValue("dive", config.AscentBite, "TurnSpeed", 999999)
            end
            if type(config.Ascent) == "table" then
                S.NosferatuExtras.setValue("dive", config.Ascent, "CanTurn", true)
            end
        end
        if state.cataclysmControl and type(config.Spire) == "table" then
            S.NosferatuExtras.setValue("cataclysm", config.Spire, "TurnControl", 999999)
        end
    end
end
S.NosferatuExtras.setHookEnabled = function(enabled)
    local state = S.NosferatuExtras
    state.hookEnabled = enabled == true
    state.hookToken = state.hookToken + 1
    local token = state.hookToken
    if not state.hookEnabled then return end
    task.spawn(function()
        while state.hookEnabled and state.hookToken == token do
            local character = S.lp and S.lp.Character
            local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
            local temporaryUI = playerGui and playerGui:FindFirstChild("TemporaryUI")
            local qte = temporaryUI and temporaryUI:FindFirstChild("QTE", true)
            if character and character.Name:lower() == "nosferatu"
                and S.__helpers.isLocalRole("Killer")
                and qte and qte:IsA("GuiObject") then
                local remote = S.getForsakenNetworkRemote and S.getForsakenNetworkRemote()
                if remote and remote:IsA("RemoteEvent") then
                    local payload = {true}
                    if type(buffer) == "table" and type(buffer.fromstring) == "function" then
                        pcall(function() payload = {buffer.fromstring("\1\1")} end)
                    end
                    pcall(function() remote:FireServer(S.lp.Name .. "NosHookQTE", payload) end)
                end
            end
            task.wait(math.clamp(tonumber(state.hookCooldown) or 0.3, 0.1, 1))
        end
    end)
end
S.NosferatuExtras.stopDiveAim = function()
    local state = S.NosferatuExtras
    if state.diveAimConnection then
        pcall(function() state.diveAimConnection:Disconnect() end)
        state.diveAimConnection = nil
    end
    if state.diveAimHumanoid and state.diveAimHumanoid.Parent
        and state.diveAimOriginalAutoRotate ~= nil then
        pcall(function() state.diveAimHumanoid.AutoRotate = state.diveAimOriginalAutoRotate end)
    end
    state.diveAimHumanoid, state.diveAimOriginalAutoRotate, state.diveAimTrack = nil, nil, nil
end
S.NosferatuExtras.startDiveAim = function(character, track)
    local state = S.NosferatuExtras
    if not state.diveAimEnabled or not character or character ~= (S.lp and S.lp.Character) then return end
    S.NosferatuExtras.stopDiveAim()
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    state.diveAimHumanoid = humanoid
    state.diveAimOriginalAutoRotate = humanoid.AutoRotate
    state.diveAimTrack = track
    humanoid.AutoRotate = false
    state.diveAimConnection = S.RunService.RenderStepped:Connect(function(dt)
        if not state.diveAimEnabled or character ~= (S.lp and S.lp.Character)
            or not character.Parent or not track or not track.IsPlaying then
            S.NosferatuExtras.stopDiveAim()
            return
        end
        local root = character:FindFirstChild("HumanoidRootPart")
        local playersFolder = workspace:FindFirstChild("Players")
        local survivors = playersFolder and playersFolder:FindFirstChild("Survivors")
        if not root or not survivors then return end
        local bestRoot, bestDistance = nil, 160
        for _, target in ipairs(survivors:GetChildren()) do
            if target:IsA("Model") and target ~= character then
                local targetHumanoid = target:FindFirstChildOfClass("Humanoid")
                local targetRoot = target:FindFirstChild("HumanoidRootPart")
                if targetHumanoid and targetHumanoid.Health > 0 and targetRoot then
                    local distance = (targetRoot.Position - root.Position).Magnitude
                    if distance < bestDistance then bestRoot, bestDistance = targetRoot, distance end
                end
            end
        end
        if bestRoot then
            local velocity = bestRoot.AssemblyLinearVelocity
            if velocity.Magnitude > 120 then velocity = Vector3.zero end
            local predicted = bestRoot.Position + velocity * 0.14
            local flatTarget = Vector3.new(predicted.X, root.Position.Y, predicted.Z)
            local direction = flatTarget - root.Position
            if direction.Magnitude > 0.05 then
                local goal = CFrame.lookAt(root.Position, flatTarget)
                local alpha = math.clamp((tonumber(dt) or 1/60) * 30, 0, 0.7)
                pcall(function() root.CFrame = root.CFrame:Lerp(goal, alpha) end)
            end
        end
    end)
end
S.NosferatuExtras.bindCharacter = function(character)
    local state = S.NosferatuExtras
    if state.animationConnection then
        pcall(function() state.animationConnection:Disconnect() end)
        state.animationConnection = nil
    end
    S.NosferatuExtras.stopDiveAim()
    if not character or character.Name:lower() ~= "nosferatu" then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
    local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 5))
    if not animator then return end
    local diveAnimationIds = {}
    pcall(function()
        local assets = S.ReplicatedStorage:FindFirstChild("Assets")
        local killers = assets and assets:FindFirstChild("Killers")
        local nosferatu = killers and killers:FindFirstChild("Nosferatu")
        local configModule = nosferatu and nosferatu:FindFirstChild("Config")
        local config = configModule and require(configModule)
        local animations = config and config.Animations
        local function collectIds(value)
            if typeof(value) == "Instance" and value:IsA("Animation") then
                local id = tostring(value.AnimationId or ""):match("%d+")
                if id then diveAnimationIds[id] = true end
            elseif type(value) == "string" or type(value) == "number" then
                local id = tostring(value):match("%d+")
                if id then diveAnimationIds[id] = true end
            elseif type(value) == "table" then
                for _, nested in pairs(value) do collectIds(nested) end
            end
        end
        if type(animations) == "table" then
            for key, value in pairs(animations) do
                local keyName = tostring(key):lower()
                if keyName:find("ascent", 1, true) or keyName:find("uppercut", 1, true) then
                    collectIds(value)
                end
            end
        end
    end)
    state.animationConnection = animator.AnimationPlayed:Connect(function(track)
        local animation = track and track.Animation
        local animationName = animation and tostring(animation.Name or ""):lower() or ""
        local animationId = animation and tostring(animation.AnimationId or ""):match("%d+") or nil
        if animationName:find("ascent", 1, true)
            or animationName:find("uppercut", 1, true)
            or (animationId and diveAnimationIds[animationId]) then
            S.NosferatuExtras.startDiveAim(character, track)
        end
    end)
end
S.__helpers.connect(S.lp.CharacterAdded, S.NosferatuExtras.bindCharacter)
if S.lp.Character then task.defer(S.NosferatuExtras.bindCharacter, S.lp.Character) end

S.NoliRushAntiCrashState = S.NoliRushAntiCrashState or {
    enabled = false,
    module = nil,
    original = nil,
    wrapper = nil,
}
S.NoliRushAntiCrashState.setEnabled = function(enabled)
    local state = S.NoliRushAntiCrashState
    S.isNoliRushAntiCrashEnabled = enabled == true
    state.enabled = S.isNoliRushAntiCrashEnabled
    -- The primary implementation is the existing NetworkModule hook above.
    -- If this executor cannot hook functions, install a reversible table wrapper.
    if state.enabled and not S.oldFireServerConnection and not state.wrapper then
        local module = S.NetworkModule
        if not module then
            pcall(function()
                module = require(S.ReplicatedStorage.Modules.Network.Network)
                S.NetworkModule = module
            end)
        end
        if module and type(module.FireServerConnection) == "function" then
            state.module = module
            state.original = module.FireServerConnection
            state.wrapper = function(self, connectionName, eventType, ...)
                local character = S.lp and S.lp.Character
                if S.isNoliRushAntiCrashEnabled
                    and eventType == "REMOTE_EVENT"
                    and S.lp and connectionName == (S.lp.Name .. "VoidRushCollision")
                    and character and character.Name:lower():gsub("%s+", "") == "noli" then
                    return nil
                end
                return state.original(self, connectionName, eventType, ...)
            end
            pcall(function() module.FireServerConnection = state.wrapper end)
        end
    elseif not state.enabled and state.wrapper and state.module
        and state.module.FireServerConnection == state.wrapper then
        pcall(function() state.module.FireServerConnection = state.original end)
        state.module, state.original, state.wrapper = nil, nil, nil
    end
end

S.SlasherExtras = S.SlasherExtras or {
    customRagingPaceSpeed = false,
    speedMultiplier = 2.1,
    originals = setmetatable({}, {__mode = "k"}),
}
S.SlasherExtras.apply = function()
    local state = S.SlasherExtras
    if not state.customRagingPaceSpeed then
        for target, properties in pairs(state.originals) do
            for key, original in pairs(properties) do pcall(function() target[key] = original end) end
        end
        state.originals = setmetatable({}, {__mode = "k"})
        return
    end
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local killers = assets and assets:FindFirstChild("Killers")
    local slasher = killers and killers:FindFirstChild("Slasher")
    if not slasher then return end
    local candidates = {}
    for _, moduleName in ipairs({"Config", "Behavior"}) do
        local moduleScript = slasher:FindFirstChild(moduleName)
        if moduleScript and moduleScript:IsA("ModuleScript") then
            local ok, result = pcall(require, moduleScript)
            if ok and type(result) == "table" then
                if type(result.RagingPace) == "table" then table.insert(candidates, result.RagingPace) end
                if type(result.Abilities) == "table" and type(result.Abilities.RagingPace) == "table" then
                    table.insert(candidates, result.Abilities.RagingPace)
                end
                if type(result.Config) == "table" and type(result.Config.RagingPace) == "table" then
                    table.insert(candidates, result.Config.RagingPace)
                end
            end
        end
    end
    for _, target in ipairs(candidates) do
        for _, property in ipairs({"SpeedMultiplier", "Multiplier"}) do
            local current = target[property]
            if type(current) == "number" then
                local saved = state.originals[target]
                if not saved then saved = {}; state.originals[target] = saved end
                if saved[property] == nil then saved[property] = current end
                pcall(function() target[property] = state.speedMultiplier end)
            end
        end
    end
end

-- AUTO PICKUP / AUTO ESCAPE / AUTO DISARM (FORSAKENPLUS SOURCE)
-- ================================================================
-- Auto Pickup: mirrors ForsakenPlus's nearby Tool pickup behavior.
-- Newly spawned Tools are ignored for 1.5s, matching the source.
S.getIngameFolders = function()
    local mapFolder = workspace:FindFirstChild("Map")
    local ingame = mapFolder and mapFolder:FindFirstChild("Ingame")
    local gameMap = ingame and ingame:FindFirstChild("Map")
    return ingame, gameMap
end

S.isAutoPickupCandidate = function(tool)
    if not tool or not tool:IsA("Tool") or not tool.Parent then
        return false
    end

    local ingame, gameMap = S.getIngameFolders()
    if not ingame or not gameMap then
        return false
    end

    -- Match the uploaded source's loose in-game item scope: do not pick up
    -- Tools equipped by characters or Tools outside the current Ingame map.
    if not tool:IsDescendantOf(ingame) then
        return false
    end

    local parent = tool.Parent
    if parent and parent:IsA("Model") and parent:FindFirstChildOfClass("Humanoid") then
        return false
    end

    -- The source queries Tools anywhere under Ingame, including direct children.
    return true
end

S.activateItemPrompt = function(object)
    local prompt = object and object:FindFirstChildWhichIsA("ProximityPrompt", true)
    if not prompt or not prompt.Parent or prompt.Enabled == false then
        return false
    end

    -- Prefer executor helpers when available.
    if type(fireprompt) == "function" then
        local ok = pcall(fireprompt, prompt)
        if ok then return true end
    end

    if type(fireproximityprompt) == "function" then
        local ok = pcall(fireproximityprompt, prompt)
        if ok then return true end
    end

    -- Match ForsakenPlus's own fallback. Some executors do not expose a
    -- prompt helper, but the prompt's hold-input methods are still available.
    local holdOK = pcall(function()
        prompt:InputHoldBegin()
        prompt:InputHoldEnd()
    end)
    if holdOK then
        return true
    end

    -- Last-resort signal fallback for executors exposing firesignal.
    if type(firesignal) == "function" then
        local signalOK = pcall(firesignal, prompt.Triggered)
        if signalOK then return true end
    end

    return false
end

-- Match ForsakenPlus: mark newly dropped Tools inside Ingame as unavailable
-- for 1.5 seconds, then clear the marker. Also catch nested map drops.
S.__helpers.markAutoPickupToolJustDropped = function(object)
    if not object or not object:IsA("Tool") or not S.isAutoPickupCandidate(object) then
        return
    end
    object:SetAttribute("JustDropped", true)
    task.delay(1.5, function()
        if object and object.Parent then
            pcall(function()
                object:SetAttribute("JustDropped", nil)
            end)
        end
    end)
end

S.__helpers.connect(workspace.DescendantAdded, function(object)
    if object:IsA("Tool") then
        S.__helpers.markAutoPickupToolJustDropped(object)
    end
end)

-- Auto Pickup loop adapted from the uploaded ForsakenPlus source.
-- Checks nearby item Tools and Gear models, independent of ITEM ESP.
task.spawn(function()
    while true do
        task.wait(S.__helpers.getScriptUpdateInterval and S.__helpers.getScriptUpdateInterval() or 0.1)
        if not S.isAutoPickupEnabled then
            continue
        end

        local character = S.lp and S.lp.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local backpack = S.lp and S.lp:FindFirstChildOfClass("Backpack")
        if not character or not root then
            continue
        end

        local ingame, gameMap = S.getIngameFolders()
        if not ingame or not gameMap then
            continue
        end

        local function isNearby(object)
            if not object or not object.Parent then
                return false
            end

            -- Use the same overlap query as the supplied ForsakenPlus source.
            -- BruteForceAllSlow/IncludeInstances is important in executor builds
            -- where ordinary FilterDescendantsInstances can miss loose Gear parts.
            local sourceOK, sourceResult = pcall(function()
                local params = OverlapParams.new()
                params.BruteForceAllSlow = true
                params.IncludeInstances = {object}
                return workspace:GetPartBoundsInRadius(root.Position, 4.5, params)
            end)
            if sourceOK and sourceResult and #sourceResult > 0 then
                return true
            end

            -- Standard Roblox API fallback.
            local fallbackOK, fallbackResult = pcall(function()
                local params = OverlapParams.new()
                params.FilterType = Enum.RaycastFilterType.Include
                params.FilterDescendantsInstances = {object}
                return workspace:GetPartBoundsInRadius(root.Position, 4.5, params)
            end)
            return fallbackOK and fallbackResult ~= nil and #fallbackResult > 0
        end

        -- Pick up loose item Tools, excluding flags and Tools held by characters.
        for _, tool in ipairs(ingame:GetDescendants()) do
            if tool:IsA("Tool") and tool.Name ~= "Flag" then
                local heldByCharacter = tool.Parent and tool.Parent:IsA("Model")
                    and tool.Parent:FindFirstChildOfClass("Humanoid")
                local alreadyOwned = character:FindFirstChild(tool.Name)
                    or (backpack and backpack:FindFirstChild(tool.Name))
                if not heldByCharacter and not alreadyOwned
                    and not tool:GetAttribute("JustDropped")
                    and S.isAutoPickupCandidate(tool)
                    and isNearby(tool) then
                    S.activateItemPrompt(tool)
                end
            end
        end

        -- Gear is a Model (not a Tool) and is handled separately, just like
        -- the supplied ForsakenPlus implementation. Its Root must be a BasePart.
        for _, gear in ipairs(gameMap:GetDescendants()) do
            local gearRoot = gear:IsA("Model") and gear.Name == "Gear"
                and gear:FindFirstChild("Root") or nil
            if gearRoot and gearRoot:IsA("BasePart") and isNearby(gear) then
                local prompt = gear:FindFirstChildWhichIsA("ProximityPrompt", true)
                if prompt then
                    S.activateItemPrompt(gear)
                end
            end
        end
    end
end)

-- Auto Escape: mirrors the source's QTE watcher and Nosferatu hook QTE remote.
S.getTemporaryUI = function()
    local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
    return playerGui and playerGui:FindFirstChild("TemporaryUI")
end

S.sendNosferatuEscapeQTE = function()
    local remote = S.getForsakenNetworkRemote()
    if not remote then
        return
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local killerFolder = playersFolder and playersFolder:FindFirstChild("Killers")
    if not killerFolder then
        return
    end

    for _, killer in ipairs(killerFolder:GetChildren()) do
        if killer.Name:lower() == "nosferatu" then
            local player = S.Players:GetPlayerFromCharacter(killer)
            if player then
                pcall(function()
                    remote:FireServer(player.Name .. "NosHookQTE", {true})
                end)
            end
        end
    end
end

S.attachAutoEscapeToQTE = function(uiElement)
    if not uiElement or uiElement.Name:upper() ~= "QTE" then
        return
    end

    if not uiElement:FindFirstChildOfClass("UIAspectRatioConstraint") then
        return
    end

    if uiElement:GetAttribute("ELSGUI_AutoEscapeAttached") then
        return
    end
    uiElement:SetAttribute("ELSGUI_AutoEscapeAttached", true)

    task.spawn(function()
        while uiElement and uiElement.Parent and uiElement.Visible do
            local cooldown = math.max(0.01, tonumber(S.autoEscapeCooldown) or 0.5)
            -- Mirror ForsakenPlus: apply +/-20% timing jitter.
            local jitter = Random.new()
            task.wait(jitter:NextNumber(cooldown - 0.2 * cooldown, cooldown + 0.2 * cooldown))
            if S.isAutoEscapeEnabled and uiElement and uiElement.Parent and uiElement.Visible then
                S.sendNosferatuEscapeQTE()
            end
        end
    end)
end

S.bindAutoEscapeUI = function()
    local tempUI = S.getTemporaryUI()
    if not tempUI then
        return
    end

    if not tempUI:GetAttribute("ELSGUI_AutoEscapeBound") then
        tempUI:SetAttribute("ELSGUI_AutoEscapeBound", true)
        S.__helpers.connect(tempUI.ChildAdded, S.attachAutoEscapeToQTE)
    end

    for _, child in ipairs(tempUI:GetChildren()) do
        S.attachAutoEscapeToQTE(child)
    end
end

S.bindAutoEscapeUI()

-- TemporaryUI can be created after ELSEGUI starts. Watch PlayerGui once so
-- Auto Escape also binds correctly when that UI appears later.
do
    local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
    if playerGui then
        S.__helpers.connect(playerGui.ChildAdded, function(child)
            if child.Name == "TemporaryUI" then
                task.defer(S.bindAutoEscapeUI)
            end
        end)
    end
end

S.__helpers.connect(S.lp.CharacterAdded, function()
    task.delay(0.5, S.bindAutoEscapeUI)
end)

-- Auto Disarm: mirrors ForsakenPlus's Azure QTE constructor hook.
S.currentAzureQTE = nil
S.autoDisarmHookInstalled = false

S.setAutoDisarmEnabled = function(value)
    S.isAutoDisarmEnabled = value == true

    if S.isAutoDisarmEnabled and S.currentAzureQTE then
        local qte = S.currentAzureQTE
        S.currentAzureQTE = nil
        if type(qte) == "table" and type(qte.AddProgress) == "function" then
            pcall(function()
                qte:AddProgress(100)
            end)
        end
    end
end

S.installAutoDisarmHook = function()
    if S.autoDisarmHookInstalled or type(hookfunction) ~= "function" then
        return
    end

    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local killers = assets and assets:FindFirstChild("Killers")
    local azure = killers and (killers:FindFirstChild("Azure") or killers:FindFirstChild("!Azure"))
    local azureQTE = azure and azure:FindFirstChild("cl_ConstructQTE", true)
    if not azureQTE and killers then
        azureQTE = killers:FindFirstChild("cl_ConstructQTE", true)
    end
    if not azureQTE or not azureQTE:IsA("ModuleScript") then
        return
    end

    local okRequire, requiredModule = pcall(require, azureQTE)
    if not okRequire or type(requiredModule) ~= "table" or type(requiredModule.new) ~= "function" then
        return
    end

    local okHook = pcall(function()
        local original
        original = hookfunction(requiredModule.new, function(...)
            local qte = original(...)
            task.delay(0.05, function()
                if typeof(qte) == "table" and type(qte.AddProgress) == "function" then
                    if S.isAutoDisarmEnabled then
                        pcall(function()
                            qte:AddProgress(100)
                        end)
                    else
                        S.currentAzureQTE = qte
                    end
                end
            end)
            return qte
        end)
    end)

    if okHook then
        S.autoDisarmHookInstalled = true
    end
end

task.spawn(function()
    for _ = 1, 60 do
        if S.autoDisarmHookInstalled then
            break
        end
        S.installAutoDisarmHook()
        if S.autoDisarmHookInstalled then
            break
        end
        task.wait(0.5)
    end
end)

-- ================================================================

-- Cursedsaken's fn6 payload format, used by Auto Undetect LMS abilities.
-- This function never searches for or clicks an ability GuiButton.
S.__helpers.fireCursedsakenAbilityDirect = function(abilityName)
    if type(abilityName) ~= "string" or abilityName == "" then
        return false
    end
    if not buffer or type(buffer.fromstring) ~= "function"
        or type(string.pack) ~= "function" then
        return false
    end

    local modules = S.ReplicatedStorage and S.ReplicatedStorage:FindFirstChild("Modules")
    local networkFolder = modules and modules:FindFirstChild("Network", true)
    local networkModule = networkFolder
        and (networkFolder:FindFirstChild("Network") or networkFolder)
    local remote = networkModule and (
        networkModule:FindFirstChild("RemoteEvent")
        or networkModule:FindFirstChildOfClass("RemoteEvent")
    )
    if not remote and type(S.getForsakenNetworkRemote) == "function" then
        local okRemote, foundRemote = pcall(S.getForsakenNetworkRemote)
        if okRemote then remote = foundRemote end
    end
    if not remote or not remote:IsA("RemoteEvent") then
        return false
    end

    local packedOK, payload = pcall(function()
        return buffer.fromstring(string.pack("<Bi4", 3, #abilityName) .. abilityName)
    end)
    if not packedOK or not payload then
        return false
    end

    local fired = pcall(function()
        remote:FireServer("UseActorAbility", {payload})
    end)
    return fired
end

S.__helpers.isAutoUndetectAbilityReady = function(abilityName)
    local mainUI = S.__helpers.getMainUI()
    local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
    local abilityWidget = abilityContainer and abilityContainer:FindFirstChild(abilityName)
    if not abilityWidget then return false end

    local foundCooldownState = false
    local cooldown = abilityWidget:FindFirstChild("CooldownTime", true)
    if cooldown and cooldown:IsA("TextLabel") then
        foundCooldownState = true
        local text = tostring(cooldown.Text or ""):gsub("%s+", "")
        if text ~= "" then
            local remaining = tonumber(text:gsub("[^%d%.%-]", ""))
            if remaining == nil or remaining > 0.01 then return false end
        end
    end

    local clipping = abilityWidget:FindFirstChild("Clipping", true)
    if clipping and clipping:IsA("GuiObject") then
        foundCooldownState = true
        if clipping.Visible and (tonumber(clipping.Size.Y.Scale) or 0) < 0.99 then
            return false
        end
    end

    -- Fail closed unless the actual cooldown indicator is observable.
    return foundCooldownState
end

S.__helpers.tryAutoUndetectLMSAbility = function()
    local state = S.AutoUndetect
    if not state or not state.lmsEnabled or state.lmsBusy
        or os.clock() < (state.nextAttemptAt or 0)
        or not S.__helpers.isLocalRole("Survivor") then
        return false
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local survivorsFolder = playersFolder and playersFolder:FindFirstChild("Survivors")
    if not survivorsFolder then
        state.soloCandidate = nil
        state.lmsTriggered = false
        return false
    end

    local children = survivorsFolder:GetChildren()
    local onlySurvivor = #children == 1 and children[1] or nil
    if onlySurvivor ~= state.soloCandidate then
        state.soloCandidate = onlySurvivor
        state.lmsTriggered = false
    end

    local character = S.lp and S.lp.Character
    if not onlySurvivor or onlySurvivor ~= character or state.lmsTriggered then
        return false
    end

    local abilityName = nil
    if onlySurvivor.Name == "007n7" then
        abilityName = state.selected007Ability or "c00lgui"
    elseif onlySurvivor.Name == "Noob" then
        abilityName = "Ghostburger"
    else
        return false
    end

    -- Cooldown state is read from the ability's cooldown widget only. No click,
    -- Activated event, MouseButton1Click, or firesignal path is used here.
    local readyCheck = S.__helpers.isAutoUndetectAbilityReady
    if type(readyCheck) ~= "function" then
        return false
    end
    local readyOK, ready = pcall(readyCheck, abilityName)
    if not readyOK or ready ~= true then
        return false
    end

    state.lmsBusy = true
    state.nextAttemptAt = os.clock() + 0.65
    local lmsToken = state.lmsToken
    task.spawn(function()
        task.wait(0.05)
        local currentFolder = workspace:FindFirstChild("Players")
        currentFolder = currentFolder and currentFolder:FindFirstChild("Survivors")
        local currentChildren = currentFolder and currentFolder:GetChildren() or {}
        local stillSolo = #currentChildren == 1
            and currentChildren[1] == onlySurvivor
            and S.lp and S.lp.Character == onlySurvivor
            and S.__helpers.isLocalRole("Survivor")
            and state.lmsEnabled
            and state.lmsToken == lmsToken

        if stillSolo then
            local secondReadyOK, secondReady = pcall(readyCheck, abilityName)
            if secondReadyOK and secondReady == true then
                local fireOK, fired = pcall(S.__helpers.fireCursedsakenAbilityDirect, abilityName)
                if fireOK and fired == true then
                    state.lmsTriggered = true
                end
            end
        end
        if state.lmsToken == lmsToken then
            state.lmsBusy = false
        end
    end)
    return true
end

S.__helpers.setAutoLMSAbility = function(enabled)
    local state = S.AutoUndetect
    if not state then return end
    state.lmsEnabled = enabled == true
    state.lmsToken += 1
    state.lmsBusy = false
    state.lmsTriggered = false
    state.soloCandidate = nil
    state.nextAttemptAt = 0
    if not state.lmsEnabled then return end

    local token = state.lmsToken
    task.spawn(function()
        while state.lmsEnabled and state.lmsToken == token do
            pcall(S.__helpers.tryAutoUndetectLMSAbility)
            task.wait(0.12)
        end
    end)
end

S.__helpers.stopAutoUndetectInvisibility = function()
    local state = S.AutoUndetect
    if not state then return end

    if state.invisTrack then
        pcall(function() state.invisTrack:Stop(0.05) end)
        pcall(function() state.invisTrack:Destroy() end)
        state.invisTrack = nil
    end
    if state.invisAnimation then
        pcall(function() state.invisAnimation:Destroy() end)
        state.invisAnimation = nil
    end
    for part, originalCanCollide in pairs(state.originalCanCollide or {}) do
        if part and part.Parent then
            pcall(function() part.CanCollide = originalCanCollide end)
        end
        state.originalCanCollide[part] = nil
    end
    state.invisCharacter = nil
end

S.__helpers.applyAutoUndetectInvisibility = function(character, enabled)
    local state = S.AutoUndetect
    if not state then return end
    if enabled ~= true or not state.autoInvisEnabled
        or not character or character ~= (S.lp and S.lp.Character)
        or not S.__helpers.isLocalRole("Survivor") then
        S.__helpers.stopAutoUndetectInvisibility()
        return
    end

    if state.invisCharacter ~= character then
        S.__helpers.stopAutoUndetectInvisibility()
        state.invisCharacter = character
    end

    local bodyNames = {"Torso", "UpperTorso", "LowerTorso", "HumanoidRootPart", "Head"}
    for _, partName in ipairs(bodyNames) do
        local part = character:FindFirstChild(partName)
        if part and part:IsA("BasePart") then
            if state.originalCanCollide[part] == nil then
                state.originalCanCollide[part] = part.CanCollide
            end
            pcall(function() part.CanCollide = false end)
        end
    end

    if not state.invisTrack then
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator then
            local animation = Instance.new("Animation")
            animation.Name = "E1LU4HUB_AutoUndetect_Invisibility"
            animation.AnimationId = "rbxassetid://75804462760596"
            local okTrack, track = pcall(function() return animator:LoadAnimation(animation) end)
            if okTrack and track then
                state.invisAnimation = animation
                state.invisTrack = track
                pcall(function()
                    track:Play()
                    track:AdjustSpeed(0)
                end)
            else
                pcall(function() animation:Destroy() end)
            end
        end
    end
end

S.__helpers.bindAutoUndetectCharacter = function(character)
    local state = S.AutoUndetect
    if not state then return end
    if state.attributeConnection then
        pcall(function() state.attributeConnection:Disconnect() end)
        state.attributeConnection = nil
    end
    S.__helpers.stopAutoUndetectInvisibility()

    if not state.autoInvisEnabled or not character then return end
    state.attributeConnection = character:GetAttributeChangedSignal("Undetectable"):Connect(function()
        if not state.autoInvisEnabled or S.lp.Character ~= character then return end
        S.__helpers.applyAutoUndetectInvisibility(
            character,
            character:GetAttribute("Undetectable") == true
        )
    end)

    S.__helpers.applyAutoUndetectInvisibility(
        character,
        character:GetAttribute("Undetectable") == true
    )
end

S.__helpers.setAutoInvisWhenUndetectable = function(enabled)
    local state = S.AutoUndetect
    if not state then return end
    state.autoInvisEnabled = enabled == true

    if state.attributeConnection then
        pcall(function() state.attributeConnection:Disconnect() end)
        state.attributeConnection = nil
    end
    if state.characterAddedConnection then
        pcall(function() state.characterAddedConnection:Disconnect() end)
        state.characterAddedConnection = nil
    end
    S.__helpers.stopAutoUndetectInvisibility()

    if not state.autoInvisEnabled then return end
    if S.lp and S.lp.Character then
        S.__helpers.bindAutoUndetectCharacter(S.lp.Character)
    end
    if S.lp then
        state.characterAddedConnection = S.lp.CharacterAdded:Connect(function(character)
            S.__helpers.bindAutoUndetectCharacter(character)
        end)
    end
end

S.__helpers.getV2Root = function(character)
    if not character then return nil end
    if S.AutoBlockV2.queryBased then
        local query = character:FindFirstChild("QueryHitbox")
        if query and query:IsA("BasePart") then return query end
    end
    return character:FindFirstChild("HumanoidRootPart")
end


-- VEERONICA AUTO TRICK
-- ================================================================
-- Mobile deliberately keeps the original working SprintingButton callback
-- path. PC sends a short Space key press through VirtualInputManager.
S.__helpers.invokeVeeronicaMobileSprint = function()
    local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
    local mainUI = playerGui and playerGui:FindFirstChild("MainUI")
    local sprintButton = mainUI and mainUI:FindFirstChild("SprintingButton")
    if not (sprintButton and sprintButton:IsA("GuiButton")) then
        return false
    end

    if type(getconnections) ~= "function" then
        return false
    end

    local ok, connections = pcall(getconnections, sprintButton.MouseButton1Down)
    if not ok or type(connections) ~= "table" then
        return false
    end

    for _, connection in pairs(connections) do
        local fired = false
        pcall(function()
            if type(connection.Fire) == "function" then
                connection:Fire()
                fired = true
            elseif type(connection.Function) == "function" then
                -- Keep the original colon call; some executor connection
                -- wrappers expect the connection object as self.
                connection:Function()
                fired = true
            end
        end)
        if fired then
            return true
        end
    end
    return false
end

S.__helpers.invokeVeeronicaPCJump = function()
    -- PC Auto Trick should perform the same input as pressing Space.
    -- Send a short key-down/key-up pair through VirtualInputManager; do not
    -- change Humanoid.Jump or force a Humanoid state directly.
    local input = S.VirtualInputManager
    if not input then
        return false
    end

    local keyCode = Enum.KeyCode.Space
    local downOK = pcall(function()
        input:SendKeyEvent(true, keyCode, false, game)
    end)
    if not downOK then
        return false
    end

    -- Always release Space shortly after pressing it to avoid a stuck input.
    task.delay(0.05, function()
        pcall(function()
            input:SendKeyEvent(false, keyCode, false, game)
        end)
    end)

    return true
end

S.setVeeronicaAutoTrick = function(value)
    S.isVeeronicaAutoTrickEnabled = value == true
    if S.veeronicaAutoTrickConnection then
        pcall(function()
            S.veeronicaAutoTrickConnection:Disconnect()
        end)
        S.veeronicaAutoTrickConnection = nil
    end

    if not S.isVeeronicaAutoTrickEnabled then
        return
    end

    S.veeronicaAutoTrickConnection = S.RunService.Heartbeat:Connect(function()
        if not S.isVeeronicaAutoTrickEnabled then
            return
        end

        local now = os.clock()
        if now - (S.veeronicaLastTrick or 0) < 0.08 then
            return
        end

        local character = S.lp and S.lp.Character
        if not character or character.Name ~= "Veeronica"
            or not S.isCharacterInRoleFolder(character, "Survivors") then
            return
        end
        if S.lp:GetAttribute("MatchState") ~= "Playing" then
            return
        end

        local assets = S.ReplicatedStorage:FindFirstChild("Assets")
        local survivors = assets and assets:FindFirstChild("Survivors")
        local veeronica = survivors and survivors:FindFirstChild("Veeronica")
        local behavior = veeronica and veeronica:FindFirstChild("Behavior")
        local highlight = behavior and behavior:FindFirstChild("Highlight")
        if not (highlight and highlight:IsA("Highlight") and highlight.Adornee == character) then
            return
        end

        -- Same gate as E1LU4SAKEN's VerronicaIsSkating(): the skating Highlight
        -- must directly adorn the current local Veeronica character.
        local detectedAtStartup = S.initialDetectedDevice
        local didTrigger = false
        if detectedAtStartup == "Mobile" then
            didTrigger = S.__helpers.invokeVeeronicaMobileSprint()
        elseif detectedAtStartup == "PC" or detectedAtStartup == "Console" then
            didTrigger = S.__helpers.invokeVeeronicaPCJump()
        end
        if didTrigger then S.veeronicaLastTrick = now end
    end)
end

-- ================================================================
-- VEERONICA FREE MOVE
--
-- Uses the source script's Veeronica animation trigger and camera-forward
-- movement. It is fail-closed: nothing runs unless the local character is
-- currently inside workspace.Players.Survivors.
-- ================================================================
S.__helpers.isVeeronicaFreeMoveAnimationPlaying = function(humanoid)
    if not humanoid then
        return false
    end

    local ok, tracks = pcall(function()
        return humanoid:GetPlayingAnimationTracks()
    end)
    if not ok or type(tracks) ~= "table" then
        return false
    end

    for _, track in ipairs(tracks) do
        local animation = track and track.Animation
        local animationId = animation and tostring(animation.AnimationId):match("%d+")
        if animationId == S.VEERONICA_FREE_MOVE_ANIMATION_ID
            and track.IsPlaying then
            return true
        end
    end

    return false
end

S.__helpers.stopVeeronicaFreeMove = function()
    if S.veeronicaFreeMoveRenderConnection then
        pcall(function()
            S.veeronicaFreeMoveRenderConnection:Disconnect()
        end)
        S.veeronicaFreeMoveRenderConnection = nil
    end

    local humanoid = S.veeronicaFreeMoveActiveHumanoid
    if humanoid and humanoid.Parent then
        if S.veeronicaFreeMoveOriginalAutoRotate ~= nil then
            pcall(function()
                humanoid.AutoRotate = S.veeronicaFreeMoveOriginalAutoRotate
            end)
        end
        pcall(function()
            humanoid:Move(Vector3.new(0, 0, 0), false)
        end)
    end

    if S.veeronicaFreeMoveOriginalMouseBehavior ~= nil then
        pcall(function()
            S.UserInputService.MouseBehavior = S.veeronicaFreeMoveOriginalMouseBehavior
        end)
    end

    local alignOrientation = S.veeronicaFreeMoveAlignOrientation
    local originalState = S.veeronicaFreeMoveAlignOriginalState
    if alignOrientation and alignOrientation.Parent and originalState then
        pcall(function()
            alignOrientation.Mode = originalState.Mode
            alignOrientation.RigidityEnabled = originalState.RigidityEnabled
            alignOrientation.MaxAngularVelocity = originalState.MaxAngularVelocity
            alignOrientation.Responsiveness = originalState.Responsiveness
            alignOrientation.CFrame = originalState.CFrame
        end)
    end

    S.veeronicaFreeMoveActive = false
    S.veeronicaFreeMoveActiveCharacter = nil
    S.veeronicaFreeMoveActiveHumanoid = nil
    S.veeronicaFreeMoveOriginalAutoRotate = nil
    S.veeronicaFreeMoveOriginalMouseBehavior = nil
    S.veeronicaFreeMoveAlignOrientation = nil
    S.veeronicaFreeMoveAlignOriginalState = nil
end

S.__helpers.startVeeronicaFreeMove = function(character, humanoid, root)
    if S.veeronicaFreeMoveActive or not character or not humanoid or not root then
        return
    end
    if not S.isVeeronicaFreeMoveEnabled
        or not S.__helpers.isLocalRole("Survivor")
        or not S.isCharacterInRoleFolder(character, "Survivors") then
        return
    end

    S.veeronicaFreeMoveActive = true
    S.veeronicaFreeMoveActiveCharacter = character
    S.veeronicaFreeMoveActiveHumanoid = humanoid
    S.veeronicaFreeMoveOriginalAutoRotate = humanoid.AutoRotate
    S.veeronicaFreeMoveOriginalMouseBehavior = S.UserInputService.MouseBehavior

    pcall(function()
        humanoid.AutoRotate = false
        S.UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
    end)

    local alignOrientation = root:FindFirstChild("SkatePointer")
    if alignOrientation and alignOrientation:IsA("AlignOrientation") then
        S.veeronicaFreeMoveAlignOrientation = alignOrientation
        S.veeronicaFreeMoveAlignOriginalState = {
            Mode = alignOrientation.Mode,
            RigidityEnabled = alignOrientation.RigidityEnabled,
            MaxAngularVelocity = alignOrientation.MaxAngularVelocity,
            Responsiveness = alignOrientation.Responsiveness,
            CFrame = alignOrientation.CFrame,
        }
    end

    S.veeronicaFreeMoveRenderConnection = S.RunService.RenderStepped:Connect(function()
        -- Recheck the role here as well so camera/movement control stops promptly
        -- if the round role changes while this callback is running.
        if not S.isVeeronicaFreeMoveEnabled
            or not S.__helpers.isLocalRole("Survivor")
            or not S.isCharacterInRoleFolder(character, "Survivors")
            or not S.lp
            or S.lp.Character ~= character
            or not character.Parent
            or not humanoid.Parent then
            S.__helpers.stopVeeronicaFreeMove()
            return
        end

        if not S.__helpers.isVeeronicaFreeMoveAnimationPlaying(humanoid) then
            S.__helpers.stopVeeronicaFreeMove()
            return
        end

        local currentRoot = character:FindFirstChild("HumanoidRootPart")
        local camera = workspace.CurrentCamera
        if not currentRoot or not camera then
            return
        end

        local lookVector = camera.CFrame.LookVector
        local moveDirection = Vector3.new(lookVector.X, 0, lookVector.Z)
        if moveDirection.Magnitude < 0.1 then
            return
        end
        moveDirection = moveDirection.Unit

        pcall(function()
            humanoid.AutoRotate = false
            humanoid:Move(moveDirection, false)
        end)

        local pointer = currentRoot:FindFirstChild("SkatePointer")
        if pointer and pointer:IsA("AlignOrientation") then
            pcall(function()
                pointer.Mode = Enum.OrientationAlignmentMode.OneAttachment
                pointer.RigidityEnabled = false
                pointer.MaxAngularVelocity = 90
                pointer.Responsiveness = 200
                pointer.CFrame = CFrame.lookAt(Vector3.zero, moveDirection)
            end)
        end
    end)
end

S.setVeeronicaFreeMove = function(value)
    S.isVeeronicaFreeMoveEnabled = value == true
    if not S.isVeeronicaFreeMoveEnabled then
        S.__helpers.stopVeeronicaFreeMove()
    end
end

S.veeronicaFreeMoveHeartbeatConnection = S.__helpers.connect(
    S.RunService.Heartbeat,
    function()
        if not S.isVeeronicaFreeMoveEnabled
            or not S.__helpers.isLocalRole("Survivor") then
            if S.veeronicaFreeMoveActive then
                S.__helpers.stopVeeronicaFreeMove()
            end
            return
        end

        local character = S.lp and S.lp.Character
        if not character or not S.isCharacterInRoleFolder(character, "Survivors") then
            if S.veeronicaFreeMoveActive then
                S.__helpers.stopVeeronicaFreeMove()
            end
            return
        end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health <= 0 or not root
            or not S.__helpers.isVeeronicaFreeMoveAnimationPlaying(humanoid) then
            if S.veeronicaFreeMoveActive then
                S.__helpers.stopVeeronicaFreeMove()
            end
            return
        end

        if S.veeronicaFreeMoveActive
            and (S.veeronicaFreeMoveActiveCharacter ~= character
                or S.veeronicaFreeMoveActiveHumanoid ~= humanoid) then
            S.__helpers.stopVeeronicaFreeMove()
        end

        if not S.veeronicaFreeMoveActive then
            S.__helpers.startVeeronicaFreeMove(character, humanoid, root)
        end
    end
)

-- ================================================================

-- CHANCE AIMBOT
-- Uses Nolsaken target selection, animation polling and ping-aware prediction.
-- ================================================================
S.ChanceAimbot = {
    enabled = false,
    aimDuration = 1.7,
    prediction = 4,
    targets = {
        "Slasher",
        "c00lkidd",
        "JohnDoe",
        "1x1x1x1",
        "Noli",
        "Sixer",
        "Nosferatu",
    },
    trackedAnimations = {
        ["103601716322988"] = true,
        ["133491532453922"] = true,
        ["86371356500204"] = true,
        ["76649505662612"] = true,
        ["81698196845041"] = true,
    },
    humanoid = nil,
    root = nil,
    lastTriggerTime = 0,
    aiming = false,
    originalWalkSpeed = nil,
    originalJumpPower = nil,
    originalAutoRotate = nil,
    targetRoot = nil,
}

S.ChanceAimbot.getTargetRoot = function()
    local killersFolder =
        workspace:FindFirstChild("Players")
        and workspace.Players:FindFirstChild("Killers")
    if not killersFolder then return nil end

    for _, name in ipairs(S.ChanceAimbot.targets) do
        local target = killersFolder:FindFirstChild(name)
        local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
        if targetRoot then return targetRoot end
    end
    return nil
end

S.ChanceAimbot.restoreMovement = function()
    local state = S.ChanceAimbot
    local humanoid = state.humanoid
    if humanoid
        and state.originalWalkSpeed ~= nil
        and state.originalJumpPower ~= nil
        and state.originalAutoRotate ~= nil then
        pcall(function()
            humanoid.WalkSpeed = state.originalWalkSpeed
            humanoid.JumpPower = state.originalJumpPower
            humanoid.AutoRotate = state.originalAutoRotate
        end)
    end

    state.originalWalkSpeed = nil
    state.originalJumpPower = nil
    state.originalAutoRotate = nil
    state.aiming = false
    state.targetRoot = nil
end

S.ChanceAimbot.setupCharacter = function(character)
    local state = S.ChanceAimbot
    state.restoreMovement()
    state.humanoid = nil
    state.root = nil
    if not character then return end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
        or character:WaitForChild("Humanoid", 5)
    local root = character:FindFirstChild("HumanoidRootPart")
        or character:WaitForChild("HumanoidRootPart", 5)
    state.humanoid = humanoid
    state.root = root
end

if S.lp.Character then
    S.ChanceAimbot.setupCharacter(S.lp.Character)
end

S.__helpers.connect(S.lp.CharacterAdded, function(character)
    S.ChanceAimbot.setupCharacter(character)
end)

S.__helpers.connect(S.RunService.Heartbeat, function()
    local state = S.ChanceAimbot
    local humanoid = state.humanoid
    local root = state.root

    if not S.__helpers.isLocalRole("Survivor") then
        if state.aiming then state.restoreMovement() end
        return
    end

    if not state.enabled or not humanoid or not root
        or not humanoid.Parent or not root.Parent then
        if state.aiming then state.restoreMovement() end
        return
    end

    local targetRoot = state.getTargetRoot()
    if not targetRoot then
        if state.aiming then state.restoreMovement() end
        return
    end
    state.targetRoot = targetRoot

    -- Nolsaken checks the local character's currently playing animation tracks
    -- on Heartbeat instead of relying on AnimationPlayed events.
    local triggered = false
    for _, track in ipairs(humanoid:GetPlayingAnimationTracks()) do
        local animation = track and track.Animation
        local animationId = animation and tostring(animation.AnimationId or ""):match("%d+")
        if animationId and state.trackedAnimations[animationId] then
            triggered = true
            break
        end
    end

    local currentTime = os.clock()
    if triggered then
        state.lastTriggerTime = currentTime
        state.aiming = true
    end

    if state.aiming and currentTime - state.lastTriggerTime <= state.aimDuration then
        if state.originalWalkSpeed == nil then
            state.originalWalkSpeed = humanoid.WalkSpeed
            state.originalJumpPower = humanoid.JumpPower
            state.originalAutoRotate = humanoid.AutoRotate
        end

        humanoid.AutoRotate = false
        root.AssemblyAngularVelocity = Vector3.zero
        root.AssemblyLinearVelocity = Vector3.zero

        local pingMilliseconds = 50
        pcall(function()
            local pingText = game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValueString()
            pingMilliseconds = tonumber(tostring(pingText):match("%d+")) or pingMilliseconds
        end)
        local pingSeconds = pingMilliseconds / 1000

        local targetVelocity = targetRoot.Velocity
        local moveDirection = targetVelocity.Magnitude > 0.1
            and targetVelocity.Unit
            or targetRoot.CFrame.LookVector
        local pingOffset = moveDirection * (pingSeconds * math.max(targetVelocity.Magnitude, 10))
        local prediction = tonumber(state.prediction) or 4
        local predictedPosition = targetRoot.Position
            + pingOffset
            + (targetRoot.CFrame.LookVector * prediction)
        local offset = predictedPosition - root.Position
        if offset.Magnitude > 0.001 then
            local direction = offset.Unit
            local yRotation = math.atan2(-direction.X, -direction.Z)
            root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, yRotation, 0)
        end

        humanoid.WalkSpeed = 0.6
        humanoid.JumpPower = 0
    elseif state.aiming then
        state.restoreMovement()
    end
end)

-- Cursedsaken Chance Shoot 360 Spin port. The source attaches this behavior to
-- Chance's AimGun animation and uses a half-second spin window. The deobfuscated
-- source omits the RenderStepped callback body, so this implementation performs
-- one complete local root yaw rotation over that same 0.5-second window.
S.ChanceShoot360Spin = {
    enabled = false,
    duration = 0.5,
    animationIds = {},
    animationConnection = nil,
    spinConnection = nil,
    token = 0,
    humanoid = nil,
    originalAutoRotate = nil,
}

S.__helpers.collectChanceAimGunAnimationIds = function()
    local ids = {}
    local function addAnimation(value)
        if typeof(value) == "Instance" and value:IsA("Animation") then
            value = value.AnimationId
        elseif type(value) == "table" then
            value = value.AnimationId or value.Id or value.ID
        end
        if type(value) == "string" or type(value) == "number" then
            local id = tostring(value):match("%d+")
            if id then ids[id] = true end
        end
    end

    local assets = S.ReplicatedStorage and S.ReplicatedStorage:FindFirstChild("Assets")
    local survivors = assets and assets:FindFirstChild("Survivors")
    local chance = survivors and survivors:FindFirstChild("Chance")
    local baseConfig = chance and chance:FindFirstChild("Config")
    if baseConfig and baseConfig:IsA("ModuleScript") then
        local okConfig, config = pcall(require, baseConfig)
        if okConfig and type(config) == "table" and type(config.Animations) == "table" then
            addAnimation(config.Animations.AimGun)
        end
    end

    local skins = assets and assets:FindFirstChild("Skins")
    local skinSurvivors = skins and skins:FindFirstChild("Survivors")
    local chanceSkins = skinSurvivors and skinSurvivors:FindFirstChild("Chance")
    if chanceSkins then
        for _, skin in ipairs(chanceSkins:GetChildren()) do
            local configModule = skin:FindFirstChild("Config")
            if configModule and configModule:IsA("ModuleScript") then
                local okConfig, config = pcall(require, configModule)
                if okConfig and type(config) == "table" and type(config.Animations) == "table" then
                    addAnimation(config.Animations.AimGun)
                end
            end
        end
    end
    return ids
end

S.__helpers.stopChanceShoot360Spin = function()
    local state = S.ChanceShoot360Spin
    if not state then return end
    state.token += 1
    if state.spinConnection then
        pcall(function() state.spinConnection:Disconnect() end)
        state.spinConnection = nil
    end
    if state.humanoid and state.humanoid.Parent and state.originalAutoRotate ~= nil then
        pcall(function() state.humanoid.AutoRotate = state.originalAutoRotate end)
    end
    state.humanoid = nil
    state.originalAutoRotate = nil
end

S.__helpers.startChanceShoot360Spin = function(character)
    local state = S.ChanceShoot360Spin
    if not state or not state.enabled or not character
        or character ~= (S.lp and S.lp.Character)
        or not S.__helpers.isLocalRole("Survivor")
        or character.Name ~= "Chance" then
        return false
    end

    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then return false end

    S.__helpers.stopChanceShoot360Spin()
    state.token += 1
    local token = state.token
    state.humanoid = humanoid
    state.originalAutoRotate = humanoid.AutoRotate
    pcall(function() humanoid.AutoRotate = false end)
    local baseRotation = root.CFrame - root.Position
    local startedAt = os.clock()
    local duration = math.max(0.1, tonumber(state.duration) or 0.5)

    state.spinConnection = S.RunService.RenderStepped:Connect(function()
        if token ~= state.token or not state.enabled
            or character ~= (S.lp and S.lp.Character)
            or not S.__helpers.isLocalRole("Survivor")
            or not character.Parent or not root.Parent or not humanoid.Parent then
            S.__helpers.stopChanceShoot360Spin()
            return
        end
        local alpha = math.clamp((os.clock() - startedAt) / duration, 0, 1)
        local yaw = math.pi * 2 * alpha
        pcall(function()
            root.AssemblyAngularVelocity = Vector3.zero
            root.CFrame = CFrame.new(root.Position) * baseRotation * CFrame.Angles(0, yaw, 0)
        end)
        if alpha >= 1 then
            S.__helpers.stopChanceShoot360Spin()
        end
    end)
    return true
end

S.__helpers.setupChanceShoot360SpinCharacter = function(character)
    local state = S.ChanceShoot360Spin
    if not state then return end
    if state.animationConnection then
        pcall(function() state.animationConnection:Disconnect() end)
        state.animationConnection = nil
    end
    S.__helpers.stopChanceShoot360Spin()
    state.animationIds = S.__helpers.collectChanceAimGunAnimationIds()

    if not character or character.Name ~= "Chance" then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
        or character:WaitForChild("Humanoid", 5)
    local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator")
        or humanoid:WaitForChild("Animator", 5))
    if not animator then return end

    state.animationConnection = S.__helpers.connect(animator.AnimationPlayed, function(track)
        if not state.enabled or not track or not track.Animation
            or character ~= (S.lp and S.lp.Character)
            or not S.__helpers.isLocalRole("Survivor") then
            return
        end
        local animation = track.Animation
        local animationId = tostring(animation.AnimationId or ""):match("%d+")
        local isAimGun = (animationId and state.animationIds[animationId] == true)
            or tostring(animation.Name or ""):lower():find("aimgun", 1, true) ~= nil
        if isAimGun then
            task.spawn(S.__helpers.startChanceShoot360Spin, character)
        end
    end)
end

if S.lp.Character then
    S.__helpers.setupChanceShoot360SpinCharacter(S.lp.Character)
end
S.__helpers.connect(S.lp.CharacterAdded, function(character)
    S.__helpers.setupChanceShoot360SpinCharacter(character)
end)


S.getClosestLivingModelInRole = function(roleName, originPosition)
    if typeof(originPosition) ~= "Vector3" then
        return nil
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local roleFolder = playersFolder and playersFolder:FindFirstChild(roleName)
    if not roleFolder then
        return nil
    end

    local closestModel = nil
    local closestDistance = math.huge
    for _, model in ipairs(roleFolder:GetChildren()) do
        if model:IsA("Model") then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local root = model:FindFirstChild("HumanoidRootPart")
            if humanoid and humanoid.Health > 0 and root then
                local distance = (root.Position - originPosition).Magnitude
                if distance < closestDistance then
                    closestDistance = distance
                    closestModel = model
                end
            end
        end
    end

    return closestModel
end

-- ================================================================
-- E1LU4SAKEN AIM FEATURES (adapted to E1LU4HUB state/UI)
-- ================================================================
S.__helpers.getClosestAimTarget = function(roleName, originPosition, maxDistance)
    local playersFolder = workspace:FindFirstChild("Players")
    local roleFolder = playersFolder and playersFolder:FindFirstChild(roleName)
    local localCharacter = S.lp and S.lp.Character
    if not roleFolder or typeof(originPosition) ~= "Vector3" then
        return nil
    end

    local best, bestDistance = nil, tonumber(maxDistance) or math.huge
    for _, model in ipairs(roleFolder:GetChildren()) do
        if model:IsA("Model") and model ~= localCharacter then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local root = model:FindFirstChild("HumanoidRootPart")
            if humanoid and humanoid.Health > 0 and root then
                local distance = (root.Position - originPosition).Magnitude
                if distance <= bestDistance then
                    best, bestDistance = model, distance
                end
            end
        end
    end
    return best
end

S.__helpers.getClosestAimTargetToMouse = function(roleName)
    local playersFolder = workspace:FindFirstChild("Players")
    local roleFolder = playersFolder and playersFolder:FindFirstChild(roleName)
    local camera = workspace.CurrentCamera
    if not roleFolder or not camera then return nil end

    local pointer = S.UserInputService:GetMouseLocation()
    local best, bestDistance = nil, math.huge
    for _, model in ipairs(roleFolder:GetChildren()) do
        if model:IsA("Model") and model ~= (S.lp and S.lp.Character) then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local root = model:FindFirstChild("HumanoidRootPart")
            if humanoid and humanoid.Health > 0 and root then
                local viewportPosition, onScreen = camera:WorldToViewportPoint(root.Position)
                if onScreen then
                    local distance = (Vector2.new(viewportPosition.X, viewportPosition.Y) - pointer).Magnitude
                    if distance < bestDistance then
                        best, bestDistance = model, distance
                    end
                end
            end
        end
    end
    return best
end

S.__helpers.predictAimPosition = function(model)
    local root = model and model:FindFirstChild("HumanoidRootPart")
    local humanoid = model and model:FindFirstChildOfClass("Humanoid")
    if not root then return nil end
    local position = root.Position
    if humanoid then
        pcall(function()
            position = position + humanoid.MoveDirection * (humanoid:GetMoveVelocity() / 20)
        end)
    end
    return position
end

S.__helpers.startE1LU4SAKENAim = function(featureKey, targetRole, maxDistance, timeout, activePredicate, useArmAim)
    local character = S.lp and S.lp.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not root or not humanoid or humanoid.Health <= 0 then return end

    local tokens = S.E1LU4SAKENAimTokens
    tokens[featureKey] = (tokens[featureKey] or 0) + 1
    local token = tokens[featureKey]
    local startedAt = os.clock()
    local seenActive = activePredicate == nil
    local activeGrace = 0.85
    -- The local user's role, not the target's role, determines when the aim loop is valid.
    -- This matters for Eliot, who throws pizza at another survivor.
    local expectedRole = S.isCharacterInRoleFolder(character, "Killers") and "Killers" or "Survivors"

    task.spawn(function()
        while os.clock() - startedAt <= (tonumber(timeout) or 6) do
            if tokens[featureKey] ~= token or character ~= S.lp.Character
                or not character.Parent or not S.isCharacterInRoleFolder(character, expectedRole) then
                break
            end

            local elapsed = os.clock() - startedAt
            local active = true
            if activePredicate then
                local ok, result = pcall(activePredicate, character, elapsed)
                active = ok and result == true
                if active then
                    seenActive = true
                elseif seenActive then
                    break
                elseif elapsed > activeGrace then
                    break
                end
            end

            if active then
                root = character:FindFirstChild("HumanoidRootPart")
                if not root then break end
                local target = S.__helpers.getClosestAimTarget(targetRole, root.Position, maxDistance)
                local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
                local targetHumanoid = target and target:FindFirstChildOfClass("Humanoid")
                if targetRoot and targetHumanoid and targetHumanoid.Health > 0 then
                    local aimPosition = targetRoot.Position
                    if useArmAim then
                        local armWorldPosition = root.CFrame * Vector3.new(-1, 0, 0)
                        local direction = aimPosition - armWorldPosition
                        if direction.Magnitude > 0.001 then
                            pcall(function()
                                root.CFrame = CFrame.lookAt(root.Position, root.Position + direction.Unit)
                            end)
                        end
                    else
                        local flatTarget = Vector3.new(aimPosition.X, root.Position.Y, aimPosition.Z)
                        if (flatTarget - root.Position).Magnitude > 0.001 then
                            pcall(function() root.CFrame = CFrame.lookAt(root.Position, flatTarget) end)
                        end
                    end
                end
            end
            task.wait()
        end
    end)
end

S.__helpers.handleE1LU4SAKENAimAbility = function(connectionName, eventType, abilityValue)
    if connectionName ~= "UseActorAbility" then return end

    -- FireServerConnection can pass the ability as a string, a nested payload table,
    -- or a buffer depending on the game/network version. Normalize all known forms.
    local function extractAbility(value, depth)
        depth = depth or 0
        if depth > 5 or value == nil then return nil end
        if type(value) == "string" then
            local flat = value:lower():gsub("[%s_%-]", "")
            if flat:find("massinfection", 1, true)
                or flat:find("entanglement", 1, true)
                or flat:find("throwpizza", 1, true)
                or flat:find("uppercut", 1, true)
                or flat:find("corruptenergy", 1, true)
                or flat:find("voidrush", 1, true)
                or flat:find("grab", 1, true)
                or flat:find("unravel", 1, true)
                or flat:find("unearthing", 1, true)
                or flat:find("golemfissure", 1, true)
                or flat:find("golemshockwave", 1, true)
                or flat:find("infernalcry", 1, true) then
                return value
            end
        elseif typeof(value) == "buffer" then
            if type(buffer) == "table" and type(buffer.tostring) == "function" then
                local ok, decoded = pcall(buffer.tostring, value)
                if ok and type(decoded) == "string" then
                    return extractAbility(decoded, depth + 1)
                end
            end
        elseif type(value) == "table" then
            for _, nested in pairs(value) do
                local decoded = extractAbility(nested, depth + 1)
                if decoded then return decoded end
            end
        end
        return nil
    end

    local ability = extractAbility(abilityValue) or ""
    if ability == "" then return end
    local lowerAbility = ability:lower():gsub("[%s_%-]", "")
    local character = S.lp and S.lp.Character
    if not character then return end

    if character.Name:lower():gsub("%s+", "") == "azure"
        and S.isCharacterInRoleFolder(character, "Killers") then
        if S.AzureAim and S.AzureAim.tentacles
            and (lowerAbility:find("grab", 1, true) or lowerAbility:find("unravel", 1, true)) then
            S.__helpers.startE1LU4SAKENAim("AzureTentacles", "Survivors", 220, 2.2, nil, false)
        elseif S.AzureAim and S.AzureAim.unearthing
            and (lowerAbility:find("unearthing", 1, true)
                or lowerAbility:find("golemfissure", 1, true)
                or lowerAbility:find("golemshockwave", 1, true)) then
            S.__helpers.startE1LU4SAKENAim("AzureUnearthing", "Survivors", 220, 1.8, nil, false)
        end
    end

    if lowerAbility:find("massinfection", 1, true)
        and S.isMassInfectionAimbotEnabled
        and S.isCharacterInRoleFolder(character, "Killers") then
        S.__helpers.startE1LU4SAKENAim(
            "MassInfection", "Survivors", 130, 6,
            function(char)
                local multipliers = char:FindFirstChild("SpeedMultipliers")
                return multipliers ~= nil and multipliers:FindFirstChild("MassInfection") ~= nil
            end,
            false
        )
    elseif lowerAbility:find("entanglement", 1, true)
        and S.isEntanglementAimbotEnabled
        and S.isCharacterInRoleFolder(character, "Killers") then
        S.__helpers.startE1LU4SAKENAim(
            "Entanglement", "Survivors", 130, 6,
            function(char)
                local multipliers = char:FindFirstChild("SpeedMultipliers")
                return multipliers ~= nil and multipliers:FindFirstChild("Entanglement") ~= nil
            end,
            false
        )
    elseif lowerAbility:find("throwpizza", 1, true)
        and S.isEliotThrowPizzaAimbotEnabled
        and character.Name:lower() == "elliot"
        and S.isCharacterInRoleFolder(character, "Survivors") then
        S.__helpers.startE1LU4SAKENAim(
            "EliotThrowPizza", "Survivors", 25, 6,
            function(char)
                local pizza = char:FindFirstChild("Pizza")
                return pizza ~= nil and pizza.Transparency == 0
            end,
            true
        )
    elseif lowerAbility:find("uppercut", 1, true)
        and S.isNosferatuBloodHookAimbotEnabled
        and character.Name:lower() == "nosferatu"
        and S.isCharacterInRoleFolder(character, "Killers") then
        S.__helpers.startE1LU4SAKENAim("NosferatuBloodHook", "Survivors", 95, 2, nil, false)
    elseif lowerAbility:find("voidrush", 1, true)
        and S.isNoliRushAutoTargetEnabled
        and character.Name:lower():gsub("%s+", "") == "noli"
        and S.isCharacterInRoleFolder(character, "Killers") then
        -- Cursedsaken's VoidRush RenderStep callback is omitted in the deobfuscated
        -- source; this preserves its short Rush-only target-facing behavior.
        S.__helpers.startE1LU4SAKENAim("NoliRushAutoTarget", "Survivors", 180, 2.4, nil, false)
    elseif lowerAbility:find("corruptenergy", 1, true)
        and S.isJohnDoeCorruptEnergyAimbotEnabled
        and (character.Name:lower() == "johndoe" or character.Name:lower() == "john doe")
        and S.isCharacterInRoleFolder(character, "Killers") then
        local duration = 2.5
        pcall(function()
            local assets = S.ReplicatedStorage:FindFirstChild("Assets")
            local killers = assets and assets:FindFirstChild("Killers")
            local johnDoe = killers and (killers:FindFirstChild("JohnDoe") or killers:FindFirstChild("John Doe"))
            local configModule = johnDoe and johnDoe:FindFirstChild("Config")
            local config = configModule and require(configModule)
            if config then
                duration = (tonumber(config.DelayBetweenSpikeSummons) or 0.2)
                    * (tonumber(config.SpikeAmount) or 1)
                    + (tonumber(config.CorruptEnergyWindup) or 2)
            end
        end)
        S.__helpers.startE1LU4SAKENAim("JohnDoeCorruptEnergy", "Survivors", 95, duration, nil, false)
    end
end

S.__helpers.installE1LU4SAKENSilentAimHook = function()
    if S.E1LU4SAKENMousePositionHookInstalled or type(hookfunction) ~= "function" then return end
    local systems = S.ReplicatedStorage:FindFirstChild("Systems")
    local player = systems and systems:FindFirstChild("Player")
    local miscellaneous = player and player:FindFirstChild("Miscellaneous")
    local moduleScript = miscellaneous and miscellaneous:FindFirstChild("GetPlayerMousePosition")
    if not moduleScript or not moduleScript:IsA("ModuleScript") then return end

    local okRequire, mouseModule = pcall(require, moduleScript)
    if not okRequire or type(mouseModule) ~= "table" or type(mouseModule.GetMousePos) ~= "function" then return end

    local oldGetMousePos
    local replacement = function(...)
        local character = S.lp and S.lp.Character
        local target
        if character and character.Name:lower() == "dusekkar" and S.isDusekkarSilentAimEnabled then
            local targetRole = S.isDusekkarTargetSurvivorEnabled and "Survivors" or "Killers"
            target = S.__helpers.getClosestAimTargetToMouse(targetRole)
            local predicted = target and S.__helpers.predictAimPosition(target)
            if predicted then return predicted end
        elseif character and character.Name:lower() == "c00lkidd" and S.isC00lkiddCorruptNatureSilentAimEnabled then
            local targetModel = S.__helpers.getClosestAimTarget("Survivors", (character:FindFirstChild("HumanoidRootPart") or {}).Position or Vector3.zero, 130)
            local abilityContainer = S.__helpers.getMainUI()
            abilityContainer = abilityContainer and abilityContainer:FindFirstChild("AbilityContainer")
            local corruptButton = abilityContainer and abilityContainer:FindFirstChild("CorruptNature")
            local abilityName = corruptButton and corruptButton:FindFirstChild("AbilityName")
            if targetModel and (not abilityName or abilityName.Text ~= "Retract") then
                local predicted = S.__helpers.predictAimPosition(targetModel)
                if predicted then return predicted end
            end
        elseif character and character.Name:lower() == "noli" and S.isNoliVoidStarSilentAimEnabled then
            local localRoot = character:FindFirstChild("HumanoidRootPart")
            local targetModel = localRoot and S.__helpers.getClosestAimTarget("Survivors", localRoot.Position, 130)
            local targetRoot = targetModel and targetModel:FindFirstChild("HumanoidRootPart")
            if targetRoot then
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = {targetModel}
                local hit = workspace:Raycast(targetRoot.Position, Vector3.new(0, -1000, 0), params)
                return (hit and hit.Position) or targetRoot.Position
            end
        elseif character and character.Name == "007n7" and S.N7CloneFollow and S.N7CloneFollow.enabled then
            local clonePosition = S.__helpers.getN7CloneFollowPosition and S.__helpers.getN7CloneFollowPosition()
            if clonePosition then return clonePosition end
        elseif character and character.Name == "Sixer"
            and S.isSixerInfernalCryAimbotEnabled
            and S.isCharacterInRoleFolder(character, "Killers") then
            -- E1LU4SAKEN's Infernal Cry silent aim targets the Survivor closest to
            -- the mouse and supplies that Survivor's HumanoidRootPart position.
            local targetModel = S.__helpers.getClosestAimTargetToMouse("Survivors")
            local targetRoot = targetModel and targetModel:FindFirstChild("HumanoidRootPart")
            if targetRoot then return targetRoot.Position end
        end
        if oldGetMousePos then return oldGetMousePos(...) end
        return nil
    end
    local wrapped = replacement
    if type(newcclosure) == "function" then
        local okClosure, closure = pcall(newcclosure, replacement)
        if okClosure and type(closure) == "function" then wrapped = closure end
    end
    local okHook, original = pcall(function()
        return hookfunction(mouseModule.GetMousePos, wrapped)
    end)
    if okHook and type(original) == "function" then
        oldGetMousePos = original
        S.E1LU4SAKENMousePositionHookOriginal = original
        S.E1LU4SAKENMousePositionHookInstalled = true
    end
end

task.spawn(function()
    for _ = 1, 20 do
        if S.E1LU4SAKENMousePositionHookInstalled then break end
        pcall(S.__helpers.installE1LU4SAKENSilentAimHook)
        if S.E1LU4SAKENMousePositionHookInstalled then break end
        task.wait(0.5)
    end
end)

-- ================================================================
-- SHEDLETSKY AUTO SLASH (E1LU4SAKEN SETTINGS, DIRECT ABILITY CALL)
-- Auto Slash is only active for a living Survivor named Shedletsky. It does not
-- search for or click an ability GuiButton: it calls fireAbilityDirect("Slash").
-- Cooldown state is read from the game's Slash ability UI before every attempt;
-- if that state cannot be observed, the feature fails closed.
-- ================================================================
S.__helpers.setAutoSlashEnabled = function(enabled)
    local state = S.AutoSlash
    if not state then return false end

    state.token = (tonumber(state.token) or 0) + 1
    local runToken = state.token
    state.enabled = enabled == true
    if state.connection then
        pcall(function() state.connection:Disconnect() end)
        state.connection = nil
    end

    if not state.enabled then
        return true
    end

    state.connection = S.RunService.Heartbeat:Connect(function()
        if not state.enabled or state.token ~= runToken or state.busy then return end
        if not S.__helpers.isLocalRole("Survivor") then return end

        local character = S.lp and S.lp.Character
        if not character or character.Name ~= "Shedletsky" or not character.Parent then return end

        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        if not humanoid or humanoid.Health <= 0 or not root or not root:IsA("BasePart") then
            return
        end

        local target = S.getClosestLivingModelInRole("Killers", root.Position)
        local targetHumanoid = target and target:FindFirstChildOfClass("Humanoid")
        local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
        if not target or not targetRoot or not targetHumanoid or targetHumanoid.Health <= 0 then
            return
        end

        local distance = (targetRoot.Position - root.Position).Magnitude
        local maxDistance = math.clamp(tonumber(state.distance) or 10, 1, 30)
        if distance > maxDistance then return end

        local minimumDelay = math.max(0.05, tonumber(state.delay) or 0.1)
        if os.clock() - (tonumber(state.lastActivationAt) or 0) < minimumDelay then
            return
        end

        local readyCheck = S.__helpers.isV2AbilityReady
        if type(readyCheck) ~= "function" then return end
        local readyOK, slashReady = pcall(readyCheck, "Slash")
        if not readyOK or slashReady ~= true then return end

        state.busy = true
        task.spawn(function()
            local originalCFrame = nil
            local originalVelocity = nil
            local didTeleport = false
            local fireSucceeded = false

            local actionOK, actionError = pcall(function()
                if not state.enabled or state.token ~= runToken
                    or S.lp.Character ~= character
                    or not character.Parent or humanoid.Health <= 0
                    or not S.__helpers.isLocalRole("Survivor") then
                    return
                end

                -- Revalidate the target and cooldown immediately before activation.
                local currentTarget = target
                local currentTargetHumanoid = currentTarget:FindFirstChildOfClass("Humanoid")
                local currentTargetRoot = currentTarget:FindFirstChild("HumanoidRootPart")
                if not currentTarget.Parent or not currentTargetHumanoid
                    or currentTargetHumanoid.Health <= 0 or not currentTargetRoot then
                    return
                end
                local currentDistance = (currentTargetRoot.Position - root.Position).Magnitude
                if currentDistance > math.clamp(tonumber(state.distance) or 10, 1, 30) then
                    return
                end

                if state.tpEnabled then
                    originalCFrame = root.CFrame
                    originalVelocity = root.AssemblyLinearVelocity

                    local targetLook = Vector3.new(
                        currentTargetRoot.CFrame.LookVector.X,
                        0,
                        currentTargetRoot.CFrame.LookVector.Z
                    )
                    if targetLook.Magnitude < 0.001 then
                        targetLook = Vector3.new(0, 0, -1)
                    else
                        targetLook = targetLook.Unit
                    end
                    local behindDistance = math.clamp(tonumber(state.tpBehindDistance) or 3.5, 1, 10)
                    local behindPosition = currentTargetRoot.Position - targetLook * behindDistance
                    local facePosition = Vector3.new(
                        currentTargetRoot.Position.X,
                        behindPosition.Y,
                        currentTargetRoot.Position.Z
                    )
                    root.CFrame = CFrame.lookAt(behindPosition, facePosition)
                    didTeleport = true
                    task.wait(0.035)
                end

                if not state.enabled or state.token ~= runToken
                    or S.lp.Character ~= character then
                    return
                end

                local secondReadyOK, secondSlashReady = pcall(readyCheck, "Slash")
                if not secondReadyOK or secondSlashReady ~= true then
                    return
                end

                local directFire = S.__helpers.fireAbilityDirect
                if type(directFire) ~= "function" then
                    return
                end
                local fireOK, fired = pcall(directFire, "Slash")
                fireSucceeded = fireOK and fired == true
            end)

            if didTeleport and root and root.Parent and character == S.lp.Character then
                -- Keep the behind position briefly so the Slash request can use it,
                -- then return to the exact pre-TP pose and velocity.
                task.wait(0.14)
                pcall(function()
                    if root.Parent and character == S.lp.Character and originalCFrame then
                        root.CFrame = originalCFrame
                        if originalVelocity then
                            root.AssemblyLinearVelocity = originalVelocity
                        end
                    end
                end)
            end

            if actionOK and fireSucceeded then
                state.lastActivationAt = os.clock()
            elseif not actionOK then
                warn("[E1LU4HUB Auto Slash] " .. tostring(actionError))
            end
            state.busy = false
        end)
    end)
    return true
end

-- Shedletsky character-facing aim loop.
-- Use the same predicted horizontal rotation as Chance Aimbot, without moving
-- the character position or directly rotating CurrentCamera.
S.startShedletskyAimAssist = function(character)
    S.shedletskyAimbotToken += 1
    local aimToken = S.shedletskyAimbotToken

    -- Restore a previous run before replacing its state, so overlapping
    -- animation triggers cannot leave AutoRotate disabled.
    local previousState = S.shedletskyAimState
    if previousState and previousState.humanoid
        and previousState.originalAutoRotate ~= nil then
        pcall(function()
            previousState.humanoid.AutoRotate = previousState.originalAutoRotate
        end)
    end

    local aimState = {
        token = aimToken,
        humanoid = nil,
        originalAutoRotate = nil,
    }
    S.shedletskyAimState = aimState

    task.spawn(function()
        local startedAt = os.clock()
        while os.clock() - startedAt < 1 do
            if not S.isShedletskyAimbotEnabled
                or aimToken ~= S.shedletskyAimbotToken
                or character ~= S.lp.Character
                or not S.isCharacterInRoleFolder(character, "Survivors") then
                break
            end

            local humanoid = character:FindFirstChildOfClass("Humanoid")
            local root = character:FindFirstChild("HumanoidRootPart")
            if not humanoid or humanoid.Health <= 0 or not root then
                break
            end

            if aimState.humanoid ~= humanoid then
                aimState.humanoid = humanoid
                aimState.originalAutoRotate = humanoid.AutoRotate
            end

            -- Match Chance Aimbot: disable automatic turning and cancel angular
            -- momentum while rotating toward the target's predicted position.
            humanoid.AutoRotate = false
            root.AssemblyAngularVelocity = Vector3.zero

            local targetModel = S.getFirstValidKillerModel()
            local targetRoot = targetModel and targetModel:FindFirstChild("HumanoidRootPart")
            local targetHumanoid = targetModel and targetModel:FindFirstChildOfClass("Humanoid")
            if not targetRoot or not targetHumanoid or targetHumanoid.Health <= 0 then
                break
            end

            local prediction = S.ChanceAimbot
                and tonumber(S.ChanceAimbot.prediction) or 4
            local predictedPosition = targetRoot.Position
                + targetRoot.CFrame.LookVector * prediction
            local offset = predictedPosition - root.Position
            if offset.Magnitude > 0.001 then
                local direction = offset.Unit
                local yRot = math.atan2(-direction.X, -direction.Z)
                root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, yRot, 0)
            end

            task.wait(0.03)
        end

        -- Only the current run may restore the state. A superseded worker must
        -- not undo AutoRotate settings applied by a newer animation trigger.
        if S.shedletskyAimState == aimState then
            if aimState.humanoid and aimState.originalAutoRotate ~= nil then
                pcall(function()
                    aimState.humanoid.AutoRotate = aimState.originalAutoRotate
                end)
            end
            S.shedletskyAimState = nil
        end
    end)
end

-- Face the nearest living survivor for a fixed window after a killer animation starts.
-- This only changes the local root's horizontal facing; it does not teleport the character.
S.__helpers.hookCharacter = function(character)
    local humanoid = character:WaitForChild("Humanoid")
    local animator = humanoid:WaitForChild("Animator")

    if not animator then
        return
    end

    S.__helpers.connect(animator.AnimationPlayed, function(track)
        if not track or not track.Animation then
            return
        end

        local id =
            tostring(track.Animation.AnimationId or "")
            :gsub("%D", "")
        local animationName = tostring(track.Animation.Name or ""):lower()

        -- Noli Rush Auto Target animation fallback.
        if character.Name:lower():gsub("%s+", "") == "azure"
            and S.isCharacterInRoleFolder(character, "Killers") then
            if S.AzureAim and S.AzureAim.tentacles
                and (animationName:find("grab", 1, true) or animationName:find("unravel", 1, true)
                    or animationName:find("tentacle", 1, true)) then
                S.__helpers.startE1LU4SAKENAim("AzureTentacles", "Survivors", 220, 2.2, nil, false)
            elseif S.AzureAim and S.AzureAim.unearthing
                and (animationName:find("unearthing", 1, true) or animationName:find("golem", 1, true)) then
                S.__helpers.startE1LU4SAKENAim("AzureUnearthing", "Survivors", 220, 1.8, nil, false)
            end
        end

        if character.Name:lower():gsub("%s+", "") == "noli"
            and S.isNoliRushAutoTargetEnabled
            and animationName:find("voidrush", 1, true)
            and S.isCharacterInRoleFolder(character, "Killers") then
            S.__helpers.startE1LU4SAKENAim("NoliRushAutoTarget", "Survivors", 180, 2.4, nil, false)
        end

        -- Mass Infection and Entanglement are now started from the ability-use
        -- network call and follow E1LU4SAKEN's actual SpeedMultipliers active state.

        -- Shedletsky Aimbot: use the shared character-facing aim style.
        if id == S.SHEDLETSKY_AIMBOT_ANIMATION_ID
            and S.isShedletskyAimbotEnabled
            and S.isCharacterInRoleFolder(character, "Survivors") then
            S.startShedletskyAimAssist(character)
        end

    end)
end

if S.lp.Character then
    S.__helpers.hookCharacter(S.lp.Character)
end

S.__helpers.connect(S.lp.CharacterAdded, S.__helpers.hookCharacter)


-- AUTO M1 (Killer feature; existing E1LU4HUB toggle only)
-- No target-specific exceptions or extra images/UI are used.
do
    local autoM1 = {
        enabled = false,
        connection = nil,
        attacking = false,
        rangeRadius = 9,
        m1Delay = 0,
        guestDelay = 0.2,
    }
    S.AutoM1 = autoM1

    local abilityNames = {
        "Slash",
        "Stab",
        "Tag",
        "CarvingSlash",
        "Lacerate",
        "Perforating",
    }

    local abilityBufferBytes = {
        Slash = {3, 5, 0, 0, 0, 83, 108, 97, 115, 104},
        Stab = {3, 4, 0, 0, 0, 83, 116, 97, 98},
        Tag = {3, 3, 0, 0, 0, 84, 97, 103},
        CarvingSlash = {3, 13, 0, 0, 0, 67, 97, 114, 118, 105, 110, 103, 32, 83, 108, 97, 115, 104},
    }

    local function safePath(root, ...)
        local current = root
        for _, name in ipairs({...}) do
            if not current then
                return nil
            end
            current = current:FindFirstChild(name)
        end
        return current
    end

    local function makeAbilityBuffer(abilityName)
        local bytes = abilityBufferBytes[abilityName]
        local bufferAPI = buffer
        if not bytes or not bufferAPI
            or type(bufferAPI.create) ~= "function"
            or type(bufferAPI.writeu8) ~= "function" then
            return nil
        end

        local ok, result = pcall(function()
            local output = bufferAPI.create(#bytes)
            for i = 1, #bytes do
                bufferAPI.writeu8(output, i - 1, bytes[i])
            end
            return output
        end)
        return ok and result or nil
    end

    local function getAutoM1Remote()
        return safePath(S.ReplicatedStorage, "Modules", "Network", "Network", "RemoteEvent")
            or (S.getForsakenNetworkRemote and S.getForsakenNetworkRemote())
    end

    local function sendAutoM1Ability(remote, abilityName)
        if not remote then
            return false
        end

        local bytes = abilityBufferBytes[abilityName]
        if bytes then
            local payload = makeAbilityBuffer(abilityName)
            if not payload then
                return false
            end
            remote:FireServer("UseActorAbility", {payload})
        else
            remote:FireServer("UseActorAbility", abilityName)
        end
        return true
    end

    local function triggerAutoM1()
        if not S.__helpers.isLocalRole("Killer") then return end
        local remote = getAutoM1Remote()
        if not remote then
            return
        end

        -- Match the source's normal (non-special-case) path: issue the attack
        -- ability payloads while a survivor is inside the configured range.
        for _, abilityName in ipairs(abilityNames) do
            pcall(sendAutoM1Ability, remote, abilityName)
        end
    end

    local function isGuest1337(survivor)
        if not survivor then
            return false
        end

        -- Match the source: ignore spaces and capitalization in the model name.
        local cleanName = tostring(survivor.Name):gsub("%s+", ""):lower()
        return cleanName == "guest1337"
    end

    local function isGuest1337Blocking(survivor)
        -- Forsaken exposes Guest 1337's active block state through the
        -- GuestBlocking speed multiplier while the block is active.
        if not isGuest1337(survivor) then
            return false
        end

        local speedMultipliers = survivor:FindFirstChild("SpeedMultipliers")
        return speedMultipliers ~= nil
            and speedMultipliers:FindFirstChild("GuestBlocking") ~= nil
    end

    local function isSurvivorInAutoM1Range(survivor, myRoot)
        local theirRoot = survivor:FindFirstChild("HumanoidRootPart")
        if not theirRoot then
            return false
        end

        local offset = theirRoot.Position - myRoot.Position
        local horizontalDistance = Vector3.new(offset.X, 0, offset.Z).Magnitude
        return horizontalDistance <= autoM1.rangeRadius
    end

    local function hasBlockingGuest1337InRange(survivorsFolder, myRoot)
        for _, survivor in ipairs(survivorsFolder:GetChildren()) do
            if survivor:IsA("Model")
                and isGuest1337(survivor)
                and isSurvivorInAutoM1Range(survivor, myRoot)
                and isGuest1337Blocking(survivor) then
                return true
            end
        end
        return false
    end

    autoM1.setEnabled = function(value)
        -- The setting remains selected off-role; the Heartbeat handler below
        -- returns unless the local character is actually a Killer.
        autoM1.enabled = value == true
        if not autoM1.enabled then
            if autoM1.connection then
                pcall(function()
                    autoM1.connection:Disconnect()
                end)
                autoM1.connection = nil
            end
            autoM1.attacking = false
            return
        end

        if autoM1.connection then
            return
        end

        autoM1.connection = S.__helpers.connect(S.RunService.Heartbeat, function()
            if not autoM1.enabled or autoM1.attacking then
                return
            end

            local character = S.lp and S.lp.Character
            local myRoot = character and character:FindFirstChild("HumanoidRootPart")
            if not character or not myRoot then
                return
            end

            local playersFolder = workspace:FindFirstChild("Players")
            local killersFolder = playersFolder and playersFolder:FindFirstChild("Killers")
            if not killersFolder or not character:IsDescendantOf(killersFolder) then
                return
            end

            local survivorsFolder = playersFolder and playersFolder:FindFirstChild("Survivors")
            if not survivorsFolder then
                return
            end

            local targetSurvivor = nil
            local isGuestTarget = false
            local blockingGuestInRange = false
            for _, survivor in ipairs(survivorsFolder:GetChildren()) do
                if survivor:IsA("Model") and isSurvivorInAutoM1Range(survivor, myRoot) then
                    local guestTarget = isGuest1337(survivor)

                    -- Because the M1 remote isn't bound to one specific target,
                    -- pause Auto M1 entirely while a blocking Guest 1337 is in range.
                    if guestTarget and isGuest1337Blocking(survivor) then
                        blockingGuestInRange = true
                        break
                    end

                    if not targetSurvivor then
                        targetSurvivor = survivor
                        isGuestTarget = guestTarget
                    end
                end
            end

            if targetSurvivor and not blockingGuestInRange then
                autoM1.attacking = true
                task.spawn(function()
                    local totalDelay = tonumber(autoM1.m1Delay) or 0
                    if isGuestTarget then
                        totalDelay = totalDelay + (tonumber(autoM1.guestDelay) or 0.2)
                    end
                    if totalDelay > 0 then
                        task.wait(totalDelay)
                    end

                    -- Recheck after the Guest 1337 pre-attack delay so Auto M1
                    -- also skips the hit if Guest 1337 starts blocking during it.
                    local targetStillExists = targetSurvivor
                        and targetSurvivor.Parent == survivorsFolder
                        and targetSurvivor:FindFirstChild("HumanoidRootPart") ~= nil
                    local guestStartedBlocking = targetStillExists
                        and isGuest1337(targetSurvivor)
                        and isGuest1337Blocking(targetSurvivor)

                    local blockingGuestNowInRange = hasBlockingGuest1337InRange(survivorsFolder, myRoot)
                    if autoM1.enabled
                        and targetStillExists
                        and not guestStartedBlocking
                        and not blockingGuestNowInRange then
                        pcall(triggerAutoM1)
                    end
                    task.wait(0.5)
                    autoM1.attacking = false
                end)
            end
        end)
    end
end

S.__helpers.createSectionHeader("AUTO M1")
S.__helpers.createCoolToggle("AUTO M1", false, function(value)
    if S.AutoM1 and S.AutoM1.setEnabled then
        S.AutoM1.setEnabled(value)
    end
end)

-- ================================================================
-- KILLER AIMBOT (Killer-only runtime gate)
-- ================================================================
do
    local aim = {
        enabled = false,
        cooldown = 0.3,
        lockTime = 0.4,
        maxDistance = 30,
        smoothing = 0.35,
        lastTriggered = 0,
        targetRoot = nil,
        humanoid = nil,
        root = nil,
        savedAutoRotate = nil,
        untilTime = 0,
    }
    S.KillerAimbot = aim

    local function refreshCharacter()
        local character = S.lp and S.lp.Character
        aim.humanoid = character and character:FindFirstChildOfClass("Humanoid") or nil
        aim.root = character and character:FindFirstChild("HumanoidRootPart") or nil
    end

    local function unlock()
        if aim.humanoid and aim.humanoid.Parent and aim.savedAutoRotate ~= nil then
            pcall(function() aim.humanoid.AutoRotate = aim.savedAutoRotate end)
        end
        aim.savedAutoRotate = nil
        aim.targetRoot = nil
        aim.untilTime = 0
    end

    local function nearestSurvivor()
        refreshCharacter()
        if not aim.root then return nil end
        local folder = workspace:FindFirstChild("Players")
        local survivors = folder and folder:FindFirstChild("Survivors")
        if not survivors then return nil end
        local best, bestDistance = nil, math.huge
        for _, model in ipairs(survivors:GetChildren()) do
            if model:IsA("Model") and model ~= S.lp.Character then
                local humanoid = model:FindFirstChildOfClass("Humanoid")
                local root = model:FindFirstChild("HumanoidRootPart")
                if humanoid and humanoid.Health > 0 and root then
                    local distance = (root.Position - aim.root.Position).Magnitude
                    if distance <= aim.maxDistance and distance < bestDistance then
                        best, bestDistance = root, distance
                    end
                end
            end
        end
        return best
    end

    S.__helpers.connect(S.RunService.RenderStepped, function()
        if not aim.enabled or not S.__helpers.isLocalRole("Killer") then
            if aim.targetRoot then unlock() end
            return
        end
        if not aim.targetRoot or not aim.targetRoot.Parent or os.clock() >= aim.untilTime then
            if aim.targetRoot then unlock() end
            return
        end
        refreshCharacter()
        if not aim.root or not aim.humanoid or aim.humanoid.Health <= 0 then
            unlock()
            return
        end
        local target = aim.targetRoot
        local flat = Vector3.new(target.Position.X - aim.root.Position.X, 0, target.Position.Z - aim.root.Position.Z)
        if flat.Magnitude > 0.001 then
            pcall(function()
                aim.root.CFrame = aim.root.CFrame:Lerp(
                    CFrame.lookAt(aim.root.Position, aim.root.Position + flat.Unit),
                    math.clamp(aim.smoothing, 0.05, 1)
                )
            end)
        end
    end)

    task.spawn(function()
        local remote
        for _ = 1, 30 do
            remote = S.getForsakenNetworkRemote and S.getForsakenNetworkRemote() or nil
            if remote and remote:IsA("RemoteEvent") then break end
            task.wait(0.5)
        end
        if not remote or not remote:IsA("RemoteEvent") then
            warn("[E1LU4HUB] Killer Aimbot: network event unavailable")
            return
        end
        S.__helpers.connect(remote.OnClientEvent, function(action)
            if not aim.enabled or not S.__helpers.isLocalRole("Killer") then return end
            if type(action) ~= "string" then return end
            local looksLikeAbility = action:find("Ability", 1, true)
                or action:match("^[QER]$") or action == "Slash" or action == "Dagger" or action == "Charge"
            if not looksLikeAbility or os.clock() - aim.lastTriggered < aim.cooldown then return end
            local target = nearestSurvivor()
            if not target then return end
            aim.lastTriggered = os.clock()
            refreshCharacter()
            if aim.humanoid and aim.root then
                if aim.savedAutoRotate == nil then aim.savedAutoRotate = aim.humanoid.AutoRotate end
                pcall(function() aim.humanoid.AutoRotate = false end)
                aim.targetRoot = target
                aim.untilTime = os.clock() + aim.lockTime
            end
        end)
    end)

    if S.lp then
        S.__helpers.connect(S.lp.CharacterAdded, function()
            task.wait(0.5)
            if aim.targetRoot then unlock() end
            refreshCharacter()
        end)
    end

    S.__helpers.createSectionHeader("AIMBOT")
    local aimSettingControls = {}
    local function setAimSettingsVisible(visible)
        for _, control in ipairs(aimSettingControls) do
            if control and control.Parent then control.Visible = true end
        end
    end
    S.__helpers.createCoolToggle("ENABLE AIMBOT", false, function(value)
        aim.enabled = value == true
        setAimSettingsVisible(aim.enabled)
        if not aim.enabled or not S.__helpers.isLocalRole("Killer") then unlock() end
    end)
    local aimControl
    aimControl = S.__helpers.createNumericControl("Aimbot Cooldown (s)", aim.cooldown, 0.1, 2, 0.05, function(value)
        local number = tonumber(value); if number then aim.cooldown = math.clamp(number, 0.1, 2) end
    end)
    table.insert(aimSettingControls, aimControl)
    aimControl = S.__helpers.createNumericControl("Aimbot Lock Time (s)", aim.lockTime, 0.1, 3, 0.1, function(value)
        local number = tonumber(value); if number then aim.lockTime = math.clamp(number, 0.1, 3) end
    end)
    table.insert(aimSettingControls, aimControl)
    aimControl = S.__helpers.createNumericControl("Aimbot Max Distance", aim.maxDistance, 5, 100, 5, function(value)
        local number = tonumber(value); if number then aim.maxDistance = math.clamp(number, 5, 100) end
    end)
    table.insert(aimSettingControls, aimControl)
    aimControl = S.__helpers.createNumericControl("Aimbot Rotation Smoothing", aim.smoothing, 0.05, 1, 0.05, function(value)
        local number = tonumber(value); if number then aim.smoothing = math.clamp(number, 0.05, 1) end
    end)
    table.insert(aimSettingControls, aimControl)
    setAimSettingsVisible(aim.enabled)
end

-- ================================================================
-- ANTI-BACKSTAB (Killer-only runtime gate)
-- ================================================================
do
    local abs = {
        enabled = false, range = 40, duration = 1.5, locked = false,
        soundConnection = nil, scanThread = nil, rings = {}, gui = nil, label = nil,
    }
    local triggerSounds = { ["86710781315432"] = true, ["99820161736138"] = true }

    local function getTwoTimeModel()
        local players = workspace:FindFirstChild("Players")
        if not players then return nil end
        for _, folder in ipairs(players:GetChildren()) do
            local target = folder:FindFirstChild("TwoTime")
            if target and target:IsA("Model") then return target end
        end
        return nil
    end

    local function showLabel(visible)
        if not visible and (not abs.gui or not abs.gui.Parent) then return end
        local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
        if not playerGui then return end
        if not abs.gui or not abs.gui.Parent then
            abs.gui = Instance.new("ScreenGui")
            abs.gui.Name = "E1LU4HUB_AntiBackstab"
            abs.gui.ResetOnSpawn = false
            abs.gui.Parent = playerGui
            abs.label = Instance.new("TextLabel")
            abs.label.Name = "AntiBackstabMessage"
            abs.label.Size = UDim2.new(0, 500, 0, 50)
            abs.label.Position = UDim2.new(0.5, -250, 0.38, 0)
            abs.label.BackgroundTransparency = 1
            abs.label.Text = "At least they tried 😂"
            abs.label.TextColor3 = Color3.new(1, 1, 1)
            abs.label.TextStrokeTransparency = 0.4
            abs.label.TextStrokeColor3 = Color3.new(0, 0, 0)
            abs.label.Font = Enum.Font.GothamBold
            abs.label.TextSize = 32
            abs.label.TextTransparency = 1
            abs.label.Parent = abs.gui
        end
        if abs.label then
            pcall(function()
                S.TweenService:Create(abs.label, TweenInfo.new(visible and 0.15 or 0.3), {
                    TextTransparency = visible and 0 or 1
                }):Play()
            end)
        end
    end

    local function removeRing(model)
        local ring = abs.rings[model]
        if ring then pcall(function() ring:Destroy() end) end
        abs.rings[model] = nil
    end

    local function cleanupRings()
        for model in pairs(abs.rings) do removeRing(model) end
    end

    local function addRing(model)
        if not model or abs.rings[model] then return end
        local root = model:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local ring = Instance.new("Part")
        ring.Name = "E1LU4HUB_AntiBackstabRange"
        ring.Anchored = false
        ring.Shape = Enum.PartType.Cylinder
        ring.Size = Vector3.new(0.1, abs.range * 2, abs.range * 2)
        ring.Color = Color3.fromRGB(220, 50, 50)
        ring.Material = Enum.Material.ForceField
        ring.Transparency = 0.5
        ring.CanCollide = false
        ring.CanTouch = false
        ring.CanQuery = false
        ring.Massless = true
        ring.CFrame = root.CFrame * CFrame.Angles(0, 0, math.rad(90))
        ring.Parent = root
        local weld = Instance.new("WeldConstraint")
        weld.Part0 = root
        weld.Part1 = ring
        weld.Parent = ring
        abs.rings[model] = ring
    end

    local function trigger()
        if not abs.enabled or not S.__helpers.isLocalRole("Killer") or abs.locked then return end
        local character = S.lp and S.lp.Character
        local myRoot = character and character:FindFirstChild("HumanoidRootPart")
        local targetModel = getTwoTimeModel()
        local targetRoot = targetModel and targetModel:FindFirstChild("HumanoidRootPart")
        if not myRoot or not targetRoot or (myRoot.Position - targetRoot.Position).Magnitude > abs.range then return end
        abs.locked = true
        showLabel(true)
        task.spawn(function()
            local deadline = os.clock() + abs.duration
            while abs.enabled and S.__helpers.isLocalRole("Killer") and os.clock() < deadline do
                local currentCharacter = S.lp and S.lp.Character
                local currentRoot = currentCharacter and currentCharacter:FindFirstChild("HumanoidRootPart")
                if not currentRoot or not targetRoot.Parent then break end
                local target = Vector3.new(targetRoot.Position.X, currentRoot.Position.Y, targetRoot.Position.Z)
                if (target - currentRoot.Position).Magnitude > 0.001 then
                    pcall(function() currentRoot.CFrame = CFrame.lookAt(currentRoot.Position, target) end)
                end
                S.RunService.RenderStepped:Wait()
            end
            abs.locked = false
            showLabel(false)
        end)
    end

    local function checkSound(object)
        if not abs.enabled or not S.__helpers.isLocalRole("Killer") or not object:IsA("Sound") then return end
        local id = tostring(object.SoundId or ""):match("%d+")
        if id and triggerSounds[id] then trigger() end
    end

    local function stop()
        abs.enabled = false
        abs.locked = false
        if abs.soundConnection then abs.soundConnection:Disconnect(); abs.soundConnection = nil end
        if abs.scanThread then pcall(task.cancel, abs.scanThread); abs.scanThread = nil end
        cleanupRings()
        showLabel(false)
    end

    local function start()
        if abs.soundConnection then abs.soundConnection:Disconnect(); abs.soundConnection = nil end
        abs.soundConnection = S.__helpers.connect(workspace.DescendantAdded, function(object)
            if object:IsA("Sound") then checkSound(object) end
        end)
        for _, object in ipairs(workspace:GetDescendants()) do
            if object:IsA("Sound") then checkSound(object) end
        end
        if abs.scanThread then return end
        abs.scanThread = task.spawn(function()
            while abs.enabled do
                if S.__helpers.isLocalRole("Killer") then
                    local target = getTwoTimeModel()
                    if target then addRing(target) end
                    for model in pairs(abs.rings) do
                        if not model or not model.Parent then removeRing(model) end
                    end
                else
                    abs.locked = false
                    showLabel(false)
                    cleanupRings()
                end
                task.wait(1)
            end
            abs.scanThread = nil
        end)
    end

    S.__helpers.createSectionHeader("ANTI-BACKSTAB")
    local antiBackstabSettingControls = {}
    local function setAntiBackstabSettingsVisible(visible)
        for _, control in ipairs(antiBackstabSettingControls) do
            if control and control.Parent then control.Visible = true end
        end
    end
    S.__helpers.createCoolToggle("ENABLE ANTI-BACKSTAB", false, function(value)
        abs.enabled = value == true
        setAntiBackstabSettingsVisible(abs.enabled)
        if abs.enabled then start() else stop() end
    end)
    local antiBackstabControl
    antiBackstabControl = S.__helpers.createNumericControl("Anti-Backstab Detection Range", abs.range, 10, 120, 5, function(value)
        local number = tonumber(value); if number then abs.range = math.clamp(number, 10, 120); for _, ring in pairs(abs.rings) do if ring and ring.Parent then ring.Size = Vector3.new(0.1, abs.range * 2, abs.range * 2) end end end
    end)
    table.insert(antiBackstabSettingControls, antiBackstabControl)
    antiBackstabControl = S.__helpers.createNumericControl("Anti-Backstab Look Duration (s)", abs.duration, 0.3, 5, 0.1, function(value)
        local number = tonumber(value); if number then abs.duration = math.clamp(number, 0.3, 5) end
    end)
    table.insert(antiBackstabSettingControls, antiBackstabControl)
    setAntiBackstabSettingsVisible(abs.enabled)
end

-- ================================================================
-- BATS AIM ASSIST (Killer-only runtime gate)
-- ================================================================
do
    local bats = S.BatsAimAssist

    local function survivorVelocity(root)
        if not root then return Vector3.zero end
        local now = os.clock()
        local entry = bats.velocity[root]
        if not entry then
            bats.velocity[root] = { position = root.Position, time = now, value = Vector3.zero }
            return Vector3.zero
        end
        local dt = now - entry.time
        if dt <= 0 then return entry.value end
        local velocity = (root.Position - entry.position) / dt
        entry.position, entry.time, entry.value = root.Position, now, velocity
        return velocity
    end

    local function nearestSurvivor()
        if not S.__helpers.isLocalRole("Killer") then return nil end
        local character = S.lp and S.lp.Character
        local myRoot = character and character:FindFirstChild("HumanoidRootPart")
        local players = workspace:FindFirstChild("Players")
        local survivors = players and players:FindFirstChild("Survivors")
        if not myRoot or not survivors then return nil end
        local best, bestDistance = nil, math.huge
        for _, model in ipairs(survivors:GetChildren()) do
            if model:IsA("Model") then
                local hum = model:FindFirstChildOfClass("Humanoid")
                local root = model:FindFirstChild("HumanoidRootPart")
                if hum and hum.Health > 0 and root then
                    local predicted = root.Position + survivorVelocity(root) * bats.prediction
                        + Vector3.new(0, bats.depthOffset, 0)
                    local distance = (predicted - myRoot.Position).Magnitude
                    if distance <= bats.maxDistance and distance < bestDistance then
                        bestDistance = distance
                        best = { root = root, position = predicted }
                    end
                end
            end
        end
        return best
    end

    local function snapToTarget(target)
        if not bats.enabled or not S.__helpers.isLocalRole("Killer") or not target or not target.root or not target.root.Parent then return end
        local character = S.lp and S.lp.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local pos = target.position or target.root.Position
        local direction = Vector3.new(pos.X - root.Position.X, 0, pos.Z - root.Position.Z)
        if direction.Magnitude < 0.1 then return end
        pcall(function() root.CFrame = CFrame.lookAt(root.Position, root.Position + direction.Unit) end)
        local hum = character:FindFirstChildOfClass("Humanoid")
        if hum then pcall(function() hum.AutoRotate = true end) end
    end

    local function abilityContainsBat(data)
        if type(data) ~= "table" then return false end
        for _, item in ipairs(data) do
            if typeof(item) == "buffer" and type(buffer) == "table" and type(buffer.tostring) == "function" then
                local ok, str = pcall(buffer.tostring, item)
                if ok and tostring(str):lower():find("bat", 1, true) then return true end
            elseif type(item) == "string" and item:lower():find("bat", 1, true) then
                return true
            end
        end
        return false
    end

    task.spawn(function()
        local remote
        for _ = 1, 30 do
            remote = S.getForsakenNetworkRemote and S.getForsakenNetworkRemote() or nil
            if remote and remote:IsA("RemoteEvent") then break end
            task.wait(0.5)
        end
        if not remote or not remote:IsA("RemoteEvent") then
            warn("[E1LU4HUB] Bats Aim Assist: network event unavailable")
            return
        end
        S.__helpers.connect(remote.OnClientEvent, function(action, data)
            if not bats.enabled or not S.__helpers.isLocalRole("Killer") then return end
            if action ~= "UseActorAbility" or not abilityContainsBat(data) then return end
            local target = nearestSurvivor()
            if target then task.spawn(snapToTarget, target) end
        end)
    end)

    task.spawn(function()
        while true do
            task.wait(5)
            local now = os.clock()
            for root, entry in pairs(bats.velocity) do
                if not root or not root.Parent or now - entry.time > 2 then bats.velocity[root] = nil end
            end
        end
    end)

end

-- ================================================================

-- ANTI (E1LU4SAKEN ANTIS FEATURES, RESTYLED FOR E1LU4HUB)
-- ================================================================
do
    local antiState = {
        AntiSlowness = false,
        AntiSubspace = false,
        AntiBlindness = false,
        AntiGlitched = false,
        AntiSlateskin = false,
        AntiNausea = false,
        AntiStun = false,
        AntiHallu = false,
        AntiSlowOnLanding = false,
        AntiFootsteps = false,
        AntiClone007n7 = false,
        fallSlowToken = 0,
        cloneToken = 0,
    }
    S.AntiFeatures = antiState

    -- Keep a shared state reference so status-effect hooks continue reading the
    -- current toggle values if the UI script is re-executed.
    local hookRegistry = _G.E1LU4HUB_AntiEffectHooks
    if type(hookRegistry) ~= "table" then
        hookRegistry = {hooked = {}}
        _G.E1LU4HUB_AntiEffectHooks = hookRegistry
    end
    hookRegistry.hooked = hookRegistry.hooked or {}
    hookRegistry.state = antiState
    hookRegistry.notify = nil

    local function setCharacterAttribute(attributeName, value)
        local character = S.lp and S.lp.Character
        if character and character.Parent then
            pcall(function()
                character:SetAttribute(attributeName, value)
            end)
        end
    end

    -- E1LU4SAKEN's Anti fall slowness repeatedly asserts NoFallSlow while enabled.
    local function updateFallSlowness(value)
        antiState.AntiSlowOnLanding = value == true
        antiState.fallSlowToken += 1
        local token = antiState.fallSlowToken
        if not antiState.AntiSlowOnLanding then
            setCharacterAttribute("NoFallSlow", false)
            return
        end
        task.spawn(function()
            while antiState.AntiSlowOnLanding and antiState.fallSlowToken == token do
                setCharacterAttribute("NoFallSlow", true)
                task.wait(0.2)
            end
        end)
    end

    local function findFake007n7Clones()
        pcall(function()
            local map = workspace:FindFirstChild("Map")
            local ingame = map and map:FindFirstChild("Ingame")
            if not ingame then
                return
            end
            for _, object in ipairs(ingame:GetChildren()) do
                if object.Name == "007n7"
                    and object:GetAttribute("Username") ~= (S.lp and S.lp.Name) then
                    object:Destroy()
                    warn("[E1LU4HUB Anti] removed a fake 007n7 clone")
                end
            end
        end)
    end

    -- Disable Noli's fake NPC locally without removing any player character.
    local noliNpcOriginals = setmetatable({}, {__mode = "k"})
    local noliNpcEnabled = false
    local function getNoliNpcCandidates()
        local candidates = {}
        local playersFolder = workspace:FindFirstChild("Players")
        local killers = playersFolder and playersFolder:FindFirstChild("Killers")
        local map = workspace:FindFirstChild("Map")
        local ingame = map and map:FindFirstChild("Ingame")
        local folders = {}
        if killers then table.insert(folders, killers) end
        if ingame then table.insert(folders, ingame) end
        for _, folder in ipairs(folders) do
            for _, object in ipairs(folder:GetChildren()) do
                if object:IsA("Model") and object.Name:lower() == "noli"
                    and not S.Players:GetPlayerFromCharacter(object) then
                    table.insert(candidates, object)
                end
            end
        end
        return candidates
    end

    local function applyDisableNoliNPC(value)
        noliNpcEnabled = value == true
        if noliNpcEnabled then
            for _, npc in ipairs(getNoliNpcCandidates()) do
                if not noliNpcOriginals[npc] then
                    local okPivot, pivot = pcall(function() return npc:GetPivot() end)
                    noliNpcOriginals[npc] = {parent = npc.Parent, pivot = okPivot and pivot or nil}
                end
                pcall(function() npc.Parent = game:GetService("Lighting") end)
            end
        else
            for npc, original in pairs(noliNpcOriginals) do
                if npc then
                    pcall(function()
                        if original.parent and (original.parent == workspace or original.parent.Parent) then
                            npc.Parent = original.parent
                            if original.pivot then npc:PivotTo(original.pivot) end
                        end
                    end)
                end
                noliNpcOriginals[npc] = nil
            end
        end
    end

    local function formatRoundSeconds(value)
        local number = tonumber(value) or 0
        number = math.max(0, math.floor(number))
        local minutes = math.floor(number % 3600 / 60)
        local seconds = math.floor(number % 60)
        return string.format("%d:%02d", minutes, seconds)
    end

    local timerState = {enabled = false, ui = nil, value = nil, connections = {}, token = 0}
    local function disconnectTimerConnections()
        for _, connection in ipairs(timerState.connections) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(timerState.connections)
        timerState.ui = nil
        timerState.value = nil
    end
    local function updateCorrectTimer()
        if timerState.enabled and timerState.ui and timerState.ui.Parent and timerState.value then
            timerState.ui:SetAttribute("E1LU4HUB_TimerSelfUpdate", true)
            timerState.ui.Text = formatRoundSeconds(timerState.value:GetAttribute("TimeLeft"))
        end
    end
    local function bindCorrectTimer()
        if not timerState.enabled then return false end
        local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
        local timerValue = S.ReplicatedStorage:FindFirstChild("RoundTimer")
        local roundGui = playerGui and playerGui:FindFirstChild("RoundTimer")
        local timerUI = roundGui and roundGui:FindFirstChild("Time", true)
        if not timerValue or not timerUI or not timerUI:IsA("TextLabel") then return false end
        disconnectTimerConnections()
        timerState.ui, timerState.value = timerUI, timerValue
        if timerUI:GetAttribute("E1LU4HUB_OriginalTimerText") == nil then
            timerUI:SetAttribute("E1LU4HUB_OriginalTimerText", timerUI.Text)
        end
        table.insert(timerState.connections, timerUI:GetPropertyChangedSignal("Text"):Connect(function()
            if timerUI:GetAttribute("E1LU4HUB_TimerSelfUpdate") then
                timerUI:SetAttribute("E1LU4HUB_TimerSelfUpdate", nil)
            else
                timerUI:SetAttribute("E1LU4HUB_OriginalTimerText", timerUI.Text)
            end
            updateCorrectTimer()
        end))
        table.insert(timerState.connections, timerValue:GetAttributeChangedSignal("TimeLeft"):Connect(updateCorrectTimer))
        updateCorrectTimer()
        return true
    end
    local function setDisplayCorrectTimer(value)
        timerState.enabled = value == true
        timerState.token += 1
        local token = timerState.token
        if not timerState.enabled then
            local ui = timerState.ui
            disconnectTimerConnections()
            if ui and ui.Parent then
                pcall(function()
                    ui.Text = ui:GetAttribute("E1LU4HUB_OriginalTimerText") or ""
                end)
            end
            return
        end
        if bindCorrectTimer() then return end
        task.spawn(function()
            for _ = 1, 60 do
                if not timerState.enabled or timerState.token ~= token then return end
                task.wait(0.25)
                if bindCorrectTimer() then return end
            end
        end)
    end

    S.__helpers.setDisableNoliNPC = applyDisableNoliNPC
    S.__helpers.setDisplayCorrectTimer = setDisplayCorrectTimer

    -- Anti affects
    S.__helpers.createSectionHeader("ANTI AFFECTS")
    S.__helpers.createCoolToggle("Anti Slowness", false, function(value)
        antiState.AntiSlowness = value == true
    end)
    S.__helpers.createCoolToggle("Anti Subspace", false, function(value)
        antiState.AntiSubspace = value == true
    end)
    S.__helpers.createCoolToggle("Anti Blindness", false, function(value)
        antiState.AntiBlindness = value == true
    end)
    S.__helpers.createCoolToggle("Anti Glitched", false, function(value)
        antiState.AntiGlitched = value == true
    end)
    S.__helpers.createCoolToggle("Anti Slatekin Slow/FOV", false, function(value)
        antiState.AntiSlateskin = value == true
    end)
    S.__helpers.createCoolToggle("Anti Nausea", false, function(value)
        antiState.AntiNausea = value == true
    end)
    S.__helpers.createCoolToggle("Anti Stun + Hallucinate", false, function(value)
        antiState.AntiStun = value == true
        antiState.AntiHallu = value == true
    end)
    S.__helpers.createCoolToggle("Anti Fall Slowness", false, updateFallSlowness)
    S.__helpers.createCoolToggle("Anti Footsteps", false, function(value)
        antiState.AntiFootsteps = value == true
        setCharacterAttribute("FootstepsMuted", antiState.AntiFootsteps)
    end)

    S.__helpers.createSectionHeader("ANTI MISC")
    S.__helpers.createCoolToggle("Anti Clone 007n7", false, function(value)
        antiState.AntiClone007n7 = value == true
        antiState.cloneToken += 1
        local token = antiState.cloneToken
        if antiState.AntiClone007n7 then
            task.spawn(function()
                while antiState.AntiClone007n7 and antiState.cloneToken == token do
                    findFake007n7Clones()
                    task.wait(0.5)
                end
            end)
        end
    end)

    S.__helpers.createSectionHeader("NOLI ANTI")
    S.__helpers.createCoolToggle("Disable Noli's NPC", false, function(value)
        applyDisableNoliNPC(value)
    end)
    S.__helpers.createCoolToggle("Always Display Correct Timer", false, function(value)
        setDisplayCorrectTimer(value)
    end)

    -- If the NPC appears after the toggle is enabled, hide it on arrival too.
    do
        local playersFolder = workspace:FindFirstChild("Players")
        local killers = playersFolder and playersFolder:FindFirstChild("Killers")
        local map = workspace:FindFirstChild("Map")
        local ingame = map and map:FindFirstChild("Ingame")
        local function onPossibleNpcAdded(child)
            if noliNpcEnabled then
                task.delay(0.2, function()
                    if noliNpcEnabled and child and child.Parent then
                        applyDisableNoliNPC(true)
                    end
                end)
            end
        end
        if killers then S.__helpers.connect(killers.ChildAdded, onPossibleNpcAdded) end
        if ingame then S.__helpers.connect(ingame.ChildAdded, onPossibleNpcAdded) end
    end

    -- Restore character attributes across respawns, mirroring E1LU4SAKEN's behavior.
    S.__helpers.connect(S.lp.CharacterAdded, function(character)
        task.delay(0.25, function()
            if not character or not character.Parent or character ~= S.lp.Character then
                return
            end
            local playersFolder = workspace:FindFirstChild("Players")
            local spectators = playersFolder and playersFolder:FindFirstChild("Spectating")
            if character.Parent ~= spectators then
                if antiState.AntiFootsteps then
                    pcall(function()
                        character:SetAttribute("FootstepsMuted", true)
                    end)
                end
            end
            if antiState.AntiSlowOnLanding then
                pcall(function()
                    character:SetAttribute("NoFallSlow", true)
                end)
            end
        end)
    end)

    -- Hook the game's status-effect Applied functions once. Each hook is passive
    -- unless its corresponding E1LU4HUB toggle is turned on.
    local function findModule(path)
        local current = S.ReplicatedStorage
        for part in string.gmatch(path, "[^%.]+") do
            current = current and current:FindFirstChild(part)
            if not current then
                return nil
            end
        end
        return current
    end

    local function installEffectHook(path, stateKeys, effectNames)
        if type(hookfunction) ~= "function" then
            return
        end
        local moduleScript = findModule(path)
        if not moduleScript or not moduleScript:IsA("ModuleScript") or hookRegistry.hooked[moduleScript] then
            return
        end
        local okRequire, effectModule = pcall(require, moduleScript)
        if not okRequire or type(effectModule) ~= "table" or type(effectModule.Applied) ~= "function" then
            return
        end

        local oldApplied
        local replacement = function(...)
            local state = hookRegistry.state or antiState
            local blockedName
            for index, stateKey in ipairs(stateKeys) do
                if state[stateKey] then
                    blockedName = effectNames[index]
                    break
                end
            end
            if blockedName then
                return coroutine.yield()
            end
            if oldApplied then
                return oldApplied(...)
            end
        end
        local wrapped = replacement
        if type(newcclosure) == "function" then
            local okClosure, closure = pcall(newcclosure, replacement)
            if okClosure and type(closure) == "function" then
                wrapped = closure
            end
        end
        local okHook, original = pcall(function()
            return hookfunction(effectModule.Applied, wrapped)
        end)
        if okHook and type(original) == "function" then
            oldApplied = original
            hookRegistry.hooked[moduleScript] = true
        else
            warn("[E1LU4HUB Anti] unable to hook status effect: " .. path)
        end
    end

    installEffectHook("Modules.Schematics.StatusEffects.Slowness", {"AntiSlowness"}, {"slowness"})
    installEffectHook("Modules.Schematics.StatusEffects.SurvivorExclusive.Subspaced", {"AntiSubspace"}, {"subspace"})
    installEffectHook("Modules.Schematics.StatusEffects.Blindness", {"AntiBlindness"}, {"blindness"})
    installEffectHook("Modules.Schematics.StatusEffects.KillerExclusive.Glitched", {"AntiGlitched"}, {"glitched"})
    installEffectHook("Modules.Schematics.StatusEffects.Slateskin", {"AntiSlateskin"}, {"slateskin"})
    installEffectHook("Modules.Schematics.StatusEffects.Nausea", {"AntiNausea"}, {"nausea"})
    installEffectHook("Modules.Schematics.StatusEffects.Stunned", {"AntiStun", "AntiHallu"}, {"stun", "hallucinate"})
end

