-- Popup selection table used by Character, Emote, and Device controls.
S.PlopSpoofer.createDropdown = function(labelText, getOptions, defaultValue, callback)
    local button = Instance.new("TextButton")
    button.Name = "PlopSpooferDropdown_" .. labelText:gsub("%W", "")
    button:SetAttribute("E1LU4HUB_PopupOpener", true)
    button.Size = UDim2.new(0.92, 0, 0, 34)
    button.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
    button.BorderSizePixel = 0
    button.AutoButtonColor = true
    button.Text = labelText .. ": " .. tostring(defaultValue) .. "  ▾"
    button.TextColor3 = Color3.new(1, 1, 1)
    button.Font = Enum.Font.GothamBold
    button.TextSize = 11
    button.TextXAlignment = Enum.TextXAlignment.Left
    button.Parent = S.contentFrame
    local textPadding = Instance.new("UIPadding")
    textPadding.PaddingLeft = UDim.new(0, 10)
    textPadding.Parent = button
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 4)
    corner.Parent = button

    local currentValue = tostring(defaultValue)
    local dropdownEntry = {
        button = button,
        label = tostring(labelText),
        getOptions = getOptions,
        getValue = function() return currentValue end,
        setValue = nil,
        legacyConnection = nil,
        converted = false,
    }
    local function setDropdownValue(value, runCallback)
        value = tostring(value or "")
        local isValid = value == tostring(defaultValue)
        local optionsOK, options = pcall(function()
            return getOptions and getOptions() or {}
        end)
        if optionsOK and type(options) == "table" then
            for _, option in ipairs(options) do
                if tostring(option) == value then
                    isValid = true
                    break
                end
            end
        end
        if not isValid then return false end

        currentValue = value
        if dropdownEntry.converted and S.__helpers.refreshRightDropdownButton then
            S.__helpers.refreshRightDropdownButton(button)
        else
            button.Text = labelText .. ": " .. currentValue .. "  ▾"
        end
        if runCallback and type(callback) == "function" then
            local callbackOK, callbackError = pcall(callback, value)
            if not callbackOK then
                warn("[ELSEGUI / Config Dropdown] " .. labelText .. ": " .. tostring(callbackError))
                if S.__helpers.notify then S.__helpers.notify(labelText, "Could not apply selection.", 3.2) end
            elseif S.__helpers.notify then
                S.__helpers.notify(labelText, "Set to " .. currentValue .. ".", 3.2)
            end
        end
        return true
    end

    dropdownEntry.setValue = setDropdownValue
    S.plopSpooferDropdownRegistry = S.plopSpooferDropdownRegistry or {}
    table.insert(S.plopSpooferDropdownRegistry, dropdownEntry)

    table.insert(S.configDropdownRegistry, {
        button = button,
        label = labelText,
        defaultValue = tostring(defaultValue),
        getValue = function() return currentValue end,
        setValue = setDropdownValue,
    })

    local function showOptions()
        local old = S.screenGui:FindFirstChild("PlopSpooferSelectionPopup")
        if old then old:Destroy() end
        local options = getOptions and getOptions() or {}
        table.sort(options, function(a, b) return tostring(a):lower() < tostring(b):lower() end)
        local overlay = Instance.new("Frame")
        overlay.Name = "PlopSpooferSelectionPopup"
        overlay.Size = UDim2.fromScale(1, 1)
        overlay.BackgroundColor3 = Color3.new(0, 0, 0)
        overlay.BackgroundTransparency = 0.35
        overlay.Active = true
        overlay.ZIndex = 100
        overlay.Parent = S.screenGui

        local panel = Instance.new("Frame")
        panel.Name = "SelectionPanel"
        panel.AnchorPoint = Vector2.new(0.5, 0.5)
        panel.Position = UDim2.fromScale(0.5, 0.5)
        panel.Size = UDim2.new(0, 300, 0, 300)
        panel.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
        panel.BorderSizePixel = 0
        panel.ZIndex = 101
        panel.Parent = overlay
        local pc = Instance.new("UICorner")
        pc.CornerRadius = UDim.new(0, 7)
        pc.Parent = panel

        local title = Instance.new("TextLabel")
        title.BackgroundTransparency = 1
        title.Position = UDim2.new(0, 12, 0, 7)
        title.Size = UDim2.new(1, -52, 0, 28)
        title.Text = "Select " .. labelText
        title.TextColor3 = Color3.new(1, 1, 1)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 13
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.ZIndex = 102
        title.Parent = panel

        local close = Instance.new("TextButton")
        close.Position = UDim2.new(1, -34, 0, 6)
        close.Size = UDim2.new(0, 27, 0, 27)
        close.Text = "X"
        close.TextColor3 = Color3.new(1, 1, 1)
        close.BackgroundColor3 = Color3.fromRGB(150, 45, 45)
        close.BorderSizePixel = 0
        close.Font = Enum.Font.GothamBold
        close.TextSize = 12
        close.ZIndex = 102
        close.Parent = panel
        S.__helpers.connect(close.MouseButton1Click, function() overlay:Destroy() end)

        local search = Instance.new("TextBox")
        search.Position = UDim2.new(0, 10, 0, 40)
        search.Size = UDim2.new(1, -20, 0, 28)
        search.PlaceholderText = "Search..."
        search.Text = ""
        search.ClearTextOnFocus = false
        search.BackgroundColor3 = Color3.fromRGB(48, 47, 56)
        search.TextColor3 = Color3.new(1, 1, 1)
        search.PlaceholderColor3 = Color3.fromRGB(132, 130, 140)
        search.Font = Enum.Font.Gotham
        search.TextSize = 11
        search.BorderSizePixel = 0
        search.ZIndex = 102
        search.Parent = panel

        local scroll = Instance.new("ScrollingFrame")
        scroll.Position = UDim2.new(0, 10, 0, 76)
        scroll.Size = UDim2.new(1, -20, 1, -86)
        scroll.BackgroundColor3 = Color3.fromRGB(26, 25, 30)
        scroll.BorderSizePixel = 0
        scroll.ScrollBarThickness = 4
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        scroll.ZIndex = 102
        scroll.Parent = panel
        local list = Instance.new("UIListLayout")
        list.Padding = UDim.new(0, 3)
        list.SortOrder = Enum.SortOrder.LayoutOrder
        list.Parent = scroll
        local pad = Instance.new("UIPadding")
        pad.PaddingTop = UDim.new(0, 4)
        pad.PaddingBottom = UDim.new(0, 4)
        pad.PaddingLeft = UDim.new(0, 4)
        pad.PaddingRight = UDim.new(0, 4)
        pad.Parent = scroll

        local function rebuild()
            for _, child in ipairs(scroll:GetChildren()) do
                if child:IsA("TextButton") or child.Name == "ConfigListEmpty" then child:Destroy() end
            end
            local query = search.Text:lower()
            local shown = 0
            for _, option in ipairs(options) do
                option = tostring(option)
                if query == "" or option:lower():find(query, 1, true) then
                    shown += 1
                    local choice = Instance.new("TextButton")
                    choice.Size = UDim2.new(1, -2, 0, 27)
                    choice.BackgroundColor3 = option == currentValue and Color3.fromRGB(58, 56, 66) or Color3.fromRGB(43, 42, 49)
                    choice.BorderSizePixel = 0
                    choice.Text = option
                    choice.TextColor3 = Color3.new(1, 1, 1)
                    choice.Font = Enum.Font.GothamBold
                    choice.TextSize = 11
                    choice.TextXAlignment = Enum.TextXAlignment.Left
                    choice.ZIndex = 103
                    choice.LayoutOrder = shown
                    choice.Parent = scroll
                    local cp = Instance.new("UIPadding")
                    cp.PaddingLeft = UDim.new(0, 8)
                    cp.Parent = choice
                    S.__helpers.connect(choice.MouseButton1Click, function()
                        setDropdownValue(option, true)
                        overlay:Destroy()
                    end)
                end
            end
            if shown == 0 then
                local empty = Instance.new("TextLabel")
                empty.Name = "ConfigListEmpty"
                empty.Size = UDim2.new(1, -2, 0, 28)
                empty.BackgroundTransparency = 1
                empty.Text = "No matches"
                empty.TextColor3 = Color3.fromRGB(153, 151, 161)
                empty.Font = Enum.Font.Gotham
                empty.TextSize = 11
                empty.ZIndex = 103
                empty.Parent = scroll
            end
        end
        S.__helpers.connect(search:GetPropertyChangedSignal("Text"), rebuild)
        rebuild()
    end
    dropdownEntry.legacyConnection = S.__helpers.connect(button.MouseButton1Click, showOptions)
    return button
end

-- Multi-select dropdown used by Ghost Animations. It follows the same
-- button/popup styling as the existing PlopSpoofer dropdown control.
S.PlopSpoofer.createMultiDropdown = function(labelText, getOptions, initialSelection, callback)
    local selected = {}
    for _, value in ipairs(initialSelection or {}) do selected[tostring(value)] = true end
    local button = Instance.new("TextButton")
    button.Name = "PlopSpooferMultiDropdown_" .. labelText:gsub("%W", "")
    button:SetAttribute("E1LU4HUB_PopupOpener", true)
    button.Size = UDim2.new(0.92, 0, 0, 34)
    button.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
    button.BorderSizePixel = 0
    button.AutoButtonColor = true
    button.TextColor3 = Color3.new(1, 1, 1)
    button.Font = Enum.Font.GothamBold
    button.TextSize = 11
    button.TextXAlignment = Enum.TextXAlignment.Left
    button.Parent = S.contentFrame
    local textPadding = Instance.new("UIPadding")
    textPadding.PaddingLeft = UDim.new(0, 10)
    textPadding.Parent = button
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 4)
    corner.Parent = button
    local function refreshText()
        local count = 0
        for _ in pairs(selected) do count += 1 end
        button.Text = labelText .. ": " .. (count == 0 and "None" or (tostring(count) .. " selected")) .. "  ▾"
    end
    local function getSelection()
        local result = {}
        for _, option in ipairs(getOptions and getOptions() or {}) do
            option = tostring(option)
            if selected[option] then table.insert(result, option) end
        end
        return result
    end
    refreshText()
    local function showOptions()
        local old = S.screenGui:FindFirstChild("PlopSpooferMultiSelectionPopup")
        if old then old:Destroy() end
        local options = getOptions and getOptions() or {}
        table.sort(options, function(a, b) return tostring(a):lower() < tostring(b):lower() end)
        local overlay = Instance.new("Frame")
        overlay.Name = "PlopSpooferMultiSelectionPopup"
        overlay.Size = UDim2.fromScale(1, 1)
        overlay.BackgroundColor3 = Color3.new(0, 0, 0)
        overlay.BackgroundTransparency = 0.35
        overlay.Active = true
        overlay.ZIndex = 120
        overlay.Parent = S.screenGui
        local panel = Instance.new("Frame")
        panel.Name = "SelectionPanel"
        panel.AnchorPoint = Vector2.new(0.5, 0.5)
        panel.Position = UDim2.fromScale(0.5, 0.5)
        panel.Size = UDim2.new(0, 310, 0, 330)
        panel.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
        panel.BorderSizePixel = 0
        panel.ZIndex = 121
        panel.Parent = overlay
        local pc = Instance.new("UICorner")
        pc.CornerRadius = UDim.new(0, 7)
        pc.Parent = panel
        local title = Instance.new("TextLabel")
        title.BackgroundTransparency = 1
        title.Position = UDim2.new(0, 12, 0, 7)
        title.Size = UDim2.new(1, -52, 0, 28)
        title.Text = "Select " .. labelText
        title.TextColor3 = Color3.new(1, 1, 1)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 13
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.ZIndex = 122
        title.Parent = panel
        local close = Instance.new("TextButton")
        close.Position = UDim2.new(1, -34, 0, 6)
        close.Size = UDim2.new(0, 27, 0, 27)
        close.Text = "X"
        close.TextColor3 = Color3.new(1, 1, 1)
        close.BackgroundColor3 = Color3.fromRGB(150, 45, 45)
        close.BorderSizePixel = 0
        close.Font = Enum.Font.GothamBold
        close.TextSize = 12
        close.ZIndex = 122
        close.Parent = panel
        S.__helpers.connect(close.MouseButton1Click, function() overlay:Destroy() end)
        local search = Instance.new("TextBox")
        search.Position = UDim2.new(0, 10, 0, 40)
        search.Size = UDim2.new(1, -20, 0, 28)
        search.PlaceholderText = "Search..."
        search.Text = ""
        search.ClearTextOnFocus = false
        search.BackgroundColor3 = Color3.fromRGB(48, 47, 56)
        search.TextColor3 = Color3.new(1, 1, 1)
        search.PlaceholderColor3 = Color3.fromRGB(132, 130, 140)
        search.Font = Enum.Font.Gotham
        search.TextSize = 11
        search.BorderSizePixel = 0
        search.ZIndex = 122
        search.Parent = panel
        local scroll = Instance.new("ScrollingFrame")
        scroll.Position = UDim2.new(0, 10, 0, 76)
        scroll.Size = UDim2.new(1, -20, 1, -122)
        scroll.BackgroundColor3 = Color3.fromRGB(26, 25, 30)
        scroll.BorderSizePixel = 0
        scroll.ScrollBarThickness = 4
        scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        scroll.ZIndex = 122
        scroll.Parent = panel
        local layout = Instance.new("UIListLayout")
        layout.Padding = UDim.new(0, 3)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Parent = scroll
        local function rebuild()
            for _, child in ipairs(scroll:GetChildren()) do
                if child:IsA("TextButton") then child:Destroy() end
            end
            local query = search.Text:lower()
            local order = 0
            for _, rawOption in ipairs(options) do
                local option = tostring(rawOption)
                if query == "" or option:lower():find(query, 1, true) then
                    order += 1
                    local choice = Instance.new("TextButton")
                    choice.Size = UDim2.new(1, -2, 0, 27)
                    choice.BackgroundColor3 = selected[option] and Color3.fromRGB(74, 72, 88) or Color3.fromRGB(43, 42, 49)
                    choice.BorderSizePixel = 0
                    choice.Text = (selected[option] and "■  " or "□  ") .. option
                    choice.TextColor3 = Color3.new(1, 1, 1)
                    choice.Font = Enum.Font.GothamBold
                    choice.TextSize = 11
                    choice.TextXAlignment = Enum.TextXAlignment.Left
                    choice.ZIndex = 123
                    choice.LayoutOrder = order
                    choice.Parent = scroll
                    local cp = Instance.new("UIPadding")
                    cp.PaddingLeft = UDim.new(0, 8)
                    cp.Parent = choice
                    S.__helpers.connect(choice.MouseButton1Click, function()
                        selected[option] = not selected[option] or nil
                        rebuild()
                    end)
                end
            end
        end
        local apply = Instance.new("TextButton")
        apply.Position = UDim2.new(0, 10, 1, -37)
        apply.Size = UDim2.new(1, -20, 0, 27)
        apply.BackgroundColor3 = Color3.fromRGB(58, 56, 66)
        apply.BorderSizePixel = 0
        apply.Text = "Apply"
        apply.TextColor3 = Color3.new(1, 1, 1)
        apply.Font = Enum.Font.GothamBold
        apply.TextSize = 11
        apply.ZIndex = 123
        apply.Parent = panel
        S.__helpers.connect(apply.MouseButton1Click, function()
            refreshText()
            if type(callback) == "function" then pcall(callback, getSelection()) end
            overlay:Destroy()
        end)
        S.__helpers.connect(search:GetPropertyChangedSignal("Text"), rebuild)
        rebuild()
    end
    S.__helpers.connect(button.MouseButton1Click, showOptions)
    return button
end

-- ================================================================

-- TWO TIME BACKSTAB / GLIDESTAB
-- Ported into ELSEGUI's existing button/popup UI. Features are opt-in.
-- Existing standalone movement controls remain unchanged.
-- ================================================================
do
    local B = {
        stopped = false,
        autoBackstab = false,
        autoUseStab = false,
        autoUseStabRange = 15,
        autoUseStabCooldown = 0.75,
        autoUseStabLastTrigger = 0,
        autoUseStabAssistToken = 0,
        range = 8,
        duration = 0.7,
        behindDistance = 1.7,
        checkInterval = 0.12,
        cooldown = 5,
        lerpSpeed = 0.37,
        backstabType = "lerp",
        rangeMode = "Around",
        strictBehind = false,
        rotationLockCount = 0,
        rotationLockHumanoid = nil,
        rotationLockOriginalAutoRotate = nil,
        glideEnabled = false,
        glideType = "Legit",
        aimingMode = "Character",
        glideCooldown = 3,
        glideBesideTimeout = 1,
        glideDuration = 0.4,
        glideCheckRate = 0.06,
        targetAnimIds = {},
        targetAnimCacheBuilt = false,
        glideRange = 8,
        lungeHitboxMultiplier = 1,
        crouchHitboxMultiplier = 1,
        sourceAnimationConnection = nil,
        lastTrigger = 0,
        glideLastTime = 0,
    }
    S.AutoBackstab = B

    B.getCharacter = function()
        return S.lp and S.lp.Character
    end

    -- These features are specifically for the local Survivor TwoTime character,
    -- not for other Survivor characters or Killer-side play.
    B.isLocalTwoTimeSurvivor = function()
        local character = B.getCharacter()
        return character ~= nil
            and character.Name == "TwoTime"
            and S.__helpers.isLocalRole("Survivor")
    end

    B.getRoot = function(character)
        return character and character:FindFirstChild("HumanoidRootPart")
    end

    B.getKillersFolder = function()
        local playersFolder = workspace:FindFirstChild("Players")
        return playersFolder and playersFolder:FindFirstChild("Killers")
    end

    B.isValidKiller = function(model)
        if not model or not model:IsA("Model") then return false end
        local root = model:FindFirstChild("HumanoidRootPart")
        local humanoid = model:FindFirstChildWhichIsA("Humanoid")
        return root ~= nil and humanoid ~= nil and humanoid.Health > 0
    end

    B.isPlayerCharacter = function(model)
        return model ~= nil
            and model:IsA("Model")
            and model:FindFirstChildWhichIsA("Humanoid") ~= nil
            and S.Players:GetPlayerFromCharacter(model) ~= nil
    end

    -- E1LU4SAKEN's backstab gate: the local Two Time must be behind the Killer,
    -- no farther than 7 studs along the Killer's rear direction and within a
    -- 3.5-stud lateral tolerance.
    B.isFacingBackForAutoUseStab = function(root, killerRoot)
        if not root or not killerRoot then return false end
        local relative = root.Position - killerRoot.Position
        local backDirection = -killerRoot.CFrame.LookVector
        local behindDepth = relative:Dot(backDirection)
        if behindDepth <= 0 or behindDepth > 7 then return false end
        local lateralOffset = relative - backDirection * behindDepth
        return lateralOffset.Magnitude <= 3.5
    end

    -- Check the game's actual Dagger cooldown UI before attempting to aim or activate.
    -- If the ability button/state is unavailable, fail closed and do nothing.
    B.isDaggerReady = function()
        local checker = S.__helpers and S.__helpers.isV2AbilityReady
        if type(checker) ~= "function" then return false end
        local ok, ready = pcall(checker, "Dagger")
        return ok and ready == true
    end

    -- Activate Two Time's Dagger through the game ability function/remote.
    -- Readiness is checked separately; the server still validates the ability request.
    B.activateDaggerDirect = function()
        if not B.isLocalTwoTimeSurvivor() then return false end
        local fireAbility = S.__helpers and S.__helpers.fireAbilityDirect
        if type(fireAbility) ~= "function" then
            warn("[ELSEGUI / Glide Stab] Direct ability function is unavailable.")
            return false
        end
        local ok, result = pcall(fireAbility, "Dagger")
        return ok and result == true
    end

    B.refreshTargetAnimationIds = function()
        table.clear(B.targetAnimIds)
        B.targetAnimCacheBuilt = true
        local assets = S.ReplicatedStorage:FindFirstChild("Assets")
        local survivors = assets and assets:FindFirstChild("Survivors")
        local twoTime = survivors and survivors:FindFirstChild("TwoTime")
        local configModule = twoTime and twoTime:FindFirstChild("Config")
        local ok, config = pcall(function()
            return configModule and require(configModule)
        end)
        local stab = ok and config and config.Animations and config.Animations.Stab
        local function addIds(value)
            if type(value) == "table" then
                for _, nested in pairs(value) do addIds(nested) end
            elseif value ~= nil then
                local digits = tostring(value):match("%d+")
                if digits then B.targetAnimIds[digits] = true end
            end
        end
        addIds(stab)
        return next(B.targetAnimIds) ~= nil
    end

    B.isPlayingTargetAnim = function(character)
        if not character or character.Name ~= "TwoTime" then return false end
        local humanoid = character:FindFirstChildWhichIsA("Humanoid")
        if not humanoid then return false end
        if not B.targetAnimCacheBuilt then B.refreshTargetAnimationIds() end
        if not next(B.targetAnimIds) then return false end
        local ok, tracks = pcall(function() return humanoid:GetPlayingAnimationTracks() end)
        if not ok or not tracks then return false end
        for _, track in ipairs(tracks) do
            local animation = track.Animation
            local digits = animation and tostring(animation.AnimationId):match("%d+")
            if digits and B.targetAnimIds[digits] then return true end
        end
        return false
    end

    B.isBesideKiller = function(root, killerRoot, range)
        if not root or not killerRoot then return false end
        local relative = root.Position - killerRoot.Position
        local distance = Vector3.new(relative.X, 0, relative.Z).Magnitude
        if distance > (tonumber(range) or B.range) or relative.Magnitude <= 0 then return false end
        return math.abs(relative.Unit:Dot(killerRoot.CFrame.RightVector)) >= 0.9
    end

    B.findCandidateForAssist = function(killersFolder, root, range)
        if not killersFolder or not root then return nil end
        local nearest, nearestDistance = nil, math.huge
        for _, killer in ipairs(killersFolder:GetChildren()) do
            if B.isValidKiller(killer) then
                local killerRoot = killer:FindFirstChild("HumanoidRootPart")
                if killerRoot then
                    local distance = (killerRoot.Position - root.Position).Magnitude
                    if distance <= (tonumber(range) or math.huge) then
                        if B.isBesideKiller(root, killerRoot, range or math.huge) then
                            return killer
                        end
                        if distance < nearestDistance then
                            nearest, nearestDistance = killer, distance
                        end
                    end
                end
            end
        end
        return nearest
    end

    -- Shared AutoRotate lock used by Auto Backstab and Glide Stab.
    -- It restores the actual prior state instead of assuming AutoRotate was true.
    B.acquireRotationLock = function(humanoid)
        if not humanoid then return function() end end
        if B.rotationLockCount == 0 then
            B.rotationLockHumanoid = humanoid
            B.rotationLockOriginalAutoRotate = humanoid.AutoRotate
        end
        B.rotationLockCount += 1
        pcall(function() humanoid.AutoRotate = false end)
        local released = false
        return function()
            if released then return end
            released = true
            B.rotationLockCount = math.max(0, B.rotationLockCount - 1)
            if B.rotationLockCount == 0 then
                local savedHumanoid = B.rotationLockHumanoid
                local savedValue = B.rotationLockOriginalAutoRotate
                if savedHumanoid and savedHumanoid.Parent and savedValue ~= nil then
                    pcall(function() savedHumanoid.AutoRotate = savedValue end)
                end
                B.rotationLockHumanoid = nil
                B.rotationLockOriginalAutoRotate = nil
            end
        end
    end

    -- Auto Backstab works without a separate aim toggle.
    -- It continuously moves/turns toward the configured backstab pose while active.
    B.activateForKiller = function(killer, duration)
        if B.stopped or not B.isLocalTwoTimeSurvivor() then return end
        local character = B.getCharacter()
        local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
        local root = B.getRoot(character)
        local killerRoot = killer and killer:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or not killerRoot then return end

        local releaseRotationLock = B.acquireRotationLock(humanoid)
        local mode = tostring(B.backstabType or "lerp"):lower()
        local startedAt = os.clock()
        local maxDuration = math.max(0.05, tonumber(duration) or B.duration)
        local connection
        local finished = false

        local function finish()
            if finished then return end
            finished = true
            if connection then pcall(function() connection:Disconnect() end) end
            releaseRotationLock()
        end

        local function desiredCFrame()
            local look = killerRoot.CFrame.LookVector
            look = Vector3.new(look.X, 0, look.Z)
            if look.Magnitude < 0.001 then look = Vector3.new(0, 0, -1) end
            look = look.Unit

            local position = root.Position
            if mode == "lerp" or mode == "teleport" then
                local behind = killerRoot.Position - look * B.behindDistance
                position = Vector3.new(behind.X, root.Position.Y, behind.Z)
            end
            return CFrame.lookAt(position, position + look, Vector3.new(0, 1, 0))
        end

        connection = S.RunService.Heartbeat:Connect(function()
            if B.stopped or not B.isLocalTwoTimeSurvivor()
                or not root.Parent or not killerRoot.Parent
                or os.clock() - startedAt >= maxDuration then
                finish()
                return
            end
            pcall(function()
                local goal = desiredCFrame()
                if mode == "lerp" then
                    root.CFrame = root.CFrame:Lerp(goal, math.clamp(B.lerpSpeed, 0.01, 1))
                else
                    root.CFrame = goal
                end
            end)
        end)
    end


    B.stop = function()
        B.stopped = true
        if B.sourceAnimationConnection then pcall(function() B.sourceAnimationConnection:Disconnect() end); B.sourceAnimationConnection = nil end
        B.autoBackstab = false
        B.autoUseStab = false
        B.autoUseStabAssistToken += 1
        B.glideEnabled = false
        local character = B.getCharacter()
        local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
        if humanoid then pcall(function() humanoid.AutoRotate = true end) end
    end

    -- Main Auto Backstab watcher. Positioning and facing are always active when
    -- this toggle is enabled; no separate aim toggle is required.
    task.spawn(function()
        while not B.stopped do
            task.wait(B.checkInterval)
            if not B.autoBackstab or not B.isLocalTwoTimeSurvivor() then continue end
            local character = B.getCharacter()
            local root = B.getRoot(character)
            local killers = B.getKillersFolder()
            if not root or not killers then continue end
            for _, killer in ipairs(killers:GetChildren()) do
                if B.isValidKiller(killer) then
                    local killerRoot = killer:FindFirstChild("HumanoidRootPart")
                    if killerRoot then
                        local distance = (killerRoot.Position - root.Position).Magnitude
                        local shouldTrigger = false
                        if B.rangeMode == "Around" then
                            shouldTrigger = distance <= B.range
                        else
                            local relative = root.Position - killerRoot.Position
                            local forwardDot = relative:Dot(killerRoot.CFrame.LookVector)
                            local behindDistance = -forwardDot
                            local angleDot = relative.Magnitude > 0 and relative.Unit:Dot(killerRoot.CFrame.LookVector) or 0
                            local passesBehind = B.strictBehind and angleDot <= -0.85 or (not B.strictBehind and forwardDot < 0.3)
                            if passesBehind and behindDistance <= B.range and distance <= B.range and B.isPlayerCharacter(killer) then
                                shouldTrigger = true
                            end
                        end
                        if shouldTrigger and os.clock() - B.lastTrigger >= B.cooldown then
                            B.lastTrigger = os.clock()
                            task.spawn(function()
                                local ok, err = pcall(B.activateForKiller, killer, B.duration)
                                if not ok then warn("[ELSEGUI / Auto Backstab] " .. tostring(err)) end
                            end)
                            break
                        end
                    end
                end
            end
        end
    end)

    -- Auto Use Stab: when Two Time is already in E1LU4SAKEN's backstab position,
    -- activate Dagger once and briefly face/move toward the selected Killer.
    -- The ability readiness check and a local debounce prevent remote spam.
    task.spawn(function()
        while not B.stopped do
            task.wait(0.06)
            if not B.autoUseStab or not B.isLocalTwoTimeSurvivor() then
                continue
            end

            local now = os.clock()
            if now - B.autoUseStabLastTrigger < B.autoUseStabCooldown then
                continue
            end

            local character = B.getCharacter()
            local root = B.getRoot(character)
            local killers = B.getKillersFolder()
            if not root or not killers then continue end

            local nearestKiller, nearestDistance = nil, B.autoUseStabRange
            for _, killer in ipairs(killers:GetChildren()) do
                if B.isValidKiller(killer) and B.isPlayerCharacter(killer) then
                    local killerRoot = killer:FindFirstChild("HumanoidRootPart")
                    if killerRoot then
                        local distance = (killerRoot.Position - root.Position).Magnitude
                        if distance <= nearestDistance then
                            nearestKiller = killer
                            nearestDistance = distance
                        end
                    end
                end
            end

            local killerRoot = nearestKiller and nearestKiller:FindFirstChild("HumanoidRootPart")
            if nearestKiller and killerRoot
                and B.isFacingBackForAutoUseStab(root, killerRoot)
                and B.isDaggerReady() then
                B.autoUseStabLastTrigger = now
                if B.activateDaggerDirect() then
                    B.autoUseStabAssistToken += 1
                    local assistToken = B.autoUseStabAssistToken
                    local humanoid = character:FindFirstChildWhichIsA("Humanoid")
                    task.spawn(function()
                        local assistEndsAt = os.clock() + 2
                        local lastMoveAt = 0
                        while not B.stopped and B.autoUseStab
                            and assistToken == B.autoUseStabAssistToken
                            and B.isLocalTwoTimeSurvivor()
                            and os.clock() < assistEndsAt
                            and root.Parent and killerRoot.Parent
                            and humanoid and humanoid.Parent do
                            local lookPoint = Vector3.new(
                                killerRoot.Position.X,
                                root.Position.Y,
                                killerRoot.Position.Z
                            )
                            if (lookPoint - root.Position).Magnitude > 0.05 then
                                pcall(function()
                                    root.CFrame = CFrame.lookAt(root.Position, lookPoint)
                                end)
                            end
                            if os.clock() - lastMoveAt >= 0.3 then
                                lastMoveAt = os.clock()
                                pcall(function() humanoid:MoveTo(killerRoot.Position) end)
                            end
                            task.wait(0.05)
                        end
                    end)
                end
            end
        end
    end)

    -- GlideStab watcher: triggers during Two Time's crouch-stab animation.
    task.spawn(function()
        while not B.stopped do
            task.wait(B.glideCheckRate)
            if not B.glideEnabled or not B.isLocalTwoTimeSurvivor() then continue end
            if os.clock() - B.glideLastTime < B.glideCooldown then continue end
            local character = B.getCharacter()
            local root = B.getRoot(character)
            local humanoid = character and character:FindFirstChildWhichIsA("Humanoid")
            if not root or not humanoid or not B.isPlayingTargetAnim(character) then continue end
            local killers = B.getKillersFolder()
            if not killers then continue end
            local candidate = nil
            for _, killer in ipairs(killers:GetChildren()) do
                if B.isValidKiller(killer) then
                    local killerRoot = killer:FindFirstChild("HumanoidRootPart")
                    if killerRoot and (killerRoot.Position - root.Position).Magnitude <= B.glideRange then
                        local started = os.clock()
                        while not B.stopped and B.isLocalTwoTimeSurvivor()
                            and B.glideEnabled and os.clock() - started < B.glideBesideTimeout do
                            if B.isBesideKiller(root, killerRoot, B.glideRange) then break end
                            task.wait(0.05)
                        end
                        if B.isBesideKiller(root, killerRoot, B.glideRange) then candidate = killer; break end
                    end
                end
            end
            if not candidate then continue end
            local killerRoot = candidate:FindFirstChild("HumanoidRootPart")
            if not killerRoot then continue end
            B.glideLastTime = os.clock()
            -- A single GlideStab run may send at most one Dagger request.
            -- Keep checking readiness while moving, but never spam the ability remote.
            local glideDaggerAttempted = false
            local previousAutoRotate = humanoid.AutoRotate
            local camera = workspace.CurrentCamera
            local previousCamera = B.aimingMode == "Camera" and camera and camera.CFrame or nil
            if B.glideType == "Teleport" then
                local endTime = os.clock() + B.glideDuration
                while not B.stopped and B.isLocalTwoTimeSurvivor()
                    and B.glideEnabled and os.clock() < endTime and root.Parent and killerRoot.Parent do
                    local look = killerRoot.CFrame.LookVector
                    if look.Magnitude < 0.001 then look = Vector3.new(0, 0, -1) end
                    local behindPos = killerRoot.Position - look.Unit * B.behindDistance
                    local targetPos = Vector3.new(behindPos.X, root.Position.Y, behindPos.Z)
                    pcall(function() root.CFrame = CFrame.new(targetPos, targetPos + look.Unit) end)
                    if not glideDaggerAttempted and B.isDaggerReady() then
                        glideDaggerAttempted = true
                        B.activateDaggerDirect()
                    end
                    task.wait(0.03)
                end
            else
                if B.aimingMode == "Character" then pcall(function() humanoid.AutoRotate = false end) end
                local endTime = os.clock() + B.glideDuration
                while not B.stopped and B.isLocalTwoTimeSurvivor()
                    and B.glideEnabled and os.clock() < endTime and root.Parent and killerRoot.Parent do
                    if not B.isBesideKiller(root, killerRoot, B.glideRange) then break end
                    if B.aimingMode == "Character" then
                        pcall(function() root.CFrame = CFrame.new(root.Position, killerRoot.Position) end)
                    elseif camera then
                        pcall(function() camera.CFrame = CFrame.new(camera.CFrame.Position, killerRoot.Position) end)
                    end
                    if not glideDaggerAttempted and B.isDaggerReady() then
                        glideDaggerAttempted = true
                        B.activateDaggerDirect()
                    end
                    task.wait(0.06)
                end
            end
            if B.aimingMode == "Character" and humanoid.Parent then
                pcall(function() humanoid.AutoRotate = previousAutoRotate end)
            elseif B.aimingMode == "Camera" and previousCamera and workspace.CurrentCamera then
                pcall(function() workspace.CurrentCamera.CFrame = previousCamera end)
            end
            task.wait(0.03)
        end
    end)


    -- Two Time-only combat controls. Every switch starts OFF.
    S.__helpers.createSectionHeader("TWO TIME")
    S.__helpers.createCoolToggle("AUTO USE STAB", false, function(value)
        B.autoUseStab = value == true
