    S.__helpers.createNumericControl("AUTO BACKSTAB COOLDOWN", B.cooldown, 0.1, 30, 0.1, function(value)
        B.cooldown = math.clamp(tonumber(value) or 5, 0.1, 30)
    end)

    S.__helpers.createCoolToggle("GLIDE STAB", false, function(value)
