    end)
    S.__helpers.createNumericControl("GLIDE STAB RANGE", B.glideRange, 1, 30, 0.5, function(value)
        B.glideRange = math.clamp(tonumber(value) or 8, 1, 30)
    end)
    S.__helpers.createNumericControl("GLIDE STAB DURATION", B.glideDuration, 0.05, 2, 0.05, function(value)
        B.glideDuration = math.clamp(tonumber(value) or 0.4, 0.05, 2)
    end)
    S.__helpers.createNumericControl("GLIDE STAB COOLDOWN", B.glideCooldown, 0.1, 30, 0.1, function(value)
        B.glideCooldown = math.clamp(tonumber(value) or 3, 0.1, 30)
    end)

    S.__helpers.createNumericControl("LUNGE HITBOX DISTANCE MULTI", 1, 1, 4.5, 0.1, function(value)
        B.lungeHitboxMultiplier = math.clamp(tonumber(value) or 1, 1, 4.5)
    end)
    S.__helpers.createNumericControl("CROUCH HITBOX DISTANCE MULTI", 1, 1, 2, 0.1, function(value)
        B.crouchHitboxMultiplier = math.clamp(tonumber(value) or 1, 1, 2)
    end)
    -- Lunge/Crouch hitbox multipliers retain their original short-lived correction behavior.
    B.bindSourceTwoTimeCharacter = function(character)
        if B.sourceAnimationConnection then
            pcall(function() B.sourceAnimationConnection:Disconnect() end)
            B.sourceAnimationConnection = nil
        end
        if not character or character.Name ~= "TwoTime"
            or not S.__helpers.isCharacterInRoleFolder(character, "Survivors") then return end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not animator then return end
        local animationMap = {}
        pcall(function()
            local assets = S.ReplicatedStorage:FindFirstChild("Assets")
            local survivors = assets and assets:FindFirstChild("Survivors")
            local twoTime = survivors and survivors:FindFirstChild("TwoTime")
            local configModule = twoTime and twoTime:FindFirstChild("Config")
            local config = configModule and require(configModule)
            local animations = config and config.Animations or {}
            B.refreshTargetAnimationIds()
            for _, key in ipairs({"LungeStart", "Stab"}) do
                local id = animations[key]
                if id then
                    if type(id) == "table" then
                        for _, nestedId in pairs(id) do
                            local digits = tostring(nestedId):match("%d+")
                            if digits then animationMap[digits] = key end
                        end
                    else
                        local digits = tostring(id):match("%d+")
                        if digits then animationMap[digits] = key end
                    end
                end
            end
        end)
        B.sourceAnimationConnection = animator.AnimationPlayed:Connect(function(track)
            local animation = track and track.Animation
            local animationId = animation and tostring(animation.AnimationId or ""):gsub("%D", "")
            local animationKind = animationId and animationMap[animationId]
            if not animationKind then return end
            local root = character:FindFirstChild("HumanoidRootPart")
            if not root then return end
            local started = os.clock()
            local duration = tonumber(track.Length) or 0.7
            if duration <= 0 then duration = 0.7 end
            task.spawn(function()
                while character.Parent and root.Parent and track.IsPlaying
                    and os.clock() - started <= duration do
                    local elapsed = os.clock() - started
                    local multiplier = animationKind == "Stab"
                        and B.lungeHitboxMultiplier or B.crouchHitboxMultiplier
                    if multiplier and multiplier > 1 then
                        local window = animationKind == "Stab"
                            and math.max(0.05, duration - (0.25 + 0.36)) or 0.6
                        if elapsed >= 0.25 then
                            local progress = math.clamp((elapsed - 0.25) / window, 0, 1)
                            local distance = multiplier * progress * (animationKind == "Stab" and 10 or 30)
                            local oldCFrame = root.CFrame
                            pcall(function() root.CFrame = oldCFrame + oldCFrame.LookVector * distance end)
                            local restoreName = "E1TwoTimeLungeRestore"
                            pcall(function()
                                S.RunService:BindToRenderStep(restoreName, Enum.RenderPriority.First.Value, function()
                                    S.RunService:UnbindFromRenderStep(restoreName)
                                    if root.Parent then pcall(function() root.CFrame = oldCFrame end) end
                                end)
                            end)
                        end
                    end
                    S.RunService.Heartbeat:Wait()
                end
            end)
        end)
    end
    if S.lp then
        S.__helpers.connect(S.lp.CharacterAdded, function(character)
            task.wait(0.25)
            B.bindSourceTwoTimeCharacter(character)
        end)
        task.defer(B.bindSourceTwoTimeCharacter, S.lp.Character)
    end

end

