-- Killer Noclip (Cursedsaken-style part handling):
-- The supplied Cursedsaken deobfuscated source exposes the KillerNoclip state
-- and uses Torso, HumanoidRootPart, Head and CollisionHitbox for its noclip
-- collision handling. Keep those target parts, but only disable collision
-- while this Survivor is physically overlapping a Killer. Original collision
-- values are restored when contact ends, the toggle is disabled, or respawn occurs.
S.KillerOverlapNoclip = {
    enabled = false,
    originals = setmetatable({}, {__mode = "k"}),
    character = nil,
    nextCheck = 0,
}

S.__helpers.getKillerNoclipParts = function(character)
    local parts = {}
    if not character then return parts end
    for _, partName in ipairs({"Torso", "HumanoidRootPart", "Head", "CollisionHitbox"}) do
        local part = character:FindFirstChild(partName)
        if part and part:IsA("BasePart") then
            table.insert(parts, part)
        end
    end
    return parts
end

S.__helpers.restoreKillerOverlapNoclip = function(clearCharacter)
    local state = S.KillerOverlapNoclip
    if not state then return end
    for part, originalCanCollide in pairs(state.originals) do
        if part and part.Parent then
            pcall(function()
                part.CanCollide = originalCanCollide
            end)
        end
        state.originals[part] = nil
    end
    if clearCharacter then
        state.character = nil
    end
end

S.__helpers.setKillerOverlapNoclip = function(enabled)
    local state = S.KillerOverlapNoclip
    state.enabled = enabled == true
    if not state.enabled then
        S.__helpers.restoreKillerOverlapNoclip(true)
    end
end

S.__helpers.updateKillerOverlapNoclip = function()
    local state = S.KillerOverlapNoclip
    if not state then return end
    if not state.enabled then
        if next(state.originals) ~= nil then
            S.__helpers.restoreKillerOverlapNoclip(true)
        end
        return
    end

    local now = os.clock()
    if now < state.nextCheck then return end
    state.nextCheck = now + 0.05

    -- Killer Noclip is intended for Survivors, matching its placement in
    -- Cursedsaken's Survivor / Two Time controls.
    if not S.__helpers.isLocalRole("Survivor") then
        S.__helpers.restoreKillerOverlapNoclip(true)
        return
    end

    local character = S.lp and S.lp.Character
    if not character or not character.Parent then
        S.__helpers.restoreKillerOverlapNoclip(true)
        return
    end
    if state.character ~= character then
        S.__helpers.restoreKillerOverlapNoclip(true)
        state.character = character
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local killersFolder = playersFolder and playersFolder:FindFirstChild("Killers")
    if not killersFolder then
        S.__helpers.restoreKillerOverlapNoclip(false)
        return
    end

    local targetParts = S.__helpers.getKillerNoclipParts(character)
    if #targetParts == 0 then
        S.__helpers.restoreKillerOverlapNoclip(false)
        return
    end

    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = {killersFolder}
    params.MaxParts = 1

    local overlappingKiller = false
    for _, part in ipairs(targetParts) do
        local querySize = part.Size + Vector3.new(0.08, 0.08, 0.08)
        local ok, hits = pcall(function()
            return workspace:GetPartBoundsInBox(part.CFrame, querySize, params)
        end)
        if ok and hits and #hits > 0 then
            overlappingKiller = true
            break
        end
    end

    if overlappingKiller then
        -- Match the four-part collision handling used by Cursedsaken's noclip.
        for _, part in ipairs(targetParts) do
            if state.originals[part] == nil then
                state.originals[part] = part.CanCollide
            end
            if part.CanCollide then
                pcall(function() part.CanCollide = false end)
            end
        end
    else
        S.__helpers.restoreKillerOverlapNoclip(false)
    end
end

S.__helpers.connect(S.RunService.Heartbeat, S.__helpers.updateKillerOverlapNoclip)

-- Legacy Two Time controls are intentionally not recreated here. The Five
-- source controls above are the only visible entries on the Two Time page.

-- Stamina settings ported from the second supplied file, adapted to ELSEGUI's controls.
S.__helpers.isStaminaCharacterInactive = function()
    local character = S.lp and S.lp.Character
    if not character then return true end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then return true end
    return tostring(character.Parent) == "Spectating"
end

S.__helpers.applyStaminaSettings = function(module)
    module = module or S.SprintingModule
    if type(module) ~= "table" or not module.DefaultsSet then
        return false
    end

    -- Capture the game-provided baseline once per Sprinting module instance.
    -- Disabled settings are left alone unless this script previously applied them,
    -- in which case their original value is restored exactly once.
    local baseline = S.staminaOriginalSettings[module]
    if not baseline then
        baseline = {
            MaxStamina = module.MaxStamina,
            MinStamina = module.MinStamina,
            StaminaLoss = module.StaminaLoss,
            StaminaGain = module.StaminaGain,
            SprintSpeed = module.SprintSpeed,
            StaminaLossDisabled = module.StaminaLossDisabled,
            applied = {},
        }
        S.staminaOriginalSettings[module] = baseline
    end
    baseline.applied = baseline.applied or {}

    local function applyOrRestore(field, enabled, value)
        if enabled then
            module[field] = value
            baseline.applied[field] = true
        elseif baseline.applied[field] then
            module[field] = baseline[field]
            baseline.applied[field] = nil
        end
    end

    applyOrRestore("MaxStamina", S.isMaxStaminaEnabled == true, tonumber(S.currentMaxStamina) or 100)
    applyOrRestore("MinStamina", S.isMinStaminaEnabled == true, tonumber(S.currentMinStamina) or 0)
    applyOrRestore("StaminaLoss", S.isStaminaLossEnabled == true, tonumber(S.currentStaminaLoss) or 10)
    applyOrRestore("StaminaGain", S.isStaminaGainEnabled == true, tonumber(S.currentStaminaGain) or 20)
    -- Apply the configured Sprint Speed while ON, then restore the exact
    -- game-provided baseline once when toggled OFF. Never force a value while OFF.
    applyOrRestore("SprintSpeed", S.isSprintSpeedEnabled == true, tonumber(S.currentSprintSpeed) or 26)

    if S.isInfStaminaEnabled == true then
        module.StaminaLossDisabled = true
        baseline.applied.StaminaLossDisabled = true
        local maxStamina = tonumber(module.MaxStamina) or tonumber(baseline.MaxStamina) or 100
        module.Stamina = maxStamina
        if module.__staminaChangedEvent then
            pcall(function() module.__staminaChangedEvent:Fire(maxStamina) end)
        end
    elseif baseline.applied.StaminaLossDisabled then
        module.StaminaLossDisabled = baseline.StaminaLossDisabled
        baseline.applied.StaminaLossDisabled = nil
    end

    return true
end

S.__helpers.initializeStaminaSettings = function()
    if S.staminaInitBusy then return end
    S.staminaInitBusy = true
    task.spawn(function()
        for _ = 1, 10 do
            if not S.__helpers.isStaminaCharacterInactive() then
                local module = S.SprintingModule
                if module then
                    if not module.DefaultsSet then
                        pcall(function() module:Init() end)
                    end
                    if module.DefaultsSet then
                        pcall(function() S.__helpers.applyStaminaSettings(module) end)
                        S.staminaInitBusy = false
                        return
                    end
                end
            end
            task.wait(0.3)
        end
        S.staminaInitBusy = false
    end)
end

S.__helpers.getLegitInfStaminaNormalLoss = function(module)
    -- Respect the existing Stamina Loss control when enabled; otherwise restore
    -- the game's captured value instead of leaving the temporary zero in place.
    if S.isStaminaLossEnabled == true then
        return tonumber(S.currentStaminaLoss) or 10
    end
    local baseline = module and S.staminaOriginalSettings[module]
    local originalLoss = baseline and tonumber(baseline.StaminaLoss)
    if originalLoss ~= nil then
        return originalLoss
    end
    return tonumber(module and module.StaminaLoss) or tonumber(S.currentStaminaLoss) or 10
end

S.__helpers.restoreLegitInfStaminaLoss = function()
    local module = S.legitInfStaminaPausedModule
    if S.legitInfStaminaLossPaused and module and not S.isInfStaminaEnabled then
        local normalLoss = S.__helpers.getLegitInfStaminaNormalLoss(module)
        pcall(function() module.StaminaLoss = normalLoss end)
    end
    S.legitInfStaminaLossPaused = false
    S.legitInfStaminaPausedModule = nil
end

S.__helpers.updateLegitInfStamina = function()
    if not S.isLegitInfStaminaEnabled then
        if S.legitInfStaminaLossPaused then
            S.__helpers.restoreLegitInfStaminaLoss()
        end
        return
    end

    -- The regular Infinite Stamina mode takes precedence if both toggles are ON.
    if S.isInfStaminaEnabled then
        S.legitInfStaminaLossPaused = false
        S.legitInfStaminaPausedModule = nil
        return
    end

    local module = S.SprintingModule
    if S.__helpers.isStaminaCharacterInactive()
        or not module or not module.DefaultsSet then
        if S.legitInfStaminaLossPaused then
            S.__helpers.restoreLegitInfStaminaLoss()
        end
        return
    end

    if S.legitInfStaminaLossPaused and S.legitInfStaminaPausedModule ~= module then
        S.__helpers.restoreLegitInfStaminaLoss()
    end

    local stamina = tonumber(module.Stamina)
    if stamina == nil then return end

    if stamina <= 1 then
        if not S.legitInfStaminaLossPaused then
            S.legitInfStaminaLossPaused = true
            S.legitInfStaminaPausedModule = module
        end
        -- Stop only the loss amount. The game's normal stamina recovery remains
        -- available; once it rises above 1, the normal loss amount is restored.
        pcall(function() module.StaminaLoss = 0 end)
        if stamina < 1 then
            pcall(function()
                module.Stamina = 1
                if module.__staminaChangedEvent then
                    module.__staminaChangedEvent:Fire(1)
                end
            end)
        end
    elseif S.legitInfStaminaLossPaused then
        S.__helpers.restoreLegitInfStaminaLoss()
    end
end

