S.__helpers.createCoolToggle("AUTO CHANCE COINFLIP", false, function(value)
    S.autoChanceCoinflipEnabled = value == true
    S.autoChanceCoinflipToken += 1
    local token = S.autoChanceCoinflipToken
    if not S.autoChanceCoinflipEnabled then return end
    task.spawn(function()
        while S.autoChanceCoinflipEnabled and token == S.autoChanceCoinflipToken do
            local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
            local mainUI = playerGui and playerGui:FindFirstChild("MainUI")
            local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
            local shoot = abilityContainer and abilityContainer:FindFirstChild("Shoot")
            local charges = shoot and shoot:FindFirstChild("Charges")
            local chargeCount = charges and tonumber(charges.Text)
            if chargeCount and chargeCount >= 3 then
                S.autoChanceCoinflipEnabled = false
                break
            end
            -- Call the shared direct ability function; never activate the in-game button.
            if type(S.__helpers.fireAbilityDirect) == "function" then
                pcall(function() S.__helpers.fireAbilityDirect("CoinFlip") end)
            else
                -- The direct-call path is unavailable, so stop rather than fall back to UI clicks.
                S.autoChanceCoinflipEnabled = false
                break
            end
            task.wait(2)
        end
    end)
end)

