-- Guest1337 block animation changer. Uses the base Guest config plus installed
-- Guest1337 skin Config.Animations.Block IDs, as in E1LU4SAKEN's t63 map.
S.GuestBlockAnimation = {
    enabled = false, selected = "Normal", selectedId = nil,
    options = {"Normal"}, ids = {}, sourceIds = {}, connection = nil,
    replacementTracks = setmetatable({}, {__mode = "k"}),
}
S.__helpers.refreshGuestBlockAnimationChoices = function()
    local state = S.GuestBlockAnimation
    state.options, state.ids, state.sourceIds = {"Normal"}, {}, {}
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local baseSurvivors = assets and assets:FindFirstChild("Survivors")
    local baseGuest = baseSurvivors and baseSurvivors:FindFirstChild("Guest1337")
    local baseConfig = baseGuest and baseGuest:FindFirstChild("Config")
    if baseConfig and baseConfig:IsA("ModuleScript") then
        local ok, config = pcall(require, baseConfig)
        local blockId = ok and config and config.Animations and config.Animations.Block
        if blockId then
            state.ids.Normal = tostring(blockId)
            state.sourceIds[tostring(blockId)] = true
        end
    end
    local skins = assets and assets:FindFirstChild("Skins")
    local survivors = skins and skins:FindFirstChild("Survivors")
    local guestSkins = survivors and survivors:FindFirstChild("Guest1337")
    if guestSkins then
        for _, skin in ipairs(guestSkins:GetChildren()) do
            local configModule = skin:FindFirstChild("Config")
            if configModule and configModule:IsA("ModuleScript") then
                local ok, config = pcall(require, configModule)
                local blockId = ok and config and config.Animations and config.Animations.Block
                local displayName = ok and config and config.DisplayName
                if blockId and type(displayName) == "string" and displayName ~= "" then
                    state.ids[displayName] = tostring(blockId)
                    state.sourceIds[tostring(blockId)] = true
                    if not table.find(state.options, displayName) then table.insert(state.options, displayName) end
                end
            end
        end
    end
    if not state.ids.Normal then state.ids.Normal = "rbxassetid://72722244508749" end
    if not state.ids[state.selected] then state.selected = "Normal" end
    state.selectedId = state.ids[state.selected]
    table.sort(state.options, function(a, b)
        if a == "Normal" then return true end
        if b == "Normal" then return false end
        return a:lower() < b:lower()
    end)
    return state.options
end
S.__helpers.applyGuestBlockAnimation = function(character)
    local state = S.GuestBlockAnimation
    if state.connection then pcall(function() state.connection:Disconnect() end); state.connection = nil end
    if not state.enabled or not character or character.Name ~= "Guest1337" then return false end
    local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
    local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 5))
    if not animator then return false end
    state.connection = S.__helpers.connect(animator.AnimationPlayed, function(track)
        if not state.enabled or state.replacementTracks[track] then return end
        local animation = track and track.Animation
        local animationId = animation and tostring(animation.AnimationId or "")
        if not state.sourceIds[animationId] or animationId == state.selectedId then return end
        local replacement = Instance.new("Animation")
        replacement.AnimationId = state.selectedId or state.ids.Normal
        pcall(function() track:Stop(0) end)
        local ok, newTrack = pcall(function() return animator:LoadAnimation(replacement) end)
        if ok and newTrack then
            state.replacementTracks[newTrack] = true
            pcall(function() newTrack:Play(0.175) end)
            task.delay(3, function() pcall(function() replacement:Destroy() end) end)
        else
            replacement:Destroy()
        end
    end)
    return true
end
S.__helpers.setGuestBlockAnimation = function(enabled)
    local state = S.GuestBlockAnimation
    state.enabled = enabled == true
    if state.enabled then
        S.__helpers.refreshGuestBlockAnimationChoices()
        return S.__helpers.applyGuestBlockAnimation(S.lp and S.lp.Character)
    end
    if state.connection then pcall(function() state.connection:Disconnect() end); state.connection = nil end
    return true
end
S.__helpers.refreshGuestBlockAnimationChoices()
S.__helpers.connect(S.lp.CharacterAdded, function(character)
    task.wait(0.2)
    if S.GuestBlockAnimation.enabled then S.__helpers.applyGuestBlockAnimation(character) end
end)
S.__helpers.createSectionHeader("GUEST1337")
S.__helpers.createCoolToggle("GUEST1337 BLOCK ANIMATION", false, function(value)
    S.__helpers.setGuestBlockAnimation(value)
end)
S.PlopSpoofer.createDropdown("Guest1337 Block Animation", function()
    return S.__helpers.refreshGuestBlockAnimationChoices()
end, "Normal", function(value)
    S.GuestBlockAnimation.selected = value
    S.GuestBlockAnimation.selectedId = S.GuestBlockAnimation.ids[value] or S.GuestBlockAnimation.ids.Normal
end)

-- Guest1337 options ported from E1LU4SAKEN v4.1. Each option is independently
-- gated to the local Guest1337 survivor to avoid affecting other characters.
S.Guest1337Extras = {
    chargeAntiCrash = false, chargeControl = false, chargePilot = false,
    chargeNoclip = false, superPunch = false, superPunchPower = 20,
    originalChargeTurnSpeed = nil, gravityBeforePilot = nil,
    noclipOriginals = setmetatable({}, {__mode = "k"}),
    activeConnections = {},
}
S.__helpers.isGuestCharging = function(character)
    if not character or character.Name ~= "Guest1337" then return false end
    if character:GetAttribute("IsCharging") == true or character:GetAttribute("Charging") == true
        or character:GetAttribute("Guest1337Charging") == true then return true end
    local animations = S.__helpers.getLocalAnimationConfig and S.__helpers.getLocalAnimationConfig(character)
    local chargeId = animations and animations.Charge
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not chargeId or not humanoid then return false end
    for _, track in ipairs(humanoid:GetPlayingAnimationTracks()) do
        local animation = track.Animation
        if animation and tostring(animation.AnimationId) == tostring(chargeId) and track.IsPlaying then return true end
    end
    return false
end
S.__helpers.setGuestChargeControl = function(enabled)
    local state = S.Guest1337Extras
    state.chargeControl = enabled == true
    if type(getgc) == "function" then
        pcall(function()
            for _, object in ipairs(getgc(true)) do
                if type(object) == "table" and rawget(object, "ChargingTurnSpeed") ~= nil then
                    if state.originalChargeTurnSpeed == nil then
                        state.originalChargeTurnSpeed = rawget(object, "ChargingTurnSpeed")
                    end
                    rawset(object, "ChargingTurnSpeed", state.chargeControl and 9999 or state.originalChargeTurnSpeed)
                end
            end
        end)
    end
end
S.__helpers.setGuestChargePilot = function(enabled)
    local state = S.Guest1337Extras
    state.chargePilot = enabled == true
    if not state.chargePilot and state.gravityBeforePilot ~= nil then
        pcall(function() workspace.Gravity = state.gravityBeforePilot end)
        state.gravityBeforePilot = nil
    end
end
S.__helpers.setGuestChargeNoclip = function(enabled)
    local state = S.Guest1337Extras
    state.chargeNoclip = enabled == true
    if not state.chargeNoclip then
        for part, old in pairs(state.noclipOriginals) do
            if part and part.Parent then pcall(function() part.CanCollide = old end) end
        end
        table.clear(state.noclipOriginals)
    end
end
S.__helpers.setGuestSuperPunchPower = function(value)
    local number = tonumber(value)
    if not number then return false end
    S.Guest1337Extras.superPunchPower = math.clamp(number, 5, 40)
    return true
end
S.__helpers.createCoolToggle("GUEST1337 CHARGE ANTI-CRASH", false, function(value)
    S.Guest1337Extras.chargeAntiCrash = value == true
end)
S.__helpers.createCoolToggle("GUEST1337 CHARGE TURN CONTROL", false, function(value)
    S.__helpers.setGuestChargeControl(value)
end)
S.__helpers.createCoolToggle("GUEST1337 CHARGE PILOT", false, function(value)
    S.__helpers.setGuestChargePilot(value)
end)
S.__helpers.createCoolToggle("GUEST1337 CHARGE NOCLIP", false, function(value)
    S.__helpers.setGuestChargeNoclip(value)
end)
S.__helpers.createCoolToggle("GUEST1337 SUPER PUNCH", false, function(value)
