-- Guest charge movement and collision handling. The game uses a few different
-- attribute names between versions, so only the local Guest model is inspected.
S.__helpers.connect(S.RunService.Heartbeat, function()
    local state = S.Guest1337Extras
    local character = S.lp and S.lp.Character
    if not character or character.Name ~= "Guest1337" then
        if state.gravityBeforePilot ~= nil then S.__helpers.setGuestChargePilot(false) end
        if next(state.noclipOriginals) then S.__helpers.setGuestChargeNoclip(false) end
        return
    end
    local charging = S.__helpers.isGuestCharging(character)
    if state.chargeNoclip and charging then
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") and state.noclipOriginals[part] == nil then
                state.noclipOriginals[part] = part.CanCollide
                part.CanCollide = false
            end
        end
    elseif not charging and next(state.noclipOriginals) then
        for part, old in pairs(state.noclipOriginals) do
            if part and part.Parent then pcall(function() part.CanCollide = old end) end
        end
        table.clear(state.noclipOriginals)
    end
    if state.chargePilot and charging then
        if state.gravityBeforePilot == nil then state.gravityBeforePilot = workspace.Gravity end
        workspace.Gravity = 0
        local root = character:FindFirstChild("HumanoidRootPart")
        local velocity = root and root:FindFirstChildWhichIsA("LinearVelocity")
        if velocity then
            pcall(function()
                velocity.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
                velocity.VectorVelocity = workspace.CurrentCamera.CFrame.LookVector * 85
            end)
        elseif root then
            pcall(function() root.AssemblyLinearVelocity = workspace.CurrentCamera.CFrame.LookVector * 65 end)
        end
    elseif state.gravityBeforePilot ~= nil then
        pcall(function() workspace.Gravity = state.gravityBeforePilot end)
        state.gravityBeforePilot = nil
    end
end)

