S.__helpers.setSixerPursuitNoclip = function(enabled)
    S.SixerPursuit.noclip = enabled == true
    if not S.SixerPursuit.noclip then
        for part, old in pairs(S.SixerPursuit.originals) do
            if part and part.Parent then pcall(function() part.CanCollide = old end) end
        end
        table.clear(S.SixerPursuit.originals)
    end
end
S.__helpers.trackSixerPursuit = function(character)
    if not character then return end
    S.__helpers.connect(character:GetAttributeChangedSignal("PursuitState"), function()
        if character:GetAttribute("PursuitState") == "Dashing" then
            S.SixerPursuit.startedAt = tick()
            if S.SixerPursuit.noclip and character == (S.lp and S.lp.Character) then
                task.spawn(function()
                    while character.Parent and character:GetAttribute("PursuitState") == "Dashing" do
                        for _, part in ipairs(character:GetDescendants()) do
                            if part:IsA("BasePart") and S.SixerPursuit.originals[part] == nil then
                                S.SixerPursuit.originals[part] = part.CanCollide
                                part.CanCollide = false
                            end
                        end
                        task.wait()
                    end
                    for part, old in pairs(S.SixerPursuit.originals) do
                        if part and part.Parent then pcall(function() part.CanCollide = old end) end
                    end
                    table.clear(S.SixerPursuit.originals)
                end)
            end
        end
    end)
end
S.__helpers.trackSixerPursuit(S.lp and S.lp.Character)
