-- Dusekkar protection flags are backed by the same module hooks as E1LU4SAKEN.
S.__helpers.createSectionHeader("DUSEKKAR")
S.DusekkarProtection = {antiBreak = false, throughWalls = false}
S.__helpers.createCoolToggle("DUSEKKAR ANTI PROTECTION BREAK", false, function(value)
    S.DusekkarProtection.antiBreak = value == true
end)
S.__helpers.createCoolToggle("DUSEKKAR PROTECTION THROUGH WALLS", false, function(value)
    S.DusekkarProtection.throughWalls = value == true
end)
S.__helpers.installDusekkarProtectionHooks = function()
    if S.DusekkarProtection.hooksInstalled or type(hookfunction) ~= "function" then return S.DusekkarProtection.hooksInstalled == true end
    local installedAny = false
    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
    local survivors = assets and assets:FindFirstChild("Survivors")
    local dusekkar = survivors and survivors:FindFirstChild("Dusekkar")
    local behaviorModule = dusekkar and dusekkar:FindFirstChild("Behavior")
    if behaviorModule and behaviorModule:IsA("ModuleScript") then
        local ok, behavior = pcall(require, behaviorModule)
        local created = ok and behavior and behavior.Created
        if type(created) == "function" and type(debug) == "table" and type(debug.getupvalue) == "function" then
            local okUp, target = pcall(debug.getupvalue, created, 3)
            if okUp and type(target) == "function" then
                local old
                local replacement = function(...)
                    if S.DusekkarProtection.antiBreak then return true, 0 end
                    if old then return old(...) end
                end
                local okHook, original = pcall(hookfunction, target, replacement)
                if okHook then old = original; installedAny = true end
            end
        end
    end
    local modules = S.ReplicatedStorage:FindFirstChild("Modules")
    local utilities = modules and modules:FindFirstChild("Utilities")
    local utilModule = utilities and utilities:FindFirstChild("Util")
    if utilModule and utilModule:IsA("ModuleScript") then
        local ok, util = pcall(require, utilModule)
        if ok and type(util) == "table" and type(util.IsOnScreen) == "function" then
            local old
            local replacement = function(...)
                if S.DusekkarProtection.throughWalls then return true end
                if old then return old(...) end
                return false
            end
            local okHook, original = pcall(hookfunction, util.IsOnScreen, replacement)
            if okHook then old = original; installedAny = true end
        end
    end
    S.DusekkarProtection.hooksInstalled = installedAny
    return installedAny
end
task.spawn(function()
    for _ = 1, 20 do
        if S.__helpers.installDusekkarProtectionHooks() then break end
        task.wait(0.5)
    end
end)

-- Veeronica collision-damage control.
S.isVeeronicaCollisionDamageDisabled = false
S.VeeronicaCollisionDamageHook = {module = nil, original = nil, wrapper = nil, installed = false}
S.__helpers.installVeeronicaCollisionDamageFallback = function()
    if S.oldFireServerConnection then return true end
    local state = S.VeeronicaCollisionDamageHook
    if state.installed then return true end

    local module = S.NetworkModule
    if not module then
        pcall(function()
            module = require(S.ReplicatedStorage.Modules.Network.Network)
            S.NetworkModule = module
        end)
    end
    if not module or type(module.FireServerConnection) ~= "function" then
        return false
    end

    state.module = module
    state.original = module.FireServerConnection
    state.wrapper = function(self, connectionName, eventType, ...)
        local character = S.lp and S.lp.Character
        if S.isVeeronicaCollisionDamageDisabled
            and type(connectionName) == "string"
            and connectionName:find("StopSkate", 1, true)
            and character and character.Name == "Veeronica"
            and S.__helpers.isLocalRole("Survivor") then
            return state.original(self, connectionName, eventType, "Manual")
        end
        return state.original(self, connectionName, eventType, ...)
    end

    local ok = pcall(function() module.FireServerConnection = state.wrapper end)
    state.installed = ok and module.FireServerConnection == state.wrapper
    return state.installed
end
S.__helpers.setVeeronicaCollisionDamageDisabled = function(enabled)
    S.isVeeronicaCollisionDamageDisabled = enabled == true
    if S.isVeeronicaCollisionDamageDisabled and not S.oldFireServerConnection then
        S.__helpers.installVeeronicaCollisionDamageFallback()
    end
end

-- 007n7 Clone follow/bodyblock settings and mouse-position integration.
S.__helpers.createSectionHeader("007N7")
S.N7CloneFollow = {enabled = false, mode = "Front", target = "Killer", prediction = 15, distance = 6}
S.__helpers.createCoolToggle("007N7 CLONE FOLLOW / BODYBLOCK", false, function(value)
    S.N7CloneFollow.enabled = value == true
end)
S.PlopSpoofer.createDropdown("007n7 Clone Follow Mode", function()
    return {"Normal", "Orbit", "Front", "Back", "Run away", "Strafe"}
end, "Front", function(value) S.N7CloneFollow.mode = value end)
S.PlopSpoofer.createDropdown("007n7 Clone Follow Target", function()
    return {"Killer", "Nearest survivor", "Lowest health", "Yourself"}
end, "Killer", function(value) S.N7CloneFollow.target = value end)
S.PlopSpoofer.createInput("007n7 Clone Follow Prediction (0-30)", "15", function(value)
    S.N7CloneFollow.prediction = math.clamp(tonumber(value) or 15, 0, 30)
end, true)
S.PlopSpoofer.createInput("007n7 Clone Follow Distance (0-14)", "6", function(value)
    S.N7CloneFollow.distance = math.clamp(tonumber(value) or 6, 0, 14)
end, true)
S.__helpers.getN7CloneFollowPosition = function()
    local settings = S.N7CloneFollow
    local character = S.lp and S.lp.Character
    if not settings.enabled or not character or character.Name ~= "007n7" then return nil end
    local map = workspace:FindFirstChild("Map")
    local ingame = map and map:FindFirstChild("Ingame")
    local clone
    if ingame then
        for _, model in ipairs(ingame:GetChildren()) do
            if model.Name == "007n7" and model:GetAttribute("Username") == S.lp.Name then clone = model; break end
        end
    end
    if not clone then return nil end
    local target
    if settings.target == "Yourself" then
        target = character
    elseif settings.target == "Killer" then
        target = S.getFirstValidKillerModel and S.getFirstValidKillerModel()
    else
        local survivors = workspace:FindFirstChild("Players")
        survivors = survivors and survivors:FindFirstChild("Survivors")
        local root = character:FindFirstChild("HumanoidRootPart")
        local best = math.huge
        if survivors then
            for _, model in ipairs(survivors:GetChildren()) do
                if model ~= character then
                    local hrp = model:FindFirstChild("HumanoidRootPart")
                    local hum = model:FindFirstChildOfClass("Humanoid")
                    if hrp and hum and hum.Health > 0 then
                        local metric = settings.target == "Lowest health" and hum.Health
                            or (root and (hrp.Position - root.Position).Magnitude or math.huge)
                        if metric < best then best = metric; target = model end
                    end
                end
            end
        end
    end
    local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
    if not targetRoot then return nil end
    local velocity = targetRoot.AssemblyLinearVelocity
    local direction = velocity.Magnitude > 1 and velocity.Unit or targetRoot.CFrame.LookVector
    local position = targetRoot.Position + velocity * (settings.prediction / 100)
    local distance = settings.distance
    if settings.mode == "Front" then position += direction * distance
    elseif settings.mode == "Back" then position -= direction * distance
    elseif settings.mode == "Orbit" then position += Vector3.new(math.sin(tick() * 4) * distance, 0, math.cos(tick() * 4) * distance)
    elseif settings.mode == "Strafe" then position += direction * distance + targetRoot.CFrame.RightVector * math.sin(tick() * 6) * distance / 1.5
    elseif settings.mode == "Run away" then
        local ownRoot = character:FindFirstChild("HumanoidRootPart")
        if ownRoot then position = ownRoot.Position + ownRoot.CFrame.LookVector * distance * 1.5 end
    end
    return position
end



-- 007n7 c00lgui helper buttons. The controls are rebuilt after respawn and
-- only operate for the local 007n7 survivor.
do
    local state = {troll = false, cancellable = false, guiButton = nil,
        cancelButton = nil, connections = {}, respawn = nil, cancelling = false}
    S.N7C00lgui = state

    local function disconnectAll()
        for _, connection in ipairs(state.connections) do pcall(function() connection:Disconnect() end) end
        table.clear(state.connections)
    end
    local function removeButtons()
        if state.guiButton then pcall(function() state.guiButton:Destroy() end); state.guiButton = nil end
        if state.cancelButton then pcall(function() state.cancelButton:Destroy() end); state.cancelButton = nil end
    end
    local function getAbilityButton()
        local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
        local main = playerGui and playerGui:FindFirstChild("MainUI")
        local container = main and main:FindFirstChild("AbilityContainer")
        return container, container and container:FindFirstChild("c00lgui")
    end
    local function cancelC00lgui()
        if state.cancelling then return end
        state.cancelling = true
        local character = S.lp and S.lp.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not character or not root then state.cancelling = false; return end
        local startCFrame = root.CFrame
        local playerGui = S.lp:FindFirstChildOfClass("PlayerGui")
        local temporary = playerGui and playerGui:FindFirstChild("TemporaryUI")
        local progress = temporary and temporary:FindFirstChild("ProgressBar")
        if progress then pcall(function() progress:Destroy() end) end
        pcall(function()
            if S.c00lguiAnimationTrack then S.c00lguiAnimationTrack:Stop() end
        end)
        local speed = character:FindFirstChild("SpeedMultipliers")
        local slowdown = speed and speed:FindFirstChild("c00lgui")
        if slowdown then pcall(function() slowdown:Destroy() end) end
        pcall(function()
            if S.SprintingModule then S.SprintingModule.CanSprint = true end
        end)
        task.spawn(function()
            local started = os.clock()
            while state.cancelling and character.Parent and root.Parent and os.clock() - started < 6.5 do
                if (root.Position - startCFrame.Position).Magnitude >= 40 then
                    pcall(function() root.CFrame = startCFrame end)
                    break
                end
                S.RunService.RenderStepped:Wait()
            end
            state.cancelling = false
        end)
    end
    local function buildButtons()
        removeButtons()
        local character = S.lp and S.lp.Character
        if not character or character.Name ~= "007n7" or not S.__helpers.isCharacterInRoleFolder(character, "Survivors") then return end
        local container, ability = getAbilityButton()
        if not container or not ability then return end
        if state.troll then
            local clone = ability:Clone()
            clone.Name = "tr0llgui"
            pcall(function() clone.AbilityName.Text = "tr0llgui" end)
            pcall(function() local key = clone:FindFirstChild("KeybindName"); if key then key:Destroy() end end)
            clone.Parent = container
            state.guiButton = clone
            table.insert(state.connections, clone.Activated:Connect(function()
                if not S.__helpers.isV2AbilityReady or S.__helpers.isV2AbilityReady("c00lgui") then
                    if S.__helpers.fireAbilityDirect then
                        pcall(S.__helpers.fireAbilityDirect, "c00lgui")
                    elseif S.NetworkModule then
                        pcall(function() S.NetworkModule:FireServerConnection("UseActorAbility", "REMOTE_EVENT", "c00lgui") end)
                    end
                    if state.cancellable then task.delay(0.25, cancelC00lgui) end
                end
            end))
            task.spawn(function()
                while state.troll and clone.Parent and ability.Parent do
                    pcall(function()
                        clone.CooldownTime.Text = ability.CooldownTime.Text
                        clone.Clipping.Size = ability.Clipping.Size
                        clone.Clipping.Top.Size = ability.Clipping.Top.Size
                    end)
                    task.wait()
                end
                if state.guiButton == clone then removeButtons() end
            end)
        end
        if state.cancellable then
            local systems = S.ReplicatedStorage:FindFirstChild("Systems")
            local playerSystem = systems and systems:FindFirstChild("Player")
            local ui = playerSystem and playerSystem:FindFirstChild("UI")
            local backpack = ui and ui:FindFirstChild("CustomBackpack")
            local hotbar = backpack and backpack:FindFirstChild("HotbarItemContainer")
            local dropTemplate = hotbar and hotbar:FindFirstChild("DropButton")
            if dropTemplate then
                local cancel = dropTemplate:Clone()
                cancel.Parent = ability
                state.cancelButton = cancel
                table.insert(state.connections, cancel.Activated:Connect(function()
                    if character:FindFirstChild("c00lgui") then cancelC00lgui() end
                end))
            end
        end
    end
    local function refresh()
        disconnectAll()
        removeButtons()
        if state.respawn then pcall(function() state.respawn:Disconnect() end); state.respawn = nil end
        if state.troll or state.cancellable then
            buildButtons()
            state.respawn = S.lp.CharacterAdded:Connect(function(character)
                disconnectAll()
                task.wait(0.4)
                if character.Name == "007n7" then buildButtons() end
            end)
        else
            disconnectAll()
        end
    end
    S.__helpers.createCoolToggle("007N7 TROLL C00LGUI", false, function(value)
        state.troll = value == true
        refresh()
    end)
    S.__helpers.createCoolToggle("007N7 CANCELLABLE C00LGUI", false, function(value)
        state.cancellable = value == true
        refresh()
    end)
end

