-- Auto Stop Sprinting: stop the active sprint when stamina reaches 1, matching
-- File 2's StaminaChanged / DisableSprinting behavior.
S.__helpers.bindAutoStopSprinting = function(module)
    module = module or S.SprintingModule
    if not module then return false end
    if S.autoStopSprintBoundModule == module and S.autoStopSprintConnection then
        return true
    end

    if S.autoStopSprintConnection then
        pcall(function() S.autoStopSprintConnection:Disconnect() end)
        S.autoStopSprintConnection = nil
    end

    local signal
    pcall(function() signal = module.StaminaChanged end)
    if not signal then return false end

    local connection
    local ok = pcall(function()
        connection = signal:Connect(function()
            if not S.isAutoStopSprintingEnabled
                or S.isInfStaminaEnabled
                or (S.isStaminaPresetEnabled and S.staminaPreset == "Infinite")
                or S.autoStopSprintCooldown then
                return
            end

            local stamina
            local isSprinting
            pcall(function()
                stamina = tonumber(rawget(module, "Stamina") or module.Stamina)
                isSprinting = rawget(module, "IsSprinting")
            end)
            if stamina == nil or stamina > 1 or isSprinting ~= true then return end

            S.autoStopSprintCooldown = true
            local network = S.NetworkModule
            local disableSent = false
            if network and type(network.FireConnection) == "function" then
                disableSent = pcall(function()
                    network:FireConnection("DisableSprinting", "", true)
                end)
            end

            if not disableSent then
                local toggleFunction
                pcall(function() toggleFunction = rawget(module, "Toggle") or module.Toggle end)
                if type(toggleFunction) == "function" then
                    pcall(function() module:Toggle() end)
                end
            end

            pcall(function() module.CanSprint = false end)
            task.delay(0.65, function()
                local currentNetwork = S.NetworkModule
                local sprintReenabled = false
                if currentNetwork and type(currentNetwork.FireConnection) == "function" then
                    sprintReenabled = pcall(function()
                        currentNetwork:FireConnection("DisableSprinting", "", false)
                    end)
                end
                if not sprintReenabled then
                    pcall(function() module.CanSprint = true end)
                end
                S.autoStopSprintCooldown = false
            end)
        end)
    end)

    if not ok or not connection then return false end
    S.autoStopSprintBoundModule = module
    S.autoStopSprintConnection = connection
    table.insert(S.connections, connection)
    return true
end

-- Match the source script: re-apply the five module fields when the game resets them.
S.__helpers.connect(S.RunService.Stepped, function()
    if S.__helpers.isStaminaCharacterInactive() then
        S.staminaManualValue = nil
        return
    end
    if not S.__helpers.applyStaminaSettings() then
        S.__helpers.initializeStaminaSettings()
    end
end)
S.__helpers.connect(S.lp.CharacterAdded, function()
    S.staminaManualValue = nil
    task.delay(0.5, S.__helpers.initializeStaminaSettings)
    task.delay(0.6, function()
        if S.isAutoStopSprintingEnabled then
            S.__helpers.bindAutoStopSprinting()
        end
    end)
end)
S.__helpers.initializeStaminaSettings()
if S.isAutoStopSprintingEnabled then
    task.defer(S.__helpers.bindAutoStopSprinting)
end

-- ================================================================
-- STAMINA PRESET (restored without the removed external dropdown dependency)
-- ================================================================
S.StaminaPresetUI = S.StaminaPresetUI or {amount = nil, infinite = nil, center = nil, drain = nil}
S.__helpers.updateStaminaPresetUI = function()
    local state = S.StaminaPresetUI
    local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
    local tempUI = playerGui and playerGui:FindFirstChild("TemporaryUI")
    local bars = tempUI and tempUI:FindFirstChild("PlayerInfo")
        and tempUI.PlayerInfo:FindFirstChild("Bars")
    local staminaBar = bars and bars:FindFirstChild("Stamina")
    local amount = staminaBar and staminaBar:FindFirstChild("Amount")

    if state.amount and state.amount ~= amount then
        pcall(function()
            state.amount.Visible = state.amount:GetAttribute("E1LU4HUB_StaminaWasVisible") ~= false
        end)
        if state.infinite then pcall(function() state.infinite:Destroy() end) end
        state.amount, state.infinite = nil, nil
    end

    if amount then
        if amount:GetAttribute("E1LU4HUB_StaminaWasVisible") == nil then
            amount:SetAttribute("E1LU4HUB_StaminaWasVisible", amount.Visible)
        end
        state.amount = amount
        if not state.infinite or not state.infinite.Parent then
            local ok, clone = pcall(function() return amount:Clone() end)
            if ok and clone then
                clone.Name = "E1LU4HUB_InfiniteStaminaAmount"
                clone.Text = "∞"
                clone.Parent = amount.Parent
                clone.Size = UDim2.new(0.225, 0, 0.7, 14)
                state.infinite = clone
            end
        end
        local isInfinite = S.isStaminaPresetEnabled == true and S.staminaPreset == "Infinite"
        amount.Visible = not isInfinite and amount:GetAttribute("E1LU4HUB_StaminaWasVisible") ~= false
        if state.infinite then state.infinite.Visible = isInfinite end
    end

    local center = tempUI and tempUI:FindFirstChild("CenterStaminaCounter")
    local drain = tempUI and tempUI:FindFirstChild("Drain")
    for _, pair in ipairs({
        {object = center, key = "E1LU4HUB_StaminaWasVisible"},
        {object = drain, key = "E1LU4HUB_StaminaWasVisible"},
    }) do
        local object = pair.object
        if object then
            if object:GetAttribute(pair.key) == nil then
                object:SetAttribute(pair.key, object.Visible)
            end
            object.Visible = not (S.isStaminaPresetEnabled == true and S.staminaPreset == "Infinite")
                and object:GetAttribute(pair.key) ~= false
        end
    end
    state.center, state.drain = center, drain
end

