-- ================================================================
-- AUTO GENERATOR (FLOW / CONNECT / GEAR / LOCK)
-- Replaces the FlowGame-only implementation with four minigame hooks.
-- ================================================================
S.AutoGenerator = {
    enabled = false,
    startDelay = 0.3, -- Fixed: 0.3 seconds
    actionDelay = 0.05,
    connectDelay = 0.2, -- Fixed: 200 ms
    gearDelay = 0.03,
    token = 0,
    lockBoard = nil,
    modules = {},
    solverInstalled = false,
    solverWatcherStarted = false,
}

function S.AutoGenerator:requireModuleAtPath(path)
    local node = S.ReplicatedStorage
    for _, segment in ipairs(path) do
        node = node and node:FindFirstChild(segment)
        if not node then
            return nil
        end
    end

    if not node:IsA("ModuleScript") then
        return nil
    end

    local ok, result = pcall(require, node)
    if ok and type(result) == "table" then
        return result
    end

    if type(S.__helpers.__executorRequire) == "function" then
        local fallbackOK, fallbackResult = pcall(S.__helpers.__executorRequire, node)
        if fallbackOK and type(fallbackResult) == "table" then
            return fallbackResult
        end
    end

    return nil
end

function S.AutoGenerator:solverDelay()
    return math.max(0, tonumber(self.actionDelay) or 0.05)
end

function S.AutoGenerator:connectSolverDelay()
    -- Connect Pair Delay is configurable in milliseconds from the UI.
    return math.max(0, tonumber(self.connectDelay) or 0.2)
end

function S.AutoGenerator:solverIsEnabled()
    return self.enabled == true
end

function S.AutoGenerator:stillSolving(token, object)
    return self:solverIsEnabled()
        and token == self.token
        and object ~= nil
        and not object.Ended
end

function S.AutoGenerator:waitForSolver(object)
    while object and not object.Ended and not self:solverIsEnabled() do
        task.wait(0.05)
    end

    if not (object and not object.Ended and self:solverIsEnabled()) then
        return false
    end

    -- Snapshot the configurable start delay after the toggle becomes enabled.
    -- Puzzles opened while disabled can still start after enabling.
    local token = self.token
    local started = os.clock()
    local delay = math.max(0, tonumber(self.startDelay) or 0.3)

    while object
        and not object.Ended
        and self:solverIsEnabled()
        and token == self.token
        and os.clock() - started < delay do
        task.wait(0.05)
    end

    if object and not object.Ended and self:solverIsEnabled() and token == self.token then
        return true, token
    end

    return false
end

-- Flow solver based on the E1LU4HUB Auto Generator implementation.
-- It first searches with the original 300-path candidate cap, then retries with
-- a wider cap if the first constrained search cannot find a disjoint solution.
function S.AutoGenerator:solveFlowBoard(board)
    local flowBoardModule = self.modules.FlowBoard
    if not board or not flowBoardModule
        or type(board.Size) ~= "number"
        or type(board.Pairs) ~= "table"
        or type(flowBoardModule.ToRowCol) ~= "function"
        or type(flowBoardModule.ToIndex) ~= "function" then
        return nil
    end

    local size, pairMap = board.Size, board.Pairs
    local endpointOwner = {}
    local remaining = {}
    for color, pair in pairs(pairMap) do
        if type(pair) ~= "table" or pair[1] == nil or pair[2] == nil then
            return nil
        end
        endpointOwner[pair[1]], endpointOwner[pair[2]] = color, color
        table.insert(remaining, color)
    end

    -- Stable color order makes equivalent puzzle runs more predictable.
    table.sort(remaining, function(a, b)
        return tostring(a) < tostring(b)
    end)

    local directions = { {-1, 0}, {1, 0}, {0, -1}, {0, 1} }
    local candidateLimits = {300, 1000}
    local maxSearchNodes = 25000

    local function solveWithLimit(candidateLimit)
        local occupied, answer = {}, {}
        local searchNodes = 0
        local hitSearchLimit = false

        local function candidates(color, limit)
            local pair = pairMap[color]
            local from, target = pair[1], pair[2]
            local results, path, seen = {}, {from}, {[from] = true}
            local targetRow, targetCol = flowBoardModule.ToRowCol(size, target)
            local function distance(cell)
                local row, col = flowBoardModule.ToRowCol(size, cell)
                return math.abs(row - targetRow) + math.abs(col - targetCol)
            end

            local function walk(cell)
                if #results >= limit then return end
                if cell == target then
                    table.insert(results, table.clone(path))
                    return
                end

                local row, col = flowBoardModule.ToRowCol(size, cell)
                local nextCells = {}
                for _, direction in ipairs(directions) do
                    local nextRow = row + direction[1]
                    local nextCol = col + direction[2]
                    if nextRow >= 1 and nextRow <= size
                        and nextCol >= 1 and nextCol <= size then
                        local nextCell = flowBoardModule.ToIndex(size, nextRow, nextCol)
                        local owner = endpointOwner[nextCell]
                        if not seen[nextCell]
                            and not occupied[nextCell]
                            and (not owner or (owner == color and nextCell == target)) then
                            table.insert(nextCells, nextCell)
                        end
                    end
                end

                table.sort(nextCells, function(a, b)
                    return distance(a) < distance(b)
                end)

                for _, nextCell in ipairs(nextCells) do
                    seen[nextCell] = true
                    table.insert(path, nextCell)
                    walk(nextCell)
                    path[#path] = nil
                    seen[nextCell] = nil
                    if #results >= limit then break end
                end
            end

            walk(from)
            table.sort(results, function(a, b)
                return #a < #b
            end)
            return results
        end

        local function search(colors)
            searchNodes += 1
            if searchNodes > maxSearchNodes then
                hitSearchLimit = true
                return false
            end
            if #colors == 0 then return true end

            -- Choose the remaining pair with the fewest currently valid paths.
            local bestIndex, bestPaths
            for index, color in ipairs(colors) do
                local list = candidates(color, candidateLimit)
                if #list == 0 then return false end
                if not bestPaths or #list < #bestPaths then
                    bestIndex, bestPaths = index, list
                end
            end

            local color = colors[bestIndex]
            local nextColors = table.clone(colors)
            table.remove(nextColors, bestIndex)
            for _, path in ipairs(bestPaths) do
                for _, cell in ipairs(path) do
                    occupied[cell] = true
                end
                answer[color] = path
                if search(nextColors) then return true end
                answer[color] = nil
                for _, cell in ipairs(path) do
                    occupied[cell] = nil
                end
                if hitSearchLimit then return false end
            end
            return false
        end

        if search(remaining) then
            return answer
        end
        return nil
    end

    for _, limit in ipairs(candidateLimits) do
        local answer = solveWithLimit(limit)
        if answer then return answer end
    end
    return nil
end

-- Wrap a module's .new only once per loaded module table. Keeping the original
-- function on the module table allows a later copy of this script to replace
-- the wrapper instead of stacking wrappers indefinitely.
function S.AutoGenerator:wrapModuleNew(moduleTable, hookName, makeWrapper)
    if type(moduleTable) ~= "table" or type(moduleTable.new) ~= "function" then
        return false
    end

    local originalKey = "__ELSGUI_AutoGeneratorOriginal_" .. hookName
    local originalNew = moduleTable[originalKey]
    if type(originalNew) ~= "function" then
        originalNew = moduleTable.new
        local stored = pcall(function()
            moduleTable[originalKey] = originalNew
        end)
        if not stored then
            return false
        end
    end

    local replacement = makeWrapper(originalNew)
    local assigned = pcall(function()
        moduleTable.new = replacement
    end)
    return assigned and moduleTable.new == replacement
end

function S.AutoGenerator:installMinigameHooks()
    if self.solverInstalled then
        return true
    end

    local modules = {
        FlowBoard = self:requireModuleAtPath({"Modules", "Minigames", "FlowBoard"}),
        LockBoard = self:requireModuleAtPath({"Modules", "Minigames", "LockBoard"}),
        FlowInput = self:requireModuleAtPath({"Systems", "Player", "Game", "Minigames", "FlowClientMinigame", "FlowInput"}),
        GearInput = self:requireModuleAtPath({"Systems", "Player", "Game", "Minigames", "GearClientMinigame", "GearInput"}),
        LockInput = self:requireModuleAtPath({"Systems", "Player", "Game", "Minigames", "LockClientMinigame", "LockInput"}),
        ConnectInput = self:requireModuleAtPath({"Systems", "Player", "Game", "Minigames", "ConnectClientMinigame", "ConnectInput"}),
    }

    if type(modules.FlowBoard) ~= "table"
        or type(modules.FlowBoard.ToRowCol) ~= "function"
        or type(modules.FlowBoard.ToIndex) ~= "function"
        or type(modules.LockBoard) ~= "table"
        or type(modules.LockBoard.new) ~= "function"
        or type(modules.FlowInput) ~= "table"
        or type(modules.FlowInput.new) ~= "function"
        or type(modules.GearInput) ~= "table"
        or type(modules.GearInput.new) ~= "function"
        or type(modules.LockInput) ~= "table"
        or type(modules.LockInput.new) ~= "function"
        or type(modules.ConnectInput) ~= "table"
        or type(modules.ConnectInput.new) ~= "function" then
        return false
    end

    self.modules = modules
    local owner = self

    local boardHookOK = self:wrapModuleNew(modules.LockBoard, "LockBoard", function(originalNew)
        return function(...)
            local board = originalNew(...)
            owner.lockBoard = board
            return board
        end
    end)

    local flowHookOK = self:wrapModuleNew(modules.FlowInput, "FlowInput", function(originalNew)
        return function(board, renderer, callbacks)
            local object = originalNew(board, renderer, callbacks)
            task.spawn(function()
                local ready, token = owner:waitForSolver(object)
                if not ready then return end
                task.wait(owner:solverDelay())

                local solveOK, paths = pcall(owner.solveFlowBoard, owner, board)
                if not solveOK then
                    warn("[Auto Generator] Flow solver error: " .. tostring(paths))
                    return
                end
                if not paths then
                    warn("[Auto Generator] Flow solution was not found")
                    return
                end

                local colors = {}
                for color in pairs(paths) do
                    table.insert(colors, color)
                end
                table.sort(colors, function(a, b)
                    return tostring(a) < tostring(b)
                end)

                for _, color in ipairs(colors) do
                    local path = paths[color]
                    if not owner:stillSolving(token, object) then return end
                    local drawing = board:Begin(path[1])
                    renderer:Render()
                    task.wait(owner:solverDelay())

                    for index = 2, #path do
                        if not owner:stillSolving(token, object) then return end
                        board:Step(drawing, path[index], 0)
                        renderer:Render()
                        task.wait(owner:solverDelay())
                    end

                    board:Release(drawing, true)
                    renderer:Render()
                    task.wait(owner:solverDelay())
                end

                if owner:stillSolving(token, object) and board:IsSolved() then
                    object:__finish()
                    if callbacks and type(callbacks.OnSolved) == "function" then
                        callbacks.OnSolved()
                    end
                end
            end)
            return object
        end
    end)

    local connectHookOK = self:wrapModuleNew(modules.ConnectInput, "ConnectInput", function(originalNew)
        return function(board, renderer, callbacks)
            local object = originalNew(board, renderer, callbacks)
            task.spawn(function()
                local ready, token = owner:waitForSolver(object)
                if not ready then return end
                task.wait(owner:connectSolverDelay())

                for blob in pairs(board.Blobs) do
                    if not owner:stillSolving(token, object) then return end
                    if not board:GetLink(blob) then
                        local mate = board:GetMate(blob)
                        if mate then
                            board:Connect(blob, mate)
                            renderer:Render()
                            task.wait(owner:connectSolverDelay())
                        end
                    end
                end

                if owner:stillSolving(token, object) and board:IsSolved() then
                    object:__finish()
                    if callbacks and type(callbacks.OnSolved) == "function" then
                        callbacks.OnSolved()
                    end
                end
            end)
            return object
        end
    end)

    local gearHookOK = self:wrapModuleNew(modules.GearInput, "GearInput", function(originalNew)
        return function(getCenter, callbacks, enabled)
            local object = originalNew(getCenter, callbacks, enabled)
            task.spawn(function()
                local ready, token = owner:waitForSolver(object)
                if not ready then return end
                task.wait(math.max(0.55, owner:solverDelay()))

                for _ = 1, 100 do
                    if not owner:stillSolving(token, object) then return end
                    if callbacks and type(callbacks.OnTurn) == "function" then
                        callbacks.OnTurn(90)
                    else
                        return
                    end
                    task.wait(math.max(0, tonumber(owner.gearDelay) or 0.03))
                end
            end)
            return object
        end
    end)

    local lockHookOK = self:wrapModuleNew(modules.LockInput, "LockInput", function(originalNew)
        return function(ui, callbacks)
            local object = originalNew(ui, callbacks)
            task.spawn(function()
                local ready, token = owner:waitForSolver(object)
                if not ready then return end
                local board = owner.lockBoard

                while owner:stillSolving(token, object)
                    and board
                    and not board:IsBroken() do
                    local now = workspace:GetServerTimeNow()
                    if board:IsOnTarget(board:AngleAt(now)) then
                        if callbacks and type(callbacks.OnPress) == "function" then
                            callbacks.OnPress()
                        else
                            return
                        end
                        task.wait(math.max(0.08, owner:solverDelay()))
                    else
                        S.RunService.Heartbeat:Wait()
                    end
                end
            end)
            return object
        end
    end)

    self.solverInstalled = boardHookOK and flowHookOK and connectHookOK and gearHookOK and lockHookOK
    return self.solverInstalled
end

function S.AutoGenerator:startMinigameHookWatcher()
    if self.solverWatcherStarted then
        return
    end

    self.solverWatcherStarted = true
    task.spawn(function()
        while not self.solverInstalled do
            pcall(function()
                self:installMinigameHooks()
            end)
            if not self.solverInstalled then
                task.wait(0.25)
            end
        end
    end)
end

function S.AutoGenerator:setEnabled(value)
    self.enabled = value == true
    self.token += 1

    if self.enabled then
        self:installMinigameHooks()
        self:startMinigameHookWatcher()
    end
end

function S.AutoGenerator:setStartDelay(value)
    local number = tonumber(value) or 0.3
    self.startDelay = math.clamp(number, 0, 5)
    return self.startDelay
end

function S.AutoGenerator:setActionDelayMs(value)
    local number = tonumber(value) or 50
    self.actionDelay = math.clamp(number, 0, 250) / 1000
    return self.actionDelay * 1000
end

function S.AutoGenerator:setConnectDelayMs(value)
    local number = tonumber(value) or 200
    self.connectDelay = math.clamp(number, 0, 2000) / 1000
    return self.connectDelay * 1000
end

function S.AutoGenerator:setGearDelayMs(value)
    local number = tonumber(value) or 16
    self.gearDelay = math.clamp(number, 0, 150) / 1000
    return self.gearDelay * 1000
end

S.AutoGenerator:startMinigameHookWatcher()
S.AutoGenerator:installMinigameHooks()

