-- One-shot teleport tools. Each toggle automatically returns to OFF when its
-- run finishes, so the user can click it again to start a fresh pass.
S.__helpers.setRegisteredToggleState = function(labelText, value)
    for _, entry in ipairs(S.configToggleRegistry) do
        if entry.label == labelText and type(entry.callback) == "function" then
            entry.callback(value == true)
            return true
        end
    end
    return false
end

S.tpAllItemEnabled = false
S.tpAllItemToken = 0
S.__helpers.createSectionHeader("TP")
S.tpAllItemButton = S.__helpers.createCoolActionButton("TP ALL ITEM", function()
    S.tpAllItemToken += 1
    local token = S.tpAllItemToken
    S.tpAllItemEnabled = true
    S.__helpers.notify("TP ALL ITEM", "Looking for loose items to visit.", 3.2)

    task.spawn(function()
        local character = S.lp and S.lp.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local ingame, gameMap = S.getIngameFolders()
        if not root or not ingame then
            if token == S.tpAllItemToken then
                S.tpAllItemEnabled = false
                S.__helpers.notify("TP ALL ITEM", "Character or item folder is unavailable.", 3.5)
            end
            return
        end

        -- Use the existing Item ESP candidate rules so this visits loose item
        -- Tools and Gear, without targeting flags or items held by characters.
        local targets = {}
        local seen = {}
        for _, object in ipairs(ingame:GetDescendants()) do
            if object:IsA("Tool") and S.__helpers.isItemToolCandidate(object) and not seen[object] then
                local part = S.__helpers.getItemESPPart(object)
                if part then
                    seen[object] = true
                    table.insert(targets, {object = object, part = part, position = part.Position})
                end
            end
        end
        if gameMap then
            for _, object in ipairs(gameMap:GetDescendants()) do
                if object:IsA("Model") and object.Name == "Gear"
                    and S.__helpers.isItemToolCandidate(object) and not seen[object] then
                    local part = S.__helpers.getItemESPPart(object)
                    if part then
                        seen[object] = true
                        table.insert(targets, {object = object, part = part, position = part.Position})
                    end
                end
            end
        end

        -- Start with the closest item and then visit each target once. A new
        -- button press rebuilds this list from scratch and supersedes any old run.
        table.sort(targets, function(a, b)
            return (a.position - root.Position).Magnitude < (b.position - root.Position).Magnitude
        end)

        for _, target in ipairs(targets) do
            if token ~= S.tpAllItemToken then return end
            if target.object and target.object.Parent and target.part and target.part.Parent then
                character = S.lp and S.lp.Character
                root = character and character:FindFirstChild("HumanoidRootPart")
                if not root then break end
                local destination = target.part.Position + Vector3.new(0, 3, 0)
                pcall(function() root.CFrame = CFrame.new(destination) end)
                task.wait(0.3)
            end
        end

        if token == S.tpAllItemToken then
            S.tpAllItemEnabled = false
            S.__helpers.notify("TP ALL ITEM", "Finished visiting loose items.", 3.5)
        end
    end)
end)

S.tpGeneratorEnabled = false
S.tpGeneratorToken = 0
S.__helpers.runTPGenerator = function()
    S.tpGeneratorToken += 1
    local token = S.tpGeneratorToken
    S.tpGeneratorEnabled = true
    S.__helpers.notify("TP GENERATOR", "Searching for the nearest unfinished generator.", 3.2)

    task.spawn(function()
        local character = S.lp and S.lp.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local _, gameMap = S.getIngameFolders()
        local teleported = false
        if root and gameMap then
            local closestPart = nil
            local closestDistance = math.huge
            for _, generator in ipairs(gameMap:GetDescendants()) do
                if generator:IsA("Model") and generator.Name == "Generator" then
                    local main = generator:FindFirstChild("Main")
                    -- Skip generators that have already reached completion.
                    -- Use the same progress/completion detection as Generator ESP.
                    local progress, completed = S.__helpers.getGeneratorProgress(generator)
                    local isFinished = completed == true
                        or (progress ~= nil and progress >= 99.95)
                    if main and main:IsA("BasePart") and not isFinished then
                        local distance = (main.Position - root.Position).Magnitude
                        if distance < closestDistance then
                            closestDistance = distance
                            closestPart = main
                        end
                    end
                end
            end
            if closestPart and closestPart.Parent and token == S.tpGeneratorToken then
                local destination = closestPart.Position + Vector3.new(0, 3, 0)
                teleported = pcall(function() root.CFrame = CFrame.new(destination) end)
            end
        end
        if token == S.tpGeneratorToken then
            S.tpGeneratorEnabled = false
            if teleported then
                S.__helpers.notify("TP GENERATOR", "Teleported to the nearest unfinished generator.", 3.5)
            elseif not root or not gameMap then
                S.__helpers.notify("TP GENERATOR", "Character or game map is unavailable.", 3.5)
            else
                S.__helpers.notify("TP GENERATOR", "No unfinished generator was found.", 3.5)
            end
        end
    end)
end

S.tpGeneratorButton = S.__helpers.createCoolActionButton("TP GENERATOR", function()
    S.__helpers.runTPGenerator()
end)

S.deleteItemsBusy = false
S.deleteItemsButton = S.__helpers.createCoolActionButton("DELETE ITEMS", function()
    if S.deleteItemsBusy then return end
    S.deleteItemsBusy = true
    task.spawn(function()
        local ok, err = pcall(function()
            local character = S.lp and S.lp.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local ingame, gameMap = S.getIngameFolders()
            if not root or not ingame or not gameMap then
                S.__helpers.notify("DELETE ITEMS", "Character or item folder is unavailable.", 3.5)
                return
            end
            local returnCFrame = root.CFrame
            local targets, seen = {}, {}
            for _, object in ipairs(gameMap:GetDescendants()) do
                if (object:IsA("Tool") or (object:IsA("Model") and object.Name == "Gear"))
                    and S.__helpers.isItemToolCandidate(object) and not seen[object] then
                    local part = S.__helpers.getItemESPPart(object)
                    if part and not part.Anchored then
                        seen[object] = true
                        table.insert(targets, {object = object, part = part})
                    end
                end
            end
            if #targets == 0 then
                S.__helpers.notify("DELETE ITEMS", "There are no loose items to delete.", 3.5)
                return
            end
            for _, entry in ipairs(targets) do
                if entry.object.Parent and entry.part.Parent then
                    root = S.lp.Character and S.lp.Character:FindFirstChild("HumanoidRootPart")
                    if not root then break end
                    pcall(function() root.CFrame = entry.part.CFrame + Vector3.new(0, 1.5, 0) end)
                    task.wait(0.1)
                    pcall(function()
                        entry.part.CFrame = CFrame.new(0, -1000, 0)
                        entry.part.AssemblyLinearVelocity = Vector3.zero
                        entry.part.Velocity = Vector3.zero
                    end)
                    task.wait(0.2)
                end
            end
            root = S.lp.Character and S.lp.Character:FindFirstChild("HumanoidRootPart")
            if root then pcall(function() root.CFrame = returnCFrame end) end
            S.__helpers.notify("DELETE ITEMS", "Finished processing loose items.", 3.5)
        end)
        if not ok then
            warn("[E1LU4HUB Delete Items] " .. tostring(err))
            pcall(function() S.__helpers.notify("DELETE ITEMS", "Action failed.", 3.5) end)
        end
        S.deleteItemsBusy = false
    end)
end)

