-- PRIVACY BYPASS: locally reveal the three profile-stat flags and restore their
-- exact original values when the toggle is turned OFF or the script is unloaded.
S.PrivacyBypass = {
    enabled = false,
    keys = {"HideKillerWins", "HidePlaytime", "HideSurvivorWins"},
}
S.__helpers.applyPrivacyBypassToPlayer = function(player)
    local state = S.PrivacyBypass
    if not state.enabled or not player or not player.Parent then return false end

    local playerData = player:FindFirstChild("PlayerData")
    local settings = playerData and playerData:FindFirstChild("Settings")
    local privacy = settings and settings:FindFirstChild("Privacy")
    if not privacy then return false end

    local saved = S.privacyBypassOriginals[player]
    if not saved then
        saved = {}
        S.privacyBypassOriginals[player] = saved
    end

    local foundCount = 0
    for _, key in ipairs(state.keys) do
        local valueObject = privacy:FindFirstChild(key)
        if valueObject and valueObject:IsA("BoolValue") then
            foundCount = foundCount + 1
            local entry = saved[key]
            if not entry or entry.object ~= valueObject then
                entry = {object = valueObject, value = valueObject.Value}
                saved[key] = entry
            end
            pcall(function() valueObject.Value = false end)
        end
    end
    return foundCount == #state.keys
end

S.__helpers.restorePrivacyBypass = function()
    for player, saved in pairs(S.privacyBypassOriginals or {}) do
        for _, entry in pairs(saved or {}) do
            local object = entry and entry.object
            if object and object.Parent then
                pcall(function() object.Value = entry.value end)
            end
        end
        S.privacyBypassOriginals[player] = nil
    end
end

S.__helpers.setPrivacyBypass = function(enabled)
    S.PrivacyBypass.enabled = enabled == true
    S.isPrivacyBypassEnabled = S.PrivacyBypass.enabled
    if not S.PrivacyBypass.enabled then
        S.__helpers.restorePrivacyBypass()
        return
    end

    local function applyWhenReady(player)
        task.spawn(function()
            for _ = 1, 24 do
                if not S.PrivacyBypass.enabled or not player or not player.Parent then return end
                if S.__helpers.applyPrivacyBypassToPlayer(player) then return end
                task.wait(0.25)
            end
        end)
    end

    for _, player in ipairs(S.Players:GetPlayers()) do
        applyWhenReady(player)
    end
end

S.__helpers.connect(S.Players.PlayerAdded, function(player)
    if S.PrivacyBypass and S.PrivacyBypass.enabled then
        task.spawn(function()
            for _ = 1, 24 do
                if not S.PrivacyBypass.enabled or not player.Parent then return end
                if S.__helpers.applyPrivacyBypassToPlayer(player) then return end
                task.wait(0.25)
            end
        end)
    end
end)
S.__helpers.connect(S.Players.PlayerRemoving, function(player)
    S.privacyBypassOriginals[player] = nil
end)

S.__helpers.createSectionHeader("PRIVACY BYPASS")
S.__helpers.createCoolToggle("PRIVACY BYPASS", S.isPrivacyBypassEnabled, function(value)
    S.__helpers.setPrivacyBypass(value)
end)

-- Gameplay utilities ported from the companion script.
S.__helpers.getLocalPlayerGui = function()
    local player = S.lp
    return player and (player:FindFirstChildOfClass("PlayerGui") or player:FindFirstChild("PlayerGui"))
end

S.__helpers.tryCloseEndGameScreen = function(screen, token)
    if not screen or screen.Name ~= "EndScreen" then return end
    task.delay(0.1, function()
        if not S.isAutoCloseEndGameScreenEnabled
            or token ~= S.autoCloseEndGameScreenToken
            or not screen.Parent then
            return
        end

        local returnButton = screen:FindFirstChild("Return", true)
        if not returnButton or not returnButton:IsA("GuiButton") then return end

        local fireSignal = firesignal
        if type(fireSignal) ~= "function" then
            pcall(function() fireSignal = fire_signal end)
        end
        if type(fireSignal) ~= "function" then
            pcall(function() fireSignal = getgenv().firesignal end)
        end
        if type(fireSignal) ~= "function" then
            pcall(function() fireSignal = getgenv().fire_signal end)
        end

        if type(fireSignal) == "function" then
            local ok = pcall(fireSignal, returnButton.MouseButton1Click)
            if not ok then pcall(fireSignal, returnButton.Activated) end
        else
            pcall(function() returnButton:Activate() end)
        end
    end)
end

S.__helpers.setAutoCloseEndGameScreen = function(enabled)
    S.isAutoCloseEndGameScreenEnabled = enabled == true
    S.autoCloseEndGameScreenToken += 1
    local token = S.autoCloseEndGameScreenToken

    if S.autoCloseEndGameScreenConnection then
        S.autoCloseEndGameScreenConnection:Disconnect()
        S.autoCloseEndGameScreenConnection = nil
    end
    if not S.isAutoCloseEndGameScreenEnabled then return end

    local playerGui = S.__helpers.getLocalPlayerGui()
    if not playerGui then return end

    for _, child in ipairs(playerGui:GetChildren()) do
        if child.Name == "EndScreen" then
            S.__helpers.tryCloseEndGameScreen(child, token)
        end
    end

    S.autoCloseEndGameScreenConnection = S.__helpers.connect(playerGui.ChildAdded, function(child)
        if child.Name == "EndScreen" then
            task.delay(0.2, function()
                S.__helpers.tryCloseEndGameScreen(child, token)
            end)
        end
    end)
end

S.__helpers.setSidebarVisibility = function(enabled)
    S.isSidebarVisibilityEnabled = enabled == true
    S.sidebarVisibilityToken += 1
    local token = S.sidebarVisibilityToken

    local systems = S.ReplicatedStorage:FindFirstChild("Systems")
    local playerSystem = systems and systems:FindFirstChild("Player")
    local uiFolder = playerSystem and playerSystem:FindFirstChild("UI")
    local sidebarHandlerModule = uiFolder and uiFolder:FindFirstChild("SidebarHandler")
    local sidebarHandler = nil
    if sidebarHandlerModule and sidebarHandlerModule:IsA("ModuleScript") then
        local ok, result = pcall(require, sidebarHandlerModule)
        if ok and type(result) == "table" then
            sidebarHandler = result
        end
    end

    local function toggleSidebarButtons(value)
        if sidebarHandler then
            pcall(function() sidebarHandler:ToggleSidebarButtons(value) end)
        end
    end

    local function getSidebar()
        local playerGui = S.__helpers.getLocalPlayerGui()
        local mainUI = playerGui and playerGui:FindFirstChild("MainUI")
        return mainUI and mainUI:FindFirstChild("Sidebar")
    end

    if not S.isSidebarVisibilityEnabled then
        toggleSidebarButtons(false)
        local sidebar = getSidebar()
        if sidebar then sidebar.Visible = false end
        return
    end

    task.spawn(function()
        while S.isSidebarVisibilityEnabled and token == S.sidebarVisibilityToken do
            toggleSidebarButtons(true)
            local sidebar = getSidebar()
            if sidebar and sidebar.Visible ~= true then
                sidebar.Visible = true
            end
            task.wait(0.2)
        end
    end)
end

