-- Mouse Cursor Changer: apply the supplied cursor only outside Shift Lock.
-- Keep it inside the existing MISCELLANEOUS section so it remains grouped
-- with the other Misc controls after the sidebar page migration.
S.MouseCursorChanger = {
    enabled = false,
    token = 0,
    originalIcon = nil,
    appliedIcon = nil,
    mouse = nil,
    cursorAssetId = "417446600",
    cursorIcon = "rbxassetid://417446600",
}
S.__helpers.isMouseCursorShiftLocked = function()
    local ok, behavior = pcall(function()
        return S.UserInputService.MouseBehavior
    end)
    return ok and behavior == Enum.MouseBehavior.LockCenter
end
S.__helpers.setMouseCursorAssetId = function(value)
    local state = S.MouseCursorChanger
    local assetId = tostring(value or ""):match("(%d+)")
    if not assetId then return false end

    state.cursorAssetId = assetId
    state.cursorIcon = "rbxassetid://" .. assetId
    if state.enabled and state.mouse and not S.__helpers.isMouseCursorShiftLocked() then
        local ok = pcall(function() state.mouse.Icon = state.cursorIcon end)
        if ok then state.appliedIcon = state.cursorIcon end
    end
    return true
end
S.__helpers.setMouseCursorChanger = function(enabled)
    local state = S.MouseCursorChanger
    enabled = enabled == true
    if state.enabled == enabled then return end

    state.enabled = enabled
    state.token = (tonumber(state.token) or 0) + 1
    local token = state.token

    if not enabled then
        local mouse = state.mouse
        if not mouse and S.lp then
            pcall(function() mouse = S.lp:GetMouse() end)
        end
        if mouse and state.originalIcon ~= nil then
            pcall(function()
                if state.appliedIcon ~= nil and mouse.Icon == state.appliedIcon then
                    mouse.Icon = state.originalIcon
                end
            end)
        end
        state.originalIcon = nil
        state.appliedIcon = nil
        state.mouse = nil
        return
    end

    task.spawn(function()
        while state.enabled and state.token == token do
            if game:IsLoaded() and S.lp then
                local mouse
                pcall(function() mouse = S.lp:GetMouse() end)
                if mouse then
                    state.mouse = mouse
                    if state.originalIcon == nil then
                        local ok, originalIcon = pcall(function()
                            return mouse.Icon
                        end)
                        if ok then state.originalIcon = originalIcon end
                    end

                    if S.__helpers.isMouseCursorShiftLocked() then
                        -- Do not leave our cursor active after Shift Lock is entered.
                        if state.originalIcon ~= nil then
                            pcall(function()
                                if state.appliedIcon ~= nil and mouse.Icon == state.appliedIcon then
                                    mouse.Icon = state.originalIcon
                                end
                            end)
                        end
                        state.appliedIcon = nil
                    else
                        if mouse.Icon ~= state.cursorIcon then
                            local ok = pcall(function() mouse.Icon = state.cursorIcon end)
                            if ok then state.appliedIcon = state.cursorIcon end
                        elseif state.appliedIcon == nil then
                            state.appliedIcon = state.cursorIcon
                        end
                    end
                end
            end
            task.wait(0.2)
        end
    end)
end
S.mouseCursorChangerToggleButton = S.__helpers.createCoolToggle(
    "MOUSE CURSOR CHANGER",
    false,
    function(value)
        S.__helpers.setMouseCursorChanger(value)
    end
)
S.mouseCursorChangerAssetInput = S.PlopSpoofer.createInput(
    "MOUSE CURSOR IMAGE ID",
