        if not S.__helpers.setMouseCursorAssetId(value) then
            if S.mouseCursorChangerAssetInput then
                S.mouseCursorChangerAssetInput.Text = S.MouseCursorChanger.cursorAssetId
            end
            if S.__helpers.notify then
                S.__helpers.notify("Mouse Cursor Changer", "Enter a numeric image asset ID.", 3.2)
            end
        end
    end,
    true
)

S.ScriptUpdateRate = 0.3
S.__helpers.getScriptUpdateInterval = function()
    -- Keep zero/near-zero values from creating a tight, runaway polling loop.
    return math.max(0.02, math.clamp(tonumber(S.ScriptUpdateRate) or 0.3, 0, 2))
end
S.PlopSpoofer.createInput("SCRIPT UPDATE RATE (0-2s)", "0.3", function(value)
    local number = tonumber(value)
    if number then S.ScriptUpdateRate = math.clamp(number, 0, 2) end
end, true)
-- Consolidate the old executor-side E1LU4SAKEN directory into E1LU4HUB.
-- This is a filesystem migration only; S.ROOT_FOLDER_NAME is a separate
-- Workspace visual folder and is intentionally not changed here.
do
    local legacyRoot = "E1LU4SAKEN"
    local hubRoot = "E1LU4HUB"
    local managedRoot = hubRoot .. "/E1LU4SAKEN"

    local function normalizePath(path)
        return tostring(path or ""):gsub("\\", "/"):gsub("/+$", "")
    end

    local function folderExists(path)
        if type(isfolder) == "function" then
            local ok, exists = pcall(isfolder, path)
            if ok and exists == true then return true end
        end
        if type(listfiles) == "function" then
            local ok, entries = pcall(listfiles, path)
            return ok and type(entries) == "table"
        end
        return false
    end

    local function ensureFolderTree(path)
        if type(makefolder) ~= "function" then return false end
        local current = ""
        for segment in normalizePath(path):gmatch("[^/]+") do
            current = current == "" and segment or (current .. "/" .. segment)
            if not folderExists(current) then
                local ok = pcall(makefolder, current)
                if not ok then return false end
            end
        end
        return folderExists(path)
    end

    local function listFolder(path)
        if type(listfiles) ~= "function" then return nil end
        local ok, entries = pcall(listfiles, path)
        if ok and type(entries) == "table" then return entries end
        return nil
    end

    local function migrateTree(sourcePath, targetPath)
        sourcePath = normalizePath(sourcePath)
        targetPath = normalizePath(targetPath)
        if not folderExists(sourcePath) then return true end
        if not ensureFolderTree(targetPath) then return false end
        local entries = listFolder(sourcePath)
        if not entries then return false end

        local allMoved = true
        for _, rawEntry in ipairs(entries) do
            local entry = normalizePath(rawEntry)
            local prefix = sourcePath .. "/"
            local relative = entry:sub(1, #prefix) == prefix
                and entry:sub(#prefix + 1)
                or (entry:match("([^/]+)$") or entry)
            if relative ~= "" then
                local destination = targetPath .. "/" .. relative
                if folderExists(entry) then
                    if not migrateTree(entry, destination) then allMoved = false end
                elseif type(isfile) == "function" then
                    local fileOK, sourceExists = pcall(isfile, entry)
                    if fileOK and sourceExists == true then
                        if type(readfile) ~= "function" or type(writefile) ~= "function" then
                            allMoved = false
                        else
                            local destinationExists = false
                            local destOK, destExists = pcall(isfile, destination)
                            destinationExists = destOK and destExists == true
                            local copied = destinationExists
                            if not destinationExists then
                                local readOK, content = pcall(readfile, entry)
                                if readOK and type(content) == "string" then
                                    ensureFolderTree(targetPath .. "/" .. (relative:match("^(.*)/") or ""))
                                    local writeOK = pcall(writefile, destination, content)
                                    if writeOK then
                                        local verifyOK, verified = pcall(isfile, destination)
                                        copied = verifyOK and verified == true
                                    end
                                end
                            end
                            if copied and type(delfile) == "function" then
                                local deleteOK = pcall(delfile, entry)
                                if not deleteOK then allMoved = false end
                            elseif not copied then
                                allMoved = false
                            end
                        end
                    end
                end
            end
        end

        local remaining = listFolder(sourcePath)
        if remaining and #remaining == 0 then
            local removeFolder = type(delfolder) == "function" and delfolder
                or (type(deletefolder) == "function" and deletefolder or nil)
            if removeFolder then pcall(removeFolder, sourcePath) end
        elseif remaining then
            allMoved = false
        end
        return allMoved
    end

    local function migrateSingleFile(sourcePath, destinationPath)
        if type(isfile) ~= "function" then return false end
        local sourceOK, sourceExists = pcall(isfile, sourcePath)
        if not sourceOK or sourceExists ~= true then return true end
        if type(delfile) ~= "function" then return false end

        local destinationExists = false
        local destOK, destExists = pcall(isfile, destinationPath)
        destinationExists = destOK and destExists == true
        local copied = destinationExists
        if not destinationExists then
            if type(readfile) ~= "function" or type(writefile) ~= "function" then return false end
            local readOK, content = pcall(readfile, sourcePath)
            if not readOK or type(content) ~= "string" then return false end
            local parent = destinationPath:match("^(.*)/[^/]+$")
            if parent and parent ~= "" and not ensureFolderTree(parent) then return false end
            local writeOK = pcall(writefile, destinationPath, content)
            if not writeOK then return false end
            local verifyOK, verified = pcall(isfile, destinationPath)
            copied = verifyOK and verified == true
        end
        if not copied then return false end
        local deleteOK = pcall(delfile, sourcePath)
        return deleteOK
    end

    local function removeEmptyFolder(path)
        local remaining = listFolder(path)
        if remaining and #remaining == 0 then
            local removeFolder = type(delfolder) == "function" and delfolder
                or (type(deletefolder) == "function" and deletefolder or nil)
            if removeFolder then pcall(removeFolder, path) end
        end
    end

    S.__helpers.migrateLegacyE1LU4SAKENFolder = function()
        ensureFolderTree(hubRoot)
        if not folderExists(legacyRoot) then
            ensureFolderTree(managedRoot)
            return true
        end
        local entries = listFolder(legacyRoot)
        if not entries then return false end
        local allMoved = true
        for _, rawEntry in ipairs(entries) do
            local entry = normalizePath(rawEntry)
            local prefix = legacyRoot .. "/"
            local relative = entry:sub(1, #prefix) == prefix
                and entry:sub(#prefix + 1)
                or (entry:match("([^/]+)$") or entry)
            if relative ~= "" then
                local topLevel = relative:match("^([^/]+)") or relative
                local targetPath
                if topLevel == "LMS" then
                    targetPath = hubRoot .. "/LMS" .. relative:sub(#topLevel + 1)
                elseif topLevel == "Music" then
                    targetPath = hubRoot .. "/Music" .. relative:sub(#topLevel + 1)
                elseif relative == "LMS_DOWNLOAD_TOGGLE" then
                    targetPath = hubRoot .. "/LMS_DOWNLOAD_TOGGLE"
                else
                    targetPath = managedRoot .. "/" .. relative
                end
                if folderExists(entry) then
                    if not migrateTree(entry, targetPath) then allMoved = false end
                else
                    if not migrateSingleFile(entry, targetPath) then allMoved = false end
                end
            end
        end
        removeEmptyFolder(legacyRoot)
        local remaining = listFolder(legacyRoot)
        if remaining and #remaining > 0 then allMoved = false end
        return allMoved
    end

    pcall(S.__helpers.migrateLegacyE1LU4SAKENFolder)
end

S.OldForsakenMenu = {enabled = false, disabled = false, handler = nil, body = nil}
S.__helpers.setOldForsakenMenu = function(enabled)
    local state = S.OldForsakenMenu
    if state.disabled then return false end
    if enabled == false then
        state.enabled = false
        if state.handler and type(state.handler.Stop) == "function" then
            pcall(function() state.handler:Stop() end)
        end
        return true
    end
    if state.enabled and state.handler then return true end

    -- The old menu is loaded only from the managed folder inside E1LU4HUB.
    -- Its bundled model is required separately; no HTTP/GitHub fallback is used.
    pcall(S.__helpers.migrateLegacyE1LU4SAKENFolder)
    local menuFolder = "E1LU4HUB/E1LU4SAKEN"
    pcall(function() if type(makefolder) == "function" then makefolder("E1LU4HUB") end end)
    pcall(function() if type(makefolder) == "function" then makefolder(menuFolder) end end)
    local scriptPath = menuFolder .. "/sidebarscript.lua"
    local modelPath = menuFolder .. "/menus4.rbxm"
    local function localFileExists(path)
        if type(isfile) ~= "function" then return false end
        local ok, result = pcall(isfile, path)
        return ok and result == true
    end
    local function localRead(path)
        if not localFileExists(path) or type(readfile) ~= "function" then return nil end
        local ok, value = pcall(readfile, path)
        if ok and type(value) == "string" and value ~= "" then return value end
        return nil
    end

    if not localFileExists(scriptPath) then
        if S.__helpers.notify then
            S.__helpers.notify("Old Forsaken Menu", "Missing E1LU4HUB/E1LU4SAKEN/sidebarscript.lua", 5)
        end
        return false
    end
    if not localFileExists(modelPath) then
        if S.__helpers.notify then
            S.__helpers.notify("Old Forsaken Menu", "Missing E1LU4HUB/E1LU4SAKEN/menus4.rbxm", 5)
        end
        return false
    end

    local body = localRead(scriptPath)
    if not body then
        if S.__helpers.notify then
            S.__helpers.notify("Old Forsaken Menu", "Could not read the local sidebar script.", 5)
        end
        return false
    end

    -- Patch the known nested model download to use the already bundled RBXM.
    local patchedModelRead = 0
    body, patchedModelRead = body:gsub(
        'local data%s*=%s*game:HttpGet%([^%)]*%)',
        'local data = readfile("E1LU4HUB/E1LU4SAKEN/menus4.rbxm")',
        1
    )
    if patchedModelRead ~= 1 then
        if S.__helpers.notify then
            S.__helpers.notify("Old Forsaken Menu", "The local sidebar script format is not recognized; no remote code was run.", 5)
        end
        return false
    end
    body = body:gsub(
        'writefile%(%s*["\'][^"\']*/menus%.rbxm["\']%s*,%s*data%s*%)',
        'writefile("E1LU4HUB/E1LU4SAKEN/menus4.rbxm", data)',
        1
    )
    body = body:gsub(
        'getcustomasset%(%s*["\'][^"\']*/menus%.rbxm["\']%s*%)',
        'getcustomasset("E1LU4HUB/E1LU4SAKEN/menus4.rbxm")',
        1
    )

    -- Normalize old branding inside the local source before it is compiled.
    local oldBrand = "Cat" .. "saken"
    body = body:gsub(oldBrand, "E1LU4SAKEN")
    body = body:gsub(oldBrand:lower(), "E1LU4SAKEN")
    body = body:gsub(oldBrand:upper(), "E1LU4SAKEN")
    -- Re-root old sidecar paths without double-prefixing paths already under the hub.
    body = body:gsub("([^/])E1LU4SAKEN/", "%1E1LU4HUB/E1LU4SAKEN/")

    -- Refuse to execute if another network loader remains in the sidecar.
    if body:find("HttpGet", 1, true) or body:find("https://", 1, true)
        or body:find("http://", 1, true) then
        if S.__helpers.notify then
            S.__helpers.notify("Old Forsaken Menu", "The local sidebar file still contains a network request; execution was blocked.", 5)
        end
        return false
    end

    local marker = "--this watermark is used to confirm that the script by E1LU4SAKEN has been retrieved without failure"
    if not body:find(marker, 1, true) then
        if S.__helpers.notify then
            S.__helpers.notify("Old Forsaken Menu", "Local sidebar verification failed; menu was not executed.", 5)
        end
        return false
    end
    if type(loadstring) ~= "function" then
        if S.__helpers.notify then S.__helpers.notify("Old Forsaken Menu", "This executor does not support loadstring.", 5) end
        return false
    end
    local okLoad, factory = pcall(loadstring, body)
    if not okLoad or type(factory) ~= "function" then
        if S.__helpers.notify then S.__helpers.notify("Old Forsaken Menu", "The local menu could not be compiled.", 5) end
        return false
    end
    local okRun, handler = pcall(factory)
    if not okRun or type(handler) ~= "table" or type(handler.Run) ~= "function" then
        if S.__helpers.notify then S.__helpers.notify("Old Forsaken Menu", "The local menu did not return a valid handler.", 5) end
        return false
    end
    local okStart = pcall(function() handler:Run() end)
    if not okStart then
        if type(handler.Stop) == "function" then pcall(function() handler:Stop() end) end
        if S.__helpers.notify then S.__helpers.notify("Old Forsaken Menu", "The local menu failed to start.", 5) end
        return false
    end
    state.body, state.handler, state.enabled = body, handler, true
    return true
end
