    S.deviceSpoofEnabled = enabled == true
    local sendValue = S.deviceSpoofEnabled and (S.deviceSpoofCurrent or "PC")
        or (S.deviceSpoofOriginalAttribute or S.initialDetectedDevice or "PC")
    pcall(function()
        if S.NetworkModule and type(S.NetworkModule.FireServerConnection) == "function" then
            S.NetworkModule:FireServerConnection("SetDevice", "REMOTE_EVENT", sendValue)
        end
        if S.lp then
            local clientValue = S.deviceSpoofEnabled and (S.deviceSpoofClientCurrent or sendValue) or sendValue
            S.lp:SetAttribute("Device", clientValue)
        end
    end)
    return true
end
S.__helpers.installClientDeviceSpoof = function()
    if S.deviceSpoofClientHookInstalled or type(hookfunction) ~= "function" then return end
    local modules = S.ReplicatedStorage:FindFirstChild("Modules")
    local utilities = modules and modules:FindFirstChild("Utilities")
    local deviceModule = utilities and utilities:FindFirstChild("Device")
    if not deviceModule or not deviceModule:IsA("ModuleScript") then return end
    local ok, device = pcall(require, deviceModule)
    if not ok or type(device) ~= "table" or type(device.GetPlayerDevice) ~= "function" then return end
    local old
    local replacement = function(player, ...)
        if S.deviceSpoofEnabled and player == S.lp then return S.deviceSpoofClientCurrent end
        if old then return old(player, ...) end
    end
    local okHook, original = pcall(hookfunction, device.GetPlayerDevice, replacement)
    if okHook and type(original) == "function" then
        old = original
        S.deviceSpoofClientHookInstalled = true
    end
end
