-- Restore the original PlayerIcon image while preserving the game's current icon.
S.HidePlayerIcon = S.HidePlayerIcon or {
    enabled = false,
    originals = setmetatable({}, {__mode = "k"}),
    connections = {},
    iconWatchers = setmetatable({}, {__mode = "k"}),
    watchedPlayerGui = nil,
    imageAsset = nil,
}
S.__helpers.isHidePlayerIconTarget = function(object)
    return object and object:IsA("ImageLabel") and object.Name == "PlayerIcon"
        and object.Parent and object.Parent.Name == "PlayerInfo"
        and object.Parent.Parent and object.Parent.Parent.Name == "TemporaryUI"
end
S.__helpers.applyHidePlayerIconTo = function(icon)
    local state = S.HidePlayerIcon
    if not state.enabled or not S.__helpers.isHidePlayerIconTarget(icon) then return false end
    if not state.imageAsset then state.imageAsset = S.__helpers.getEmbeddedUIImage() end
    if type(state.imageAsset) ~= "string" or state.imageAsset == "" then return false end
    local applied = S.SkinChanger.setPlayerIcon(state.imageAsset, state.originals, icon)
    if applied and not state.iconWatchers[icon] then
        local connection = icon:GetPropertyChangedSignal("Image"):Connect(function()
            if state.enabled and icon.Parent and icon.Image ~= state.imageAsset then
                task.defer(function()
                    if state.enabled and icon.Parent and icon.Image ~= state.imageAsset then
                        S.SkinChanger.setPlayerIcon(state.imageAsset, state.originals, icon)
                    end
                end)
            end
        end)
        state.iconWatchers[icon] = connection
        table.insert(state.connections, connection)
    end
    return applied
end
S.__helpers.setHidePlayerIconEnabled = function(enabled)
    local state = S.HidePlayerIcon
    state.enabled = enabled == true
    if not state.enabled then
        for _, connection in ipairs(state.connections) do pcall(function() connection:Disconnect() end) end
        table.clear(state.connections)
        state.iconWatchers = setmetatable({}, {__mode = "k"})
        state.watchedPlayerGui = nil
        for icon, originalImage in pairs(state.originals) do
            if icon and icon.Parent then pcall(function() icon.Image = originalImage end) end
        end
        table.clear(state.originals)
        return true
    end

    state.imageAsset = S.__helpers.getEmbeddedUIImage()
    if type(state.imageAsset) ~= "string" or state.imageAsset == "" then
        state.enabled = false
        return false
    end
    local function watchPlayerGui(playerGui)
        if not state.enabled or not playerGui or state.watchedPlayerGui == playerGui then return end
        state.watchedPlayerGui = playerGui
        table.insert(state.connections, playerGui.DescendantAdded:Connect(function(object)
            if S.__helpers.isHidePlayerIconTarget(object) then
                task.defer(function() S.__helpers.applyHidePlayerIconTo(object) end)
            end
        end))
        for _, object in ipairs(playerGui:GetDescendants()) do
            if S.__helpers.isHidePlayerIconTarget(object) then
                S.__helpers.applyHidePlayerIconTo(object)
            end
        end
    end
    local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
    if playerGui then watchPlayerGui(playerGui) end
    if S.lp then
        table.insert(state.connections, S.lp.ChildAdded:Connect(function(child)
            if child:IsA("PlayerGui") then task.defer(function() watchPlayerGui(child) end) end
        end))
    end
    return true
end
