S.__helpers.setAutoBlockEnabled = function(value)
    -- Keep the master switch and its range panel configurable from either role.
    -- The Auto Block processor itself is Survivor-gated when it executes.
    local previousEnabled = S.isAutoBlockEnabled == true
    S.isAutoBlockEnabled = value == true
    S.AutoBlockV2.enabled = S.isAutoBlockEnabled

    -- Turning the Auto Block master OFF also cancels any Hitbox Drag startup
    -- delay that is waiting on a target-specific timer.
    if not S.isAutoBlockEnabled then
        S.autoBlockPendingToken = (tonumber(S.autoBlockPendingToken) or 0) + 1
        S.autoBlockPending = false
        S.hitboxDragPendingToken = (tonumber(S.hitboxDragPendingToken) or 0) + 1
        S.hitboxDragPending = false
        if not S.isHitboxDragActive then
            S.hitboxDragCooldown = false
        end
    end

    if S.autoBlockRangeContainer then
        -- Use Hitbox replaces the legacy distance range, so keep this setting
        -- hidden until the mode is turned OFF again.
        S.autoBlockRangeContainer.Visible = not S.isAutoBlockUseHitboxEnabled
    end

    if S.autoBlockToggleButton then
        S.autoBlockToggleButton:SetAttribute("ToggleState", S.isAutoBlockEnabled)
    end

    if S.autoBlockToggleBox then
        S.autoBlockToggleBox.BackgroundColor3 = S.isAutoBlockEnabled
            and S.uiAccentColor
            or Color3.fromRGB(48, 47, 56)
    end

    -- Keep the floating center button synchronized with every Auto Block entry point
    -- (the normal UI toggle, the grouped keybind, and the floating button itself).
    if S.__helpers.updateAutoBlockScreenButton then
        S.__helpers.updateAutoBlockScreenButton()
    end

    if previousEnabled ~= S.isAutoBlockEnabled
        and S.isAutoBlockToggleNoticeEnabled == true
        and S.__configApplying ~= true
        and type(S.__helpers.notify) == "function" then
        S.__helpers.notify(
            "Auto Block",
            S.isAutoBlockEnabled and "Auto Block is enabled." or "Auto Block is disabled.",
            3.6,
            S.isAutoBlockEnabled and S.NOTIFICATION_SUCCESS_COLOR or nil
        )
    end
end

