-- Remove any leftover instance from a previous run before the replacement is created.
pcall(function()
    local mainUI = S.__helpers.getMainUI and S.__helpers.getMainUI()
    local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer", true)
    local oldButton = abilityContainer and abilityContainer:FindFirstChild("FourthBlockAbility")
    if oldButton then oldButton:Destroy() end
end)
pcall(function()
    local legacyGui = S.CoreGui:FindFirstChild("E1LU4HUB_AutoBlockButton")
    if legacyGui then legacyGui:Destroy() end
end)

S.__helpers.disconnectAutoBlockButtonClone = function()
    local state = S.autoBlockButtonCloneState
    for _, connection in ipairs(state.connections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(state.connections)
end

S.__helpers.updateAutoBlockScreenButton = function()
    local state = S.autoBlockButtonCloneState
    local button = state and state.instance
    if not button or not button.Parent then return end

    local color = S.isAutoBlockEnabled == true
        and Color3.fromRGB(0, 255, 60)
        or Color3.fromRGB(255, 0, 0)
    if button:IsA("ImageButton") or button:IsA("ImageLabel") then
        button.ImageColor3 = color
    end
    for _, descendant in ipairs(button:GetDescendants()) do
        if descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
            descendant.ImageColor3 = color
        elseif descendant:IsA("Frame") and descendant.BackgroundTransparency < 1 then
            descendant.BackgroundColor3 = color
        end
    end
end

S.__helpers.stopAutoBlockButtonClone = function()
    local state = S.autoBlockButtonCloneState
    if not state then return end
    state.running = false
    S.__helpers.disconnectAutoBlockButtonClone()
    if state.instance and state.instance.Parent then
        pcall(function() state.instance:Destroy() end)
    end
    state.instance = nil
    state.sourceName = nil
    state.container = nil
end

S.__helpers.startAutoBlockButtonClone = function()
    local state = S.autoBlockButtonCloneState
    if state.running then return end
    state.running = true

    task.spawn(function()
        while state.running and S.isAutoBlockButtonEnabled do
            local mainUI = S.__helpers.getMainUI and S.__helpers.getMainUI()
            local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer", true)
            local sourceButton = abilityContainer and (
                abilityContainer:FindFirstChild("Block")
                or abilityContainer:FindFirstChild("Clone")
            )

            if abilityContainer and sourceButton and sourceButton:IsA("GuiObject") then
                local needsCreate = not state.instance
                    or not state.instance.Parent
                    or state.container ~= abilityContainer
                    or state.sourceName ~= sourceButton.Name

                if needsCreate then
                    S.__helpers.disconnectAutoBlockButtonClone()
                    if state.instance and state.instance.Parent then
                        pcall(function() state.instance:Destroy() end)
                    end

                    local clone = sourceButton:Clone()
                    clone.Name = "FourthBlockAbility"
                    clone.LayoutOrder = 4
                    clone.Visible = true
                    clone.Active = true
                    clone.ZIndex = math.max(clone.ZIndex, 50)

                    for _, descendant in ipairs(clone:GetDescendants()) do
                        if descendant:IsA("TextLabel") or descendant:IsA("TextButton") then
                            local labelText = tostring(descendant.Text or ""):lower()
                            if labelText:find("block", 1, true) or labelText:find("clone", 1, true) then
                                descendant.Text = ""
                                descendant.Visible = false
                            end
                        end
                        if descendant:IsA("GuiObject") then
                            descendant.ZIndex = math.max(descendant.ZIndex, 50)
                            descendant.Active = true
                        end
                    end

                    state.instance = clone
                    state.sourceName = sourceButton.Name
                    state.container = abilityContainer
                    clone.Parent = abilityContainer

                    local function toggleAutoBlock()
                        local now = os.clock()
                        if now - state.lastToggleAt < 0.15 then return end
                        state.lastToggleAt = now
                        S.__helpers.setAutoBlockEnabled(not S.isAutoBlockEnabled)
                    end

                    local foundButton = false
                    local function bindGuiButton(object)
                        if not object or not object:IsA("GuiButton") then return end
                        foundButton = true
                        pcall(function()
                            object.Active = true
                            object.Selectable = true
                        end)
                        table.insert(state.connections, object.Activated:Connect(toggleAutoBlock))
                    end
                    bindGuiButton(clone)
                    for _, descendant in ipairs(clone:GetDescendants()) do
                        bindGuiButton(descendant)
                    end

                    -- Fallback for an ability template built from Frames instead of GuiButtons.
                    if not foundButton then
                        local pressed = false
                        table.insert(state.connections, clone.InputBegan:Connect(function(input)
                            if input.UserInputType == Enum.UserInputType.MouseButton1
                                or input.UserInputType == Enum.UserInputType.Touch then
                                pressed = true
                            end
                        end))
                        table.insert(state.connections, clone.InputEnded:Connect(function(input)
                            if not pressed then return end
                            if input.UserInputType == Enum.UserInputType.MouseButton1
                                or input.UserInputType == Enum.UserInputType.Touch then
                                pressed = false
                                toggleAutoBlock()
                            end
                        end))
                    end
                end

                S.__helpers.updateAutoBlockScreenButton()
            elseif state.instance then
                S.__helpers.disconnectAutoBlockButtonClone()
                if state.instance.Parent then
                    pcall(function() state.instance:Destroy() end)
                end
                state.instance = nil
                state.sourceName = nil
                state.container = nil
            end

            task.wait(0.5)
        end

        if not S.isAutoBlockButtonEnabled then
            S.__helpers.stopAutoBlockButtonClone()
        end
    end)
end

S.__helpers.refreshAutoBlockButtonClone = function()
    if S.isAutoBlockButtonEnabled then
        S.__helpers.startAutoBlockButtonClone()
    else
        S.__helpers.stopAutoBlockButtonClone()
    end
end

S.__helpers.refreshAutoBlockButtonClone()

