-- This selector is custom-built rather than using the generic dropdown helper,
-- so register it explicitly or Save/Load Config will silently omit its value.
S.AUTO_BLOCK_DETECTION_MODES = {"Animation + Sounds detection", "Animation Detection", "Sounds Detection"}
S.__helpers.setAutoBlockDetectionMode = function(value, runCallback)
    value = tostring(value or "")
    -- Backward compatibility for configs saved before the visible name was changed.
    if value == "Ability Detection" or value == "Animation + sounds detection" then
        value = "Animation + Sounds detection"
    end
    local valid = false
    for _, option in ipairs(S.AUTO_BLOCK_DETECTION_MODES) do
        if value == option then valid = true break end
    end
    if not valid then return false end
    S.autoBlockDetectionMode = value
    if S.__helpers.refreshRightDropdownButton then
        S.__helpers.refreshRightDropdownButton(S.autoBlockDetectionModeButton)
    elseif S.autoBlockDetectionModeButton then
        S.autoBlockDetectionModeButton.Text = "AUTO BLOCK DETECTION: " .. value
    end
    return true
end

table.insert(S.configDropdownRegistry, {
    button = S.autoBlockDetectionModeButton,
    label = "Auto Block Detection",
    defaultValue = "Animation Detection",
    getValue = function() return S.autoBlockDetectionMode end,
    setValue = function(value, runCallback)
        return S.__helpers.setAutoBlockDetectionMode(value, runCallback)
    end,
})

S.__helpers.createRangeControl = function(labelText, defaultValue, minValue, maxValue, callback, stepValue)
    local container = Instance.new("Frame")
    container.Name = "RangeContainer"
    container.Size = UDim2.new(0.82, 0, 0, 64)
    container.BackgroundTransparency = 1
    container.Parent = S.contentFrame

    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(0.58, 0, 0, 22)
    lbl.Position = UDim2.new(0, 0, 0, 0)
    lbl.Text = labelText
    lbl.TextColor3 = Color3.fromRGB(175, 173, 183)
    lbl.Font = Enum.Font.Gotham
    lbl.TextSize = 11
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.BackgroundTransparency = 1
    lbl.Parent = container

    local box = Instance.new("TextBox")
    box.Name = "ValueBox"
    box.Size = UDim2.new(0, 58, 0, 22)
    box.Position = UDim2.new(1, -58, 0, 0)
    box.BackgroundColor3 = Color3.fromRGB(48, 47, 56)
    box.Text = tostring(defaultValue)
    box.TextColor3 = Color3.new(1, 1, 1)
    box.Font = Enum.Font.Gotham
    box.TextSize = 11
    box.ClearTextOnFocus = false
    box.Parent = container

    local boxCorner = Instance.new("UICorner")
    boxCorner.CornerRadius = UDim.new(0, 3)
    boxCorner.Parent = box

    local bg = Instance.new("Frame")
    bg.Name = "SliderBackground"
    bg.Size = UDim2.new(1, 0, 0, 6)
    bg.Position = UDim2.new(0, 0, 0, 34)
    bg.BackgroundColor3 = Color3.fromRGB(48, 47, 56)
    bg.BorderSizePixel = 0
    bg.Active = true
    bg.Parent = container

    local bgCorner = Instance.new("UICorner")
    bgCorner.CornerRadius = UDim.new(0, 3)
    bgCorner.Parent = bg

    local fill = Instance.new("Frame")
    fill.Name = "SliderFill"
    fill.BackgroundColor3 = S.uiAccentColor
    fill.BorderSizePixel = 0
    fill.Parent = bg

    local fillCorner = Instance.new("UICorner")
    fillCorner.CornerRadius = UDim.new(0, 3)
    fillCorner.Parent = fill

    -- Typed values are allowed outside the slider range; the slider thumb
    -- remains visually clamped to the track's endpoints.
    local function setValue(value, allowOutOfRange)
        value = tonumber(value)
        if not value or value ~= value or value == math.huge or value == -math.huge then
            value = defaultValue
        end
        local step = math.max(0.000001, tonumber(stepValue) or 1)
        value = minValue + math.floor(((value - minValue) / step) + 0.5) * step
        if not allowOutOfRange then
            value = math.clamp(value, minValue, maxValue)
        end

        local ratio = (value - minValue) / (maxValue - minValue)
        ratio = math.clamp(ratio, 0, 1)
        fill.Size = UDim2.new(ratio, 0, 1, 0)
        box.Text = tostring(value)
        callback(value)
    end

    local function updateFromInput(input)
        if bg.AbsoluteSize.X <= 0 then return end
        local ratio = math.clamp((input.Position.X - bg.AbsolutePosition.X) / bg.AbsoluteSize.X, 0, 1)
        local value = minValue + ratio * (maxValue - minValue)
        setValue(value)
    end

    S.__helpers.connect(box.FocusLost, function()
        local value = tonumber(box.Text)
        if value then
            setValue(value, true)
        else
            setValue(defaultValue)
        end
    end)

    local sliding = false
    S.__helpers.connect(bg.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            sliding = true
            updateFromInput(input)
        end
    end)

    S.__helpers.connect(S.UserInputService.InputChanged, function(input)
        if not sliding then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            updateFromInput(input)
        end
    end)

    S.__helpers.connect(S.UserInputService.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            sliding = false
        end
    end)

    setValue(defaultValue)

    -- Register the Auto Block range and Facing Check settings with Configs.
    table.insert(S.configNumericRegistry, {
        container = container,
        box = box,
        label = labelText,
        setValue = setValue,
        getValue = function() return tonumber(box.Text) or defaultValue end,
    })

    return container, box
end

