-- ================================================================
-- STATIC SURVIVOR-BASED AUTO BLOCK RANGE PREVIEW
-- This is a settings visualizer, not a live player tracker. It uses a frozen
-- Survivor rig centered inside the range circle and viewed from directly above,
-- then redraws the configured Auto Block range,
-- Facing Check angle and close-range allowance whenever those settings change.
-- The geometry follows the same mode choice as the in-world Range ESP:
-- a full detection circle without Facing Check, or a facing cone plus the
-- close-range disc while Facing Check is enabled.
-- All implementation locals are scoped inside this helper to preserve the
-- main-chunk Luau local-register budget.
-- ================================================================
S.__helpers.createAutoBlockRangePreview = function()
    local previewCard = Instance.new("Frame")
    previewCard.Name = "AutoBlockRangePreviewCard"
    -- The preview is displayed inline directly beneath SHOW AUTO BLOCK RANGE.
    -- There is no separate Show Preview toggle.
    previewCard.Size = UDim2.fromOffset(280, 254)
    previewCard.BackgroundColor3 = Color3.fromRGB(24, 23, 29)
    previewCard.BackgroundTransparency = 0
    previewCard.BorderSizePixel = 0
    previewCard.Parent = S.contentFrame
    S.autoBlockRangePreviewCard = previewCard

    local cardCorner = Instance.new("UICorner")
    cardCorner.CornerRadius = UDim.new(0, 6)
    cardCorner.Parent = previewCard
    local cardStroke = Instance.new("UIStroke")
    cardStroke.Color = Color3.fromRGB(62, 59, 72)
    cardStroke.Thickness = 1
    cardStroke.Transparency = 0.12
    cardStroke.Parent = previewCard

    local title = Instance.new("TextLabel")
    title.Name = "PreviewTitle"
    title.Position = UDim2.fromOffset(10, 5)
    title.Size = UDim2.new(1, -20, 0, 18)
    title.BackgroundTransparency = 1
    title.Text = "AUTO BLOCK RANGE PREVIEW"
    title.TextColor3 = S.uiAccentColor or Color3.fromRGB(190, 150, 255)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Parent = previewCard

    local canvas = Instance.new("Frame")
    canvas.Name = "RangePreviewCanvas"
    canvas.Position = UDim2.fromOffset(8, 27)
    canvas.Size = UDim2.new(1, -16, 0, 196)
    canvas.BackgroundColor3 = Color3.fromRGB(15, 14, 18)
    canvas.BackgroundTransparency = 0
    canvas.BorderSizePixel = 0
    canvas.ClipsDescendants = true
    canvas.Parent = previewCard
    local canvasCorner = Instance.new("UICorner")
    canvasCorner.CornerRadius = UDim.new(0, 4)
    canvasCorner.Parent = canvas
    local canvasStroke = Instance.new("UIStroke")
    canvasStroke.Color = Color3.fromRGB(54, 52, 62)
    canvasStroke.Thickness = 1
    canvasStroke.Parent = canvas

    -- Full-range ring is shown when Facing Check is off.
    local rangeRing = Instance.new("Frame")
    rangeRing.Name = "DetectionRangeRing"
    rangeRing.AnchorPoint = Vector2.new(0.5, 0.5)
    rangeRing.BackgroundTransparency = 1
    rangeRing.BorderSizePixel = 0
    rangeRing.ZIndex = 2
    rangeRing.Parent = canvas
    local rangeRingCorner = Instance.new("UICorner")
    rangeRingCorner.CornerRadius = UDim.new(1, 0)
    rangeRingCorner.Parent = rangeRing
    local rangeRingStroke = Instance.new("UIStroke")
    rangeRingStroke.Color = Color3.fromRGB(222, 91, 101)
    rangeRingStroke.Thickness = 1.8
    rangeRingStroke.Transparency = 0.12
    rangeRingStroke.Parent = rangeRing

    -- Filled close-range disc used with the facing cone (4-stud Auto Block allowance).
    local closeDisc = Instance.new("Frame")
    closeDisc.Name = "CloseRangeDisc"
    closeDisc.AnchorPoint = Vector2.new(0.5, 0.5)
    closeDisc.BackgroundColor3 = Color3.fromRGB(224, 105, 116)
    closeDisc.BackgroundTransparency = 0.67
    closeDisc.BorderSizePixel = 0
    closeDisc.ZIndex = 2
    closeDisc.Parent = canvas
    local closeDiscCorner = Instance.new("UICorner")
    closeDiscCorner.CornerRadius = UDim.new(1, 0)
    closeDiscCorner.Parent = closeDisc
    local closeDiscStroke = Instance.new("UIStroke")
    closeDiscStroke.Color = Color3.fromRGB(224, 105, 116)
    closeDiscStroke.Thickness = 1
    closeDiscStroke.Transparency = 0.45
    closeDiscStroke.Parent = closeDisc

    local coneLines = {}
    for index = 1, 4 do
        local line = Instance.new("Frame")
        line.Name = "FacingConeLine" .. tostring(index)
        line.AnchorPoint = Vector2.new(0.5, 0.5)
        line.Size = UDim2.fromOffset(1, 2)
        line.BackgroundColor3 = Color3.fromRGB(222, 91, 101)
        line.BackgroundTransparency = 0.08
        line.BorderSizePixel = 0
        line.ZIndex = 4
        line.Parent = canvas
        coneLines[index] = line
    end

    local coneMarkers = {}
    for index = 1, 3 do
        local marker = Instance.new("Frame")
        marker.Name = "FacingConePoint" .. tostring(index)
        marker.AnchorPoint = Vector2.new(0.5, 0.5)
        marker.Size = UDim2.fromOffset(6, 6)
        marker.BackgroundColor3 = Color3.fromRGB(222, 91, 101)
        marker.BorderSizePixel = 0
        marker.ZIndex = 5
        marker.Parent = canvas
        local markerCorner = Instance.new("UICorner")
        markerCorner.CornerRadius = UDim.new(1, 0)
        markerCorner.Parent = marker
        coneMarkers[index] = marker
    end

    -- A dedicated ViewportFrame keeps the Survivor model 3D while the range
    -- guide remains a clean, readable diagram above it.
    local avatarViewport = Instance.new("ViewportFrame")
    avatarViewport.Name = "SurvivorRangePreview"
    avatarViewport.AnchorPoint = Vector2.new(0.5, 0.5)
    avatarViewport.Size = UDim2.fromOffset(46, 46)
    avatarViewport.BackgroundTransparency = 1
    avatarViewport.BorderSizePixel = 0
    avatarViewport.Ambient = Color3.fromRGB(195, 195, 205)
    avatarViewport.LightColor = Color3.fromRGB(245, 245, 255)
    avatarViewport.LightDirection = Vector3.new(-1, -1, -1)
    avatarViewport.ZIndex = 6
    avatarViewport.Parent = canvas

    local avatarCamera = Instance.new("Camera")
    avatarCamera.Name = "SurvivorRangePreviewCamera"
    avatarCamera.FieldOfView = 38
    avatarCamera.Parent = avatarViewport
    avatarViewport.CurrentCamera = avatarCamera
    local avatarWorld = Instance.new("WorldModel")
    avatarWorld.Name = "SurvivorRangePreviewWorld"
    avatarWorld.Parent = avatarViewport

    local info = Instance.new("TextLabel")
    info.Name = "RangePreviewInfo"
    info.Position = UDim2.fromOffset(8, 227)
    info.Size = UDim2.new(1, -16, 0, 16)
    info.BackgroundTransparency = 1
    info.TextColor3 = Color3.fromRGB(151, 148, 160)
    info.Font = Enum.Font.Gotham
    info.TextSize = 9
    info.TextXAlignment = Enum.TextXAlignment.Center
    info.TextTruncate = Enum.TextTruncate.AtEnd
    info.Parent = previewCard

    local preview = {
        card = previewCard,
        canvas = canvas,
        info = info,
        camera = avatarCamera,
        world = avatarWorld,
        avatarViewport = avatarViewport,
        survivorModel = nil,
        visible = true,
        connections = {},
    }
    S.autoBlockRangePreview = preview

    -- Avoid scrolling the Auto Block page while the pointer is over this card.
    local contentScrollFrame = S.contentFrame
    local originalScrollingEnabled = true
    if contentScrollFrame and contentScrollFrame:IsA("ScrollingFrame") then
        originalScrollingEnabled = contentScrollFrame.ScrollingEnabled
    end
    local function setHover(active)
        preview.hovering = active == true
        if contentScrollFrame and contentScrollFrame.Parent
            and contentScrollFrame:IsA("ScrollingFrame") then
            if preview.hovering then
                contentScrollFrame.ScrollingEnabled = false
            else
                contentScrollFrame.ScrollingEnabled = originalScrollingEnabled
            end
        end
    end
    preview.setHover = setHover
    previewCard.Active = true
    S.__helpers.connect(previewCard.MouseEnter, function() setHover(true) end)
    S.__helpers.connect(previewCard.MouseLeave, function() setHover(false) end)

    local function isSurvivorRig(model)
        if not model or not model:IsA("Model") then return false end
        local humanoid = model:FindFirstChildWhichIsA("Humanoid", true)
        local root = model:FindFirstChild("HumanoidRootPart", true)
            or model:FindFirstChild("RootPart", true)
            or model.PrimaryPart
            or model:FindFirstChildWhichIsA("BasePart", true)
        if not root then return false end
        local visibleBodyParts = 0
        for _, descendant in ipairs(model:GetDescendants()) do
            if descendant:IsA("BasePart") and descendant ~= root
                and descendant.Name ~= "QueryHitbox" and descendant.Name ~= "CollisionHitbox" then
                local visible = true
                pcall(function() visible = descendant.Transparency < 0.98 end)
                if visible then visibleBodyParts += 1 end
            end
        end
        -- Some stored Survivor rigs omit Humanoid but still contain a complete
        -- renderable body. Accept those assets while rejecting empty/weapon models.
        return humanoid ~= nil or visibleBodyParts >= 2
    end

    local function findSurvivorRig(container)
        if not container then return nil end
        if container:IsA("Model") and isSurvivorRig(container) then return container end
        for _, descendant in ipairs(container:GetDescendants()) do
            if descendant:IsA("Model") and isSurvivorRig(descendant) then
                return descendant
            end
        end
        return nil
    end

    local function getSurvivorSource()
        local character = S.lp and S.lp.Character
        if character and S.__helpers.isLocalRole("Survivor") and isSurvivorRig(character) then
            return character
        end

        -- When loaded from the lobby or while the local player is not a Survivor,
        -- use an in-round Survivor snapshot if one exists.
        local playersFolder = workspace:FindFirstChild("Players")
        local survivorsFolder = playersFolder and (playersFolder:FindFirstChild("Survivors")
            or playersFolder:FindFirstChild("survivors"))
        if survivorsFolder then
            for _, candidate in ipairs(survivorsFolder:GetChildren()) do
                if isSurvivorRig(candidate) then return candidate end
            end
        end

        -- Lobby fallback: prefer Guest1337, then any Survivor asset with a Humanoid/root.
        local assets = S.ReplicatedStorage and S.ReplicatedStorage:FindFirstChild("Assets")
        local survivorAssets = assets and assets:FindFirstChild("Survivors")
        if survivorAssets then
            local preferred = survivorAssets:FindFirstChild("Guest1337")
            local preferredModel = findSurvivorRig(preferred)
            if preferredModel then return preferredModel end
            local anyModel = findSurvivorRig(survivorAssets)
            if anyModel then return anyModel end
        end
        local skinAssets = assets and assets:FindFirstChild("Skins")
        local skinSurvivors = skinAssets and skinAssets:FindFirstChild("Survivors")
        local skinModel = findSurvivorRig(skinSurvivors)
        if skinModel then return skinModel end
        local instanceAssets = assets and assets:FindFirstChild("Instances")
        local dummy = instanceAssets and instanceAssets:FindFirstChild("Dummy")
        local dummyModel = findSurvivorRig(dummy)
        if dummyModel then return dummyModel end
        return nil
    end

    local function cloneModel(source)
        if not source or not source:IsA("Model") then return nil end
        local oldArchivable = source.Archivable
        local changedArchivable = false
        if not oldArchivable then
            local ok = pcall(function() source.Archivable = true end)
            changedArchivable = ok
        end
        local ok, clone = pcall(function() return source:Clone() end)
        if changedArchivable then pcall(function() source.Archivable = oldArchivable end) end
        if ok and clone and clone:IsA("Model") then return clone end
        return nil
    end

    local function makeFallbackSurvivor()
        local model = Instance.new("Model")
        model.Name = "SurvivorRangePreviewFallback"
        local function makePart(name, size, color, position, transparency)
            local part = Instance.new("Part")
            part.Name = name
            part.Size = size
            part.Color = color
            part.Position = position
            part.Anchored = true
            part.CanCollide = false
            part.CanTouch = false
            part.CanQuery = false
            part.CastShadow = false
            part.Transparency = transparency or 0
            part.Parent = model
            return part
        end
        local root = makePart("HumanoidRootPart", Vector3.new(2, 2, 1), Color3.new(1, 1, 1), Vector3.new(0, 2.8, 0), 1)
        makePart("Torso", Vector3.new(2, 2, 1), Color3.fromRGB(150, 52, 58), Vector3.new(0, 3, 0))
        makePart("Head", Vector3.new(1.15, 1.15, 1.15), Color3.fromRGB(220, 190, 160), Vector3.new(0, 4.58, 0))
        makePart("LeftArm", Vector3.new(0.8, 2, 0.85), Color3.fromRGB(175, 65, 70), Vector3.new(-1.38, 3, 0))
        makePart("RightArm", Vector3.new(0.8, 2, 0.85), Color3.fromRGB(175, 65, 70), Vector3.new(1.38, 3, 0))
        makePart("LeftLeg", Vector3.new(0.9, 1.8, 0.95), Color3.fromRGB(45, 45, 54), Vector3.new(-0.48, 1.1, 0))
        makePart("RightLeg", Vector3.new(0.9, 1.8, 0.95), Color3.fromRGB(45, 45, 54), Vector3.new(0.48, 1.1, 0))
        model.PrimaryPart = root
        return model
    end

    local function mountSurvivor(source)
        local replacement = cloneModel(source)
        if not replacement then replacement = makeFallbackSurvivor() end
        replacement.Name = "AutoBlockRangePreviewSurvivor"

        for _, descendant in ipairs(replacement:GetDescendants()) do
            if descendant:IsA("Script") or descendant:IsA("LocalScript") then
                pcall(function() descendant:Destroy() end)
            elseif descendant:IsA("Animator") then
                pcall(function() descendant:Destroy() end)
            elseif descendant:IsA("BasePart") then
                pcall(function()
                    descendant.Anchored = true
                    descendant.CanCollide = false
                    descendant.CanTouch = false
                    descendant.CanQuery = false
                    descendant.CastShadow = false
                    descendant.LocalTransparencyModifier = 0
                end)
            elseif descendant:IsA("Humanoid") then
                pcall(function()
                    descendant.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                    descendant.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
                    descendant.NameDisplayDistance = 0
                end)
            end
        end

        local root = replacement:FindFirstChild("HumanoidRootPart", true)
            or replacement:FindFirstChild("RootPart", true)
            or replacement.PrimaryPart
            or replacement:FindFirstChildWhichIsA("BasePart", true)
        if root then
            pcall(function()
                replacement.PrimaryPart = root
                local pivot = replacement:GetPivot()
                local rootToPivot = pivot:ToObjectSpace(root.CFrame)
                -- Face the top of the diagram (-Z) so the cone has a consistent direction.
                replacement:PivotTo(CFrame.new(0, 0, 0) * rootToPivot:Inverse())
            end)
        end
        replacement.Parent = avatarWorld
        local old = preview.survivorModel
        preview.survivorModel = replacement
        if old and old ~= replacement then pcall(function() old:Destroy() end) end

        local okBounds, boundsCF, boundsSize = pcall(function() return replacement:GetBoundingBox() end)
        if okBounds and boundsCF and boundsSize then
            -- Top-down / map-style view: look straight down at the Survivor's
            -- root so the character sits in the middle of the range circle.
            -- Use world -Z as screen-up so the Survivor's forward direction
            -- (also -Z) points toward the top of the facing-cone diagram.
            avatarCamera.FieldOfView = 44
            local aspect = 48 / 46
            pcall(function()
                local viewportSize = avatarViewport.AbsoluteSize
                if viewportSize.X > 1 and viewportSize.Y > 1 then
                    aspect = viewportSize.X / viewportSize.Y
                end
            end)
            local halfFovTangent = math.tan(math.rad(avatarCamera.FieldOfView * 0.5))
            local horizontalFootprint = math.max(boundsSize.X / math.max(0.5, aspect), boundsSize.Z, 2.5)
            local topDownDistance = math.max(5.5, (horizontalFootprint * 0.5 / math.max(0.01, halfFovTangent)) * 1.35)
            avatarCamera.CFrame = CFrame.lookAt(
                Vector3.new(0, topDownDistance, 0),
                Vector3.new(0, 0, 0),
                Vector3.new(0, 0, -1)
            )
        else
            -- Safe overhead fallback framing for incomplete Survivor rigs.
            avatarCamera.FieldOfView = 44
            avatarCamera.CFrame = CFrame.lookAt(
                Vector3.new(0, 7, 0),
                Vector3.new(0, 0, 0),
                Vector3.new(0, 0, -1)
            )
        end
    end

    local function setLine(line, fromPoint, toPoint, color)
        local delta = toPoint - fromPoint
        line.Position = UDim2.fromOffset((fromPoint.X + toPoint.X) * 0.5, (fromPoint.Y + toPoint.Y) * 0.5)
        line.Size = UDim2.fromOffset(math.max(1, delta.Magnitude), 2)
        line.Rotation = math.deg(math.atan2(delta.Y, delta.X))
        line.BackgroundColor3 = color
    end

    local function updatePreview()
        if not preview.card or not preview.card.Parent then return end
        local width = canvas.AbsoluteSize.X
        local height = canvas.AbsoluteSize.Y
        -- AbsoluteSize can still be zero during the first construction frame.
        -- Use the card's authored dimensions until Roblox completes layout.
        if width < 80 then width = 264 end
        if height < 80 then height = 196 end
        local centerX = width * 0.5
        local detectionRange = math.clamp(tonumber(S.autoBlockDetectionRange) or 16, 1, 30)
        local facingESPRange = math.clamp(tonumber(S.facingCheckESPRange) or 16, 1, 20)
        local angleDegrees = math.clamp(tonumber(S.facingCheckAngleDegrees) or 85, 1, 200)
        local facingEnabled = S.isFacingCheckEnabled == true
        -- With Facing Check, put the Survivor near the bottom so the cone can
        -- extend upward from its position. Without it, center the Survivor in
        -- the full-range circle.
        local originY = height * (facingEnabled and 0.82 or 0.5)
        local useHitbox = S.isAutoBlockUseHitboxEnabled == true
        local color = useHitbox and Color3.fromRGB(124, 120, 132) or Color3.fromRGB(222, 91, 101)

        local origin = Vector2.new(centerX, originY)
        if facingEnabled then
            -- Facing Check ESP has its own visual range, while the real Auto Block
            -- still has the detection-range cap. Show the effective overlap of both.
            local effectiveRange = math.min(detectionRange, facingESPRange)
            local coneLength = math.clamp(effectiveRange * 6.8, 12, math.min(116, height - 43))
            local halfAngle = math.rad(angleDegrees * 0.5)
            local apex = Vector2.new(centerX, originY - coneLength)
            local sideY = math.cos(halfAngle) * coneLength
            local sideX = math.sin(halfAngle) * coneLength
            local leftPoint = Vector2.new(centerX - sideX, originY - sideY)
            local rightPoint = Vector2.new(centerX + sideX, originY - sideY)
            local points = {origin, leftPoint, apex, rightPoint, origin}
            for index = 1, 4 do setLine(coneLines[index], points[index], points[index + 1], color) end
            for index, point in ipairs({leftPoint, apex, rightPoint}) do
                coneMarkers[index].Position = UDim2.fromOffset(point.X, point.Y)
                coneMarkers[index].BackgroundColor3 = color
                coneMarkers[index].Visible = true
            end
            for _, line in ipairs(coneLines) do line.Visible = true end
            rangeRing.Visible = false

            local closeRadius = math.min(
                tonumber(S.AUTO_BLOCK_CLOSE_RANGE) or 4,
                effectiveRange
            )
            local closeDiameter = math.clamp(closeRadius * 2 * (coneLength / math.max(0.1, effectiveRange)) * 0.8, 14, 58)
            closeDisc.Size = UDim2.fromOffset(closeDiameter, closeDiameter)
            closeDisc.Position = UDim2.fromOffset(centerX, originY)
            closeDisc.Visible = true
            closeDiscStroke.Color = color
            closeDisc.BackgroundColor3 = color

            if useHitbox then
                info.Text = string.format("USE HITBOX ACTIVE  |  Range preview inactive  |  %.0f°", angleDegrees)
            else
                info.Text = string.format("Range: %.0f st  |  ESP: %.0f st  |  Facing: %.0f°", detectionRange, facingESPRange, angleDegrees)
            end
        else
            local radius = math.clamp(detectionRange * 5.6, 10, math.min(70, width * 0.34, height * 0.38))
            rangeRing.Size = UDim2.fromOffset(radius * 2, radius * 2)
            rangeRing.Position = UDim2.fromOffset(centerX, originY)
            rangeRingStroke.Color = color
            rangeRing.Visible = true
            closeDisc.Visible = false
            for _, line in ipairs(coneLines) do line.Visible = false end
            for _, marker in ipairs(coneMarkers) do marker.Visible = false end
            if useHitbox then
                info.Text = "USE HITBOX ACTIVE  |  Range preview inactive"
            else
                info.Text = string.format("Auto Block range: %.0f studs  |  Facing Check: OFF", detectionRange)
            end
        end

        -- rangeRing / closeDisc are centered at (centerX, originY); place the
        -- Survivor viewport at that exact same center instead of above it.
        avatarViewport.Position = UDim2.fromOffset(centerX, originY)
        -- The preview is always visible; it is positioned inline beneath
        -- SHOW AUTO BLOCK RANGE instead of using a separate Show Preview button.
        canvas.Visible = true
        info.Visible = true
        avatarViewport.Visible = true
        -- The model stays frozen; only the settings diagram is redrawn.
    end

    local source = getSurvivorSource()
    mountSurvivor(source)
    if not source then
        info.Text = "Survivor asset unavailable - using preview dummy"
    end

    if S.lp then
        S.__helpers.connect(S.lp.CharacterAdded, function(character)
            task.delay(0.35, function()
                if not preview.card or not preview.card.Parent then return end
                if character and S.__helpers.isLocalRole("Survivor") and isSurvivorRig(character) then
                    mountSurvivor(character)
                    updatePreview()
                end
            end)
        end)
    end

    preview.refresh = updatePreview
    S.__helpers.refreshAutoBlockRangePreview = updatePreview
    S.__helpers.connect(canvas:GetPropertyChangedSignal("AbsoluteSize"), updatePreview)
    updatePreview()
    return preview
end

S.autoBlockRangePreviewCreateOK, S.autoBlockRangePreviewCreateError = pcall(S.__helpers.createAutoBlockRangePreview)
if not S.autoBlockRangePreviewCreateOK then
    warn("[E1LU4HUB Auto Block Range Preview] " .. tostring(S.autoBlockRangePreviewCreateError))
    if S.autoBlockRangePreviewCard and S.autoBlockRangePreviewCard.Parent then
        pcall(function() S.autoBlockRangePreviewCard:Destroy() end)
    end
end
S.autoBlockRangePreviewCreateOK = nil
S.autoBlockRangePreviewCreateError = nil
S.__helpers.createAutoBlockRangePreview = nil

-- ================================================================
-- STATIC 3D HITBOX PREVIEW
-- This is a visual sample, not a live Killer tracker. Its default framing places
-- a small, side-facing Killer rig at the right edge of the prediction volume,
-- matching the supplied reference image. Drag to rotate; wheel to zoom.
-- The box uses the same shared dimensions, fill material, edge material,
-- colors and opacity getters as the actual Hitbox Prediction ESP.
-- Keep preview locals inside this helper to preserve the main-chunk local budget.
-- ================================================================
S.__helpers.createHitboxPreview = function()
    -- Calibrate the preview rig against the default prediction box.
    -- The 7.8-stud preview body changes framing only, not live hitbox dimensions.
    -- The visual model is aligned with its feet at the lowest edge of the preview hitbox.
    local PREVIEW_KILLER_HEIGHT = 7.8

    local previewCard = Instance.new("Frame")
    previewCard.Name = "HitboxPreviewCard"
    previewCard.Size = UDim2.fromOffset(280, 270)
    previewCard.BackgroundColor3 = Color3.fromRGB(24, 23, 29)
    previewCard.BackgroundTransparency = 0
    previewCard.BorderSizePixel = 0
    previewCard.Parent = S.contentFrame
    S.hitboxPreviewCard = previewCard

    local cardCorner = Instance.new("UICorner")
    cardCorner.CornerRadius = UDim.new(0, 6)
    cardCorner.Parent = previewCard

    local cardStroke = Instance.new("UIStroke")
    cardStroke.Color = Color3.fromRGB(62, 59, 72)
    cardStroke.Thickness = 1
    cardStroke.Transparency = 0.12
    cardStroke.Parent = previewCard

    local previewTitle = Instance.new("TextLabel")
    previewTitle.Name = "PreviewTitle"
    previewTitle.Position = UDim2.fromOffset(10, 5)
    previewTitle.Size = UDim2.new(1, -20, 0, 18)
    previewTitle.BackgroundTransparency = 1
    previewTitle.Text = "HITBOX PREVIEW"
    previewTitle.TextColor3 = S.uiAccentColor or Color3.fromRGB(190, 150, 255)
    previewTitle.Font = Enum.Font.GothamBold
    previewTitle.TextSize = 11
    previewTitle.TextXAlignment = Enum.TextXAlignment.Left
    previewTitle.Parent = previewCard

    local viewport = Instance.new("ViewportFrame")
    viewport.Name = "HitboxPreviewViewport"
    viewport.Position = UDim2.fromOffset(8, 27)
    viewport.Size = UDim2.new(1, -16, 0, 190)
    viewport.BackgroundColor3 = Color3.fromRGB(13, 12, 17)
    viewport.BackgroundTransparency = 0.02
    viewport.BorderSizePixel = 0
    viewport.Ambient = Color3.fromRGB(175, 180, 195)
    viewport.LightColor = Color3.fromRGB(245, 245, 255)
    viewport.LightDirection = Vector3.new(-1, -1.2, -1)
    viewport.Active = true
    viewport.Parent = previewCard

    local viewportCorner = Instance.new("UICorner")
    viewportCorner.CornerRadius = UDim.new(0, 4)
    viewportCorner.Parent = viewport

    local viewportStroke = Instance.new("UIStroke")
    viewportStroke.Color = Color3.fromRGB(55, 53, 64)
    viewportStroke.Thickness = 1
    viewportStroke.Parent = viewport

    local camera = Instance.new("Camera")
    camera.Name = "HitboxPreviewCamera"
    camera.FieldOfView = 42
    camera.Parent = viewport
    viewport.CurrentCamera = camera

    local worldModel = Instance.new("WorldModel")
    worldModel.Name = "HitboxPreviewWorld"
    worldModel.Parent = viewport

    local previewHint = Instance.new("TextLabel")
    previewHint.Name = "PreviewHint"
    previewHint.Position = UDim2.fromOffset(8, 220)
    previewHint.Size = UDim2.new(1, -16, 0, 13)
    previewHint.BackgroundTransparency = 1
    previewHint.Text = "Drag to rotate  |  Scroll to zoom"
    previewHint.TextColor3 = Color3.fromRGB(135, 132, 145)
    previewHint.Font = Enum.Font.Gotham
    previewHint.TextSize = 9
    previewHint.TextXAlignment = Enum.TextXAlignment.Center
    previewHint.Parent = previewCard

    local normalButton = Instance.new("TextButton")
    normalButton.Name = "NormalPreviewButton"
    normalButton.Position = UDim2.new(0.5, -74, 0, 238)
    normalButton.Size = UDim2.fromOffset(68, 28)
    normalButton.BackgroundColor3 = Color3.fromRGB(49, 47, 58)
    normalButton.BorderSizePixel = 0
    normalButton.AutoButtonColor = true
    normalButton.Text = "NORMAL"
    normalButton.TextColor3 = Color3.new(1, 1, 1)
    normalButton.Font = Enum.Font.GothamBold
    normalButton.TextSize = 9
    normalButton.Parent = previewCard
    local normalCorner = Instance.new("UICorner")
    normalCorner.CornerRadius = UDim.new(0, 4)
    normalCorner.Parent = normalButton

    local readyButton = Instance.new("TextButton")
    readyButton.Name = "ReadyPreviewButton"
    readyButton.Position = UDim2.new(0.5, 6, 0, 238)
    readyButton.Size = UDim2.fromOffset(68, 28)
    readyButton.BackgroundColor3 = Color3.fromRGB(49, 47, 58)
    readyButton.BorderSizePixel = 0
    readyButton.AutoButtonColor = true
    readyButton.Text = "READY"
    readyButton.TextColor3 = Color3.new(1, 1, 1)
    readyButton.Font = Enum.Font.GothamBold
    readyButton.TextSize = 9
    readyButton.Parent = previewCard
    local readyCorner = Instance.new("UICorner")
    readyCorner.CornerRadius = UDim.new(0, 4)
    readyCorner.Parent = readyButton

    local preview = {
        card = previewCard,
        viewport = viewport,
        camera = camera,
        world = worldModel,
        fill = nil,
        edges = {},
        model = nil,
        modelRoot = nil,
        modelRootLocal = nil,
        sourceHitboxLocal = CFrame.identity,
        modelRootPosition = Vector3.new(5.6, 2.5, 0),
        yaw = math.rad(90),
        zoom = 1,
        mode = "Normal",
        dragging = false,
        lastPointer = nil,
    }
    S.hitboxPreview = preview

    -- While the pointer is over this preview card, suspend the parent page's
    -- vertical ScrollingFrame so wheel input cannot move the surrounding menu.
    -- Restore the original setting as soon as the pointer leaves the whole card.
    local contentScrollFrame = S.contentFrame
    local originalContentScrollingEnabled = true
    if contentScrollFrame and contentScrollFrame:IsA("ScrollingFrame") then
        originalContentScrollingEnabled = contentScrollFrame.ScrollingEnabled
    end
    local function setPreviewHover(active)
        preview.hovering = active == true
        if contentScrollFrame and contentScrollFrame.Parent
            and contentScrollFrame:IsA("ScrollingFrame") then
            if preview.hovering then
                contentScrollFrame.ScrollingEnabled = false
            else
                contentScrollFrame.ScrollingEnabled = originalContentScrollingEnabled
            end
        end
    end
    preview.setHover = setPreviewHover
    previewCard.Active = true
    S.__helpers.connect(previewCard.MouseEnter, function()
        setPreviewHover(true)
    end)
    S.__helpers.connect(previewCard.MouseLeave, function()
        setPreviewHover(false)
    end)

    local function isPreviewBodyPart(part)
        if not part or not part:IsA("BasePart") then return false end
        local name = tostring(part.Name or ""):lower()
        if name == "humanoidrootpart" or name == "rootpart"
            or name:find("queryhitbox", 1, true)
            or name:find("collisionhitbox", 1, true)
            or name:find("hitbox", 1, true)
            or name:find("detector", 1, true) then
            return false
        end
        local visible = true
        pcall(function() visible = part.Transparency < 0.98 end)
        return visible
    end

    local function getRenderableBodyPartCount(model)
        if not model or not model:IsA("Model") then return 0 end
        local count = 0
        for _, descendant in ipairs(model:GetDescendants()) do
            if isPreviewBodyPart(descendant) then count += 1 end
        end
        return count
    end

    local function isKillerRigCandidate(model)
        if not model or not model:IsA("Model") then return false end
        local root = model:FindFirstChild("HumanoidRootPart", true)
            or model:FindFirstChild("RootPart", true)
            or model.PrimaryPart
            or model:FindFirstChildWhichIsA("BasePart", true)
        if not root then return false end
        local bodyCount = getRenderableBodyPartCount(model)
        local humanoid = model:FindFirstChildWhichIsA("Humanoid", true)
        -- A real rig has multiple visible body parts, or a Humanoid plus a
        -- single skinned MeshPart. This rejects empty folders and weapon models.
        return bodyCount >= 2 or (bodyCount >= 1 and humanoid ~= nil)
    end

    local function findModelWithRoot(container)
        if not container then return nil end
        if container:IsA("Model") and isKillerRigCandidate(container) then
            return container
        end
        for _, descendant in ipairs(container:GetDescendants()) do
            if descendant:IsA("Model") and isKillerRigCandidate(descendant) then
                return descendant
            end
        end
        return nil
    end

    local function getKillerPreviewSource()
        -- Prefer a real in-round Killer rig. Scan the folder directly as well
        -- as using the shared helper, because some rounds expose the rig before
        -- its Humanoid health state is initialized.
        local liveKiller = nil
        pcall(function()
            if type(S.getFirstValidKillerModel) == "function" then
                liveKiller = S.getFirstValidKillerModel()
            end
        end)
        if isKillerRigCandidate(liveKiller) then return liveKiller end

        local playersFolder = workspace:FindFirstChild("Players")
        local killerFolder = playersFolder and (playersFolder:FindFirstChild("Killers")
            or playersFolder:FindFirstChild("killers"))
        if killerFolder then
            for _, candidate in ipairs(killerFolder:GetChildren()) do
                if candidate:IsA("Model") and isKillerRigCandidate(candidate) then
                    return candidate
                end
            end
        end

        local assets = S.ReplicatedStorage and S.ReplicatedStorage:FindFirstChild("Assets")
        -- Match the game's preview-rig source used elsewhere in the project.
        -- Assets.Killers mostly contains Config/Behavior modules, so its nested
        -- models are only considered after the dedicated Instances dummy.
        local instances = assets and assets:FindFirstChild("Instances")
        local dummy = instances and instances:FindFirstChild("Dummy")
        local source = findModelWithRoot(dummy)
        if source then return source end

        local killerAssets = assets and assets:FindFirstChild("Killers")
        source = findModelWithRoot(killerAssets)
        if source then return source end

        local skins = assets and assets:FindFirstChild("Skins")
        local killerSkins = skins and skins:FindFirstChild("Killers")
        source = findModelWithRoot(killerSkins)
        if source then return source end
        return nil
    end

    local function cloneArchivableModel(sourceModel)
        if not isKillerRigCandidate(sourceModel) then return nil end
        local savedArchivable = {}
        pcall(function()
            savedArchivable[sourceModel] = sourceModel.Archivable
            sourceModel.Archivable = true
        end)
        for _, descendant in ipairs(sourceModel:GetDescendants()) do
            pcall(function()
                savedArchivable[descendant] = descendant.Archivable
                descendant.Archivable = true
            end)
        end
        local ok, clone = pcall(function() return sourceModel:Clone() end)
        for instance, original in pairs(savedArchivable) do
            pcall(function()
                if instance.Parent or instance == sourceModel then
                    instance.Archivable = original
                end
            end)
        end
        if not ok or not clone or not clone:IsA("Model") then return nil end

        for _, descendant in ipairs(clone:GetDescendants()) do
            if descendant:IsA("BaseScript") or descendant:IsA("ModuleScript")
                or descendant:IsA("Animator") or descendant:IsA("Sound")
                or descendant:IsA("ParticleEmitter") or descendant:IsA("Trail")
                or descendant:IsA("Beam") or descendant:IsA("Highlight")
                or descendant:IsA("BillboardGui") or descendant:IsA("SurfaceGui")
                or descendant:IsA("Fire") or descendant:IsA("Smoke")
                or descendant:IsA("Sparkles") then
                pcall(function() descendant:Destroy() end)
            elseif descendant:IsA("BasePart") then
                pcall(function()
                    descendant.Anchored = true
                    descendant.CanCollide = false
                    descendant.CanTouch = false
                    descendant.CanQuery = false
                    descendant.CastShadow = false
                    descendant.Massless = true
                    descendant.LocalTransparencyModifier = 0
                    if descendant.Name == "HumanoidRootPart" then
                        descendant.Transparency = 1
                    elseif descendant.Name:lower():find("queryhitbox", 1, true)
                        or descendant.Name:lower():find("collisionhitbox", 1, true)
                        or descendant.Name:lower():find("detector", 1, true) then
                        -- Keep QueryHitbox so the preview uses the same local
                        -- reference frame as detection, but never render it as a body part.
                        descendant.Transparency = 1
                    end
                end)
            elseif descendant:IsA("Humanoid") then
                pcall(function()
                    descendant.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                    descendant.RequiresNeck = false
                end)
            end
        end

        local root = clone:FindFirstChild("HumanoidRootPart", true)
            or clone:FindFirstChild("RootPart", true)
            or clone.PrimaryPart
            or clone:FindFirstChildWhichIsA("BasePart", true)
        if root then
            pcall(function() clone.PrimaryPart = root end)
            pcall(function() root.Anchored = true end)
        end
        if not isKillerRigCandidate(clone) then
            pcall(function() clone:Destroy() end)
            return nil
        end
        return clone
    end

    -- Bounds of visible rig geometry only. QueryHitbox/CollisionHitbox parts
    -- can be much larger than the character and must not shrink or hide the rig
    -- when selecting its preview scale/camera framing.
    local function getVisibleRigBounds(rig)
        if not rig then return nil, nil end
        local pivot = rig:GetPivot()
        local minimum = Vector3.new(math.huge, math.huge, math.huge)
        local maximum = Vector3.new(-math.huge, -math.huge, -math.huge)
        local found = false
        for _, part in ipairs(rig:GetDescendants()) do
            if isPreviewBodyPart(part) then
                local relative = pivot:ToObjectSpace(part.CFrame)
                local half = part.Size * 0.5
                for _, sx in ipairs({-1, 1}) do
                    for _, sy in ipairs({-1, 1}) do
                        for _, sz in ipairs({-1, 1}) do
                            local point = relative:PointToWorldSpace(Vector3.new(
                                half.X * sx, half.Y * sy, half.Z * sz
                            ))
                            minimum = Vector3.new(
                                math.min(minimum.X, point.X),
                                math.min(minimum.Y, point.Y),
                                math.min(minimum.Z, point.Z)
                            )
                            maximum = Vector3.new(
                                math.max(maximum.X, point.X),
                                math.max(maximum.Y, point.Y),
                                math.max(maximum.Z, point.Z)
                            )
                            found = true
                        end
                    end
                end
            end
        end
        if not found then return nil, nil end
        local center = (minimum + maximum) * 0.5
        return pivot * CFrame.new(center), maximum - minimum
    end

    local function createFallbackPreviewRig()
        local model = Instance.new("Model")
        model.Name = "HitboxPreviewKillerFallback"
        local function makePart(name, size, cf, color, transparency)
            local part = Instance.new("Part")
            part.Name = name
            part.Size = size
            part.CFrame = cf
            part.Color = color
            part.Material = Enum.Material.SmoothPlastic
            part.Transparency = transparency or 0
            part.Anchored = true
            part.CanCollide = false
            part.CanTouch = false
            part.CanQuery = false
            part.CastShadow = false
            part.Parent = model
            return part
        end
        local root = makePart("HumanoidRootPart", Vector3.new(2, 2, 1), CFrame.new(0, 2.5, 0), Color3.new(1, 1, 1), 1)
        makePart("Torso", Vector3.new(2, 2, 1), CFrame.new(0, 2.5, 0), Color3.fromRGB(145, 45, 45))
        makePart("Head", Vector3.new(1.15, 1.15, 1.15), CFrame.new(0, 4.15, 0), Color3.fromRGB(185, 185, 195))
        makePart("Left Arm", Vector3.new(0.8, 2, 0.8), CFrame.new(-1.4, 2.5, 0), Color3.fromRGB(165, 55, 45))
        makePart("Right Arm", Vector3.new(0.8, 2, 0.8), CFrame.new(1.4, 2.5, 0), Color3.fromRGB(165, 55, 45))
        makePart("Left Leg", Vector3.new(0.9, 1.8, 0.9), CFrame.new(-0.5, 0.7, 0), Color3.fromRGB(185, 155, 35))
        makePart("Right Leg", Vector3.new(0.9, 1.8, 0.9), CFrame.new(0.5, 0.7, 0), Color3.fromRGB(185, 155, 35))
        model.PrimaryPart = root
        return model
    end

    local sourceModel = getKillerPreviewSource()
    local previewModel = cloneArchivableModel(sourceModel)
    if not previewModel then
        -- Use the game's neutral dummy rig before the simple fallback. The
        -- source resolver already tries this path, but keep a second guarded
        -- attempt in case the asset tree finishes loading during initialization.
        local assets = S.ReplicatedStorage and S.ReplicatedStorage:FindFirstChild("Assets")
        local instances = assets and assets:FindFirstChild("Instances")
        previewModel = cloneArchivableModel(findModelWithRoot(instances and instances:FindFirstChild("Dummy")))
    end
    if not previewModel then previewModel = createFallbackPreviewRig() end
    previewModel.Name = "HitboxPreviewKiller"

    -- Scale from visible character geometry, not the usually oversized invisible
    -- QueryHitbox. This is the key to keeping the Killer model visible beside the box.
    local _, previewBodySize = getVisibleRigBounds(previewModel)
    pcall(function()
        if previewBodySize and previewBodySize.Y > 0.05
            and type(previewModel.ScaleTo) == "function" then
            local currentScale = previewModel:GetScale()
            local targetScale = currentScale * (PREVIEW_KILLER_HEIGHT / previewBodySize.Y)
            previewModel:ScaleTo(math.clamp(targetScale, currentScale * 0.1, currentScale * 10))
        end
    end)
    previewModel.Parent = worldModel

    for _, descendant in ipairs(previewModel:GetDescendants()) do
        if descendant:IsA("BasePart") then
            pcall(function()
                descendant.Anchored = true
                descendant.CanCollide = false
                descendant.CanTouch = false
                descendant.CanQuery = false
                descendant.CastShadow = false
                descendant.LocalTransparencyModifier = 0
            end)
        end
    end

    local modelRoot = previewModel:FindFirstChild("HumanoidRootPart", true)
        or previewModel:FindFirstChild("RootPart", true)
        or previewModel.PrimaryPart
        or previewModel:FindFirstChildWhichIsA("BasePart", true)
    if not modelRoot then
        pcall(function() previewModel:Destroy() end)
        previewModel = createFallbackPreviewRig()
        previewModel.Name = "HitboxPreviewKiller"
        previewModel.Parent = worldModel
        modelRoot = previewModel:FindFirstChild("HumanoidRootPart", true) or previewModel.PrimaryPart
    end
    preview.model = previewModel
    preview.modelRoot = modelRoot
    pcall(function()
        previewModel.PrimaryPart = modelRoot
        modelRoot.Anchored = true
        modelRoot.AssemblyLinearVelocity = Vector3.zero
        modelRoot.AssemblyAngularVelocity = Vector3.zero
    end)
    preview.modelRootLocal = previewModel:GetPivot():ToObjectSpace(modelRoot.CFrame)
    local previewSourceHitbox = previewModel:FindFirstChild("QueryHitbox", true)
    if previewSourceHitbox and previewSourceHitbox:IsA("BasePart") then
        preview.sourceHitboxLocal = modelRoot.CFrame:ToObjectSpace(previewSourceHitbox.CFrame)
    end
    local _, previewBodySizeAfterScale = getVisibleRigBounds(previewModel)
    preview.modelRootPosition = Vector3.new(5.6, math.max(1, (previewBodySizeAfterScale and previewBodySizeAfterScale.Y or PREVIEW_KILLER_HEIGHT) * 0.48), 0)
    preview.sourceName = sourceModel and tostring(sourceModel:GetAttribute("CharacterName") or sourceModel.Name) or "Dummy"
    local initialPlayersFolder = workspace:FindFirstChild("Players")
    local initialKillerFolder = initialPlayersFolder and (initialPlayersFolder:FindFirstChild("Killers")
        or initialPlayersFolder:FindFirstChild("killers"))
    preview.usingLiveKiller = sourceModel ~= nil and initialKillerFolder ~= nil
        and sourceModel:IsDescendantOf(initialKillerFolder)

    local fill = Instance.new("Part")
    fill.Name = "HitboxPreviewFill"
    fill.Shape = Enum.PartType.Block
    fill.Anchored = true
    fill.CanCollide = false
    fill.CanTouch = false
    fill.CanQuery = false
    fill.CastShadow = false
    fill.Material = S.HITBOX_PREDICTION_NORMAL_MATERIAL or Enum.Material.ForceField
    fill.Reflectance = 0
    fill.Parent = worldModel
    preview.fill = fill

    for index = 1, 12 do
        local edge = Instance.new("Part")
        edge.Name = "HitboxPreviewEdge"
        edge.Shape = Enum.PartType.Block
        edge.Anchored = true
        edge.CanCollide = false
        edge.CanTouch = false
        edge.CanQuery = false
        edge.CastShadow = false
        edge.Material = S.HITBOX_PREDICTION_OUTLINE_MATERIAL or Enum.Material.Neon
        edge.Reflectance = 0
        edge.Parent = worldModel
        preview.edges[index] = edge
    end

    local function getEdgeSpecs(size)
        local thickness = 0.035
        local specs = {}
        for _, ySign in ipairs({-1, 1}) do
            for _, zSign in ipairs({-1, 1}) do
                specs[#specs + 1] = {
                    size = Vector3.new(size.X, thickness, thickness),
                    offset = CFrame.new(0, ySign * size.Y / 2, zSign * size.Z / 2),
                }
            end
        end
        for _, xSign in ipairs({-1, 1}) do
            for _, zSign in ipairs({-1, 1}) do
                specs[#specs + 1] = {
                    size = Vector3.new(thickness, size.Y, thickness),
                    offset = CFrame.new(xSign * size.X / 2, 0, zSign * size.Z / 2),
                }
            end
        end
        for _, xSign in ipairs({-1, 1}) do
            for _, ySign in ipairs({-1, 1}) do
                specs[#specs + 1] = {
                    size = Vector3.new(thickness, thickness, size.Z),
                    offset = CFrame.new(xSign * size.X / 2, ySign * size.Y / 2, 0),
                }
            end
        end
        return specs
    end

    local function styleModeButton(button, selected, selectedColor)
        button.BackgroundColor3 = selected and selectedColor or Color3.fromRGB(49, 47, 58)
        button.TextColor3 = Color3.new(1, 1, 1)
    end

    S.__helpers.refreshHitboxPreview = function()
        if not preview.card or not preview.card.Parent
            or not preview.viewport or not preview.viewport.Parent
            or not preview.model or not preview.model.Parent then
            return
        end
        local isReady = preview.mode == "Ready"
        local color = isReady and S.HITBOX_PREDICTION_READY_COLOR or S.HITBOX_PREDICTION_ESP_COLOR
        if typeof(color) ~= "Color3" then
            color = isReady and Color3.fromRGB(0, 255, 90) or Color3.fromRGB(255, 255, 255)
        end
        local fillTransparency = S.__helpers.getHitboxPredictionTransparency(isReady, false)
        local edgeTransparency = S.__helpers.getHitboxPredictionTransparency(isReady, true)
        local multiplier = math.clamp(tonumber(S.autoBlockHitboxSizeMultiplier) or 1.0, 0.25, 3.0)
        local baseSize = S.HITBOX_PREDICTION_BASE_SIZE or (Vector3.new(5.2, 6, 5.65) * 2.2)
        local fallbackSize = baseSize * multiplier
        local distance = math.clamp(tonumber(S.autoBlockHitboxDistance) or 3.5, 0, 10)

        local rootCF = CFrame.new(preview.modelRootPosition) * CFrame.Angles(0, preview.yaw, 0)
        pcall(function()
            preview.model:PivotTo(rootCF * preview.modelRootLocal:Inverse())
        end)

        -- The preview rig is anchored, so the shared live geometry helper gives
        -- the exact QueryHitbox/root orientation, distance and size with zero
        -- velocity lead. Only use the local calculation as a compatibility fallback.
        local boxCF, boxSize
        local predictionOK, predictionCF, predictionSize = pcall(
            S.__helpers.getHitboxPredictionBox,
            preview.model
        )
        if predictionOK and predictionCF and predictionSize then
            boxCF, boxSize = predictionCF, predictionSize
        else
            local sourceCF = rootCF * (preview.sourceHitboxLocal or CFrame.identity)
            boxCF = CFrame.new(sourceCF.Position)
                * (sourceCF - sourceCF.Position) * CFrame.new(0, 0, -distance)
            boxSize = fallbackSize
        end

        fill.Size = boxSize
        fill.CFrame = boxCF
        fill.Color = color
        fill.Transparency = fillTransparency
        fill.Material = S.HITBOX_PREDICTION_NORMAL_MATERIAL or Enum.Material.ForceField
        fill.Shape = Enum.PartType.Block

        local specs = getEdgeSpecs(boxSize)
        for index, edge in ipairs(preview.edges) do
            local spec = specs[index]
            if spec then
                edge.Size = spec.size
                edge.CFrame = boxCF * spec.offset
                edge.Color = color
                edge.Transparency = edgeTransparency
                edge.Material = S.HITBOX_PREDICTION_OUTLINE_MATERIAL or Enum.Material.Neon
                edge.Shape = Enum.PartType.Block
            end
        end

        -- Align the visible Killer's feet with the bottom-most edge of the
        -- preview hitbox. The preview box is already calculated above, so this
        -- moves only the rendered character model; it does not alter the shared
        -- hitbox dimensions, origin, detection logic, or live prediction.
        local bodyCF, bodySize = getVisibleRigBounds(preview.model)
        if bodyCF and bodySize then
            local function getLowestWorldY(cf, size)
                local half = size * 0.5
                local verticalRadius = math.abs(cf.RightVector.Y) * half.X
                    + math.abs(cf.UpVector.Y) * half.Y
                    + math.abs(cf.LookVector.Y) * half.Z
                return cf.Position.Y - verticalRadius
            end
            local hitboxBottomY = getLowestWorldY(boxCF, boxSize)
            local bodyBottomY = getLowestWorldY(bodyCF, bodySize)
            local verticalOffset = hitboxBottomY - bodyBottomY
            if math.abs(verticalOffset) > 0.001 then
                local currentPivot = preview.model:GetPivot()
                preview.model:PivotTo(CFrame.new(0, verticalOffset, 0) * currentPivot)
                bodyCF, bodySize = getVisibleRigBounds(preview.model)
            end
        end

        -- Fit the full character AND all eight oriented hitbox corners in view.
        -- Using only the hitbox center can crop the Killer when QueryHitbox is offset.
        local boundsMin = Vector3.new(math.huge, math.huge, math.huge)
        local boundsMax = Vector3.new(-math.huge, -math.huge, -math.huge)
        local function includeBounds(cf, size)
            local half = size * 0.5
            for _, sx in ipairs({-1, 1}) do
                for _, sy in ipairs({-1, 1}) do
                    for _, sz in ipairs({-1, 1}) do
                        local point = cf:PointToWorldSpace(Vector3.new(half.X * sx, half.Y * sy, half.Z * sz))
                        boundsMin = Vector3.new(
                            math.min(boundsMin.X, point.X),
                            math.min(boundsMin.Y, point.Y),
                            math.min(boundsMin.Z, point.Z)
                        )
                        boundsMax = Vector3.new(
                            math.max(boundsMax.X, point.X),
                            math.max(boundsMax.Y, point.Y),
                            math.max(boundsMax.Z, point.Z)
                        )
                    end
                end
            end
        end
        if bodyCF and bodySize then includeBounds(bodyCF, bodySize) end
        includeBounds(boxCF, boxSize)
        local center = (boundsMin + boundsMax) * 0.5
        local extent = boundsMax - boundsMin
        camera.FieldOfView = 42
        local viewportSize = viewport.AbsoluteSize
        local aspect = (viewportSize.Y > 0) and (viewportSize.X / viewportSize.Y) or 1.2
        local fovY = math.rad(camera.FieldOfView)
        local fovX = 2 * math.atan(math.tan(fovY * 0.5) * math.max(0.5, aspect))
        local fitHeight = extent.Y / math.max(0.01, 2 * math.tan(fovY * 0.5))
        local fitWidth = extent.X / math.max(0.01, 2 * math.tan(fovX * 0.5))
        local fitDepth = extent.Z * 0.72
        local cameraDistance = math.max(fitHeight, fitWidth, fitDepth, 6) * 1.18 * preview.zoom
        local cameraDirection = Vector3.new(0.42, 0.28, 1).Unit
        camera.CFrame = CFrame.lookAt(center + cameraDirection * cameraDistance, center)

        previewTitle.Text = "HITBOX PREVIEW"
        previewHint.Text = "Drag to rotate  |  Scroll to zoom  |  " .. (isReady and "READY" or "NORMAL")
        styleModeButton(normalButton, not isReady, S.uiAccentColor or Color3.fromRGB(150, 120, 220))
        styleModeButton(readyButton, isReady, Color3.fromRGB(30, 135, 82))
    end

    local function setPreviewMode(mode)
        if mode ~= "Normal" and mode ~= "Ready" then return end
        preview.mode = mode
        pcall(S.__helpers.refreshHitboxPreview)
    end

    S.__helpers.connect(normalButton.Activated, function() setPreviewMode("Normal") end)
    S.__helpers.connect(readyButton.Activated, function() setPreviewMode("Ready") end)

    S.__helpers.connect(viewport.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            preview.dragging = true
            preview.lastPointer = input.Position
        end
    end)
    S.__helpers.connect(S.UserInputService.InputChanged, function(input)
        if input.UserInputType == Enum.UserInputType.MouseWheel then
            local mousePosition = S.UserInputService:GetMouseLocation()
            local viewportPosition = viewport.AbsolutePosition
            local viewportSize = viewport.AbsoluteSize
            local insideViewport = mousePosition.X >= viewportPosition.X
                and mousePosition.X <= viewportPosition.X + viewportSize.X
                and mousePosition.Y >= viewportPosition.Y
                and mousePosition.Y <= viewportPosition.Y + viewportSize.Y
            if insideViewport then
                preview.zoom = math.clamp(preview.zoom - input.Position.Z * 0.08, 0.65, 1.8)
                pcall(S.__helpers.refreshHitboxPreview)
            end
            return
        end
        if not preview.dragging or not preview.lastPointer then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            local current = input.Position
            local deltaX = current.X - preview.lastPointer.X
            preview.lastPointer = current
            if math.abs(deltaX) > 0 then
                preview.yaw = (preview.yaw + math.rad(deltaX * 0.55)) % (math.pi * 2)
                pcall(S.__helpers.refreshHitboxPreview)
            end
        end
    end)
    S.__helpers.connect(S.UserInputService.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            preview.dragging = false
            preview.lastPointer = nil
        end
    end)
    S.__helpers.cleanupHitboxPreview = function()
        preview.dragging = false
        preview.lastPointer = nil
        setPreviewHover(false)
        if preview.killerFolderConnection then
            pcall(function() preview.killerFolderConnection:Disconnect() end)
            preview.killerFolderConnection = nil
        end
        if preview.playersFolderConnection then
            pcall(function() preview.playersFolderConnection:Disconnect() end)
            preview.playersFolderConnection = nil
        end
        if preview.card and preview.card.Parent then
            pcall(function() preview.card:Destroy() end)
        end
        preview.model = nil
        preview.modelRoot = nil
        preview.fill = nil
        table.clear(preview.edges)
        S.hitboxPreview = nil
        S.hitboxPreviewCard = nil
    end

    S.__helpers.connect(viewport:GetPropertyChangedSignal("AbsoluteSize"), function()
        pcall(S.__helpers.refreshHitboxPreview)
    end)
    S.__helpers.refreshHitboxPreview()

    -- If the script is loaded in the lobby, the preview starts from the game's
    -- Dummy rig. Once a real Killer appears, take one static snapshot of that
    -- model (no position/velocity tracking) and replace the dummy preview.
    local function tryUseSpawnedKiller(killerModel)
        if not killerModel or not killerModel.Parent or not killerModel:IsA("Model") then return end
        if preview.usingLiveKiller then return end
        task.delay(0.45, function()
            if not preview.card or not preview.card.Parent or preview.usingLiveKiller then return end
            if not isKillerRigCandidate(killerModel) then return end
            local replacement = cloneArchivableModel(killerModel)
            if not replacement then return end
            replacement.Name = "HitboxPreviewKiller"
            local _, bodySize = getVisibleRigBounds(replacement)
            pcall(function()
                if bodySize and bodySize.Y > 0.05 and type(replacement.ScaleTo) == "function" then
                    local currentScale = replacement:GetScale()
                    local targetScale = currentScale * (PREVIEW_KILLER_HEIGHT / bodySize.Y)
                    replacement:ScaleTo(math.clamp(targetScale, currentScale * 0.1, currentScale * 10))
                end
            end)
            for _, descendant in ipairs(replacement:GetDescendants()) do
                if descendant:IsA("BasePart") then
                    pcall(function()
                        descendant.Anchored = true
                        descendant.CanCollide = false
                        descendant.CanTouch = false
                        descendant.CanQuery = false
                        descendant.CastShadow = false
                        descendant.LocalTransparencyModifier = 0
                    end)
                end
            end
            local newRoot = replacement:FindFirstChild("HumanoidRootPart", true)
                or replacement:FindFirstChild("RootPart", true)
                or replacement.PrimaryPart
                or replacement:FindFirstChildWhichIsA("BasePart", true)
            if not newRoot then
                pcall(function() replacement:Destroy() end)
                return
            end
            pcall(function() replacement.PrimaryPart = newRoot end)
            local oldModel = preview.model
            replacement.Parent = worldModel
            preview.model = replacement
            preview.modelRoot = newRoot
            preview.modelRootLocal = replacement:GetPivot():ToObjectSpace(newRoot.CFrame)
            preview.sourceHitboxLocal = CFrame.identity
            local newHitbox = replacement:FindFirstChild("QueryHitbox", true)
            if newHitbox and newHitbox:IsA("BasePart") then
                preview.sourceHitboxLocal = newRoot.CFrame:ToObjectSpace(newHitbox.CFrame)
            end
            local _, newBodySize = getVisibleRigBounds(replacement)
            preview.modelRootPosition = Vector3.new(5.6, math.max(1, (newBodySize and newBodySize.Y or PREVIEW_KILLER_HEIGHT) * 0.48), 0)
            preview.sourceName = tostring(killerModel:GetAttribute("CharacterName") or killerModel.Name)
            preview.usingLiveKiller = true
            if oldModel and oldModel ~= replacement then
                pcall(function() oldModel:Destroy() end)
            end
            pcall(S.__helpers.refreshHitboxPreview)
        end)
    end

    local function bindKillerFolder(killerFolder)
        if not killerFolder or preview.killerFolder == killerFolder then return end
        if preview.killerFolderConnection then
            pcall(function() preview.killerFolderConnection:Disconnect() end)
            preview.killerFolderConnection = nil
        end
        preview.killerFolder = killerFolder
        preview.killerFolderConnection = killerFolder.ChildAdded:Connect(function(child)
            if child:IsA("Model") then tryUseSpawnedKiller(child) end
        end)
        -- Catch a Killer that was inserted just before the folder connection.
        for _, child in ipairs(killerFolder:GetChildren()) do
            if child:IsA("Model") and not preview.usingLiveKiller then
                tryUseSpawnedKiller(child)
            end
        end
    end

    local function bindKillerPreviewFolder(playersFolder)
        if not playersFolder then return end
        local killerFolder = playersFolder:FindFirstChild("Killers") or playersFolder:FindFirstChild("killers")
        if killerFolder then bindKillerFolder(killerFolder) end
        if not preview.playersFolderConnection then
            preview.playersFolderConnection = playersFolder.ChildAdded:Connect(function(child)
                if child.Name == "Killers" or child.Name == "killers" then
                    bindKillerFolder(child)
                end
            end)
        end
    end

    if initialPlayersFolder then bindKillerPreviewFolder(initialPlayersFolder) end
    S.__helpers.connect(workspace.ChildAdded, function(child)
        if child.Name == "Players" then
            task.defer(function() bindKillerPreviewFolder(child) end)
        end
    end)
end
