-- PART 7: AUTO BACKSTAB / DASHSTAB EXECUTOR & FIXED NETWORK TRAFFIC HOOKING
-- ================================================================
S.__helpers.runAutoStabSequence = function()
    if not S.__helpers.isLocalRole("Survivor")
        or not S.isAutoStabEnabled or S.running then return end
    S.running = true

    local character = S.__helpers.getCharacter()
    task.wait(S.autoStabStartDelay)
    local hrp = character and character:FindFirstChild("HumanoidRootPart")
    if not S.__helpers.isLocalRole("Survivor")
        or not character or not character.Parent or not hrp then
        S.running = false
        return
    end

    local place = Instance.new("Part")
    place.Name = "place"
    place.Size = Vector3.new(2, 2, 2)
    place.Transparency = 1
    place.CanCollide = false
    place.Anchored = true
    place.Parent = character

    local originalPrimaryPart = character.PrimaryPart
    local oldSpeed = 16
    pcall(function() oldSpeed = S.speed.Value end)

    if S.moredirectenabled then
        S.moredirectrn = true
        task.wait(0.01)
        S.moredirectrn = false
    end

    local startTime = os.clock()
    while os.clock() - startTime < S.duration do
        if not S.__helpers.isLocalRole("Survivor")
            or not character.Parent or not place.Parent or not S.isAutoStabEnabled then break end
        pcall(function() S.speed.Value = 0 end)
        S.doitmate = true
        S.RunService.PreRender:Wait()
    end

    pcall(function() S.speed.Value = oldSpeed end)
    S.doitmate = false

    if S.moredirectenabled then
        S.moredirectrn = true
        task.wait(0.01)
        S.moredirectend = true
        S.moredirectrn = false
        task.wait(0.01)
        S.moredirectend = false
    end

    if place and place.Parent then place:Destroy() end
    if character and character.Parent then character.PrimaryPart = originalPrimaryPart end
    S.running = false
end

S.__helpers.runDashstabSequence = function()
    if not S.__helpers.isLocalRole("Survivor")
        or not S.isDashstabEnabled or S.running then
        return
    end

    S.running = true

    local character = S.__helpers.getCharacter()

    task.wait(S.dsStartDelay)

    local hrp = character and character:FindFirstChild("HumanoidRootPart")

    if not S.__helpers.isLocalRole("Survivor")
        or not character or not character.Parent or not hrp then
        S.running = false
        return
    end

    local place = Instance.new("Part")
    place.Name = "place"
    place.Size = Vector3.new(2, 2, 2)
    place.Transparency = 0
    place.CanCollide = false
    place.Anchored = true
    place.Parent = character

    local originalPrimaryPart = character.PrimaryPart

    local oldspeed = 16

    pcall(function()
        oldspeed = S.speed.Value
    end)

    if S.moredirectenabled then
        S.moredirectrn = true
        task.wait(0.01)
        S.moredirectrn = false
    end

    local startTime = os.clock()

    while os.clock() - startTime < S.duration do
        if not S.__helpers.isLocalRole("Survivor")
            or not character.Parent
            or not place.Parent
            or not S.isDashstabEnabled then
            break
        end

        pcall(function()
            S.speed.Value = 0
        end)

        S.doitmate = true
        S.RunService.PreRender:Wait()
    end

    pcall(function()
        S.speed.Value = oldspeed
    end)

    S.doitmate = false

    if S.moredirectenabled then
        S.moredirectrn = true
        task.wait(0.001)

        S.moredirectend = true
        S.moredirectrn = false

        task.wait(0.001)
        S.moredirectend = false
    end

    if place and place.Parent then
        place:Destroy()
    end

    if character and character.Parent then
        character.PrimaryPart = originalPrimaryPart
    end

    S.running = false
end

