S.oldFireServerConnection = nil
if S.NetworkModule and type(S.NetworkModule.FireServerConnection) == "function" then
    task.defer(function()
        if S.deviceSpoofEnabled then
            pcall(function()
                S.NetworkModule:FireServerConnection("SetDevice", "REMOTE_EVENT", S.deviceSpoofCurrent or S.initialDetectedDevice or "PC")
            end)
        end
    end)
end

if S.NetworkModule
    and type(hookfunction) == "function"
    and type(S.NetworkModule.FireServerConnection) == "function" then

S.oldFireServerConnection = hookfunction(
    S.NetworkModule.FireServerConnection,
    function(self, connectionName, eventType, ...)
        local args = {...}
        if S.__helpers.handleE1LU4SAKENAimAbility then
            pcall(S.__helpers.handleE1LU4SAKENAimAbility, connectionName, eventType, args[1])
        end
        if connectionName == "SetDevice" and S.deviceSpoofEnabled then
            args[1] = S.deviceSpoofCurrent or S.initialDetectedDevice or "PC"
        end
        if S.lp and connectionName == (S.lp.Name .. "DusekkarCancel")
            and S.DusekkarProtection
            and (S.DusekkarProtection.antiBreak or S.DusekkarProtection.throughWalls) then
            return nil
        end
        if S.lp and connectionName == (S.lp.Name .. "Guest1337Collision")
            and S.Guest1337Extras and S.Guest1337Extras.chargeAntiCrash then
            return nil
        end
        local veeronicaCharacter = S.lp and S.lp.Character
        if S.isVeeronicaCollisionDamageDisabled
            and type(connectionName) == "string"
            and connectionName:find("StopSkate", 1, true)
            and veeronicaCharacter and veeronicaCharacter.Name == "Veeronica"
            and S.__helpers.isLocalRole("Survivor") then
            return S.oldFireServerConnection(self, connectionName, eventType, "Manual")
        end
        if connectionName == "UseActorAbility" and args[1] == "Punch"
            and S.Guest1337Extras and S.Guest1337Extras.superPunch
            and S.__helpers.isLocalGuest1337() then
            task.delay(0.62, function()
                local character = S.lp and S.lp.Character
                local root = character and character:FindFirstChild("HumanoidRootPart")
                local attachment = root and (root:FindFirstChild("RootAttachment") or root:FindFirstChildWhichIsA("Attachment"))
                if not root or not attachment then return end
                local boost = Instance.new("LinearVelocity")
                boost.Name = "Guest1337SuperPunchBoost"
                boost.Attachment0 = attachment
                boost.RelativeTo = Enum.ActuatorRelativeTo.World
                boost.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
                boost.PrimaryTangentAxis = Vector3.xAxis
                boost.SecondaryTangentAxis = Vector3.zAxis
                boost.MaxForce = math.huge
                local power = S.Guest1337Extras.superPunchPower * 5
                local look = root.CFrame.LookVector
                boost.PlaneVelocity = Vector2.new(look.X * power, look.Z * power)
                boost.Parent = root
                local startTime = tick()
                local connection
                connection = S.RunService.Heartbeat:Connect(function()
                    if not boost.Parent or tick() - startTime > 0.22 then
                        if connection then connection:Disconnect() end
                        pcall(function() boost:Destroy() end)
                        return
                    end
                    local direction = root.CFrame.LookVector
                    boost.PlaneVelocity = Vector2.new(direction.X * power, direction.Z * power)
                end)
            end)
        end
        if S.lp and connectionName == (S.lp.Name .. "666Crashed") and S.SixerPursuit then
            if S.SixerPursuit.antiCrash and S.SixerPursuit.startedAt > 0 then
                local duration = 2.5
                pcall(function()
                    local assets = S.ReplicatedStorage:FindFirstChild("Assets")
                    local killers = assets and assets:FindFirstChild("Killers")
                    local sixer = killers and killers:FindFirstChild("Sixer")
                    local configModule = sixer and sixer:FindFirstChild("Config")
                    local config = configModule and require(configModule)
                    duration = tonumber(config and config.PursuitLength) or duration
                end)
                while tick() - S.SixerPursuit.startedAt < duration do task.wait() end
            end
            if S.SixerPursuit.infiniteTrail then
                pcall(function() S.RunService:UnbindFromRenderStep("666PursuitCharge") end)
                return nil
            end
        end
        if S.lp and connectionName == (S.lp.Name .. "NosAirDiveLand")
            and S.NosferatuInfiniteHitboxTrailEnabled then
            -- E1LU4SAKEN cancels the landing event to preserve the airborne hitbox trail.
            return nil
        end
        if connectionName == "UpdateCharacterPosition" then
            local character = S.lp.Character
            local hrp = character and character:FindFirstChild("HumanoidRootPart")
            local killerModel = S.getFirstValidKillerModel()

            if killerModel then
                local killerHrp = killerModel:FindFirstChild("HumanoidRootPart")

                if killerHrp and hrp then
                    local targetCFrame =
                        killerHrp.CFrame * CFrame.new(0, 0, S.behindstuds)

                    local targetdirect =
                        hrp.CFrame * CFrame.new(0, -90000, 0)

                    local targetdirectend =
                        hrp.CFrame * CFrame.new(0, 0, 0)

                    local CharacterReplication = require(
                        game.ReplicatedStorage
                            :WaitForChild("Systems")
                            :WaitForChild("Player")
                            :WaitForChild("Game")
                            :WaitForChild("CharacterReplication")
                    )

                    if S.moredirectrn then
                        args[1] = CharacterReplication.Serialize(
                            targetdirect,
                            hrp.AssemblyLinearVelocity
                        )
                    elseif S.moredirectend then
                        args[1] = CharacterReplication.Serialize(
                            targetdirectend,
                            hrp.AssemblyLinearVelocity
                        )
                    elseif S.isAntiBaitEnabled and S.antiBaitActive then
                        -- File 2 Anti Bait: smoothly redirect only the outgoing
                        -- UpdateCharacterPosition payload during the short window
                        -- after Auto Block successfully fires; the local root is untouched.
                        local antiBaitTarget = killerHrp.CFrame
                            * CFrame.new(0, 0, tonumber(S.antiBaitBehindStuds) or 4)
                        local antiBaitStep = hrp.CFrame:Lerp(
                            antiBaitTarget,
                            math.clamp((tonumber(S.antiBaitSpeed) or 55) / 60, 0, 1)
                        )
                        args[1] = CharacterReplication.Serialize(
                            antiBaitStep,
                            hrp.AssemblyLinearVelocity
                        )
                    elseif S.doitmate then
                        args[1] = CharacterReplication.Serialize(
                            targetCFrame,
                            hrp.AssemblyLinearVelocity
                        )
                    end
                end
            end
        end

        return S.oldFireServerConnection(
            self,
            connectionName,
            eventType,
            unpack(args)
        )
    end
)

end

