S.__helpers.createStaminaBarUI = function()
    local state = S.StaminaBarUI
    if state.root and state.root.Parent then return state end
    if not S.screenGui or not S.screenGui.Parent then return nil end

    local valueLabel = Instance.new("TextLabel")
    valueLabel.Name = "E1LU4HUB_CenterStaminaNumber"
    valueLabel.AnchorPoint = Vector2.new(0.5, 0.5)
    valueLabel.Position = UDim2.new(0.5, 0, 0.41, 0)
    valueLabel.Size = UDim2.new(0, 72, 0, 28)
    valueLabel.BackgroundTransparency = 1
    valueLabel.BorderSizePixel = 0
    valueLabel.Text = "--"
    valueLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    valueLabel.TextSize = 15
    valueLabel.Font = Enum.Font.GothamBold
    valueLabel.TextXAlignment = Enum.TextXAlignment.Center
    valueLabel.TextYAlignment = Enum.TextYAlignment.Center
    valueLabel.TextStrokeColor3 = Color3.fromRGB(25, 22, 19)
    valueLabel.TextStrokeTransparency = 0.18
    valueLabel.ZIndex = 80
    valueLabel.Visible = false
    valueLabel.Parent = S.screenGui

    state.root = valueLabel
    state.valueLabel = valueLabel
    return state
end

S.__helpers.updateStaminaBar = function()
    local state = S.StaminaBarUI
    if not state or not state.root or not state.root.Parent then
        state = S.__helpers.createStaminaBarUI()
    end
    if not state or not state.root or not state.valueLabel then return end

    if S.isStaminaNumberEnabled ~= true then
        state.root.Visible = false
        return
    end

    local character = S.lp and S.lp.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local module = S.SprintingModule
    local stamina = module and tonumber(module.Stamina)
    local maxStamina = module and tonumber(module.MaxStamina)
    local inactive = S.__helpers.isStaminaCharacterInactive and S.__helpers.isStaminaCharacterInactive()
    if not character or not humanoid or humanoid.Health <= 0 or inactive
        or stamina == nil or maxStamina == nil or maxStamina <= 0 then
        state.root.Visible = false
        return
    end

    state.root.Visible = true
    local digits = tostring(math.floor(stamina + 0.5))
    local spacedDigits = {}
    for digit in digits:gmatch("%d") do table.insert(spacedDigits, digit) end
    state.valueLabel.Text = table.concat(spacedDigits, " ")
    if stamina <= 26 then
        state.valueLabel.TextColor3 = Color3.fromRGB(255, 65, 65)
    elseif stamina <= 49 then
        state.valueLabel.TextColor3 = Color3.fromRGB(255, 220, 70)
    else
        state.valueLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    end
end
S.__helpers.createStaminaBarUI()

