S.smoothedSpeed = 0
S.staminaAccumulator = 0
S.autoStudsAccumulator = 0
S.pingAccumulator = 1
S.cachedPing = 20

S.__helpers.connect(S.RunService.Heartbeat, function(dt)
    S.staminaAccumulator += dt
    S.autoStudsAccumulator += dt

    -- Run every Heartbeat so stamina is clamped to 1 before it can empty.
    if S.__helpers.updateLegitInfStamina then
        pcall(S.__helpers.updateLegitInfStamina)
    end

    if S.staminaAccumulator >= 0.1 then
        local staminaSampleDt = S.staminaAccumulator
        S.staminaAccumulator = 0

        -- Enforce the configured Sprint Speed only while the toggle is ON.
        -- OFF is handled once by the toggle callback, not continuously here.
        local sprintModule = S.SprintingModule
        if sprintModule and S.isSprintSpeedEnabled == true then
            local targetSprintSpeed = tonumber(S.currentSprintSpeed) or 26
            if sprintModule.SprintSpeed ~= targetSprintSpeed then
                sprintModule.SprintSpeed = targetSprintSpeed
            end
        end

        -- Match the second supplied file's negative-stamina simulation when Min Stamina is below zero.
        local staminaModule = S.SprintingModule
        if S.__helpers.isStaminaCharacterInactive() or S.isInfStaminaEnabled
            or not S.isMinStaminaEnabled or (tonumber(S.currentMinStamina) or 0) >= 0 then
            S.staminaManualValue = nil
        elseif staminaModule and staminaModule.DefaultsSet and type(staminaModule.Stamina) == "number" then
            local currentStamina = staminaModule.Stamina
            if currentStamina > 0 then
                S.staminaManualValue = currentStamina
            else
                local character = S.lp.Character
                local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                local simulatedStamina = tonumber(S.staminaManualValue) or 0
                if simulatedStamina > 0 then simulatedStamina = 0 end
                local activeLoss = tonumber(staminaModule.StaminaLoss) or (tonumber(S.currentStaminaLoss) or 10)
                local activeGain = tonumber(staminaModule.StaminaGain) or (tonumber(S.currentStaminaGain) or 20)
                local activeMax = tonumber(staminaModule.MaxStamina) or (tonumber(S.currentMaxStamina) or 100)
                if humanoid and humanoid.MoveDirection.Magnitude > 0.05 then
                    simulatedStamina -= activeLoss * staminaSampleDt
                else
                    simulatedStamina += activeGain * staminaSampleDt
                end
                simulatedStamina = math.clamp(
                    simulatedStamina,
                    tonumber(S.currentMinStamina) or 0,
                    activeMax
                )
                S.staminaManualValue = simulatedStamina
                staminaModule.Stamina = simulatedStamina
                if staminaModule.__staminaChangedEvent then
                    pcall(function() staminaModule.__staminaChangedEvent:Fire(simulatedStamina) end)
                end
            end
        end

        -- Keep the original stamina preset behavior alongside the replacement settings system.
        local preset = S.staminaPreset or "Original"
        if S.isStaminaPresetEnabled == true and preset ~= "Original" then
            pcall(function()
                local module = S.SprintingModule
                local maxStamina = tonumber(module.MaxStamina)
                local stamina = tonumber(module.Stamina)
                if maxStamina and maxStamina > 0 and stamina then
                    if preset == "Infinite" then
                        rawset(module, "Stamina", maxStamina)
                    elseif stamina < maxStamina * 0.8 then
                        local fraction = preset == "Semi-Realistic" and 0.005 or 0.0025
                        rawset(module, "Stamina", math.min(stamina + maxStamina * fraction, maxStamina))
                    end
                end
            end)
        end
        if S.__helpers.updateStaminaPresetUI then
            pcall(S.__helpers.updateStaminaPresetUI)
        end
        if S.__helpers.updateStaminaBar then
            pcall(S.__helpers.updateStaminaBar)
        end
    end

    if S.autoStudsAccumulator < 0.033 then
        return
    end

    if not S.__helpers.isLocalRole("Survivor") then
        S.autoStudsAccumulator = 0
        S.pingAccumulator = 0
        S.cachedPing = 20
        S.lastKillerModel = nil
        S.smoothedSpeed = 0
        return
    end

    local sampleDt = S.autoStudsAccumulator
    S.autoStudsAccumulator = 0

    if S.isDetectPingEnabled then
        S.pingAccumulator += sampleDt
        if S.pingAccumulator >= 0.5 then
            S.pingAccumulator = 0
            S.cachedPing = S.__helpers.getPing()
        end
    else
        S.pingAccumulator = 0
        S.cachedPing = 20
    end

    if not S.isAutoStudsEnabled then
        S.lastKillerModel = nil
        S.smoothedSpeed = 0
        return
    end

    local killerModel = S.getFirstValidKillerModel()
    if not killerModel then
        S.lastKillerModel = nil
        S.smoothedSpeed = 0
        return
    end

    local killerHrp = killerModel:FindFirstChild("HumanoidRootPart")
    if not killerHrp then
        S.lastKillerModel = nil
        return
    end

    local currentPos = killerHrp.Position
    local rawSpeed = 0

    if S.lastKillerModel == killerModel and S.lastKillerPos then
        local dx = currentPos.X - S.lastKillerPos.X
        local dz = currentPos.Z - S.lastKillerPos.Z
        rawSpeed = math.sqrt(dx * dx + dz * dz) / math.max(sampleDt, 1 / 240)
    end

    S.lastKillerModel = killerModel
    S.lastKillerPos = currentPos

    S.smoothedSpeed += (rawSpeed - S.smoothedSpeed) * math.min(sampleDt * 15, 1)

    local finalSpeed = math.clamp(S.smoothedSpeed, 0, 30)
    local studsAtRun = S.autoRunStuds

    if S.isDetectPingEnabled then
        local ping = S.cachedPing
        studsAtRun = math.max(
            S.autoRunStuds - ((math.max(ping, 20) - 20) / 100) * 1.5,
            1.0
        )
    end

    S.behindstuds = S.autoStandStuds
        - finalSpeed * ((S.autoStandStuds - studsAtRun) / 26.0)

    if S.behindStudsBox and not S.behindStudsBox:IsFocused() then
        S.behindStudsBox.Text = string.format("%.1f", S.behindstuds)
    end
end)

S.__helpers.hookCharacter = function(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 5))
    if not animator then return end
    S.__helpers.connect(animator.AnimationPlayed, function(track)
        if not track or not track.Animation then return end
        local animationId = tostring(track.Animation.AnimationId or ""):gsub("%D", "")
        if not S.getFirstValidKillerModel() then
            return
        end

        -- Auto Backstab follows file 2's Auto Studs-linked path:
        -- detect the Two Time stab animation, then let runAutoStabSequence
        -- redirect the outgoing character position using the live behindstuds value.
        if S.__helpers.isLocalRole("Survivor") and (
            animationId == S.AUTO_STAB_ANIM_ID
            or animationId == "106086955212611"
        ) and S.isAutoStabEnabled then
            task.spawn(S.__helpers.runAutoStabSequence)
        elseif S.__helpers.isLocalRole("Survivor") and (
            animationId == S.DASHSTAB_ANIM_ID
            or animationId == "107640065977686"
        ) and S.isDashstabEnabled then
            task.spawn(S.__helpers.runDashstabSequence)
        end
    end)
end

if S.lp.Character then
    S.__helpers.hookCharacter(S.lp.Character)
end
S.__helpers.connect(S.lp.CharacterAdded, S.__helpers.hookCharacter)

-- Ensure E1LU4HUB_v1 title is white on initial load
if S.titleLabel then
    S.titleLabel.TextColor3 = Color3.new(1, 1, 1)
end

-- ================================================================
-- This integrated file uses ELSEGUI's own UI and does not need Rayfield notifications.
-- If the executor exposes a global Rayfield object, silence its Notify method.
pcall(function()
    if typeof(Rayfield) == "table" and type(Rayfield.Notify) == "function" then
        Rayfield.Notify = function() end
    end
end)

-- ================================================================
-- SKIN CHANGER
-- Adds the requested cosmetic variants to the existing dropdown popup.
-- Remote source scripts are only requested when their option is selected.
-- ================================================================
S.SkinChanger = S.SkinChanger or {
    active = nil,
    respawnConnection = nil,
    morphConnections = {},
    snapshots = setmetatable({}, {__mode = "k"}),
    configOriginals = {},
}
S.SkinChanger = S.SkinChanger
S.SkinChanger.iconOriginals = S.SkinChanger.iconOriginals or setmetatable({}, {__mode = "k"})
S.SkinChanger.enabled = S.SkinChanger.enabled == true
S.SkinChanger.selectedByCharacter = S.SkinChanger.selectedByCharacter or {}
-- C00lkidd / Tenna are intentionally not supported by Skin Changer.
for selectedCharacter, selectedSkin in pairs(S.SkinChanger.selectedByCharacter) do
    if tostring(selectedCharacter):lower() == "c00lkidd"
        or tostring(selectedSkin):lower() == "tenna" then
        S.SkinChanger.selectedByCharacter[selectedCharacter] = nil
    end
end
S.SkinChanger.activeCharacter = S.SkinChanger.activeCharacter

S.__helpers.skinDeepCopy = function(value, seen)
    if type(value) ~= "table" then
        return value
    end
    seen = seen or {}
    if seen[value] then
        return seen[value]
    end
    local copy = {}
    seen[value] = copy
    for key, child in pairs(value) do
        copy[S.__helpers.skinDeepCopy(key, seen)] = S.__helpers.skinDeepCopy(child, seen)
    end
    return copy
end

S.SkinChanger.trackConnection = function(connection)
    if connection then
        table.insert(S.SkinChanger.morphConnections, connection)
    end
    return connection
end

S.SkinChanger.clearMorphConnections = function()
    for _, connection in ipairs(S.SkinChanger.morphConnections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(S.SkinChanger.morphConnections)
end

S.SkinChanger.rememberAndSet = function(target, property, value)
    if not target then return end
    local values = S.SkinChanger.configOriginals[target]
    if not values then
        values = {}
        S.SkinChanger.configOriginals[target] = values
    end
    if values[property] == nil then
        values[property] = {
            wasNil = target[property] == nil,
            value = S.__helpers.skinDeepCopy(target[property]),
        }
    end
    target[property] = S.__helpers.skinDeepCopy(value)
end

S.SkinChanger.restoreConfig = function()
    for target, values in pairs(S.SkinChanger.configOriginals) do
        for property, saved in pairs(values) do
            pcall(function()
                target[property] = saved.wasNil and nil or S.__helpers.skinDeepCopy(saved.value)
            end)
        end
    end

    table.clear(S.SkinChanger.configOriginals)
end

S.SkinChanger.captureCharacter = function(character)
    if not character or S.SkinChanger.snapshots[character] then
        return S.SkinChanger.snapshots[character]
    end

    local snapshot = {parts = {}, transparency = {}, children = {}, clothing = {}, meshes = {}, joints = {}, destroyedBackups = {}}
    for _, child in ipairs(character:GetChildren()) do
        snapshot.children[child] = true
        if child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            local okClone, clone = pcall(function() return child:Clone() end)
            if okClone and clone then
                table.insert(snapshot.clothing, {original = child, backup = clone})
            end
        end
    end
    for _, object in ipairs(character:GetDescendants()) do
        if object:IsA("BasePart") then
            snapshot.parts[object] = {
                Transparency = object.Transparency,
                Color = object.Color,
                BrickColor = object.BrickColor,
                CanCollide = object.CanCollide,
                CanTouch = object.CanTouch,
                CanQuery = object.CanQuery,
                LocalTransparencyModifier = object.LocalTransparencyModifier,
                Size = object.Size,
                Material = object.Material,
                Reflectance = object.Reflectance,
                isMeshPart = object:IsA("MeshPart"),
                MeshId = object:IsA("MeshPart") and object.MeshId or nil,
                TextureID = object:IsA("MeshPart") and object.TextureID or nil,
            }
        elseif object:IsA("SpecialMesh") or object:IsA("DataModelMesh") then
            snapshot.meshes[object] = {
                MeshId = object.MeshId,
                TextureId = object.TextureId,
                Scale = object.Scale,
                Offset = object.Offset,
                VertexColor = object.VertexColor,
            }
        elseif object:IsA("JointInstance") then
            snapshot.joints[object] = {C0 = object.C0, C1 = object.C1, Part0 = object.Part0, Part1 = object.Part1}
        elseif object:IsA("Decal") or object:IsA("Texture") then
            snapshot.transparency[object] = object.Transparency
        end
    end
    S.SkinChanger.snapshots[character] = snapshot
    return snapshot
end

S.SkinChanger.destroyPreserving = function(object, character)
    if not object or not object.Parent then return end
    local isArtifact = false
    pcall(function() isArtifact = object:GetAttribute("E1LU4HUBSkinChangerArtifact") == true
        or object:GetAttribute("OWERE1LU4SkinChangerArtifact") == true end)
    if isArtifact then object:Destroy(); return end
    character = character or (S.lp and S.lp.Character)
    local snapshot = character and S.SkinChanger.captureCharacter(character)
    if snapshot then
        snapshot.destroyedBackups = snapshot.destroyedBackups or {}
        for _, item in ipairs(snapshot.destroyedBackups) do
            if item.original == object then
                object.Parent = nil
                return
            end
        end
        -- Detach the real instance instead of destroying it. This preserves
        -- scripts, attachments, and instance identity for a clean reset.
        table.insert(snapshot.destroyedBackups, {original = object, parent = object.Parent})
        object.Parent = nil
        return
    end
    object:Destroy()
end

S.SkinChanger.tagArtifact = function(object)
    if object then
        pcall(function() object:SetAttribute("E1LU4HUBSkinChangerArtifact", true) end)
    end
    return object
end

S.SkinChanger.hideObject = function(object)
    if not object then return end
    local function hide(item)
        if item:IsA("BasePart") then
            item.Transparency = 1
            item.CanCollide = false
            item.CanTouch = false
            item.CanQuery = false
        elseif item:IsA("Decal") or item:IsA("Texture") then
            item.Transparency = 1
        end
    end
    pcall(hide, object)
    for _, descendant in ipairs(object:GetDescendants()) do
        pcall(hide, descendant)
    end
end

S.SkinChanger.restoreCharacter = function(character)
    if not character then return end
    local snapshot = S.SkinChanger.snapshots[character]

    -- Remove only skin elements created by this dropdown or the Artist script.
    for _, object in ipairs(character:GetDescendants()) do
        local remove = false
        pcall(function()
            remove = object:GetAttribute("E1LU4HUBSkinChangerArtifact") == true
                or object:GetAttribute("OWERE1LU4SkinChangerArtifact") == true
                or object:GetAttribute("E1LU4HUBTwoTimeSkinArtifact") == true
                or (object:IsA("Accessory") and (object.Name == "CustomHat" or object.Name == "CustomTorso"))
        end)
        if remove and object.Parent then
            pcall(function() object:Destroy() end)
        end
    end
    for _, child in ipairs(character:GetChildren()) do
        local remove = false
        pcall(function()
            remove = child:GetAttribute("E1LU4HUBSkinChangerArtifact") == true
                or child:GetAttribute("OWERE1LU4SkinChangerArtifact") == true
                or child:GetAttribute("E1LU4HUBTwoTimeSkinArtifact") == true
                or (child:IsA("Accessory") and (child.Name == "CustomHat" or child.Name == "CustomTorso"))
        end)
        if remove and child.Parent then
            pcall(function() child:Destroy() end)
        end
    end

    if snapshot then
        -- Restore the original clothing if a selected skin script replaced it.
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
                if not snapshot.children[child] then
                    pcall(function() child:Destroy() end)
                end
            end
        end
        for _, clothing in ipairs(snapshot.clothing) do
            local original = clothing.original
            if not original or original.Parent ~= character then
                local restored = clothing.backup and clothing.backup:Clone()
                if restored then restored.Parent = character end
            end
        end
        for _, item in ipairs(snapshot.destroyedBackups or {}) do
            if item.parent and item.parent.Parent then
                pcall(function()
                    if item.original and not item.original.Parent then
                        item.original.Parent = item.parent
                    elseif item.clone and not item.clone.Parent then
                        item.clone.Parent = item.parent
                    end
                end)
            end
        end
        snapshot.destroyedBackups = {}
        for part, values in pairs(snapshot.parts) do
            if part and part.Parent then
                pcall(function()
                    part.Transparency = values.Transparency
                    part.BrickColor = values.BrickColor
                    part.Color = values.Color
                    part.CanCollide = values.CanCollide
                    part.CanTouch = values.CanTouch
                    part.CanQuery = values.CanQuery
                    part.LocalTransparencyModifier = values.LocalTransparencyModifier
                    part.Size = values.Size
                    part.Material = values.Material
                    part.Reflectance = values.Reflectance
                    if values.isMeshPart and part:IsA("MeshPart") then
                        part.MeshId = values.MeshId
                        part.TextureID = values.TextureID
                    end
                end)
            end
        end
        for object, values in pairs(snapshot.meshes or {}) do
            if object and object.Parent then
                pcall(function()
                    object.MeshId = values.MeshId
                    object.TextureId = values.TextureId
                    object.Scale = values.Scale
                    object.Offset = values.Offset
                    object.VertexColor = values.VertexColor
                end)
            end
        end
        for object, values in pairs(snapshot.joints or {}) do
            if object and object.Parent then
                pcall(function() object.C0 = values.C0; object.C1 = values.C1; object.Part0 = values.Part0; object.Part1 = values.Part1 end)
            end
        end
        for object, transparency in pairs(snapshot.transparency) do
            if object and object.Parent then
                pcall(function() object.Transparency = transparency end)
            end
        end
    end
end


