S.__helpers.cloneAdminNoliVoiceLines = function()
    local copy = {}
    for category, urls in pairs(S.ADMIN_NOLI_VOICELINE_URLS or {}) do
        local list = {}
        for index, url in ipairs(urls) do list[index] = url end
        copy[category] = list
    end
    return copy
end

S.__helpers.getAdminNoliAssetPath = function(kind, name)
    local folder = S.ADMIN_NOLI_ASSET_FOLDER
    if kind == "Model" then return S.ADMIN_NOLI_MODEL_FILE end
    if kind == "Animation" then
        return folder .. "/AdminNoli_" .. tostring(name) .. ".rbxm"
    end
    if kind == "Sound" then
        return folder .. "/AdminNoli_Sound_" .. tostring(name) .. ".mp3"
    end
    return nil
end

S.__helpers.ensureAdminNoliFolder = function()
    if type(makefolder) ~= "function" then return false end
    pcall(makefolder, "E1LU4HUB")
    pcall(makefolder, S.ADMIN_NOLI_ASSET_FOLDER)
    if type(isfolder) == "function" then
        local ok, exists = pcall(isfolder, S.ADMIN_NOLI_ASSET_FOLDER)
        return ok and exists == true
    end
    return true
end

S.__helpers.adminNoliFileExists = function(path)
    if type(path) ~= "string" or path == "" then return false end
    if type(isfile) == "function" then
        local ok, exists = pcall(isfile, path)
        if ok and exists == true then return true end
    end
    if type(readfile) == "function" then
        local ok, content = pcall(readfile, path)
        return ok and type(content) == "string" and #content > 0
    end
    return false
end

S.__helpers.ensureAdminNoliAssetFile = function(url, path, legacyPaths)
    if S.__helpers.adminNoliFileExists(path) then
        return true, false
    end

    -- Migrate assets from both prior locations into E1LU4HUB/E1LU4SAKEN,
    -- preserving the existing cache and avoiding a second network download.
    if type(legacyPaths) == "string" then legacyPaths = {legacyPaths} end
    if type(legacyPaths) == "table"
        and type(readfile) == "function" and type(writefile) == "function" then
        for _, legacyPath in ipairs(legacyPaths) do
            if type(legacyPath) == "string" and S.__helpers.adminNoliFileExists(legacyPath) then
                local readOK, oldContent = pcall(readfile, legacyPath)
                if readOK and type(oldContent) == "string" and #oldContent > 0 then
                    S.__helpers.ensureAdminNoliFolder()
                    local writeOK = pcall(writefile, path, oldContent)
                    if writeOK and S.__helpers.adminNoliFileExists(path) then
                        if type(delfile) == "function" then pcall(delfile, legacyPath) end
                        return true, false
                    end
                end
            end
        end
    end

    if type(game.HttpGet) ~= "function" or type(writefile) ~= "function" then
        return false, false
    end
    local ok, content = pcall(function() return game:HttpGet(url) end)
    if not ok or type(content) ~= "string" or #content == 0 then
        ok, content = pcall(game.HttpGet, game, url)
    end
    if not ok or type(content) ~= "string" or #content == 0 then
        return false, true
    end

    S.__helpers.ensureAdminNoliFolder()
    local writeOK = pcall(writefile, path, content)
    if not writeOK then return false, true end
    return S.__helpers.adminNoliFileExists(path), true
end

S.__helpers.preloadAdminNoliAssets = function()
    if S.ADMIN_NOLI_PRELOAD_STARTED then
        while not S.ADMIN_NOLI_PRELOAD_DONE do task.wait(0.1) end
        return S.ADMIN_NOLI_PRELOAD_FAILED == 0
    end
    S.ADMIN_NOLI_PRELOAD_STARTED = true
    S.ADMIN_NOLI_PRELOAD_QUEUED = false

    local jobs = {}
    table.insert(jobs, {
        url = S.ADMIN_NOLI_CONFIG.ModelUrl,
        path = S.__helpers.getAdminNoliAssetPath("Model"),
        legacy = {
            S.ADMIN_NOLI_LEGACY_ASSET_FOLDER .. "/AdminNoli_Model_Download.rbxm",
            "AdminNoli_Model_Download.rbxm",
        },
    })
    for name, url in pairs(S.ADMIN_NOLI_CONFIG.AnimationUrls or {}) do
        table.insert(jobs, {
            url = url,
            path = S.__helpers.getAdminNoliAssetPath("Animation", name),
            legacy = {
                S.ADMIN_NOLI_LEGACY_ASSET_FOLDER .. "/AdminNoli_" .. tostring(name) .. ".rbxm",
                "AdminNoli_" .. tostring(name) .. ".rbxm",
            },
        })
    end
    for name, url in pairs(S.ADMIN_NOLI_CONFIG.SoundUrls or {}) do
        table.insert(jobs, {
            url = url,
            path = S.__helpers.getAdminNoliAssetPath("Sound", name),
            legacy = {
                S.ADMIN_NOLI_LEGACY_ASSET_FOLDER .. "/AdminNoli_Sound_" .. tostring(name) .. ".mp3",
                "AdminNoli_Sound_" .. tostring(name) .. ".mp3",
            },
        })
    end
    for category, list in pairs(S.ADMIN_NOLI_VOICELINE_URLS or {}) do
        for index, url in ipairs(list) do
            local soundName = "VL_" .. tostring(category) .. "_" .. tostring(index)
            table.insert(jobs, {
                url = url,
                path = S.__helpers.getAdminNoliAssetPath("Sound", soundName),
                legacy = {
                    S.ADMIN_NOLI_LEGACY_ASSET_FOLDER .. "/AdminNoli_Sound_" .. soundName .. ".mp3",
                    "AdminNoli_Sound_" .. soundName .. ".mp3",
                },
            })
        end
    end

    local missing = 0
    for _, job in ipairs(jobs) do
        local hasLegacyCache = false
        if type(job.legacy) == "string" then
            hasLegacyCache = S.__helpers.adminNoliFileExists(job.legacy)
        elseif type(job.legacy) == "table" then
            for _, legacyPath in ipairs(job.legacy) do
                if S.__helpers.adminNoliFileExists(legacyPath) then
                    hasLegacyCache = true
                    break
                end
            end
        end
        if not S.__helpers.adminNoliFileExists(job.path) and not hasLegacyCache then
            missing += 1
        end
    end

    if missing > 0 and S.__helpers.notify then
        pcall(S.__helpers.notify, "E1LU4 HUB", "downloading...", 60)
    end

    local failed = 0
    for _, job in ipairs(jobs) do
        local ok = S.__helpers.ensureAdminNoliAssetFile(job.url, job.path, job.legacy)
        if not ok then
            failed += 1
            warn("[AdminNoli] Asset preload failed: " .. tostring(job.path))
        end
        task.wait(0.02)
    end

    S.ADMIN_NOLI_PRELOAD_FAILED = failed
    S.ADMIN_NOLI_PRELOAD_DONE = true
    if failed > 0 then
        warn("[AdminNoli] Preload finished with " .. tostring(failed) .. " missing file(s).")
    end
    return failed == 0
end

-- Start the cache pass during the initial UI construction, before any saved
-- skin selection can try to activate Admin Noli.
S.ADMIN_NOLI_PRELOAD_QUEUED = true
task.spawn(function()
    local ok, result = pcall(S.__helpers.preloadAdminNoliAssets)
    S.ADMIN_NOLI_PRELOAD_QUEUED = false
    if not ok then
        warn("[AdminNoli] Startup preload crashed: " .. tostring(result))
        S.ADMIN_NOLI_PRELOAD_FAILED = (S.ADMIN_NOLI_PRELOAD_FAILED or 0) + 1
        S.ADMIN_NOLI_PRELOAD_DONE = true
    end
end)

S.SkinChanger.startAdminNoliOld = function(character)
    if (S.ADMIN_NOLI_PRELOAD_QUEUED or S.ADMIN_NOLI_PRELOAD_STARTED)
        and not S.ADMIN_NOLI_PRELOAD_DONE then
        while not S.ADMIN_NOLI_PRELOAD_DONE do task.wait(0.1) end
    end
    character = character or (S.lp and S.lp.Character)
    if not character or character.Name ~= "Noli"
        or not S.__helpers.isLocalRole
        or not S.__helpers.isLocalRole("Killer") then
        return false
    end
    local skinName = character:GetAttribute("SkinName")
    if skinName ~= nil and skinName ~= "" then return false end

    if S.SkinChanger.captureCharacter then
        pcall(S.SkinChanger.captureCharacter, character)
    end

    local existing = S.SkinChanger.adminNoliOld
    if existing and existing.running then
        if existing.templateModel and character ~= existing.corpoInicial then
            existing.setupCharacter(character)
            task.spawn(function()
                task.wait(0.5)
                if existing.running and existing.isTargetCharacter(character) then
                    existing.hookAbilityAnimations(character)
                end
            end)
        end
        return true
    end

    S.SkinChanger.stopAdminNoliOld()
    local AN = {}
    AN.running = true
    AN.connections = {}
    AN.createdObjects = {}
    AN.originalProperties = setmetatable({}, {__mode = "k"})
    S.SkinChanger.adminNoliOld = AN

    AN.trackConnection = function(connection)
        if connection then table.insert(AN.connections, connection) end
        return connection
    end
    AN.trackCreatedObject = function(object)
        if object then table.insert(AN.createdObjects, object) end
        return object
    end
    AN.rememberProperty = function(object, property)
        if not object then return end
        local properties = AN.originalProperties[object]
        if not properties then
            properties = {}
            AN.originalProperties[object] = properties
        end
        if properties[property] == nil then
            local ok, value = pcall(function() return object[property] end)
            if ok then properties[property] = value end
        end
    end
    AN.restoreOriginalProperties = function()
        for object, properties in pairs(AN.originalProperties) do
            if object and object.Parent then
                for property, value in pairs(properties) do
                    pcall(function() object[property] = value end)
                end
            end
            AN.originalProperties[object] = nil
        end
    end
    AN.isTargetCharacter = function(character)
        if not character or character ~= AN.Player.Character or character.Name ~= "Noli" then
            return false
        end
        local playersFolder = workspace:FindFirstChild("Players")
        local killersFolder = playersFolder and playersFolder:FindFirstChild("Killers")
        if not killersFolder or not character:IsDescendantOf(killersFolder) then
            return false
        end
        local skinName = character:GetAttribute("SkinName")
        return skinName == nil or skinName == ""
    end

    do
local AN = AN
AN.Players = game:GetService("Players")
AN.RunService = game:GetService("RunService")
