local AN = AN

AN.stopSound = function(category)
    local s = AN.activeSounds[category]
    if s and s.Parent then s:Stop() s:Destroy() end
    AN.activeSounds[category] = nil
end

AN.playVoiceline = function(category)
    local list = AN.VoiceLines[category]
    if not list or #list == 0 then return end
    if AN.lastVLPlayed[category] and (os.clock() - AN.lastVLPlayed[category]) < 0.5 then return end
    
    for cat, s in pairs(AN.activeSounds) do
        if s and s.IsPlaying then
            AN.stopSound(cat)
        end
    end
    
    AN.lastVLPlayed[category] = os.clock()
    local chosenId = list[math.random(#list)]
    local s = Instance.new("Sound")
    s.SoundId = chosenId
    s.Volume = 1.5
    
    local tag = Instance.new("BoolValue")
    tag.Name = "IsAdminSound"
    AN.trackCreatedObject(tag)
    tag.Parent = s
    
    local parent = AN.Player.Character and (AN.Player.Character:FindFirstChild("HumanoidRootPart") or AN.Player.Character) or workspace
    s.Parent = parent
    AN.activeSounds[category] = s
    local cleanup = function()
        if AN.activeSounds[category] == s then AN.activeSounds[category] = nil end
        if s.Parent then s:Destroy() end
    end
    s.Ended:Once(cleanup)
    s:Play()
    AN.lastVLTime = os.clock()
end

AN.pickCustomKillSound = function()
    local list = AN.VoiceLines["Kill"]
    if list and #list > 0 then return list[math.random(#list)] end
    return AN.SoundData["Kill"]
end

AN.setupSoundReplacer = function()
    local function tagOnce(inst)
        if inst:FindFirstChild("AdminNoliReplaced") then return false end
        local tag = Instance.new("BoolValue")
        tag.Name = "AdminNoliReplaced"
        AN.trackCreatedObject(tag)
        tag.Parent = inst
        return true
    end
    local function checkSound(inst)
        if not inst:IsA("Sound") then return end
        local function replace()
            if inst:FindFirstChild("IsAdminSound") then return end
            if inst:FindFirstChild("AdminNoliReplaced") then return end
            AN.rememberProperty(inst, "SoundId")
            AN.rememberProperty(inst, "Volume")
            AN.rememberProperty(inst, "Looped")
            local id = inst.SoundId
            local match = id:match("rbxassetid://(%d+)") or id:match("id=(%d+)")
            if match then id = "rbxassetid://" .. match end
            if AN.KILL_VL_IDS[id] then
                local recent = AN.lastVLPlayed["Kill"] and (os.clock() - AN.lastVLPlayed["Kill"]) < 0.5
                if recent then
                    tagOnce(inst)
                    inst.Volume = 0
                    return
                end
                local customKill = AN.pickCustomKillSound()
                if customKill then
                    tagOnce(inst)
                    inst.SoundId = customKill
                    inst.Volume = 1.5
                    local tag = Instance.new("BoolValue")
                    tag.Name = "IsAdminSound"
                    AN.trackCreatedObject(tag)
                    tag.Parent = inst
                    AN.lastVLPlayed["Kill"] = os.clock()
                    AN.stopSound("Idle")
                    AN.lastVLTime = os.clock()
                end
                return
            end
            if AN.NOLI_ORIGINAL_VLS[id] or AN.MUTE_SET[id] then
                tagOnce(inst)
                inst.Volume = 0
            end
            local repl = AN.SOUND_REPLACER[id]
            if repl and AN.SoundData[repl.customSound] then
                tagOnce(inst)
                inst.SoundId = AN.SoundData[repl.customSound]
                inst.Volume = repl.volume or 1.5
                local tag = Instance.new("BoolValue")
                tag.Name = "IsAdminSound"
                AN.trackCreatedObject(tag)
                tag.Parent = inst
                if repl.looped ~= nil then inst.Looped = repl.looped end
                if AN.STOP_IDLE_SOUNDS[repl.customSound] then AN.stopSound("Idle") end
            end
            local vlCategory = AN.VL_MAP[id]
            if vlCategory then
                tagOnce(inst)
                inst.Volume = 0
                AN.playVoiceline(vlCategory)
            end
        end
        replace()
        AN.trackConnection(inst:GetPropertyChangedSignal("SoundId"):Connect(replace))
        AN.trackConnection(inst.Played:Connect(replace))
    end
    for _, obj in ipairs(game:GetDescendants()) do checkSound(obj) end
    AN.trackConnection(game.DescendantAdded:Connect(checkSound))
end

AN.setupChaseReplacer = function()
    local orig = "rbxassetid://82229037343524"
    local themes = workspace:FindFirstChild("Themes")
    local function check(inst)
        if inst:IsA("Sound") and inst.SoundId == orig and AN.SoundData["Chase"] then
            AN.rememberProperty(inst, "SoundId")
            AN.rememberProperty(inst, "Volume")
            inst.SoundId = AN.SoundData["Chase"]
            inst.Volume = 13.5
        end
    end
    if themes then
        for _, obj in ipairs(themes:GetChildren()) do check(obj) end
        AN.themeConnection = AN.trackConnection(themes.ChildAdded:Connect(check))
    end
end
