AN.MapearArticulacoes = function(modelo)
    AN.jointMap = {}
    for _, desc in ipairs(modelo:GetDescendants()) do
        if desc:IsA("Bone") then
            AN.jointMap[desc.Name] = desc
        elseif desc:IsA("Motor6D") then
            AN.jointMap[desc.Name] = desc
            if desc.Part1 and desc.Part1.Name ~= desc.Name and not AN.jointMap[desc.Part1.Name] then
                AN.jointMap[desc.Part1.Name] = desc
            end
        end
    end
end

AN.iniciarOverride = function(animName, looped, clearOnEnd)
    if not animName or not AN.KeyframeData[animName] then return end
    AN.activeOverride = animName
    AN.overrideClearOnEnd = clearOnEnd
    AN.currentAnimName = animName
    AN.animTime = 0
    AN.isLoopingAnim = looped
    for _, joint in pairs(AN.jointMap) do
        if joint and joint.Parent then joint.Transform = CFrame.identity end
    end
end

AN.limparOverride = function()
    AN.activeOverride = nil
    AN.currentAnimName = ""
    AN.animTime = 0
    AN.lastState = ""
    for _, joint in pairs(AN.jointMap) do
        if joint and joint.Parent then joint.Transform = CFrame.identity end
    end
end

AN.PlayAnimationRealtime = function(animName, isAction)
    if not animName or not AN.KeyframeData[animName] then return end
    if AN.currentAnimName == animName and not isAction then return end
    for _, joint in pairs(AN.jointMap) do
        if joint and joint.Parent then joint.Transform = CFrame.identity end
    end
    AN.currentAnimName = animName
    AN.animTime = 0
    AN.isLoopingAnim = not isAction
end

AN.hasActiveObservantServerTrack = function()
    for track in pairs(AN.observantServerTracks) do
        if track.IsPlaying then return true end
    end
    return false
end

AN.ProcessarKeyframesEmTempoReal = function(dt)
    if not AN.currentAnimName or not AN.KeyframeData[AN.currentAnimName] or #AN.KeyframeData[AN.currentAnimName] == 0 then return end
    local kfList = AN.KeyframeData[AN.currentAnimName]
    local maxTime = AN.AnimDurations[AN.currentAnimName] or 1
    AN.animTime = AN.animTime + (dt * AN.CONFIG.VelocidadeGlobal)
    if AN.animTime >= maxTime then
        if AN.isLoopingAnim then
            AN.animTime = AN.animTime % maxTime
        else
            AN.animTime = maxTime
            if AN.activeOverride then
                if AN.activeOverride == "ObservantLoop" and AN.KeyframeData["ObservantIdle"] then
                    if AN.hasActiveObservantServerTrack() then
                        AN.iniciarOverride("ObservantIdle", true, false)
                        return
                    end
                end
                if AN.overrideClearOnEnd then AN.limparOverride() return end
            else
                AN.currentAnimName = ""
                return
            end
        end
    end
    local kfPrev = kfList[1]
    local kfNext = kfList[#kfList]
    for i = 1, #kfList - 1 do
        if AN.animTime >= kfList[i].Time and AN.animTime <= kfList[i+1].Time then
            kfPrev = kfList[i]
            kfNext = kfList[i+1]
            break
        end
    end
    local span = kfNext.Time - kfPrev.Time
    local alpha = span > 0 and math.clamp((AN.animTime - kfPrev.Time) / span, 0, 1) or 0
    for jointName, joint in pairs(AN.jointMap) do
        if joint and joint.Parent then
            local poseA = kfPrev.Poses[jointName]
            local poseB = kfNext.Poses[jointName]
            if poseA and poseB then
                joint.Transform = poseA:Lerp(poseB, alpha)
            elseif poseA then
                joint.Transform = poseA
            elseif poseB then
                joint.Transform = poseB
            else
                joint.Transform = CFrame.identity
            end
        end
    end
end
AN.debug("PARTE 5 carregada")
local AN = AN

AN.isObservantServerId = function(id)
    return AN.OBS_START_SERVER[id] or AN.OBS_LOOP_SERVER[id] or AN.OBS_TELEPORT_SERVER[id]
end

AN.handleAbilityAnim = function(id)
    if AN.OBS_START_SERVER[id] or AN.OBS_LOOP_SERVER[id] then
        if AN.KeyframeData["ObservantIdle"] then AN.iniciarOverride("ObservantIdle", true, false) end
        return
    end
    if AN.OBS_TELEPORT_SERVER[id] then
        if AN.KeyframeData["ObservantLoop"] then AN.iniciarOverride("ObservantLoop", false, false) end
        return
    end
    local entry = AN.ANIM_MAP[id]
    if not entry then return end
    if entry.name == "IGNORE" then return end
    
    if entry.name == "Nova" then
        AN.playVoiceline("NovaThrow")
    elseif entry.name == "ExecKiller" then
        AN.playVoiceline("Kill")
    elseif entry.name == "VoidRushCrash" then
        AN.stopSound("VoidRushing")
        AN.playVoiceline("VoidRushCrash")
    elseif entry.name == "VoidRushHit" or entry.name == "VoidRushCutscene" or entry.name == "VoidRushEnd" or entry.name == "VoidRushCancel" then
        AN.stopSound("VoidRushing")
    end
    
    if entry.name == "VoidRushHit" or entry.name == "VoidRushCrash" or entry.name == "VoidRushCutscene" or entry.name == "VoidRushEnd" or entry.name == "VoidRushCancel" then
        if AN.vrDashSound then AN.vrDashSound:Stop() AN.vrDashSound:Destroy() AN.vrDashSound = nil end
    end
    AN.iniciarOverride(entry.name, entry.looped, entry.clearOnEnd)
end

AN.handleVoidRushState = function(rig, newState)
    if newState == AN.currentVoidRushState then return end
    local oldState = AN.currentVoidRushState
    AN.currentVoidRushState = newState
    if newState ~= "Dashing" and AN.vrDashSound then
        AN.vrDashSound:Stop() AN.vrDashSound:Destroy() AN.vrDashSound = nil
    end
    if newState == "Charging" then
        if AN.KeyframeData["VoidRushLoop"] then AN.iniciarOverride("VoidRushLoop", true, false) end
    elseif newState == "Dashing" then
        if AN.KeyframeData["VoidRushDash"] then
            AN.iniciarOverride("VoidRushDash", true, false)
            if not AN.vrDashSound and AN.SoundData["VoidRushVrooom"] then
                AN.vrDashSound = Instance.new("Sound")
                AN.vrDashSound.SoundId = AN.SoundData["VoidRushVrooom"]
                AN.vrDashSound.Volume = 1.5
                AN.vrDashSound.Looped = true
                local tag = Instance.new("BoolValue")
                tag.Name = "IsAdminSound"
                tag.Parent = AN.vrDashSound
                AN.vrDashSound.Parent = rig:FindFirstChild("HumanoidRootPart") or rig
                AN.vrDashSound:Play()
            end
        elseif AN.KeyframeData["Run"] then
            AN.iniciarOverride("Run", true, false)
        end
    elseif newState == "ChargingCancelled" then
        AN.stopSound("VoidRushing")
        if AN.KeyframeData["VoidRushCancel"] then AN.iniciarOverride("VoidRushCancel", false, true) end
    elseif (newState == nil or newState == "") and (oldState == "Charging" or oldState == "ChargingCancelled") then
        AN.stopSound("VoidRushing")
        if oldState == "Charging" and AN.KeyframeData["VoidRushCancel"] then
            AN.iniciarOverride("VoidRushCancel", false, true)
        else
            AN.limparOverride()
        end
    elseif newState == nil or newState == "" then
        AN.limparOverride()
    end
end

AN.hookAbilityAnimations = function(rig)
    if not AN.running or not AN.isTargetCharacter(rig) then return end
    local humanoid = rig:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if not animator then return end
    if AN.animatorConnection then pcall(function() AN.animatorConnection:Disconnect() end) end
    if AN.vrAttrConnection then pcall(function() AN.vrAttrConnection:Disconnect() end) end
    AN.currentVoidRushState = rig:GetAttribute("VoidRushState")
    AN.observantServerTracks = setmetatable({}, {__mode = "k"})
    AN.animatorConnection = AN.trackConnection(animator.AnimationPlayed:Connect(function(track)
        if not track.Animation then return end
        local id = track.Animation.AnimationId
        if AN.isObservantServerId(id) then
            AN.observantServerTracks[track] = true
            AN.trackConnection(track.Stopped:Connect(function()
                AN.observantServerTracks[track] = nil
                task.defer(function()
                    if not AN.hasActiveObservantServerTrack() then
                        if AN.activeOverride == "ObservantIdle" or AN.activeOverride == "ObservantLoop" then
                            AN.limparOverride()
                        end
                    end
                end)
            end))
        end
        if id == "rbxassetid://101309478627323" or id == "rbxassetid://126896426760253" or id == "rbxassetid://104152391233857" then
            AN.trackConnection(track.Stopped:Connect(function()
                if AN.activeOverride == "VoidRushDash" or AN.activeOverride == "VoidRushLoop" then
                    AN.limparOverride()
                end
            end))
        end
        pcall(AN.handleAbilityAnim, id)
    end))
    AN.vrAttrConnection = AN.trackConnection(rig:GetAttributeChangedSignal("VoidRushState"):Connect(function()
        pcall(AN.handleVoidRushState, rig, rig:GetAttribute("VoidRushState"))
    end))
end

AN.esconderPartesOriginais = function(character)
    if character.Name ~= "Noli" then return end
    if character:GetAttribute("SkinName") ~= nil and character:GetAttribute("SkinName") ~= "" then return end
    for _, obj in ipairs(character:GetDescendants()) do
        if obj:IsA("BasePart") or obj:IsA("MeshPart") then
            AN.rememberProperty(obj, "Transparency")
            AN.rememberProperty(obj, "CastShadow")
            AN.rememberProperty(obj, "LocalTransparencyModifier")
            obj.Transparency = 1
            obj.CastShadow = false
            obj.LocalTransparencyModifier = 1
        elseif obj:IsA("Decal") or obj:IsA("Texture") then
            AN.rememberProperty(obj, "Transparency")
            obj.Transparency = 1
        elseif obj:IsA("Sound") then
            if not obj:FindFirstChild("IsAdminSound") then
                AN.rememberProperty(obj, "Volume")
                obj.Volume = 0
            end
        end
    end
    -- Keep the original Animate instance intact so Skin Changer OFF can restore cleanly.
end

AN.esconderNoliOriginal = function()
    if not AN.running then return end
    local players = workspace:FindFirstChild("Players")
    if not players then return end
    local killers = players:FindFirstChild("Killers")
    if not killers then return end
    local noli = killers:FindFirstChild("Noli")
    if not noli or not AN.isTargetCharacter(noli) then return end
    for _, obj in ipairs(noli:GetDescendants()) do
        if obj:IsA("BasePart") then
            AN.rememberProperty(obj, "Transparency")
            AN.rememberProperty(obj, "CastShadow")
            obj.Transparency = 1
            obj.CastShadow = false
        elseif obj:IsA("Decal") or obj:IsA("Texture") then
            AN.rememberProperty(obj, "Transparency")
            obj.Transparency = 1
        elseif obj:IsA("Sound") then
            if not obj:FindFirstChild("IsAdminSound") then
                AN.rememberProperty(obj, "Volume")
                obj.Volume = 0
            end
        elseif obj:IsA("ParticleEmitter") or obj:IsA("Beam") or obj:IsA("Trail") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles")
            or obj:IsA("BillboardGui") or obj:IsA("SurfaceGui") or obj:IsA("Highlight") then
            AN.rememberProperty(obj, "Enabled")
            pcall(function() obj.Enabled = false end)
        end
    end
end

AN.startIdleSequence = function(character)
    task.spawn(function()
        while AN.running and AN.Player.Character == character and character.Parent and character:FindFirstChild("Humanoid") and character.Humanoid.Health > 0 do
            local now = os.clock()
            if now - AN.lastVLTime >= 25 then
                AN.playVoiceline("Idle")
            end
            task.wait(1)
        end
    end)
end

AN.createVisualModelFor = function()
    if not AN.templateModel then return end
    if AN.VisualModel then AN.VisualModel:Destroy() end
    AN.VisualModel = Instance.new("Model")
    AN.VisualModel.Name = "VisualModel_Client_" .. AN.Player.Name
    AN.VisualModel.Parent = workspace
    local clone = AN.templateModel:Clone()
    for _, obj in ipairs(clone:GetDescendants()) do
        if obj:IsA("BasePart") then
            obj.CanCollide = false
            obj.CanTouch = false
            obj.CanQuery = false
            obj.Anchored = false
            obj.Massless = true
            local lower = string.lower(obj.Name)
            if (lower == "humanoidrootpart" or lower == "rootpart") and not obj:IsA("MeshPart") then
                obj.Transparency = 1
            end
        end
    end
    AN.rigRoot = clone:FindFirstChild("HumanoidRootPart") or clone:FindFirstChild("RootPart") or clone.PrimaryPart or clone:FindFirstChildWhichIsA("BasePart")
    AN.modeloSelecionado = clone
    AN.modeloSelecionado.Parent = AN.VisualModel
    AN.MapearArticulacoes(AN.modeloSelecionado)
    AN.lastState = ""
    AN.currentAnimName = ""
    AN.activeOverride = nil
    if AN.KeyframeData["Idle"] then AN.PlayAnimationRealtime("Idle", false) end
end

AN.setupCharacter = function(character)
    if not character then return false end
    if not AN.isTargetCharacter(character) or not character:FindFirstChild("HumanoidRootPart") then
        AN.corpoInicial = character
        if AN.VisualModel and AN.VisualModel.Parent then
            pcall(function() AN.VisualModel:Destroy() end)
            AN.VisualModel = nil
        end
        return false
    end
    if AN.corpoInicial == character and AN.VisualModel then return true end
    AN.corpoInicial = character
    AN.esconderPartesOriginais(character)
    AN.createVisualModelFor()
    AN.lastVLTime = os.clock()
    AN.startIdleSequence(character)
    return true
end
