local AN = AN
local RunService = AN.RunService
local Player = AN.Player

local function getModelFromGithub()
    local path = S.__helpers.getAdminNoliAssetPath("Model")
    if not path or not S.__helpers.adminNoliFileExists(path) then
        AN.warn("Cached Admin Noli model is missing; startup preload did not complete.")
        return nil
    end
    local okAsset, assetId = pcall(getcustomasset, path)
    if not okAsset or not assetId then return nil end
    local insert = game:GetService("InsertService")
    local okIns, ins = pcall(function() return insert:LoadLocalAsset(assetId) end)
    if okIns and ins then return ins end
    local okObj, resObj = pcall(game.GetObjects, game, assetId)
    if okObj and resObj and #resObj > 0 then return resObj[1] end
    return nil
end

task.spawn(function()
    task.wait(1)
    if not AN.running then return end
    
    local downloaded = getModelFromGithub()
    if not AN.running then
        if downloaded then pcall(function() downloaded:Destroy() end) end
        return
    end
    if not downloaded then
        return
    end
    
    local target = downloaded:FindFirstChild(AN.CONFIG.NomeModeloFoco, true) or downloaded
    if not target then
        return
    end
    
    local clone = target:Clone()
    local h = clone:FindFirstChildOfClass("Humanoid")
    if h then h:Destroy() end
    AN.templateModel = clone
    task.wait(0.3)
    
    for animName, url in pairs(AN.CONFIG.AnimationUrls) do
        AN.LoadAnimFromUrl(animName, url)
        task.wait(0.02)
    end
    if not AN.running then return end
    task.wait(0.3)
    
    for sName, sUrl in pairs(AN.CONFIG.SoundUrls) do
        AN.LoadSoundFromUrl(sName, sUrl)
        task.wait(0.02)
    end
    if not AN.running then return end
    task.wait(0.3)
    
    for category, list in pairs(AN.VoiceLines) do
        for i, url in ipairs(list) do
            local vlName = "VL_" .. category .. "_" .. i
            if AN.LoadSoundFromUrl(vlName, url) then
                list[i] = AN.SoundData[vlName]
            end
        end
    end
    if not AN.running then return end
    task.wait(0.3)
    
    if not AN.running then return end
    AN.setupSoundReplacer()
    AN.setupChaseReplacer()
    
    task.spawn(function()
        while AN.running do
            pcall(AN.esconderNoliOriginal)
            task.wait(0.5)
        end
    end)
    
    task.spawn(function()
        while AN.running do
            task.wait(0.1)
            local ingame = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("Ingame")
            if ingame then
                local voidstar = ingame:FindFirstChild("Voidstar")
                if voidstar and voidstar:IsA("BasePart") then
                    AN.rememberProperty(voidstar, "Transparency")
                    voidstar.Transparency = 1
                end
            end
        end
    end)
    
    AN.loadingDone = true
    local char = Player.Character
    if char then
        pcall(AN.setupCharacter, char)
        task.spawn(function()
            task.wait(0.5)
            if AN.running and AN.isTargetCharacter(char) then
                pcall(AN.hookAbilityAnimations, char)
            end
        end)
    end
    
    AN.debug("=== LOADING COMPLETE ===")
end)

AN.visualRenderConnection = AN.trackConnection(RunService.PreRender:Connect(function(dt)
    if not AN.running then return end
    local corpo = Player.Character
    if not corpo or not corpo.Parent then
        if AN.VisualModel and AN.VisualModel.Parent then AN.VisualModel.Parent = nil end
        return
    end
    if corpo ~= AN.corpoInicial then
        AN.setupCharacter(corpo)
        if AN.isTargetCharacter(corpo) then
            task.spawn(function()
                task.wait(0.5)
                if AN.running and AN.isTargetCharacter(corpo) then AN.hookAbilityAnimations(corpo) end
            end)
        end
        return
    end
    local humanoid = corpo:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then
        if AN.VisualModel and AN.VisualModel.Parent then AN.VisualModel.Parent = nil end
        return
    end
    
    local isNoli = corpo.Name == "Noli"
    local skin = corpo:GetAttribute("SkinName")
    local semSkin = (skin == nil or skin == "")
    
    if not isNoli or not semSkin or not AN.isTargetCharacter(corpo) then
        if AN.VisualModel and AN.VisualModel.Parent then AN.VisualModel.Parent = nil end
        return
    end

    if AN.VisualModel and not AN.VisualModel.Parent then
        AN.VisualModel.Parent = workspace
        AN.lastState = ""
    end
    
    AN.esconderPartesOriginais(corpo)

    local atualRoot = corpo:FindFirstChild("HumanoidRootPart")
    if not atualRoot or not AN.rigRoot or not AN.modeloSelecionado then return end
    
    AN.rememberProperty(humanoid, "CameraOffset")
    humanoid.CameraOffset = AN.CONFIG.OffsetCamera
    local rootCFrame = atualRoot.CFrame
    local _, ry, _ = rootCFrame:ToOrientation()
    AN.rigRoot.CFrame = CFrame.new(rootCFrame.Position) * CFrame.Angles(0, ry, 0) * AN.CONFIG.OffsetModelo
    
    if not AN.activeOverride then
        local velReal = atualRoot.AssemblyLinearVelocity
        local velPlana = math.sqrt(velReal.X^2 + velReal.Z^2)
        local ws = humanoid.WalkSpeed
        local desired
        
        if velPlana > 1.8 then
            if velPlana >= AN.CONFIG.LimiteVelocidadeCorrida or ws >= AN.CONFIG.LimiteVelocidadeCorrida then
                desired = "Run"
            else
                desired = "Walk"
            end
        else
            desired = "Idle"
        end
        
        if AN.lastState ~= desired and AN.KeyframeData[desired] then
            AN.lastState = desired
            AN.PlayAnimationRealtime(desired, false)
        end
    end
    AN.ProcessarKeyframesEmTempoReal(dt)
end))

