-- Artist Shedletsky can be selected and equipped through the same game-side
-- Equipped.Skins mechanism used by the TwoTime variants. Resolve the real asset
-- folder name when it exists; keep a stable fallback for custom/local-only assets.
local function resolveArtistShedletskySkinName()
    local assets = S.ReplicatedStorage and S.ReplicatedStorage:FindFirstChild("Assets")
    local skinsRoot = assets and assets:FindFirstChild("Skins")
    local survivors = skinsRoot and skinsRoot:FindFirstChild("Survivors")
    local shedletsky = survivors and survivors:FindFirstChild("Shedletsky")
    if shedletsky then
        for _, candidate in ipairs({"ArtistShedletsky", "Artist shedletsky", "Artist"}) do
            local found = shedletsky:FindFirstChild(candidate)
            if found and (found:IsA("Folder") or found:IsA("Model")) then
                return found.Name
            end
        end
        for _, descendant in ipairs(shedletsky:GetDescendants()) do
            if (descendant:IsA("Folder") or descendant:IsA("Model"))
                and descendant.Name:lower():gsub("[^%w]", ""):find("artist", 1, true) then
                return descendant.Name
            end
        end
    end
    return "ArtistShedletsky"
end

S.SkinChanger.getArtistShedletskySkinName = resolveArtistShedletskySkinName
S.SkinChanger.artistEquippedBackup = nil
S.SkinChanger.artistEquippedCreatedValue = nil
S.SkinChanger.artistPurchasedCreatedValue = nil
S.SkinChanger.artistEquipConnection = nil

S.SkinChanger.ensureArtistShedletskyEquip = function()
    local player = S.lp
    local playerData = player and player:FindFirstChild("PlayerData")
    local equipped = playerData and playerData:FindFirstChild("Equipped")
    local equippedSkins = equipped and equipped:FindFirstChild("Skins")
    local purchased = playerData and playerData:FindFirstChild("Purchased")
    local purchasedSkins = purchased and purchased:FindFirstChild("Skins")
    if not equippedSkins then
        return false, "PlayerData.Equipped.Skins is not available yet"
    end

    local skinName = resolveArtistShedletskySkinName()
    local value = equippedSkins:FindFirstChild("Shedletsky")
    if not S.SkinChanger.artistEquippedBackup then
        local originalAttributes = {}
        if value then
            pcall(function() originalAttributes = value:GetAttributes() end)
        end
        S.SkinChanger.artistEquippedBackup = {
            parent = equippedSkins,
            original = value,
            originalParent = value and value.Parent or nil,
            originalValue = value and value:IsA("StringValue") and value.Value or nil,
            originalAttributes = originalAttributes,
        }
    end

    if value and not value:IsA("StringValue") then
        pcall(function() value.Parent = nil end)
        value = nil
    end
    if not value then
        value = Instance.new("StringValue")
        value.Name = "Shedletsky"
        value.Parent = equippedSkins
        S.SkinChanger.artistEquippedCreatedValue = value
    end

    value.Value = skinName
    value:SetAttribute("Skin", skinName)
    value:SetAttribute("UniqueId", "00000000-0000-0000-0000-000000000000")
    value:SetAttribute("E1LU4HUB_SkinChangerOwned", "Artist shedletsky")

    -- Unlock all supported Skin Changer assets at this same activation point.
    if S.SkinChanger.unlockAllAvailableSkins then
        pcall(S.SkinChanger.unlockAllAvailableSkins)
    end

    -- Mirror the existing TwoTime unlock handling: add a Purchased marker only
    -- when the matching asset is not already present.
    if purchasedSkins and not purchasedSkins:FindFirstChild(skinName) then
        local marker = Instance.new("StringValue")
        marker.Name = skinName
        marker.Parent = purchasedSkins
        marker:SetAttribute("E1LU4HUB_SkinChangerOwned", "Artist shedletsky")
        S.SkinChanger.artistPurchasedCreatedValue = marker
    end
    return true, skinName
end

S.SkinChanger.restoreArtistShedletskyEquip = function()
    local backup = S.SkinChanger.artistEquippedBackup
    if not backup then
        -- Recover from a previous run of this script that ended before its
        -- normal cleanup callback could restore the local equipped value.
        local playerData = S.lp and S.lp:FindFirstChild("PlayerData")
        local equipped = playerData and playerData:FindFirstChild("Equipped")
        local equippedSkins = equipped and equipped:FindFirstChild("Skins")
        local current = equippedSkins and equippedSkins:FindFirstChild("Shedletsky")
        if current and current:IsA("StringValue")
            and current:GetAttribute("E1LU4HUB_SkinChangerOwned") == "Artist shedletsky" then
            pcall(function()
                current.Value = ""
                current:SetAttribute("Skin", nil)
                current:SetAttribute("UniqueId", nil)
                current:SetAttribute("E1LU4HUB_SkinChangerOwned", nil)
            end)
        end
        return
    end

    if S.SkinChanger.artistEquipConnection then
        pcall(function() S.SkinChanger.artistEquipConnection:Disconnect() end)
        S.SkinChanger.artistEquipConnection = nil
    end
    if S.SkinChanger.artistEquippedCreatedValue
        and S.SkinChanger.artistEquippedCreatedValue.Parent then
        pcall(function() S.SkinChanger.artistEquippedCreatedValue:Destroy() end)
    end
    if backup.original then
        if backup.original.Parent ~= backup.originalParent and backup.originalParent then
            pcall(function() backup.original.Parent = backup.originalParent end)
        end
        if backup.original:IsA("StringValue") and backup.originalValue ~= nil then
            pcall(function() backup.original.Value = backup.originalValue end)
        end
        local currentAttributes = {}
        pcall(function() currentAttributes = backup.original:GetAttributes() end)
        for name in pairs(currentAttributes) do
            if backup.originalAttributes[name] == nil then
                pcall(function() backup.original:SetAttribute(name, nil) end)
            end
        end
        for name, attributeValue in pairs(backup.originalAttributes) do
            pcall(function() backup.original:SetAttribute(name, attributeValue) end)
        end
    end
    S.SkinChanger.artistEquippedBackup = nil
    S.SkinChanger.artistEquippedCreatedValue = nil
end

S.SkinChanger.updateArtistShedletskyEquip = function()
    local shouldEquip = S.SkinChanger.enabled == true
        and S.SkinChanger.selectedByCharacter
        and S.SkinChanger.selectedByCharacter["Shedletsky"] == "Artist shedletsky"
    if not shouldEquip then
        if S.SkinChanger.artistEquipConnection then
            pcall(function() S.SkinChanger.artistEquipConnection:Disconnect() end)
            S.SkinChanger.artistEquipConnection = nil
        end
        S.SkinChanger.restoreArtistShedletskyEquip()
        return true
    end

    local equipOK = S.SkinChanger.ensureArtistShedletskyEquip()
    if not S.SkinChanger.artistEquipConnection and S.RunService then
        local elapsed = 0
        S.SkinChanger.artistEquipConnection = S.RunService.Heartbeat:Connect(function(deltaTime)
            if S.SkinChanger.enabled ~= true
                or not S.SkinChanger.selectedByCharacter
                or S.SkinChanger.selectedByCharacter["Shedletsky"] ~= "Artist shedletsky" then
                local connection = S.SkinChanger.artistEquipConnection
                S.SkinChanger.artistEquipConnection = nil
                if connection then pcall(function() connection:Disconnect() end) end
                S.SkinChanger.restoreArtistShedletskyEquip()
                return
            end
            elapsed += tonumber(deltaTime) or (1 / 60)
            if elapsed >= 0.2 then
                elapsed = 0
                pcall(S.SkinChanger.ensureArtistShedletskyEquip)
            end
        end)
    end
    return equipOK
end

-- Remove an Artist Equip value left by an interrupted previous run when this
-- run has no saved Artist Shedletsky selection.
if S.SkinChanger.enabled ~= true
    or not S.SkinChanger.selectedByCharacter
    or S.SkinChanger.selectedByCharacter["Shedletsky"] ~= "Artist shedletsky" then
    pcall(S.SkinChanger.restoreArtistShedletskyEquip)
end

-- The default Shedletsky gate also accepts the exact Artist skin that this
-- Skin Changer has equipped, but continues to reject unrelated game skins.
S.SkinChanger.isDefaultShedletsky = function(character)
    if not character or character.Name ~= "Shedletsky" then
        return false
    end

    local playersFolder = workspace:FindFirstChild("Players")
    local spectating = playersFolder and playersFolder:FindFirstChild("Spectating")
    if spectating and S.lp and spectating:FindFirstChild(S.lp.Name) then
        return false
    end

    local mainUI = S.__helpers.getMainUI and S.__helpers.getMainUI()
    local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
    if not abilityContainer or not abilityContainer:FindFirstChild("Slash") then
        return false
    end

    local playerData = S.lp and S.lp:FindFirstChild("PlayerData")
    local equipped = playerData and playerData:FindFirstChild("Equipped")
    local skins = equipped and equipped:FindFirstChild("Skins")
    local equippedSkin = skins and skins:FindFirstChild("Shedletsky")
    if equippedSkin then
        local ok, value = pcall(function() return equippedSkin.Value end)
        local equippedName = tostring(value or "")
        local artistName = resolveArtistShedletskySkinName()
        if ok and equippedName ~= "" and equippedName ~= artistName then
            return false
        end
    end
    return true
end

S.SkinChanger.applyArtistShedletskyToCharacter = function(character)
    if not S.SkinChanger.isDefaultShedletsky(character) then
        return false
    end

    local head = character:FindFirstChild("Head")
    local torso = character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not head or not torso or not humanoid then
        return false
    end

    S.SkinChanger.captureCharacter(character)
    local state = {
        character = character,
        token = tonumber(S.SkinChanger.artistToken) or 0,
        elapsed = 0,
    }
    S.SkinChanger.artistState = state

    -- Replace the default outfit reversibly using the existing skin snapshot.
    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Shirt") or child:IsA("Pants") then
            S.SkinChanger.destroyPreserving(child, character)
        end
    end

    local shirt = Instance.new("Shirt")
    shirt.Name = "E1LU4HUB_ArtistShedletsky_Shirt"
    shirt.ShirtTemplate = "rbxassetid://118042344317053"
    S.SkinChanger.tagArtifact(shirt)
    shirt.Parent = character

    local pants = Instance.new("Pants")
    pants.Name = "E1LU4HUB_ArtistShedletsky_Pants"
    pants.PantsTemplate = "rbxassetid://100561495134250"
    S.SkinChanger.tagArtifact(pants)
    pants.Parent = character

    -- Artist hat mesh, welded at the same offset and rotation as the supplied code.
    local hat = Instance.new("Accessory")
    hat.Name = "E1LU4HUB_ArtistShedletsky_Hat"
    S.SkinChanger.tagArtifact(hat)
    local handle = Instance.new("Part")
    handle.Name = "Handle"
    handle.Size = Vector3.new(1, 1, 1)
    handle.CanCollide = false
    handle.CanTouch = false
    handle.CanQuery = false
    handle.Massless = true
    S.SkinChanger.tagArtifact(handle)
    handle.Parent = hat

    local mesh = Instance.new("SpecialMesh")
    mesh.MeshId = "rbxassetid://102770853506860"
    mesh.TextureId = "rbxassetid://117341189541689"
    S.SkinChanger.tagArtifact(mesh)
    mesh.Parent = handle

    local hatOffset = Vector3.new(0.47, 0.97, 0)
    local hatRotation = Vector3.new(0, -90, 0)
    handle.CFrame = head.CFrame * CFrame.new(hatOffset)
        * CFrame.Angles(math.rad(hatRotation.X), math.rad(hatRotation.Y), math.rad(hatRotation.Z))
    local hatWeld = Instance.new("WeldConstraint")
    hatWeld.Part0 = head
    hatWeld.Part1 = handle
    S.SkinChanger.tagArtifact(hatWeld)
    hatWeld.Parent = handle
    hat.Parent = character

    -- Artist torso mesh.
    local torsoAccessory = Instance.new("Accessory")
    torsoAccessory.Name = "E1LU4HUB_ArtistShedletsky_Torso"
    S.SkinChanger.tagArtifact(torsoAccessory)
    local torsoHandle = Instance.new("Part")
    torsoHandle.Name = "Handle"
    torsoHandle.Size = Vector3.new(2, 2, 1)
    torsoHandle.CanCollide = false
    torsoHandle.CanTouch = false
    torsoHandle.CanQuery = false
    torsoHandle.Massless = true
    S.SkinChanger.tagArtifact(torsoHandle)
    torsoHandle.Parent = torsoAccessory

    local torsoMesh = Instance.new("SpecialMesh")
    torsoMesh.MeshId = "rbxassetid://122893327645752"
    torsoMesh.TextureId = "rbxassetid://104104537744071"
    S.SkinChanger.tagArtifact(torsoMesh)
    torsoMesh.Parent = torsoHandle

    local torsoOffset = Vector3.new(0, -0.34, 0)
    local torsoRotation = Vector3.new(0, -90, 0)
    torsoHandle.CFrame = torso.CFrame * CFrame.new(torsoOffset)
        * CFrame.Angles(math.rad(torsoRotation.X), math.rad(torsoRotation.Y), math.rad(torsoRotation.Z))
    local torsoWeld = Instance.new("WeldConstraint")
    torsoWeld.Part0 = torso
    torsoWeld.Part1 = torsoHandle
    S.SkinChanger.tagArtifact(torsoWeld)
    torsoWeld.Parent = torsoHandle
    torsoAccessory.Parent = character

    -- Four-second alternating footprints, fading/shrinking over one second.
    local worldRootFolder = S.__helpers.getWorldRootFolder()
    local oldEffectFolder = worldRootFolder:FindFirstChild("E1LU4HUB_ArtistShedletskyEffects")
    if oldEffectFolder then pcall(function() oldEffectFolder:Destroy() end) end
    local effectFolder = Instance.new("Folder")
    effectFolder.Name = "E1LU4HUB_ArtistShedletskyEffects"
    effectFolder.Parent = worldRootFolder
    state.effectFolder = effectFolder
    local decalIds = {
        "http://www.roblox.com/asset/?id=17364186013",
        "http://www.roblox.com/asset/?id=17364186013",
    }
    local colors = {
        Color3.fromRGB(255, 0, 255),
        Color3.fromRGB(56, 56, 255),
        Color3.fromRGB(255, 30, 30),
        Color3.fromRGB(255, 255, 40),
        Color3.fromRGB(30, 255, 30),
    }
    local function choose(list)
        return list[math.random(1, #list)]
    end
    local debris = game:GetService("Debris")
    S.SkinChanger.trackConnection(S.RunService.Heartbeat:Connect(function(deltaTime)
        if S.SkinChanger.active ~= "Artist shedletsky"
            or S.SkinChanger.artistState ~= state
            or S.lp.Character ~= character
            or not character.Parent then
            return
        end
        state.elapsed = state.elapsed + (tonumber(deltaTime) or (1 / 60))
        if state.elapsed < 4 then return end
        state.elapsed = 0

        local leftFoot = character:FindFirstChild("LeftFoot") or character:FindFirstChild("Left Leg")
        local rightFoot = character:FindFirstChild("RightFoot") or character:FindFirstChild("Right Leg")
        if not leftFoot or not rightFoot then return end
        local foot = math.random() < 0.5 and leftFoot or rightFoot
        if not foot:IsA("BasePart") then return end

        local splatter = Instance.new("Part")
        splatter.Name = "ArtistShedletskyFootprint"
        splatter.Size = Vector3.new(6, 0.05, 6)
        splatter.Anchored = true
        splatter.CanCollide = false
        splatter.CanTouch = false
        splatter.CanQuery = false
        splatter.Transparency = 1
        splatter.Position = foot.Position - Vector3.new(0, foot.Size.Y / 2 + 0.05, 0)
        S.SkinChanger.tagArtifact(splatter)
        splatter.Parent = effectFolder

        local decal = Instance.new("Decal")
        decal.Face = Enum.NormalId.Top
        decal.Texture = choose(decalIds)
        decal.Color3 = choose(colors)
        S.SkinChanger.tagArtifact(decal)
        decal.Parent = splatter

        local tween = S.TweenService:Create(
            splatter,
            TweenInfo.new(1, Enum.EasingStyle.Linear),
            {Transparency = 1, Size = Vector3.new(0.2, 0.05, 0.2)}
        )
        tween:Play()
        debris:AddItem(splatter, 1.1)
    end))

    -- Replace the default stop animation with the supplied Artist animation.
    local stopAnimationId = "116618003477002"
    local replacementAnimation = Instance.new("Animation")
    replacementAnimation.Name = "E1LU4HUB_ArtistShedletsky_Animation"
    replacementAnimation.AnimationId = "rbxassetid://77448521277146"
    S.SkinChanger.tagArtifact(replacementAnimation)
    replacementAnimation.Parent = character
    state.replacementAnimation = replacementAnimation

    S.SkinChanger.trackConnection(humanoid.AnimationPlayed:Connect(function(animationTrack)
        if S.SkinChanger.active ~= "Artist shedletsky"
            or S.SkinChanger.artistState ~= state then
            return
        end
        local playedAnimation = animationTrack and animationTrack.Animation
        local animationId = playedAnimation and tostring(playedAnimation.AnimationId or "") or ""
        if animationId ~= ("rbxassetid://" .. stopAnimationId)
            and animationId ~= stopAnimationId then
            return
        end
        pcall(function() animationTrack:Stop() end)
        local replacementTrack
        local animator = humanoid:FindFirstChildOfClass("Animator")
        local loaded, result = pcall(function()
            if animator then
                return animator:LoadAnimation(replacementAnimation)
            end
            return humanoid:LoadAnimation(replacementAnimation)
        end)
        if loaded then replacementTrack = result end
        if replacementTrack then
            state.replacementTrack = replacementTrack
            pcall(function() replacementTrack:Play() end)
        end
    end))

    -- Change only the local player's Shedletsky survivor icon and retain its original.
    local token = state.token
    task.spawn(function()
        for _ = 1, 40 do
            if S.SkinChanger.active ~= "Artist shedletsky"
                or S.SkinChanger.artistState ~= state
                or (tonumber(S.SkinChanger.artistToken) or 0) ~= token then
                return
            end
            local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
            local temporaryUI = playerGui and playerGui:FindFirstChild("TemporaryUI")
            local playerInfo = temporaryUI and temporaryUI:FindFirstChild("PlayerInfo")
            local currentSurvivors = playerInfo and playerInfo:FindFirstChild("CurrentSurvivors")
            local shedletskyIcon = currentSurvivors and currentSurvivors:FindFirstChild("Shedletsky")
            local icon = shedletskyIcon and shedletskyIcon:FindFirstChild("Icon")
            local username = shedletskyIcon and shedletskyIcon:FindFirstChild("Username")
            if icon and username
                and (username:IsA("TextLabel") or username:IsA("TextButton"))
                and username.Text == (S.lp.Name .. " (You)") then
                S.SkinChanger.setPlayerIcon("rbxassetid://110965459998666", nil, icon)
                return
            end
            task.wait(0.25)
        end
    end)

    return true
end

-- Generic survivor asset-rig application used by the character-specific
-- entries added below. This follows the supplied second file's normal
-- Skin Changer V2 mapping (Assets.Skins.Survivors/<Character>/<Skin>) while
-- routing removals through this file's reversible snapshot cleanup.
S.SkinChanger.genericSkinDefinitions = S.SkinChanger.genericSkinDefinitions or {}

S.SkinChanger.findGenericSkinRig = function(characterName, folderNames)
    local assets = S.ReplicatedStorage and S.ReplicatedStorage:FindFirstChild("Assets")
    local skins = assets and assets:FindFirstChild("Skins")
    local survivors = skins and skins:FindFirstChild("Survivors")
    if not survivors then error("ReplicatedStorage.Assets.Skins.Survivors was not found") end

    local characterFolderNames = {characterName}
    if characterName == "007n7" then
        table.insert(characterFolderNames, "007N7")
    end

    local characterFolder
    for _, candidate in ipairs(characterFolderNames) do
        characterFolder = survivors:FindFirstChild(candidate)
        if characterFolder then break end
    end
    if not characterFolder then
        error("Survivor skin folder was not found: " .. tostring(characterName))
    end

    local skinFolder
    for _, folderName in ipairs(folderNames or {}) do
        skinFolder = characterFolder:FindFirstChild(folderName)
        if skinFolder then break end
    end
    if not skinFolder then
        error("Skin folder was not found under " .. tostring(characterName) .. ": " .. table.concat(folderNames or {}, " / "))
    end

    local rigs = {}
    for _, descendant in ipairs(skinFolder:GetDescendants()) do
        if descendant:IsA("Model") and (descendant:FindFirstChild("Head")
            or descendant:FindFirstChildOfClass("Humanoid") or descendant:FindFirstChild("Torso")) then
            table.insert(rigs, descendant)
        end
    end
    for _, rig in ipairs(rigs) do
        if rig.Name == "1" or (rig.Parent and rig.Parent.Name == "1") then
            return rig, skinFolder
        end
    end
    if rigs[1] then return rigs[1], skinFolder end
    if skinFolder:FindFirstChild("Head") or skinFolder:FindFirstChild("Torso") then
        return skinFolder, skinFolder
    end
    error("Skin folder contains no valid rig model: " .. tostring(skinFolder.Name))
end

-- Generic skins use the same local Equipped.Skins value pattern as
-- LegacyMS100TwoTime. Each character's original value is preserved so turning
-- Skin Changer OFF or selecting None restores the previous local value.
S.SkinChanger.genericEquippedSkinBackups = S.SkinChanger.genericEquippedSkinBackups or {}
S.SkinChanger.genericEquippedSkinCreatedValues = S.SkinChanger.genericEquippedSkinCreatedValues or {}
S.SkinChanger.genericEquippedNameByCharacter = S.SkinChanger.genericEquippedNameByCharacter or {}

S.SkinChanger.readGenericSkinIcon = function(skinFolder)
    if not skinFolder then return nil end
    local config = skinFolder:FindFirstChild("Config") or skinFolder:FindFirstChild("Config", true)
    if not config or not config:IsA("ModuleScript") then return nil end
    local ok, data = pcall(require, config)
    if not ok or type(data) ~= "table" then return nil end
    local image = data.RenderImage or data.Icon or data.Image or data.Portrait or data.Thumbnail
    if typeof(image) == "number" and image > 0 then
        return "rbxassetid://" .. tostring(math.floor(image))
    end
    if type(image) == "string" and image ~= "" then
        local numeric = tonumber(image)
        if numeric and numeric > 0 then
            return "rbxassetid://" .. tostring(math.floor(numeric))
        end
        return image
    end
    return nil
end

S.SkinChanger.updateGenericSkinIcon = function(characterName, skinFolder)
    local player = S.lp
    local character = player and player.Character
    if not player or not character or character.Name ~= characterName then return false end
    if S.__helpers.getLocalRole and S.__helpers.getLocalRole() ~= "Survivor" then return false end

    local image = S.SkinChanger.readGenericSkinIcon(skinFolder)
    if not image then return false end

    local playerGui = player:FindFirstChildOfClass("PlayerGui")
    local temporaryUI = playerGui and playerGui:FindFirstChild("TemporaryUI")
    local playerInfo = temporaryUI and temporaryUI:FindFirstChild("PlayerInfo")
    if not playerInfo then return false end
    local currentSurvivors = playerInfo:FindFirstChild("CurrentSurvivors")

    local ownUsername = player.Name .. " (You)"
    if currentSurvivors then
        for _, survivorCard in ipairs(currentSurvivors:GetChildren()) do
            local usernameLabel = survivorCard:FindFirstChild("Username", true)
            local icon = survivorCard:FindFirstChild("Icon", true)
            local matches = false
            if usernameLabel and icon then
                pcall(function() matches = usernameLabel.Text == ownUsername end)
            end
            if matches and (icon:IsA("ImageLabel") or icon:IsA("ImageButton")) then
                -- Use the shared original-image store so Skin Changer OFF/None
                -- restores this exact card icon along with the character appearance.
                return S.SkinChanger.setPlayerIcon(image, nil, icon)
            end
        end
    end

    -- Some lobby/UI variants expose the local portrait directly instead of
    -- creating a CurrentSurvivors card immediately. Preserve and update it too.
    local fallbackIcon = playerInfo:FindFirstChild("PlayerIcon", true)
    if fallbackIcon and (fallbackIcon:IsA("ImageLabel") or fallbackIcon:IsA("ImageButton")) then
        return S.SkinChanger.setPlayerIcon(image, nil, fallbackIcon)
    end
    return false
end


S.SkinChanger.genericSkinIconRetryTokens = S.SkinChanger.genericSkinIconRetryTokens or {}
S.SkinChanger.queueGenericSkinIconUpdate = function(characterName, skinFolder)
    local token = (S.SkinChanger.genericSkinIconRetryTokens[characterName] or 0) + 1
    S.SkinChanger.genericSkinIconRetryTokens[characterName] = token
    task.spawn(function()
        for _ = 1, 40 do
            if S.SkinChanger.genericSkinIconRetryTokens[characterName] ~= token then return end
            local character = S.lp and S.lp.Character
            if character and character.Name == characterName then
                if S.SkinChanger.updateGenericSkinIcon(characterName, skinFolder) then return end
            end
            task.wait(0.25)
        end
    end)
end

S.SkinChanger.equipGenericSkin = function(skinKey)
    local definition = S.SkinChanger.genericSkinDefinitions
        and S.SkinChanger.genericSkinDefinitions[skinKey]
    if not definition then return false, "unknown generic skin" end

    local resolved, _, skinFolder = pcall(
        S.SkinChanger.findGenericSkinRig,
        definition.characterName,
        definition.folderNames
    )
    if not resolved or not skinFolder then
        return false, tostring(_ or "skin asset folder is not ready")
    end
    definition.cachedSkinFolder = skinFolder

    local player = S.lp
    local playerData = player and player:FindFirstChild("PlayerData")
    local equipped = playerData and playerData:FindFirstChild("Equipped")
    local equippedSkins = equipped and equipped:FindFirstChild("Skins")
    if not equippedSkins then
        return false, "PlayerData.Equipped.Skins is not available yet"
    end

    local characterName = definition.characterName
    local characterKeyCandidates = {characterName}
    if characterName == "007n7" then
        table.insert(characterKeyCandidates, "007N7")
    end

    -- Prefer a pre-existing Equipped.Skins key. If the game has not created
    -- one, use the exact survivor folder name that contains this skin asset.
    local equippedValueName = nil
    for _, candidate in ipairs(characterKeyCandidates) do
        if equippedSkins:FindFirstChild(candidate) then
            equippedValueName = candidate
            break
        end
    end
    if not equippedValueName then
        equippedValueName = characterName
    end
    definition.equippedValueName = equippedValueName
    S.SkinChanger.genericEquippedNameByCharacter[characterName] = equippedValueName

    local value = equippedSkins:FindFirstChild(equippedValueName)
    local backup = S.SkinChanger.genericEquippedSkinBackups[equippedValueName]
    if not backup then
        local attributes = {}
        if value then pcall(function() attributes = value:GetAttributes() end) end
        backup = {
            parent = equippedSkins,
            original = value,
            originalParent = value and value.Parent or nil,
            originalValue = value and value:IsA("StringValue") and value.Value or nil,
            originalAttributes = attributes,
        }
        S.SkinChanger.genericEquippedSkinBackups[equippedValueName] = backup
    end

    if value and not value:IsA("StringValue") then
        pcall(function() value.Parent = nil end)
        value = nil
    end
    if not value then
        value = Instance.new("StringValue")
        value.Name = equippedValueName
        value.Parent = equippedSkins
        S.SkinChanger.genericEquippedSkinCreatedValues[equippedValueName] = value
    end

    local realSkinName = skinFolder.Name
    value.Value = realSkinName
    value:SetAttribute("Skin", realSkinName)
    value:SetAttribute("UniqueId", "00000000-0000-0000-0000-000000000000")
    value:SetAttribute("E1LU4HUB_SkinChangerOwned", "Generic:" .. characterName)

    -- Update the active survivor's CurrentSurvivors portrait just as the
    -- dedicated TwoTime path does. The saved original image is restored by
    -- S.SkinChanger.restorePlayerIcons when this selection is cleared.
    S.SkinChanger.updateGenericSkinIcon(characterName, skinFolder)
    return true, realSkinName, skinFolder
end


S.SkinChanger.genericSkinEquipRetryTokens = S.SkinChanger.genericSkinEquipRetryTokens or {}
S.SkinChanger.queueGenericSkinEquip = function(skinKey)
    local definition = S.SkinChanger.genericSkinDefinitions
        and S.SkinChanger.genericSkinDefinitions[skinKey]
    if not definition then return false end
    local characterName = definition.characterName
    local token = (S.SkinChanger.genericSkinEquipRetryTokens[characterName] or 0) + 1
    S.SkinChanger.genericSkinEquipRetryTokens[characterName] = token
    task.spawn(function()
        for _ = 1, 40 do
            if S.SkinChanger.genericSkinEquipRetryTokens[characterName] ~= token
                or S.SkinChanger.enabled ~= true
                or not S.SkinChanger.selectedByCharacter
                or S.SkinChanger.selectedByCharacter[characterName] ~= skinKey then
                return
            end
            local callOK, equipOK = pcall(S.SkinChanger.equipGenericSkin, skinKey)
            if callOK and equipOK == true then
                local folder = definition.cachedSkinFolder
                if folder then S.SkinChanger.queueGenericSkinIconUpdate(characterName, folder) end
                return
            end
            task.wait(0.25)
        end
    end)
    return true
end

S.SkinChanger.restoreGenericEquippedSkin = function(characterName)
    local equippedValueName = S.SkinChanger.genericEquippedNameByCharacter[characterName] or characterName
    local backup = S.SkinChanger.genericEquippedSkinBackups[equippedValueName]
    if not backup then return end

    local created = S.SkinChanger.genericEquippedSkinCreatedValues[equippedValueName]
    if created and created.Parent then
        pcall(function() created:Destroy() end)
    end
    if backup.original then
        if backup.original.Parent ~= backup.originalParent and backup.originalParent then
            pcall(function() backup.original.Parent = backup.originalParent end)
        end
        if backup.original:IsA("StringValue") and backup.originalValue ~= nil then
            pcall(function() backup.original.Value = backup.originalValue end)
        end
        local currentAttributes = {}
        pcall(function() currentAttributes = backup.original:GetAttributes() end)
        for name in pairs(currentAttributes) do
            if backup.originalAttributes[name] == nil then
                pcall(function() backup.original:SetAttribute(name, nil) end)
            end
        end
        for name, attributeValue in pairs(backup.originalAttributes) do
            pcall(function() backup.original:SetAttribute(name, attributeValue) end)
        end
    end
    S.SkinChanger.genericEquippedSkinBackups[equippedValueName] = nil
    S.SkinChanger.genericEquippedSkinCreatedValues[equippedValueName] = nil
    S.SkinChanger.genericEquippedNameByCharacter[characterName] = nil
end

S.SkinChanger.restoreAllGenericEquippedSkins = function()
    local names = {}
    local visited = {}

    -- Restore through the original character key first, so aliases such as
    -- Character keys use their canonical in-game names (including JaneDoe).
    for characterName in pairs(S.SkinChanger.genericEquippedNameByCharacter or {}) do
        if not visited[characterName] then
            visited[characterName] = true
            table.insert(names, characterName)
        end
    end

    -- Also clean any orphaned backup left by an interrupted selection change.
    for equippedValueName in pairs(S.SkinChanger.genericEquippedSkinBackups or {}) do
        if not visited[equippedValueName] then
            visited[equippedValueName] = true
            table.insert(names, equippedValueName)
        end
    end

    for _, characterName in ipairs(names) do
        pcall(S.SkinChanger.restoreGenericEquippedSkin, characterName)
    end
end

-- Generic asset skins use the same robust rig-transfer approach as TwoTime's
-- Party skin: preserve the live rig, overlay cloned body parts with welds, and
-- move complete accessory assemblies using source-rig body relationships.
-- This avoids mutating live MeshIds or copying only an accessory's Handle.
S.SkinChanger.applyGenericSpecialRemovals = function(character, characterName, skinFolderName)
    -- Shedletsky Bloodedge and Turking both remove the same live ShedHair instance.
    local shouldRemoveShedHair = characterName == "Shedletsky"
        and (skinFolderName == "BloodedgeShedletsky" or skinFolderName == "TurkingShedletsky")
    local shouldRemoveChanceHat = characterName == "Chance" and skinFolderName == "KingOfPranksChance"
    -- Elliot Valiant removes the Hat from the live Workspace survivor model.
    local shouldRemoveElliotValiantHat = characterName == "Elliot" and skinFolderName == "!ValiantElliot"
    -- Banana Taph removes only the Bandana from the live Workspace survivor model.
    local shouldRemoveTaphBananaBandana = characterName == "Taph" and skinFolderName == "BananaTaph"
    -- Every JaneDoe skin uses the exact Workspace path requested by the user:
    -- workspace.Players.Survivors.JaneDoe.Head.Hat:Destroy().
    local shouldRemoveJaneDoeHeadHat = characterName == "JaneDoe"
    if characterName ~= "Taph" and not shouldRemoveShedHair
        and not shouldRemoveChanceHat and not shouldRemoveElliotValiantHat
        and not shouldRemoveJaneDoeHeadHat then return end

    -- Streamed survivor models can appear after the skin rig. Retry briefly so
    -- the exact live Workspace paths requested are cleaned as soon as present.
    task.spawn(function()
        for _ = 1, 30 do
            local playersFolder = workspace:FindFirstChild("Players")
            local survivorsFolder = playersFolder and playersFolder:FindFirstChild("Survivors")
            local worldCharacter = survivorsFolder and survivorsFolder:FindFirstChild(characterName)
            local targets = {worldCharacter}
            if character and character ~= worldCharacter then table.insert(targets, character) end

            for _, model in ipairs(targets) do
                if model then
                    if characterName == "Taph" then
                        local hood = model:FindFirstChild("HoodOfTheInternationalFellowshipOfBuilders")
                        local handle = hood and hood:FindFirstChild("Handle")
                        if handle then pcall(function() handle:Destroy() end) end
                        -- For Banana only, this resolves to the requested path:
                        -- workspace.Players.Survivors.Taph.Bandana:Destroy().
                        if shouldRemoveTaphBananaBandana and model == worldCharacter then
                            local bandana = worldCharacter:FindFirstChild("Bandana")
                            if bandana then pcall(function() bandana:Destroy() end) end
                        end
                    elseif shouldRemoveShedHair then
                        local shedHair = model:FindFirstChild("ShedHair")
                        if shedHair then pcall(function() shedHair:Destroy() end) end
                    elseif shouldRemoveChanceHat then
                        local hat = model:FindFirstChild("Hat")
                        if hat then pcall(function() hat:Destroy() end) end
                    elseif shouldRemoveElliotValiantHat and model == worldCharacter then
                        -- Exact requested target: workspace.Players.Survivors.Elliot.Hat:Destroy().
                        local hat = worldCharacter:FindFirstChild("Hat")
                        if hat then pcall(function() hat:Destroy() end) end
                    elseif shouldRemoveJaneDoeHeadHat then
                        local head = model:FindFirstChild("Head")
                        local hat = head and head:FindFirstChild("Hat")
                        if hat then pcall(function() hat:Destroy() end) end
                    end
                end
            end
            task.wait(0.15)
        end
    end)
end

