S.SkinChanger.getGenericSkinBodyName = function(sourceObject)
    local originalName = tostring(sourceObject and sourceObject.Name or "")
    local bracketName = originalName:match("%[(.-)%]")
    local allowed = {
        ["Head"] = true, ["Torso"] = true, ["Left Arm"] = true,
        ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
    }
    if bracketName and allowed[bracketName] then return bracketName end

    local handle = sourceObject
    if handle and handle:IsA("Accessory") then
        handle = handle:FindFirstChild("Handle") or handle
    end
    local attachment = handle and handle:FindFirstChildWhichIsA("Attachment")
    local attachmentName = attachment and attachment.Name:lower() or ""
    if attachmentName:find("leftarm") or attachmentName:find("leftshoulder") then return "Left Arm" end
    if attachmentName:find("rightarm") or attachmentName:find("rightshoulder") then return "Right Arm" end
    if attachmentName:find("leftleg") then return "Left Leg" end
    if attachmentName:find("rightleg") then return "Right Leg" end
    if attachmentName:find("body") or attachmentName:find("back") or attachmentName:find("waist")
        or attachmentName:find("chest") then return "Torso" end
    if attachmentName:find("hair") or attachmentName:find("hat") or attachmentName:find("face")
        or attachmentName:find("head") then return "Head" end

    local lower = originalName:lower()
    if lower:find("left pant") or lower:find("left leg") or lower:find("leftfoot") then return "Left Leg" end
    if lower:find("right pant") or lower:find("right leg") or lower:find("rightfoot") then return "Right Leg" end
    if lower:find("left sleeve") or lower:find("left arm") then return "Left Arm" end
    if lower:find("right sleeve") or lower:find("right arm") then return "Right Arm" end
    if lower:find("torso") or lower:find("chest") or lower:find("armor") or lower:find("vest") then return "Torso" end
    return "Head"
end

S.SkinChanger.applyGenericAssetSkinFromFile2 = function(character, characterName, folderNames)
    if not character or character ~= (S.lp and S.lp.Character) or character.Name ~= characterName then
        return false
    end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local targetHead = character:FindFirstChild("Head")
    if not humanoid or not targetHead then
        error("Character rig is not ready: " .. tostring(characterName))
    end

    local sourceRig, skinFolder = S.SkinChanger.findGenericSkinRig(characterName, folderNames)
    local sourceHead = sourceRig:FindFirstChild("Head", true)
    if not sourceHead then error("Skin rig has no Head: " .. tostring(skinFolder.Name)) end
    S.SkinChanger.captureCharacter(character)

    -- Detach the current visual pieces instead of destroying them. The normal
    -- Skin Changer reset path restores these exact instances on selection clear.
    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            -- captureCharacter already made a clothing backup; destroy the live
            -- instance so restoreCharacter recreates exactly one copy from it.
            pcall(function() child:Destroy() end)
        elseif child:IsA("BodyColors") or child:IsA("Accessory") then
            S.SkinChanger.destroyPreserving(child, character)
        end
    end

    for _, descendant in ipairs(sourceRig:GetDescendants()) do
        if descendant:IsA("Shirt") or descendant:IsA("Pants") or descendant:IsA("ShirtGraphic")
            or descendant:IsA("BodyColors") then
            local clone = descendant:Clone()
            S.SkinChanger.tagArtifact(clone)
            clone.Parent = character
        end
    end

    local bodyNames = {
        ["Head"] = true, ["Torso"] = true, ["Left Arm"] = true,
        ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
    }
    local sourceBodyParts = {}
    for bodyName in pairs(bodyNames) do
        sourceBodyParts[bodyName] = sourceRig:FindFirstChild(bodyName, true)
    end

    -- Copy matching classic MeshPart body visuals, while preserving the
    -- original MeshId/TextureID and detaching their old appearance children.
    for bodyName in pairs(bodyNames) do
        local sourcePart = sourceBodyParts[bodyName]
        local targetPart = character:FindFirstChild(bodyName)
        if sourcePart and targetPart and sourcePart:IsA("MeshPart") and targetPart:IsA("MeshPart") then
            targetPart.MeshId = sourcePart.MeshId
            targetPart.TextureID = sourcePart.TextureID
            for _, child in ipairs(targetPart:GetChildren()) do
                if child:IsA("SurfaceAppearance") or child:IsA("Decal") then
                    S.SkinChanger.destroyPreserving(child, character)
                end
            end
            for _, child in ipairs(sourcePart:GetChildren()) do
                if child:IsA("SurfaceAppearance") or child:IsA("Decal") then
                    local clone = child:Clone()
                    S.SkinChanger.tagArtifact(clone)
                    clone.Parent = targetPart
                end
            end
        end
    end

    -- Add non-body parts and accessory handles as welded visual artifacts.
    local candidates = {}
    for _, descendant in ipairs(sourceRig:GetDescendants()) do
        if descendant:IsA("Accessory") then
            table.insert(candidates, descendant)
        elseif descendant:IsA("BasePart") and not bodyNames[descendant.Name]
            and descendant.Name ~= "HumanoidRootPart"
            and not descendant:FindFirstAncestorWhichIsA("Accessory") then
            table.insert(candidates, descendant)
        end
    end

    for _, sourceObject in ipairs(candidates) do
        local sourcePart = sourceObject:IsA("Accessory")
            and (sourceObject:FindFirstChild("Handle") or sourceObject)
            or sourceObject
        if sourcePart and sourcePart:IsA("BasePart") then
            local bodyName = S.SkinChanger.getGenericSkinBodyName(sourceObject)
            local sourceAnchor = sourceRig:FindFirstChild(bodyName, true)
            local targetAnchor = character:FindFirstChild(bodyName)
            if sourceAnchor and sourceAnchor:IsA("BasePart") and targetAnchor and targetAnchor:IsA("BasePart") then
                local clone = sourcePart:Clone()
                clone.Name = "E1LU4HUBGenericSkin_" .. tostring(sourceObject.Name):gsub("[^%w_%-]", "")
                clone.Anchored = false
                clone.CanCollide = false
                clone.CanTouch = false
                clone.CanQuery = false
                for _, child in ipairs(clone:GetDescendants()) do
                    if child:IsA("JointInstance") or child:IsA("WeldConstraint") then
                        pcall(function() child:Destroy() end)
                    end
                end
                local relative = sourceAnchor.CFrame:ToObjectSpace(sourcePart.CFrame)
                clone.CFrame = targetAnchor.CFrame * relative
                S.SkinChanger.tagArtifact(clone)
                clone.Parent = character
                local weld = Instance.new("Weld")
                weld.Name = "E1LU4HUBGenericSkinWeld"
                weld.Part0 = targetAnchor
                weld.Part1 = clone
                weld.C0 = relative
                weld.C1 = CFrame.new()
                weld.Parent = clone
            end
        end
    end

    -- Replace the face decal using the reversible detach/restore path.
    for _, child in ipairs(targetHead:GetChildren()) do
        if child:IsA("Decal") then
            S.SkinChanger.destroyPreserving(child, character)
        end
    end
    local sourceFace = sourceHead:FindFirstChildOfClass("Decal")
    if sourceFace then
        local face = sourceFace:Clone()
        S.SkinChanger.tagArtifact(face)
        face.Parent = targetHead
    end

    -- Keep every existing Destroy cleanup active when a skin uses the file-2
    -- rig pipeline too (Taph hood/Banana bandana, Shedletsky hair, Chance hat,
    -- JaneDoe head hat), and apply Elliot Valiant's requested Hat removal.
    -- The helper itself gates each cleanup to the matching character/skin.
    S.SkinChanger.applyGenericSpecialRemovals(character, characterName, skinFolder.Name)

    return true
end

S.SkinChanger.applyGenericAssetSkin = function(character, characterName, folderNames)
    for _, folderName in ipairs(folderNames or {}) do
        local file2CharacterName = S.SkinChanger.file2GenericSkinFolderCharacter[folderName]
        if file2CharacterName == characterName then
            return S.SkinChanger.applyGenericAssetSkinFromFile2(character, characterName, folderNames)
        end
    end
    if not character or character ~= (S.lp and S.lp.Character) or character.Name ~= characterName then
        return false
    end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid or not character:FindFirstChild("Head") then
        error("Character rig is not ready: " .. tostring(characterName))
    end

    local sourceRig, skinFolder = S.SkinChanger.findGenericSkinRig(characterName, folderNames)
    local sourceHead = sourceRig:FindFirstChild("Head", true)
    if not sourceHead then error("Skin rig has no Head: " .. tostring(skinFolder.Name)) end

    -- Capture every original body-part property, decal transparency and clothing
    -- instance before hiding/detaching anything. The normal OFF/None path restores it.
    S.SkinChanger.captureCharacter(character)

    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic")
            or child:IsA("BodyColors") or child:IsA("Accessory") then
            S.SkinChanger.destroyPreserving(child, character)
        end
    end

    local sourceBodyNameToSlot = {
        ["Head"] = "Head", ["Torso"] = "Torso", ["UpperTorso"] = "Torso",
        ["LowerTorso"] = "Torso", ["Left Arm"] = "Left Arm",
        ["LeftUpperArm"] = "Left Arm", ["LeftLowerArm"] = "Left Arm", ["LeftHand"] = "Left Arm",
        ["Right Arm"] = "Right Arm", ["RightUpperArm"] = "Right Arm",
        ["RightLowerArm"] = "Right Arm", ["RightHand"] = "Right Arm",
        ["Left Leg"] = "Left Leg", ["LeftUpperLeg"] = "Left Leg",
        ["LeftLowerLeg"] = "Left Leg", ["LeftFoot"] = "Left Leg",
        ["Right Leg"] = "Right Leg", ["RightUpperLeg"] = "Right Leg",
        ["RightLowerLeg"] = "Right Leg", ["RightFoot"] = "Right Leg",
    }
    local targetFallbacks = {
        ["Head"] = {"Head"},
        ["Torso"] = {"Torso", "UpperTorso", "LowerTorso"},
        ["Left Arm"] = {"Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand"},
        ["Right Arm"] = {"Right Arm", "RightUpperArm", "RightLowerArm", "RightHand"},
        ["Left Leg"] = {"Left Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot"},
        ["Right Leg"] = {"Right Leg", "RightUpperLeg", "RightLowerLeg", "RightFoot"},
    }
    local function findBasePart(root, name)
        if not root then return nil end
        local direct = root:FindFirstChild(name)
        if direct and direct:IsA("BasePart") then return direct end
        for _, item in ipairs(root:GetDescendants()) do
            if item.Name == name and item:IsA("BasePart")
                and not item:FindFirstAncestorOfClass("Accessory") then
                return item
            end
        end
        return nil
    end
    local function findTargetBody(slot)
        for _, name in ipairs(targetFallbacks[slot] or {slot}) do
            local part = findBasePart(character, name)
            if part and not part:FindFirstAncestorOfClass("Accessory") then return part end
        end
        return nil
    end
    local function sourceSlot(part)
        if not part or not part:IsA("BasePart") then return nil end
        return sourceBodyNameToSlot[part.Name]
    end
    local sourceBodyParts = {}
    for _, descendant in ipairs(sourceRig:GetDescendants()) do
        if descendant:IsA("BasePart") and not descendant:FindFirstAncestorOfClass("Accessory") then
            local slot = sourceSlot(descendant)
            if slot and not sourceBodyParts[slot] then sourceBodyParts[slot] = descendant end
        end
    end
    -- Prefer direct body parts over nested duplicate models.
    for _, bodyName in ipairs({"Head", "Torso", "UpperTorso", "LowerTorso", "Left Arm", "LeftUpperArm", "Left Leg", "LeftUpperLeg", "Right Arm", "RightUpperArm", "Right Leg", "RightUpperLeg"}) do
        local direct = sourceRig:FindFirstChild(bodyName)
        local slot = sourceBodyNameToSlot[bodyName]
        if direct and direct:IsA("BasePart") and slot then
            if bodyName == "Head" or bodyName == "Torso" or not sourceBodyParts[slot] then
                sourceBodyParts[slot] = direct
            end
        end
    end

    local appliedBodyParts = 0
    for slot, sourceBody in pairs(sourceBodyParts) do
        local targetBody = findTargetBody(slot)
        if sourceBody and sourceBody.Parent and targetBody and targetBody.Parent then
            local okClone, bodyClone = pcall(function() return sourceBody:Clone() end)
            if okClone and bodyClone and bodyClone:IsA("BasePart") then
                bodyClone.Name = "E1LU4HUBGenericSkin_Body_" .. tostring(slot):gsub("%W+", "_")
                S.SkinChanger.tagArtifact(bodyClone)
                for _, child in ipairs(bodyClone:GetDescendants()) do
                    if child:IsA("JointInstance") or child:IsA("WeldConstraint")
                        or child:IsA("Constraint") or child:IsA("Script")
                        or child:IsA("LocalScript") or child:IsA("ModuleScript") then
                        pcall(function() child:Destroy() end)
                    end
                end
                bodyClone.CFrame = targetBody.CFrame
                bodyClone.Anchored = false
                bodyClone.CanCollide = false
                bodyClone.CanTouch = false
                bodyClone.CanQuery = false
                bodyClone.Massless = true
                bodyClone.Parent = targetBody.Parent
                local weld = Instance.new("WeldConstraint")
                weld.Name = "E1LU4HUBGenericSkinBodyWeld"
                weld.Part0 = targetBody
                weld.Part1 = bodyClone
                S.SkinChanger.tagArtifact(weld)
                weld.Parent = bodyClone

                targetBody.Transparency = 1
                targetBody.LocalTransparencyModifier = 1
                targetBody.CastShadow = false
                for _, child in ipairs(targetBody:GetDescendants()) do
                    if child:IsA("Decal") or child:IsA("Texture") then
                        pcall(function() child.Transparency = 1 end)
                    end
                end
                appliedBodyParts += 1
            elseif not okClone then
                warn("[E1LU4HUB Skin Changer] Could not clone generic body part: " .. tostring(bodyClone))
            end
        end
    end

    -- Copy one instance of each clothing/body-color class, matching PartyTwoTime.
    local copiedClothing = 0
    for _, className in ipairs({"Shirt", "Pants", "ShirtGraphic", "BodyColors"}) do
        local sourceItem = sourceRig:FindFirstChildOfClass(className)
        if not sourceItem then
            for _, descendant in ipairs(sourceRig:GetDescendants()) do
                if descendant:IsA(className) then sourceItem = descendant; break end
            end
        end
        if sourceItem then
            local clone = sourceItem:Clone()
            S.SkinChanger.tagArtifact(clone)
            clone.Parent = character
            copiedClothing += 1
        end
    end

    local function within(instance, container)
        return instance == container or (instance ~= nil and instance:IsDescendantOf(container))
    end
    local function removeExternalJoints(clone)
        for _, descendant in ipairs(clone:GetDescendants()) do
            if descendant:IsA("JointInstance") or descendant:IsA("WeldConstraint") then
                if not within(descendant.Part0, clone) or not within(descendant.Part1, clone) then
                    pcall(function() descendant:Destroy() end)
                end
            end
        end
    end
    local function prepareAssembly(root)
        for _, descendant in ipairs(root:GetDescendants()) do
            if descendant:IsA("BasePart") then
                descendant.Anchored = false
                descendant.CanCollide = false
                descendant.CanTouch = false
                descendant.CanQuery = false
                descendant.Massless = true
            end
        end
    end
    local function moveAssembly(root, delta)
        local parts = {}
        for _, descendant in ipairs(root:GetDescendants()) do
            if descendant:IsA("BasePart") then
                table.insert(parts, descendant)
                descendant.Anchored = true
            end
        end
        for _, part in ipairs(parts) do part.CFrame = delta * part.CFrame end
        for _, part in ipairs(parts) do part.Anchored = false end
    end
    local function getObjectNameSlot(object)
        local name = tostring(object and object.Name or "")
        local bracket = name:match("%[(.-)%]")
        if bracket and targetFallbacks[bracket] then return bracket end
        local lower = name:lower()
        if lower:find("hair") or lower:find("hat") or lower:find("helmet") or lower:find("head") or lower:find("face") then return "Head" end
        if lower:find("torso") or lower:find("chest") or lower:find("armor") or lower:find("vest") or lower:find("cape") or lower:find("back") or lower:find("waist") then return "Torso" end
        if lower:find("left arm") or lower:find("left sleeve") or lower:find("leftarm") or lower:find("leftshoulder") then return "Left Arm" end
        if lower:find("right arm") or lower:find("right sleeve") or lower:find("rightarm") or lower:find("rightshoulder") then return "Right Arm" end
        if lower:find("left leg") or lower:find("left pant") or lower:find("leftleg") then return "Left Leg" end
        if lower:find("right leg") or lower:find("right pant") or lower:find("rightleg") then return "Right Leg" end
        if lower:find("shield") then return "Left Arm" end
        return nil
    end
    local function inferBodySlot(sourceObject, sourceHandle)
        -- First use the exact source-rig weld relation, like PartyTwoTime.
        for _, joint in ipairs(sourceRig:GetDescendants()) do
            if joint:IsA("JointInstance") or joint:IsA("WeldConstraint") then
                local other = nil
                if joint.Part0 == sourceHandle then other = joint.Part1
                elseif joint.Part1 == sourceHandle then other = joint.Part0 end
                local slot = sourceSlot(other)
                if slot then return slot end
            end
        end
        -- Then match an attachment on the item to the same attachment on a body part.
        local sourceAttachment = sourceHandle and sourceHandle:FindFirstChildWhichIsA("Attachment")
        if sourceAttachment then
            for slot, body in pairs(sourceBodyParts) do
                for _, candidate in ipairs(body:GetDescendants()) do
                    if candidate:IsA("Attachment") and candidate.Name == sourceAttachment.Name then return slot end
                end
            end
        end
        local slot = getObjectNameSlot(sourceObject) or getObjectNameSlot(sourceHandle)
        if slot then return slot end
        -- Ancestor names sometimes carry the [Head]/[Torso] marker.
        local ancestor = sourceObject and sourceObject.Parent
        while ancestor and ancestor ~= sourceRig do
            slot = getObjectNameSlot(ancestor)
            if slot then return slot end
            ancestor = ancestor.Parent
        end
        -- Final fallback: nearest source body slot, with a strict distance cap.
        local nearest, nearestDistance = nil, math.huge
        if sourceHandle then
            for candidateSlot, body in pairs(sourceBodyParts) do
                if body and body.Parent then
                    local distance = (sourceHandle.Position - body.Position).Magnitude
                    if distance < nearestDistance then nearest, nearestDistance = candidateSlot, distance end
                end
            end
        end
        if nearestDistance <= 12 then return nearest end
        return nil
    end

    local objects, seen = {}, {}
    for _, item in ipairs(sourceRig:GetDescendants()) do
        if item:IsA("Accessory") then
            if not seen[item] then seen[item] = true; table.insert(objects, item) end
        elseif item:IsA("BasePart") and not item:FindFirstAncestorOfClass("Accessory")
            and not sourceSlot(item) and item.Name ~= "HumanoidRootPart" then
            if not seen[item] then seen[item] = true; table.insert(objects, item) end
        end
    end

    local attachedAccessories = 0
    for _, sourceObject in ipairs(objects) do
        local sourceHandle = sourceObject:IsA("Accessory")
            and (sourceObject:FindFirstChild("Handle") or sourceObject)
            or sourceObject
        if sourceHandle and sourceHandle:IsA("BasePart") then
            local slot = inferBodySlot(sourceObject, sourceHandle)
            local sourceAnchor = slot and sourceBodyParts[slot]
            local targetAnchor = slot and findTargetBody(slot)
            if sourceAnchor and targetAnchor then
                local cloneRoot
                local handle
                if sourceObject:IsA("Accessory") then
                    cloneRoot = sourceObject:Clone()
                    handle = cloneRoot:FindFirstChild("Handle")
                    if not handle or not handle:IsA("BasePart") then
                        pcall(function() cloneRoot:Destroy() end)
                        cloneRoot, handle = nil, nil
                    end
                else
                    cloneRoot = Instance.new("Accessory")
                    cloneRoot.Name = "E1LU4HUBGenericSkin_" .. tostring(sourceObject.Name):gsub("[^%w_%-]", "")
                    handle = sourceObject:Clone()
                    handle.Name = "Handle"
                    handle.Parent = cloneRoot
                end
                if cloneRoot and handle then
                    cloneRoot.Name = "E1LU4HUBGenericSkin_" .. tostring(sourceObject.Name):gsub("%[.-%]%s*", "")
                    S.SkinChanger.tagArtifact(cloneRoot)
                    removeExternalJoints(cloneRoot)
                    prepareAssembly(cloneRoot)
                    local relativeOffset = sourceAnchor.CFrame:ToObjectSpace(sourceHandle.CFrame)
                    local delta = (targetAnchor.CFrame * relativeOffset) * sourceHandle.CFrame:Inverse()
                    moveAssembly(cloneRoot, delta)
                    local weld = Instance.new("Weld")
                    weld.Name = "E1LU4HUBGenericSkinWeld"
                    weld.Part0 = targetAnchor
                    weld.Part1 = handle
                    weld.C0 = relativeOffset
                    weld.C1 = CFrame.new()
                    S.SkinChanger.tagArtifact(weld)
                    weld.Parent = handle
                    cloneRoot.Parent = character
                    attachedAccessories += 1
                end
            else
                warn("[E1LU4HUB Skin Changer] Could not map generic accessory '" .. tostring(sourceObject.Name) .. "' to a body part")
            end
        end
    end

    -- Party-style portrait handling: read RenderImage from the exact selected
    -- skin Config, then update CurrentSurvivors after applying the rig.
    if type(S.SkinChanger.queueGenericSkinIconUpdate) == "function" then
        S.SkinChanger.queueGenericSkinIconUpdate(characterName, skinFolder)
    else
        S.SkinChanger.updateGenericSkinIcon(characterName, skinFolder)
    end
    S.SkinChanger.applyGenericSpecialRemovals(character, characterName, skinFolder.Name)

    if appliedBodyParts == 0 and copiedClothing == 0 and attachedAccessories == 0 then
        error("Skin rig found, but no body parts, clothing or wearable accessories could be applied: " .. tostring(skinFolder.Name))
    end
    return true
end

S.SkinChanger.apply = function(skinName)
    local genericDefinition = S.SkinChanger.genericSkinDefinitions
        and S.SkinChanger.genericSkinDefinitions[skinName]
    if skinName ~= "Kai 1337 Skin" and skinName ~= "Jason" and skinName ~= "Artist shedletsky"
        and skinName ~= "Admin Noli old" and not genericDefinition then
        return false
    end

    local character = S.lp and S.lp.Character
    if not character then return false end
    if skinName == "Artist shedletsky" then
        if S.SkinChanger.enabled == true and S.SkinChanger.ensureArtistShedletskyEquip then
            pcall(S.SkinChanger.updateArtistShedletskyEquip)
        end
        if not S.SkinChanger.isDefaultShedletsky(character) then
            return false
        end
    end

    S.SkinChanger.deactivate()
    character = S.lp and S.lp.Character
    if not character then return false end

    local applyFunction
    if genericDefinition then
        if character.Name ~= genericDefinition.characterName then return false end
        applyFunction = function(targetCharacter)
            return S.SkinChanger.applyGenericAssetSkin(
                targetCharacter,
                genericDefinition.characterName,
                genericDefinition.folderNames
            )
        end
    elseif skinName == "Kai 1337 Skin" then
        if character.Name ~= "Guest1337" then return false end
        applyFunction = S.SkinChanger.applyKai1337ToCharacter
    elseif skinName == "Jason" then
        if character.Name ~= "Slasher" or (character:GetAttribute("SkinName") or "") ~= "" then
            return false
        end
        if not S.SkinChanger.prepareJason() then return false end
        applyFunction = S.SkinChanger.applyJasonToCharacter
    elseif skinName == "Admin Noli old" then
        if character.Name ~= "Noli"
            or not S.__helpers.isLocalRole
            or not S.__helpers.isLocalRole("Killer")
            or (character:GetAttribute("SkinName") or "") ~= "" then
            return false
        end
        applyFunction = S.SkinChanger.startAdminNoliOld
    else
        if not S.SkinChanger.isDefaultShedletsky(character) then return false end
        applyFunction = S.SkinChanger.applyArtistShedletskyToCharacter
    end

    S.SkinChanger.active = skinName
    S.SkinChanger.activeCharacter = character
    local ok, result = pcall(applyFunction, character)
    if not ok or result == false then
        S.SkinChanger.active = nil
        S.SkinChanger.activeCharacter = nil
        if S.SkinChanger.stopAdminNoliOld then
            pcall(S.SkinChanger.stopAdminNoliOld)
        end
        if S.SkinChanger.clearMorphConnections then S.SkinChanger.clearMorphConnections() end
        if S.SkinChanger.clearArtistEffects then S.SkinChanger.clearArtistEffects() end
        pcall(S.SkinChanger.restoreCharacter, character)
        pcall(S.SkinChanger.restorePlayerIcons)
        warn("[E1LU4HUB Skin Changer] " .. skinName .. " failed: " .. tostring(result))
        return false
    end

    if genericDefinition then
        local equipCallOK, equipOK, equipError = pcall(S.SkinChanger.equipGenericSkin, skinName)
        if not equipCallOK or equipOK ~= true then
            warn("[E1LU4HUB Skin Changer] Generic Equip Skin pending: " .. tostring(equipError or equipOK))
        end
        if S.SkinChanger.queueGenericSkinEquip then
            pcall(S.SkinChanger.queueGenericSkinEquip, skinName)
        end
    end

    S.SkinChanger.respawnConnection = S.lp.CharacterAdded:Connect(function(newCharacter)
        task.defer(function()
            if S.SkinChanger.active ~= skinName then return end
            if genericDefinition and newCharacter.Name ~= genericDefinition.characterName then return end
            if skinName == "Kai 1337 Skin" and newCharacter.Name ~= "Guest1337" then return end
            if skinName == "Jason" and (newCharacter.Name ~= "Slasher"
                or (newCharacter:GetAttribute("SkinName") or "") ~= "") then return end
            if skinName == "Admin Noli old" and (newCharacter.Name ~= "Noli"
                or (newCharacter:GetAttribute("SkinName") or "") ~= "") then return end

            if skinName == "Artist shedletsky" then
                S.SkinChanger.clearMorphConnections()
                S.SkinChanger.clearArtistEffects()
                -- Character UI/ability objects may appear shortly after CharacterAdded.
                for _ = 1, 40 do
                    if S.SkinChanger.active ~= skinName then return end
                    if S.SkinChanger.isDefaultShedletsky(newCharacter)
                        and newCharacter:FindFirstChild("Head")
                        and (newCharacter:FindFirstChild("Torso") or newCharacter:FindFirstChild("UpperTorso"))
                        and newCharacter:FindFirstChildOfClass("Humanoid") then
                        break
                    end
                    task.wait(0.25)
                end
                if S.SkinChanger.active ~= skinName then return end
            end

            local respawnOK, respawnResult = pcall(applyFunction, newCharacter)
            if not respawnOK or respawnResult == false then
                warn("[E1LU4HUB Skin Changer] " .. skinName .. " failed after respawn: " .. tostring(respawnResult))
            else
                S.SkinChanger.activeCharacter = newCharacter
                if genericDefinition then
                    pcall(S.SkinChanger.equipGenericSkin, skinName)
                end
            end
        end)
    end)
    return true
end


-- ================================================================
-- TWOTIME SKINS (integrated into E1LU4HUB Skin Changer)
-- Uses the supplied TwoTime LegacyMS/Artist/Milestone skin rig logic.
-- Selection is stored by the existing Skin Changer; application is gated by
-- Enable Skin Changer + the local Survivor TwoTime character.
-- ================================================================
do
    local T = {}
    S.TwoTimeSkinChanger = T

    local player = S.lp
    local ReplicatedStorage = S.ReplicatedStorage
    local CHARACTER_NAME = "TwoTime"
    local EQUIPPED_SKIN_VALUE_NAME = "TwoTime"
    local ARTIFACT_PREFIX = "E1LU4HUB_TwoTimeAccessory_"
    local WELD_NAME = "E1LU4HUB_TwoTimeSkinWeld"
    local ARTIFACT_ATTRIBUTE = "E1LU4HUBTwoTimeSkinArtifact"

    local AUTO_UNLOCK_SKIN_NAMES = {
        LegacyMS25TwoTime = true,
        LegacyMS50TwoTime = true,
        LegacyMS75TwoTime = true,
        LegacyMS100TwoTime = true,
        ArtistTwoTime = true,
        Milestone100TwoTime = true,
        Milestone100TwoTimeNightshade = true,
        Milestone75TwoTime = true,
        Milestone50TwoTime = true,
        Milestone25TwoTime = true,
    }

    local SKIN_VARIANTS = {
        {label = "LegacyMS25", folderNames = {"LegacyMS25TwoTime", "LegacyMS25"}},
        {label = "LegacyMS50", folderNames = {"LegacyMS50TwoTime", "LegacyMS50"}},
        {label = "LegacyMS75", folderNames = {"LegacyMS75TwoTime", "LegacyMS75"}},
        {label = "LegacyMS100", folderNames = {"LegacyMS100TwoTime", "LegacyMS100"}},
        {label = "!ModeratorTwoTime", folderNames = {"!ModeratorTwoTime"}},
        {label = "ArtistTwoTime", folderNames = {"ArtistTwoTime"}},
        {label = "Milestone100TwoTime", folderNames = {"Milestone100TwoTime"}},
        {label = "Milestone100TwoTimeNightshade", folderNames = {"Milestone100TwoTimeNightshade"}},
        {label = "Milestone75TwoTime", folderNames = {"Milestone75TwoTime"}},
        {label = "Milestone50TwoTime", folderNames = {"Milestone50TwoTime"}},
        {label = "Milestone25TwoTime", folderNames = {"Milestone25TwoTime"}},
        {label = "#VATwoTime", folderNames = {"#VATwoTime"}},
        {label = "AnubisTwoTime", folderNames = {"AnubisTwoTime"}},
        {label = "AssassinTwoTime", folderNames = {"AssassinTwoTime"}},
        {label = "AutumnTwoTime", folderNames = {"AutumnTwoTime"}},
        {label = "BaldTwoTime", folderNames = {"BaldTwoTime"}},
        {label = "BlossomTwoTime", folderNames = {"BlossomTwoTime"}},
        {label = "BossTwoTime", folderNames = {"BossTwoTime"}},
        {label = "CatTwoTime", folderNames = {"CatTwoTime"}},
        {label = "ChristmasTwoTime", folderNames = {"ChristmasTwoTime"}},
        {label = "CloakTwoTime", folderNames = {"CloakTwoTime"}},
        {label = "CupidTwoTime", folderNames = {"CupidTwoTime"}},
        {label = "DoctorWhoTwoTime", folderNames = {"DoctorWhoTwoTime"}},
        {label = "DoubleLifeTwoTime", folderNames = {"DoubleLifeTwoTime"}},
        {label = "FancyTwoTime", folderNames = {"FancyTwoTime"}},
        {label = "FrankentimeTwoTime", folderNames = {"FrankentimeTwoTime"}},
        {label = "FrigidTwoTime", folderNames = {"FrigidTwoTime"}},
        {label = "GhostTwoTime", folderNames = {"GhostTwoTime"}},
        {label = "GhoulTwoTime", folderNames = {"GhoulTwoTime"}},
        {label = "HonestlyTwoTime", folderNames = {"HonestlyTwoTime"}},
        {label = "IceAssassinTwoTime", folderNames = {"IceAssassinTwoTime"}},
        {label = "InvictaTwoTime", folderNames = {"InvictaTwoTime"}},
        {label = "JesterTwoTime", folderNames = {"JesterTwoTime"}},
        {label = "JockTwoTime", folderNames = {"JockTwoTime"}},
        {label = "MonitoringTwoTime", folderNames = {"MonitoringTwoTime"}},
        {label = "MosquitoTwoTime", folderNames = {"MosquitoTwoTime"}},
        {label = "PartyTwoTime", folderNames = {"PartyTwoTime"}},
        {label = "PhoenixTwoTime", folderNames = {"PhoenixTwoTime"}},
        {label = "PlushTwoTime", folderNames = {"PlushTwoTime"}},
        {label = "PrideTwoTime", folderNames = {"PrideTwoTime"}},
        {label = "PrincessTwoTime", folderNames = {"PrincessTwoTime"}},
        {label = "PrinceTwoTime", folderNames = {"PrinceTwoTime"}},
        {label = "PunkTwoTime", folderNames = {"PunkTwoTime"}},
        {label = "SisselTwoTime", folderNames = {"SisselTwoTime"}},
        {label = "SilverthornTwoTime", folderNames = {"SilverthornTwoTime"}},
        {label = "SleepyTwoTime", folderNames = {"SleepyTwoTime"}},
        {label = "SnakeTwoTime", folderNames = {"SnakeTwoTime"}},
        {label = "SoulmatesTwoTime", folderNames = {"SoulmatesTwoTime"}},
        {label = "SpiralTwoTime", folderNames = {"SpiralTwoTime"}},
        {label = "SpringTwoTime", folderNames = {"SpringTwoTime"}},
        {label = "SuperStabbyElfTwoTime", folderNames = {"SuperStabbyElfTwoTime"}},
        {label = "TazunaTwoTime", folderNames = {"TazunaTwoTime"}},
        {label = "WeepingTwoTime", folderNames = {"WeepingTwoTime"}},
        {label = "YinYangTwoTime", folderNames = {"YinYangTwoTime"}},
        {label = "YorickTwoTime", folderNames = {"YorickTwoTime"}},
    }
    local variantByLabel = {}
    for _, variant in ipairs(SKIN_VARIANTS) do
        variantByLabel[variant.label] = variant
    end
    -- Any TwoTime variant added to the selector automatically uses the same
    -- unlock marker and stale-equipped-value cleanup path as LegacyMS100TwoTime.
    for _, variant in ipairs(SKIN_VARIANTS) do
        for _, folderName in ipairs(variant.folderNames or {}) do
            AUTO_UNLOCK_SKIN_NAMES[folderName] = true
        end
    end

    T.variants = SKIN_VARIANTS
    T.isSkin = function(value)
        return type(value) == "string" and variantByLabel[value] ~= nil
    end
    T.isLocalSurvivorTwoTime = function(character)
        character = character or (player and player.Character)
        if not character or character ~= (player and player.Character)
            or character.Name ~= CHARACTER_NAME then
            return false
        end
        local playersFolder = workspace:FindFirstChild("Players")
        local survivorsFolder = playersFolder and playersFolder:FindFirstChild("Survivors")
        return survivorsFolder ~= nil and character:IsDescendantOf(survivorsFolder)
    end

    local V2_BODY_NAMES = {
        ["Head"] = true, ["Torso"] = true, ["Left Arm"] = true,
        ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
        ["HumanoidRootPart"] = true,
    }
    local TARGET_BODY_FALLBACKS = {
        ["Head"] = {"Head"},
        ["Torso"] = {"Torso", "UpperTorso", "LowerTorso"},
        ["Left Arm"] = {"Left Arm", "LeftUpperArm", "LeftLowerArm", "LeftHand"},
        ["Right Arm"] = {"Right Arm", "RightUpperArm", "RightLowerArm", "RightHand"},
        ["Left Leg"] = {"Left Leg", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot"},
        ["Right Leg"] = {"Right Leg", "RightUpperLeg", "RightLowerLeg", "RightFoot"},
        ["HumanoidRootPart"] = {"HumanoidRootPart"},
    }

    -- All game-side Skin Changer unlock markers are created at the same point
    -- as Artist Shedletsky: only after the master switch is ON and a skin has
    -- actually been selected. Nothing is unlocked during script initialization.
    local unlockTaskRunning = false
    local unlockCompleted = false
    S.SkinChanger.unlockAllAvailableSkins = function()
        if S.SkinChanger.enabled ~= true then
            return false, "Skin Changer is disabled"
        end
        local hasSelection = false
        for _, selectedName in pairs(S.SkinChanger.selectedByCharacter or {}) do
            if type(selectedName) == "string" and selectedName ~= "" then
                hasSelection = true
                break
            end
        end
        if not hasSelection then
            return false, "no skin selected"
        end
        if unlockCompleted or unlockTaskRunning then
            return true, unlockCompleted and "already unlocked" or "unlock pending"
        end

        unlockTaskRunning = true
        task.spawn(function()
            local playerData = player and (player:FindFirstChild("PlayerData")
                or player:WaitForChild("PlayerData", 15))
            local purchased = playerData and (playerData:FindFirstChild("Purchased")
                or playerData:WaitForChild("Purchased", 15))
            local purchasedSkins = purchased and (purchased:FindFirstChild("Skins")
                or purchased:WaitForChild("Skins", 15))
            local assets = ReplicatedStorage:FindFirstChild("Assets")
            local skinsRoot = assets and assets:FindFirstChild("Skins")
            if not purchasedSkins or not skinsRoot then
                unlockTaskRunning = false
                return
            end

            -- Re-check the activation condition after PlayerData has finished loading.
            local stillSelected = false
            if S.SkinChanger.enabled == true then
                for _, selectedName in pairs(S.SkinChanger.selectedByCharacter or {}) do
                    if type(selectedName) == "string" and selectedName ~= "" then
                        stillSelected = true
                        break
                    end
                end
            end
            if not stillSelected then
                unlockTaskRunning = false
                return
            end

            local wantedNames = table.clone(AUTO_UNLOCK_SKIN_NAMES)
            -- Include every skin exposed by the shared survivor selector. These
            -- names are resolved from the actual Assets.Skins tree at runtime.
            for _, definition in pairs(S.SkinChanger.genericSkinDefinitions or {}) do
                for _, folderName in ipairs(definition.folderNames or {}) do
                    wantedNames[folderName] = true
                end
            end
            local artistName = S.SkinChanger.getArtistShedletskySkinName
                and S.SkinChanger.getArtistShedletskySkinName()
            if type(artistName) == "string" and artistName ~= "" then
                wantedNames[artistName] = true
            end

            local found = {}
            for _, skin in ipairs(skinsRoot:GetDescendants()) do
                if (skin:IsA("Folder") or skin:IsA("Model")) and wantedNames[skin.Name] then
                    found[skin.Name] = true
                    if not purchasedSkins:FindFirstChild(skin.Name) then
                        local marker = Instance.new("StringValue")
                        marker.Name = skin.Name
                        marker:SetAttribute("E1LU4HUB_SkinChangerUnlockOwned", true)
                        marker.Parent = purchasedSkins
                    end
                end
            end

            local missing = {}
            for skinName in pairs(wantedNames) do
                if not found[skinName] then
                    table.insert(missing, skinName)
                end
            end
            if #missing > 0 then
                warn("[E1LU4HUB Skin Changer] Skin assets not found: " .. table.concat(missing, ", "))
            end

            unlockCompleted = next(found) ~= nil
            unlockTaskRunning = false
        end)
        return true, "unlock started"
    end

    local getSkinRig = function(skinFolderNames)
        local assets = ReplicatedStorage:FindFirstChild("Assets") or ReplicatedStorage:WaitForChild("Assets", 10)
        if not assets then error("ReplicatedStorage.Assets was not found") end
        local skins = assets:FindFirstChild("Skins") or assets:WaitForChild("Skins", 10)
        if not skins then error("ReplicatedStorage.Assets.Skins was not found") end
        local survivors = skins:FindFirstChild("Survivors") or skins:WaitForChild("Survivors", 10)
        if not survivors then error("ReplicatedStorage.Assets.Skins.Survivors was not found") end
        local characterFolder = survivors:FindFirstChild(CHARACTER_NAME) or survivors:WaitForChild(CHARACTER_NAME, 10)
        if not characterFolder then error("TwoTime skin folder was not found") end

        local skinFolder
        for _, folderName in ipairs(skinFolderNames or {}) do
            skinFolder = characterFolder:FindFirstChild(folderName)
            if skinFolder then break end
        end
        if not skinFolder then
            error("Skin folder was not found under TwoTime: " .. table.concat(skinFolderNames or {}, " / "))
        end
        local rigs = {}
        for _, descendant in ipairs(skinFolder:GetDescendants()) do
            if descendant:IsA("Model") and (descendant:FindFirstChild("Head")
                or descendant:FindFirstChildOfClass("Humanoid") or descendant:FindFirstChild("Torso")) then
                table.insert(rigs, descendant)
            end
        end
        for _, rig in ipairs(rigs) do
            if rig.Name == "1" or (rig.Parent and rig.Parent.Name == "1") then
                return rig, skinFolder.Name, skinFolder
            end
        end
        if rigs[1] then return rigs[1], skinFolder.Name, skinFolder end
        error(tostring(skinFolder.Name) .. " contains no valid rig model (Head/Humanoid/Torso)")
    end

    local isSkinArtifact = function(item)
        if not item then return false end
        local marked = false
        pcall(function() marked = item:GetAttribute(ARTIFACT_ATTRIBUTE) == true end)
        return marked or tostring(item.Name):sub(1, #ARTIFACT_PREFIX) == ARTIFACT_PREFIX
    end
    local function removePreviousSkin(character)
        if not character then return end
        local toRemove = {}
        for _, item in ipairs(character:GetDescendants()) do
            if isSkinArtifact(item) or item.Name == WELD_NAME then table.insert(toRemove, item) end
        end
        for _, item in ipairs(character:GetChildren()) do
            if isSkinArtifact(item) or item.Name == WELD_NAME then table.insert(toRemove, item) end
        end
        for _, item in ipairs(toRemove) do
            if item.Parent then pcall(function() item:Destroy() end) end
        end
    end

    -- BEGIN: attachment and life-rig helpers reused from TwoTime v20.
local function findBasePart(parent, name)
    if not parent then return nil end

    -- Prefer a direct rig body part. This avoids accidentally selecting a
    -- nested accessory/extra part that happens to share the same name.
    local direct = parent:FindFirstChild(name)
    if direct and direct:IsA("BasePart") then
        return direct
    end

    for _, item in ipairs(parent:GetDescendants()) do
        if item.Name == name and item:IsA("BasePart")
            and not item:FindFirstAncestorOfClass("Accessory") then
            return item
        end
    end
    return nil
end

local function findTargetBodyPart(character, bodyName)
    for _, name in ipairs(TARGET_BODY_FALLBACKS[bodyName] or {bodyName}) do
        local part = findBasePart(character, name)
        if part and not part:FindFirstAncestorOfClass("Accessory") then
            return part
        end
    end
    return nil
end

local function mapAttachmentNameToBody(attachmentName)
    local name = tostring(attachmentName or ""):lower()
    if name:find("hair") or name:find("hat") or name:find("face") or name:find("head") then
        return "Head"
    elseif name:find("body") or name:find("back") or name:find("waist") or name:find("chest") or name:find("neck") then
        return "Torso"
    elseif name:find("leftarm") or name:find("leftshoulder") then
        return "Left Arm"
    elseif name:find("rightarm") or name:find("rightshoulder") then
        return "Right Arm"
    elseif name:find("leftleg") then
        return "Left Leg"
    elseif name:find("rightleg") then
        return "Right Leg"
    end
    return nil
end

-- Determine the matching live body slot from an explicit [BodyPart] marker,
-- a direct Attachment name, or the wearable's descriptive name.
local function getBodySlotName(object)
    local objectName = tostring(object.Name or "")
    local bracketName = objectName:match("%[(.-)%]")
    if bracketName and V2_BODY_NAMES[bracketName] then
        return bracketName
    end

    local attachmentContainer = object
    if object:IsA("Accessory") then
        attachmentContainer = object:FindFirstChild("Handle") or object
    end

    local attachment = attachmentContainer:FindFirstChildWhichIsA("Attachment")
    if attachment then
        local mapped = mapAttachmentNameToBody(attachment.Name)
        if mapped then return mapped end
    end

    local name = objectName:lower()
    if name:find("helmet") or name:find("hat") or name:find("hair") or name:find("antenna") then
        return "Head"
    elseif name:find("torso") or name:find("chest") or name:find("armor") or name:find("vest") then
        return "Torso"
    elseif name:find("left pant") or name:find("left leg") then
        return "Left Leg"
    elseif name:find("right pant") or name:find("right leg") then
        return "Right Leg"
    elseif name:find("left sleeve") or name:find("left arm") then
        return "Left Arm"
    elseif name:find("right sleeve") or name:find("right arm") then
        return "Right Arm"
    elseif name:find("shield") then
        return "Left Arm"
    end

    -- Unlabelled wearable pieces use the same Head fallback as the source Skin Changer.
    return "Head"
end

local function isSkinArtifact(item)
    if not item then return false end
    local marked = false
    pcall(function()
        marked = item:GetAttribute(ARTIFACT_ATTRIBUTE) == true
    end)
    return marked or item.Name:sub(1, #ARTIFACT_PREFIX) == ARTIFACT_PREFIX
end

local function removePreviousSkin(character)
    -- Remove only objects made by this one-button skin applier (and leftovers
    -- from previous one-button versions). Do not delete the player's unrelated accessories.
    local toRemove = {}
    for _, item in ipairs(character:GetDescendants()) do
        if isSkinArtifact(item) or item.Name == WELD_NAME then
            table.insert(toRemove, item)
        end
    end
    for _, item in ipairs(toRemove) do
        if item.Parent then
            pcall(function() item:Destroy() end)
        end
    end

end

local function copySkinClothing(sourceRig, character)
    local replaced = 0
    for _, className in ipairs({"Shirt", "Pants", "ShirtGraphic", "BodyColors"}) do
        local sourceItem = sourceRig:FindFirstChildOfClass(className)
        if not sourceItem then
            for _, descendant in ipairs(sourceRig:GetDescendants()) do
                if descendant:IsA(className) then
                    sourceItem = descendant
                    break
                end
            end
        end

        if sourceItem then
            -- Match the non-V2 replacePresetClothing behavior: remove the old
            -- class first, then parent a fresh skin copy to the live character.
            for _, old in ipairs(character:GetChildren()) do
                if old:IsA(className) then
                    old:Destroy()
                end
            end
            local copy = sourceItem:Clone()
            pcall(function() copy:SetAttribute(ARTIFACT_ATTRIBUTE, true) end)
            copy.Parent = character
            replaced += 1
        end
    end
    return replaced
end

-- Reproduce the normal (non-V2) Skin Changer's addPresetMeshAccessory pattern:
-- create an Accessory + Handle, position the Handle relative to the correct
-- body part, then Weld with Part0=bodyPart, Part1=Handle, C0=relativeOffset.
-- Do NOT use V2's attachment-name remapping or Humanoid:AddAccessory solver.

local SOURCE_BODY_PART_NAMES = {
    Head = "Head",
    Torso = "Torso",
    UpperTorso = "Torso",
    LowerTorso = "Torso",
    ["Left Arm"] = "Left Arm",
    LeftUpperArm = "Left Arm",
    LeftLowerArm = "Left Arm",
    LeftHand = "Left Arm",
    ["Right Arm"] = "Right Arm",
    RightUpperArm = "Right Arm",
    RightLowerArm = "Right Arm",
    RightHand = "Right Arm",
    ["Left Leg"] = "Left Leg",
    LeftUpperLeg = "Left Leg",
    LeftLowerLeg = "Left Leg",
    LeftFoot = "Left Leg",
    ["Right Leg"] = "Right Leg",
    RightUpperLeg = "Right Leg",
    RightLowerLeg = "Right Leg",
    RightFoot = "Right Leg",
}

local function getSourceBodySlot(part)
    if not part or not part:IsA("BasePart") then return nil end
    return SOURCE_BODY_PART_NAMES[part.Name]
end

local function getBodyFromName(object)
    if not object then return nil end
    local name = tostring(object.Name or "")
    local marker = name:match("%[(.-)%]")
    if marker and SOURCE_BODY_PART_NAMES[marker] then
        return SOURCE_BODY_PART_NAMES[marker]
    end

    local lowered = name:lower()
    if lowered:find("hair") or lowered:find("hat") or lowered:find("helmet")
        or lowered:find("head") or lowered:find("face") then
        return "Head"
    elseif lowered:find("torso") or lowered:find("chest") or lowered:find("armor")
        or lowered:find("vest") or lowered:find("cape") or lowered:find("back") then
        return "Torso"
    elseif lowered:find("left arm") or lowered:find("left sleeve") or lowered:find("leftarm") then
        return "Left Arm"
    elseif lowered:find("right arm") or lowered:find("right sleeve") or lowered:find("rightarm") then
        return "Right Arm"
    elseif lowered:find("left leg") or lowered:find("left pant") or lowered:find("leftleg") then
        return "Left Leg"
    elseif lowered:find("right leg") or lowered:find("right pant") or lowered:find("rightleg") then
        return "Right Leg"
    elseif lowered:find("shield") then
        return "Left Arm"
    end
    return nil
end

local function getBodyFromAttachment(sourceRig, anchorPart)
    for _, attachment in ipairs(anchorPart:GetChildren()) do
        if attachment:IsA("Attachment") then
            for _, candidate in ipairs(sourceRig:GetDescendants()) do
                if candidate:IsA("BasePart") and candidate ~= anchorPart
                    and not candidate:FindFirstAncestorOfClass("Accessory") then
                    local matching = candidate:FindFirstChild(attachment.Name)
                    if matching and matching:IsA("Attachment") then
                        local slot = getSourceBodySlot(candidate)
                        if slot then return slot end
                    end
                end
            end
        end
    end
    return nil
end

local function getBodyFromJoint(sourceRig, anchorPart)
    for _, descendant in ipairs(sourceRig:GetDescendants()) do
        if descendant:IsA("JointInstance") or descendant:IsA("WeldConstraint") then
            local otherPart
            if descendant.Part0 == anchorPart then
                otherPart = descendant.Part1
            elseif descendant.Part1 == anchorPart then
                otherPart = descendant.Part0
            end
            local slot = getSourceBodySlot(otherPart)
            if slot then return slot end
        end
    end
    return nil
end

local function collectSourceBodyParts(sourceRig)
    local parts = {}
    for _, descendant in ipairs(sourceRig:GetDescendants()) do
        if descendant:IsA("BasePart") and not descendant:FindFirstAncestorOfClass("Accessory") then
            local slot = getSourceBodySlot(descendant)
            if slot and not parts[slot] then
                parts[slot] = descendant
            end
        end
    end
    -- Direct rig body parts take precedence over nested cosmetic/body copies.
    for name, slot in pairs(SOURCE_BODY_PART_NAMES) do
        local direct = sourceRig:FindFirstChild(name)
        if direct and direct:IsA("BasePart") then
            parts[slot] = direct
        end
    end
    return parts
end

local function getNearestSourceBodySlot(sourceBodyParts, part)
    local nearestSlot, nearestDistance = nil, math.huge
    for slot, sourceBody in pairs(sourceBodyParts) do
        if sourceBody and sourceBody.Parent then
            local distance = (part.Position - sourceBody.Position).Magnitude
            if distance < nearestDistance then
                nearestDistance, nearestSlot = distance, slot
            end
        end
    end
    -- Never attach arbitrary distant effects/props to the Head as a fallback.
    if nearestDistance <= 12 then return nearestSlot end
    return nil
end

local function inferSourceBodySlot(sourceRig, sourcePart, sourceAnchor, descriptionObject, sourceBodyParts)
    -- First trust the source rig's own Weld/AccessoryWeld relationship.
    local slot = getBodyFromJoint(sourceRig, sourceAnchor)
        or getBodyFromAttachment(sourceRig, sourceAnchor)
        or getBodyFromName(descriptionObject)
        or getBodyFromName(sourcePart)
    if slot then return slot end

    -- Some wearable models keep their body marker on a parent Model/Folder.
    local ancestor = sourcePart.Parent
    while ancestor and ancestor ~= sourceRig do
        slot = getBodyFromName(ancestor)
        if slot then return slot end
        ancestor = ancestor.Parent
    end

    -- Last resort: use the closest source-rig limb, not an arbitrary Head weld.
    return getNearestSourceBodySlot(sourceBodyParts, sourcePart)
end

local function isWithin(instance, container)
    return instance == container or (instance ~= nil and instance:IsDescendantOf(container))
end

local function removeExternalJoints(clone)
    -- Preserve joints between parts inside this cloned accessory, but remove
    -- source-rig joints so no clone can remain connected to the asset rig.
    for _, descendant in ipairs(clone:GetDescendants()) do
        if descendant:IsA("JointInstance") or descendant:IsA("WeldConstraint") then
            if not isWithin(descendant.Part0, clone) or not isWithin(descendant.Part1, clone) then
                descendant:Destroy()
            end
        end
    end
end

local function prepareAccessory(accessory)
    for _, descendant in ipairs(accessory:GetDescendants()) do
        if descendant:IsA("BasePart") then
            descendant.Anchored = false
            descendant.CanCollide = false
            descendant.CanTouch = false
            descendant.CanQuery = false
            descendant.Massless = true
        end
    end
end

local function moveAssembly(accessory, delta)
    -- Move every cloned physical piece by the same rigid transform so internal
    -- joints retain their exact relative positions from the source skin rig.
    local parts = {}
    for _, descendant in ipairs(accessory:GetDescendants()) do
        if descendant:IsA("BasePart") then
            table.insert(parts, descendant)
            descendant.Anchored = true
        end
    end
    for _, part in ipairs(parts) do
        part.CFrame = delta * part.CFrame
    end
    for _, part in ipairs(parts) do
        part.Anchored = false
    end
end

local function buildAccessoryClone(sourceObject)
    if sourceObject:IsA("Accessory") then
        local clone = sourceObject:Clone()
        local handle = clone:FindFirstChild("Handle")
        if not handle or not handle:IsA("BasePart") then
            clone:Destroy()
            return nil, nil
        end
        clone.Name = ARTIFACT_PREFIX .. tostring(sourceObject.Name):gsub("%[.-%]%s*", "")
        pcall(function() clone:SetAttribute(ARTIFACT_ATTRIBUTE, true) end)
        removeExternalJoints(clone)
        prepareAccessory(clone)
        return clone, handle
    elseif sourceObject:IsA("BasePart") then
        local accessory = Instance.new("Accessory")
        accessory.Name = ARTIFACT_PREFIX .. tostring(sourceObject.Name):gsub("%[.-%]%s*", "")
        pcall(function() accessory:SetAttribute(ARTIFACT_ATTRIBUTE, true) end)
        local handle = sourceObject:Clone()
        handle.Name = "Handle"
        removeExternalJoints(handle)
        handle.Parent = accessory
        prepareAccessory(accessory)
        return accessory, handle
    end
    return nil, nil
end

local function attachLikeNormalSkinChanger(sourceRig, character, sourceObject, sourceBodyParts, variantLabel)
    local sourceAccessory = sourceObject:IsA("Accessory") and sourceObject or nil
    local sourceHandle = sourceAccessory and sourceAccessory:FindFirstChild("Handle") or sourceObject
    if not sourceHandle or not sourceHandle:IsA("BasePart") then
        return false, "missing source Handle/BasePart"
    end

    local bodySlot = inferSourceBodySlot(
        sourceRig,
        sourceHandle,
        sourceHandle,
        sourceAccessory or sourceObject,
        sourceBodyParts
    )
    local sourceBody = bodySlot and sourceBodyParts[bodySlot]
    local targetBody = bodySlot and findTargetBodyPart(character, bodySlot)
    if not sourceBody or not targetBody then
        return false, "could not match source body part"
    end

    local accessory, handle = buildAccessoryClone(sourceObject)
    if not accessory or not handle then
        return false, "could not clone accessory Handle"
    end

    -- Keep every cloned add-on at its original source-rig position. ArtistTwoTime's
    -- original torso/leg Robe pieces are detached when the variant is applied.
    local relativeOffset = sourceBody.CFrame:ToObjectSpace(sourceHandle.CFrame)
    local delta = (targetBody.CFrame * relativeOffset) * sourceHandle.CFrame:Inverse()
    moveAssembly(accessory, delta)

    -- This is the normal Skin Changer's non-V2 addPresetMeshAccessory weld
    -- arrangement, not the V2 attachment solver:
    -- bodyPart -> Handle, C0 = body-relative position, C1 = identity.
    local weld = Instance.new("Weld")
    weld.Name = WELD_NAME
    weld.Part0 = targetBody
    weld.Part1 = handle
    weld.C0 = relativeOffset
    weld.C1 = CFrame.new()
    pcall(function() weld:SetAttribute(ARTIFACT_ATTRIBUTE, true) end)
    weld.Parent = handle

    accessory.Parent = character
    return true, bodySlot
end

local function isLife1WingObject(item, sourceRig, lifeName)
    -- Life1 never receives wings. Life2 keeps the matching skin's wing pieces.
    if lifeName ~= "Life1" then return false end
    local current = item
    while current and current ~= sourceRig do
        local name = tostring(current.Name or ""):lower()
        if name == "wing1" or name == "wing2" then
            return true
        end
        current = current.Parent
    end
    return false
end

local function copyAndWearSkinAccessories(sourceRig, character, lifeName, variantLabel)
    local sourceBodyParts = collectSourceBodyParts(sourceRig)
    local objects = {}
    local seen = {}

    -- Handle each Accessory as a complete assembly. Any standalone BasePart
    -- (the normal Skin Changer's scAccs/scCreatePart style) becomes a one-Handle
    -- Accessory, still welded directly to its corresponding live body part.
    -- Life1 omits wing1/wing2. Life2 can receive its own matching wing pieces.
    for _, item in ipairs(sourceRig:GetDescendants()) do
        if not isLife1WingObject(item, sourceRig, lifeName) then
            if item:IsA("Accessory") then
                if not seen[item] then
                    seen[item] = true
                    table.insert(objects, item)
                end
            elseif item:IsA("BasePart") then
                local insideAccessory = item:FindFirstAncestorOfClass("Accessory") ~= nil
                local bodyPart = not insideAccessory and getSourceBodySlot(item) ~= nil
                if not insideAccessory and not bodyPart and item.Name ~= "HumanoidRootPart" and not seen[item] then
                    seen[item] = true
                    table.insert(objects, item)
                end
            end
        end
    end

    local attached = 0
    local headAttached = 0
    local skipped = 0
    local byBody = {}
    for _, object in ipairs(objects) do
        local ok, bodyOrError = attachLikeNormalSkinChanger(
            sourceRig, character, object, sourceBodyParts, variantLabel
        )
        if ok then
            attached += 1
            byBody[bodyOrError] = (byBody[bodyOrError] or 0) + 1
            if bodyOrError == "Head" then headAttached += 1 end
        else
            skipped += 1
            warn("[TwoTime Skin] Skipped '" .. tostring(object.Name) .. "': " .. tostring(bodyOrError))
        end
    end

    return attached, headAttached, skipped, byBody
end

-- Remove the original TwoTime cosmetics from the nested Life1 and Life2 rigs
-- before each variant is applied. The main TwoTime rig is intentionally left
-- untouched. Missing objects are ignored so one absent cosmetic does not stop
-- the skin switch.
local ORIGINAL_TWOTIME_COSMETICS = {
    {body = "Head",      items = {"Hair_Front"}},
    {body = "Left Arm",  items = {"Left Cloak", "Left Glove", "Left Sleeve"}},
    {body = "Left Leg",  items = {"Left Robe"}},
    {body = "Right Arm", items = {"Right Cloak", "Right Glove", "Right Sleeve"}},
    {body = "Right Leg", items = {"Right Robe"}},
    {body = "Torso",     items = {"Belt", "Cloak", "Robe", "Scarf", "graphic", "tail", "wing1", "wing2"}},
}


local function isLifeContainer(instance)
    return instance and (instance:IsA("Model") or instance:IsA("Folder"))
end

local function hasLifeBody(instance)
    return isLifeContainer(instance)
        and findBasePart(instance, "Head") ~= nil
        and (findBasePart(instance, "Torso") ~= nil
            or findBasePart(instance, "UpperTorso") ~= nil
            or findBasePart(instance, "LowerTorso") ~= nil)
end

local function findNamedLifeRig(root, lifeName)
    if not root then return nil end
    local candidates = {}
    if isLifeContainer(root) and root.Name == lifeName then
        table.insert(candidates, root)
    end
    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant.Name == lifeName and isLifeContainer(descendant) then
            table.insert(candidates, descendant)
        end
    end

    for _, candidate in ipairs(candidates) do
        -- Some assets wrap the actual rig inside a same-named Life folder.
        for _, nested in ipairs(candidate:GetDescendants()) do
            if nested:IsA("Model") and nested:FindFirstChild("Head")
                and (nested:FindFirstChild("Torso") or nested:FindFirstChild("UpperTorso")
                    or nested:FindFirstChild("LowerTorso")) then
                return nested
            end
        end
        if hasLifeBody(candidate) then return candidate end
    end
    return nil
end

local function findLifeTargets(root)
    local entries = {}
    if not root then return entries end
    for _, lifeName in ipairs({"Life1", "Life2"}) do
        local lifeRig = findNamedLifeRig(root, lifeName)
        if lifeRig and lifeRig ~= root then
            table.insert(entries, {target = lifeRig, lifeName = lifeName})
        end
    end
    return entries
end

local function normalizeLifeValue(value)
    if value == nil then return nil end
    if type(value) == "number" then
        if value >= 2 then return "Life2" end
        if value >= 1 then return "Life1" end
    end
    local text = tostring(value):lower()
    if text == "2" or text:find("life2", 1, true) or text:find("second", 1, true) then
        return "Life2"
    end
    if text == "1" or text:find("life1", 1, true) or text:find("first", 1, true) then
        return "Life1"
    end
    return nil
end

local function detectCurrentLife(root)
    local valueNames = {
        "CurrentLife", "ActiveLife", "Life", "LifeState", "LifeNumber",
        "CurrentLives", "TwoTimeLife", "Lives",
    }
    local roots = {root, player}
    for _, searchRoot in ipairs(roots) do
        if searchRoot then
            for _, name in ipairs(valueNames) do
                local attributeValue
                pcall(function() attributeValue = searchRoot:GetAttribute(name) end)
                local normalized = normalizeLifeValue(attributeValue)
                if normalized then return normalized end

                local valueObject = searchRoot:FindFirstChild(name, true)
                if valueObject and (valueObject:IsA("StringValue")
                    or valueObject:IsA("IntValue") or valueObject:IsA("NumberValue")) then
                    normalized = normalizeLifeValue(valueObject.Value)
                    if normalized then return normalized end
                end
            end
            for _, flagName in ipairs({"IsLife2", "SecondLife", "Life2Active"}) do
                local flag
                pcall(function() flag = searchRoot:GetAttribute(flagName) end)
                if flag == true then return "Life2" end
            end
        end
    end
    -- The default is Life1 only when the game exposes no life marker and no
    -- nested Life1/Life2 rigs. When the nested rigs exist, both are handled.
    return "Life1"
end

-- Resolve targets strictly from the local player's own active Survivor TwoTime.
-- Never search workspace by character name: another player's TwoTime can have
-- the same name and must not be changed by this client-side Skin Changer.
local function resolveTargetEntries()
    local character = player and player.Character
    if not T.isLocalSurvivorTwoTime(character) then
        return nil, {}
    end

    local entries = findLifeTargets(character)
    if #entries > 0 then
        return character, entries
    end

    if not character.Parent then return nil, {} end
    return character, {{target = character, lifeName = detectCurrentLife(character)}}
end

local function countSkinArtifacts(target)
    local count = 0
    for _, item in ipairs(target:GetDescendants()) do
        if isSkinArtifact(item) then count += 1 end
    end
    return count
end

local function collectTargetBodyRefs(target)
    local refs = {}
    for bodyName, _ in pairs(TARGET_BODY_FALLBACKS) do
        refs[bodyName] = findTargetBodyPart(target, bodyName)
    end
    return refs
end

local appliedTargets = setmetatable({}, {__mode = "k"})

local function findNumberedLifeRig(root, lifeName)
    if not root then return nil end
    local wantedNumber = lifeName == "Life2" and "2" or "1"

    if root:IsA("Model") and root.Name == wantedNumber
        and (root:FindFirstChild("Head") or root:FindFirstChild("Torso")
            or root:FindFirstChildOfClass("Humanoid")) then
        return root
    end

    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant:IsA("Model")
            and (descendant.Name == wantedNumber
                or (descendant.Parent and descendant.Parent.Name == wantedNumber))
            and (descendant:FindFirstChild("Head") or descendant:FindFirstChild("Torso")
                or descendant:FindFirstChildOfClass("Humanoid")) then
            return descendant
        end
    end
    return nil
end


    -- Original TwoTime pieces are detached, not destroyed, so Skin Changer OFF
    -- and switching to another skin can restore the exact original instances.
    local ORIGINAL_TWOTIME_COSMETICS = {
        {body = "Head", items = {"Hair_Front"}},
        {body = "Left Arm", items = {"Left Cloak", "Left Glove", "Left Sleeve"}},
        {body = "Left Leg", items = {"Left Robe"}},
        {body = "Right Arm", items = {"Right Cloak", "Right Glove", "Right Sleeve"}},
        {body = "Right Leg", items = {"Right Robe"}},
        {body = "Torso", items = {"Belt", "Cloak", "Robe", "Scarf", "graphic", "tail", "wing1", "wing2"}},
    }
    local ARTIST_PRESERVED_PARTS = {
        ["Left Cloak"] = true, ["Left Glove"] = true, ["Left Sleeve"] = true,
        ["Right Cloak"] = true, ["Right Glove"] = true, ["Right Sleeve"] = true,
        -- ArtistTwoTime keeps the original cloak/glove/sleeve pieces, but removes
        -- the torso and leg Robe pieces so the added skin details stay visible.
    }
    local targetSnapshots = setmetatable({}, {__mode = "k"})
    local trackedTargets = {}
    local appliedTargets = setmetatable({}, {__mode = "k"})

    local getTargetSnapshot

    local function rememberOriginal(targetState, object)
        if not object or not object.Parent or targetState.originalSet[object] then return end
        targetState.originalSet[object] = true
        table.insert(targetState.originals, {object = object, parent = object.Parent})
    end

    getTargetSnapshot = function(target)
        local targetState = targetSnapshots[target]
        if targetState then return targetState end

        -- Remember every live body slot before hiding it behind a skin body-part
        -- replacement. Original instances stay in the rig so Motor6D connections
        -- remain intact; only their local visual state is changed.
        local bodyVisuals = {}
        for bodyName in pairs(TARGET_BODY_FALLBACKS) do
            local part = findTargetBodyPart(target, bodyName)
            if part then
                local saved = {
                    part = part,
                    transparency = part.Transparency,
                    localTransparencyModifier = 0,
                    castShadow = part.CastShadow,
                    childVisuals = {},
                }
                pcall(function()
                    saved.localTransparencyModifier = part.LocalTransparencyModifier
                end)
                for _, child in ipairs(part:GetDescendants()) do
                    if child:IsA("Decal") or child:IsA("Texture") then
                        table.insert(saved.childVisuals, {
                            object = child,
                            transparency = child.Transparency,
                        })
                    end
                end
                bodyVisuals[bodyName] = saved
            end
        end

        targetState = {
            bodyVisuals = bodyVisuals,
            originals = {},
            originalSet = {},
        }
        targetSnapshots[target] = targetState
        table.insert(trackedTargets, target)
        return targetState
    end

    local function restoreTargetOriginals(target)
        local targetState = targetSnapshots[target]
        if not targetState then
            removePreviousSkin(target)
            appliedTargets[target] = nil
            return
        end
        -- Remove cloned skin body parts/accessories first, then reveal the exact
        -- original body-part instances and their original decals/textures.
        removePreviousSkin(target)
        for _, saved in pairs(targetState.bodyVisuals or {}) do
            local part = saved.part
            if part and part.Parent then
                pcall(function()
                    part.Transparency = saved.transparency
                    part.LocalTransparencyModifier = saved.localTransparencyModifier
                    part.CastShadow = saved.castShadow
                end)
            end
            for _, childSaved in ipairs(saved.childVisuals or {}) do
                local object = childSaved.object
                if object and object.Parent then
                    pcall(function() object.Transparency = childSaved.transparency end)
                end
            end
        end
        for _, saved in ipairs(targetState.originals) do
            local object, parent = saved.object, saved.parent
            if object and not object.Parent and parent and parent.Parent then
                pcall(function() object.Parent = parent end)
            end
        end
        appliedTargets[target] = nil
    end

    local function detachOriginalsForVariant(target, preserveArtistPieces)
        local targetState = getTargetSnapshot(target)
        -- Keep the original clothing instances for reset; copies are tagged artifacts.
        for _, object in ipairs(target:GetDescendants()) do
            if object:IsA("Shirt") or object:IsA("Pants")
                or object:IsA("ShirtGraphic") or object:IsA("BodyColors") then
                rememberOriginal(targetState, object)
            end
        end
        for _, saved in ipairs(targetState.originals) do
            local object = saved.object
            if object and object.Parent and (object:IsA("Shirt") or object:IsA("Pants")
                or object:IsA("ShirtGraphic") or object:IsA("BodyColors")) then
                pcall(function() object.Parent = nil end)
            end
        end

        for _, group in ipairs(ORIGINAL_TWOTIME_COSMETICS) do
            local bodyPart = target:FindFirstChild(group.body)
            if bodyPart then
                for _, itemName in ipairs(group.items) do
                    local item = bodyPart:FindFirstChild(itemName)
                    local keep = preserveArtistPieces and ARTIST_PRESERVED_PARTS[itemName] == true
                    if item and not keep then
                        rememberOriginal(targetState, item)
                        pcall(function() item.Parent = nil end)
                    end
                end
            end
        end
    end

    local function countSkinArtifacts(target)
        local count = 0
        for _, item in ipairs(target:GetDescendants()) do
            if isSkinArtifact(item) then count += 1 end
        end
        return count
    end

    local function collectTargetBodyRefs(target)
        local refs = {}
        for bodyName in pairs(TARGET_BODY_FALLBACKS) do
            refs[bodyName] = findTargetBodyPart(target, bodyName)
        end
        return refs
    end

    local function findNumberedLifeRig(root, lifeName)
        if not root then return nil end
        local wantedNumber = lifeName == "Life2" and "2" or "1"
        if root:IsA("Model") and root.Name == wantedNumber
            and (root:FindFirstChild("Head") or root:FindFirstChild("Torso") or root:FindFirstChildOfClass("Humanoid")) then
            return root
        end
        for _, descendant in ipairs(root:GetDescendants()) do
            if descendant:IsA("Model")
                and (descendant.Name == wantedNumber or (descendant.Parent and descendant.Parent.Name == wantedNumber))
                and (descendant:FindFirstChild("Head") or descendant:FindFirstChild("Torso")
                    or descendant:FindFirstChildOfClass("Humanoid")) then
                return descendant
            end
        end
        return nil
    end

    local function applySkinBodyParts(sourceRig, target)
        local sourceBodyParts = collectSourceBodyParts(sourceRig)
        local replaced = 0

        -- Replace only body slots actually supplied by the selected skin rig.
        -- The original live parts remain as invisible rig anchors so their
        -- Motor6D joints and the game's character controller are not disrupted.
        for bodySlot, sourceBody in pairs(sourceBodyParts) do
            if sourceBody and sourceBody.Parent then
                local targetBody = findTargetBodyPart(target, bodySlot)
                if targetBody and targetBody.Parent then
                    local cloneOK, bodyClone = pcall(function() return sourceBody:Clone() end)
                    if cloneOK and bodyClone and bodyClone:IsA("BasePart") then
                        bodyClone.Name = ARTIFACT_PREFIX .. "Body_" .. tostring(bodySlot):gsub("%W+", "_")
                        pcall(function() bodyClone:SetAttribute(ARTIFACT_ATTRIBUTE, true) end)

                        -- A body part clone must not keep joints pointing back into
                        -- the ReplicatedStorage source rig. Preserve mesh, color,
                        -- material, SurfaceAppearance, SpecialMesh, decals and
                        -- attachments; remove only rig joints/scripts.
                        local descendants = bodyClone:GetDescendants()
                        for _, child in ipairs(descendants) do
                            if child:IsA("JointInstance") or child:IsA("WeldConstraint")
                                or child:IsA("Constraint") or child:IsA("Script")
                                or child:IsA("LocalScript") or child:IsA("ModuleScript") then
                                pcall(function() child:Destroy() end)
                            end
                        end

                        bodyClone.CFrame = targetBody.CFrame
                        bodyClone.Anchored = false
                        bodyClone.CanCollide = false
                        bodyClone.CanTouch = false
                        bodyClone.CanQuery = false
                        bodyClone.Massless = true
                        bodyClone.CastShadow = sourceBody.CastShadow
                        pcall(function() bodyClone.LocalTransparencyModifier = 0 end)
                        bodyClone.Parent = targetBody.Parent

                        local weld = Instance.new("WeldConstraint")
                        weld.Name = WELD_NAME
                        weld.Part0 = targetBody
                        weld.Part1 = bodyClone
                        pcall(function() weld:SetAttribute(ARTIFACT_ATTRIBUTE, true) end)
                        weld.Parent = bodyClone

                        -- Hide the live part without deleting or replacing its
                        -- joint-connected instance. The cloned skin part is the
                        -- visible replacement and follows it through the weld.
                        targetBody.Transparency = 1
                        pcall(function() targetBody.LocalTransparencyModifier = 1 end)
                        targetBody.CastShadow = false
                        for _, child in ipairs(targetBody:GetDescendants()) do
                            if child:IsA("Decal") or child:IsA("Texture") then
                                pcall(function() child.Transparency = 1 end)
                            end
                        end
                        replaced += 1
                    elseif not cloneOK then
                        warn("[E1LU4HUB TwoTime] Could not clone " .. tostring(bodySlot) .. ": " .. tostring(bodyClone))
                    end
                end
            end
        end

        return replaced
    end

    local function applySkinToLifeTarget(variant, skinFolder, fallbackRig, target, lifeName)
        -- Final ownership check: the target must be the local player's current
        -- TwoTime character or a nested Life rig belonging to that character.
        local localCharacter = player and player.Character
        if not localCharacter or not T.isLocalSurvivorTwoTime(localCharacter)
            or not target
            or (target ~= localCharacter and not target:IsDescendantOf(localCharacter)) then
            error("Refusing to apply TwoTime skin outside the local player's character")
        end

        -- LegacyMS100 / Legacy Milestone IV now follows the uploaded reference's
        -- standard source-rig pipeline. Only ArtistTwoTime keeps its special pieces.
        local preserveArtistPieces = variant.label == "ArtistTwoTime"
        restoreTargetOriginals(target)
        detachOriginalsForVariant(target, preserveArtistPieces)
        local sourceRig = findNamedLifeRig(skinFolder, lifeName)
            or findNumberedLifeRig(skinFolder, lifeName)
            or findNamedLifeRig(fallbackRig, lifeName)
            or findNumberedLifeRig(fallbackRig, lifeName)
            or fallbackRig
        if not findBasePart(sourceRig, "Head") then
            error(lifeName .. " source skin rig does not contain a Head")
        end

        removePreviousSkin(target)
        local bodyPartCount = applySkinBodyParts(sourceRig, target)
        local clothingCount = copySkinClothing(sourceRig, target)
        local accessoryCount, headAttachedCount, skippedCount, byBody =
            copyAndWearSkinAccessories(sourceRig, target, lifeName, variant.label)
        if bodyPartCount == 0 and clothingCount == 0 and accessoryCount == 0 then
            error(lifeName .. " skin rig found, but no body parts, clothing or wearable accessories could be applied")
        end

        appliedTargets[target] = {
            variantKey = table.concat(variant.folderNames, "|"),
            sourceRig = sourceRig,
            lifeName = lifeName,
            artifactCount = countSkinArtifacts(target),
            bodyRefs = collectTargetBodyRefs(target),
        }
        return {
            lifeName = lifeName,
            actualSkinName = sourceRig.Name,
            bodyPartCount = bodyPartCount,
            clothingCount = clothingCount,
            accessoryCount = accessoryCount,
            headAttachedCount = headAttachedCount,
            skippedCount = skippedCount,
            byBody = byBody,
        }
    end

    local function isTargetAlreadyApplied(entry, variant)
        local state = appliedTargets[entry.target]
        if not state or state.variantKey ~= table.concat(variant.folderNames, "|")
            or state.lifeName ~= entry.lifeName then
            return false
        end
        for bodyName, oldPart in pairs(state.bodyRefs or {}) do
            if findTargetBodyPart(entry.target, bodyName) ~= oldPart then return false end
        end
        if countSkinArtifacts(entry.target) < (state.artifactCount or 0) then return false end
        return true
    end

    local function applySkin(variant, activeCharacter)
        if not T.isLocalSurvivorTwoTime(activeCharacter) then
            error("Skin Changer is available only as Survivor TwoTime")
        end
        local root, entries = resolveTargetEntries()
        if not root or #entries == 0 then error("TwoTime character or its Life1/Life2 rig was not found") end
        if root == player.Character and not root:FindFirstChildOfClass("Humanoid") then
            error("Humanoid was not found in your character")
        end

        local fallbackRig, actualSkinName, skinFolder = getSkinRig(variant.folderNames)
        if not T.isLocalSurvivorTwoTime(activeCharacter) or player.Character ~= activeCharacter then
            error("Role or character changed; skin application was cancelled")
        end
        local reports, errors = {}, {}
        for _, entry in ipairs(entries) do
            if not T.isLocalSurvivorTwoTime(activeCharacter) or player.Character ~= activeCharacter then
                error("Role or character changed during skin application")
            end
            local ok, report = pcall(applySkinToLifeTarget, variant, skinFolder, fallbackRig, entry.target, entry.lifeName)
            if ok then
                table.insert(reports, report)
            else
                table.insert(errors, entry.lifeName .. ": " .. tostring(report))
                warn("[E1LU4HUB TwoTime] " .. entry.lifeName .. " apply failed: " .. tostring(report))
            end
        end
        if #reports == 0 then error(table.concat(errors, " | ")) end
        return {actualSkinName = actualSkinName, skinFolder = skinFolder, reports = reports, errors = errors}
    end

    -- Keep the selected Equipped.Skins.TwoTime value while the master switch is
    -- ON and the local player is actually Survivor TwoTime. Restore its prior
    -- value and attributes when Skin Changer is disabled or another skin is used.
    local equippedBackup = nil
    local equippedCreatedValue = nil
    local function ensureEquippedSkinValue(skinName)
        if type(skinName) ~= "string" or skinName == "" then return false end
        local playerData = player and player:FindFirstChild("PlayerData")
        local equipped = playerData and playerData:FindFirstChild("Equipped")
        local skins = equipped and equipped:FindFirstChild("Skins")
        if not skins then return false end

        local value = skins:FindFirstChild(EQUIPPED_SKIN_VALUE_NAME)
        if not equippedBackup then
            equippedBackup = {
                parent = skins,
                original = value,
                originalParent = value and value.Parent or nil,
                originalValue = value and value:IsA("StringValue") and value.Value or nil,
                originalAttributes = value and value:GetAttributes() or {},
            }
        end
        if value and not value:IsA("StringValue") then
            pcall(function() value.Parent = nil end)
            value = nil
        end
        if not value then
            value = Instance.new("StringValue")
            value.Name = EQUIPPED_SKIN_VALUE_NAME
            value.Parent = skins
            equippedCreatedValue = value
        end
        value.Value = skinName
        value:SetAttribute("Skin", skinName)
        value:SetAttribute("UniqueId", "00000000-0000-0000-0000-000000000000")
        value:SetAttribute("E1LU4HUB_TwoTimeSkinChangerOwned", true)
        return true
    end

    local function restoreEquippedSkinValue()
        local backup = equippedBackup
        if not backup then return end
        if equippedCreatedValue and equippedCreatedValue.Parent then
            pcall(function() equippedCreatedValue:Destroy() end)
        end
        if backup.original then
            if backup.original.Parent ~= backup.originalParent and backup.originalParent then
                pcall(function() backup.original.Parent = backup.originalParent end)
            end
            if backup.original:IsA("StringValue") and backup.originalValue ~= nil then
                pcall(function() backup.original.Value = backup.originalValue end)
            end
            local currentAttributes = {}
            pcall(function() currentAttributes = backup.original:GetAttributes() end)
            for name in pairs(currentAttributes) do
                if backup.originalAttributes[name] == nil then
                    pcall(function() backup.original:SetAttribute(name, nil) end)
                end
            end
            for name, value in pairs(backup.originalAttributes) do
                pcall(function() backup.original:SetAttribute(name, value) end)
            end
        end
        equippedBackup = nil
        equippedCreatedValue = nil
    end

    -- CurrentSurvivors portrait changes are visual-only and require the local
    -- player to actually be Survivor TwoTime. Equip Skin remains role-independent.
    local iconOriginals = setmetatable({}, {__mode = "k"})
    local function restoreEquippedSkinIcon()
        for icon, image in pairs(iconOriginals) do
            if icon and icon.Parent then pcall(function() icon.Image = image end) end
        end
        table.clear(iconOriginals)
    end
    local function readSkinIcon(skinFolder)
        if not skinFolder then return nil end
        local config = skinFolder:FindFirstChild("Config") or skinFolder:FindFirstChild("Config", true)
        if not config or not config:IsA("ModuleScript") then return nil end
        local ok, data = pcall(require, config)
        if not ok or type(data) ~= "table" then return nil end
        local image = data.RenderImage or data.Icon or data.Image or data.Portrait or data.Thumbnail
        if typeof(image) == "number" and image > 0 then return "rbxassetid://" .. tostring(math.floor(image)) end
        if type(image) == "string" and image ~= "" then
            if tonumber(image) then return "rbxassetid://" .. tostring(math.floor(tonumber(image))) end
            return image
        end
        return nil
    end
    local function updateEquippedSkinIcon(variant)
        -- Do not change the lobby/current-survivor portrait for off-role or
        -- non-TwoTime characters, even though Equipped.Skins is still maintained.
        if not T.isLocalSurvivorTwoTime(player and player.Character) then
            restoreEquippedSkinIcon()
            return false
        end
        local image = readSkinIcon(variant and variant.skinFolder)
        if not image then return false end
        local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
        local temporaryUI = playerGui and playerGui:FindFirstChild("TemporaryUI")
        local playerInfo = temporaryUI and temporaryUI:FindFirstChild("PlayerInfo")
        local currentSurvivors = playerInfo and playerInfo:FindFirstChild("CurrentSurvivors")
        if not currentSurvivors then return false end
        local ownUsername = player.Name .. " (You)"
        for _, survivorCard in ipairs(currentSurvivors:GetChildren()) do
            local usernameLabel = survivorCard:FindFirstChild("Username", true)
            local icon = survivorCard:FindFirstChild("Icon", true)
            local matches = false
            if usernameLabel and icon then pcall(function() matches = usernameLabel.Text == ownUsername end) end
            if matches and (icon:IsA("ImageLabel") or icon:IsA("ImageButton")) then
                if iconOriginals[icon] == nil then iconOriginals[icon] = icon.Image end
                pcall(function() icon.Image = image end)
                return true
            end
        end
        return false
    end

    -- ArtistTwoTime footprints mirror Artist shedletsky's alternating, colored
    -- ground decal effect: emit every four seconds and fade/shrink over one second.
    local heartbeatConnection = nil
    local footprintFolder = nil
    local footprintElapsed = 0
    local maintainElapsed = 0
    local function clearFootprints()
        if footprintFolder and footprintFolder.Parent then
            pcall(function() footprintFolder:Destroy() end)
        end
        footprintFolder = nil
        footprintElapsed = 0
    end
    local function addArtistTwoTimeFootprint(character)
        local leftFoot = character:FindFirstChild("LeftFoot") or character:FindFirstChild("Left Leg")
        local rightFoot = character:FindFirstChild("RightFoot") or character:FindFirstChild("Right Leg")
        if not leftFoot or not rightFoot then return end
        local foot = math.random() < 0.5 and leftFoot or rightFoot
        if not foot:IsA("BasePart") then return end
        if not footprintFolder or not footprintFolder.Parent then
            footprintFolder = Instance.new("Folder")
            footprintFolder.Name = "E1LU4HUB_ArtistTwoTimeEffects"
            footprintFolder.Parent = S.__helpers.getWorldRootFolder()
        end
        local splatter = Instance.new("Part")
        splatter.Name = "ArtistTwoTimeFootprint"
        splatter.Size = Vector3.new(6, 0.05, 6)
        splatter.Anchored = true
        splatter.CanCollide = false
        splatter.CanTouch = false
        splatter.CanQuery = false
        splatter.Transparency = 1
        splatter.Position = foot.Position - Vector3.new(0, foot.Size.Y / 2 + 0.05, 0)
        splatter.Parent = footprintFolder

        local decal = Instance.new("Decal")
        decal.Face = Enum.NormalId.Top
        decal.Texture = "http://www.roblox.com/asset/?id=17364186013"
        local colors = {
            Color3.fromRGB(255, 0, 255), Color3.fromRGB(56, 56, 255),
            Color3.fromRGB(255, 30, 30), Color3.fromRGB(255, 255, 40),
            Color3.fromRGB(30, 255, 30),
        }
        decal.Color3 = colors[math.random(1, #colors)]
        decal.Parent = splatter
        local tween = S.TweenService:Create(
            splatter,
            TweenInfo.new(1, Enum.EasingStyle.Linear),
            {Transparency = 1, Size = Vector3.new(0.2, 0.05, 0.2)}
        )
        tween:Play()
        S.Debris = S.Debris or game:GetService("Debris")
        S.Debris:AddItem(splatter, 1.1)
    end

    local selectedVariant = nil

    local function clearStaleInjectedTwoTimeEquip()
        task.spawn(function()
            local playerData = player and (player:FindFirstChild("PlayerData")
                or player:WaitForChild("PlayerData", 15))
            local equipped = playerData and (playerData:FindFirstChild("Equipped")
                or playerData:WaitForChild("Equipped", 10))
            local equippedSkins = equipped and (equipped:FindFirstChild("Skins")
                or equipped:WaitForChild("Skins", 10))
            if not equippedSkins then return end

            -- A currently saved selection owns the value; do not clear it during
            -- a fast enable/select sequence while PlayerData is still loading.
            local saved = S.SkinChanger.selectedByCharacter
                and S.SkinChanger.selectedByCharacter["TwoTime"]
            if S.SkinChanger.enabled == true and T.isSkin(saved) then return end

            local value = equippedSkins:FindFirstChild(EQUIPPED_SKIN_VALUE_NAME)
            if not value or not value:IsA("StringValue") then return end
            local currentSkin = tostring(value.Value or "")
            local skinAttribute = tostring(value:GetAttribute("Skin") or "")
            local uniqueId = tostring(value:GetAttribute("UniqueId") or "")
            local taggedByThisScript = value:GetAttribute("E1LU4HUB_TwoTimeSkinChangerOwned") == true
            local legacySyntheticValue = AUTO_UNLOCK_SKIN_NAMES[currentSkin] == true
                and skinAttribute == currentSkin
                and uniqueId == "00000000-0000-0000-0000-000000000000"
            if taggedByThisScript or legacySyntheticValue then
                pcall(function()
                    value.Value = ""
                    value:SetAttribute("Skin", nil)
                    value:SetAttribute("UniqueId", nil)
                    value:SetAttribute("E1LU4HUB_TwoTimeSkinChangerOwned", nil)
                end)
            end
        end)
    end

    -- Previous versions could leave their synthetic LegacyMS value behind if
    -- the executor stopped before the normal restore callback ran.
    clearStaleInjectedTwoTimeEquip()

    local function maintainSelectedSkin()
        local variant = selectedVariant
        if not variant or S.SkinChanger.enabled ~= true then return end

        -- Equip Skin is independent from the local character/role gate. Keep the
        -- game-side Equipped.Skins.TwoTime value active while a TwoTime choice is
        -- selected and Enable Skin Changer is ON.
        if variant.equippedSkinName then
            ensureEquippedSkinValue(variant.equippedSkinName)
        end
        updateEquippedSkinIcon(variant)

        -- Only the local appearance/accessory changes require Survivor TwoTime.
        local character = player and player.Character
        if not T.isLocalSurvivorTwoTime(character) then return end
        if S.SkinChanger.active ~= variant.label or S.SkinChanger.activeCharacter ~= character then
            return
        end

        local root, entries = resolveTargetEntries()
        if not root or #entries == 0 then return end
        local needsApply = false
        for _, entry in ipairs(entries) do
            if not isTargetAlreadyApplied(entry, variant) then needsApply = true; break end
        end
        if not needsApply then return end

        local ok, result = pcall(applySkin, variant, character)
        if ok and result then
            variant.equippedSkinName = result.actualSkinName or variant.equippedSkinName
            variant.skinFolder = result.skinFolder or variant.skinFolder
        elseif not ok then
            warn("[E1LU4HUB TwoTime] Auto-maintain failed: " .. tostring(result))
        end
    end

    local function startHeartbeat()
        if heartbeatConnection then pcall(function() heartbeatConnection:Disconnect() end) end
        maintainElapsed = 0
        footprintElapsed = 0
        heartbeatConnection = S.RunService.Heartbeat:Connect(function(deltaTime)
            local variant = selectedVariant
            if not variant or S.SkinChanger.enabled ~= true then
                return
            end

            -- Always maintain the game-side Equip Skin value while enabled,
            -- regardless of which character/role is currently being played.
            maintainElapsed += tonumber(deltaTime) or (1 / 60)
            if maintainElapsed >= 0.15 then
                maintainElapsed = 0
                local ok, err = pcall(maintainSelectedSkin)
                if not ok then warn("[E1LU4HUB TwoTime] Monitor error: " .. tostring(err)) end
            end

            -- Footprints are a visual effect and remain restricted to the actual
            -- local Survivor TwoTime character using ArtistTwoTime.
            local character = player and player.Character
            if variant.label == "ArtistTwoTime"
                and S.SkinChanger.active == variant.label
                and S.SkinChanger.activeCharacter == character
                and T.isLocalSurvivorTwoTime(character) then
                footprintElapsed += tonumber(deltaTime) or (1 / 60)
                if footprintElapsed >= 4 then
                    footprintElapsed = 0
                    pcall(addArtistTwoTimeFootprint, character)
                end
            else
                footprintElapsed = 0
            end
        end)
    end

    -- Resolve and set the game-side skin without changing the live character.
    -- This is intentionally callable off-role/off-character; only T.apply below
    -- performs the Survivor TwoTime appearance modification.
    T.equipSelectedSkin = function(skinLabel)
        local variant = variantByLabel[skinLabel]
        if not variant then return false, "unknown TwoTime skin" end

        if S.SkinChanger.enabled == true and S.SkinChanger.unlockAllAvailableSkins then
            pcall(S.SkinChanger.unlockAllAvailableSkins)
        end

        local ok, fallbackRig, actualSkinName, skinFolder = pcall(getSkinRig, variant.folderNames)
        if not ok then
            return false, fallbackRig
        end
        variant.equippedSkinName = actualSkinName or variant.equippedSkinName
        variant.skinFolder = skinFolder or variant.skinFolder
        if not variant.equippedSkinName or variant.equippedSkinName == "" then
            return false, "skin asset name could not be resolved"
        end

        -- Store the pending selection before attempting the value write. If
        -- PlayerData is still loading, the heartbeat retries Equip Skin.
        selectedVariant = variant
        local equipValueReady = ensureEquippedSkinValue(variant.equippedSkinName)
        updateEquippedSkinIcon(variant)
        startHeartbeat()
        if not equipValueReady then
            return false, "PlayerData.Equipped.Skins.TwoTime is not available yet; retrying while enabled"
        end
        return true, fallbackRig, actualSkinName, skinFolder
    end

    T.apply = function(skinLabel, character)
        local variant = variantByLabel[skinLabel]
        character = character or (player and player.Character)
        if S.SkinChanger.enabled ~= true or not variant or not T.isLocalSurvivorTwoTime(character) then
            return false
        end
        local activeCharacter = character

        -- Make sure the game-side Equip Skin succeeds independently, then gate
        -- only the visual model work to Survivor TwoTime.
        local equipOK, fallbackRig, actualSkinName, skinFolder = T.equipSelectedSkin(skinLabel)
        if not equipOK then
            error(tostring(fallbackRig or "Equip Skin failed"))
        end
        if not T.isLocalSurvivorTwoTime(activeCharacter) or player.Character ~= activeCharacter then
            return false
        end

        local ok, result = pcall(applySkin, variant, activeCharacter)
        if not ok then
            -- Keep the selected game-side Equip Skin value even if the local
            -- cosmetic model cannot be changed on this attempt.
            selectedVariant = variant
            ensureEquippedSkinValue(variant.equippedSkinName)
            error(result)
        end
        variant.equippedSkinName = result.actualSkinName or variant.equippedSkinName
        variant.skinFolder = result.skinFolder or variant.skinFolder
        updateEquippedSkinIcon(variant)
        if variant.label == "ArtistTwoTime" then
            clearFootprints()
            footprintFolder = Instance.new("Folder")
            footprintFolder.Name = "E1LU4HUB_ArtistTwoTimeEffects"
            footprintFolder.Parent = S.__helpers.getWorldRootFolder()
        else
            clearFootprints()
        end
        startHeartbeat()
        return true
    end

    T.deactivate = function()
        if heartbeatConnection then
            pcall(function() heartbeatConnection:Disconnect() end)
            heartbeatConnection = nil
        end
        clearFootprints()
        for index = #trackedTargets, 1, -1 do
            local target = trackedTargets[index]
            if target then
                pcall(restoreTargetOriginals, target)
                targetSnapshots[target] = nil
                appliedTargets[target] = nil
            end
            table.remove(trackedTargets, index)
        end

        -- Keep Force Equip Skin when Enable is ON and a TwoTime choice remains
        -- saved, even if the current character is not Survivor TwoTime. Turning
        -- Enable OFF or choosing None restores the original Equipped value.
        local savedTwoTimeSkin = S.SkinChanger.selectedByCharacter
            and S.SkinChanger.selectedByCharacter["TwoTime"]
        local keepEquip = S.SkinChanger.enabled == true and T.isSkin(savedTwoTimeSkin)
        if keepEquip and selectedVariant then
            if selectedVariant.equippedSkinName then
                ensureEquippedSkinValue(selectedVariant.equippedSkinName)
            end
            updateEquippedSkinIcon(selectedVariant)
            startHeartbeat()
        else
            restoreEquippedSkinValue()
            clearStaleInjectedTwoTimeEquip()
            restoreEquippedSkinIcon()
            selectedVariant = nil
        end
    end

    -- Publicly expose a simple readiness helper for the shared Skin Changer UI.
    T.isReady = function(character)
        return T.isLocalSurvivorTwoTime(character)
            and character:FindFirstChild("Head") ~= nil
            and (character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso")) ~= nil
            and character:FindFirstChildOfClass("Humanoid") ~= nil
    end
end

-- Extend the existing dispatcher; the regular Guest1337 / Shedletsky / Slasher
-- application paths remain unchanged.
do
    local originalSkinApply = S.SkinChanger.apply
    S.SkinChanger.apply = function(skinName)
        local twoTime = S.TwoTimeSkinChanger
        if twoTime and twoTime.isSkin(skinName) then
            if S.SkinChanger.enabled ~= true then return false end
            local character = S.lp and S.lp.Character
            if twoTime.equipSelectedSkin then
                local equipOK, equipError = twoTime.equipSelectedSkin(skinName)
                if not equipOK then
                    warn("[E1LU4HUB Skin Changer] Equip Skin failed: " .. tostring(equipError))
                    return false
                end
            end
            if not twoTime.isLocalSurvivorTwoTime(character) then return false end
            S.SkinChanger.deactivate()
            character = S.lp and S.lp.Character
            if not character or not twoTime.isLocalSurvivorTwoTime(character) then return false end
            S.SkinChanger.active = skinName
            S.SkinChanger.activeCharacter = character
            local ok, result = pcall(twoTime.apply, skinName, character)
            if not ok or result == false then
                S.SkinChanger.active = nil
                S.SkinChanger.activeCharacter = nil
                pcall(twoTime.deactivate)
                warn("[E1LU4HUB Skin Changer] " .. tostring(result))
                return false
            end
            return true
        end
        return originalSkinApply(skinName)
    end
end

-- GAME: SPOOF USERNAMES (E1LU4HUB-style player-name matching)
-- Replaces exact and partial player Name / DisplayName matches in local UI text.
-- The original text is retained so disabling the feature restores the UI.
-- ================================================================
S.spoofUsernamesReplacement = "E1LU4 HUB"
do
    local spoof = {
        enabled = false,
        value = S.spoofUsernamesReplacement,
        usernames = {},
        displayNames = {},
        nameKeys = {},
        originals = setmetatable({}, {__mode = "k"}),
        lastWritten = setmetatable({}, {__mode = "k"}),
        tracked = setmetatable({}, {__mode = "k"}),
        watchedPlayers = setmetatable({}, {__mode = "k"}),
        connections = {},
        playerGui = nil,
    }

    local textClasses = {
        TextLabel = true,
        TextButton = true,
        TextBox = true,
    }

    local function disconnectAll()
        for _, connection in ipairs(spoof.connections) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(spoof.connections)
    end

    -- Match the source feature's Spectate protection when getconnections exists.
    local function disableTextSignals(object)
        if type(getconnections) ~= "function" or not object then return end
        pcall(function()
            for _, connection in pairs(getconnections(object.Changed)) do
                pcall(function()
                    if connection.Disable then connection:Disable() end
                end)
            end
        end)
        pcall(function()
            for _, connection in pairs(getconnections(object:GetPropertyChangedSignal("Text"))) do
                pcall(function()
                    if connection.Disable then connection:Disable() end
                end)
            end
        end)
    end

    local function isSpectateNameLabel(object)
        if not object or (object.Name ~= "Username" and object.Name ~= "ActorName") then
            return false
        end
        local parent = object.Parent
        return parent ~= nil and parent.Name == "Spectate"
    end

    local function refreshPlayerNames()
        table.clear(spoof.usernames)
        table.clear(spoof.displayNames)
        table.clear(spoof.nameKeys)

        for _, player in ipairs(S.Players:GetPlayers()) do
            local username = tostring(player.Name or "")
            local displayName = tostring(player.DisplayName or "")
            if username ~= "" then spoof.usernames[username] = true end
            if displayName ~= "" and displayName ~= username then
                spoof.displayNames[displayName] = true
            end
        end

        local seen = {}
        for username in pairs(spoof.usernames) do
            if not seen[username] then
                seen[username] = true
                table.insert(spoof.nameKeys, username)
            end
        end
        for displayName in pairs(spoof.displayNames) do
            if not seen[displayName] then
                seen[displayName] = true
                table.insert(spoof.nameKeys, displayName)
            end
        end

        -- Longest-first avoids replacing a short username inside a longer one.
        table.sort(spoof.nameKeys, function(a, b)
            if #a == #b then return a:lower() < b:lower() end
            return #a > #b
        end)
    end

    -- Literal substring replacement (usernames may contain Lua pattern characters).
    local function replaceLiteral(source, needle, replacement)
        if needle == "" then return source, false end
        local pieces = {}
        local cursor = 1
        local replaced = false
        while true do
            local first, last = source:find(needle, cursor, true)
            if not first then break end
            table.insert(pieces, source:sub(cursor, first - 1))
            table.insert(pieces, replacement)
            cursor = last + 1
            replaced = true
        end
        if not replaced then return source, false end
        table.insert(pieces, source:sub(cursor))
        return table.concat(pieces), true
    end

    local function transformText(originalText)
        local source = tostring(originalText or "")
        if source == "" then return source end

        if spoof.usernames[source] or spoof.displayNames[source] then
            return spoof.value
        end

        local result = source
        for _, name in ipairs(spoof.nameKeys) do
            result = replaceLiteral(result, name, spoof.value)
        end
        return result
    end

    local function applyObject(object)
        if not object or not textClasses[object.ClassName] then return end
        pcall(function()
            local currentText = tostring(object.Text or "")
            local lastWritten = spoof.lastWritten[object]
            local originalText = spoof.originals[object]

            -- If the game wrote a fresh label value, preserve that value as the
            -- new source text instead of keeping a stale snapshot from earlier.
            if originalText == nil or lastWritten ~= currentText then
                originalText = currentText
                spoof.originals[object] = originalText
            end

            local replacement = transformText(originalText)
            if replacement ~= originalText then
                spoof.lastWritten[object] = replacement
                if currentText ~= replacement then
                    object.Text = replacement
                end
            else
                spoof.lastWritten[object] = nil
                if currentText ~= originalText then
                    object.Text = originalText
                end
                spoof.originals[object] = nil
            end
        end)
    end

    local function trackObject(object)
        if not object or not textClasses[object.ClassName] or spoof.tracked[object] then
            return
        end
        spoof.tracked[object] = true
        if isSpectateNameLabel(object) then
            disableTextSignals(object)
        end

        local textConnection = object:GetPropertyChangedSignal("Text"):Connect(function()
            if not spoof.enabled then return end
            local currentText = tostring(object.Text or "")
            if spoof.lastWritten[object] ~= nil and currentText == spoof.lastWritten[object] then
                return
            end
            spoof.originals[object] = currentText
            task.defer(applyObject, object)
        end)
        table.insert(spoof.connections, textConnection)

        local ancestryConnection
        ancestryConnection = object.AncestryChanged:Connect(function()
            local gui = spoof.playerGui
            if not gui or not object:IsDescendantOf(gui) then
                spoof.originals[object] = nil
                spoof.lastWritten[object] = nil
                spoof.tracked[object] = nil
                if ancestryConnection then
                    ancestryConnection:Disconnect()
                end
            end
        end)
        table.insert(spoof.connections, ancestryConnection)

        applyObject(object)
    end

    local function reapplyTrackedObjects()
        for object in pairs(spoof.tracked) do
            if object and object.Parent then
                applyObject(object)
            end
        end
    end

    local function scheduleNameRefresh()
        task.delay(0.5, function()
            if not spoof.enabled then return end
            refreshPlayerNames()
            reapplyTrackedObjects()
        end)
    end

    local function watchPlayerDisplayName(player)
        if not player or spoof.watchedPlayers[player] then return end
        spoof.watchedPlayers[player] = true
        table.insert(spoof.connections, player:GetPropertyChangedSignal("DisplayName"):Connect(function()
            scheduleNameRefresh()
        end))
    end

    local function scan()
        local playerGui = spoof.playerGui
        if not playerGui then return end
        for _, object in ipairs(playerGui:GetDescendants()) do
            trackObject(object)
        end
    end

    local function restoreAll()
        for object, originalText in pairs(spoof.originals) do
            if object and object.Parent then
                pcall(function() object.Text = originalText end)
            end
        end
        spoof.originals = setmetatable({}, {__mode = "k"})
        spoof.lastWritten = setmetatable({}, {__mode = "k"})
        spoof.tracked = setmetatable({}, {__mode = "k"})
        spoof.watchedPlayers = setmetatable({}, {__mode = "k"})
    end

    local function stop()
        spoof.enabled = false
        disconnectAll()
        restoreAll()
    end

    local function start()
        -- Character respawns can rebuild the UI; disconnect first so restoring
        -- old labels cannot trigger stale Text-change callbacks.
        if spoof.enabled then
            spoof.enabled = false
            disconnectAll()
            restoreAll()
        else
            disconnectAll()
        end
        spoof.enabled = true
        spoof.playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui") or nil
        refreshPlayerNames()

        for _, player in ipairs(S.Players:GetPlayers()) do
            watchPlayerDisplayName(player)
        end
        table.insert(spoof.connections, S.Players.PlayerAdded:Connect(function(player)
            watchPlayerDisplayName(player)
            scheduleNameRefresh()
        end))
        table.insert(spoof.connections, S.Players.PlayerRemoving:Connect(scheduleNameRefresh))

        local playerGui = spoof.playerGui
        if not playerGui then return end
        scan()
        table.insert(spoof.connections, playerGui.DescendantAdded:Connect(function(object)
            if not spoof.enabled then return end
            task.defer(function()
                if not spoof.enabled then return end
                trackObject(object)
            end)
        end))
    end

    if S.lp then
        S.__helpers.connect(S.lp.CharacterAdded, function()
            task.delay(1, function()
                if spoof.enabled then start() end
            end)
        end)
    end

    S.__helpers.createSectionHeader("SPOOF USERNAMES")
    S.spoofUsernamesToggleButton, S.spoofUsernamesToggleBox = S.__helpers.createCoolToggle(
        "SPOOF USERNAMES",
        false,
        function(value)
            if value == true then start() else stop() end
        end
    )
    S.spoofUsernamesReplacementLabel = Instance.new("TextLabel")
    S.spoofUsernamesReplacementLabel.Name = "SpoofUsernamesReplacement"
    S.spoofUsernamesReplacementLabel.Size = UDim2.new(0.92, 0, 0, 22)
    S.spoofUsernamesReplacementLabel.BackgroundTransparency = 1
    S.spoofUsernamesReplacementLabel.BorderSizePixel = 0
    S.spoofUsernamesReplacementLabel.Text = "REPLACEMENT NAME: " .. S.spoofUsernamesReplacement
    S.spoofUsernamesReplacementLabel.TextColor3 = Color3.fromRGB(175, 173, 183)
    S.spoofUsernamesReplacementLabel.Font = Enum.Font.Gotham
    S.spoofUsernamesReplacementLabel.TextSize = 11
    S.spoofUsernamesReplacementLabel.TextXAlignment = Enum.TextXAlignment.Left
    S.spoofUsernamesReplacementLabel.Parent = S.contentFrame
end

-- ================================================================
-- ESP UI (restored core player/item/generator features only)
-- ================================================================


-- ================================================================
-- ESP COLORS + ADDITIONAL WORLD ESP (Files and Veeronica Spray omitted)
-- ================================================================
S.__helpers.color3ToHex = function(color)
    return string.format(
        "#%02X%02X%02X",
        math.clamp(math.floor(color.R * 255 + 0.5), 0, 255),
        math.clamp(math.floor(color.G * 255 + 0.5), 0, 255),
        math.clamp(math.floor(color.B * 255 + 0.5), 0, 255)
    )
end

S.__helpers.parseESPColor = function(raw)
    local value = tostring(raw or ""):gsub("%s+", "")
    value = value:gsub("^#", ""):gsub("^0[xX]", "")
    if #value == 6 and value:match("^%x%x%x%x%x%x$") then
        local red = tonumber(value:sub(1, 2), 16)
        local green = tonumber(value:sub(3, 4), 16)
        local blue = tonumber(value:sub(5, 6), 16)
        return Color3.fromRGB(red, green, blue)
    end

    local redText, greenText, blueText = value:match("^(%d+),(%d+),(%d+)$")
    if redText and greenText and blueText then
        return Color3.fromRGB(
            math.clamp(tonumber(redText), 0, 255),
            math.clamp(tonumber(greenText), 0, 255),
            math.clamp(tonumber(blueText), 0, 255)
        )
    end
    return nil
end

S.__helpers.getESPColorPicker = function()
    if S.espColorPickerUI and S.espColorPickerUI.frame
        and S.espColorPickerUI.frame.Parent then
        return S.espColorPickerUI
    end

    local picker = Instance.new("Frame")
    picker.Name = "ESPColorPicker"
    picker.Size = UDim2.new(0, 285, 0, 350)
    picker.Position = UDim2.new(0.5, -142, 0.5, -175)
    picker.BackgroundColor3 = (S.mainFrame and S.mainFrame.BackgroundColor3) or Color3.fromRGB(26, 25, 30)
    picker.BackgroundTransparency = (S.mainFrame and S.mainFrame.BackgroundTransparency) or 0.12
    picker.BorderSizePixel = 0
    picker.Visible = false
    picker.Active = true
    picker.ZIndex = 500
    picker.Parent = S.screenGui
    local pickerCorner = Instance.new("UICorner")
    pickerCorner.CornerRadius = UDim.new(0, 5)
    pickerCorner.Parent = picker

    -- Subtle thin white outline around the ESP color picker.
    local pickerStroke = Instance.new("UIStroke")
    pickerStroke.Name = "PickerOutline"
    pickerStroke.Color = Color3.fromRGB(255, 255, 255)
    pickerStroke.Transparency = 0.65
    pickerStroke.Thickness = 1
    pickerStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    pickerStroke.Parent = picker

    local title = Instance.new("TextLabel")
    title.Name = "PickerTitle"
    title.Position = UDim2.new(0, 4, 0, 1)
    title.Size = UDim2.new(1, -30, 0, 20)
    title.BackgroundTransparency = 1
    title.Text = "Color"
    title.TextColor3 = S.uiAccentColor or Color3.fromRGB(235, 235, 238)
    title.TextSize = 13
    title.Font = Enum.Font.Code
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.ZIndex = 501
    title.Parent = picker

    local closeButton = Instance.new("TextButton")
    closeButton.Name = "ClosePicker"
    closeButton.Position = UDim2.new(1, -24, 0, 1)
    closeButton.Size = UDim2.new(0, 20, 0, 20)
    closeButton.BackgroundTransparency = 1
    closeButton.BorderSizePixel = 0
    closeButton.Text = "×"
    closeButton.TextColor3 = Color3.fromRGB(165, 165, 170)
    closeButton.TextSize = 17
    closeButton.Font = Enum.Font.Gotham
    closeButton.ZIndex = 510
    closeButton.Parent = picker

    local square = Instance.new("Frame")
    square.Name = "SaturationValue"
    square.Position = UDim2.new(0, 4, 0, 23)
    square.Size = UDim2.new(0, 250, 0, 250)
    square.BackgroundColor3 = Color3.fromRGB(255, 0, 0)
    square.BorderSizePixel = 0
    square.Active = true
    square.ZIndex = 501
    square.Parent = picker

    local whiteLayer = Instance.new("Frame")
    whiteLayer.Name = "WhiteSaturationGradient"
    whiteLayer.Size = UDim2.new(1, 0, 1, 0)
    whiteLayer.BackgroundColor3 = Color3.new(1, 1, 1)
    whiteLayer.BorderSizePixel = 0
    whiteLayer.ZIndex = 502
    whiteLayer.Parent = square
    local whiteGradient = Instance.new("UIGradient")
    whiteGradient.Rotation = 0
    whiteGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0),
        NumberSequenceKeypoint.new(1, 1),
    })
    whiteGradient.Parent = whiteLayer

    local blackLayer = Instance.new("Frame")
    blackLayer.Name = "BlackValueGradient"
    blackLayer.Size = UDim2.new(1, 0, 1, 0)
    blackLayer.BackgroundColor3 = Color3.new(0, 0, 0)
    blackLayer.BorderSizePixel = 0
    blackLayer.ZIndex = 503
    blackLayer.Parent = square
    local blackGradient = Instance.new("UIGradient")
    blackGradient.Rotation = 90
    blackGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(1, 0),
    })
    blackGradient.Parent = blackLayer

    local svMarker = Instance.new("Frame")
    svMarker.Name = "SelectedColorMarker"
    svMarker.Size = UDim2.new(0, 11, 0, 11)
    svMarker.AnchorPoint = Vector2.new(0.5, 0.5)
    svMarker.Position = UDim2.new(1, 0, 0, 0)
    svMarker.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    svMarker.BorderSizePixel = 0
    svMarker.ZIndex = 505
    svMarker.Parent = square
    local markerCorner = Instance.new("UICorner")
    markerCorner.CornerRadius = UDim.new(1, 0)
    markerCorner.Parent = svMarker
    local markerStroke = Instance.new("UIStroke")
    markerStroke.Color = S.uiAccentColor or Color3.fromRGB(255, 255, 255)
    markerStroke.Thickness = 1.5
    markerStroke.Parent = svMarker

    local hueStrip = Instance.new("Frame")
    hueStrip.Name = "HueStrip"
    hueStrip.Position = UDim2.new(0, 260, 0, 23)
    hueStrip.Size = UDim2.new(0, 20, 0, 250)
    hueStrip.BackgroundColor3 = Color3.new(1, 0, 0)
    hueStrip.BorderSizePixel = 0
    hueStrip.Active = true
    hueStrip.ZIndex = 501
    hueStrip.Parent = picker
    -- Build the hue rail from explicit top-to-bottom HSV rows instead of UIGradient.
    -- This avoids UIGradient.Rotation direction differences and guarantees the
    -- reference order: red -> yellow -> green -> cyan -> blue -> purple -> red.
    -- The rail is 250px tall, so each row is exactly one pixel high.
    local HUE_RAIL_HEIGHT = 250
    for row = 0, HUE_RAIL_HEIGHT - 1 do
        local hueStep = Instance.new("Frame")
        hueStep.Name = "HueStep"
        hueStep.Position = UDim2.new(0, 0, 0, row)
        hueStep.Size = UDim2.new(1, 0, 0, 1)
        hueStep.BackgroundColor3 = Color3.fromHSV(row / (HUE_RAIL_HEIGHT - 1), 1, 1)
        hueStep.BorderSizePixel = 0
        hueStep.Active = false
        hueStep.ZIndex = 502
        hueStep.Parent = hueStrip
    end

    local hueMarker = Instance.new("Frame")
    hueMarker.Name = "HueMarker"
    hueMarker.AnchorPoint = Vector2.new(0, 0.5)
    hueMarker.Position = UDim2.new(0, -1, 0, 0)
    hueMarker.Size = UDim2.new(1, 2, 0, 3)
    hueMarker.BackgroundColor3 = S.uiAccentColor or Color3.fromRGB(255, 255, 255)
    hueMarker.BorderSizePixel = 0
    hueMarker.ZIndex = 505
    hueMarker.Parent = hueStrip

    local function makePickerBox(name, position, width, placeholder)
        local box = Instance.new("TextBox")
        box.Name = name
        box.Position = position
        box.Size = UDim2.new(0, width, 0, 27)
        box.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
        box.BorderSizePixel = 0
        box.Text = ""
        box.PlaceholderText = placeholder
        box.TextColor3 = Color3.fromRGB(238, 238, 238)
        box.PlaceholderColor3 = Color3.fromRGB(140, 140, 140)
        box.TextSize = 13
        box.Font = Enum.Font.Code
        box.ClearTextOnFocus = false
        box.TextXAlignment = Enum.TextXAlignment.Center
        box.ZIndex = 501
        box.Parent = picker
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 4)
        corner.Parent = box
        return box
    end

    local hexBox = makePickerBox("HexInput", UDim2.new(0, 4, 0, 282), 134, "#RRGGBB")
    local rgbBox = makePickerBox("RGBInput", UDim2.new(0, 146, 0, 282), 135, "R, G, B")

    local function makePickerButton(name, textValue, position)
        local button = Instance.new("TextButton")
        button.Name = name
        button.Position = position
        button.Size = UDim2.new(0, 134, 0, 27)
        button.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
        button.BorderSizePixel = 0
        button.AutoButtonColor = true
        button.Text = textValue
        button.TextColor3 = Color3.fromRGB(238, 238, 238)
        button.TextSize = 13
        button.Font = Enum.Font.Code
        button.ZIndex = 501
        button.Parent = picker
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 4)
        corner.Parent = button
        return button
    end

    local copyButton = makePickerButton("CopyColor", "Copy color", UDim2.new(0, 4, 0, 317))
    local pasteButton = makePickerButton("PasteColor", "Paste color", UDim2.new(0, 146, 0, 317))

    local currentHue, currentSaturation, currentValue = 0, 1, 1
    local activeControl = nil
    local dragMode = nil

    local function refreshPickerVisuals(color, updateText, preserveHSV)
        if not color then return end
        if not preserveHSV then
            local h, saturation, value = color:ToHSV()
            currentHue = h
            currentSaturation = saturation
            currentValue = value
        end
        square.BackgroundColor3 = Color3.fromHSV(currentHue, 1, 1)
        svMarker.Position = UDim2.new(currentSaturation, 0, 1 - currentValue, 0)
        hueMarker.Position = UDim2.new(0, -1, currentHue, -currentHue)
        if updateText ~= false then
            hexBox.Text = S.__helpers.color3ToHex(color)
            rgbBox.Text = string.format("%d, %d, %d",
                math.floor(color.R * 255 + 0.5),
                math.floor(color.G * 255 + 0.5),
                math.floor(color.B * 255 + 0.5))
        end
    end

    local function applyPickerColor()
        if not activeControl then return end
        local selected = Color3.fromHSV(currentHue, currentSaturation, currentValue)
        refreshPickerVisuals(selected, true, true)
        if type(activeControl.onChange) == "function" then
            local ok, err = pcall(activeControl.onChange, selected)
            if not ok then warn("[ELHUB ESP Color] " .. tostring(err)) end
        end
    end

    local function updateFromPointer(mode, position)
        if not position then return end
        if mode == "Hue" then
            local height = math.max(1, hueStrip.AbsoluteSize.Y)
            local localY = position.Y - hueStrip.AbsolutePosition.Y
            local percent = math.clamp((localY - 0.5) / math.max(1, height - 1), 0, 1)
            currentHue = percent
        elseif mode == "SV" then
            local width = math.max(1, square.AbsoluteSize.X)
            local height = math.max(1, square.AbsoluteSize.Y)
            currentSaturation = math.clamp((position.X - square.AbsolutePosition.X) / width, 0, 1)
            currentValue = 1 - math.clamp((position.Y - square.AbsolutePosition.Y) / height, 0, 1)
        else
            return
        end
        applyPickerColor()
    end

    S.__helpers.connect(square.InputBegan, function(input)
        if not picker.Visible then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragMode = "SV"
            updateFromPointer("SV", input.Position)
        end
    end)
    S.__helpers.connect(hueStrip.InputBegan, function(input)
        if not picker.Visible then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragMode = "Hue"
            updateFromPointer("Hue", input.Position)
        end
    end)
    S.__helpers.connect(S.UserInputService.InputChanged, function(input)
        if not picker.Visible or not dragMode then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch then
            updateFromPointer(dragMode, input.Position)
        end
    end)
    S.__helpers.connect(S.UserInputService.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            dragMode = nil
        end
    end)
    S.__helpers.connect(S.UserInputService.InputBegan, function(input)
        if picker.Visible and input.KeyCode == Enum.KeyCode.Escape then
            picker.Visible = false
            dragMode = nil
        end
    end)

    local function applyManualInput(box)
        local selected = S.__helpers.parseESPColor(box.Text)
        if not selected then
            refreshPickerVisuals(Color3.fromHSV(currentHue, currentSaturation, currentValue), true)
            return
        end
        refreshPickerVisuals(selected, true)
        if activeControl and type(activeControl.onChange) == "function" then
            local ok, err = pcall(activeControl.onChange, selected)
            if not ok then warn("[ELHUB ESP Color] " .. tostring(err)) end
        end
    end
    S.__helpers.connect(hexBox.FocusLost, function() applyManualInput(hexBox) end)
    S.__helpers.connect(rgbBox.FocusLost, function() applyManualInput(rgbBox) end)

    S.__helpers.connect(copyButton.Activated, function()
        local value = hexBox.Text
        local clipboard = setclipboard
        if type(clipboard) ~= "function" then clipboard = toclipboard end
        if type(clipboard) ~= "function" then clipboard = set_clipboard end
        if type(clipboard) == "function" then
            pcall(clipboard, value)
        end
    end)

    S.__helpers.connect(pasteButton.Activated, function()
        local clipboard = getclipboard
        if type(clipboard) ~= "function" then clipboard = readclipboard end
        local raw = nil
        if type(clipboard) == "function" then
            local ok, value = pcall(clipboard)
            if ok then raw = value end
        end
        local selected = S.__helpers.parseESPColor(raw)
        if selected then
            refreshPickerVisuals(selected, true)
            if activeControl and type(activeControl.onChange) == "function" then
                local ok, err = pcall(activeControl.onChange, selected)
                if not ok then warn("[ELHUB ESP Color] " .. tostring(err)) end
            end
        end
    end)
    S.__helpers.connect(closeButton.Activated, function()
        picker.Visible = false
        dragMode = nil
    end)

    local api = {
        frame = picker,
        openFor = function(controlTitle, color, onChange, owner)
            activeControl = {onChange = onChange, owner = owner}
            title.Text = tostring(controlTitle or "Color")
            refreshPickerVisuals(color or Color3.new(1, 1, 1), true)
            picker.Visible = true
            picker.Position = UDim2.new(0.5, -142, 0.5, -175)
            dragMode = nil
        end,
        isOpenFor = function(owner)
            return picker.Visible and activeControl ~= nil and activeControl.owner == owner
        end,
        setColor = function(color, owner)
            if owner and (not activeControl or activeControl.owner ~= owner) then return end
            refreshPickerVisuals(color, true)
        end,
        close = function()
            picker.Visible = false
            dragMode = nil
        end,
    }
    S.espColorPickerUI = api
    return api
end

