-- A compact row with a preview swatch; click the swatch for the full HSV picker.
-- The row HEX field remains editable and is retained by the Config system.
S.__helpers.createESPColorControl = function(labelText, initialColor, callback, allowAutoDefault, parent)
    local defaultColor = initialColor or Color3.new(1, 1, 1)
    local container = Instance.new("Frame")
    container.Name = "ESPColorControl"
    container.Size = parent and UDim2.new(1, 0, 0, 34) or UDim2.new(0.92, 0, 0, 34)
    container.BackgroundTransparency = 1
    container.BorderSizePixel = 0
    if parent then container.LayoutOrder = #parent:GetChildren() end
    container.Parent = parent or S.contentFrame

    local label = Instance.new("TextLabel")
    label.Name = "ColorLabel"
    label.Size = UDim2.new(1, -148, 1, 0)
    label.Position = UDim2.new(0, 0, 0, 0)
    label.BackgroundTransparency = 1
    label.Text = tostring(labelText or "Color")
    label.TextColor3 = Color3.fromRGB(205, 203, 213)
    label.Font = Enum.Font.GothamSemibold
    label.TextSize = 10
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = container

    local box = Instance.new("TextBox")
    box.Name = "HexValue"
    box.Size = UDim2.new(0, 82, 0, 24)
    box.Position = UDim2.new(1, -110, 0, 5)
    box.BackgroundColor3 = Color3.fromRGB(48, 47, 56)
    box.BorderSizePixel = 0
    box.Text = S.__helpers.color3ToHex(defaultColor)
    box.PlaceholderText = "#RRGGBB"
    box.TextColor3 = Color3.fromRGB(245, 244, 249)
    box.PlaceholderColor3 = Color3.fromRGB(135, 133, 145)
    box.Font = Enum.Font.Gotham
    box.TextSize = 10
    box.ClearTextOnFocus = false
    box.TextXAlignment = Enum.TextXAlignment.Center
    box.Parent = container
    local boxCorner = Instance.new("UICorner")
    boxCorner.CornerRadius = UDim.new(0, 4)
    boxCorner.Parent = box

    local swatch = Instance.new("TextButton")
    swatch.Name = "ColorPreview"
    swatch:SetAttribute("E1LU4HUB_PopupOpener", true)
    swatch.Size = UDim2.new(0, 24, 0, 24)
    swatch.Position = UDim2.new(1, -24, 0, 5)
    swatch.BackgroundColor3 = defaultColor
    swatch.BorderSizePixel = 0
    swatch.Text = ""
    swatch.AutoButtonColor = true
    swatch.Parent = container
    local swatchCorner = Instance.new("UICorner")
    swatchCorner.CornerRadius = UDim.new(0, 4)
    swatchCorner.Parent = swatch
    local swatchStroke = Instance.new("UIStroke")
    swatchStroke.Color = Color3.fromRGB(92, 90, 104)
    swatchStroke.Thickness = 1
    swatchStroke.Parent = swatch

    local hasCustomColor = false
    local picker = S.__helpers.getESPColorPicker()
    local function setColorFromText(rawValue)
        local rawText = tostring(rawValue or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if allowAutoDefault and rawText:upper() == "AUTO" then
            hasCustomColor = false
            swatch.BackgroundColor3 = defaultColor
            box.Text = S.__helpers.color3ToHex(defaultColor)
            if type(callback) == "function" then
                local ok, err = pcall(callback, nil)
                if not ok then
                    warn("[ELHUB ESP Color] " .. tostring(err))
                    return false
                end
            end
            if picker.isOpenFor(swatch) then picker.setColor(defaultColor, swatch) end
            return true
        end

        local selected = S.__helpers.parseESPColor(rawText)
        if not selected then
            box.Text = hasCustomColor
                and S.__helpers.color3ToHex(swatch.BackgroundColor3)
                or S.__helpers.color3ToHex(defaultColor)
            return false
        end
        hasCustomColor = true
        swatch.BackgroundColor3 = selected
        box.Text = S.__helpers.color3ToHex(selected)
        if type(callback) == "function" then
            local ok, err = pcall(callback, selected)
            if not ok then
                warn("[ELHUB ESP Color] " .. tostring(err))
                return false
            end
        end
        if picker.isOpenFor(swatch) then picker.setColor(selected, swatch) end
        return true
    end

    S.__helpers.connect(box.FocusLost, function()
        setColorFromText(box.Text)
    end)
    S.__helpers.connect(swatch.Activated, function()
        if picker.isOpenFor(swatch) then
            picker.close()
        else
            picker.openFor(labelText, swatch.BackgroundColor3, function(selected)
                hasCustomColor = true
                swatch.BackgroundColor3 = selected
                box.Text = S.__helpers.color3ToHex(selected)
                if type(callback) == "function" then
                    local ok, err = pcall(callback, selected)
                    if not ok then warn("[ELHUB ESP Color] " .. tostring(err)) end
                end
            end, swatch)
        end
    end)

    table.insert(S.configColorRegistry, {
        label = labelText,
        box = box,
        getValue = function()
            return allowAutoDefault and not hasCustomColor and "AUTO" or box.Text
        end,
        setValue = setColorFromText,
    })

    return container, box, swatch
end

