-- READY (green) state can override fill / outline opacity independently.
S.__helpers.createNumericControl(
    "HITBOX PREDICTION READY (GREEN) FILL OPACITY (%)",
    math.floor((S.HITBOX_PREDICTION_READY_FILL_TRANSPARENCY or S.HITBOX_PREDICTION_FILL_TRANSPARENCY) * 100 + 0.5),
    0, 100, 1,
    function(value)
        local normalized = math.clamp(tonumber(value) or 100, 0, 100) / 100
        if not S.hitboxPredictionReadyFillTransparencyControlInitialized then
            -- Keep the default inherited opacity during the control's
            -- one-time initialization callback.
            S.hitboxPredictionReadyFillTransparencyControlInitialized = true
            S.__helpers.updateHitboxPredictionESPTransparency()
            return math.floor((S.HITBOX_PREDICTION_READY_FILL_TRANSPARENCY or S.HITBOX_PREDICTION_FILL_TRANSPARENCY) * 100 + 0.5)
        end
        S.HITBOX_PREDICTION_READY_FILL_TRANSPARENCY = normalized
        S.__helpers.updateHitboxPredictionESPTransparency()
        return math.floor(normalized * 100 + 0.5)
    end,
    S.hitboxPredictionSettingsHolder
)
S.__helpers.createNumericControl(
    "HITBOX PREDICTION READY (GREEN) OUTLINE OPACITY (%)",
    math.floor((
        S.HITBOX_PREDICTION_READY_OUTLINE_TRANSPARENCY
        or S.HITBOX_PREDICTION_READY_DEFAULT_OUTLINE_TRANSPARENCY
        or S.HITBOX_PREDICTION_DEFAULT_OUTLINE_TRANSPARENCY
    ) * 100 + 0.5),
    0, 100, 1,
    function(value)
        local normalized = math.clamp(tonumber(value) or 25, 0, 100) / 100
        if not S.hitboxPredictionReadyOutlineTransparencyControlInitialized then
            -- Preserve inheritance until the user actually edits this control.
            S.hitboxPredictionReadyOutlineTransparencyControlInitialized = true
            S.HITBOX_PREDICTION_READY_OUTLINE_TRANSPARENCY = nil
            S.__helpers.updateHitboxPredictionESPTransparency()
            return math.floor((S.HITBOX_PREDICTION_READY_DEFAULT_OUTLINE_TRANSPARENCY or S.HITBOX_PREDICTION_DEFAULT_OUTLINE_TRANSPARENCY) * 100 + 0.5)
        end
        S.HITBOX_PREDICTION_READY_OUTLINE_TRANSPARENCY = normalized
        S.__helpers.updateHitboxPredictionESPTransparency()
        return math.floor(normalized * 100 + 0.5)
    end,
    S.hitboxPredictionSettingsHolder
)

