S.__helpers.getPing = function()
    local success, val = pcall(function()
        return game:GetService("Stats")
            .Network.ServerStatsItem["Data Ping"]:GetValue()
    end)

    if success and val then
        return val
    end

    local success2, val2 = pcall(function()
        return S.lp:GetNetworkPing() * 1000
    end)

    if success2 and val2 then
        return val2
    end

    return nil
end

-- Executor status uses the reference script's live FPS counter pattern:
-- count rendered frames, publish the count once per approximately one second,
-- and refresh the Stats Data Ping value in the same status line.
S.executorStatusFPS = 0
S.executorStatusFPSFrames = 0
S.executorStatusFPSElapsed = 0
S.__helpers.updateExecutorStatusText = function()
    local pingValue = tonumber(S.__helpers.getPing())
    local pingText = pingValue and tostring(math.floor(pingValue + 0.5)) or "--"
    local fps = math.max(0, math.floor(tonumber(S.executorStatusFPS) or 0))
    local executor = tostring(S.executorName or "Unknown")
    local statusText = "E1LU4 HUB | " .. executor
    if S.isShowFPSPingEnabled == true then
        statusText ..= " | FPS: " .. tostring(fps)
            .. " | Ping: " .. pingText .. "ms"
    end

    if S.executorStatusLabel and S.executorStatusLabel.Parent then
        S.executorStatusLabel.Text = statusText
        -- Measure the actual line and trim the strip to a small 8px right inset.
        -- This removes the oversized empty area while keeping the text readable.
        local measuredWidth = nil
        local measureOK, measured = pcall(function()
            return game:GetService("TextService"):GetTextSize(
                statusText,
                S.executorStatusLabel.TextSize,
                S.executorStatusLabel.Font,
                Vector2.new(1000, 42)
            )
        end)
        if measureOK and measured then measuredWidth = measured.X end
        if measuredWidth and S.executorStatusBar and S.executorStatusBar.Parent then
            local compactWidth = math.clamp(math.ceil(measuredWidth) + 58, 220, 420)
            S.executorStatusBar.Size = UDim2.fromOffset(compactWidth, 42)
            S.executorStatusLabel.Size = UDim2.new(1, -50, 1, 0)
        end
    end
    if S.executorInfoDetails and S.executorInfoDetails.Parent then
        local version = S.executorVersion and tostring(S.executorVersion) or "Unavailable"
        local detailsText = "Executor: " .. executor
            .. "\nVersion: " .. version
        if S.isShowFPSPingEnabled == true then
            detailsText ..= "\nFPS: " .. tostring(fps)
                .. "\nPing: " .. pingText .. "ms"
        end
        S.executorInfoDetails.Text = detailsText
    end
end

S.__helpers.connect(S.RunService.RenderStepped, function(deltaTime)
    S.executorStatusFPSFrames = S.executorStatusFPSFrames + 1
    S.executorStatusFPSElapsed = S.executorStatusFPSElapsed + (tonumber(deltaTime) or 0)
    if S.executorStatusFPSElapsed >= 1 then
        local elapsed = S.executorStatusFPSElapsed
        S.executorStatusFPS = math.floor((S.executorStatusFPSFrames / math.max(elapsed, 0.001)) + 0.5)
        S.executorStatusFPSFrames = 0
        S.executorStatusFPSElapsed = 0
        pcall(S.__helpers.updateExecutorStatusText)
    end
end)

