S.AzureTrapRadiusESPState = {
    running = false,
    folder = nil,
    connections = {},
    adornments = setmetatable({}, {__mode = "k"}),
    watchers = setmetatable({}, {__mode = "k"}),
}
S.__helpers.stopAzureTrapRadiusESP = function()
    local state = S.AzureTrapRadiusESPState
    state.running = false
    for _, connection in ipairs(state.connections or {}) do
        pcall(function() connection:Disconnect() end)
    end
    state.connections = {}
    for model, connection in pairs(state.watchers or {}) do
        pcall(function() connection:Disconnect() end)
        state.watchers[model] = nil
    end
    for target, adornment in pairs(state.adornments or {}) do
        if adornment and adornment.Parent then
            pcall(function() adornment:Destroy() end)
        end
        state.adornments[target] = nil
    end
    if state.folder and state.folder.Parent then
        pcall(function() state.folder:Destroy() end)
    end
    state.folder = nil
end
S.__helpers.startAzureTrapRadiusESP = function()
    local state = S.AzureTrapRadiusESPState
    if state.running then return end
    S.__helpers.stopAzureTrapRadiusESP()
    state.running = true
    state.connections = {}
    state.adornments = setmetatable({}, {__mode = "k"})
    state.watchers = setmetatable({}, {__mode = "k"})

    local folder = Instance.new("Folder")
    folder.Name = "E1LU4HUB_AzureTrapRadiusESP"
    folder.Parent = S.__helpers.getWorldRootFolder()
    state.folder = folder

    local function addModel(model)
        if not state.running or not model or not model:IsA("Model") or not model:IsDescendantOf(workspace) then return end
        local name = tostring(model.Name or "")
        local radius
        if name == "GroundBulbModel" or name:find("GroundBulb", 1, true) then
            radius = 30
        elseif name == "VineModel" or name:find("Vine", 1, true) then
            radius = 20
        end
        if not radius then return end

        local target = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true)
        if not target or state.adornments[target] then return end
        local adornment = Instance.new("CylinderHandleAdornment")
        adornment.Name = "AzureAttackRadius"
        adornment.Color3 = Color3.fromRGB(255, 30, 30)
        adornment.Transparency = 0.75
        adornment.Height = 0.05
        adornment.AlwaysOnTop = true
        adornment.Radius = radius
        adornment.CFrame = CFrame.Angles(math.pi / 2, 0, 0)
        adornment.Adornee = target
        adornment.Parent = folder
        state.adornments[target] = adornment

        if not state.watchers[model] then
            state.watchers[model] = model.AncestryChanged:Connect(function(_, parent)
                if parent == nil then
                    local old = state.adornments[target]
                    if old then pcall(function() old:Destroy() end); state.adornments[target] = nil end
                    local watcher = state.watchers[model]
                    if watcher then watcher:Disconnect(); state.watchers[model] = nil end
                end
            end)
        end
    end

    for _, descendant in ipairs(workspace:GetDescendants()) do
        if descendant:IsA("Model") then addModel(descendant) end
    end
    table.insert(state.connections, workspace.DescendantAdded:Connect(function(descendant)
        if descendant:IsA("Model") then
            task.delay(0.12, function() addModel(descendant) end)
        elseif descendant:IsA("BasePart") then
            local model = descendant:FindFirstAncestorOfClass("Model")
            if model then task.delay(0.12, function() addModel(model) end) end
        end
    end))
end

S.AzureTrapESPState = {
    running = false,
    folder = nil,
    connections = {},
    partConnections = setmetatable({}, {__mode = "k"}),
    highlights = setmetatable({}, {__mode = "k"}),
    counted = setmetatable({}, {__mode = "k"}),
    retryUntil = setmetatable({}, {__mode = "k"}),
    counts = {},
    blockedNames = {},
}

S.AZURE_TRAP_ESP_PART_NAMES = {
    Flower_Base = true,
    Flower_Bottom = true,
    Flower_Root = true,
    Flower_Tentacle = true,
    Flower_Top = true,
    Nectar = true,
    Root1 = true,
    Root2 = true,
    Root3 = true,
    Root4 = true,
    Tendril_Middle = true,
    Tentacle = true,
    ["Tentacle42.001"] = true,
    Tentacle_Base = true,
    GroundBulb = true,
    Vine = true,
}

S.__helpers.startAzureTrapESP = function()
    local state = S.AzureTrapESPState
    if state.running then return end
    state.running = true
    state.connections = {}
    state.partConnections = setmetatable({}, {__mode = "k"})
    state.highlights = setmetatable({}, {__mode = "k"})
    state.counted = setmetatable({}, {__mode = "k"})
    state.retryUntil = setmetatable({}, {__mode = "k"})
    state.counts = {}
    state.blockedNames = {}

    local MAX_PARTS_PER_NAME = 6
    local RETRY_SECONDS = 5
    local RETRY_INTERVAL = 0.3
    local TRAP_COLOR = S.AZURE_TRAP_ESP_COLOR or Color3.fromRGB(160, 32, 240)
    local lobbyKeywords = {"lobby", "spawn", "menu", "waitingroom", "decor", "ambient"}

    local worldRootFolder = S.__helpers.getWorldRootFolder()
    local oldFolder = worldRootFolder:FindFirstChild(S.AZURE_TRAP_ESP_FOLDER_NAME)
    if oldFolder then pcall(function() oldFolder:Destroy() end) end

    local folder = Instance.new("Folder")
    folder.Name = S.AZURE_TRAP_ESP_FOLDER_NAME
    folder.Parent = worldRootFolder
    state.folder = folder

    local handlePart
    local cleanupPart

    local function isPlayerCharacterPart(part)
        for _, player in ipairs(S.Players:GetPlayers()) do
            local character = player.Character
            if character and part:IsDescendantOf(character) then
                return true
            end
        end
        local model = part:FindFirstAncestorOfClass("Model")
        return model ~= nil and model:FindFirstChildOfClass("Humanoid") ~= nil
    end

    local function isInLobby(part)
        local ancestor = part.Parent
        while ancestor and ancestor ~= workspace do
            local name = tostring(ancestor.Name):lower()
            for _, keyword in ipairs(lobbyKeywords) do
                if name:find(keyword, 1, true) then
                    return true
                end
            end
            ancestor = ancestor.Parent
        end
        return false
    end

    local function clearHighlightsForName(partName)
        for part, highlight in pairs(state.highlights) do
            if part and part.Name == partName then
                if highlight and highlight.Parent then
                    pcall(function() highlight:Destroy() end)
                end
                state.highlights[part] = nil
            end
        end
    end

    local function refreshNameIfUnblocked(partName)
        if not state.running or state.blockedNames[partName] then return end
        task.defer(function()
            if not state.running or state.blockedNames[partName] then return end
            for _, object in ipairs(workspace:GetDescendants()) do
                if object:IsA("BasePart") and object.Name == partName then
                    handlePart(object)
                end
            end
        end)
    end

    local function updateNameLimit(partName)
        local count = state.counts[partName] or 0
        if count > MAX_PARTS_PER_NAME then
            state.blockedNames[partName] = true
            clearHighlightsForName(partName)
        elseif state.blockedNames[partName] then
            state.blockedNames[partName] = nil
            refreshNameIfUnblocked(partName)
        end
    end

    cleanupPart = function(part)
        if not part then return end
        local partName = part.Name

        local highlight = state.highlights[part]
        if highlight then
            if highlight.Parent then pcall(function() highlight:Destroy() end) end
            state.highlights[part] = nil
        end

        state.retryUntil[part] = nil

        local connection = state.partConnections[part]
        if connection then
            pcall(function() connection:Disconnect() end)
            state.partConnections[part] = nil
        end

        if state.counted[part] then
            state.counted[part] = nil
            state.counts[partName] = math.max(0, (state.counts[partName] or 1) - 1)
            updateNameLimit(partName)
        end
    end

    local function watchPartLifetime(part)
        if state.partConnections[part] then return end
        state.partConnections[part] = part.AncestryChanged:Connect(function()
            if not state.running then return end
            local stillInWorkspace = false
            pcall(function() stillInWorkspace = part:IsDescendantOf(workspace) end)
            if not stillInWorkspace then
                cleanupPart(part)
            end
        end)
    end

    local function registerPart(part)
        if not part or not part:IsA("BasePart")
            or not S.AZURE_TRAP_ESP_PART_NAMES[part.Name]
            or not part:IsDescendantOf(workspace) then
            return
        end
        watchPartLifetime(part)
        if not state.counted[part] then
            state.counted[part] = true
            state.counts[part.Name] = (state.counts[part.Name] or 0) + 1
            updateNameLimit(part.Name)
        end
    end

    handlePart = function(part)
        if not state.running or not part or not part.Parent
            or not part:IsA("BasePart")
            or not part:IsDescendantOf(workspace)
            or not S.AZURE_TRAP_ESP_PART_NAMES[part.Name] then
            return false
        end

        registerPart(part)
        if state.blockedNames[part.Name]
            or isPlayerCharacterPart(part)
            or isInLobby(part) then
            return false
        end

        local current = state.highlights[part]
        if current and current.Parent then
            return true
        end
        state.highlights[part] = nil

        local highlight = Instance.new("Highlight")
        highlight.Name = "AzureTrapESP_Highlight"
        highlight.Adornee = part
        highlight.FillColor = TRAP_COLOR
        highlight.FillTransparency = 0.75
        highlight.OutlineColor = TRAP_COLOR
        highlight.OutlineTransparency = 0
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.Parent = folder
        state.highlights[part] = highlight
        return true
    end

    -- Count existing matching parts first, preserving the supplied source's
    -- safeguard that suppresses a part name when more than six copies exist.
    local existingParts = {}
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("BasePart") and S.AZURE_TRAP_ESP_PART_NAMES[object.Name] then
            state.counted[object] = true
            state.counts[object.Name] = (state.counts[object.Name] or 0) + 1
            table.insert(existingParts, object)
        end
    end
    for partName, count in pairs(state.counts) do
        if count > MAX_PARTS_PER_NAME then
            state.blockedNames[partName] = true
        end
    end
    for _, part in ipairs(existingParts) do
        watchPartLifetime(part)
        handlePart(part)
    end

    table.insert(state.connections, workspace.DescendantAdded:Connect(function(object)
        if not state.running or not object:IsA("BasePart")
            or not S.AZURE_TRAP_ESP_PART_NAMES[object.Name] then
            return
        end
        registerPart(object)
        state.retryUntil[object] = os.clock() + RETRY_SECONDS
        if handlePart(object) then
            state.retryUntil[object] = nil
        end
    end))

    task.spawn(function()
        while state.running do
            task.wait(RETRY_INTERVAL)
            local now = os.clock()
            for part, expiresAt in pairs(state.retryUntil) do
                if not part.Parent or not part:IsDescendantOf(workspace) then
                    cleanupPart(part)
                elseif now >= expiresAt then
                    state.retryUntil[part] = nil
                elseif handlePart(part) then
                    state.retryUntil[part] = nil
                end
            end
        end
    end)
end

S.__helpers.stopAzureTrapESP = function()
    local state = S.AzureTrapESPState
    state.running = false

    for _, connection in ipairs(state.connections or {}) do
        pcall(function() connection:Disconnect() end)
    end
    state.connections = {}

    for part, connection in pairs(state.partConnections or {}) do
        pcall(function() connection:Disconnect() end)
        state.partConnections[part] = nil
    end
    for part, highlight in pairs(state.highlights or {}) do
        if highlight and highlight.Parent then
            pcall(function() highlight:Destroy() end)
        end
        state.highlights[part] = nil
    end
    table.clear(state.counted)
    table.clear(state.retryUntil)
    table.clear(state.counts)
    table.clear(state.blockedNames)

    if state.folder and state.folder.Parent then
        pcall(function() state.folder:Destroy() end)
    end
    state.folder = nil
end

-- ================================================================

-- JD DIGITAL FOOTPRINTS ESP (ported from Betrayalsaken.lua).
-- John Doe's Shadow parts under *Shadows containers receive a red highlight
-- and ground rings only; this ESP intentionally has no text label.
S.__helpers.isJDDigitalFootprint = function(object)
    if not object or not object:IsA("BasePart") or object.Name ~= "Shadow" then
        return false
    end
    local parent = object.Parent
    return parent ~= nil and parent.Name:match("Shadows$") ~= nil
end

S.__helpers.clearJDDigitalFootprintsESP = function()
    for part, entry in pairs(S.jdDigitalFootprintEntries or {}) do
        if entry.sizeConnection then
            pcall(function() entry.sizeConnection:Disconnect() end)
        end
        if entry.ancestryConnection then
            pcall(function() entry.ancestryConnection:Disconnect() end)
        end
        if entry.highlight and entry.highlight.Parent then
            pcall(function() entry.highlight:Destroy() end)
        end
        if entry.holder and entry.holder.Parent then
            pcall(function() entry.holder:Destroy() end)
        end
        S.jdDigitalFootprintEntries[part] = nil
    end
end

S.__helpers.addJDDigitalFootprintESP = function(part)
    if not S.isJDDigitalFootprintsESPEnabled
        or not S.__helpers.isJDDigitalFootprint(part)
        or S.jdDigitalFootprintEntries[part] then
        return
    end

    local entry = {}
    local highlight = Instance.new("Highlight")
    highlight.Name = "E1LU4HUB_JDDigitalFootprints_Highlight"
    highlight.FillColor = Color3.fromRGB(255, 50, 50)
    highlight.FillTransparency = S.ESP_FILL_TRANSPARENCY or 0.55
    highlight.OutlineColor = Color3.fromRGB(255, 50, 50)
    highlight.OutlineTransparency = 0.1
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Adornee = part
    highlight.Parent = part
    entry.highlight = highlight

    local radius = math.max(math.max(part.Size.X, part.Size.Z) * 0.5, 3)
    local holder = Instance.new("Part")
    holder.Name = "E1LU4HUB_JDDigitalFootprints_Holder"
    holder.Size = Vector3.new(1, 0.1, 1)
    holder.Transparency = 1
    holder.CanCollide = false
    holder.CanTouch = false
    holder.CanQuery = false
    holder.Anchored = true
    holder.Position = part.Position + Vector3.new(0, 0.05, 0)
    holder.Parent = part
    entry.holder = holder

    local blackRing = Instance.new("CylinderHandleAdornment")
    blackRing.Name = "JDDigitalFootprints_BlackRing"
    blackRing.Adornee = holder
    blackRing.Color3 = Color3.fromRGB(0, 0, 0)
    blackRing.Transparency = 0.2
    blackRing.Radius = radius
    blackRing.Height = 0.02
    blackRing.CFrame = CFrame.Angles(math.rad(90), 0, 0)
    blackRing.ZIndex = 5
    blackRing.AlwaysOnTop = true
    blackRing.Parent = holder
    entry.blackRing = blackRing

    local redRing = Instance.new("CylinderHandleAdornment")
    redRing.Name = "JDDigitalFootprints_RedRing"
    redRing.Adornee = holder
    redRing.Color3 = Color3.fromRGB(255, 0, 0)
    redRing.Transparency = 0.4
    redRing.Radius = radius + 0.8
    redRing.Height = 0.02
    redRing.CFrame = CFrame.Angles(math.rad(90), 0, 0)
    redRing.ZIndex = 4
    redRing.AlwaysOnTop = true
    redRing.Parent = holder
    entry.redRing = redRing

    S.jdDigitalFootprintEntries[part] = entry

    entry.sizeConnection = part:GetPropertyChangedSignal("Size"):Connect(function()
        if not part.Parent or not holder.Parent then return end
        local nextRadius = math.max(math.max(part.Size.X, part.Size.Z) * 0.5, 3)
        blackRing.Radius = nextRadius
        redRing.Radius = nextRadius + 0.8
    end)
    entry.ancestryConnection = part.AncestryChanged:Connect(function()
        if part.Parent then return end
        if entry.sizeConnection then pcall(function() entry.sizeConnection:Disconnect() end) end
        if entry.ancestryConnection then pcall(function() entry.ancestryConnection:Disconnect() end) end
        if highlight and highlight.Parent then pcall(function() highlight:Destroy() end) end
        if holder and holder.Parent then pcall(function() holder:Destroy() end) end
        S.jdDigitalFootprintEntries[part] = nil
    end)
end

S.jdDigitalFootprintBaseline = setmetatable({}, {__mode = "k"})
S.jdDigitalFootprintAddedConnection = nil
S.__helpers.disconnectJDDigitalFootprintAddedConnection = function()
    local connection = S.jdDigitalFootprintAddedConnection
    S.jdDigitalFootprintAddedConnection = nil
    if connection then pcall(function() connection:Disconnect() end) end
end

S.__helpers.setJDDigitalFootprintsESP = function(enabled)
    S.isJDDigitalFootprintsESPEnabled = enabled == true
    S.jdDigitalFootprintESPToken = (S.jdDigitalFootprintESPToken or 0) + 1
    local token = S.jdDigitalFootprintESPToken
    S.__helpers.disconnectJDDigitalFootprintAddedConnection()
    S.__helpers.clearJDDigitalFootprintsESP()
    S.jdDigitalFootprintBaseline = setmetatable({}, {__mode = "k"})

    if not S.isJDDigitalFootprintsESPEnabled then
        return
    end

    task.spawn(function()
        local boundCharacter = nil
        local boundRole = nil
        while S.isJDDigitalFootprintsESPEnabled and S.jdDigitalFootprintESPToken == token do
            local character = S.lp and S.lp.Character
            local role = S.__helpers.getLocalRole()
            local eligibleRole = role == "Survivor" or role == "Killer"

            if not character or not eligibleRole then
                if boundCharacter ~= nil or S.jdDigitalFootprintAddedConnection then
                    S.__helpers.disconnectJDDigitalFootprintAddedConnection()
                    S.__helpers.clearJDDigitalFootprintsESP()
                    S.jdDigitalFootprintBaseline = setmetatable({}, {__mode = "k"})
                    boundCharacter = nil
                    boundRole = nil
                end
                task.wait(0.2)
            elseif character ~= boundCharacter or role ~= boundRole then
                -- On role/character entry, wait one second, then snapshot everything
                -- already present. Only footprints created after this baseline are ESP'd.
                S.__helpers.disconnectJDDigitalFootprintAddedConnection()
                S.__helpers.clearJDDigitalFootprintsESP()
                S.jdDigitalFootprintBaseline = setmetatable({}, {__mode = "k"})
                boundCharacter = character
                boundRole = role
                local startedAt = os.clock()
                while S.isJDDigitalFootprintsESPEnabled
                    and S.jdDigitalFootprintESPToken == token
                    and S.lp and S.lp.Character == boundCharacter
                    and S.__helpers.getLocalRole() == boundRole
                    and os.clock() - startedAt < 1 do
                    task.wait(0.05)
                end

                if S.isJDDigitalFootprintsESPEnabled and S.jdDigitalFootprintESPToken == token
                    and S.lp and S.lp.Character == boundCharacter
                    and S.__helpers.getLocalRole() == boundRole then
                    local baseline = setmetatable({}, {__mode = "k"})
                    for _, object in ipairs(workspace:GetDescendants()) do
                        if S.__helpers.isJDDigitalFootprint(object) then
                            baseline[object] = true
                        end
                    end
                    S.jdDigitalFootprintBaseline = baseline
                    -- Capture this role session so delayed events from a previous
                    -- role cannot be mistaken for fresh footprints in the next one.
                    local eventCharacter, eventRole, eventBaseline = boundCharacter, boundRole, baseline
                    S.jdDigitalFootprintAddedConnection = workspace.DescendantAdded:Connect(function(object)
                        task.delay(0.12, function()
                            if not S.isJDDigitalFootprintsESPEnabled
                                or S.jdDigitalFootprintESPToken ~= token
                                or not S.lp or S.lp.Character ~= eventCharacter
                                or S.__helpers.getLocalRole() ~= eventRole then
                                return
                            end
                            local function addIfNew(candidate)
                                if candidate and not eventBaseline[candidate]
                                    and S.__helpers.isJDDigitalFootprint(candidate) then
                                    eventBaseline[candidate] = true
                                    pcall(S.__helpers.addJDDigitalFootprintESP, candidate)
                                end
                            end
                            addIfNew(object)
                            pcall(function()
                                for _, descendant in ipairs(object:GetDescendants()) do
                                    addIfNew(descendant)
                                end
                            end)
                        end)
                    end)
                else
                    boundCharacter = nil
                    boundRole = nil
                end
                task.wait(0.1)
            else
                task.wait(0.2)
            end
        end

        if S.jdDigitalFootprintESPToken == token then
            S.__helpers.disconnectJDDigitalFootprintAddedConnection()
            S.__helpers.clearJDDigitalFootprintsESP()
        end
    end)
end

S.__helpers.createSectionHeader("ESP")
-- Extra ESP toggles ported from the second supplied file.
-- All non-excluded ESP highlights use the matching Killer/Survivor opacity settings.
-- JD Digital Footprints, Azure Trap, and Azure Bulb/Vine Ranges keep their dedicated opacity.
S.extraESPStates = S.extraESPStates or {}
S.__helpers.setExtraESP = function(key, enabled, targetNames, labelText, color, useRespawnPattern, showLabel, matchKillerStyle, transparencyRole)
    local states = S.extraESPStates
    local state = states[key]
    if not state then
        state = { enabled = false, connections = {}, objects = {} }
        states[key] = state
    end
    if state.defaultColor == nil then state.defaultColor = color end
    if state.color == nil and not state.colorOverride then state.color = color end
    state.matchKillerStyle = matchKillerStyle == true
    -- Keep object ESP color styling independent from which role transparency it follows.
    state.transparencyRole = transparencyRole or (matchKillerStyle == true and "Killer" or "Survivor")
    state.enabled = enabled == true

    local function clearObject(object)
        local entry = state.objects[object]
        if not entry then return end
        for _, instance in ipairs(entry) do
            if instance and instance.Parent then
                pcall(function() instance:Destroy() end)
            end
        end
        state.objects[object] = nil
    end

    local function matches(object)
        if not object then return false end
        if useRespawnPattern then
            return object.Name:find("RespawnLocation") ~= nil
        end
        for _, targetName in ipairs(targetNames) do
            if object.Name == targetName then return true end
        end
        return false
    end

    local function addObject(object)
        if not state.enabled or not matches(object) or state.objects[object] then return end
        local adornee = object
        if object:IsA("Model") then
            adornee = object
        elseif not object:IsA("BasePart") then
            adornee = object:FindFirstChildWhichIsA("BasePart", true)
        end
        if not adornee then return end

        local made = {}
        if object:IsA("Model") or object:IsA("BasePart") then
            local highlight = Instance.new("Highlight")
            highlight.Name = "ELSGUI_ExtraESP_" .. key
            highlight.Adornee = object
            -- Optional exact Killer ESP styling: same fill/outline colors and
            -- the shared fill/outline transparency settings.
            local activeColor = state.color or color
            if state.colorOverride then
                highlight.FillColor = activeColor
                highlight.OutlineColor = activeColor:Lerp(Color3.fromRGB(255, 255, 255), 0.25)
            elseif matchKillerStyle then
                highlight.FillColor = S.KILLER_ESP_FILL_COLOR
                highlight.OutlineColor = S.KILLER_ESP_OUTLINE_COLOR
            else
                highlight.FillColor = state.defaultColor or activeColor
                highlight.OutlineColor = state.defaultColor or activeColor
            end
            local useKillerTransparency = state.transparencyRole == "Killer"
            highlight.FillTransparency = useKillerTransparency
                and S.KILLER_ESP_FILL_TRANSPARENCY or S.SURVIVOR_ESP_FILL_TRANSPARENCY
            highlight.OutlineTransparency = useKillerTransparency
                and S.KILLER_ESP_OUTLINE_TRANSPARENCY or S.SURVIVOR_ESP_OUTLINE_TRANSPARENCY
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Parent = object
            -- Keep the native Highlight fill and outline; no proxy overlay is generated.
            table.insert(made, highlight)
        end

        local labelAdornee = object:IsA("Model") and (object.PrimaryPart or object:FindFirstChildWhichIsA("BasePart", true)) or adornee
        if labelAdornee and showLabel ~= false then
            local billboard = Instance.new("BillboardGui")
            billboard.Name = "ELSGUI_ExtraESPLabel_" .. key
            billboard.Adornee = labelAdornee
            billboard.Size = UDim2.new(0, 150, 0, 28)
            billboard.StudsOffset = Vector3.new(0, 3, 0)
            billboard.AlwaysOnTop = true
            billboard.MaxDistance = math.huge
            billboard.Parent = labelAdornee
            local text = Instance.new("TextLabel")
            text.Name = "Label"
            text.Size = UDim2.new(1, 0, 1, 0)
            text.BackgroundTransparency = 1
            text.TextTransparency = 0
            text.TextStrokeTransparency = 0.35
            text.TextScaled = true
            S.__helpers.applyESPTextFont(text)
            text.TextColor3 = state.color or color
            text.Text = useRespawnPattern
                and ((object.Name:match("^(.-)RespawnLocation") or "Unknown") .. " Respawn Point")
                or labelText
            text.Parent = billboard
            table.insert(made, billboard)
        end
        state.objects[object] = made
    end

    if state.scanConnection then state.scanConnection:Disconnect(); state.scanConnection = nil end
    if state.addConnection then state.addConnection:Disconnect(); state.addConnection = nil end
    if state.removeConnection then state.removeConnection:Disconnect(); state.removeConnection = nil end
    if not state.enabled then
        for object in pairs(state.objects) do clearObject(object) end
        return
    end

    local ingame = workspace:FindFirstChild("Map")
        and workspace.Map:FindFirstChild("Ingame")
    if not ingame then return end
    for _, child in ipairs(ingame:GetChildren()) do addObject(child) end
    state.addConnection = S.__helpers.connect(ingame.ChildAdded, function(child)
        task.defer(function() addObject(child) end)
    end)
    state.removeConnection = S.__helpers.connect(ingame.ChildRemoved, function(child)
        clearObject(child)
    end)
end

S.__helpers.setExtraESPColor = function(key, selectedColor)
    local states = S.extraESPStates
    local state = states[key]
    if not state then
        state = {enabled = false, connections = {}, objects = {}}
        states[key] = state
    end
    state.color = selectedColor
    state.colorOverride = selectedColor ~= nil
    local defaultFill = state.matchKillerStyle
        and S.KILLER_ESP_FILL_COLOR or state.defaultColor
    local defaultOutline = state.matchKillerStyle
        and S.KILLER_ESP_OUTLINE_COLOR or state.defaultColor
    for _, made in pairs(state.objects or {}) do
        for _, instance in ipairs(made) do
            if instance and instance.Parent then
                if instance:IsA("Highlight") then
                    instance.FillColor = selectedColor or defaultFill or Color3.fromRGB(255, 255, 255)
                    instance.OutlineColor = selectedColor
                        and selectedColor:Lerp(Color3.fromRGB(255, 255, 255), 0.25)
                        or defaultOutline or defaultFill or Color3.fromRGB(255, 255, 255)
                elseif instance:IsA("BillboardGui") then
                    local label = instance:FindFirstChild("Label")
                    if label and label:IsA("TextLabel") then
                        label.TextColor3 = selectedColor or defaultFill or Color3.fromRGB(255, 255, 255)
                    end
                end
            end
        end
    end
end

-- ================================================================
-- WORLD OBJECT ESPs PORTED FROM THE SUPPLIED XENONZ SOURCE
-- Veeronica Vandalism/Spray, Jane Doe Files, Subspace Tripmines,
-- and Subspace Tripwires. Each feature owns its objects and listeners.
-- ================================================================
S.worldKeywordESPStates = S.worldKeywordESPStates or {}

S.__helpers.setWorldKeywordESP = function(key, enabled, config)
    local states = S.worldKeywordESPStates
    local state = states[key]
    if not state then
        state = {
            enabled = false,
            objects = {},
            defaultColor = config and config.fillColor or Color3.new(1, 1, 1),
            outlineColor = config and config.outlineColor or Color3.new(1, 1, 1),
            color = nil,
            colorOverride = false,
            addConnection = nil,
        }
        states[key] = state
    end
    if config then
        state.config = config
        state.defaultColor = state.defaultColor or config.fillColor
        state.outlineColor = config.outlineColor or state.outlineColor
    end

    local function clearObject(target)
        local entry = state.objects[target]
        if not entry then return end
        if entry.ancestryConnection then
            pcall(function() entry.ancestryConnection:Disconnect() end)
        end
        if entry.highlight and entry.highlight.Parent then
            pcall(function() entry.highlight:Destroy() end)
        end
        state.objects[target] = nil
    end

    local function isPlayerCharacter(target)
        for _, player in ipairs(S.Players:GetPlayers()) do
            local character = player.Character
            if character and (target == character or target:IsDescendantOf(character)) then
                return true
            end
        end
        local playersFolder = workspace:FindFirstChild("Players")
        return playersFolder ~= nil and (target == playersFolder or target:IsDescendantOf(playersFolder))
    end

    local function resolveTarget(object)
        if not object or not object:IsDescendantOf(workspace) then
            return nil, nil
        end
        if object:IsA("Model") then
            local model = object
            local root = model.PrimaryPart
                or model:FindFirstChild("HumanoidRootPart")
                or model:FindFirstChildWhichIsA("BasePart", true)
            return root, model
        end
        if object:IsA("BasePart") then
            -- Keep the exact part as the adornee: Vandalism zones can be rotated
            -- independently from their containing model, and traps often have
            -- several differently named component parts.
            return object, object
        end
        local model = object:FindFirstAncestorOfClass("Model")
        if model then
            local root = model.PrimaryPart
                or model:FindFirstChild("HumanoidRootPart")
                or model:FindFirstChildWhichIsA("BasePart", true)
            return root, model
        end
        -- Match the reference source: only a Model or BasePart is an ESP target.
        -- Do not attach an ESP to the first random part inside a generic Folder.
        return nil, nil
    end

    local function nameMatches(object)
        if not object or not state.config then return false end
        local name = tostring(object.Name or ""):lower()
        for _, keyword in ipairs(state.config.keywords or {}) do
            if name:find(keyword, 1, true) then
                -- Avoid treating a generic map/quest container as an individual file.
                if key == "Files" and (keyword == "basement" or keyword == "quest"
                    or keyword == "collectible" or keyword == "pickup") then
                    local specific = name:find("file", 1, true)
                        or name:find("doc", 1, true)
                        or name:find("note", 1, true)
                        or name:find("record", 1, true)
                        or name:find("letter", 1, true)
                    if not specific then return false end
                end
                return true
            end
        end
        return false
    end

    local function addObject(object)
        if not state.enabled or not nameMatches(object) then return end
        local adornee, target = resolveTarget(object)
        if not adornee or not target or isPlayerCharacter(target) then return end
        -- A named parent Model already covers all matching descendants.
        local ancestor = target.Parent
        while ancestor and ancestor ~= workspace do
            if state.objects[ancestor] then return end
            ancestor = ancestor.Parent
        end

        local existing = state.objects[target]
        if existing then
            local highlightAlive = existing.highlight and existing.highlight.Parent
            if highlightAlive then return end
            clearObject(target)
        end

        -- If a Model itself becomes a match after a descendant was tracked,
        -- keep only the Model-level Highlight to avoid stacked duplicate boxes.
        if target:IsA("Model") then
            local descendantsToClear = {}
            for existingTarget in pairs(state.objects) do
                if existingTarget ~= target and existingTarget:IsDescendantOf(target) then
                    table.insert(descendantsToClear, existingTarget)
                end
            end
            for _, existingTarget in ipairs(descendantsToClear) do
                clearObject(existingTarget)
            end
        end

        local fill = state.color or state.defaultColor
        local outline = state.colorOverride
            and fill:Lerp(Color3.fromRGB(255, 255, 255), 0.25)
            or state.outlineColor

        local highlight = Instance.new("Highlight")
        highlight.Name = "ELSGUI_WorldESP_" .. key .. "_Highlight"
        highlight.Adornee = target
        highlight.FillColor = fill
        highlight.OutlineColor = outline
        -- Tripmine / Tripwire are Killer-side world hazards, so they use Killer ESP opacity.
        highlight.FillTransparency = S.KILLER_ESP_FILL_TRANSPARENCY
        highlight.OutlineTransparency = S.KILLER_ESP_OUTLINE_TRANSPARENCY
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.Parent = target

        -- These world-object ESPs are highlight-only; no BillboardGui/TextLabel is created.
        local entry = {highlight = highlight, ancestryConnection = nil}
        state.objects[target] = entry
        entry.ancestryConnection = target.AncestryChanged:Connect(function()
            if not target:IsDescendantOf(workspace) then
                clearObject(target)
            end
        end)
    end

    state.applyObject = addObject
    if state.addConnection then
        pcall(function() state.addConnection:Disconnect() end)
        state.addConnection = nil
    end
    state.enabled = enabled == true
    if not state.enabled then
        local targets = {}
        for target in pairs(state.objects) do table.insert(targets, target) end
        for _, target in ipairs(targets) do clearObject(target) end
        return
    end

    -- Full initial scan; the listener below handles objects created later.
    for _, object in ipairs(workspace:GetDescendants()) do
        addObject(object)
    end
    state.addConnection = workspace.DescendantAdded:Connect(function(object)
        task.defer(function()
            if state.enabled then
                pcall(addObject, object)
            end
        end)
    end)
end

S.__helpers.setWorldKeywordESPColor = function(key, selectedColor)
    local state = S.worldKeywordESPStates and S.worldKeywordESPStates[key]
    if not state then return end
    state.color = selectedColor
    state.colorOverride = selectedColor ~= nil
    local fill = selectedColor or state.defaultColor
    local outline = selectedColor
        and selectedColor:Lerp(Color3.fromRGB(255, 255, 255), 0.25)
        or state.outlineColor
    for _, entry in pairs(state.objects or {}) do
        if entry.highlight and entry.highlight.Parent then
            entry.highlight.FillColor = fill
            entry.highlight.OutlineColor = outline
        end
    end
end

-- ================================================================
-- SPRAY ESP (ported from SyncsakenOld.lua)
-- Tracks the same Ingame Models whose names contain "Spray".
-- ================================================================
S.isSprayESPEnabled = false
S.SPRAY_ESP_DEFAULT_COLOR = Color3.fromRGB(0, 255, 255)
S.SPRAY_ESP_COLOR = S.SPRAY_ESP_COLOR or S.SPRAY_ESP_DEFAULT_COLOR
S.sprayESPEntries = setmetatable({}, {__mode = "k"})
S.sprayESPContainer = nil
S.sprayESPAddedConnection = nil
S.sprayESPRemovedConnection = nil

S.__helpers.removeSprayESPObject = function(model)
    local entry = S.sprayESPEntries[model]
    if not entry then return end

    if entry.ancestryConnection then
        pcall(function() entry.ancestryConnection:Disconnect() end)
        entry.ancestryConnection = nil
    end
    if entry.highlight then
        pcall(function() entry.highlight:Destroy() end)
        entry.highlight = nil
    end
    if entry.billboard then
        pcall(function() entry.billboard:Destroy() end)
        entry.billboard = nil
    end
    S.sprayESPEntries[model] = nil
end

S.__helpers.addSprayESPObject = function(model)
    if not S.isSprayESPEnabled
        or typeof(model) ~= "Instance"
        or not model:IsA("Model")
        or not string.find(model.Name, "Spray", 1, true)
        or not model:IsDescendantOf(workspace) then
        return
    end

    local existing = S.sprayESPEntries[model]
    if existing and existing.highlight and existing.highlight.Parent
        and existing.billboard and existing.billboard.Parent then
        return
    end
    if existing then
        S.__helpers.removeSprayESPObject(model)
    end

    local basePart = model:FindFirstChildWhichIsA("BasePart", true)
    if not basePart then return end

    -- Match the source Highlight's fill opacity and AlwaysOnTop behavior.
    local highlight = Instance.new("Highlight")
    highlight.Name = "E1LU4HUB_SprayESPHighlight"
    highlight.Adornee = basePart
    highlight.FillColor = S.SPRAY_ESP_COLOR
    highlight.FillTransparency = 0.7
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Parent = basePart

    -- Syncsaken also displays a small "spray" label above each matching Model.
    local billboard = Instance.new("BillboardGui")
    billboard.Name = "E1LU4HUB_SprayESPBillboard"
    billboard.Archivable = false
    billboard.Parent = model
    billboard.Adornee = basePart
    billboard.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    billboard.Active = true
    billboard.MaxDistance = 2000
    billboard.AlwaysOnTop = true
    billboard.Size = UDim2.new(0, 133, 0, 15)
    billboard.StudsOffset = Vector3.new(0, 3, 0)

    local label = Instance.new("TextLabel")
    label.Name = "SprayESPText"
    label.Parent = billboard
    label.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    label.BackgroundTransparency = 1
    label.BorderColor3 = Color3.fromRGB(0, 0, 0)
    label.BorderSizePixel = 0
    label.Size = UDim2.new(1, 0, 1, 0)
    label.Font = Enum.Font.Code
    label.Text = "spray"
    label.TextColor3 = Color3.fromRGB(255, 255, 255)
    label.TextScaled = true
    label.TextSize = 14
    label.TextWrapped = true

    local labelStroke = Instance.new("UIStroke")
    labelStroke.Parent = label
    labelStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual
    labelStroke.Color = Color3.fromRGB(0, 0, 0)
    labelStroke.Thickness = 1.25

    local entry = {
        highlight = highlight,
        billboard = billboard,
        ancestryConnection = nil,
    }
    S.sprayESPEntries[model] = entry
    entry.ancestryConnection = model.AncestryChanged:Connect(function()
        if not model:IsDescendantOf(workspace) then
            S.__helpers.removeSprayESPObject(model)
        end
    end)
end

S.__helpers.updateSprayESPColor = function()
    for model, entry in pairs(S.sprayESPEntries) do
        if not model or not model:IsDescendantOf(workspace) then
            S.__helpers.removeSprayESPObject(model)
        elseif entry.highlight and entry.highlight.Parent then
            entry.highlight.FillColor = S.SPRAY_ESP_COLOR
        end
    end
end

S.__helpers.setSprayESP = function(enabled)
    S.isSprayESPEnabled = enabled == true

    if S.sprayESPAddedConnection then
        pcall(function() S.sprayESPAddedConnection:Disconnect() end)
        S.sprayESPAddedConnection = nil
    end
    if S.sprayESPRemovedConnection then
        pcall(function() S.sprayESPRemovedConnection:Disconnect() end)
        S.sprayESPRemovedConnection = nil
    end

    if not S.isSprayESPEnabled then
        local trackedModels = {}
        for model in pairs(S.sprayESPEntries) do
            table.insert(trackedModels, model)
        end
        for _, model in ipairs(trackedModels) do
            S.__helpers.removeSprayESPObject(model)
        end
        S.sprayESPContainer = nil
        return
    end

    local ingame = S.getIngameFolders()
    if not ingame then
        S.sprayESPContainer = nil
        return
    end
    S.sprayESPContainer = ingame

    -- Initial scan follows the source behavior and includes nested Models.
    for _, descendant in ipairs(ingame:GetDescendants()) do
        S.__helpers.addSprayESPObject(descendant)
    end

    -- New spray Models are normally added directly under Map.Ingame.
    S.sprayESPAddedConnection = ingame.ChildAdded:Connect(function(child)
        task.defer(function()
            if S.isSprayESPEnabled and S.sprayESPContainer == ingame then
                S.__helpers.addSprayESPObject(child)
            end
        end)
    end)
    S.sprayESPRemovedConnection = ingame.ChildRemoved:Connect(function(child)
        if S.sprayESPEntries[child] then
            S.__helpers.removeSprayESPObject(child)
        end
        for _, descendant in ipairs(child:GetDescendants()) do
            if S.sprayESPEntries[descendant] then
                S.__helpers.removeSprayESPObject(descendant)
            end
        end
    end)
end

