-- Initialise the color/config records up front so color pickers also work
-- before their matching ESP toggle has ever been enabled.
for key, config in pairs(S.WORLD_KEYWORD_ESP_CONFIGS) do
    local state = S.worldKeywordESPStates[key] or {}
    state.enabled = state.enabled == true
    state.objects = state.objects or {}
    state.config = config
    state.defaultColor = state.defaultColor or config.fillColor
    state.outlineColor = config.outlineColor
    state.colorOverride = state.colorOverride == true
    S.worldKeywordESPStates[key] = state
end

-- Re-scan occasionally in case the game removes an ESP Highlight without removing
-- its source object; each enabled feature reuses its own deduplicating handler.
task.spawn(function()
    while true do
        task.wait(5)
        local activeStates = {}
        for _, state in pairs(S.worldKeywordESPStates) do
            if state.enabled and type(state.applyObject) == "function" then
                table.insert(activeStates, state)
            end
        end
        if #activeStates > 0 then
            for _, object in ipairs(workspace:GetDescendants()) do
                for _, state in ipairs(activeStates) do
                    pcall(state.applyObject, object)
                end
            end
        end
    end
end)

