-- Jane Doe quest object ESP: identify top-level MeshParts named "Model".
-- The source distinguishes a Folder by its specific child SoundId; all other
-- matching Models are shown as Rings. BillboardGui labels track the objects.
S.__helpers.addFolderRingESPObject = function(object)
    if not S.isFolderRingESPEnabled or not object then return end
    if not object:IsA("MeshPart") or object.Name ~= "Model" then return end

    local current = S.folderRingESPEntries[object]
    if current and current.Parent then return end
    S.folderRingESPEntries[object] = nil

    local isFolder = false
    for _, child in ipairs(object:GetChildren()) do
        if child:IsA("Sound") and child.SoundId == "rbxassetid://9112795583" then
            isFolder = true
            break
        end
    end

    local billboard = Instance.new("BillboardGui")
    billboard.Name = "E1LU4HUB_FolderRingESP"
    billboard.Adornee = object
    billboard.Size = UDim2.new(0, 116, 0, 24)
    billboard.StudsOffset = Vector3.new(0, 2.5, 0)
    billboard.AlwaysOnTop = true
    billboard.LightInfluence = 0
    billboard.MaxDistance = 1500

    local label = Instance.new("TextLabel")
    label.Name = "ObjectLabel"
    label.Size = UDim2.new(1, 0, 1, 0)
    label.BackgroundTransparency = 1
    label.BorderSizePixel = 0
    label.Text = isFolder and "📁 FOLDER" or "💍 RING"
    label.TextColor3 = isFolder and Color3.fromRGB(100, 235, 255) or Color3.fromRGB(255, 225, 125)
    label.TextStrokeColor3 = Color3.new(0, 0, 0)
    label.TextStrokeTransparency = 0.1
    label.Font = Enum.Font.GothamBold
    label.TextSize = 13
    label.TextWrapped = false
    label.Parent = billboard

    local playerGui = S.lp and (S.lp:FindFirstChildOfClass("PlayerGui") or S.lp:FindFirstChild("PlayerGui"))
    billboard.Parent = playerGui or S.CoreGui
    S.folderRingESPEntries[object] = billboard
end

S.__helpers.removeFolderRingESPObject = function(object)
    local billboard = S.folderRingESPEntries[object]
    if billboard then
        pcall(function() billboard:Destroy() end)
        S.folderRingESPEntries[object] = nil
    end
end

S.__helpers.clearFolderRingESP = function()
    for object, billboard in pairs(S.folderRingESPEntries) do
        if billboard then pcall(function() billboard:Destroy() end) end
        S.folderRingESPEntries[object] = nil
    end
end

S.__helpers.setFolderRingESP = function(enabled)
    S.isFolderRingESPEnabled = enabled == true

    if S.folderRingESPAddedConnection then
        S.folderRingESPAddedConnection:Disconnect()
        S.folderRingESPAddedConnection = nil
    end
    if S.folderRingESPRemovedConnection then
        S.folderRingESPRemovedConnection:Disconnect()
        S.folderRingESPRemovedConnection = nil
    end

    if not S.isFolderRingESPEnabled then
        S.__helpers.clearFolderRingESP()
        return
    end

    for _, child in ipairs(workspace:GetChildren()) do
        S.__helpers.addFolderRingESPObject(child)
    end

    S.folderRingESPAddedConnection = S.__helpers.connect(workspace.ChildAdded, function(child)
        task.delay(0.2, function()
            if S.isFolderRingESPEnabled and child and child.Parent == workspace then
                S.__helpers.addFolderRingESPObject(child)
            end
        end)
    end)
    S.folderRingESPRemovedConnection = S.__helpers.connect(workspace.ChildRemoved, function(child)
        S.__helpers.removeFolderRingESPObject(child)
    end)
end

