-- Killer and Survivor Highlight opacity controls are independent.
S.__helpers.createNumericControl(
    "KILLER ESP FILL OPACITY (%)",
    math.floor(S.KILLER_ESP_FILL_TRANSPARENCY * 100 + 0.5),
    0, 100, 1,
    function(value)
        local percent = math.clamp(tonumber(value) or 85, 0, 100)
        local nextValue = percent / 100
        if math.abs(S.KILLER_ESP_FILL_TRANSPARENCY - nextValue) > 0.0001 then
            S.KILLER_ESP_FILL_TRANSPARENCY = nextValue
            S.__helpers.updateAllPlayerESP()
        end
        return percent
    end
)
