S.RoundTimerSettings = {x = 50, y = 0, onlyTime = false, hideStatus = false}
S.__helpers.getRoundTimerMain = function()
    local playerGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
    local roundTimer = playerGui and playerGui:FindFirstChild("RoundTimer")
    local main = roundTimer and roundTimer:FindFirstChild("Main")
    return main
end
S.__helpers.applyRoundTimerSettings = function()
    local main = S.__helpers.getRoundTimerMain()
    if not main or not main:IsA("GuiObject") then return false end
    main.Position = UDim2.new(
        S.RoundTimerSettings.x / 100, main.Position.X.Offset,
        S.RoundTimerSettings.y / 100 - 0.018, main.Position.Y.Offset
    )
    if main:IsA("ImageLabel") or main:IsA("ImageButton") then
        main.ImageTransparency = S.RoundTimerSettings.onlyTime and 1 or 0
    end
    local title = main:FindFirstChild("Title", true)
    if title and title:IsA("TextLabel") then
        title.TextTransparency = (S.RoundTimerSettings.onlyTime and S.RoundTimerSettings.hideStatus) and 1 or 0
    end
    return true
end
