end)
S.__helpers.createCoolToggle("HIDE ROUND TIMER STATUS", false, function(value)
    S.RoundTimerSettings.hideStatus = value == true
    S.__helpers.applyRoundTimerSettings()
end)
do
    local watchedRoundTimer = setmetatable({}, {__mode = "k"})
    local function watchRoundTimerObject(object)
        if not object or watchedRoundTimer[object] then return end
        if object.Name ~= "RoundTimer" and object.Name ~= "Main" then return end
        watchedRoundTimer[object] = true
        task.defer(S.__helpers.applyRoundTimerSettings)
        if object:IsA("GuiObject") then
            S.__helpers.connect(object:GetPropertyChangedSignal("Parent"), function()
                task.defer(S.__helpers.applyRoundTimerSettings)
            end)
        end
    end
    local function bindPlayerGui(playerGui)
        if not playerGui then return end
        for _, object in ipairs(playerGui:GetDescendants()) do watchRoundTimerObject(object) end
        S.__helpers.connect(playerGui.DescendantAdded, function(object)
            watchRoundTimerObject(object)
            task.defer(S.__helpers.applyRoundTimerSettings)
        end)
    end
    local initialGui = S.lp and S.lp:FindFirstChildOfClass("PlayerGui")
    bindPlayerGui(initialGui)
    if S.lp then
        S.__helpers.connect(S.lp.ChildAdded, function(child)
            if child:IsA("PlayerGui") then bindPlayerGui(child) end
        end)
    end
    task.spawn(function()
        for _ = 1, 30 do
            S.__helpers.applyRoundTimerSettings()
            task.wait(0.5)
        end
    end)
end

