S.__helpers.playFakeBlockAnimation = function()
    local character = S.lp and S.lp.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if not animator then
        animator = Instance.new("Animator")
        animator.Parent = humanoid
    end
    local animation = Instance.new("Animation")
    animation.AnimationId = (S.GuestBlockAnimation and S.GuestBlockAnimation.selectedId)
        or "rbxassetid://72722244508749"
    local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
    if ok and track then
        track:Play()
        task.delay(3, function() pcall(function() animation:Destroy() end) end)
    else
        animation:Destroy()
    end
end

