    if gameProcessed or not S.fakeBlockEnabled then return end
    if S.fakeBlockKeyContainer and S.fakeBlockKeyContainer:GetAttribute("Listening") then return end
    if S.__helpers.inputMatchesConfiguredKey(input, S.fakeBlockKey) then
        S.__helpers.playFakeBlockAnimation()
    end
end)

