S.infBloxyColaSession = nil
S.__helpers.setInfBloxyColaEnabled = function(enabled)
    if enabled then
        if S.infBloxyColaSession then return true end
        if type(getgenv) == "function" then
            local env = getgenv()
            env.infBloxySettings = env.infBloxySettings or {cooldownDuration = 3}
        end

        local function createSession()
            local Players = game:GetService("Players")
            local ReplicatedStorage = game:GetService("ReplicatedStorage")
            local RunService = game:GetService("RunService")
            local localPlayer = Players.LocalPlayer
            local animationId = "rbxassetid://102123566838185"
            local statuses = ReplicatedStorage.Modules.Gameplay.Statuses
            local statusContainer = statuses.StatusContainer
            local statusDisplay = statuses.StatusDisplay
            local speedModule = ReplicatedStorage.Modules.Schematics.StatusEffects:FindFirstChild("Speed")

            local humanoid = nil
            local characterAddedConnection = nil
            local heartbeatConnection = nil
            local cameraHeartbeatConnection = nil
            local activeSpeedBillboard = nil
            local activeTrack = nil
            local speedEffectData = nil
            local activeStartedAt = nil
            local fieldOfView = nil
            local currentCamera = workspace.CurrentCamera
            local savedSpeedEffect = nil
            local previousNewIndex = nil
            local newIndexHookInstalled = false
            local warningShown = false
            local transitionBusy = false
            local sessionAlive = true
            local isActive = false
            local isWaitingForTrackEnd = false

            local function formatTimer(seconds)
                local minutes = math.floor(seconds / 60)
                local remaining = math.floor(seconds % 60)
                return string.format("%02d:%02d", minutes, remaining)
            end

            local function installNewIndexGuard()
                if newIndexHookInstalled or type(hookmetamethod) ~= "function" then return end
                newIndexHookInstalled = true
                local ok, original = pcall(function()
                    return hookmetamethod(game, "__newindex", function(object, property, value)
                        return previousNewIndex(object, property, value)
                    end)
                end)
                if ok then
                    previousNewIndex = original
                else
                    newIndexHookInstalled = false
                end
            end

            local function restoreNewIndexGuard()
                if previousNewIndex and type(hookmetamethod) == "function" then
                    pcall(function() hookmetamethod(game, "__newindex", previousNewIndex) end)
                    previousNewIndex = nil
                    newIndexHookInstalled = false
                end
            end

            local function captureFieldOfView()
                if currentCamera and not fieldOfView then
                    fieldOfView = currentCamera.FieldOfView
                end
            end

            local function restoreFieldOfView()
                if currentCamera and fieldOfView and currentCamera.FieldOfView ~= fieldOfView then
                    currentCamera.FieldOfView = fieldOfView
                end
            end

            local function applySpeedEffect(level)
                if not speedModule then return end
                local ok, module = pcall(require, speedModule)
                if not ok or type(module) ~= "table" then return end
                if savedSpeedEffect then
                    pcall(function() module.Removed(savedSpeedEffect) end)
                end
                savedSpeedEffect = {Player = localPlayer, Level = level, Data = module.Data}
                pcall(function() module.Applied(savedSpeedEffect) end)
            end

            local function removeSpeedEffect()
                if not speedModule then return end
                local ok, module = pcall(require, speedModule)
                if not ok or type(module) ~= "table" then return end
                if savedSpeedEffect then
                    pcall(function() module.Removed(savedSpeedEffect) end)
                    savedSpeedEffect = nil
                end
                if fieldOfView and currentCamera then
                    task.delay(1, function()
                        if currentCamera then currentCamera.FieldOfView = fieldOfView end
                    end)
                end
            end

            local function showStatus(name, duration)
                local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
                local mainUI = playerGui and playerGui:FindFirstChild("MainUI")
                if not mainUI then return nil end
                local statusContainerClone = mainUI:FindFirstChild("StatusContainer") or statusContainer:Clone()
                statusContainerClone.Parent = mainUI
                local oldStatus = statusContainerClone:FindFirstChild(name)
                if oldStatus then oldStatus:Destroy() end

                local clone = statusDisplay:Clone()
                clone.Name = name
                clone.Title.Text = name
                clone.Timer.Text = formatTimer(duration)
                clone.Visible = true
                clone.Parent = statusContainerClone
                local expiresAt = tick() + duration
                local timerConnection
                timerConnection = RunService.Heartbeat:Connect(function()
                    if not clone or not clone.Parent then
                        timerConnection:Disconnect()
                        return
                    end
                    local remaining = math.max(0, expiresAt - tick())
                    clone.Timer.Text = formatTimer(remaining)
                    if remaining <= 0 then
                        clone:Destroy()
                        timerConnection:Disconnect()
                    end
                end)
                return clone
            end

            local function useBloxyCola()
                local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
                local mainUI = playerGui and playerGui:FindFirstChild("MainUI")
                local backpack = mainUI and mainUI:FindFirstChild("Backpack")
                local colaButton = backpack and backpack:FindFirstChild("BloxyCola")
                if not colaButton or type(getconnections) ~= "function" then return end
                local ok, connections = pcall(getconnections, colaButton.MouseButton1Click)
                if not ok or type(connections) ~= "table" then return end
                for _, connection in ipairs(connections) do
                    if connection and typeof(connection.Function) == "function" then
                        pcall(connection.Function)
                        break
                    end
                end
            end

            local function stopSpeedSequence()
                if cameraHeartbeatConnection then
                    cameraHeartbeatConnection:Disconnect()
                    cameraHeartbeatConnection = nil
                end
                if activeSpeedBillboard and activeSpeedBillboard.Parent then
                    activeSpeedBillboard:Destroy()
                end
                activeSpeedBillboard = nil
                isActive = false
                isWaitingForTrackEnd = false
                activeTrack = nil
                transitionBusy = false
                restoreNewIndexGuard()
            end

            local function beginSpeedSequence()
                if cameraHeartbeatConnection then
                    cameraHeartbeatConnection:Disconnect()
                    cameraHeartbeatConnection = nil
                end
                local duration = 10
                activeStartedAt = tick()
                transitionBusy = false
                captureFieldOfView()
                installNewIndexGuard()
                local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:FindFirstChild("PlayerGui")
                local mainUI = playerGui and playerGui:FindFirstChild("MainUI")
                if not mainUI then
                    stopSpeedSequence()
                    return
                end
                local statusContainerClone = mainUI:FindFirstChild("StatusContainer") or statusContainer:Clone()
                statusContainerClone.Parent = mainUI
                local oldSpeed = statusContainerClone:FindFirstChild("Speed")
                if oldSpeed then oldSpeed:Destroy() end
                local clone = statusDisplay:Clone()
                clone.Name = "Speed"
                clone.Title.Text = "Speed II"
                clone.Timer.Text = formatTimer(duration)
                clone.Visible = true
                clone.Parent = statusContainerClone
                activeSpeedBillboard = clone
                applySpeedEffect(2)
                local lastLevel = 2

                cameraHeartbeatConnection = RunService.Heartbeat:Connect(function()
                    local elapsed = tick() - activeStartedAt
                    local remaining = math.max(0, duration - elapsed)
                    if activeSpeedBillboard and activeSpeedBillboard.Parent then
                        activeSpeedBillboard.Timer.Text = formatTimer(remaining)
                    end
                    restoreFieldOfView()
                    if remaining <= 0 then
                        removeSpeedEffect()
                        stopSpeedSequence()
                        return
                    end
                    if elapsed < 5 then
                        if lastLevel ~= 2 then applySpeedEffect(2); lastLevel = 2 end
                    elseif elapsed < 6.5 then
                        if lastLevel ~= 1 then applySpeedEffect(1); lastLevel = 1 end
                    elseif elapsed < 9 then
                        if lastLevel ~= 2 then applySpeedEffect(2); lastLevel = 2 end
                    elseif not transitionBusy then
                        transitionBusy = true
                        lastLevel = nil
                        removeSpeedEffect()
                    end
                end)
            end

            local function inspectBloxyAnimation()
                if not sessionAlive or not humanoid or not humanoid.Parent then return end
                for _, track in pairs(humanoid:GetPlayingAnimationTracks()) do
                    if track.Animation and track.Animation.AnimationId == animationId then
                        if track == activeTrack then return end
                        activeTrack = track
                        if isActive or isWaitingForTrackEnd then
                            if not warningShown then
                                warningShown = true
                                showStatus("Dude DON'T do this..", 1)
                                task.delay(1, function()
                                    if not sessionAlive then return end
                                    showStatus("People may notice u 😡 Follow the tutorial", 3)
                                    useBloxyCola()
                                    warningShown = false
                                end)
                            end
                            return
                        end

                        isWaitingForTrackEnd = true
                        local waitLabel = showStatus("Wait!", 3.4)
                        local stoppedConnection
                        stoppedConnection = track.Stopped:Connect(function()
                            if not sessionAlive then return end
                            if waitLabel and waitLabel.Parent then waitLabel:Destroy() end
                            stopSpeedSequence()
                            if stoppedConnection then stoppedConnection:Disconnect() end
                        end)
                        task.delay(3.4, function()
                            if not sessionAlive then return end
                            if not track.IsPlaying then
                                if waitLabel and waitLabel.Parent then waitLabel:Destroy() end
                                stopSpeedSequence()
                                if stoppedConnection then stoppedConnection:Disconnect() end
                                return
                            end
                            if waitLabel and waitLabel.Parent then waitLabel:Destroy() end
                            if stoppedConnection then stoppedConnection:Disconnect() end
                            useBloxyCola()
                            warningShown = false
                            isActive = true
                            isWaitingForTrackEnd = false
                            beginSpeedSequence()
                        end)
                    end
                end
            end

            local function bindCharacter(character)
                if not sessionAlive then return end
                humanoid = character:WaitForChild("Humanoid")
                stopSpeedSequence()
                if heartbeatConnection then heartbeatConnection:Disconnect() end
                pcall(inspectBloxyAnimation)
                if cameraHeartbeatConnection then cameraHeartbeatConnection:Disconnect() end
                cameraHeartbeatConnection = RunService.Heartbeat:Connect(function()
                    if isActive then restoreFieldOfView() end
                end)
                task.delay(1.5, function()
                    if not sessionAlive or heartbeatConnection then return end
                    heartbeatConnection = RunService.Heartbeat:Connect(function()
                        if not sessionAlive then return end
                        if humanoid and humanoid.Parent then
                            inspectBloxyAnimation()
                        else
                            stopSpeedSequence()
                        end
                    end)
                end)
            end

            if localPlayer.Character then
                bindCharacter(localPlayer.Character)
            end
            characterAddedConnection = localPlayer.CharacterAdded:Connect(bindCharacter)

            return {
                Disconnect = function()
                    sessionAlive = false
                    if heartbeatConnection then heartbeatConnection:Disconnect(); heartbeatConnection = nil end
                    if characterAddedConnection then characterAddedConnection:Disconnect(); characterAddedConnection = nil end
                    if cameraHeartbeatConnection then cameraHeartbeatConnection:Disconnect(); cameraHeartbeatConnection = nil end
                    removeSpeedEffect()
                    stopSpeedSequence()
                end,
            }
        end

        local ok, session = pcall(createSession)
        if not ok then
            warn("[E1LU4HUB] Inf Bloxy Cola setup failed: " .. tostring(session))
            return false
        end
        S.infBloxyColaSession = session
        return true
    end

    local session = S.infBloxyColaSession
    S.infBloxyColaSession = nil
    if session and type(session.Disconnect) == "function" then
        pcall(function() session:Disconnect() end)
    end
    return true
end

