S.__helpers.selectHitboxExpanderTarget = function(root)
    local state = S.HitboxExpander
    local playersFolder = workspace:FindFirstChild("Players")
    local isKiller = S.__helpers.isLocalRole("Killer")
    local targetFolder = playersFolder and playersFolder:FindFirstChild(isKiller and "Survivors" or "Killers")
    if not targetFolder then return nil end
    local best, bestScore = nil, math.huge
    local look = root.CFrame.LookVector
    for _, model in ipairs(targetFolder:GetChildren()) do
        if model:IsA("Model") then
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            local targetRoot = model:FindFirstChild("HumanoidRootPart")
            if humanoid and humanoid.Health > 0 and targetRoot then
                local delta = targetRoot.Position - root.Position
                local distance = delta.Magnitude
                if distance > 0 and distance <= state.range then
                    local score
                    if state.targetMode == "Nearest" then
                        score = distance
                    elseif state.targetMode == "Lowest HP" then
                        score = humanoid.Health
                    else
                        score = -look:Dot(delta.Unit)
                    end
                    if score < bestScore then best, bestScore = model, score end
                end
            end
        end
    end
    return best
end
S.__helpers.runHitboxExpanderTrack = function(character, track)
    local state = S.HitboxExpander
    if not state.enabled or not character or not track or not track.Animation then return end
    if not (S.__helpers.isLocalRole("Killer") or character.Name == "Shedletsky") then return end
    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then return end

    -- Resolve the attack and its windup from the live character/skin config,
    -- matching E1LU4SAKEN's GeneralAttacks + AttackIdToWindup lookup.
    local animationConfig = S.__helpers.getLocalAnimationConfig and S.__helpers.getLocalAnimationConfig(character)
    if type(animationConfig) ~= "table" then return end
    local animationId = tostring(track.Animation.AnimationId or "")
    local windup
    local attackMap = state.attackMeta[character.Name]
    if not attackMap then return end
    for animationPath, attackWindup in pairs(attackMap) do
        local id = S.__helpers.getAnimationAtPath and S.__helpers.getAnimationAtPath(animationConfig, animationPath)
        if id and tostring(id) == animationId then
            windup = attackWindup
            break
        end
    end
    if not windup then return end

    local originalCFrame = root.CFrame
    local startTime = os.clock()
    local hitWindow = 0.36
    local maxDuration = tonumber(track.Length) or (windup + hitWindow)
    maxDuration = math.max(maxDuration, windup + hitWindow)
    local hitboxDepth = tonumber(state.hitboxDepth[character.Name]) or 7.5
    local hitboxOffset = tonumber(state.hitboxOffset[character.Name]) or 2.25
    task.spawn(function()
        while state.enabled and track.IsPlaying and root.Parent and character == (S.lp and S.lp.Character)
            and os.clock() - startTime <= maxDuration do
            local elapsed = os.clock() - startTime
            if elapsed >= windup and elapsed <= windup + hitWindow then
                local alreadyRegistered = false
                pcall(function()
                    local multipliers = character:FindFirstChild("FOVMultipliers")
                    alreadyRegistered = multipliers and multipliers:FindFirstChild("HitRegistered") ~= nil
                end)
                if not alreadyRegistered then
                    if state.expandMode == "Static" then
                        local progress = math.clamp((elapsed - windup) / hitWindow, 0, 1)
                        pcall(function()
                            root.CFrame = originalCFrame + originalCFrame.LookVector * (state.range * progress)
                        end)
                    else
                        local target
                        if S.__helpers.isLocalRole("Killer") then
                            target = S.__helpers.selectHitboxExpanderTarget(root)
                        else
                            local playersFolder = workspace:FindFirstChild("Players")
                            local killersFolder = playersFolder and playersFolder:FindFirstChild("Killers")
                            if killersFolder then
                                for _, model in ipairs(killersFolder:GetChildren()) do
                                    if model:GetAttribute("Username") ~= nil and model:FindFirstChild("HumanoidRootPart") then
                                        target = model
                                        break
                                    end
                                end
                            end
                        end
                        local query = target and (target:FindFirstChild("QueryHitbox") or target:FindFirstChild("HumanoidRootPart"))
                        local targetHumanoid = target and target:FindFirstChildOfClass("Humanoid")
                        if query and targetHumanoid then
                            local base = state.autoRotate and query.CFrame or (CFrame.new(query.Position) * originalCFrame.Rotation)
                            local velocity = Vector3.zero
                            pcall(function() velocity = targetHumanoid:GetMoveVelocity() / 3.5 end)
                            local destination = base + velocity - base.LookVector * (hitboxOffset / 2)
                            pcall(function() root.CFrame = destination end)
                        end
                    end
                end
            end
            S.RunService.Heartbeat:Wait()
        end
        if root and root.Parent and character == (S.lp and S.lp.Character) then
            pcall(function() root.CFrame = originalCFrame end)
        end
    end)
end
S.__helpers.bindHitboxExpanderCharacter = function(character)
    local state = S.HitboxExpander
    if state.connection then pcall(function() state.connection:Disconnect() end); state.connection = nil end
    if not state.enabled or not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
    local animator = humanoid and (humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 5))
    if not animator then return end
    state.connection = S.__helpers.connect(animator.AnimationPlayed, function(track)
        S.__helpers.runHitboxExpanderTrack(character, track)
    end)
end
S.__helpers.setHitboxExpanderEnabled = function(enabled)
    local state = S.HitboxExpander
    state.enabled = enabled == true
    if state.connection then pcall(function() state.connection:Disconnect() end); state.connection = nil end
    if state.characterConnection then pcall(function() state.characterConnection:Disconnect() end); state.characterConnection = nil end
    if not state.enabled then return true end
    state.characterConnection = S.__helpers.connect(S.lp.CharacterAdded, function(character)
        task.defer(S.__helpers.bindHitboxExpanderCharacter, character)
    end)
    if S.lp and S.lp.Character then task.defer(S.__helpers.bindHitboxExpanderCharacter, S.lp.Character) end
    return true
end
S.__helpers.setHitboxExpanderRange = function(value)
    local number = tonumber(value)
    if not number then return false end
    S.HitboxExpander.range = math.clamp(number, 8, 200)
    return true
end

S.__helpers.createSectionHeader("HITBOX EXPANDER")
S.__helpers.createCoolToggle("ENABLE HITBOX EXPANDER", false, function(value)
    S.__helpers.setHitboxExpanderEnabled(value)
end)
S.__helpers.createNumericControl("RANGE", 15, 8, 200, 1, function(value)
    S.__helpers.setHitboxExpanderRange(value)
end)
S.PlopSpoofer.createDropdown("TARGET", function()
