end, "Facing", function(value)
    S.HitboxExpander.targetMode = value
end)
S.PlopSpoofer.createDropdown("EXPAND MODE", function()
    return {"Dynamic", "Static"}
end, "Dynamic", function(value)
    S.HitboxExpander.expandMode = value
end)
S.__helpers.createCoolToggle("(DYNAMIC) AUTO ROTATE", true, function(value)
    S.HitboxExpander.autoRotate = value == true
end)
S.__helpers.createFunInfoLabel("Dynamic: follows the selected target during the hit window. Static: extends the hitbox forward. High range is more obvious.", 44)

