-- INVISIBILITY: hold the game's invisibility animation at its hidden pose.
S.__helpers.createSectionHeader("INVISIBILITY")
S.invisibilityEnabled = false
S.invisibilityTrack = nil
S.invisibilityAnimationId = "75804462760596"
S.__helpers.setupInvisibilityCharacter = function(character)
    local humanoid = character and (character:FindFirstChildOfClass("Humanoid")
        or character:WaitForChild("Humanoid", 5))
    if not humanoid then return end
    local animator = humanoid:FindFirstChildOfClass("Animator")
        or humanoid:WaitForChild("Animator", 5)
    if not animator then return end

    if S.invisibilityTrack then
        pcall(function() S.invisibilityTrack:Stop() end)
        pcall(function() S.invisibilityTrack:Destroy() end)
        S.invisibilityTrack = nil
    end

    local animation = Instance.new("Animation")
    animation.AnimationId = "rbxassetid://" .. S.invisibilityAnimationId
    local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
    animation:Destroy()
    if not ok or not track then return end

    S.invisibilityTrack = track
    if S.invisibilityEnabled then
        pcall(function()
            track:Play()
            task.wait(0.00025)
            track:AdjustSpeed(0)
        end)
    end
end

if S.lp then
    S.__helpers.connect(S.lp.CharacterAdded, function(character)
