    end
end)

-- NOCLIP: disable character-part collision while enabled, then restore snapshots.
S.__helpers.createSectionHeader("NOCLIP")
S.noclipEnabled = false
S.noclipConnection = nil
S.noclipCharacterConnection = nil
S.noclipRespawnConnection = nil
S.noclipOriginal = {}
S.noclipParts = {}

S.__helpers.restoreNoclip = function()
    for part, original in pairs(S.noclipOriginal) do
        if part and part.Parent then
            pcall(function() part.CanCollide = original end)
        end
    end
    table.clear(S.noclipOriginal)
    table.clear(S.noclipParts)
    if S.noclipCharacterConnection then
        pcall(function() S.noclipCharacterConnection:Disconnect() end)
        S.noclipCharacterConnection = nil
    end
    if S.noclipRespawnConnection then
        pcall(function() S.noclipRespawnConnection:Disconnect() end)
        S.noclipRespawnConnection = nil
    end
end

S.__helpers.addNoclipPart = function(part)
    if not part or not part:IsA("BasePart") then return end
    if S.noclipOriginal[part] == nil then
        S.noclipOriginal[part] = part.CanCollide
    end
    S.noclipParts[part] = true
    pcall(function() part.CanCollide = false end)
end

S.__helpers.attachNoclipCharacter = function(character)
    if not S.noclipEnabled or not character then return end
    if S.noclipCharacterConnection then
        pcall(function() S.noclipCharacterConnection:Disconnect() end)
        S.noclipCharacterConnection = nil
    end

    for part, original in pairs(S.noclipOriginal) do
        local belongsToCurrent = false
        pcall(function() belongsToCurrent = part and part:IsDescendantOf(character) end)
        if not belongsToCurrent then
            if part and part.Parent then pcall(function() part.CanCollide = original end) end
            S.noclipOriginal[part] = nil
            S.noclipParts[part] = nil
        end
    end

    for _, part in ipairs(character:GetDescendants()) do
        S.__helpers.addNoclipPart(part)
    end
    S.noclipCharacterConnection = S.__helpers.connect(
        character.DescendantAdded,
        S.__helpers.addNoclipPart
    )
end

S.__helpers.setNoclip = function(enabled)
    S.noclipEnabled = enabled == true
    if S.__helpers.refreshKeybindList then S.__helpers.refreshKeybindList() end
    if S.noclipConnection then
        pcall(function() S.noclipConnection:Disconnect() end)
        S.noclipConnection = nil
    end
    S.__helpers.restoreNoclip()
    if not S.noclipEnabled then return end

    S.__helpers.attachNoclipCharacter(S.lp and S.lp.Character)
    if S.lp then
        S.noclipRespawnConnection = S.__helpers.connect(S.lp.CharacterAdded, function(character)
            if S.noclipEnabled then S.__helpers.attachNoclipCharacter(character) end
        end)
    end
    S.noclipConnection = S.RunService.Stepped:Connect(function()
        if not S.noclipEnabled then return end
        for part in pairs(S.noclipParts) do
            if part and part.Parent then
                pcall(function() part.CanCollide = false end)
            else
                S.noclipParts[part] = nil
            end
        end
    end)
end

S.__helpers.createCoolToggle("NOCLIP", false, function(value)
    -- createCoolToggle already emits one categorized ON/OFF notification.
    -- Keep this callback limited to applying the feature state to avoid duplicates.
    S.__helpers.setNoclip(value)
end)

-- ENABLE JUMP: temporarily raises JumpPower and restores the original value.
S.__helpers.createSectionHeader("ENABLE JUMP")
S.enableJumpingEnabled = false
S.enableJumpingConnection = nil
S.enableJumpingHumanoid = nil
S.enableJumpingOriginalPower = nil
S.enableJumpingCooldown = false

S.__helpers.stopEnableJumpingForHumanoid = function(restorePower)
    if S.enableJumpingConnection then
        pcall(function() S.enableJumpingConnection:Disconnect() end)
        S.enableJumpingConnection = nil
    end
    local humanoid = S.enableJumpingHumanoid
    if restorePower and humanoid and humanoid.Parent then
        pcall(function() humanoid.JumpPower = S.enableJumpingOriginalPower or 0 end)
    end
    S.enableJumpingHumanoid = nil
    S.enableJumpingOriginalPower = nil
    S.enableJumpingCooldown = false
end

S.__helpers.bindEnableJumpingCharacter = function(character)
    S.__helpers.stopEnableJumpingForHumanoid(true)
    if not S.enableJumpingEnabled or not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
        or character:WaitForChild("Humanoid", 5)
    if not humanoid then return end

    S.enableJumpingHumanoid = humanoid
    S.enableJumpingOriginalPower = humanoid.JumpPower
    humanoid.JumpPower = 47
    S.enableJumpingConnection = humanoid.StateChanged:Connect(function(_, newState)
        if not S.enableJumpingEnabled or S.enableJumpingHumanoid ~= humanoid then return end
        if humanoid.FloorMaterial == Enum.Material.Air then return end
        if newState ~= Enum.HumanoidStateType.Jumping
            and newState ~= Enum.HumanoidStateType.Freefall then return end
        if S.enableJumpingCooldown then return end

        S.enableJumpingCooldown = true
        task.spawn(function()
            pcall(function()
                humanoid:GetPropertyChangedSignal("FloorMaterial"):Wait()
                if not S.enableJumpingEnabled or S.enableJumpingHumanoid ~= humanoid
                    or not humanoid.Parent then return end
                if humanoid.FloorMaterial ~= Enum.Material.Air then return end
                humanoid.JumpPower = 0
                task.wait(1.25)
                if S.enableJumpingEnabled and S.enableJumpingHumanoid == humanoid
                    and humanoid.Parent then
                    humanoid.JumpPower = 47
                end
            end)
            S.enableJumpingCooldown = false
        end)
    end)
end

S.__helpers.setEnableJumping = function(enabled)
    S.enableJumpingEnabled = enabled == true
    S.__helpers.stopEnableJumpingForHumanoid(true)
    if S.enableJumpingEnabled then
        S.__helpers.bindEnableJumpingCharacter(S.lp and S.lp.Character)
    end
end

S.__helpers.createCoolToggle("EnableJump", false, function(value)
    S.__helpers.setEnableJumping(value)
end)
if S.lp then
    S.__helpers.connect(S.lp.CharacterAdded, function(character)
        if S.enableJumpingEnabled then
            task.delay(0.25, function()
                if S.enableJumpingEnabled then
                    S.__helpers.bindEnableJumpingCharacter(character)
                end
            end)
        end
    end)
end

-- FRONT FLIP + MASTERBAIT: front flip is key/button triggered; Masterbait loops while ON.
-- This intentionally includes only the two emotes requested for the Misc page.
do
    S.FunEmotes = {}
    S.funEmoteButtonOrder = {}
    S.funEmoteMotionBusy = false

    local emoteDefinitions = {
        {id = "FrontFlip", label = "FRONT FLIP", key = "O", kind = "flip", backwards = false},
        {id = "Masterbait", label = "MASTERBAIT", kind = "animation", animationId = "rbxassetid://72042024", looped = true, toggleOnly = true},
    }

    local function getCharacterParts()
        local character = S.lp and S.lp.Character
        if not character then return nil end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or humanoid.Health <= 0 then return nil end
        local animator = humanoid:FindFirstChildOfClass("Animator")
        if not animator then
            animator = Instance.new("Animator")
            animator.Parent = humanoid
        end
        return character, humanoid, root, animator
    end

    local function stopEmoteTrack(state, fadeTime)
        local track = state.track
        state.track = nil
        if track then pcall(function() track:Stop(fadeTime or 0.08) end) end
        local animation = state.animation
        state.animation = nil
        if animation then
            task.delay(0.2, function() pcall(function() animation:Destroy() end) end)
        end
    end
    S.__helpers.stopFunEmoteTrack = stopEmoteTrack

    local function createTrack(state, animator)
        local animation = Instance.new("Animation")
        animation.AnimationId = state.definition.animationId
        local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
        if not ok or not track then
            animation:Destroy()
            return nil
        end
        state.animation = animation
        state.track = track
        track.Looped = state.definition.looped == true
        pcall(function() track.Priority = Enum.AnimationPriority.Action end)
        track.Stopped:Connect(function()
            if state.track == track then
                state.track = nil
                state.animation = nil
            end
            pcall(function() animation:Destroy() end)
        end)
        return track
    end

    local function startLoopingAnimation(state)
        if not state or not state.enabled or not state.definition.toggleOnly then return end
        if state.track then
            local isPlaying = false
            pcall(function() isPlaying = state.track.IsPlaying end)
            if isPlaying then return end
            stopEmoteTrack(state, 0)
        end
        local _, _, _, animator = getCharacterParts()
        if not animator then return end
        local track = createTrack(state, animator)
        if not track then return end
        track.Looped = true
        local ok = pcall(function() track:Play(0.08) end)
        if not ok then stopEmoteTrack(state, 0) end
    end

    local function performFlip(state)
        if S.funEmoteMotionBusy then return end
        local character, humanoid, root = getCharacterParts()
        if not character or not humanoid or not root then return end
        S.funEmoteMotionBusy = true

        task.spawn(function()
            local stateTypes = {
                Enum.HumanoidStateType.FallingDown,
                Enum.HumanoidStateType.Freefall,
                Enum.HumanoidStateType.Running,
                Enum.HumanoidStateType.Seated,
                Enum.HumanoidStateType.Climbing,
            }
            local previousStates = {}
            for _, humanoidState in ipairs(stateTypes) do
                local ok, enabled = pcall(function() return humanoid:GetStateEnabled(humanoidState) end)
                previousStates[humanoidState] = ok and enabled or false
            end

            local startCFrame = root.CFrame
            local startPosition = startCFrame.Position
            local direction = state.definition.backwards and -startCFrame.LookVector or startCFrame.LookVector
            local duration, steps, distance = 0.45, 120, 35
            local startedAt = os.clock()
            local ok, err = pcall(function()
                humanoid:ChangeState(Enum.HumanoidStateType.Physics)
                for _, humanoidState in ipairs(stateTypes) do
                    humanoid:SetStateEnabled(humanoidState, false)
                end
                for i = 1, steps do
                    if not character.Parent or not humanoid.Parent or not root.Parent or humanoid.Health <= 0 then
                        break
                    end
                    local progress = i / steps
                    local arcHeight = 4 * (progress - progress * progress) * 10
                    local position = startPosition + direction * (distance * progress)
                        + Vector3.new(0, arcHeight, 0)
                    local rotation = startCFrame.Rotation
                        * CFrame.Angles(-math.rad(i * (360 / steps)), 0, 0)
                    root.CFrame = CFrame.new(position) * rotation
                    local remaining = duration * progress - (os.clock() - startedAt)
                    if remaining > 0 then task.wait(math.min(remaining, duration / steps)) end
                end
                if root.Parent and character.Parent then
                    root.CFrame = CFrame.new(startPosition + direction * distance) * startCFrame.Rotation
                end
            end)

            for _, humanoidState in ipairs(stateTypes) do
                pcall(function() humanoid:SetStateEnabled(humanoidState, previousStates[humanoidState]) end)
            end
            if humanoid.Parent and humanoid.Health > 0 then
                pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Running) end)
            end
            if not ok then warn("[Fun Emote] Front flip failed: " .. tostring(err)) end
            S.funEmoteMotionBusy = false
        end)
    end

    local function triggerEmote(state)
        if not state.enabled or state.definition.toggleOnly then return end
        if state.definition.kind == "flip" then performFlip(state) end
    end

    local function refreshEmoteButtons()
        local visibleIndex = 0
        for _, state in ipairs(S.funEmoteButtonOrder) do
            local shouldShow = not state.definition.toggleOnly
                and state.enabled and state.buttonEnabled and state.screenButton ~= nil
            if state.screenButton then state.screenButton.Visible = shouldShow end
            if shouldShow then
                visibleIndex += 1
                state.screenButton.Position = UDim2.new(1, -18, 0, 222 + (visibleIndex - 1) * 47)
            end
        end
    end

    for _, definition in ipairs(emoteDefinitions) do
        if definition.id == "FrontFlip" then
            S.__helpers.createSectionHeader("FUN ANIMATIONS")
        elseif definition.id == "Masterbait" then
            S.__helpers.createSectionHeader("MASTERBAIT")
        end

        local state = {
            definition = definition,
            enabled = false,
            key = definition.key,
            buttonEnabled = false,
            track = nil,
            animation = nil,
            screenButton = nil,
            keyContainer = nil,
            buttonToggleContainer = nil,
        }
        S.FunEmotes[definition.id] = state
        table.insert(S.funEmoteButtonOrder, state)

        state.toggleButton = select(1, S.__helpers.createCoolToggle(definition.label, false, function(value)
            state.enabled = value == true
            if state.definition.toggleOnly then
                if state.enabled then
                    startLoopingAnimation(state)
                else
                    stopEmoteTrack(state, 0.1)
                end
            else
                if state.keyContainer then state.keyContainer.Visible = true end
                if state.buttonToggleContainer then state.buttonToggleContainer.Visible = true end
            end
            refreshEmoteButtons()
            if S.__helpers.refreshKeybindList then S.__helpers.refreshKeybindList() end
        end))

        if not definition.toggleOnly then
            state.buttonToggleContainer = select(1, S.__helpers.createCoolToggle(
                definition.label .. " Button",
                false,
                function(value)
                    state.buttonEnabled = value == true
                    refreshEmoteButtons()
                end
            ))
            state.buttonToggleContainer.Visible = true
            state.keyContainer = select(1, S.__helpers.createKeybind(
                definition.label .. " Key",
                definition.key,
                function(value)
                    state.key = S.__helpers.normalizeKeyName(value) or definition.key
                    if S.__helpers.refreshKeybindList then S.__helpers.refreshKeybindList() end
                end
            ))
            state.keyContainer.Visible = true

            local screenButton = Instance.new("TextButton")
            screenButton.Name = "FunEmoteButton_" .. definition.id
            screenButton.Size = UDim2.new(0, 130, 0, 42)
            screenButton.AnchorPoint = Vector2.new(1, 0)
            screenButton.Position = UDim2.new(1, -18, 0, 222)
            screenButton.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
            screenButton.BorderSizePixel = 0
            screenButton.Text = "Front Flip"
            screenButton.TextColor3 = Color3.new(1, 1, 1)
            screenButton.TextSize = 14
            screenButton.Font = Enum.Font.GothamBold
            screenButton.Visible = false
            screenButton.ZIndex = 100
            screenButton.Parent = S.screenGui
            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0, 8)
            corner.Parent = screenButton
            state.screenButton = screenButton
            S.__helpers.connect(screenButton.Activated, function() triggerEmote(state) end)
        end
    end

    S.__helpers.connect(S.UserInputService.InputBegan, function(input, gameProcessed)
        if gameProcessed then return end
        for _, state in ipairs(S.funEmoteButtonOrder) do
            if not state.definition.toggleOnly and state.enabled
                and not (state.keyContainer and state.keyContainer:GetAttribute("Listening"))
                and S.__helpers.inputMatchesConfiguredKey(input, state.key) then
                triggerEmote(state)
            end
        end
    end)

    if S.lp then
        S.__helpers.connect(S.lp.CharacterAdded, function(character)
            for _, state in ipairs(S.funEmoteButtonOrder) do stopEmoteTrack(state, 0) end
            S.funEmoteMotionBusy = false
            task.spawn(function()
                if character then character:WaitForChild("Humanoid", 8) end
                for _, state in ipairs(S.funEmoteButtonOrder) do
                    if state.definition.toggleOnly and state.enabled then
                        startLoopingAnimation(state)
                    end
                end
            end)
        end)
    end
end

-- ================================================================
-- v7: LMS and active Music caches are consolidated under E1LU4HUB.
-- LMS THEME CHANGER (URL DOWNLOADS + E1LU4HUB CACHE)
-- ================================================================
do
    local HttpService = game:GetService("HttpService")
    local LMS_ROOT = "E1LU4HUB"
    local LMS_FOLDER = LMS_ROOT .. "/LMS"
    -- The active Music cache is also part of the local LMS selection library.
    -- Keep it under E1LU4HUB and scan it so those tracks remain visible in the UI.
    local LMS_MUSIC_FOLDER = LMS_ROOT .. "/Music"
    local LMS_DOWNLOAD_FLAG = LMS_ROOT .. "/LMS_DOWNLOAD_TOGGLE"
    local LMS_INDEX_URL = "https://api.github.com/repos/aibabylaugh/catsaken/contents/lms"
    local LMS_AUDIO_EXTENSIONS = {mp3 = true, ogg = true, wav = true}
    local state = {
        selected = "None",
        customId = "",
        customFile = "",
        enabled = false,
        downloadsDisabled = false,
        names = {"None", "Custom"},
        data = {},
        files = {},
        currentSound = nil,
        loading = false,
        refreshToken = 0,
        dropdown = nil,
        downloaded = 0,
        cached = 0,
        failed = 0,
    }
    S.LMSChanger = state

    local function isFile(path)
        if type(isfile) ~= "function" then return false end
        local ok, result = pcall(isfile, path)
        return ok and result == true
    end

    local function readFile(path, fallback)
        if not isFile(path) or type(readfile) ~= "function" then return fallback end
        local ok, value = pcall(readfile, path)
        if ok and type(value) == "string" then return value end
        return fallback
    end

    local function ensureFolder()
        if type(makefolder) ~= "function" then return end
        pcall(makefolder, LMS_ROOT)
        pcall(makefolder, LMS_FOLDER)
        pcall(makefolder, LMS_MUSIC_FOLDER)
        -- Move old E1LU4SAKEN/Music tracks into E1LU4HUB/Music before scanning.
        pcall(S.__helpers.migrateLegacyE1LU4SAKENFolder)
    end

    local function isSupportedAudioFile(filename)
        if type(filename) ~= "string" then return false end
        local extension = filename:lower():match("%.([%w]+)$")
        return extension ~= nil and LMS_AUDIO_EXTENSIONS[extension] == true
    end

    local function writeFile(path, value)
        if type(writefile) ~= "function" then return false end
        ensureFolder()
        local ok = pcall(writefile, path, tostring(value or ""))
        return ok
    end

    local function assetForFile(path)
        if type(getcustomasset) == "function" then
            local ok, asset = pcall(getcustomasset, path)
            if ok and type(asset) == "string" and asset ~= "" then return asset end
        end
        if type(getsynasset) == "function" then
            local ok, asset = pcall(getsynasset, path)
            if ok and type(asset) == "string" and asset ~= "" then return asset end
        end
        return nil
    end

    local lmsStatus = nil
    local function setStatus(message)
        if lmsStatus and lmsStatus.Parent then
            lmsStatus.Text = tostring(message or "")
        end
    end

    local function httpGet(url)
        local requestFunction = nil
        if type(request) == "function" then
            requestFunction = request
        elseif type(http_request) == "function" then
            requestFunction = http_request
        elseif type(syn) == "table" and type(syn.request) == "function" then
            requestFunction = syn.request
        end

        if requestFunction then
            local requestOK, response = pcall(function()
                return requestFunction({
                    Url = url,
                    Method = "GET",
                    Headers = {
                        Accept = "application/vnd.github+json, audio/*, */*",
                        ["User-Agent"] = "E1LU4SAKEN",
                    },
                })
            end)
            if requestOK then
                if type(response) == "table" then
                    local statusCode = tonumber(response.StatusCode or response.Status or response.status_code)
                    local body = response.Body or response.body
                    if type(body) == "string" and body ~= ""
                        and (not statusCode or (statusCode >= 200 and statusCode < 300)) then
                        return body
                    end
                elseif type(response) == "string" and response ~= "" then
                    return response
                end
            end
        end

        local httpOK, body = pcall(function() return game:HttpGet(url) end)
        if httpOK and type(body) == "string" and body ~= "" then
            return body
        end
        return nil
    end

    local function addFileToList(path, filename)
        if not isSupportedAudioFile(filename) then return false end
        local safeName = tostring(filename):gsub("\\", "/"):match("([^/]+)$") or tostring(filename)
        local displayName = safeName:gsub("%.[^%.]+$", "")
        if displayName == "" or displayName == "Custom" or displayName == "None" then return false end
        local lowerName = displayName:lower()
        if lowerName == "selectedlms" or lowerName == "customlmsid"
            or lowerName == "customlmsfile" or lowerName == "lmschangerenabled"
            or lowerName == "lms_download_toggle" then
            return false
        end
        if state.files[displayName] then return false end
        state.files[displayName] = path
        state.data[displayName] = true
        table.insert(state.names, displayName)
        return true
    end

    local function scanLocalLmsFiles()
        if type(listfiles) ~= "function" then return 0 end
        local found = 0
        local scanFolders = {LMS_FOLDER, LMS_MUSIC_FOLDER}
        for _, folder in ipairs(scanFolders) do
            local listOK, entries = pcall(listfiles, folder)
            if listOK and type(entries) == "table" then
                for _, path in ipairs(entries) do
                    if type(path) == "string" then
                        local normalized = path:gsub("\\", "/")
                        local filename = normalized:match("([^/]+)$") or normalized
                        if isFile(path) and addFileToList(path, filename) then
                            found += 1
                        end
                    end
                end
            end
        end
        return found
    end

    local function getLmsSound(waitSeconds)
        local themes = workspace:FindFirstChild("Themes")
        if not themes and waitSeconds and waitSeconds > 0 then
            local ok, found = pcall(function()
                return workspace:WaitForChild("Themes", waitSeconds)
            end)
            if ok then themes = found end
        end
        if not themes then return nil end
        local sound = themes:FindFirstChild("LastSurvivor")
        if not sound and waitSeconds and waitSeconds > 0 then
            local ok, found = pcall(function()
                return themes:WaitForChild("LastSurvivor", waitSeconds)
            end)
            if ok then sound = found end
        end
        if sound and sound:IsA("Sound") then return sound end
        return nil
    end

    local function restoreLmsSound(sound)
        sound = sound or getLmsSound(1)
        if not sound then
            setStatus("LMS sound has not spawned yet")
            return false
        end
        local original = sound:GetAttribute("E1LU4HUB_OriginalLMS_SoundId")
            or sound:GetAttribute("RealId")
            or sound:GetAttribute("RealID")
        if original and tostring(original) ~= "" then
            pcall(function() sound.SoundId = tostring(original) end)
            setStatus("Original LMS theme restored")
            return true
        end
        setStatus("Original LMS theme has not been captured")
        return false
    end

    local function resolveSelectedAsset()
        if state.selected == "None" or state.selected == "" then return nil end
        if state.selected == "Custom" then
            local customId = tostring(state.customId or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if customId ~= "" then
                local digits = customId:match("^rbxassetid://(%d+)$") or customId:match("^(%d+)$")
                if digits then return "rbxassetid://" .. digits end
            end
            local customFile = tostring(state.customFile or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if customFile ~= "" and isFile(customFile) and isSupportedAudioFile(customFile) then
                return assetForFile(customFile)
            end
            return nil
        end

        local localPath = state.files and state.files[state.selected]
            or (LMS_FOLDER .. "/" .. state.selected)
        if isFile(localPath) and isSupportedAudioFile(localPath) then
            return assetForFile(localPath)
        end
        return nil
    end

    local function applySelectedLms()
        task.spawn(function()
            local sound = getLmsSound(5)
            if not sound then
                setStatus("Could not find workspace.Themes.LastSurvivor")
                return
            end
            state.currentSound = sound
            if not sound:GetAttribute("E1LU4HUB_OriginalLMS_SoundId") then
                pcall(function()
                    sound:SetAttribute("E1LU4HUB_OriginalLMS_SoundId", sound.SoundId)
                end)
            end
            if state.selected == "None" or state.selected == "" then
                restoreLmsSound(sound)
                return
            end
            local asset = resolveSelectedAsset()
            if not asset then
                setStatus("LMS file unavailable. Refresh the URL library or check Custom ID/File.")
                return
            end
            local ok = pcall(function()
                sound.SoundId = asset
                sound.TimePosition = 0
            end)
            if ok then
                setStatus("Applied LMS: " .. tostring(state.selected))
            else
                setStatus("Could not apply the selected LMS theme")
            end
        end)
    end

    local function saveSelectedTheme(name)
        state.selected = tostring(name or "None")
        writeFile(LMS_FOLDER .. "/Selectedlms", state.selected)
        if state.enabled then applySelectedLms() end
        setStatus("Selected LMS: " .. state.selected)
    end

    -- Move old LMS files out of the executor-root E1LU4SAKEN directory.
    pcall(S.__helpers.migrateLegacyE1LU4SAKENFolder)
    state.selected = readFile(LMS_FOLDER .. "/Selectedlms", "None")
    state.customId = readFile(LMS_FOLDER .. "/CustomLMSID", "")
    state.customFile = readFile(LMS_FOLDER .. "/CustomLMSFile", "")
    -- All toggles begin OFF after script startup.
    state.enabled = false
    -- The existing preference file is retained: "0" disables URL downloads.
    state.downloadsDisabled = readFile(LMS_DOWNLOAD_FLAG, "1") == "0"

    S.__helpers.createSectionHeader("LMS")
    lmsStatus = Instance.new("TextLabel")
    lmsStatus.Name = "LMSStatusLabel"
    lmsStatus.Size = UDim2.new(0.92, 0, 0, 38)
    lmsStatus.BackgroundTransparency = 1
    lmsStatus.BorderSizePixel = 0
    lmsStatus.Text = "Connecting to the online LMS library..."
    lmsStatus.TextColor3 = S.uiAccentColor
    lmsStatus.Font = Enum.Font.Gotham
    lmsStatus.TextSize = 10
    lmsStatus.TextWrapped = true
    lmsStatus.TextXAlignment = Enum.TextXAlignment.Left
    lmsStatus.Parent = S.contentFrame

    local function refreshLmsList()
        state.refreshToken += 1
        local token = state.refreshToken
        state.loading = true
        state.names = {"None", "Custom"}
        state.data = {}
        state.files = {}
        state.downloaded = 0
        state.cached = 0
        state.failed = 0
        ensureFolder()

        local localCount = scanLocalLmsFiles()
        if state.downloadsDisabled then
            state.loading = false
            setStatus("LMS downloads disabled • " .. tostring(localCount) .. " local/cached track(s) available")
            return
        end

        setStatus("CONNECTING TO LMS URL...")
        task.spawn(function()
            local indexBody = httpGet(LMS_INDEX_URL)
            if state.refreshToken ~= token then return end
            if type(indexBody) ~= "string" then
                state.loading = false
                setStatus("LMS URL request failed • " .. tostring(localCount) .. " local track(s) available")
                return
            end

            local decodeOK, entries = pcall(function()
                return HttpService:JSONDecode(indexBody)
            end)
            if not decodeOK or type(entries) ~= "table" or entries.message then
                state.loading = false
                local reason = type(entries) == "table" and tostring(entries.message or "JSON error") or "JSON error"
                setStatus("LMS index error: " .. reason .. " • " .. tostring(localCount) .. " local track(s)")
                return
            end

            local remoteFiles = {}
            for _, entry in ipairs(entries) do
                if type(entry) == "table" and entry.type == "file"
                    and type(entry.name) == "string" and isSupportedAudioFile(entry.name)
                    and type(entry.download_url) == "string"
                    and entry.download_url:match("^https://raw%.githubusercontent%.com/") then
                    table.insert(remoteFiles, entry)
                end
            end
            table.sort(remoteFiles, function(a, b)
                return tostring(a.name):lower() < tostring(b.name):lower()
            end)

            local total = #remoteFiles
            if total == 0 then
                state.loading = false
                setStatus("LMS URL connected • No MP3/OGG/WAV files found • " .. tostring(localCount) .. " local track(s)")
                return
            end

            setStatus("DOWNLOADING LMS 0/" .. tostring(total) .. " • 0%")
            for index, entry in ipairs(remoteFiles) do
                if state.refreshToken ~= token then return end
                local filename = tostring(entry.name):gsub("[/\\]", "_")
                filename = filename:gsub("[^%w%._ %-%(%)]", "_")
                local displayName = filename:gsub("%.[^%.]+$", "")
                local destination = LMS_FOLDER .. "/" .. filename
                local alreadyListed = state.files[displayName] ~= nil

                if alreadyListed or isFile(destination) then
                    state.cached += 1
                    if not alreadyListed then
                        addFileToList(destination, filename)
                    end
                elseif type(writefile) ~= "function" then
                    state.failed += 1
                else
                    local currentPercent = math.floor(((index - 1) / total) * 100)
                    setStatus("DOWNLOADING LMS " .. tostring(index) .. "/" .. tostring(total)
                        .. " • " .. tostring(currentPercent) .. "%\n" .. displayName)
                    local audioBody = httpGet(entry.download_url)
                    if state.refreshToken ~= token then return end
                    if type(audioBody) == "string" and #audioBody > 0 then
                        local writeOK = pcall(writefile, destination, audioBody)
                        if writeOK and isFile(destination) then
                            if addFileToList(destination, filename) then
                                state.downloaded += 1
                            else
                                state.cached += 1
                            end
                        else
                            state.failed += 1
                        end
                    else
                        state.failed += 1
                    end
                end

                local percent = math.floor((index / total) * 100)
                setStatus("DOWNLOADING LMS " .. tostring(index) .. "/" .. tostring(total)
                    .. " • " .. tostring(percent) .. "%\nNew " .. tostring(state.downloaded)
                    .. " | Cached " .. tostring(state.cached) .. " | Failed " .. tostring(state.failed))
                task.wait(0.05)
            end

            if state.refreshToken ~= token then return end
            state.loading = false
            table.sort(state.names, function(a, b)
                if a == "None" then return b ~= "None" end
                if b == "None" then return false end
                if a == "Custom" then return b ~= "None" and b ~= "Custom" end
                if b == "Custom" then return false end
                return a:lower() < b:lower()
            end)
            setStatus("LMS READY • " .. tostring(#state.names - 2) .. " track(s)\nDownloaded "
                .. tostring(state.downloaded) .. " | Cached " .. tostring(state.cached)
                .. " | Failed " .. tostring(state.failed))
            if state.enabled and state.selected ~= "None" then
                applySelectedLms()
            end
        end)
    end
    state.refresh = refreshLmsList
    state.dropdown = S.PlopSpoofer.createDropdown("LMS Theme", function()
        local copy = {}
        for _, name in ipairs(state.names) do table.insert(copy, name) end
        return copy
    end, state.selected, saveSelectedTheme)

    S.PlopSpoofer.createInput("Custom LMS ID", state.customId, function(value)
        local raw = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
        local digits = raw:match("^rbxassetid://(%d+)$") or raw:match("^(%d+)$")
        if raw ~= "" and not digits then
            state.customId = ""
            writeFile(LMS_FOLDER .. "/CustomLMSID", "")
            setStatus("Only numeric Roblox asset IDs are accepted. Use Custom LMS File for local audio.")
            return
        end
        state.customId = digits or ""
        writeFile(LMS_FOLDER .. "/CustomLMSID", state.customId)
        if state.enabled then applySelectedLms() end
    end)
    S.PlopSpoofer.createInput("Custom LMS File", state.customFile, function(value)
        state.customFile = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
        writeFile(LMS_FOLDER .. "/CustomLMSFile", state.customFile)
        if state.customFile ~= "" and (not isFile(state.customFile) or not isSupportedAudioFile(state.customFile)) then
            setStatus("Choose an existing local MP3, OGG, or WAV file")
            return
        end
        if state.enabled then applySelectedLms() end
    end)
    S.PlopSpoofer.createButton("REFRESH / DOWNLOAD LMS", refreshLmsList)
    S.PlopSpoofer.createButton("APPLY LMS THEME", function()
        if not state.enabled then
            setStatus("Turn on Change LMS first")
            return
        end
        applySelectedLms()
    end)
    S.__helpers.createCoolToggle("CHANGE LMS", state.enabled, function(value)
        state.enabled = value == true
        if state.enabled then
            writeFile(LMS_FOLDER .. "/LmsChangerEnabled", "")
            applySelectedLms()
        else
            if type(delfile) == "function" and isFile(LMS_FOLDER .. "/LmsChangerEnabled") then
                pcall(delfile, LMS_FOLDER .. "/LmsChangerEnabled")
            end
            restoreLmsSound(state.currentSound)
        end
    end)
    S.__helpers.createCoolToggle("DISABLE LMS DOWNLOADS", state.downloadsDisabled, function(value)
        state.downloadsDisabled = value == true
        writeFile(LMS_DOWNLOAD_FLAG, state.downloadsDisabled and "0" or "1")
        refreshLmsList()
    end)

    local function onThemeChild(child)
        if child:IsA("Sound") and child.Name == "LastSurvivor" then
            task.defer(function()
                if state.enabled then applySelectedLms() end
            end)
        end
    end
    local themes = workspace:FindFirstChild("Themes")
    if themes then
        S.__helpers.connect(themes.ChildAdded, onThemeChild)
    end
    S.__helpers.connect(workspace.ChildAdded, function(child)
        if child.Name == "Themes" then
            S.__helpers.connect(child.ChildAdded, onThemeChild)
            local existingSound = child:FindFirstChild("LastSurvivor")
            if existingSound then onThemeChild(existingSound) end
        end
    end)
    state.cleanup = function()
        state.enabled = false
        state.refreshToken += 1
        state.loading = false
        restoreLmsSound(state.currentSound)
    end
    if state.enabled then task.defer(applySelectedLms) end
    task.defer(refreshLmsList)
end

-- ================================================================
-- MUSIC: CHASE + LOBBY REPLACEMENT (E1LU4HUB/Music cache)
-- Adds category-based local track replacement beside the existing LMS
-- selector. Chase IDs are loaded from the same public sound map as the
-- reference script; lobby sounds are matched by their in-game sound names.
-- ================================================================
do
    local HttpService = game:GetService("HttpService")
    local MUSIC_FOLDER = "E1LU4HUB/Music"
    local CHASE_SOUND_MAP_URL = "https://gist.githubusercontent.com/zxcursedsocute/4e0833a7a6cfdc537844b7545dd9079e/raw/gistfile1.json"
    local tracks = {
        Chase = {
            ["1X1X1X1 INFERNUM CHASE THEME"] = {
                file = "1X1X1X1_INFERNUM_CHASE_THEME.mp3",
                url = "https://raw.githubusercontent.com/zxcursedsocute/music/refs/heads/main/Music/1X1X1X1%20INFERNUM%20CHASE%20THEME.mp3",
            },
            ["Champion 1x1"] = {
                file = "Champion_1x1.mp3",
                url = "https://raw.githubusercontent.com/zxcursedsocute/music/refs/heads/main/Music/Champion%201x1.mp3",
            },
            ["ONE EGG"] = {
                file = "ONE_EGG.mp3",
                url = "https://raw.githubusercontent.com/zxcursedsocute/music/refs/heads/main/Music/ONE%20EGG.mp3",
            },
        },
        Lobby = {
            ["Monkeys Spinning Monkeys"] = {
                file = "Monkeys_Spinning_Monkeys.mp3",
                url = "https://raw.githubusercontent.com/zxcursedsocute/music/refs/heads/main/Music/Monkeys%20Spinning%20Monkeys.mp3",
            },
            ["Wii Shop"] = {
                file = "Wii_Shop.mp3",
                url = "https://raw.githubusercontent.com/zxcursedsocute/music/refs/heads/main/Music/Wii%20Shop.mp3",
            },
            ["confess your love"] = {
                file = "confess_your_love.mp3",
                url = "https://raw.githubusercontent.com/zxcursedsocute/music/refs/heads/main/Music/confess%20your%20love.mp3",
            },
        },
    }

    local categories = {
        Chase = {
            enabled = false,
            selected = "1X1X1X1 INFERNUM CHASE THEME",
            customId = "",
            customFile = "",
            originals = setmetatable({}, {__mode = "k"}),
            applied = setmetatable({}, {__mode = "k"}),
            bound = setmetatable({}, {__mode = "k"}),
            applying = setmetatable({}, {__mode = "k"}),
            cachedAsset = nil,
            resolving = false,
        },
        Lobby = {
            enabled = false,
            selected = "Monkeys Spinning Monkeys",
            customId = "",
            customFile = "",
            originals = setmetatable({}, {__mode = "k"}),
            applied = setmetatable({}, {__mode = "k"}),
            bound = setmetatable({}, {__mode = "k"}),
            applying = setmetatable({}, {__mode = "k"}),
            cachedAsset = nil,
            resolving = false,
        },
    }
    S.MusicReplacements = categories
    local chaseSoundIds = {}
    local chaseMapLoaded = false
    local themesFolder = nil

    local function isFile(path)
        if type(isfile) ~= "function" then return false end
        local ok, result = pcall(isfile, path)
        return ok and result == true
    end

    local function ensureFolder()
        if type(makefolder) ~= "function" then return end
        pcall(makefolder, "E1LU4HUB")
        pcall(makefolder, MUSIC_FOLDER)
        pcall(S.__helpers.migrateLegacyE1LU4SAKENFolder)
    end

    local function assetForFile(path)
        if type(getcustomasset) == "function" then
            local ok, asset = pcall(getcustomasset, path)
            if ok and type(asset) == "string" and asset ~= "" then return asset end
        end
        if type(getsynasset) == "function" then
            local ok, asset = pcall(getsynasset, path)
            if ok and type(asset) == "string" and asset ~= "" then return asset end
        end
        return nil
    end

    local function downloadTrack(path, url)
        if not isFile(path) then
            if type(writefile) ~= "function" then return nil end
            local ok, body = pcall(function() return game:HttpGet(url) end)
            if not ok or type(body) ~= "string" or body == "" then return nil end
            ensureFolder()
            local writeOK = pcall(writefile, path, body)
            if not writeOK then return nil end
        end
        return assetForFile(path)
    end

    local function resolveAsset(categoryName)
        local state = categories[categoryName]
        if not state then return nil end
        if state.selected == "None" then return nil end
        if state.selected == "Custom" then
            local custom = tostring(state.customId or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if custom ~= "" then
                if custom:match("^%d+$") then return "rbxassetid://" .. custom end
                if custom:match("^rbxassetid://%d+$") then return custom end
                if isFile(custom) then return assetForFile(custom) end
            end
            local file = tostring(state.customFile or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if file ~= "" and isFile(file) then return assetForFile(file) end
            return nil
        end
        if state.cachedAsset then return state.cachedAsset end
        if state.resolving then
            while state.resolving and state.enabled do task.wait(0.05) end
            if not state.enabled then return nil end
            if state.cachedAsset then return state.cachedAsset end
        end
        local selected = state.selected
        local definition = tracks[categoryName] and tracks[categoryName][selected]
        if not definition then return nil end
        state.resolving = true
        local asset = downloadTrack(MUSIC_FOLDER .. "/" .. definition.file, definition.url)
        state.resolving = false
        if state.selected ~= selected then return nil end
        state.cachedAsset = asset
        return asset
    end

    local function getOriginalSoundId(sound)
        local original = nil
        pcall(function()
            original = sound:GetAttribute("OriginalSoundId")
                or sound:GetAttribute("RealId")
                or sound:GetAttribute("RealID")
        end)
        return original or sound.SoundId
    end

    local function classifySound(sound)
        if not sound or not sound:IsA("Sound") then return nil end
        local lowerName = tostring(sound.Name):lower()
        if lowerName == "lobby" or lowerName == "oldlobby"
            or lowerName == "deathlobby" or lowerName == "spectreoutside" then
            return "Lobby"
        end
        if lowerName:find("chase", 1, true) or lowerName:find("terror", 1, true) then
            return "Chase"
        end
        local soundId = tostring(getOriginalSoundId(sound)):match("(%d+)")
        if soundId and chaseSoundIds[soundId] then return "Chase" end
        return nil
    end

    local function restoreSound(categoryName, sound)
        local state = categories[categoryName]
        local original = state and state.originals[sound]
        if not original or not sound or not sound.Parent then return end
        state.applying[sound] = true
        pcall(function()
            local wasPlaying = sound.Playing
            sound.SoundId = original
            if wasPlaying then sound:Play() end
        end)
        state.applying[sound] = nil
        state.applied[sound] = nil
    end

    local function applySound(categoryName, sound)
        local state = categories[categoryName]
        if not state or not state.enabled or not sound or not sound.Parent then return end
        if state.selected == "None" then
            restoreSound(categoryName, sound)
            return
        end
        task.spawn(function()
            local asset = resolveAsset(categoryName)
            if not asset or not state.enabled or not sound.Parent then return end
            local original = state.originals[sound]
            if not original then
                original = getOriginalSoundId(sound)
                state.originals[sound] = original
                pcall(function() sound:SetAttribute("E1LU4HUB_Original_" .. categoryName, original) end)
            end
            if state.applied[sound] == asset and sound.SoundId == asset then return end
            state.applying[sound] = true
            local wasPlaying = sound.Playing
            local ok = pcall(function()
                sound.SoundId = asset
                sound.TimePosition = 0
                sound:SetAttribute("E1LU4HUB_Custom_" .. categoryName, true)
            end)
            if ok then
                state.applied[sound] = asset
                if wasPlaying then pcall(function() sound:Play() end) end
            end
            state.applying[sound] = nil
        end)
    end

    local function bindSound(sound)
        if not sound or not sound:IsA("Sound") then return end
        local categoryName = classifySound(sound)
        if not categoryName then return end
        local state = categories[categoryName]
        if state.bound[sound] then
            if state.enabled then applySound(categoryName, sound) end
            return
        end
        state.bound[sound] = true
        S.__helpers.connect(sound:GetPropertyChangedSignal("SoundId"), function()
            if state.applying[sound] then return end
            local applied = state.applied[sound]
            if applied and sound.SoundId ~= applied then
                -- The game changed the real theme while our local replacement was active.
                state.originals[sound] = sound.SoundId
                pcall(function() sound:SetAttribute("E1LU4HUB_Original_" .. categoryName, sound.SoundId) end)
                state.applied[sound] = nil
                if state.enabled then task.defer(applySound, categoryName, sound) end
            end
        end)
        if state.enabled then applySound(categoryName, sound) end
    end

    local function applyCategory(categoryName)
        local state = categories[categoryName]
        if not state then return end
        if not themesFolder then themesFolder = workspace:FindFirstChild("Themes") end
        if not themesFolder then return end
        for _, sound in ipairs(themesFolder:GetChildren()) do
            if sound:IsA("Sound") and classifySound(sound) == categoryName then
                bindSound(sound)
                if state.enabled then applySound(categoryName, sound) end
            end
        end
    end

    local function setCategoryEnabled(categoryName, enabled)
        local state = categories[categoryName]
        state.enabled = enabled == true
        if state.enabled then
            applyCategory(categoryName)
        else
            for sound in pairs(state.originals) do
                restoreSound(categoryName, sound)
            end
        end
    end
    S.AudioReplacementCleanup = function()
        setCategoryEnabled("Chase", false)
        setCategoryEnabled("Lobby", false)
    end

    local function refreshChaseSoundMap()
        if chaseMapLoaded then return end
        task.spawn(function()
            local ok, body = pcall(function() return game:HttpGet(CHASE_SOUND_MAP_URL) end)
            if not ok or type(body) ~= "string" or body == "" then return end
            local decodeOK, data = pcall(function() return HttpService:JSONDecode(body) end)
            if not decodeOK or type(data) ~= "table" then return end
            for key in pairs(data.c or {}) do
                local id = tostring(key):match("(%d+)")
                if id then chaseSoundIds[id] = true end
            end
            chaseMapLoaded = true
            if categories.Chase.enabled then applyCategory("Chase") end
        end)
    end

    local function bindThemes(folder)
        if not folder or themesFolder == folder then return end
        themesFolder = folder
        for _, sound in ipairs(folder:GetChildren()) do bindSound(sound) end
        S.__helpers.connect(folder.ChildAdded, function(child)
            task.defer(function() bindSound(child) end)
        end)
    end

    local initialThemes = workspace:FindFirstChild("Themes")
    if initialThemes then bindThemes(initialThemes) end
    S.__helpers.connect(workspace.ChildAdded, function(child)
        if child.Name == "Themes" then bindThemes(child) end
    end)

    -- Guest 1337 Audio controls from E1LU4SAKEN's Audio page.
    S.__helpers.createSectionHeader("GUEST 1337 AUDIO")
    S.Guest1337Audio = {BlockSuccessID = "", BlockSuccessFile = "", ParryID = "", ParryFile = "",
        PunchID = "", PunchFile = "", silenceRageSFX = false, connections = {}, originals = setmetatable({}, {__mode = "k"})}
    local function guestAudioValue(idValue, fileValue)
        if idValue ~= "" then return idValue end
        if fileValue ~= "" then return fileValue end
        return nil
    end
    local function setGuestAudioId(kind, value)
        value = tostring(value or "")
        if value == "" then S.Guest1337Audio[kind .. "ID"] = ""; return end
        if tonumber(value) then value = "rbxassetid://" .. value end
        if value:find("rbxassetid://", 1, true) or value:find("http://www.roblox.com/asset/", 1, true) then
            S.Guest1337Audio[kind .. "ID"] = value
            pcall(function() game:GetService("ContentProvider"):PreloadAsync({value}) end)
        else
            S.Guest1337Audio[kind .. "ID"] = ""
        end
    end
    local function setGuestAudioFile(kind, value)
        value = tostring(value or "")
        if value == "" then S.Guest1337Audio[kind .. "File"] = ""; return end
        if type(isfile) ~= "function" or type(getcustomasset) ~= "function" then
            S.Guest1337Audio[kind .. "File"] = ""
            if S.__helpers.notify then S.__helpers.notify(kind .. " audio", "File audio is not supported by this executor.", 4) end
            return
        end
        local okFile, exists = pcall(isfile, value)
        if not okFile or not exists then
            S.Guest1337Audio[kind .. "File"] = ""
            if S.__helpers.notify then S.__helpers.notify(kind .. " audio", "File not found.", 4) end
            return
        end
        local okAsset, asset = pcall(getcustomasset, value)
        if okAsset and type(asset) == "string" then
            S.Guest1337Audio[kind .. "File"] = asset
            pcall(function() game:GetService("ContentProvider"):PreloadAsync({asset}) end)
        end
    end
    S.PlopSpoofer.createInput("Block Success | ID", "", function(value) setGuestAudioId("BlockSuccess", value) end)
    S.PlopSpoofer.createInput("Block Success | File", "", function(value) setGuestAudioFile("BlockSuccess", value) end)
    S.PlopSpoofer.createInput("Parry | ID", "", function(value) setGuestAudioId("Parry", value) end)
    S.PlopSpoofer.createInput("Parry | File", "", function(value) setGuestAudioFile("Parry", value) end)
    S.PlopSpoofer.createInput("Punch | ID", "", function(value) setGuestAudioId("Punch", value) end)
    S.PlopSpoofer.createInput("Punch | File", "", function(value) setGuestAudioFile("Punch", value) end)
    S.__helpers.createCoolToggle("SILENCE RAGE SFX", false, function(value)
        S.Guest1337Audio.silenceRageSFX = value == true
    end)
    S.__helpers.applyGuest1337Audio = function(sound)
        local state = S.Guest1337Audio
        if not sound or not sound:IsA("Sound") then return end
        local character = sound:FindFirstAncestor("Guest1337")
        if not character then return end
        if state.silenceRageSFX and sound.Name == "rbxassetid://109931874166612" then
            pcall(function() sound:Destroy() end)
            return
        end
        local config
        pcall(function()
            local assets = S.ReplicatedStorage:FindFirstChild("Assets")
            local survivors = assets and assets:FindFirstChild("Survivors")
            local guest = survivors and survivors:FindFirstChild("Guest1337")
            local baseModule = guest and guest:FindFirstChild("Config")
            config = baseModule and require(baseModule)
            local skinName = character:GetAttribute("SkinName")
            local skins = assets and assets:FindFirstChild("Skins")
            local skinSurvivors = skins and skins:FindFirstChild("Survivors")
            local guestSkins = skinSurvivors and skinSurvivors:FindFirstChild("Guest1337")
            local skin = skinName and guestSkins and guestSkins:FindFirstChild(skinName)
            local skinConfig = skin and skin:FindFirstChild("Config")
            if skinConfig then
                local skinData = require(skinConfig)
                if skinData then config = skinData end
            end
        end)
        local baseSounds = config and config.Sounds or {}
        local override
        if sound.Name == tostring(baseSounds.BlockSuccess or "") then
            override = guestAudioValue(state.BlockSuccessID, state.BlockSuccessFile)
        elseif sound.SoundId == tostring(baseSounds.Parry or "") then
            override = guestAudioValue(state.ParryID, state.ParryFile)
        elseif sound.SoundId == tostring(baseSounds.Punch or "") then
            override = guestAudioValue(state.PunchID, state.PunchFile)
        end
        if override then
            if not state.originals[sound] then state.originals[sound] = sound.SoundId end
            pcall(function() sound.SoundId = override end)
        end
    end
    local function bindGuestAudio(root)
        if not root then return end
        for _, object in ipairs(root:GetDescendants()) do S.__helpers.applyGuest1337Audio(object) end
        S.__helpers.connect(root.DescendantAdded, function(object)
            task.defer(S.__helpers.applyGuest1337Audio, object)
        end)
    end
    local watchedSurvivorFolder
    local function bindGuestSurvivorFolder(survivorFolder)
        if not survivorFolder or watchedSurvivorFolder == survivorFolder then return end
        watchedSurvivorFolder = survivorFolder
        for _, model in ipairs(survivorFolder:GetChildren()) do
            if model.Name == "Guest1337" then bindGuestAudio(model) end
        end
        S.__helpers.connect(survivorFolder.ChildAdded, function(model)
            if model.Name == "Guest1337" then bindGuestAudio(model) end
        end)
    end
    local function bindPlayersFolder(playerFolder)
        if not playerFolder then return end
        bindGuestSurvivorFolder(playerFolder:FindFirstChild("Survivors"))
        S.__helpers.connect(playerFolder.ChildAdded, function(child)
            if child.Name == "Survivors" then bindGuestSurvivorFolder(child) end
        end)
    end
    bindPlayersFolder(workspace:FindFirstChild("Players"))
    S.__helpers.connect(workspace.ChildAdded, function(child)
        if child.Name == "Players" then bindPlayersFolder(child) end
    end)

    S.__helpers.createSectionHeader("CHASE MUSIC")
    S.PlopSpoofer.createDropdown("Chase Track", function()
        return {"None", "1X1X1X1 INFERNUM CHASE THEME", "Champion 1x1", "ONE EGG", "Custom"}
    end, categories.Chase.selected, function(value)
        categories.Chase.selected = value
        categories.Chase.cachedAsset = nil
        applyCategory("Chase")
    end)
    S.PlopSpoofer.createInput("Chase Custom Asset ID", categories.Chase.customId, function(value)
        categories.Chase.customId = tostring(value or "")
        categories.Chase.cachedAsset = nil
        if categories.Chase.enabled and categories.Chase.selected == "Custom" then applyCategory("Chase") end
    end)
    S.PlopSpoofer.createInput("Chase Custom File", categories.Chase.customFile, function(value)
        local path = tostring(value or "")
        categories.Chase.customFile = isFile(path) and path or ""
        categories.Chase.cachedAsset = nil
        if categories.Chase.enabled and categories.Chase.selected == "Custom" then applyCategory("Chase") end
        if path ~= "" and not isFile(path) and S.__helpers.notify then
            S.__helpers.notify("Chase Custom File", "File not found. Enter a valid local audio path.", 4)
        end
    end)
    S.__helpers.createCoolToggle("CHANGE CHASE MUSIC", false, function(value)
        setCategoryEnabled("Chase", value)
        if value then refreshChaseSoundMap() end
    end)

    S.__helpers.createSectionHeader("LOBBY MUSIC")
    S.PlopSpoofer.createDropdown("Lobby Track", function()
        return {"None", "Monkeys Spinning Monkeys", "Wii Shop", "confess your love", "Custom"}
    end, categories.Lobby.selected, function(value)
        categories.Lobby.selected = value
        categories.Lobby.cachedAsset = nil
        applyCategory("Lobby")
    end)
    S.PlopSpoofer.createInput("Lobby Custom Asset ID", categories.Lobby.customId, function(value)
        categories.Lobby.customId = tostring(value or "")
        categories.Lobby.cachedAsset = nil
        if categories.Lobby.enabled and categories.Lobby.selected == "Custom" then applyCategory("Lobby") end
    end)
    S.PlopSpoofer.createInput("Lobby Custom File", categories.Lobby.customFile, function(value)
        local path = tostring(value or "")
        categories.Lobby.customFile = isFile(path) and path or ""
        categories.Lobby.cachedAsset = nil
        if categories.Lobby.enabled and categories.Lobby.selected == "Custom" then applyCategory("Lobby") end
        if path ~= "" and not isFile(path) and S.__helpers.notify then
            S.__helpers.notify("Lobby Custom File", "File not found. Enter a valid local audio path.", 4)
        end
    end)
    S.__helpers.createCoolToggle("CHANGE LOBBY MUSIC", false, function(value)
        setCategoryEnabled("Lobby", value)
    end)
    refreshChaseSoundMap()
end

-- ================================================================
-- ANIMATION TAB: Ghost Abilities + Animation Changer
-- The previous local movement overrides and ghost-animation filters are removed.
-- This tab now uses the corresponding systems from the supplied reference file.
-- ================================================================
S.GhostAbilities = {
    enabled = {
        GhostPunch = false,
        GhostBlock = false,
        GhostCrystalPitch = false,
        GhostHatchet = false,
        GhostShoot = false,
    },
    hooks = {},
}

-- Reversible Behavior.Abilities callback hooks for Ghost Ability toggles.
S.__helpers.setGhostAbility = function(characterName, abilityName, enabled)
    local ghostState = S.GhostAbilities
    if type(ghostState) ~= "table" then return false end

    local key = tostring(characterName) .. ":" .. tostring(abilityName)
    local existing = ghostState.hooks[key]

    if enabled ~= true then
        ghostState.enabled[key] = false
        if not existing then return true end

        local restored = false
        if type(hookfunction) == "function" and type(existing.callback) == "function"
            and type(existing.original) == "function" then
            local okRestore = pcall(function()
                hookfunction(existing.callback, existing.original)
            end)
            restored = okRestore
        end
        if existing.ability and existing.ability.Callback == existing.callback then
            pcall(function() existing.ability.Callback = existing.original end)
            restored = true
        end
        if restored then
            ghostState.hooks[key] = nil
            return true
        end
        warn("[E1LU4SAKEN Ghost Abilities] Could not restore " .. key)
        return false
    end

    ghostState.enabled[key] = true
    if existing then return true end

    if type(hookfunction) ~= "function" then
        warn("[E1LU4SAKEN Ghost Abilities] hookfunction is unavailable.")
        return false
    end

    local replicatedStorage = S.ReplicatedStorage
    local assets = replicatedStorage and replicatedStorage:FindFirstChild("Assets")
    local survivors = assets and assets:FindFirstChild("Survivors")
    local survivorAssets = survivors and survivors:FindFirstChild(tostring(characterName))
    local behaviorModule = survivorAssets and survivorAssets:FindFirstChild("Behavior")
    if not behaviorModule or not behaviorModule:IsA("ModuleScript") then
        warn("[E1LU4SAKEN Ghost Abilities] Behavior module not found: " .. tostring(characterName))
        return false
    end

    local okRequire, behavior = pcall(require, behaviorModule)
    if not okRequire or type(behavior) ~= "table"
        or type(behavior.Abilities) ~= "table" then
        warn("[E1LU4SAKEN Ghost Abilities] Could not load abilities for " .. tostring(characterName))
        return false
    end

    local ability = behavior.Abilities[abilityName]
    local callback = ability and ability.Callback
    if type(callback) ~= "function" then
        warn("[E1LU4SAKEN Ghost Abilities] Ability callback not found: " .. key)
        return false
    end

    local okHook, original = pcall(function()
        return hookfunction(callback, function(...) end)
    end)
    if not okHook or type(original) ~= "function" then
        warn("[E1LU4SAKEN Ghost Abilities] Failed to hook " .. key .. ": " .. tostring(original))
        return false
    end

    ghostState.hooks[key] = {
        callback = callback,
        original = original,
        ability = ability,
        module = behaviorModule,
    }
    return true
end

