S.__helpers.createSectionHeader("ANIMATION CHANGER")
do
    -- Animation Changer follows ForsakenPlus's local Idle/Walk/Run override approach.
    -- It builds a searchable preset list from ReplicatedStorage.Assets config modules.
    local AnimationChanger = {
        selected = "Original",
        presets = {},
        presetsBuilt = false,
        character = nil,
        humanoid = nil,
        animator = nil,
        tracks = {},
        trackIds = {},
        animationFolder = nil,
        currentType = nil,
        currentPreset = nil,
        lastNativeTrack = nil,
        playedConnection = nil,
        moveConnection = nil,
        sprintConnection = nil,
        heartbeatConnection = nil,
        characterAddedConnection = nil,
    }
    S.AnimationChanger = AnimationChanger

    local function animationAssetId(value, seen)
        if type(value) == "table" then
            seen = seen or {}
            if seen[value] then return nil end
            seen[value] = true
            for _, key in ipairs({"AnimationId", "AnimationID", "AssetId", "AssetID", "Id", "ID", "Animation", "IdValue"}) do
                if value[key] ~= nil then
                    local found = animationAssetId(value[key], seen)
                    if found then return found end
                end
            end
            for _, nested in pairs(value) do
                local found = animationAssetId(nested, seen)
                if found then return found end
            end
            return nil
        end
        if type(value) ~= "string" and type(value) ~= "number" then
            return nil
        end
        local text = tostring(value)
        if text:find("rbxassetid://", 1, true) or text:match("^https?://") then
            return text
        end
        local digits = text:match("%d+")
        return digits and ("rbxassetid://" .. digits) or nil
    end

    local function getMoveAnimation(animationData, moveName)
        if type(animationData) ~= "table" then return nil end
        local aliases = {
            Idle = {"Idle", "IdleAnimation"},
            Walk = {"Walk", "Walking", "WalkAnimation"},
            Run = {"Run", "Running", "RunAnimation"},
        }
        for _, alias in ipairs(aliases[moveName] or {moveName}) do
            for key, value in pairs(animationData) do
                if type(key) == "string" and key:lower() == alias:lower() then
                    local assetId = animationAssetId(value)
                    if assetId then return assetId end
                end
            end
        end
        return nil
    end

    AnimationChanger.scanPresets = function(forceRefresh)
        if AnimationChanger.presetsBuilt and not forceRefresh then
            return AnimationChanger.presets
        end

        local presets = {
            ["Default Roblox"] = {
                Idle = "rbxassetid://180435571",
                Walk = "rbxassetid://180426354",
                Run = "rbxassetid://180426354",
            },
        }
        local assets = S.ReplicatedStorage:FindFirstChild("Assets")
        if assets then
            for _, groupName in ipairs({"Killers", "Survivors", "Skins"}) do
                local group = assets:FindFirstChild(groupName)
                if group then
                    for _, configModule in ipairs(group:GetDescendants()) do
                        if configModule:IsA("ModuleScript")
                            and configModule.Name == "Config"
                            and configModule.Parent
                            and not configModule.Parent:IsA("Model") then
                            local ok, configData = pcall(require, configModule)
                            if ok and type(configData) == "table"
                                and type(configData.Animations) == "table"
                                and type(configData.DisplayName) == "string"
                                and configData.DisplayName ~= "" then
                                local displayName = configData.DisplayName
                                if displayName:find("Milestone", 1, true) then
                                    local characterFolder = configModule.Parent.Parent
                                    if characterFolder then
                                        displayName = characterFolder.Name .. " " .. displayName:gsub("Milestone%s*", "")
                                    end
                                end

                                local preset = {
                                    Idle = getMoveAnimation(configData.Animations, "Idle"),
                                    Walk = getMoveAnimation(configData.Animations, "Walk"),
                                    Run = getMoveAnimation(configData.Animations, "Run"),
                                }
                                -- ForsakenPlus excludes presets which have no idle animation.
                                if preset.Idle then
                                    local finalName = displayName
                                    if presets[finalName] then
                                        local parentName = configModule.Parent.Name
                                        finalName = displayName .. " (" .. parentName .. ")"
                                    end
                                    presets[finalName] = preset
                                end
                            end
                        end
                    end
                end
            end
        end

        AnimationChanger.presets = presets
        AnimationChanger.presetsBuilt = true
        return presets
    end

    local function disconnectCharacterConnections()
        for _, key in ipairs({"playedConnection", "moveConnection", "sprintConnection", "heartbeatConnection"}) do
            local connection = AnimationChanger[key]
            if connection then
                pcall(function() connection:Disconnect() end)
                AnimationChanger[key] = nil
            end
        end
    end

    local function clearOverrideTracks()
        for _, track in pairs(AnimationChanger.tracks) do
            pcall(function() track:Stop(0.12) end)
        end
        table.clear(AnimationChanger.tracks)
        table.clear(AnimationChanger.trackIds)
        AnimationChanger.currentType = nil
        AnimationChanger.currentPreset = nil
        if AnimationChanger.animationFolder then
            pcall(function() AnimationChanger.animationFolder:Destroy() end)
            AnimationChanger.animationFolder = nil
        elseif AnimationChanger.character then
            local leftover = AnimationChanger.character:FindFirstChild("E1LU4SAKEN_AnimationChangerOverrides")
            if leftover then pcall(function() leftover:Destroy() end) end
        end
    end

    local function isLocomotionTrack(track)
        if not track then return false end
        local ok, animation = pcall(function() return track.Animation end)
        if not ok or not animation then return false end
        local attrOk, isOverride = pcall(function()
            return animation:GetAttribute("E1LU4SAKEN_AnimationChanger")
        end)
        if attrOk and isOverride then return false end

        local rawId = ""
        pcall(function() rawId = tostring(animation.AnimationId or "") end)
        local numericId = tonumber(rawId:match("%d+"))

        -- Prefer the game's own animation classifier when available.
        local animationType
        if numericId and type(S.__helpers.getForsakenAnimationType) == "function" then
            pcall(function()
                animationType = S.__helpers.getForsakenAnimationType(numericId)
            end)
        end
        if type(animationType) == "string" then
            local kind = animationType:lower()
            if kind:find("idle", 1, true) or kind:find("walk", 1, true)
                or kind:find("run", 1, true) then
                return true
            end
        end

        -- Match the animation ID against the preset assets so skin/milestone locomotion
        -- tracks are recognized even when the game classifier does not know them.
        local presets = AnimationChanger.scanPresets()
        for _, preset in pairs(presets) do
            if type(preset) == "table" then
                for _, moveName in ipairs({"Idle", "Walk", "Run"}) do
                    local presetId = preset[moveName]
                    if presetId and rawId:match("%d+") and tostring(presetId):match("%d+")
                        == rawId:match("%d+") then
                        return true
                    end
                end
            end
        end

        local animationName = ""
        pcall(function()
            animationName = (tostring(track.Name or "") .. " " .. tostring(animation.Name or "")):lower()
        end)
        if animationName:find("idle", 1, true) or animationName:find("walk", 1, true)
            or animationName:find("run", 1, true) then
            return true
        end

        -- Roblox default Animate locomotion IDs.
        local knownDefaults = {
            ["180435571"] = true, ["180426354"] = true,
            ["180436148"] = true, ["180436334"] = true,
        }
        return numericId ~= nil and knownDefaults[tostring(numericId)] == true
    end

    local function isSprinting()
        local character = AnimationChanger.character
        local humanoid = AnimationChanger.humanoid
        local speedMultipliers = character and character:FindFirstChild("SpeedMultipliers")
        local sprinting = speedMultipliers and speedMultipliers:FindFirstChild("Sprinting")
        if sprinting and (sprinting:IsA("NumberValue") or sprinting:IsA("IntValue")) then
            if sprinting.Value > 1.01 then return true end
        end
        return humanoid ~= nil and humanoid.WalkSpeed > 17.5
    end

    AnimationChanger.update = function()
        if AnimationChanger.selected == "Original" then return end
        local character = AnimationChanger.character
        local humanoid = AnimationChanger.humanoid
        local animator = AnimationChanger.animator
        if not character or not character.Parent or not humanoid or humanoid.Health <= 0 or not animator then
            return
        end

        local presets = AnimationChanger.scanPresets()
        local preset = presets[AnimationChanger.selected]
        if not preset then return end

        local moveName
        if humanoid.MoveDirection.Magnitude < 0.05 then
            moveName = "Idle"
        elseif isSprinting() then
            moveName = "Run"
        else
            moveName = "Walk"
        end
        local targetId = preset[moveName]
            or (moveName == "Run" and preset.Walk)
            or (moveName == "Walk" and preset.Run)
            or preset.Idle
        if not targetId then return end

        local activeTrack = AnimationChanger.tracks[moveName]
        if AnimationChanger.currentPreset == AnimationChanger.selected
            and AnimationChanger.currentType == moveName
            and AnimationChanger.trackIds[moveName] == targetId
            and activeTrack and activeTrack.IsPlaying then
            return
        end

        if AnimationChanger.currentPreset ~= AnimationChanger.selected then
            clearOverrideTracks()
            AnimationChanger.currentPreset = AnimationChanger.selected
        end

        if not AnimationChanger.animationFolder or AnimationChanger.animationFolder.Parent ~= character then
            local leftover = character:FindFirstChild("E1LU4SAKEN_AnimationChangerOverrides")
            if leftover then pcall(function() leftover:Destroy() end) end
            local folder = Instance.new("Folder")
            folder.Name = "E1LU4SAKEN_AnimationChangerOverrides"
            folder.Parent = character
            AnimationChanger.animationFolder = folder
        end

        activeTrack = AnimationChanger.tracks[moveName]
        if not activeTrack or AnimationChanger.trackIds[moveName] ~= targetId then
            if activeTrack then pcall(function() activeTrack:Stop(0.1) end) end
            local animation = Instance.new("Animation")
            animation.Name = "E1LU4SAKEN_Override_" .. moveName
            animation.AnimationId = targetId
            animation:SetAttribute("E1LU4SAKEN_AnimationChanger", true)
            animation.Parent = AnimationChanger.animationFolder
            local ok, loadedTrack = pcall(function() return animator:LoadAnimation(animation) end)
            if not ok or not loadedTrack then
                pcall(function() animation:Destroy() end)
                warn("[E1LU4SAKEN / Animation Changer] Failed to load " .. moveName .. " animation: " .. tostring(targetId))
                return
            end
            loadedTrack.Priority = Enum.AnimationPriority.Movement
            loadedTrack.Looped = true
            AnimationChanger.tracks[moveName] = loadedTrack
            AnimationChanger.trackIds[moveName] = targetId
            activeTrack = loadedTrack
        end

        for name, track in pairs(AnimationChanger.tracks) do
            if name ~= moveName and track.IsPlaying then
                pcall(function() track:Stop(0.12) end)
            end
        end

        -- Follow the reference script's distinction between locomotion and action tracks.
        -- Native idle/walk/run tracks are stopped; attacks, emotes, and other action tracks
        -- are left running and the override fades in more gently around them.
        local foundAction = false
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            if track ~= activeTrack and track.IsPlaying then
                if isLocomotionTrack(track) then
                    AnimationChanger.lastNativeTrack = track
                    pcall(function() track:Stop(0) end)
                else
                    foundAction = true
                end
            end
        end

        pcall(function()
            if not activeTrack.IsPlaying then
                activeTrack:Play(foundAction and 0.3 or 0.1)
            end
        end)
        AnimationChanger.currentType = moveName
        AnimationChanger.currentPreset = AnimationChanger.selected
    end

    AnimationChanger.setPreset = function(name)
        name = tostring(name or "Original")
        if name ~= "Original" then
            local presets = AnimationChanger.scanPresets()
            if not presets[name] then
                warn("[E1LU4SAKEN / Animation Changer] Unknown preset: " .. name)
                return
            end
        end

        local restoreTrack = AnimationChanger.lastNativeTrack
        AnimationChanger.selected = name
        clearOverrideTracks()
        if name == "Original" then
            if restoreTrack then
                task.defer(function()
                    pcall(function() restoreTrack:Play(0.12) end)
                end)
            end
            AnimationChanger.lastNativeTrack = nil
        else
            task.defer(function() AnimationChanger.update() end)
        end
    end

    local function bindCharacter(character)
        disconnectCharacterConnections()
        clearOverrideTracks()
        AnimationChanger.character = character
        AnimationChanger.humanoid = character and character:FindFirstChildOfClass("Humanoid")
        AnimationChanger.animator = nil
        AnimationChanger.lastNativeTrack = nil
        local humanoid = AnimationChanger.humanoid
        if not humanoid then return end

        local animator = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 5)
        if not animator or not animator:IsA("Animator") then return end
        AnimationChanger.animator = animator

        AnimationChanger.playedConnection = animator.AnimationPlayed:Connect(function(track)
            if AnimationChanger.selected == "Original" then return end
            if isLocomotionTrack(track) then
                AnimationChanger.lastNativeTrack = track
                task.defer(function()
                    if AnimationChanger.selected ~= "Original" and track.IsPlaying
                        and isLocomotionTrack(track) then
                        pcall(function() track:Stop(0) end)
                    end
                    AnimationChanger.update()
                end)
            else
                -- Action animations are not cancelled; restore the selected locomotion
                -- preset after the action track ends, matching the reference behavior.
                task.spawn(function()
                    local stopped = false
                    local connection
                    pcall(function()
                        connection = track.Stopped:Connect(function() stopped = true end)
                    end)
                    local deadline = os.clock() + math.max(tonumber(track.Length) or 0, 1) + 1
                    while AnimationChanger.selected ~= "Original" and track.IsPlaying
                        and os.clock() < deadline do
                        task.wait(0.05)
                    end
                    if connection then pcall(function() connection:Disconnect() end) end
                    if AnimationChanger.selected ~= "Original" then
                        task.defer(function() AnimationChanger.update() end)
                    end
                end)
            end
        end)
        AnimationChanger.moveConnection = humanoid:GetPropertyChangedSignal("MoveDirection"):Connect(function()
            AnimationChanger.update()
        end)

        local speedMultipliers = character:FindFirstChild("SpeedMultipliers")
        local sprinting = speedMultipliers and speedMultipliers:FindFirstChild("Sprinting")
        if sprinting then
            AnimationChanger.sprintConnection = sprinting:GetPropertyChangedSignal("Value"):Connect(function()
                AnimationChanger.update()
            end)
        end

        local lastRefresh = 0
        AnimationChanger.heartbeatConnection = S.RunService.Heartbeat:Connect(function()
            if AnimationChanger.selected ~= "Original" then
                local now = os.clock()
                if now - lastRefresh >= 0.18 then
                    lastRefresh = now
                    AnimationChanger.update()
                end
            end
        end)
        task.defer(function()
            if AnimationChanger.character == character then AnimationChanger.update() end
        end)
    end

    AnimationChanger.shutdown = function()
        AnimationChanger.selected = "Original"
        disconnectCharacterConnections()
        clearOverrideTracks()
        local restoreTrack = AnimationChanger.lastNativeTrack
        if restoreTrack then
            task.defer(function() pcall(function() restoreTrack:Play(0.12) end) end)
        end
        AnimationChanger.lastNativeTrack = nil
        if AnimationChanger.characterAddedConnection then
            pcall(function() AnimationChanger.characterAddedConnection:Disconnect() end)
            AnimationChanger.characterAddedConnection = nil
        end
        AnimationChanger.character = nil
        AnimationChanger.humanoid = nil
        AnimationChanger.animator = nil
    end

    local animationDropdown = S.PlopSpoofer.createDropdown("Animation Changer", function()
        local presets = AnimationChanger.scanPresets()
        local options = {"Original"}
        for name in pairs(presets) do table.insert(options, name) end
        return options
    end, "Original", function(value)
        AnimationChanger.setPreset(value)
    end)

    S.PlopSpoofer.createButton("Use Original Animations", function()
        AnimationChanger.setPreset("Original")
        if animationDropdown then animationDropdown.Text = "Animation Changer: Original  ▾" end
    end)

    S.PlopSpoofer.createButton("Refresh Animation List", function()
        local previousSelection = AnimationChanger.selected
        local presets = AnimationChanger.scanPresets(true)
        if previousSelection ~= "Original" and not presets[previousSelection] then
            AnimationChanger.setPreset("Original")
        end
        warn("[E1LU4SAKEN / Animation Changer] Animation preset list refreshed. Reopen the dropdown to see updated entries.")
    end)

    AnimationChanger.characterAddedConnection = S.lp.CharacterAdded:Connect(function(character)
        task.delay(0.35, function()
            if S.lp.Character == character and S.screenGui and S.screenGui.Parent then
                bindCharacter(character)
            end
        end)
    end)
    if S.lp.Character then
        task.defer(function() bindCharacter(S.lp.Character) end)
    end
end

