    -- Render chevrons with small UI strokes instead of Unicode glyphs; this avoids
    -- missing-glyph squares on executors/fonts that do not include ⌄ / ⌃.
    local function createWideChevron(parent, name, armLength, color, initialDirection, alignSide)
        local holder = Instance.new("Frame")
        holder.Name = name
        holder.AnchorPoint = Vector2.new(0.5, 0.5)
        holder.Position = alignSide == "left"
            and UDim2.new(0, 18, 0.5, 0)
            or UDim2.new(1, -18, 0.5, 0)
        holder.Size = UDim2.new(0, armLength * 2 + 4, 0, 18)
        holder.BackgroundTransparency = 1
        holder.BorderSizePixel = 0
        holder.Parent = parent

        local leftArm = Instance.new("Frame")
        leftArm.Name = "LeftStroke"
        leftArm.AnchorPoint = Vector2.new(0.5, 0.5)
        leftArm.Size = UDim2.new(0, armLength, 0, 2)
        leftArm.BackgroundColor3 = color
        leftArm.BorderSizePixel = 0
        leftArm.Parent = holder

        local rightArm = Instance.new("Frame")
        rightArm.Name = "RightStroke"
        rightArm.AnchorPoint = Vector2.new(0.5, 0.5)
        rightArm.Size = UDim2.new(0, armLength, 0, 2)
        rightArm.BackgroundColor3 = color
        rightArm.BorderSizePixel = 0
        rightArm.Parent = holder

        local function setDirection(direction)
            if direction == "up" or direction == "down" then
                local xOffset = armLength * 0.433
                leftArm.Position = UDim2.new(0.5, -xOffset, 0.5, 0)
                rightArm.Position = UDim2.new(0.5, xOffset, 0.5, 0)
                if direction == "down" then
                    leftArm.Rotation = 30
                    rightArm.Rotation = -30
                else
                    leftArm.Rotation = -30
                    rightArm.Rotation = 30
                end
            else -- right-pointing chevron for a collapsed sidebar section
                leftArm.Position = UDim2.new(0.5, -2, 0.5, -2.5)
                rightArm.Position = UDim2.new(0.5, -2, 0.5, 2.5)
                leftArm.Rotation = 45
                rightArm.Rotation = -45
            end
        end

        setDirection(initialDirection)
        return setDirection
    end

    local pages = {}
    S.pages = pages -- Expose the category pages for controls loaded after startup.

    -- Repaint section-card outlines after a page becomes visible. UIStroke on
    -- AutomaticSize cards can otherwise wait for a user scroll to redraw.
    local function refreshSectionOutlines(page)
        if not page then return end
        task.spawn(function()
            S.RunService.Heartbeat:Wait()
            local strokes = {}
            for _, object in ipairs(page:GetDescendants()) do
                if object:IsA("UIStroke") and object.Parent then
                    local parentName = object.Parent.Name
                    if parentName:sub(1, 12) == "SectionCard_"
                        or parentName:sub(1, 8) == "Foldout_" then
                        object.Enabled = false
                        table.insert(strokes, object)
                    end
                end
            end

            S.RunService.Heartbeat:Wait()
            for _, stroke in ipairs(strokes) do
                if stroke and stroke.Parent then
                    stroke.Enabled = true
                end
            end

            S.RunService.Heartbeat:Wait()
            if page.Parent then
                local oldPosition = page.CanvasPosition
                page.CanvasPosition = Vector2.new(oldPosition.X, oldPosition.Y + 1)
                page.CanvasPosition = oldPosition
            end
        end)
