        -- The public Discord invite endpoint provides approximate online/member counts.
        -- Counts stay as unavailable rather than displaying invented numbers if HTTP is blocked.
        local function formatDiscordCount(value)
            local number = tonumber(value)
            if not number then
                return nil
            end
            local reversed = tostring(math.floor(number)):reverse()
            local grouped = reversed:gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
            return grouped
        end

        local function fetchDiscordInviteCounts()
            local endpoint = "https://discord.com/api/v10/invites/arwDMGwj2V?with_counts=true"
            local responseBody
            local requestFunction
            if type(request) == "function" then
                requestFunction = request
            elseif type(http_request) == "function" then
                requestFunction = http_request
            elseif type(syn) == "table" and type(syn.request) == "function" then
                requestFunction = syn.request
            end

            if requestFunction then
                local requestOK, response = pcall(function()
                    return requestFunction({
                        Url = endpoint,
                        Method = "GET",
                        Headers = {Accept = "application/json"}
                    })
                end)
                if requestOK and type(response) == "table" then
                    responseBody = response.Body or response.body
                elseif requestOK and type(response) == "string" then
                    responseBody = response
                end
            end

            -- game:HttpGet is a fallback for executors that expose it.
            if type(responseBody) ~= "string" or responseBody == "" then
                local httpOK, body = pcall(function()
                    return game:HttpGet(endpoint)
                end)
                if httpOK and type(body) == "string" then
                    responseBody = body
                end
            end

            if type(responseBody) ~= "string" or responseBody == "" then
                return nil, nil
            end

            local decodeOK, inviteData = pcall(function()
                return game:GetService("HttpService"):JSONDecode(responseBody)
            end)
            if not decodeOK or type(inviteData) ~= "table" then
                return nil, nil
            end

            return formatDiscordCount(inviteData.approximate_presence_count),
                formatDiscordCount(inviteData.approximate_member_count)
        end

        local function updateDiscordStats()
            local onlineCount, memberCount = fetchDiscordInviteCounts()
            if not serverStats or not serverStats.Parent then
                return
            end
            if onlineCount and memberCount then
                serverStats.Text = onlineCount .. " Online  •  " .. memberCount .. " Members"
            else
                serverStats.Text = "Online / Members unavailable"
            end
        end

        task.spawn(function()
            repeat
                updateDiscordStats()
                task.wait(300)
            until not discordCard.Parent
        end)

        local inviteBar = Instance.new("TextButton")
