        local function openDiscordInvite()
            local url = "https://discord.gg/arwDMGwj2V"
            local opened = pcall(function()
                game:GetService("GuiService"):OpenBrowserWindow(url)
            end)
            -- Clipboard fallback is kept for executors that block browser opening.
            if not opened then
                pcall(function()
                    if type(setclipboard) == "function" then
                        setclipboard(url)
                    end
                end)
            end
        end

        local function copyDiscordInvite()
            local url = "https://discord.gg/arwDMGwj2V"
            local copied = false
            if type(setclipboard) == "function" then
                copied = pcall(function()
                    setclipboard(url)
                end)
            end
            -- If clipboard support is unavailable, still make the invite accessible.
            if not copied then
                pcall(function()
                    game:GetService("GuiService"):OpenBrowserWindow(url)
                end)
            end
        end

        -- Green button copies the invitation; clicking the rest of the card opens it.
        inviteBar.Activated:Connect(copyDiscordInvite)
        discordCard.Activated:Connect(openDiscordInvite)
