    local pageColumns = {}

    local function estimateColumnHeight(object, depth)
        if not object or not object:IsA("GuiObject") then return 0 end
        depth = depth or 0
        if depth > 7 then return math.max(object.Size.Y.Offset, 12) end
        if not object.Visible then return 0 end

        local height = object.Size.Y.Offset
        if object.AutomaticSize == Enum.AutomaticSize.Y or height <= 0 then
            local contentHeight = 0
            for _, nested in ipairs(object:GetChildren()) do
                if nested:IsA("GuiObject") and nested.Visible then
                    contentHeight = contentHeight + estimateColumnHeight(nested, depth + 1) + 4
                end
            end
            if contentHeight > 0 then return contentHeight end
            return math.max(height, 32)
        end
        return height
    end

