    local function readControlLabel(child)
        if not child:IsA("GuiObject") then return nil end
        if child.Name == "NumericControlContainer" or child.Name == "PlopSpooferInput" then
            for _, item in ipairs(child:GetChildren()) do
                if item:IsA("TextLabel") then
                    return string.upper((item.Text or ""):gsub("%s+", " "))
                end
            end
        end
        -- The 007N7 selector in this hub is a plain TextButton rather than a
        -- dropdown container, so normalize its visible text before the colon.
        if child.Name == "AutoUndetectAbilitySelector" then
            return "007N7 ABILITY"
        end
        local label = child:FindFirstChild("Label")
        if label and label:IsA("TextLabel") then
            return string.upper((label.Text or ""):gsub("%s+", " "))
        end
        if child:IsA("TextButton") and child.Text then
            local firstPart = tostring(child.Text):match("^%s*([^:]+)")
            if firstPart then
                return string.upper((firstPart:gsub("%s+", " ")):gsub("%s+$", ""))
            end
        end
        return nil
    end

    -- Keep character-specific automation controls on their original character pages.
    local autoBlockV2Page = pages["Auto Block"]
    if autoBlockV2Page then
        for _, child in ipairs(autoBlockV2Page:GetChildren()) do
            local label = readControlLabel(child)
            if label == "AUTO CLONE 007N7" then
                child.Parent = pages.Survivor
            end
        end
    end

    local function rebuildFoldoutPage(page, groupOrder, controlToGroup, isKillerPage)
        if not page then return end
        local bodies = {}
        for index, groupName in ipairs(groupOrder) do
            bodies[groupName] = makeFoldout(page, groupName, isKillerPage and (1000 + index) or index)
        end
        local childSnapshot = page:GetChildren()
        local groupOrders = {}
        for _, child in ipairs(childSnapshot) do
            if child:IsA("UIListLayout") or child:IsA("UIPadding") then
                -- Keep the page's own layout objects untouched.
            elseif child.Name == "SectionHeader" then
                child:Destroy()
            elseif child:IsA("GuiObject") then
                local text = readControlLabel(child)
                local groupName = text and controlToGroup[text]
                if isKillerPage and text == "AUTO M1" then
                    child.LayoutOrder = 1
                elseif groupName and bodies[groupName] then
                    child.Parent = bodies[groupName]
                    groupOrders[groupName] = (groupOrders[groupName] or 0) + 1
                    child.LayoutOrder = groupOrders[groupName]
                end
            end
        end
        if isKillerPage then
            local preferredOrders = {
                ["AUTO M1"] = 1,
                ["ENABLE ANTI-BACKSTAB"] = 2,
                ["ANTI-BACKSTAB DETECTION RANGE"] = 3,
                ["ANTI-BACKSTAB LOOK DURATION (S)"] = 4,
                ["ENABLE AIMBOT"] = 5,
                ["AIMBOT COOLDOWN (S)"] = 6,
                ["AIMBOT LOCK TIME (S)"] = 7,
                ["AIMBOT MAX DISTANCE"] = 8,
                ["AIMBOT ROTATION SMOOTHING"] = 9,
            }
            local fallbackOrder = 100
            for _, child in ipairs(page:GetChildren()) do
                if child:IsA("GuiObject") and not child.Name:match("^Foldout_") then
                    local label = readControlLabel(child)
                    local preferredOrder = label and preferredOrders[label]
                    if preferredOrder then
                        child.LayoutOrder = preferredOrder
                    else
                        fallbackOrder += 1
                        child.LayoutOrder = fallbackOrder
                    end
                end
            end
        end
    end

    rebuildFoldoutPage(pages.Survivor, {"Chance", "Auto undetect", "Guest1337", "Shedletsky", "Veeronica", "Dusekkar", "Eliot", "007n7", "Jane Doe"}, {
        ["CHANCE AIMBOT"] = "Chance",
        ["AUTO CHANCE COINFLIP"] = "Chance",
        ["PREDICTION"] = "Chance",
        ["CHANCE SHOOT 360 SPIN"] = "Chance",
        ["007N7 ABILITY"] = "Auto undetect",
        ["LMS AUTO ABILITY"] = "Auto undetect",
        ["AUTO INVIS WHEN ABILITY (RAGE)"] = "Auto undetect",
        ["GUEST1337 BLOCK ANIMATION"] = "Guest1337",
        ["GUEST1337 CHARGE ANTI-CRASH"] = "Guest1337",
        ["GUEST1337 CHARGE TURN CONTROL"] = "Guest1337",
        ["GUEST1337 CHARGE PILOT"] = "Guest1337",
        ["GUEST1337 CHARGE NOCLIP"] = "Guest1337",
        ["GUEST1337 SUPER PUNCH"] = "Guest1337",
        ["GUEST1337 SUPER PUNCH POWER (5-40)"] = "Guest1337",
        ["SHEDLETSKY AIMBOT"] = "Shedletsky",
        ["AUTO SLASH"] = "Shedletsky",
        ["AUTO SLASH DELAY"] = "Shedletsky",
        ["AUTO SLASH DISTANCE (STUDS)"] = "Shedletsky",
        ["TP SLASH (TELEPORT BEHIND)"] = "Shedletsky",
        ["TP BEHIND DISTANCE"] = "Shedletsky",
        ["VEERONICA AUTO TRICK"] = "Veeronica",
        ["VEERONICA FREE MOVE"] = "Veeronica",
        ["DISABLE VEERONICA'S COLLISION DAMAGE"] = "Veeronica",
        ["DUSEKKAR SILENT AIM"] = "Dusekkar",
        ["DUSEKKAR TARGET SURVIVOR"] = "Dusekkar",
        ["DUSEKKAR ANTI PROTECTION BREAK"] = "Dusekkar",
        ["DUSEKKAR PROTECTION THROUGH WALLS"] = "Dusekkar",
        ["ELIOT THROW PIZZA AIMBOT"] = "Eliot",
        ["AUTO CLONE 007N7"] = "007n7",
        ["007N7 CLONE FOLLOW / BODYBLOCK"] = "007n7",
        ["007N7 CLONE FOLLOW MODE"] = "007n7",
        ["007N7 CLONE FOLLOW TARGET"] = "007n7",
        ["007N7 CLONE FOLLOW PREDICTION (0-30)"] = "007n7",
        ["007N7 CLONE FOLLOW DISTANCE (0-14)"] = "007n7",
        ["007N7 TROLL C00LGUI"] = "007n7",
        ["007N7 CANCELLABLE C00LGUI"] = "007n7",
        ["JANE DOE AUTO HATCHET"] = "Jane Doe",
        ["JANE DOE AIMBOT"] = "Jane Doe",
        ["JANE DOE INSTANT THROW CRYSTAL"] = "Jane Doe",
        ["JANE DOE INFINITE CRYSTAL HOLD"] = "Jane Doe",
        ["JANE DOE AXE LOCK-ON"] = "Jane Doe",
    }, false)

    rebuildFoldoutPage(pages.Killer, {"Auto Dodge", "Azure", "Slasher", "C00lkidd", "1x1x1", "Noli", "Nosferatu", "Sixer", "John Doe"}, {
        ["AUTO RAGING PACE / 404"] = "Auto Dodge",
        ["DODGE RADIUS"] = "Auto Dodge",
        ["AUTO TRAP MINIGAME"] = "Azure",
        ["AZURE INFINITE ATTEMPTS"] = "Azure",
        ["QTE METHOD"] = "Azure",
        ["AIM ON TENTACLES (GRAB)"] = "Azure",
        ["AIM ON UNEARTHING (GOLEM ONLY)"] = "Azure",
        ["CUSTOM RAGING PACE SPEED"] = "Slasher",
        ["RAGING PACE SPEED MULTIPLIER"] = "Slasher",
        ["C00LKIDD CORRUPT NATURE SILENT AIM"] = "C00lkidd",
        ["MAKE C00LKIDD'S DASH CONTROLLABLE"] = "C00lkidd",
        ["MASS INFECTION AIMBOT"] = "1x1x1",
        ["ENTANGLEMENT AIMBOT"] = "1x1x1",
        ["NOLI RUSH AUTO TARGET"] = "Noli",
        ["NOLI RUSH ANTI CRASH"] = "Noli",
        ["NOLI VOID STAR SILENT AIM"] = "Noli",
        ["BETTER VOID RUSH"] = "Noli",
        ["NOSFERATU AUTO HOOK MINIGAME"] = "Nosferatu",
        ["NOSFERATU HOOK COOLDOWN"] = "Nosferatu",
        ["NOSFERATU UNLIMITED FLY"] = "Nosferatu",
        ["NOSFERATU DIVE CONTROL"] = "Nosferatu",
        ["NOSFERATU CATACLYSM CONTROL"] = "Nosferatu",
        ["NOSFERATU DIVE AIMBOT"] = "Nosferatu",
        ["NOSFERATU BLOOD HOOK AIMBOT"] = "Nosferatu",
        ["NOSFERATU INFINITE HITBOX TRAIL"] = "Nosferatu",
        ["ENABLE BATS AIM ASSIST"] = "Nosferatu",
        ["BATS PREDICTION (S)"] = "Nosferatu",
        ["BATS DEPTH OFFSET"] = "Nosferatu",
        ["BATS MAX DISTANCE"] = "Nosferatu",
        ["SIXER INFERNAL CRY AIMBOT"] = "Sixer",
        ["SIXER DEMONIC PURSUIT NOCLIP"] = "Sixer",
        ["SIXER DEMONIC PURSUIT ANTI-CRASH"] = "Sixer",
        ["SIXER DEMONIC PURSUIT INFINITE HITBOX TRAIL"] = "Sixer",
        ["JOHN DOE CORRUPT ENERGY AIMBOT"] = "John Doe",
    }, true)

    -- Keep Azure controls in the same order as the source's Killer page.
    local azureFoldout = pages.Killer and pages.Killer:FindFirstChild("Foldout_Azure")
    local azureBody = azureFoldout and azureFoldout:FindFirstChild("FoldoutContents")
    if azureBody then
        local azureOrders = {
            ["AUTO TRAP MINIGAME"] = 1,
            ["QTE METHOD"] = 2,
            ["AZURE INFINITE ATTEMPTS"] = 3,
            ["AIM ON TENTACLES (GRAB)"] = 4,
            ["AIM ON UNEARTHING (GOLEM ONLY)"] = 5,
        }
        for _, child in ipairs(azureBody:GetChildren()) do
            local label = readControlLabel(child)
            if label and azureOrders[label] then
                child.LayoutOrder = azureOrders[label]
            end
        end
    end

    for pageName, page in pairs(pages) do
        if pageName ~= "Info" then
            local pageLayout = page:FindFirstChildOfClass("UIListLayout")
            if pageLayout then
                pageLayout.FillDirection = Enum.FillDirection.Horizontal
                pageLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
                pageLayout.VerticalAlignment = Enum.VerticalAlignment.Top
                pageLayout.Padding = UDim.new(0, 12)
            end

            -- Sort a snapshot before moving items; ties keep the original order.
            local orderedItems = {}
            for originalIndex, child in ipairs(page:GetChildren()) do
                if child:IsA("GuiObject") then
                    table.insert(orderedItems, {
                        object = child,
                        layoutOrder = child.LayoutOrder,
                        originalIndex = originalIndex,
                    })
                end
            end
            table.sort(orderedItems, function(a, b)
                if a.layoutOrder == b.layoutOrder then
                    return a.originalIndex < b.originalIndex
                end
                return a.layoutOrder < b.layoutOrder
            end)

            -- For ordinary pages, controls between two headings stay together.
            -- Unheaded controls get a clear GENERAL card instead of floating alone.
            if pageName ~= "Survivor" and pageName ~= "Killer" then
                local createdCards = {}
                local activeCard = nil
                local activeContents = nil
                local sectionIndex = 0
                local function beginGroup(titleText, layoutOrder)
                    sectionIndex = sectionIndex + 1
                    activeCard, activeContents = makeSectionCard(page, titleText, layoutOrder or sectionIndex)
                    table.insert(createdCards, activeCard)
                end

                for _, entry in ipairs(orderedItems) do
                    local child = entry.object
                    if child and child.Parent == page then
                        if child.Name == "SectionHeader" then
                            local titleText = tostring(child.Text or "SECTION")
                            child:Destroy()
                            beginGroup(titleText, entry.layoutOrder)
                        else
                            if not activeContents then
                                beginGroup("GENERAL", entry.layoutOrder)
                            end
                            child.Parent = activeContents
                            child.LayoutOrder = (#activeContents:GetChildren())
                        end
                    end
                end
            else
                -- Survivor/Killer controls use the explicit collapsible character groups.
                -- Unassigned Survivor controls stay on the page; they are never folded into Jane Doe.
                local activeContents = nil
                local groupIndex = 0
                local function beginRoleGroup(titleText, layoutOrder)
                    groupIndex = groupIndex + 1
                    local _, contents = makeSectionCard(page, titleText, layoutOrder or groupIndex)
                    activeContents = contents
                end
                for _, entry in ipairs(orderedItems) do
                    local child = entry.object
                    if child and child.Parent == page and child.Name ~= "ColumnLeft" and child.Name ~= "ColumnRight" then
                        if child.Name:match("^Foldout_") then
                            -- Existing foldouts retain their own card.
                        elseif child.Name == "SectionHeader" then
                            local headerText = tostring(child.Text or "SECTION")
                            child:Destroy()
                            local normalized = headerText:upper():gsub("%s+", " ")
                            if pageName == "Survivor" and (normalized == "JANE DOE" or normalized == "JANE DOE SURVIVOR") then
                                -- Jane Doe already has its collapsible Foldout_Jane Doe group.
                                -- Do not recreate a second, arrowless Jane Doe card.
                                activeContents = nil
                            else
                                beginRoleGroup(headerText, entry.layoutOrder)
                            end
                        else
                            if not activeContents and pageName ~= "Survivor" then
                                beginRoleGroup("GENERAL", entry.layoutOrder)
                            end
                            if activeContents then
                                child.Parent = activeContents
                                child.LayoutOrder = #activeContents:GetChildren()
                            else
                                -- Survivor has explicit collapsible character groups.
                                -- Never create a second, non-collapsible Jane Doe card
                                -- for controls whose label has not been mapped yet.
                                child.LayoutOrder = entry.layoutOrder
                            end
                        end
                    end
                end
            end

            -- Force FOV RING COLOR to sit immediately after FOV RING SIZE.
            -- Both controls stay inside the same Auto Punch section card; this
            -- stable re-order runs after section grouping and before column layout.
            do
                local sizeRow = S.punchFOVRingSizeContainer
                local colorRow = S.punchFOVColorControlHolder
                if sizeRow and colorRow and sizeRow.Parent then
                    local sectionContents = sizeRow.Parent
                    if colorRow.Parent ~= sectionContents then
                        colorRow.Parent = sectionContents
                    end

                    local orderedRows = {}
                    for originalIndex, child in ipairs(sectionContents:GetChildren()) do
                        if child:IsA("GuiObject") then
                            table.insert(orderedRows, {
                                object = child,
                                layoutOrder = child.LayoutOrder,
                                originalIndex = originalIndex,
                            })
                        end
                    end
                    table.sort(orderedRows, function(a, b)
                        if a.layoutOrder == b.layoutOrder then
                            return a.originalIndex < b.originalIndex
                        end
                        return a.layoutOrder < b.layoutOrder
                    end)

                    local rows = {}
                    for _, entry in ipairs(orderedRows) do
                        if entry.object ~= colorRow then
                            table.insert(rows, entry.object)
                        end
                    end
                    local sizeIndex = nil
                    for index, row in ipairs(rows) do
                        if row == sizeRow then
                            sizeIndex = index
                            break
                        end
                    end
                    if sizeIndex then
                        table.insert(rows, sizeIndex + 1, colorRow)
                        for index, row in ipairs(rows) do
                            row.LayoutOrder = index
                        end
                    end
                end
            end

            -- All section cards now sit at the page level. Split those cards into
            -- columns based on accumulated visual height, keeping each card intact.
            local columns = {}
            local columnHeights = {0, 0}
            for columnIndex = 1, 2 do
                local column = Instance.new("Frame")
                column.Name = columnIndex == 1 and "ColumnLeft" or "ColumnRight"
                column.Size = UDim2.new(0.5, -6, 0, 0)
                column.AutomaticSize = Enum.AutomaticSize.Y
                column.BackgroundTransparency = 1
                column.BorderSizePixel = 0
                column.LayoutOrder = columnIndex - 1
                column.Parent = page

                local columnLayout = Instance.new("UIListLayout")
                columnLayout.SortOrder = Enum.SortOrder.LayoutOrder
                columnLayout.FillDirection = Enum.FillDirection.Vertical
                columnLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
                columnLayout.VerticalAlignment = Enum.VerticalAlignment.Top
                columnLayout.Padding = UDim.new(0, 8)
                columnLayout.Parent = column
                columns[columnIndex] = column
            end

            local cards = {}
            for originalIndex, child in ipairs(page:GetChildren()) do
                if child:IsA("GuiObject") and child ~= columns[1] and child ~= columns[2] then
                    table.insert(cards, {
                        object = child,
                        layoutOrder = child.LayoutOrder,
                        originalIndex = originalIndex,
                    })
                end
            end
            table.sort(cards, function(a, b)
                if a.layoutOrder == b.layoutOrder then return a.originalIndex < b.originalIndex end
                return a.layoutOrder < b.layoutOrder
            end)

            for _, entry in ipairs(cards) do
                local child = entry.object
                if child and child.Parent == page then
                    local columnIndex = columnHeights[1] <= columnHeights[2] and 1 or 2
                    child.Parent = columns[columnIndex]
                    child.LayoutOrder = math.floor(columnHeights[columnIndex]) + entry.originalIndex
                    columnHeights[columnIndex] = columnHeights[columnIndex]
                        + estimateColumnHeight(child) + 8
                end
            end

            pageColumns[page] = {
                columns = columns,
                heights = columnHeights,
            }

            -- Route controls added later (font/config/remove controls) into the
            -- shorter column so runtime additions remain visible and don't overlap.
            page.ChildAdded:Connect(function(child)
                if not child:IsA("GuiObject") or child.Name == "ColumnLeft" or child.Name == "ColumnRight" then
                    return
                end
                task.defer(function()
                    local state = pageColumns[page]
                    if not state or not child.Parent or child.Parent ~= page then return end
                    local columnIndex = state.heights[1] <= state.heights[2] and 1 or 2
                    child.Parent = state.columns[columnIndex]
                    state.heights[columnIndex] = state.heights[columnIndex]
                        + estimateColumnHeight(child) + 8
                end)
            end)
        end
    end


    -- ESP layout is intentional rather than height-balanced: all ESP feature cards
    -- stay in the left column, while ESP COLORS and FULLBRIGHT are stacked on the right.
    do
        local espPage = pages.ESP
        local espState = espPage and pageColumns[espPage]
        if espPage and espState and espState.columns then
            local leftColumn = espState.columns[1]
            local rightColumn = espState.columns[2]
            local allCards = {}
            for _, column in ipairs({leftColumn, rightColumn}) do
                for _, child in ipairs(column:GetChildren()) do
                    if child:IsA("GuiObject") and child.Name:match("^SectionCard_") then
                        table.insert(allCards, child)
                    end
                end
            end

            -- Keep the core player / object ESP groups together first, followed
            -- by the standalone special-purpose ESP sections.
            local espLeftOrder = {
                SectionCard_KILLERESP = 1,
                SectionCard_SURVIVORESP = 2,
                SectionCard_TEXTESP = 3,
                SectionCard_GENERATORESP = 4,
                SectionCard_ITEMESP = 5,
                SectionCard_ESP = 6,
                SectionCard_FOLDERANDRINGESP = 7,
                SectionCard_JDDIGITALFOOTPRINTSESP = 8,
                SectionCard_AZURETRAPESP = 9,
            }
            local extras = {}
            for _, card in ipairs(allCards) do
                if card.Name == "SectionCard_ESPCOLORS" then
                    card.Parent = rightColumn
                    card.LayoutOrder = 1
                elseif card.Name == "SectionCard_FULLBRIGHT" then
                    card.Parent = rightColumn
                    card.LayoutOrder = 2
                else
                    card.Parent = leftColumn
                    table.insert(extras, card)
                end
            end

            table.sort(extras, function(a, b)
                local aOrder = espLeftOrder[a.Name] or (1000 + (tonumber(a.LayoutOrder) or 0))
                local bOrder = espLeftOrder[b.Name] or (1000 + (tonumber(b.LayoutOrder) or 0))
                if aOrder == bOrder then return a.Name < b.Name end
                return aOrder < bOrder
            end)
            for index, card in ipairs(extras) do
                card.LayoutOrder = espLeftOrder[card.Name] or (100 + index)
            end
        end
    end

    -- Auto Block layout: keep the main controls and hotkey group together on
    -- the left, and place the Hitbox / related action groups on the right.
    -- The large AUTO BLOCK and HITBOX cards therefore occupy opposite columns.
    do
        local autoBlockPage = pages["Auto Block"]
        local autoBlockState = autoBlockPage and pageColumns[autoBlockPage]
        if autoBlockPage and autoBlockState and autoBlockState.columns then
            local leftColumn = autoBlockState.columns[1]
            local rightColumn = autoBlockState.columns[2]
            local placement = {
                SectionCard_AUTOBLOCK = {column = leftColumn, order = 1},
                SectionCard_TOGGLE = {column = leftColumn, order = 2},
                SectionCard_AUTOPUNCH = {column = leftColumn, order = 3},
                SectionCard_HITBOX = {column = rightColumn, order = 1},
                SectionCard_HITBOXDRAG = {column = rightColumn, order = 2},
                SectionCard_ANTIBAIT = {column = rightColumn, order = 3},
            }

            local autoBlockCards = {}
            for _, column in ipairs({leftColumn, rightColumn}) do
                for _, child in ipairs(column:GetChildren()) do
                    if child:IsA("GuiObject") and child.Name:match("^SectionCard_") then
                        table.insert(autoBlockCards, child)
                    end
                end
            end

            for _, card in ipairs(autoBlockCards) do
                local target = placement[card.Name]
                if target and target.column then
                    card.Parent = target.column
                    card.LayoutOrder = target.order * 10
                end
            end
        end
    end

    -- Fix delayed section-outline rendering on initial page load. On some Roblox
    -- clients, UIStroke on AutomaticSize cards does not repaint until scrolling
    -- invalidates the ScrollingFrame canvas. Wait for layout, refresh the strokes,
    -- then nudge each page's canvas by one pixel and restore it without user input.
    task.spawn(function()
        S.RunService.Heartbeat:Wait()
        S.RunService.Heartbeat:Wait()

        local outlineStrokes = {}
        for _, page in pairs(pages) do
            if page and page.Parent then
                for _, object in ipairs(page:GetDescendants()) do
                    if object:IsA("UIStroke") and object.Parent then
                        local parentName = object.Parent.Name
                        if parentName:sub(1, 12) == "SectionCard_"
                            or parentName:sub(1, 8) == "Foldout_" then
                            object.Enabled = false
                            table.insert(outlineStrokes, object)
                        end
                    end
                end
            end
        end

        S.RunService.Heartbeat:Wait()
        for _, stroke in ipairs(outlineStrokes) do
            if stroke and stroke.Parent then
                stroke.Enabled = true
            end
        end

        S.RunService.Heartbeat:Wait()
        for _, page in pairs(pages) do
            if page and page.Parent then
                local oldPosition = page.CanvasPosition
                page.CanvasPosition = Vector2.new(oldPosition.X, oldPosition.Y + 1)
                page.CanvasPosition = oldPosition
            end
        end
    end)

    -- Shared right-side dropdowns: use the same left-chevron row and floating
    -- option list as Skin Changer for Device, Auto Block Detection, Aim Mode,
    -- and Stamina Preset. The chosen value is stored independently of popup state.
    S.rightDropdownUI = S.rightDropdownUI or {activePopup = nil, controls = setmetatable({}, {__mode = "k"})}

    S.__helpers.closeRightDropdownPopup = function()
        local state = S.rightDropdownUI
        if state and state.activePopup then
            pcall(function() state.activePopup:Destroy() end)
            state.activePopup = nil
        end
    end

    S.__helpers.refreshRightDropdownButton = function(button)
        local state = S.rightDropdownUI
        local control = state and state.controls and state.controls[button]
        if not control or not control.valueLabel or not control.valueLabel.Parent then return end
        local ok, current = pcall(control.getValue)
        if ok then
            control.valueLabel.Text = tostring(current or "None")

            -- Game Font selector preview: only the selected font-name label
            -- uses the chosen font. The row title and the rest of the hub UI
            -- keep their existing fonts and layout.
            if button == S.gameFontButton then
                local selectedFontName = tostring(current or S.currentGameFontName or "FredokaOne")
                local selectedFont = Enum.Font[selectedFontName]
                if selectedFont then
                    pcall(function() control.valueLabel.Font = selectedFont end)
                    pcall(function() control.valueLabel.FontFace = Font.fromEnum(selectedFont) end)
                end
            end
        end
    end

    S.__helpers.attachRightDropdownButton = function(button, titleText, options, getValue, setValue)
        if not button or not button.Parent then return false end
        if (type(options) ~= "table" and type(options) ~= "function")
            or type(getValue) ~= "function" or type(setValue) ~= "function" then
            return false
        end

        button:SetAttribute("E1LU4HUB_PopupOpener", true)
        button.Size = UDim2.new(0.92, 0, 0, 32)
        button.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
        button.BackgroundTransparency = 0
        button.BorderSizePixel = 0
        button.AutoButtonColor = true
        button.Text = ""
        button.ClipsDescendants = false
        button.ZIndex = 2

        for _, oldName in ipairs({"RightDropdownArrow", "RightDropdownTitle", "RightDropdownValue", "RightDropdownOutline"}) do
            local old = button:FindFirstChild(oldName)
            if old then old:Destroy() end
        end
        -- Remove legacy text padding so the custom left-chevron layout aligns identically on all four rows.
        for _, child in ipairs(button:GetChildren()) do
            if child:IsA("UIPadding") then child:Destroy() end
        end

        local rowCorner = button:FindFirstChildOfClass("UICorner") or Instance.new("UICorner")
        rowCorner.CornerRadius = UDim.new(0, 4)
        rowCorner.Parent = button

        local rowStroke = button:FindFirstChildOfClass("UIStroke") or Instance.new("UIStroke")
        rowStroke.Name = "RightDropdownOutline"
        rowStroke.Color = Color3.fromRGB(58, 56, 66)
        rowStroke.Thickness = 1
        rowStroke.Transparency = 0
        rowStroke.Parent = button

        createWideChevron(
            button,
            "RightDropdownArrow",
            4,
            S.uiAccentColor or Color3.fromRGB(255, 255, 255),
            "right",
            "left"
        )
        local arrow = button:FindFirstChild("RightDropdownArrow")
        if arrow then
            arrow.ZIndex = 4
            for _, arm in ipairs(arrow:GetChildren()) do
                if arm:IsA("GuiObject") then
                    arm.ZIndex = 4
                    arm:SetAttribute("SkinChangerAccentFill", true)
                end
            end
        end

        local title = Instance.new("TextLabel")
        title.Name = "RightDropdownTitle"
        title.Position = UDim2.new(0, 31, 0, 0)
        title.Size = UDim2.new(0.46, -31, 1, 0)
        title.BackgroundTransparency = 1
        title.Text = tostring(titleText or "SELECT")
        title.TextColor3 = Color3.fromRGB(246, 245, 250)
        title.Font = Enum.Font.Gotham
        title.TextSize = 10
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextTruncate = Enum.TextTruncate.AtEnd
        title.ZIndex = 3
        title.Parent = button

        local valueLabel = Instance.new("TextLabel")
        valueLabel.Name = "RightDropdownValue"
        valueLabel.Position = UDim2.new(0.49, 0, 0, 0)
        valueLabel.Size = UDim2.new(0.48, -7, 1, 0)
        valueLabel.BackgroundTransparency = 1
        valueLabel.Text = ""
        valueLabel.TextColor3 = Color3.fromRGB(246, 245, 250)
        valueLabel.Font = Enum.Font.Gotham
        valueLabel.TextSize = 11
        valueLabel.TextXAlignment = Enum.TextXAlignment.Right
        valueLabel.TextTruncate = Enum.TextTruncate.AtEnd
        valueLabel.ZIndex = 3
        valueLabel.Parent = button

        local state = S.rightDropdownUI
        state.controls[button] = {
            title = title,
            valueLabel = valueLabel,
            options = options,
            getValue = getValue,
            setValue = setValue,
        }
        S.__helpers.refreshRightDropdownButton(button)

        local function showOptions()
            local active = S.rightDropdownUI.activePopup
            if active and active.Parent then
                if active:GetAttribute("AnchorButton") == button.Name then
                    S.__helpers.closeRightDropdownPopup()
                    return
                end
                S.__helpers.closeRightDropdownPopup()
            end

            local optionList = options
            if type(options) == "function" then
                local optionsOK, resolvedOptions = pcall(options)
                if not optionsOK or type(resolvedOptions) ~= "table" then return end
                optionList = resolvedOptions
            end
            local choiceCount = #optionList
            if choiceCount == 0 then return end
            local popupWidth = 208
            local camera = workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
            local desiredPopupHeight = 10 + choiceCount * 32 + math.max(0, choiceCount - 1) * 4
            -- Long menus scroll inside a bounded popup instead of extending off-screen.
            local popupHeight = math.min(desiredPopupHeight, math.max(56, viewport.Y - 16))
            local anchorPosition = button.AbsolutePosition
            local anchorSize = button.AbsoluteSize
            local popupX = anchorPosition.X + anchorSize.X + 7
            if popupX + popupWidth > viewport.X - 8 then
                popupX = math.max(8, anchorPosition.X - popupWidth - 7)
            end
            local popupY = math.clamp(anchorPosition.Y, 8, math.max(8, viewport.Y - popupHeight - 8))

            local popup = Instance.new("Frame")
            popup.Name = "E1LU4HUB_RightDropdownPopup"
            popup:SetAttribute("AnchorButton", button.Name)
            popup.Position = UDim2.fromOffset(popupX, popupY)
            popup.Size = UDim2.fromOffset(popupWidth, popupHeight)
            popup.BackgroundColor3 = (S.mainFrame and S.mainFrame.BackgroundColor3) or Color3.fromRGB(26, 25, 30)
            popup.BackgroundTransparency = (S.mainFrame and tonumber(S.mainFrame.BackgroundTransparency)) or 0.12
            popup.BorderSizePixel = 0
            popup.Active = true
            popup.ZIndex = 10000
            popup.Parent = S.screenGui
            S.rightDropdownUI.activePopup = popup

            local popupCorner = Instance.new("UICorner")
            popupCorner.CornerRadius = UDim.new(0, 6)
            popupCorner.Parent = popup
            local popupStroke = Instance.new("UIStroke")
            popupStroke.Color = Color3.fromRGB(58, 56, 66)
            popupStroke.Thickness = 1
            popupStroke.Transparency = 0
            popupStroke.Parent = popup

            -- The scrolling list must exist before option buttons are created.
            -- This was the missing object that previously left all four menus empty.
            local choiceScroll = Instance.new("ScrollingFrame")
            choiceScroll.Name = "ChoiceList"
            choiceScroll.Position = UDim2.fromOffset(5, 5)
            choiceScroll.Size = UDim2.new(1, -10, 1, -10)
            choiceScroll.BackgroundTransparency = 1
            choiceScroll.BorderSizePixel = 0
            choiceScroll.ScrollBarThickness = 3
            choiceScroll.ScrollBarImageColor3 = S.uiAccentColor or Color3.fromRGB(160, 130, 255)
            choiceScroll.ScrollBarImageTransparency = 0.15
            choiceScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
            choiceScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
            choiceScroll.ScrollingDirection = Enum.ScrollingDirection.Y
            choiceScroll.Active = true
            choiceScroll.ClipsDescendants = true
            choiceScroll.ZIndex = 10001
            choiceScroll.Parent = popup

            local list = Instance.new("UIListLayout")
            list.SortOrder = Enum.SortOrder.LayoutOrder
            list.Padding = UDim.new(0, 4)
            list.Parent = choiceScroll

            local currentValue = nil
            pcall(function() currentValue = getValue() end)
            for index, optionValue in ipairs(optionList) do
                local selected = tostring(currentValue) == tostring(optionValue)
                local option = Instance.new("TextButton")
                option.Name = "RightDropdownOption_" .. tostring(index)
                option.Size = UDim2.new(1, -5, 0, 32)
                option.BackgroundColor3 = selected
                    and (S.uiAccentColor or Color3.fromRGB(255, 255, 255))
                    or Color3.fromRGB(36, 35, 42)
                option.BackgroundTransparency = 0
                option.BorderSizePixel = 0
                option.AutoButtonColor = true
                option.Text = ""
                option.LayoutOrder = index
                option.ZIndex = 10002
                option.Parent = choiceScroll
                if selected then option:SetAttribute("SkinChangerAccentFill", true) end

                local optionCorner = Instance.new("UICorner")
                optionCorner.CornerRadius = UDim.new(0, 4)
                optionCorner.Parent = option

                local optionLabel = Instance.new("TextLabel")
                optionLabel.Name = "ChoiceLabel"
                optionLabel.Position = UDim2.new(0, 10, 0, 0)
                optionLabel.Size = UDim2.new(1, -38, 1, 0)
                optionLabel.BackgroundTransparency = 1
                optionLabel.Text = tostring(optionValue)
                optionLabel.TextColor3 = selected and Color3.fromRGB(26, 25, 30) or Color3.fromRGB(246, 245, 250)
                optionLabel.TextSize = 12
                optionLabel.Font = Enum.Font.Gotham
                optionLabel.TextXAlignment = Enum.TextXAlignment.Left
                optionLabel.ZIndex = 10003
                optionLabel.Parent = option

                if selected then
                    local check = Instance.new("TextLabel")
                    check.Name = "SelectedCheck"
                    check.AnchorPoint = Vector2.new(1, 0.5)
                    check.Position = UDim2.new(1, -9, 0.5, 0)
                    check.Size = UDim2.new(0, 16, 0, 18)
                    check.BackgroundTransparency = 1
                    check.Text = "✓"
                    check.TextColor3 = Color3.fromRGB(26, 25, 30)
                    check.TextSize = 14
                    check.Font = Enum.Font.GothamBold
                    check.ZIndex = 10003
                    check.Parent = option
                end

                option.Activated:Connect(function()
                    local ok, result = pcall(setValue, optionValue, true)
                    if not ok then
                        warn("[E1LU4HUB Dropdown] " .. tostring(result))
                    elseif result ~= false then
                        S.__helpers.refreshRightDropdownButton(button)
                    end
                    S.__helpers.closeRightDropdownPopup()
                end)
            end
        end

        S.__helpers.connect(button.Activated, showOptions)
        return true
    end

    -- Apply the shared chevron + right-side list to the four requested selectors.
    S.__helpers.attachRightDropdownButton(
        S.deviceSpoofButton,
        "DEVICE",
        S.deviceSpoofOptions,
        function() return S.deviceSpoofCurrent end,
        function(value) return S.__helpers.setDeviceSpoof(value) end
    )
    S.__helpers.attachRightDropdownButton(
        S.deviceSpoofClientButton,
        "CLIENT DEVICE",
        S.deviceSpoofClientOptions,
        function() return S.deviceSpoofClientCurrent end,
        function(value)
            if not table.find(S.deviceSpoofClientOptions, value) then return false end
            S.deviceSpoofClientCurrent = value
            return true
        end
    )
    S.__helpers.attachRightDropdownButton(
        S.autoBlockDetectionModeButton,
        "BLOCK DETECT",
        S.AUTO_BLOCK_DETECTION_MODES,
        function() return S.autoBlockDetectionMode end,
        function(value) return S.__helpers.setAutoBlockDetectionMode(value, true) end
    )
    S.__helpers.attachRightDropdownButton(
        S.antiBaitMethodButton,
        "ANTI BAIT MODE",
        {"Legit", "Blatant"},
        function() return S.antiBaitMethod end,
        function(value) return S.__helpers.setAntiBaitMethod(value) end
    )
    -- Keep Punch Aim Mode visibly grouped with the AUTO PUNCH controls above.
    S.__helpers.attachRightDropdownButton(
        S.punchAimbotModeButton,
        "PUNCH AIM MODE",
        {"Character", "Camera"},
        function() return S.punchAimbotMode end,
        function(value) return S.__helpers.setPunchAimbotMode(value) end
    )
    S.__helpers.attachRightDropdownButton(
        S.staminaPresetButton,
        "STAMINA PRESET",
        {"Original", "Realistic", "Semi-Realistic", "Infinite"},
        function() return S.staminaPreset end,
        function(value) S.__helpers.setStaminaPreset(value); return true end
    )

    local gameFontOptions = {}
    for _, fontItem in ipairs(Enum.Font:GetEnumItems()) do
        table.insert(gameFontOptions, fontItem.Name)
    end
    table.sort(gameFontOptions)
    S.__helpers.attachRightDropdownButton(
        S.gameFontButton,
        "GAME FONT",
        gameFontOptions,
        function() return S.currentGameFontName or "FredokaOne" end,
        function(value)
            if not S.__helpers.setSelectedGameFont then return false end
            return S.__helpers.setSelectedGameFont(value) == true
        end
    )

    S.__helpers.attachRightDropdownButton(
        S.autoUndetectAbilityButton,
        "007N7 ABILITY",
        {"Clone", "c00lgui"},
        function() return S.AutoUndetect.selected007Ability or "c00lgui" end,
        function(value)
            if value ~= "Clone" and value ~= "c00lgui" then return false end
            S.AutoUndetect.selected007Ability = value
            S.AutoUndetect.lmsTriggered = false
            S.AutoUndetect.nextAttemptAt = 0
            return true
        end
    )

    -- Standard single-select lists now use the same compact floating dropdown
    -- as Auto Block Detection. Audio and Animation selectors intentionally keep
    -- their existing searchable list UI so their larger catalogs remain easy to browse.
    for _, dropdownEntry in ipairs(S.plopSpooferDropdownRegistry or {}) do
        local button = dropdownEntry.button
        if not dropdownEntry.converted and button and button.Parent then
            local labelLower = tostring(dropdownEntry.label or ""):lower()
            local onAudioPage = pages.Audio and button:IsDescendantOf(pages.Audio)
            local onAnimationPage = pages.Animation and button:IsDescendantOf(pages.Animation)
            local isMediaOrAnimationSelector = labelLower:find("audio", 1, true)
                or labelLower:find("music", 1, true)
                or labelLower:find("lms", 1, true)
                or labelLower:find("track", 1, true)
                or labelLower:find("animation", 1, true)

            if not onAudioPage and not onAnimationPage and not isMediaOrAnimationSelector then
                local function getSortedOptions()
                    local ok, sourceOptions = pcall(dropdownEntry.getOptions)
                    if not ok or type(sourceOptions) ~= "table" then return {} end
                    local optionsCopy = {}
                    for _, option in ipairs(sourceOptions) do
                        table.insert(optionsCopy, option)
                    end
                    table.sort(optionsCopy, function(a, b)
                        return tostring(a):lower() < tostring(b):lower()
                    end)
                    return optionsCopy
                end

                if dropdownEntry.legacyConnection then
                    pcall(function() dropdownEntry.legacyConnection:Disconnect() end)
                    dropdownEntry.legacyConnection = nil
                end

                local attached = S.__helpers.attachRightDropdownButton(
                    button,
                    dropdownEntry.label,
                    getSortedOptions,
                    dropdownEntry.getValue,
                    function(value)
                        return dropdownEntry.setValue(value, true)
                    end
                )
                dropdownEntry.converted = attached == true
            end
        end
    end

    -- Preserve these choices in Config save/load alongside the existing dropdowns.
    table.insert(S.configDropdownRegistry, {
        button = S.deviceSpoofButton,
        label = "Device Spoofer",
        defaultValue = S.deviceSpoofCurrent,
        getValue = function() return S.deviceSpoofCurrent end,
        setValue = function(value) return S.__helpers.setDeviceSpoof(value) end,
    })
    table.insert(S.configDropdownRegistry, {
        button = S.deviceSpoofClientButton,
        label = "Client Device Spoofer",
        defaultValue = S.deviceSpoofClientCurrent,
        getValue = function() return S.deviceSpoofClientCurrent end,
        setValue = function(value)
            if not table.find(S.deviceSpoofClientOptions, value) then return false end
            S.deviceSpoofClientCurrent = value
            return true
        end,
    })
    table.insert(S.configDropdownRegistry, {
        button = S.staminaPresetButton,
        label = "Stamina Preset",
        defaultValue = "Original",
        getValue = function() return S.staminaPreset end,
        setValue = function(value) S.__helpers.setStaminaPreset(value); return true end,
    })
    table.insert(S.configDropdownRegistry, {
        button = S.gameFontButton,
        label = "Game Font",
        defaultValue = "FredokaOne",
        getValue = function() return S.currentGameFontName or "FredokaOne" end,
        setValue = function(value)
            if not S.__helpers.setSelectedGameFont then return false end
            return S.__helpers.setSelectedGameFont(value) == true
        end,
    })
    table.insert(S.configDropdownRegistry, {
        button = S.autoUndetectAbilityButton,
        label = "007n7 Ability",
        defaultValue = "c00lgui",
        getValue = function() return S.AutoUndetect.selected007Ability or "c00lgui" end,
        setValue = function(value)
            if value ~= "Clone" and value ~= "c00lgui" then return false end
            S.AutoUndetect.selected007Ability = value
            S.AutoUndetect.lmsTriggered = false
            S.AutoUndetect.nextAttemptAt = 0
            return true
        end,
    })

    -- Skin Changer is arranged as three separate cards:
    -- master switch on the left, Survivor skins below it, and Killer skins on the right.
    do
        local miscPage = pages["Skin Changer"]
        local miscColumns = miscPage and pageColumns[miscPage]
        local leftColumn = miscColumns and miscColumns.columns[1] or miscPage
        local rightColumn = miscColumns and miscColumns.columns[2] or miscPage

        -- Remove the single legacy Skin Changer card created from the old section header.
        local oldSkinSection = miscPage and miscPage:FindFirstChild("SectionCard_SKINCHANGER", true)
        if oldSkinSection then
            oldSkinSection:Destroy()
        end

        local skinEntryRegistry = {}
        local activeSkinPopup = nil
        local function closeSkinPopup()
            if activeSkinPopup then
                pcall(function() activeSkinPopup:Destroy() end)
                activeSkinPopup = nil
            end
        end
        S.__helpers.closeSkinChangerPopup = closeSkinPopup

        local function refreshSkinEntryLabels()
            for _, item in ipairs(skinEntryRegistry) do
                if item.label and item.label.Parent then
                    local currentKey = S.SkinChanger.selectedByCharacter[item.requiredCharacter]
                    local currentLabel = currentKey or "None"
                    if currentKey and item.choices then
                        for _, choice in ipairs(item.choices) do
                            if choice.key == currentKey then
                                currentLabel = choice.label
                                break
                            end
                        end
                    end
                    item.label.Text = item.characterName .. ": " .. currentLabel
                end
            end
        end

        -- Runtime application is deliberately separate from selection.
        -- Users can choose a skin while the master switch is OFF or while using
        -- a different character; it is applied only when both conditions match.
        local function applySelectedSkinForCurrentCharacter()
            if S.SkinChanger.enabled ~= true then
                return false, "disabled"
            end

            local character = S.lp and S.lp.Character
            if not character then
                return false, "no-character"
            end

            local selectedSkin = S.SkinChanger.selectedByCharacter[character.Name]
            if selectedSkin and S.SkinChanger.unlockAllAvailableSkins then
                pcall(S.SkinChanger.unlockAllAvailableSkins)
            end
            if selectedSkin == "Artist shedletsky" then
                pcall(S.SkinChanger.updateArtistShedletskyEquip)
            end
            if not selectedSkin then
                if S.SkinChanger.active then
                    pcall(S.SkinChanger.deactivate)
                end
                return false, "none"
            end

            local eligible = false
            local genericDefinition = S.SkinChanger.genericSkinDefinitions
                and S.SkinChanger.genericSkinDefinitions[selectedSkin]
            if genericDefinition then
                eligible = character.Name == genericDefinition.characterName
            elseif selectedSkin == "Admin Noli old" then
                eligible = character.Name == "Noli"
                    and S.__helpers.getLocalRole
                    and S.__helpers.getLocalRole() == "Killer"
                    and (character:GetAttribute("SkinName") or "") == ""
            elseif S.TwoTimeSkinChanger and S.TwoTimeSkinChanger.isSkin(selectedSkin) then
                eligible = S.TwoTimeSkinChanger.isLocalSurvivorTwoTime(character)
            elseif selectedSkin == "Kai 1337 Skin" then
                eligible = character.Name == "Guest1337"
            elseif selectedSkin == "Jason" then
                eligible = character.Name == "Slasher"
                    and (character:GetAttribute("SkinName") or "") == ""
            elseif selectedSkin == "Artist shedletsky" then
                eligible = S.SkinChanger.isDefaultShedletsky(character) == true
            end

            if not eligible then
                if S.SkinChanger.active then
                    pcall(S.SkinChanger.deactivate)
                end
                return false, "character-not-ready"
            end

            if S.SkinChanger.active == selectedSkin
                and S.SkinChanger.activeCharacter == character then
                return true, "already-applied"
            end

            local ok, result = pcall(S.SkinChanger.apply, selectedSkin)
            if not ok then
                warn("[E1LU4HUB Skin Changer] " .. tostring(result))
                return false, "apply-error"
            end
            if result == false or S.SkinChanger.active ~= selectedSkin then
                return false, "apply-failed"
            end
            return true, "applied"
        end
        S.SkinChanger.applySelectedForCurrentCharacter = applySelectedSkinForCurrentCharacter

        -- Retry only while the matching character is still loading. This keeps
        -- saved choices automatic without applying on the wrong character.
        local skinApplyRetryToken = 0
        local function queueApplySelectedSkin(character)
            skinApplyRetryToken += 1
            local thisToken = skinApplyRetryToken
            if not character then return end

            task.spawn(function()
                for _ = 1, 40 do
                    if thisToken ~= skinApplyRetryToken
                        or S.SkinChanger.enabled ~= true
                        or not S.lp
                        or S.lp.Character ~= character then
                        return
                    end

                    local selectedSkin = S.SkinChanger.selectedByCharacter[character.Name]
                    if not selectedSkin then
                        if S.SkinChanger.active then
                            pcall(S.SkinChanger.deactivate)
                        end
                        return
                    end

                    local hasBody = character:FindFirstChild("Head")
                        and (character:FindFirstChild("Torso") or character:FindFirstChild("UpperTorso"))
                        and character:FindFirstChildOfClass("Humanoid")
                    local mayTryApply = hasBody ~= nil and hasBody ~= false
                    local genericDefinition = S.SkinChanger.genericSkinDefinitions
                        and S.SkinChanger.genericSkinDefinitions[selectedSkin]

                    if genericDefinition then
                        if character.Name ~= genericDefinition.characterName then return end
                        mayTryApply = mayTryApply and character.Name == genericDefinition.characterName
                    elseif selectedSkin == "Admin Noli old" then
                        if character.Name ~= "Noli" then return end
                        mayTryApply = character:FindFirstChild("HumanoidRootPart") ~= nil
                            and character:FindFirstChildOfClass("Humanoid") ~= nil
                            and S.__helpers.getLocalRole
                            and S.__helpers.getLocalRole() == "Killer"
                            and (character:GetAttribute("SkinName") or "") == ""
                    elseif S.TwoTimeSkinChanger and S.TwoTimeSkinChanger.isSkin(selectedSkin) then
                        if character.Name ~= "TwoTime" then return end
                        mayTryApply = mayTryApply and S.TwoTimeSkinChanger.isLocalSurvivorTwoTime(character)
                    elseif selectedSkin == "Jason" then
                        if character.Name ~= "Slasher" or (character:GetAttribute("SkinName") or "") ~= "" then
                            return
                        end
                    elseif selectedSkin == "Artist shedletsky" then
                        if character.Name ~= "Shedletsky" then return end
                        local playersFolder = workspace:FindFirstChild("Players")
                        local spectating = playersFolder and playersFolder:FindFirstChild("Spectating")
                        if spectating and S.lp and spectating:FindFirstChild(S.lp.Name) then
                            return
                        end
                        local equipOK = S.SkinChanger.updateArtistShedletskyEquip
                            and S.SkinChanger.updateArtistShedletskyEquip()
                        if not equipOK then
                            mayTryApply = false
                        end
                        local playerData = S.lp and S.lp:FindFirstChild("PlayerData")
                        local equipped = playerData and playerData:FindFirstChild("Equipped")
                        local skins = equipped and equipped:FindFirstChild("Skins")
                        local equippedSkin = skins and skins:FindFirstChild("Shedletsky")
                        if equippedSkin then
                            local valueOK, value = pcall(function() return equippedSkin.Value end)
                            local artistName = S.SkinChanger.getArtistShedletskySkinName()
                            if valueOK and tostring(value or "") ~= ""
                                and tostring(value) ~= artistName then
                                mayTryApply = false
                            end
                        end
                        local mainUI = S.__helpers.getMainUI and S.__helpers.getMainUI()
                        local abilityContainer = mainUI and mainUI:FindFirstChild("AbilityContainer")
                        if not abilityContainer or not abilityContainer:FindFirstChild("Slash") then
                            mayTryApply = false
                        end
                    elseif selectedSkin == "Kai 1337 Skin" and character.Name ~= "Guest1337" then
                        return
                    end

                    if mayTryApply then
                        local ok, applied = pcall(applySelectedSkinForCurrentCharacter)
                        if ok and applied == true then
                            refreshSkinEntryLabels()
                            return
                        end
                        if not ok then
                            warn("[E1LU4HUB Skin Changer] " .. tostring(applied))
                        end
                        return
                    end
                    task.wait(0.25)
                end
            end)
        end

        -- First card: the master enable switch. Its state controls execution only;
        -- it never disables or clears the saved character selections.
        local masterCard, masterContents = makeSectionCard(leftColumn, "TOGGLE SKIN CHANGER", 1)
        masterCard.Name = "SectionCard_SKINCHANGER_MASTER"
        masterCard.Size = UDim2.new(0.98, 0, 0, 0)

        local skinEnabledButton = nil
        skinEnabledButton = S.__helpers.createCoolToggle(
            "Enable Skin Changer",
            S.SkinChanger.enabled == true,
            function(value)
                S.SkinChanger.enabled = value == true
                if not S.SkinChanger.enabled then
                    skinApplyRetryToken += 1
                    pcall(S.SkinChanger.deactivate)
                else
                    if S.SkinChanger.unlockAllAvailableSkins then
                        pcall(S.SkinChanger.unlockAllAvailableSkins)
                    end
                    local savedTwoTimeSkin = S.SkinChanger.selectedByCharacter["TwoTime"]
                    if S.TwoTimeSkinChanger and S.TwoTimeSkinChanger.isSkin(savedTwoTimeSkin) then
                        local equipOK, equipError = S.TwoTimeSkinChanger.equipSelectedSkin(savedTwoTimeSkin)
                        if not equipOK then
                            warn("[E1LU4HUB Skin Changer] Equip Skin failed: " .. tostring(equipError))
                        end
                    end
                    if S.SkinChanger.selectedByCharacter["Shedletsky"] == "Artist shedletsky" then
                        local equipOK, equipError = S.SkinChanger.updateArtistShedletskyEquip()
                        if not equipOK then
                            warn("[E1LU4HUB Skin Changer] Artist Shedletsky Equip Skin failed: " .. tostring(equipError))
                        end
                    end
                    for _, selectedKey in pairs(S.SkinChanger.selectedByCharacter or {}) do
                        if S.SkinChanger.genericSkinDefinitions
                            and S.SkinChanger.genericSkinDefinitions[selectedKey] then
                            local callOK, equipOK, equipError = pcall(S.SkinChanger.equipGenericSkin, selectedKey)
                            if not callOK or equipOK ~= true then
                                warn("[E1LU4HUB Skin Changer] Generic Equip Skin pending: " .. tostring(equipError or equipOK))
                            end
                        end
                    end
                    queueApplySelectedSkin(S.lp and S.lp.Character)
                end
                task.defer(refreshSkinEntryLabels)
            end
        )
        skinEnabledButton.Name = "SkinChangerEnabledToggle"
        skinEnabledButton.Parent = masterContents
        skinEnabledButton.Size = UDim2.new(0.92, 0, 0, 32)
        skinEnabledButton.LayoutOrder = 1
        skinEnabledButton.Visible = true

        -- The same two-stroke Chevron as the reference UI, scaled to the
        -- standard 32px E1LU4HUB control height.
        local function makeSkinFoldout(parent, labelText, order)
            local outer = Instance.new("Frame")
            outer.Name = "Foldout_Skin" .. labelText:gsub("%W+", "")
            outer.Size = UDim2.new(0.98, 0, 0, 0)
            outer.AutomaticSize = Enum.AutomaticSize.Y
            outer.BackgroundColor3 = Color3.fromRGB(31, 30, 36)
            outer.BackgroundTransparency = 0
            outer.BorderSizePixel = 0
            outer.LayoutOrder = order
            outer.Parent = parent

            local outerCorner = Instance.new("UICorner")
            outerCorner.CornerRadius = UDim.new(0, 7)
            outerCorner.Parent = outer
            local outerStroke = Instance.new("UIStroke")
            outerStroke.Color = Color3.fromRGB(58, 56, 66)
            outerStroke.Thickness = 1
            outerStroke.Parent = outer

            local outerPadding = Instance.new("UIPadding")
            outerPadding.PaddingTop = UDim.new(0, 5)
            outerPadding.PaddingBottom = UDim.new(0, 5)
            outerPadding.PaddingLeft = UDim.new(0, 6)
            outerPadding.PaddingRight = UDim.new(0, 6)
            outerPadding.Parent = outer

            local outerLayout = Instance.new("UIListLayout")
            outerLayout.SortOrder = Enum.SortOrder.LayoutOrder
            outerLayout.Padding = UDim.new(0, 4)
            outerLayout.Parent = outer

            local head = Instance.new("TextButton")
            head.Name = "FoldoutButton"
            head.Size = UDim2.new(1, 0, 0, 32)
            head.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
            head.BackgroundTransparency = 1
            head.BorderSizePixel = 0
            head.AutoButtonColor = false
