        -- The selector is parented to ScreenGui so it can extend to the right
        -- of a column without being clipped by the page's ScrollingFrame.
        local function showSkinPopup(anchorButton, characterName, requiredCharacter, skinKey, choiceLabel, choiceOptions)
            closeSkinPopup()

            local options = choiceOptions or {{key = skinKey, label = choiceLabel}}
            local popupWidth = 210
            local popupHeight = math.min(420, 14 + (#options + 1) * 36 + #options * 3)
            local camera = workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
            local anchorPosition = anchorButton.AbsolutePosition
            local anchorSize = anchorButton.AbsoluteSize
            local popupX = anchorPosition.X + anchorSize.X + 7
            if popupX + popupWidth > viewport.X - 10 then
                popupX = math.max(10, anchorPosition.X - popupWidth - 7)
            end
            local popupY = math.clamp(anchorPosition.Y, 10, math.max(10, viewport.Y - popupHeight - 10))

            local popup = Instance.new("Frame")
            popup.Name = "SkinChangerSelectionPopup"
            popup.Position = UDim2.fromOffset(popupX, popupY)
            popup.Size = UDim2.fromOffset(popupWidth, popupHeight)
            popup.BackgroundColor3 = (S.mainFrame and S.mainFrame.BackgroundColor3) or Color3.fromRGB(26, 25, 30)
            popup.BackgroundTransparency = (S.mainFrame and S.mainFrame.BackgroundTransparency) or 0.12
            popup.BorderSizePixel = 0
            popup.Active = true
            popup.ZIndex = 10000
            popup.Parent = S.screenGui
            activeSkinPopup = popup

            local popupCorner = Instance.new("UICorner")
            popupCorner.CornerRadius = UDim.new(0, 6)
            popupCorner.Parent = popup
            local popupStroke = Instance.new("UIStroke")
            popupStroke.Color = Color3.fromRGB(58, 56, 66)
            popupStroke.Thickness = 1
            popupStroke.Transparency = 0
            popupStroke.Parent = popup

            local popupPadding = Instance.new("UIPadding")
            popupPadding.PaddingTop = UDim.new(0, 5)
            popupPadding.PaddingBottom = UDim.new(0, 5)
            popupPadding.PaddingLeft = UDim.new(0, 5)
            popupPadding.PaddingRight = UDim.new(0, 5)
            popupPadding.Parent = popup

            local choiceScroll = Instance.new("ScrollingFrame")
            choiceScroll.Name = "ChoiceList"
            choiceScroll.Position = UDim2.fromOffset(5, 5)
            choiceScroll.Size = UDim2.new(1, -10, 1, -10)
            choiceScroll.BackgroundTransparency = 1
            choiceScroll.BorderSizePixel = 0
            choiceScroll.ScrollBarThickness = 3
            choiceScroll.ScrollBarImageColor3 = S.uiAccentColor or Color3.fromRGB(160, 130, 255)
            choiceScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
            choiceScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
            choiceScroll.ScrollingDirection = Enum.ScrollingDirection.Y
            choiceScroll.ZIndex = 10001
            choiceScroll.Parent = popup

            local optionLayout = Instance.new("UIListLayout")
            optionLayout.SortOrder = Enum.SortOrder.LayoutOrder
            optionLayout.Padding = UDim.new(0, 4)
            optionLayout.Parent = choiceScroll

            local function addChoice(labelText, choiceKey, isNone, order)
                local selectedKey = S.SkinChanger.selectedByCharacter[requiredCharacter]
                local selected = isNone and selectedKey == nil
                    or (not isNone and selectedKey == choiceKey)

                local option = Instance.new("TextButton")
                option.Name = isNone and "SkinChoice_None" or "SkinChoice_SelectedSkin"
                option.Size = UDim2.new(1, 0, 0, 32)
                option.BackgroundColor3 = selected
                    and (S.uiAccentColor or Color3.fromRGB(255, 255, 255))
                    or Color3.fromRGB(36, 35, 42)
                option.BackgroundTransparency = 0
                option.BorderSizePixel = 0
                option.AutoButtonColor = true
                option.Text = ""
                option.LayoutOrder = order
                option.ZIndex = 10001
                option.Parent = choiceScroll
                if selected then option:SetAttribute("SkinChangerAccentFill", true) end

                local optionCorner = Instance.new("UICorner")
                optionCorner.CornerRadius = UDim.new(0, 4)
                optionCorner.Parent = option

                local optionLabel = Instance.new("TextLabel")
                optionLabel.Name = "ChoiceLabel"
                optionLabel.Position = UDim2.new(0, 10, 0, 0)
                optionLabel.Size = UDim2.new(1, -38, 1, 0)
                optionLabel.BackgroundTransparency = 1
                optionLabel.Text = labelText
                optionLabel.TextColor3 = selected and Color3.fromRGB(26, 25, 30) or Color3.fromRGB(246, 245, 250)
                optionLabel.TextSize = 12
                optionLabel.Font = Enum.Font.Gotham
                optionLabel.TextXAlignment = Enum.TextXAlignment.Left
                optionLabel.ZIndex = 10002
                optionLabel.Parent = option

                if selected then
                    local check = Instance.new("TextLabel")
                    check.Name = "SelectedCheck"
                    check.AnchorPoint = Vector2.new(1, 0.5)
                    check.Position = UDim2.new(1, -9, 0.5, 0)
                    check.Size = UDim2.new(0, 16, 0, 18)
                    check.BackgroundTransparency = 1
                    check.Text = "✓"
                    check.TextColor3 = Color3.fromRGB(26, 25, 30)
                    check.TextSize = 14
                    check.Font = Enum.Font.GothamBold
                    check.ZIndex = 10002
                    check.Parent = option
                end

                option.Activated:Connect(function()
                    if isNone then
                        -- Clearing a preference is always allowed, even while disabled
                        -- or while the local player is using a different character.
                        local previousSelection = S.SkinChanger.selectedByCharacter[requiredCharacter]
                        S.SkinChanger.selectedByCharacter[requiredCharacter] = nil
                        local currentCharacter = S.lp and S.lp.Character
                        if currentCharacter and currentCharacter.Name == requiredCharacter then
                            skinApplyRetryToken += 1
                        end
                        if requiredCharacter == "TwoTime" then
                            -- Clear only TwoTime's model/equip state; do not deactivate
                            -- a different character's currently active Skin Changer.
                            if S.TwoTimeSkinChanger and S.TwoTimeSkinChanger.deactivate then
                                pcall(S.TwoTimeSkinChanger.deactivate)
                            end
                            if S.SkinChanger.active and S.TwoTimeSkinChanger
                                and S.TwoTimeSkinChanger.isSkin(S.SkinChanger.active) then
                                S.SkinChanger.active = nil
                                S.SkinChanger.activeCharacter = nil
                            end
                        elseif requiredCharacter == "Shedletsky" then
                            pcall(S.SkinChanger.updateArtistShedletskyEquip)
                            if previousSelection == "Artist shedletsky"
                                and S.SkinChanger.active == previousSelection then
                                pcall(S.SkinChanger.deactivate)
                            end
                        elseif previousSelection and S.SkinChanger.genericSkinDefinitions
                            and S.SkinChanger.genericSkinDefinitions[previousSelection] then
                            pcall(S.SkinChanger.restoreGenericEquippedSkin, requiredCharacter)
                            if S.SkinChanger.active == previousSelection then
                                pcall(S.SkinChanger.deactivate)
                            end
                        elseif previousSelection and S.SkinChanger.active == previousSelection then
                            pcall(S.SkinChanger.deactivate)
                        end
                        closeSkinPopup()
                        refreshSkinEntryLabels()
                        return
                    end

                    -- Save the chosen skin first. Applying it is a separate operation
                    -- gated by both the master Enable state and the active character.
                    S.SkinChanger.selectedByCharacter[requiredCharacter] = choiceKey
                    closeSkinPopup()
                    refreshSkinEntryLabels()
                    if S.SkinChanger.enabled == true and S.SkinChanger.unlockAllAvailableSkins then
                        pcall(S.SkinChanger.unlockAllAvailableSkins)
                    end

                    local character = S.lp and S.lp.Character
                    local isTwoTimeSkin = requiredCharacter == "TwoTime"
                        and S.TwoTimeSkinChanger
                        and S.TwoTimeSkinChanger.isSkin(choiceKey)
                    local isArtistShedletsky = requiredCharacter == "Shedletsky"
                        and choiceKey == "Artist shedletsky"
                    local genericDefinition = S.SkinChanger.genericSkinDefinitions
                        and S.SkinChanger.genericSkinDefinitions[choiceKey]
                    local isGenericSkin = genericDefinition ~= nil
                        and genericDefinition.characterName == requiredCharacter
                    local equipWasApplied = false
                    if S.SkinChanger.enabled == true and isTwoTimeSkin then
                        local equipOK, equipError = S.TwoTimeSkinChanger.equipSelectedSkin(choiceKey)
                        equipWasApplied = equipOK == true
                        if not equipOK then
                            warn("[E1LU4HUB Skin Changer] Equip Skin failed: " .. tostring(equipError))
                        end
                    elseif S.SkinChanger.enabled == true and isArtistShedletsky then
                        local equipOK, equipError = S.SkinChanger.updateArtistShedletskyEquip()
                        equipWasApplied = equipOK == true
                        if not equipOK then
                            warn("[E1LU4HUB Skin Changer] Artist Shedletsky Equip Skin failed: " .. tostring(equipError))
                        end
                    elseif S.SkinChanger.enabled == true and isGenericSkin then
                        local callOK, equipOK, equipError = pcall(S.SkinChanger.equipGenericSkin, choiceKey)
                        equipWasApplied = callOK and equipOK == true
                        if not equipWasApplied then
                            warn("[E1LU4HUB Skin Changer] Generic Equip Skin pending: " .. tostring(equipError or equipOK))
                        end
                        if S.SkinChanger.queueGenericSkinEquip then
                            pcall(S.SkinChanger.queueGenericSkinEquip, choiceKey)
                        end
                    end

                    if S.SkinChanger.enabled == true and character and character.Name == requiredCharacter then
                        queueApplySelectedSkin(character)
                        if S.__helpers.notify then
                            S.__helpers.notify("Skin Changer", "Selection saved. It will apply when the character is ready.", 3.2)
                        end
                    else
                        -- Other-character selection is allowed. For TwoTime, Equip Skin
                        -- has already been written above while visual morphing stays gated.
                        if S.__helpers.notify then
                            local message
                            if isTwoTimeSkin and equipWasApplied then
                                message = "Equip Skin applied. The character appearance will update when you use Survivor TwoTime."
                            elseif isArtistShedletsky and equipWasApplied then
                                message = "Equip Skin applied. The appearance will update when you use Shedletsky."
                            elseif isGenericSkin and equipWasApplied then
                                message = "Equip Skin applied. The appearance and portrait will update when you use " .. requiredCharacter .. "."
                            else
                                message = "Selection saved. It will apply when Enable is ON and you use " .. requiredCharacter .. "."
                            end
                            S.__helpers.notify("Skin Changer", message, 3.2)
                        end
                    end
                end)
            end

            addChoice("None", nil, true, 1)
            for index, choice in ipairs(options) do
                addChoice(choice.label, choice.key, false, index + 1)
            end
        end

        local function addSkinEntry(targetContents, characterName, requiredCharacter, skinKey, choiceLabel, order, choiceOptions)
            local rowButton = Instance.new("TextButton")
            rowButton.Name = "SkinEntry_" .. requiredCharacter
            rowButton:SetAttribute("E1LU4HUB_PopupOpener", true)
            rowButton.Size = UDim2.new(0.92, 0, 0, 32)
            rowButton.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
            rowButton.BackgroundTransparency = 0
            rowButton.BorderSizePixel = 0
            rowButton.AutoButtonColor = true
            rowButton.Text = ""
            rowButton.LayoutOrder = order
            rowButton.ZIndex = 2
            rowButton.Parent = targetContents

            local rowCorner = Instance.new("UICorner")
            rowCorner.CornerRadius = UDim.new(0, 4)
            rowCorner.Parent = rowButton
            local rowStroke = Instance.new("UIStroke")
            rowStroke.Color = Color3.fromRGB(58, 56, 66)
            rowStroke.Thickness = 1
            rowStroke.Transparency = 0
            rowStroke.Parent = rowButton

            -- Left-edge > marker, drawn with the reference two-stroke Chevron.
            createWideChevron(
                rowButton,
                "SkinEntryArrow",
                4,
                S.uiAccentColor or Color3.fromRGB(255, 255, 255),
                "right",
                "left"
            )
            local skinEntryArrow = rowButton:FindFirstChild("SkinEntryArrow")
            if skinEntryArrow then
                skinEntryArrow.ZIndex = 4
                for _, strokePart in ipairs(skinEntryArrow:GetChildren()) do
                    if strokePart:IsA("GuiObject") then
                        strokePart.ZIndex = 4
                        strokePart:SetAttribute("SkinChangerAccentFill", true)
                    end
                end
            end

            local rowLabel = Instance.new("TextLabel")
            rowLabel.Name = "SkinEntryLabel"
            rowLabel.Position = UDim2.new(0, 30, 0, 0)
            rowLabel.Size = UDim2.new(1, -40, 1, 0)
            rowLabel.BackgroundTransparency = 1
            local initialSelection = S.SkinChanger.selectedByCharacter[requiredCharacter]
            local initialLabel = initialSelection or "None"
            if initialSelection and choiceOptions then
                for _, choice in ipairs(choiceOptions) do
                    if choice.key == initialSelection then
                        initialLabel = choice.label
                        break
                    end
                end
            end
            rowLabel.Text = characterName .. ": " .. initialLabel
            rowLabel.TextColor3 = Color3.fromRGB(246, 245, 250)
            rowLabel.Font = Enum.Font.Gotham
            rowLabel.TextSize = 12
            rowLabel.TextXAlignment = Enum.TextXAlignment.Left
            rowLabel.ZIndex = 3
            rowLabel.Parent = rowButton

            local entryInfo = {
                button = rowButton,
                label = rowLabel,
                characterName = characterName,
                requiredCharacter = requiredCharacter,
                skinKey = skinKey,
                choiceLabel = choiceLabel,
                choices = choiceOptions,
            }
            table.insert(skinEntryRegistry, entryInfo)

            rowButton.Activated:Connect(function()
                if activeSkinPopup and activeSkinPopup.Parent then
                    -- Tapping the same row closes it; another row replaces it.
                    if activeSkinPopup:GetAttribute("SkinEntryKey") == requiredCharacter then
                        closeSkinPopup()
                        return
                    end
                end
                showSkinPopup(rowButton, characterName, requiredCharacter, skinKey, choiceLabel, choiceOptions)
                if activeSkinPopup then
                    activeSkinPopup:SetAttribute("SkinEntryKey", requiredCharacter)
                end
            end)
        end

        -- Skin choice buttons show the skin name without the character suffix.
        -- This is presentation-only: saved keys and asset folder names stay intact.
        local function getSkinToggleLabel(label, characterName)
            local suffixByCharacter = {
                ["TwoTime"] = "TwoTime",
                ["Helperbot"] = "Helperbot",
                ["Guest1337"] = "Guest",
                ["Shedletsky"] = "Shedletsky",
                ["Dusekkar"] = "Dusekkar",
                ["Noob"] = "Noob",
                ["JaneDoe"] = "JaneDoe",
                ["Veeronica"] = "Veeronica",
                ["Elliot"] = "Elliot",
                ["007n7"] = "007n7",
                ["Chance"] = "Chance",
                ["Taph"] = "Taph",
                ["Builderman"] = "Builderman",
            }
            local text = tostring(label or "")
            local suffix = suffixByCharacter[characterName]
            if suffix and suffix ~= "" then
                -- Most entries end with the character name. A few composite
                -- variant names (for example Milestone100TwoTimeNightshade)
                -- place it in the middle, so remove only the suffix token itself.
                text = text:gsub(suffix, ""):gsub("%s+$", "")
            end

            -- Display labels only: remove decorative ! / # prefixes while
            -- preserving the real key and ReplicatedStorage asset folder name.
            text = text:gsub("[!#]", "")

            local milestoneLabels = {
                LegacyMS100 = "Legacy Milestone lV",
                LegacyMS75 = "Legacy Milestone lll",
                LegacyMS50 = "Legacy Milestone ll",
                LegacyMS25 = "Legacy Milestone l",
            }
            if milestoneLabels[text] then
                text = milestoneLabels[text]
            else
                local milestoneTiers = {
                    {"100", "lV"},
                    {"75", "lll"},
                    {"50", "ll"},
                    {"25", "l"},
                }
                for _, tier in ipairs(milestoneTiers) do
                    local prefix = "Milestone" .. tier[1]
                    if text:sub(1, #prefix) == prefix then
                        local remainder = text:sub(#prefix + 1):gsub("^%s+", "")
                        text = "Milestone " .. tier[2]
                        if remainder ~= "" then
                            text ..= " " .. remainder
                        end
                        break
                    end
                end
            end
            return text
        end

        -- Register a folder-backed skin option. The visible label may differ
        -- from the real asset folder name (e.g. ArtistElliot -> OvenbotElliot).
        local function makeGenericSkinChoices(characterName, definitions)
            local choices = {}
            for _, definition in ipairs(definitions) do
                local key = definition.key or definition.folderName
                local folderNames = definition.folderNames or {definition.folderName or key}
                local originalLabel = definition.label or key
                S.SkinChanger.genericSkinDefinitions[key] = {
                    characterName = characterName,
                    folderNames = folderNames,
                    displayLabel = originalLabel,
                }
                table.insert(choices, {
                    key = key,
                    label = getSkinToggleLabel(originalLabel, characterName),
                })
            end
            return choices
        end

