        end
        if S.lp then
            S.SkinChanger.selectionCharacterConnection = S.lp.CharacterAdded:Connect(function(newCharacter)
                queueApplySelectedSkin(newCharacter)
            end)
        end

        -- Clicking the master switch also closes any open chooser when disabled;
        -- enabling invokes the saved preference handler without changing selection.
        skinEnabledButton.Activated:Connect(function()
            task.defer(function()
                if S.SkinChanger.enabled ~= true then
                    closeSkinPopup()
                    refreshSkinEntryLabels()
                else
                    queueApplySelectedSkin(S.lp and S.lp.Character)
                    refreshSkinEntryLabels()
                end
            end)
        end)

        -- Generic skins keep their game-side Equipped.Skins entry in sync just
        -- like the dedicated TwoTime/Artist paths. This retries while PlayerData
        -- and the CurrentSurvivors card are still being constructed.
        if S.SkinChanger.genericEquipHeartbeatConnection then
            pcall(function() S.SkinChanger.genericEquipHeartbeatConnection:Disconnect() end)
        end
        local genericEquipElapsed = 0
        S.SkinChanger.genericEquipHeartbeatConnection = S.RunService.Heartbeat:Connect(function(deltaTime)
            if S.SkinChanger.enabled ~= true then return end
            genericEquipElapsed += tonumber(deltaTime) or (1 / 60)
            if genericEquipElapsed < 0.75 then return end
            genericEquipElapsed = 0
            for _, selectedKey in pairs(S.SkinChanger.selectedByCharacter or {}) do
                local definition = S.SkinChanger.genericSkinDefinitions
                    and S.SkinChanger.genericSkinDefinitions[selectedKey]
                if definition then
                    pcall(S.SkinChanger.equipGenericSkin, selectedKey)
                end
            end
        end)

        -- Ensure the shared dropdown rows use the active values after page creation.
        for _, dropdownButton in ipairs({
            S.deviceSpoofButton,
            S.autoBlockDetectionModeButton,
            S.antiBaitMethodButton,
            S.punchAimbotModeButton,
            S.staminaPresetButton,
            S.autoUndetectAbilityButton,
        }) do
            if dropdownButton and S.__helpers.refreshRightDropdownButton then
                S.__helpers.refreshRightDropdownButton(dropdownButton)
            end
        end

        -- Apply the active accent color immediately to the three left-chevron strokes.
        if S.__helpers.applyUIAccentColor then
            S.__helpers.applyUIAccentColor()
        end
    end

    -- Drop registry entries whose controls were destroyed with unrequested sections.
    -- This prevents legacy saved Configs from re-enabling removed features.
    local function isVisibleConfigObject(object)
        if not object or not object.Parent or not S.screenGui then return false end
        local ok, result = pcall(function() return object:IsDescendantOf(S.screenGui) end)
        return ok and result == true
    end
    local function pruneRegistry(registry, objectField)
        for index = #registry, 1, -1 do
            local entry = registry[index]
            if not entry or not isVisibleConfigObject(entry[objectField]) then
                table.remove(registry, index)
            end
        end
    end
    pruneRegistry(S.configToggleRegistry, "button")
    pruneRegistry(S.configNumericRegistry, "container")
    pruneRegistry(S.configDropdownRegistry, "button")
    pruneRegistry(S.configColorRegistry, "box")
    for index = #S.uiToggleBoxes, 1, -1 do
        if not isVisibleConfigObject(S.uiToggleBoxes[index]) then
            table.remove(S.uiToggleBoxes, index)
        end
    end

    S.categoryPagesReady = true
end

-- FONT SELECTOR (Settings; uses the same popup-button style as Skin Changer)
-- The initial UI font is FredokaOne. This selector lets the user choose
-- another Roblox font and applies it to the E1LU4HUB interface.
-- Utility controls such as UI COLOR and Config actions keep
-- the same bold text style as ordinary action buttons, regardless of font selection.
-- Keep UI COLOR and Config action labels identical to ordinary action buttons
-- (Gotham Bold, 11px), independent of the font selector.
S.__helpers.isUtilityButtonFontTarget = function(object)
    if not object or not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then
        return false
    end

    local name = tostring(object.Name or "")
    if name == "UIColorButton"
        or name == "AntiLagActionButton" or name == "ConfigHeader" then
        return true
    end
    -- Config List / Create / Save / Load / Delete are the Config_ TextButtons.
    if object:IsA("TextButton") and name:sub(1, 7) == "Config_" then
        return true
    end

    local shownText = tostring(object.Text or object.PlaceholderText or ""):upper()
    return shownText == "UI COLOR"
        or shownText == "CONFIG"
        or shownText:match("^CONFIG LIST[: ]") ~= nil
        or shownText == "CREATE CONFIG"
        or shownText == "SAVE CONFIG"
        or shownText == "LOAD CONFIG"
        or shownText == "DELETE CONFIG"
end

S.__helpers.applyUtilityButtonFont = function(object)
    if not object or not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then
        return
    end
    pcall(function() object.Font = Enum.Font.GothamBold end)
    pcall(function()
        object.FontFace = Font.new(
            "rbxasset://fonts/families/GothamSSm.json",
            Enum.FontWeight.Bold,
            Enum.FontStyle.Normal
        )
    end)
    object.TextSize = 11
end

S.currentUIFontName = "FredokaOne"
-- Keep game font selection separate from the hub's own font so choosing a game
-- font never changes the existing ELSEGUI appearance. Both start at FredokaOne.
S.currentGameFontName = S.currentGameFontName or "FredokaOne"

-- Change Game Font applies the selected game font to game-owned text objects.
-- It deliberately skips CoreGui and this script's own ScreenGuis, so the hub UI
-- and its floating controls keep their independent styling.
S.gameFontState = S.gameFontState or {
    enabled = false,
    originals = setmetatable({}, {__mode = "k"}),
}
S.gameFontState.originals = S.gameFontState.originals or setmetatable({}, {__mode = "k"})

S.__helpers.isGameFontTarget = function(object)
    if not object or not (object:IsA("TextLabel")
        or object:IsA("TextButton")
        or object:IsA("TextBox")) then
        return false
    end

    if S.espTextFontTargets and S.espTextFontTargets[object] then
        return false
    end

    local node = object
    while node do
        if node == S.CoreGui
            or node == S.screenGui
            or node == S.restoreScreenGui
            or node == S.autoBlockScreenGui
            then
            return false
        end

        local nodeName = tostring(node.Name or "")
        if nodeName:sub(1, 10) == "E1LU4HUB"
            or nodeName:sub(1, 7) == "ELSGUI_"
            or nodeName == S.GENERATOR_TEXT_GUI_NAME then
            return false
        end
        node = node.Parent
    end
    return true
end

S.__helpers.applyGameFontToObject = function(object, fontEnum)
    if not S.gameFontState.enabled or not S.__helpers.isGameFontTarget(object) then
        return false
    end

    local originals = S.gameFontState.originals
    if originals[object] == nil then
        local saved = {}
        local fontOK, originalFont = pcall(function() return object.Font end)
        if fontOK then saved.Font = originalFont end
        local faceOK, originalFontFace = pcall(function() return object.FontFace end)
        if faceOK then saved.FontFace = originalFontFace end
        originals[object] = saved
    end

    if not fontEnum then
        fontEnum = Enum.Font[S.currentGameFontName or "FredokaOne"]
    end
    if not fontEnum then return false end

    pcall(function() object.Font = fontEnum end)
    pcall(function() object.FontFace = Font.fromEnum(fontEnum) end)
    return true
end

S.__helpers.applyGameFont = function(fontEnum)
    if not S.gameFontState.enabled then return false end
    fontEnum = fontEnum or Enum.Font[S.currentGameFontName or "FredokaOne"]
    if not fontEnum then return false end

    for _, object in ipairs(game:GetDescendants()) do
        S.__helpers.applyGameFontToObject(object, fontEnum)
    end
    return true
end

S.__helpers.setSelectedGameFont = function(fontName)
    if type(fontName) ~= "string" or not Enum.Font[fontName] then return false end
    S.currentGameFontName = fontName

    -- Refresh the selector sample immediately, even when Change Game Font is OFF.
    -- This changes only the font-name value label inside the Game Font row.
    if S.__helpers.refreshRightDropdownButton then
        S.__helpers.refreshRightDropdownButton(S.gameFontButton)
    end

    -- When the feature is already active, update existing game text immediately.
    if S.gameFontState and S.gameFontState.enabled then
        return S.__helpers.applyGameFont(Enum.Font[fontName]) == true
    end
    return true
end

S.__helpers.setChangeGameFontEnabled = function(enabled)
    local state = S.gameFontState
    state.enabled = enabled == true
    S.isChangeGameFontEnabled = state.enabled

    if state.enabled then
        local fontEnum = Enum.Font[S.currentGameFontName or "FredokaOne"]
        if not fontEnum then
            state.enabled = false
            S.isChangeGameFontEnabled = false
            return false
        end
        return S.__helpers.applyGameFont(fontEnum)
    end

    for object, original in pairs(state.originals) do
        if object then
            if original.Font ~= nil then
                pcall(function() object.Font = original.Font end)
            end
            if original.FontFace ~= nil then
                pcall(function() object.FontFace = original.FontFace end)
            end
        end
        state.originals[object] = nil
    end
    return true
end

-- Apply the chosen font to game UI added while the option is active.
S.gameFontDescendantConnection = S.gameFontDescendantConnection or S.__helpers.connect(game.DescendantAdded, function(object)
    if not S.gameFontState or not S.gameFontState.enabled then return end
    if not (object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox")) then return end
    task.defer(function()
        if S.gameFontState and S.gameFontState.enabled and object.Parent then
            S.__helpers.applyGameFontToObject(object, Enum.Font[S.currentGameFontName or "FredokaOne"])
        end
    end)
end)

-- Keep the two brand labels fixed to FredokaOne regardless of the selected UI font.
S.__helpers.isFixedBrandFontTarget = function(object)
    return object ~= nil and (object == S.titleLabel or object == S.titleCreditLabel)
end

S.__helpers.applyFixedBrandFont = function(object)
    if not S.__helpers.isFixedBrandFontTarget(object) then return end
    pcall(function() object.Font = Enum.Font.FredokaOne end)
    pcall(function() object.FontFace = Font.fromEnum(Enum.Font.FredokaOne) end)
end

-- The title-bar minimize (-) and close (X) controls always use Arcade,
-- regardless of the font selected for the rest of the interface.
S.__helpers.isFixedArcadeTitleButton = function(object)
    return object ~= nil
        and object:IsA("TextButton")
        and (object.Name == "ELSEGUI_MinimizeButton"
            or object.Name == "ELSEGUI_DestroyButton")
end

S.__helpers.applyFixedArcadeTitleFont = function(object)
    if not S.__helpers.isFixedArcadeTitleButton(object) then return end
    pcall(function() object.Font = Enum.Font.Arcade end)
    pcall(function() object.FontFace = Font.fromEnum(Enum.Font.Arcade) end)
end

S.__helpers.applyUIFont = function(fontName)
    local fontEnum = Enum.Font[fontName]
    if not fontEnum then return false end
    S.currentUIFontName = fontName

    local function applyToTextObject(object)
        if object and (object:IsA("TextLabel")
            or object:IsA("TextButton")
            or object:IsA("TextBox")) then
            if S.__helpers.isFixedBrandFontTarget(object) then
                S.__helpers.applyFixedBrandFont(object)
            elseif S.__helpers.isFixedArcadeTitleButton(object) then
                S.__helpers.applyFixedArcadeTitleFont(object)
            elseif S.__helpers.isUtilityButtonFontTarget(object) then
                S.__helpers.applyUtilityButtonFont(object)
            else
                pcall(function() object.Font = fontEnum end)
            end
        end
    end

    if S.screenGui then
        for _, object in ipairs(S.screenGui:GetDescendants()) do
            applyToTextObject(object)
        end
    end


    -- Keep the title-bar controls fixed to Arcade regardless of the chosen UI font.
    if S.minimizeButton then S.__helpers.applyFixedArcadeTitleFont(S.minimizeButton) end
    if S.elseguiDestroyButton then S.__helpers.applyFixedArcadeTitleFont(S.elseguiDestroyButton) end

    -- If Change Game Font is active, update game-owned text to the newly selected font.
    if S.isChangeGameFontEnabled and S.__helpers.applyGameFont then
        S.__helpers.applyGameFont(fontEnum)
    end
    return true
end

-- Keep the selected font on UI text created later as well.
if S.screenGui then
    S.__helpers.connect(S.screenGui.DescendantAdded, function(object)
        if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
            task.defer(function()
                if not object.Parent then return end
                if S.__helpers.isFixedBrandFontTarget(object) then
                    S.__helpers.applyFixedBrandFont(object)
                elseif S.__helpers.isFixedArcadeTitleButton(object) then
                    S.__helpers.applyFixedArcadeTitleFont(object)
                elseif S.__helpers.isUtilityButtonFontTarget(object) then
                    S.__helpers.applyUtilityButtonFont(object)
                else
                    local fontEnum = Enum.Font[S.currentUIFontName or "Gotham"]
                    if fontEnum then
                        pcall(function() object.Font = fontEnum end)
                    end
                end
            end)
        end
    end)

    -- Reapply the matching ordinary-button font to UI COLOR and Config controls.
    for _, object in ipairs(S.screenGui:GetDescendants()) do
        if S.__helpers.isFixedBrandFontTarget(object) then
            S.__helpers.applyFixedBrandFont(object)
        elseif S.__helpers.isUtilityButtonFontTarget(object) then
            S.__helpers.applyUtilityButtonFont(object)
        elseif S.__helpers.isFixedArcadeTitleButton(object) then
            S.__helpers.applyFixedArcadeTitleFont(object)
        end
    end
end

-- Apply FredokaOne (the initial font) to UI elements that already exist.
-- The DescendantAdded handler above applies it to subsequently-created elements.
S.__helpers.applyUIFont(S.currentUIFontName)

