S.__helpers.setResizeHandleHover = function(hovered)
    hovered = hovered == true
    S.resizeHandleHovered = hovered
    local handle = S.resizeHandle
    if not handle or not handle.Parent then return end
    local info = TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local goal = {
        Size = hovered and UDim2.fromOffset(27, 27) or UDim2.fromOffset(19, 19),
        ImageTransparency = hovered and 0.06 or 0.72,
        ImageColor3 = hovered and S.uiAccentColor or Color3.fromRGB(170, 168, 178),
    }
    pcall(function() S.TweenService:Create(handle, info, goal):Play() end)
end

S.__helpers.connect(S.resizeHandle.MouseEnter, function()
    S.__helpers.setResizeHandleHover(true)
end)
S.__helpers.connect(S.resizeHandle.MouseLeave, function()
    if not S.isResizingMainFrame then S.__helpers.setResizeHandleHover(false) end
end)
S.__helpers.connect(S.resizeHandle.InputBegan, function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1
        and input.UserInputType ~= Enum.UserInputType.Touch then
        return
    end
    S.dragging = false
    S.dragInput = nil
    S.isResizingMainFrame = true
    S.resizeDragStartPosition = Vector2.new(input.Position.X, input.Position.Y)
    S.resizeStartSize = S.mainFrame.AbsoluteSize
    S.__helpers.setResizeHandleHover(true)
end)
-- Global UserInputService.InputEnded above finishes mouse/touch resizing,
-- avoiding a child/parent InputEnded ordering race on the resize handle.

