S.__helpers.animateDestroyUI = function(onComplete)
    local frame = S.mainFrame
    if not frame or not frame.Parent then
        if type(onComplete) == "function" then onComplete() end
        return
    end
    S.__helpers.mainFrameVisibilityToken += 1
    local info = TweenInfo.new(0.24, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
    local targets = S.__helpers.captureMainFrameOpacity()
    for obj, properties in pairs(targets) do
        if obj and obj.Parent then
            local goal = {}
            for property in pairs(properties) do goal[property] = 1 end
            if next(goal) then pcall(function() S.TweenService:Create(obj, info, goal):Play() end) end
        end
    end
    local pos = frame.Position
    local moveTween = S.TweenService:Create(frame, info, {
        Position = UDim2.new(pos.X.Scale, pos.X.Offset, pos.Y.Scale, pos.Y.Offset + 14),
    })
    moveTween.Completed:Connect(function()
        if type(onComplete) == "function" then
            pcall(onComplete)
        end
    end)
    moveTween:Play()
end

S.__helpers.connect(S.elseguiDestroyButton.MouseButton1Click, function()
    S.__helpers.showStyledActionConfirm(
        "Destroy E1LU4 HUB?",
        "Close and remove E1LU4 HUB from the screen? This cannot be undone.",
        function()
            -- Let the visual fade finish first; cleanup itself also removes GUI instances.
            S.__helpers.animateDestroyUI(function()
                pcall(function()
                    if _G.StaminaSettingsCleanup then _G.StaminaSettingsCleanup() end
                end)
                pcall(function()
                    if S.restoreScreenGui and S.restoreScreenGui.Parent then
                        S.restoreScreenGui:Destroy()
                    end
                end)
                pcall(function()
                    if S.autoBlockScreenGui and S.autoBlockScreenGui.Parent then
                        S.autoBlockScreenGui:Destroy()
                    end
                end)
                pcall(function()
                    if S.punchFOVScreenGui and S.punchFOVScreenGui.Parent then
                        S.punchFOVScreenGui:Destroy()
                    end
                end)
                pcall(function()
                    if S.screenGui and S.screenGui.Parent then S.screenGui:Destroy() end
                end)
            end)
        end,
        "Destroy"
    )
end)

-- ================================================================
-- CONFIG SYSTEM: create, save and load named configurations
-- Default is read-only; custom configs are stored as separate JSON files.
-- ================================================================
do
    local settingsPage = S.mainFrame and S.mainFrame:FindFirstChild("Page_Settings")
    if settingsPage then
        -- Put Config in a single bordered card inside the existing two-column layout.
        -- Keep this local to Config so the established page/sidebar construction stays untouched.
        local configHost = settingsPage:FindFirstChild("ColumnLeft") or settingsPage:FindFirstChild("ColumnRight") or settingsPage
