        configFrameCorner.Parent = configFrame
        local configFrameStroke = Instance.new("UIStroke")
        configFrameStroke.Color = Color3.fromRGB(58, 56, 66)
        configFrameStroke.Thickness = 1
        configFrameStroke.Parent = configFrame
        local configFramePadding = Instance.new("UIPadding")
        configFramePadding.PaddingTop = UDim.new(0, 8)
        configFramePadding.PaddingBottom = UDim.new(0, 8)
        configFramePadding.PaddingLeft = UDim.new(0, 8)
        configFramePadding.PaddingRight = UDim.new(0, 8)
        configFramePadding.Parent = configFrame
        local configFrameLayout = Instance.new("UIListLayout")
        configFrameLayout.SortOrder = Enum.SortOrder.LayoutOrder
        configFrameLayout.FillDirection = Enum.FillDirection.Vertical
        configFrameLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
        configFrameLayout.VerticalAlignment = Enum.VerticalAlignment.Top
        configFrameLayout.Padding = UDim.new(0, 5)
        configFrameLayout.Parent = configFrame

        local configHeader = Instance.new("TextLabel")
        configHeader.Name = "ConfigHeader"
        configHeader.Size = UDim2.new(1, -16, 0, 26)
        configHeader.BackgroundTransparency = 1
        configHeader.Text = "CONFIG"
        configHeader.TextColor3 = S.uiAccentColor
        configHeader.Font = Enum.Font.GothamBold
        configHeader.TextSize = 11
        configHeader.TextXAlignment = Enum.TextXAlignment.Left
        configHeader.LayoutOrder = 1
        configHeader.Parent = configFrame

        local configName = Instance.new("TextBox")
        configName.Name = "ConfigName"
        configName.Size = UDim2.new(1, -16, 0, 30)
        configName.BackgroundColor3 = Color3.fromRGB(38, 37, 44)
        configName.BorderSizePixel = 0
        configName.Text = ""
        configName.PlaceholderText = "Enter config name (Default to load default)"
        configName.ClearTextOnFocus = false
        configName.TextColor3 = Color3.new(1, 1, 1)
        configName.PlaceholderColor3 = Color3.fromRGB(132, 130, 140)
        configName.Font = Enum.Font.Gotham
        configName.TextSize = 12
        configName.TextXAlignment = Enum.TextXAlignment.Left
        configName.LayoutOrder = 3
        configName.Parent = configFrame
        local configNamePadding = Instance.new("UIPadding")
        configNamePadding.PaddingLeft = UDim.new(0, 8)
        configNamePadding.Parent = configName
        local configNameCorner = Instance.new("UICorner")
        configNameCorner.CornerRadius = UDim.new(0, 4)
        configNameCorner.Parent = configName

        local configStatus = Instance.new("TextLabel")
        configStatus.Name = "ConfigStatus"
        configStatus.Size = UDim2.new(1, -16, 0, 24)
        configStatus.BackgroundTransparency = 1
        configStatus.Text = "Select a saved config from Config List, or enter a new name"
        configStatus.TextColor3 = Color3.fromRGB(170, 168, 178)
        configStatus.Font = Enum.Font.Gotham
        configStatus.TextSize = 10
        configStatus.TextXAlignment = Enum.TextXAlignment.Left
        configStatus.LayoutOrder = 8
        configStatus.Parent = configFrame

        local function makeConfigButton(text, order, isSelector)
            local button = Instance.new("TextButton")
            button.Name = "Config_" .. text:gsub("%s+", "")
            -- Action buttons match TP GENERATOR; the selector matches Skin Changer.
            button.Size = UDim2.new(1, -16, 0, isSelector and 34 or 32)
            button.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
            button.BorderSizePixel = 0
            button.AutoButtonColor = true
            button.Text = text
            button.TextColor3 = Color3.new(1, 1, 1)
            button.Font = Enum.Font.GothamBold
            button.TextSize = 11
            button.TextXAlignment = Enum.TextXAlignment.Left
            button.LayoutOrder = order
            button.Parent = configFrame
            local padding = Instance.new("UIPadding")
            padding.PaddingLeft = UDim.new(0, 10)
            padding.Parent = button
            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0, 4)
            corner.Parent = button
            return button
        end

        local HttpService = game:GetService("HttpService")
        local configFolder = "E1LU4HUB/Configs"
        local configListButton = makeConfigButton("Config List: Default  ≡", 2, true)
        configListButton:SetAttribute("E1LU4HUB_PopupOpener", true)
        local createConfigButton = makeConfigButton("Create Config", 4, false)
        local saveConfigButton = makeConfigButton("Save Config", 5, false)
        local loadConfigButton = makeConfigButton("Load Config", 6, false)
        local deleteConfigButton = makeConfigButton("Delete Config", 7, false)

        local function cleanConfigName(value)
            local name = tostring(value or ""):gsub("[^%w_%- ]", ""):gsub("%s+", "_")
            name = name:gsub("^_+", ""):gsub("_+$", "")
            if #name > 48 then name = name:sub(1, 48) end
            return name
        end

        local function getConfigPath(value)
            local name = cleanConfigName(value)
            if name == "" then return nil end
            return configFolder .. "/" .. name .. ".json", name
        end

        local function ensureConfigFolder()
            if type(isfolder) ~= "function" or type(makefolder) ~= "function" then return false end
            pcall(function() if not isfolder("E1LU4HUB") then makefolder("E1LU4HUB") end end)
            pcall(function() if not isfolder(configFolder) then makefolder(configFolder) end end)
            local ok, exists = pcall(function() return isfolder(configFolder) end)
            return ok and exists == true
        end

        -- Cache also keeps newly-created names visible if the executor's listfiles
        -- temporarily fails or returns paths in a different format.
        local configNameCache = {Default = true}

        local function getAvailableConfigs()
            local names = {"Default"}
            local seen = {default = true}

            local function addConfigName(displayName)
                displayName = tostring(displayName or ""):gsub("^%s+", ""):gsub("%s+$", "")
                if displayName == "" then return end
                local key = displayName:lower()
                if seen[key] then return end
                seen[key] = true
                table.insert(names, displayName)
            end

            -- Refresh the disk view each time so files created outside this UI also appear.
            if type(listfiles) == "function" then
                local folderOK, folderExists = pcall(function()
                    return type(isfolder) == "function" and isfolder(configFolder)
                end)
                if folderOK and folderExists then
                    local listOK, files = pcall(function() return listfiles(configFolder) end)
                    if listOK and type(files) == "table" then
                        for _, filePath in ipairs(files) do
                            local normalizedPath = tostring(filePath):gsub("\\", "/")
                            local fileName = normalizedPath:match("([^/]+)%.json$")
                            if fileName and fileName ~= "" then
                                addConfigName(fileName:gsub("_", " "))
                            end
                        end
                    end
                end
            end

            -- Cache catches a new config even if directory enumeration is flaky.
            for cachedName in pairs(configNameCache) do
                if cachedName ~= "Default" then addConfigName(cachedName) end
            end

            table.sort(names, function(a, b)
                -- Strict weak ordering: never return true when comparing equal values.
                if a == b then return false end
                local aDefault = a == "Default"
                local bDefault = b == "Default"
                if aDefault ~= bDefault then return aDefault end
                return a:lower() < b:lower()
            end)
            return names
        end

        -- Configs are selected from the searchable list, which is refreshed every time it opens.
        local selectedConfigName = "Default"

        local function refreshConfigListButton()
            if configListButton and configListButton.Parent then
                configListButton.Text = "Config List: " .. tostring(selectedConfigName) .. "  ≡"
            end
        end
        refreshConfigListButton()

        local function collectConfigData()
            local data = {
                version = 4,
                toggles = {},
                numbers = {},
                dropdowns = {},
                colors = {},
                uiAccentColorIndex = S.uiAccentColorIndex,
            }
            for _, item in ipairs(S.configToggleRegistry) do
                if item.button and item.button.Parent then
                    data.toggles[item.label] = item.button:GetAttribute("ToggleState") == true
                end
            end
            for _, item in ipairs(S.configNumericRegistry) do
                if item.container and item.container.Parent then
                    data.numbers[item.label] = item.getValue()
                end
            end
            for _, item in ipairs(S.configDropdownRegistry) do
                if item.button and item.button.Parent then
                    data.dropdowns[item.label] = item.getValue()
                end
            end
            for _, item in ipairs(S.configColorRegistry) do
                if item.box and item.box.Parent then
                    data.colors[item.label] = item.getValue()
                end
            end

            -- Store the floating Auto Block button position as normalized screen
            -- coordinates so it survives a Config reload and screen-size changes.
            local floatingButton = S.autoBlockScreenButton
            local camera = workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize
            if floatingButton and floatingButton.Parent and viewport
                and viewport.X > 0 and viewport.Y > 0 then
                local centerX = floatingButton.AbsolutePosition.X + floatingButton.AbsoluteSize.X * 0.5
                local centerY = floatingButton.AbsolutePosition.Y + floatingButton.AbsoluteSize.Y * 0.5
                data.autoBlockButtonPosition = {
                    x = math.clamp(centerX / viewport.X, 0, 1),
                    y = math.clamp(centerY / viewport.Y, 0, 1),
                }
            end
            return data
        end

        -- Capture this script's built-in UI defaults once. Loading "Default"
        -- restores these values rather than requiring a nonexistent Default.json.
        local defaultConfigData = collectConfigData()

        local function applyConfigData(data, displayName, isDefault)
            if type(data) ~= "table" then
                configStatus.Text = "Config: invalid data"
                return false
            end

            if type(data.uiAccentColorIndex) == "number" and S.uiAccentColors[data.uiAccentColorIndex] then
                S.uiAccentColorIndex = data.uiAccentColorIndex
                S.__helpers.applyUIAccentColor()
            end

            local savedButtonPosition = data.autoBlockButtonPosition
            -- Older custom Config files predate position storage; fall back to
            -- the captured built-in/default position for predictable loading.
            if type(savedButtonPosition) ~= "table"
                and type(defaultConfigData) == "table" then
                savedButtonPosition = defaultConfigData.autoBlockButtonPosition
            end
            local floatingButton = S.autoBlockScreenButton
            local camera = workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize
            if type(savedButtonPosition) == "table"
                and type(savedButtonPosition.x) == "number"
                and type(savedButtonPosition.y) == "number"
                and floatingButton and floatingButton.Parent
                and viewport and viewport.X > 0 and viewport.Y > 0 then
                local halfWidthScale = (floatingButton.AbsoluteSize.X * 0.5) / viewport.X
                local halfHeightScale = (floatingButton.AbsoluteSize.Y * 0.5) / viewport.Y
                local x = math.clamp(savedButtonPosition.x, halfWidthScale, 1 - halfWidthScale)
                local y = math.clamp(savedButtonPosition.y, halfHeightScale, 1 - halfHeightScale)
                floatingButton.Position = UDim2.fromScale(x, y)
            end

            local toggleMap = {}
            for _, item in ipairs(S.configToggleRegistry) do
                if item.button and item.button.Parent then toggleMap[item.label] = item end
            end
            -- Apply all registered toggle states as one silent transaction. Callbacks
            -- still run even when the requested state matches the current state, so
            -- runtime features are re-synchronized without noisy OFF -> OFF toasts.
            local wasApplyingConfig = S.__configApplying
            S.__configApplying = true
            for _, item in ipairs(S.configToggleRegistry) do
                if item.button and item.button.Parent then
                    local value = data.toggles and data.toggles[item.label]
                    if type(value) == "boolean" then
                        item.button:SetAttribute("ToggleState", value)
                        if item.box then
                            item.box.BackgroundColor3 = value and S.uiAccentColor or Color3.fromRGB(48, 47, 56)
                        end
                        local ok, err = pcall(item.callback, value)
                        if not ok then
                            warn("[E1LU4HUB] Config toggle apply failed for " .. tostring(item.label) .. ": " .. tostring(err))
                        end
                    end
                end
            end
            S.__configApplying = wasApplying

            local numberMap = {}
            for _, item in ipairs(S.configNumericRegistry) do numberMap[item.label] = item end
            for label, value in pairs(data.numbers or {}) do
                local item = numberMap[label]
                if item and type(value) == "number" then
                    local ok, err = pcall(item.setValue, value, true)
                    if not ok then warn("[E1LU4HUB] Config number apply failed for " .. tostring(label) .. ": " .. tostring(err)) end
                end
            end

            local colorMap = {}
            for _, item in ipairs(S.configColorRegistry) do colorMap[item.label] = item end
            for label, value in pairs(data.colors or {}) do
                local item = colorMap[label]
                if item and type(value) == "string" then
                    local ok, err = pcall(item.setValue, value)
                    if not ok then
                        warn("[E1LU4HUB] Config color apply failed for " .. tostring(label) .. ": " .. tostring(err))
                    end
                end
            end

            local dropdownMap = {}
            for _, item in ipairs(S.configDropdownRegistry) do dropdownMap[item.label] = item end
            for label, value in pairs(data.dropdowns or {}) do
                local item = dropdownMap[label]
                if item and type(value) == "string" and item.button and item.button.Parent then
                    local ok, err = pcall(item.setValue, value, true)
                    if not ok then warn("[E1LU4HUB] Config dropdown apply failed for " .. tostring(label) .. ": " .. tostring(err)) end
                end
            end

            selectedConfigName = displayName or "Default"
            configName.Text = selectedConfigName == "Default" and "" or selectedConfigName
            refreshConfigListButton()
            configStatus.Text = "Loaded: " .. selectedConfigName .. (isDefault and " (built-in defaults)" or "")
            S.__helpers.notify("Config Loaded", "Loaded config: " .. tostring(selectedConfigName), 3.8)
            return true
        end

        local function loadConfigByName(selected)
            selected = tostring(selected or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if selected == "" or selected:lower() == "default" then
                return applyConfigData(defaultConfigData, "Default", true)
            end
            if type(readfile) ~= "function" or type(isfile) ~= "function" then
                configStatus.Text = "Config: executor file API unavailable"
                return false
            end
            local path, name = getConfigPath(selected)
            if not path or not name then
                configStatus.Text = "Config: select a config first"
                return false
            end
            local existsOK, exists = pcall(function() return isfile(path) end)
            if not existsOK or not exists then
                configStatus.Text = "Config: file not found"
                return false
            end
            local readOK, raw = pcall(function() return readfile(path) end)
            if not readOK or type(raw) ~= "string" then
                configStatus.Text = "Config: read failed"
                return false
            end
            local decodeOK, data = pcall(function() return HttpService:JSONDecode(raw) end)
            if not decodeOK or type(data) ~= "table" then
                configStatus.Text = "Config: invalid file"
                return false
            end
            return applyConfigData(data, name:gsub("_", " "), false)
        end

        local function writeConfig(path)
            local ok, encoded = pcall(function() return HttpService:JSONEncode(collectConfigData()) end)
            if not ok then return false, "Config: encode failed" end
            local wrote = pcall(function() writefile(path, encoded) end)
            return wrote, wrote and "" or "Config: save failed"
        end

        S.__helpers.connect(createConfigButton.Activated, function()
            if type(writefile) ~= "function" or type(isfile) ~= "function" then
                configStatus.Text = "Config: executor file API unavailable"
                return
            end
            if not ensureConfigFolder() then configStatus.Text = "Config: could not create folder"; return end
            local path, name = getConfigPath(configName.Text)
            if not path or name == "" then configStatus.Text = "Config: enter a name first"; return end
            if name:lower() == "default" then configStatus.Text = "Config: Default is read-only"; return end
            local existsOK, exists = pcall(function() return isfile(path) end)
            if existsOK and exists then configStatus.Text = "Config: name already exists; select it to save"; return end
            local wrote, err = writeConfig(path)
            if not wrote then configStatus.Text = err; return end
            selectedConfigName = name:gsub("_", " ")
            configNameCache[selectedConfigName] = true
            configName.Text = selectedConfigName
            refreshConfigListButton()
            configStatus.Text = "Created: " .. configName.Text
            S.__helpers.notify("Config Created", "Created config: " .. configName.Text, 3.8)
        end)

        S.__helpers.connect(saveConfigButton.Activated, function()
            if type(writefile) ~= "function" or type(isfile) ~= "function" then
                configStatus.Text = "Config: executor file API unavailable"
                return
            end
            if not ensureConfigFolder() then configStatus.Text = "Config: could not create folder"; return end
            local path, name = getConfigPath(configName.Text)
            if not path or name == "" then configStatus.Text = "Config: select a custom config first"; return end
            if name:lower() == "default" then configStatus.Text = "Config: Default is read-only"; return end
            local existsOK, exists = pcall(function() return isfile(path) end)
            if not existsOK or not exists then configStatus.Text = "Config: create this config first"; return end
            local wrote, err = writeConfig(path)
            if wrote then
                selectedConfigName = name:gsub("_", " ")
                configNameCache[selectedConfigName] = true
                refreshConfigListButton()
            end
            configStatus.Text = wrote and ("Saved: " .. name:gsub("_", " ")) or err
            if wrote then
                -- Save Config success is the only green notification.
                S.__helpers.notify("Config Saved", "Saved config: " .. name:gsub("_", " "), 3.8, S.NOTIFICATION_SUCCESS_COLOR)
            else
                S.__helpers.notify("Config", err or "Could not save config.", 3.8)
            end
        end)

        S.__helpers.connect(loadConfigButton.Activated, function()
            local selected = configName.Text
            if selected == nil or selected == "" then selected = "Default" end
            local loaded = loadConfigByName(selected)
            if not loaded then
                S.__helpers.notify("Config", configStatus.Text or "Could not load config.", 3.8)
            end
        end)

        -- Delete is intentionally a two-step action and Default is immutable.
        S.__helpers.connect(deleteConfigButton.Activated, function()
            local typedName = tostring(configName.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
            local targetDisplayName = typedName ~= "" and typedName or selectedConfigName
            if not targetDisplayName or targetDisplayName == "" or targetDisplayName:lower() == "default" then
                configStatus.Text = "Config: Default is read-only"
                return
            end
            if type(isfile) ~= "function" then
                configStatus.Text = "Config: executor file API unavailable"
                return
            end
            local path, normalizedName = getConfigPath(targetDisplayName)
            if not path or not normalizedName or normalizedName:lower() == "default" then
                configStatus.Text = "Config: select a custom config first"
                return
            end
            local existsOK, exists = pcall(function() return isfile(path) end)
            if not existsOK or not exists then
                configStatus.Text = "Config: selected file not found"
                return
            end
            local deleteFunction = type(delfile) == "function" and delfile or (type(deletefile) == "function" and deletefile or nil)
            if not deleteFunction then
                configStatus.Text = "Config: delete file API unavailable"
                return
            end
            local screen = S.screenGui
            if not screen or not screen.Parent then
                configStatus.Text = "Config: UI is not available"
                return
            end
            local oldConfirm = screen:FindFirstChild("E1LU4HUBDeleteConfigPopup")
            if oldConfirm then oldConfirm:Destroy() end

            local popup = Instance.new("Frame")
            popup.Name = "E1LU4HUBDeleteConfigPopup"
            popup.Size = UDim2.fromScale(1, 1)
            popup.BackgroundColor3 = Color3.new(0, 0, 0)
            popup.BackgroundTransparency = 0.35
            popup.Active = true
            popup.ZIndex = 220
            popup.Parent = screen

            local panel = Instance.new("Frame")
            panel.Name = "DeleteConfigPanel"
            panel.AnchorPoint = Vector2.new(0.5, 0.5)
            panel.Position = UDim2.fromScale(0.5, 0.5)
            panel.Size = UDim2.new(0, 320, 0, 150)
            panel.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
            panel.BorderSizePixel = 0
            panel.ZIndex = 221
            panel.Parent = popup
            local panelCorner = Instance.new("UICorner")
            panelCorner.CornerRadius = UDim.new(0, 7)
            panelCorner.Parent = panel

            local title = Instance.new("TextLabel")
            title.BackgroundTransparency = 1
            title.Position = UDim2.new(0, 12, 0, 9)
            title.Size = UDim2.new(1, -24, 0, 24)
            title.Text = "Delete Config?"
            title.TextColor3 = Color3.new(1, 1, 1)
            title.Font = Enum.Font.Gotham
            title.TextSize = 13
            title.TextXAlignment = Enum.TextXAlignment.Left
            title.ZIndex = 222
            title.Parent = panel

            local message = Instance.new("TextLabel")
            message.BackgroundTransparency = 1
            message.Position = UDim2.new(0, 12, 0, 37)
            message.Size = UDim2.new(1, -24, 0, 36)
            message.Text = "Delete '" .. targetDisplayName .. "'? This cannot be undone."
            message.TextWrapped = true
            message.TextColor3 = Color3.fromRGB(200, 198, 207)
            message.Font = Enum.Font.Gotham
            message.TextSize = 11
            message.TextXAlignment = Enum.TextXAlignment.Left
            message.ZIndex = 222
            message.Parent = panel

            local cancelButton = Instance.new("TextButton")
            cancelButton.Name = "CancelDelete"
            cancelButton.Position = UDim2.new(0, 12, 1, -39)
            cancelButton.Size = UDim2.new(0.5, -18, 0, 27)
            cancelButton.BackgroundColor3 = Color3.fromRGB(54, 52, 61)
            cancelButton.BorderSizePixel = 0
            cancelButton.Text = "Cancel"
            cancelButton.TextColor3 = Color3.new(1, 1, 1)
            cancelButton.Font = Enum.Font.Gotham
            cancelButton.TextSize = 11
            cancelButton.ZIndex = 222
            cancelButton.Parent = panel
            local cancelCorner = Instance.new("UICorner")
            cancelCorner.CornerRadius = UDim.new(0, 4)
            cancelCorner.Parent = cancelButton

            local confirmButton = Instance.new("TextButton")
            confirmButton.Name = "ConfirmDelete"
            confirmButton.Position = UDim2.new(0.5, 6, 1, -39)
            confirmButton.Size = UDim2.new(0.5, -18, 0, 27)
            confirmButton.BackgroundColor3 = Color3.fromRGB(150, 45, 45)
            confirmButton.BorderSizePixel = 0
            confirmButton.Text = "Delete"
            confirmButton.TextColor3 = Color3.new(1, 1, 1)
            confirmButton.Font = Enum.Font.Gotham
            confirmButton.TextSize = 11
            confirmButton.ZIndex = 222
            confirmButton.Parent = panel
            local confirmCorner = Instance.new("UICorner")
            confirmCorner.CornerRadius = UDim.new(0, 4)
            confirmCorner.Parent = confirmButton

            S.__helpers.connect(cancelButton.Activated, function()
                if popup and popup.Parent then popup:Destroy() end
            end)
            S.__helpers.connect(confirmButton.Activated, function()
                if popup and popup.Parent then popup:Destroy() end
                -- Re-check the captured path at confirmation time. The selected
                -- name, rather than an editable TextBox value, is the delete target.
                if targetDisplayName:lower() == "default" or normalizedName:lower() == "default" then
                    configStatus.Text = "Config: Default is read-only"
                    return
                end
                local checkOK, stillExists = pcall(function() return isfile(path) end)
                if not checkOK or not stillExists then
                    configStatus.Text = "Config: selected file not found"
                    return
                end
                local deleteOK = pcall(function() deleteFunction(path) end)
                local verifyOK, remains = pcall(function() return isfile(path) end)
                if not deleteOK or not verifyOK or remains then
                    configStatus.Text = "Config: delete failed"
                    return
                end
                configNameCache[targetDisplayName] = nil
                configNameCache[normalizedName:gsub("_", " ")] = nil
                selectedConfigName = "Default"
                configName.Text = ""
                refreshConfigListButton()
                configStatus.Text = "Deleted: " .. targetDisplayName
                S.__helpers.notify("Config Deleted", "Deleted config: " .. targetDisplayName, 3.8)
                -- The selector rebuilds its entries from listfiles every time it opens.
            end)
        end)

        -- Searchable Config List, styled after the Skin Changer selector.
        -- Selecting an entry loads it immediately; the list is rebuilt each time
        -- it opens so newly created/deleted config files are reflected.
        local function showConfigListPopup()
            local screen = S.screenGui
            if not screen or not screen.Parent then
                configStatus.Text = "Config: UI is not available"
                return
            end
            -- Clear any stale list/confirmation overlay before constructing a fresh list.
            local staleNames = {"E1LU4HUBConfigListPopup", "E1LU4HUBActionConfirmPopup"}
            for _, staleName in ipairs(staleNames) do
                local stale = screen:FindFirstChild(staleName)
                if stale then stale:Destroy() end
            end

            local optionsOK, options = pcall(getAvailableConfigs)
            if not optionsOK or type(options) ~= "table" then
                configStatus.Text = "Config: could not refresh list"
                warn("[E1LU4HUB] Config List refresh failed: " .. tostring(options))
                return
            end
            local overlay = Instance.new("Frame")
            overlay.Name = "E1LU4HUBConfigListPopup"
            overlay.Size = UDim2.fromScale(1, 1)
            overlay.BackgroundColor3 = Color3.new(0, 0, 0)
            overlay.BackgroundTransparency = 0.35
            overlay.Active = true
            overlay.ZIndex = 210
            overlay.Parent = screen

            local panel = Instance.new("Frame")
            panel.Name = "ConfigListPanel"
            panel.AnchorPoint = Vector2.new(0.5, 0.5)
            panel.Position = UDim2.fromScale(0.5, 0.5)
            panel.Size = UDim2.new(0, 320, 0, 330)
            panel.BackgroundColor3 = Color3.fromRGB(36, 35, 42)
            panel.BorderSizePixel = 0
            panel.ZIndex = 211
            panel.Parent = overlay
            local panelCorner = Instance.new("UICorner")
            panelCorner.CornerRadius = UDim.new(0, 7)
            panelCorner.Parent = panel

            local title = Instance.new("TextLabel")
            title.BackgroundTransparency = 1
            title.Position = UDim2.new(0, 12, 0, 7)
            title.Size = UDim2.new(1, -52, 0, 28)
            title.Text = "Config List"
            title.TextColor3 = S.uiAccentColor
            title.Font = Enum.Font.Gotham
            title.TextSize = 13
            title.TextXAlignment = Enum.TextXAlignment.Left
            title.ZIndex = 212
            title.Parent = panel

            local close = Instance.new("TextButton")
            close.Name = "CloseConfigList"
            close.Position = UDim2.new(1, -34, 0, 6)
            close.Size = UDim2.new(0, 27, 0, 27)
            close.Text = "X"
            close.TextColor3 = Color3.new(1, 1, 1)
            close.BackgroundColor3 = Color3.fromRGB(150, 45, 45)
            close.BorderSizePixel = 0
            close.Font = Enum.Font.Gotham
            close.TextSize = 12
            close.ZIndex = 212
            close.Parent = panel
            S.__helpers.connect(close.Activated, function()
                if overlay and overlay.Parent then overlay:Destroy() end
            end)

            local search = Instance.new("TextBox")
            search.Name = "ConfigListSearch"
            search.Position = UDim2.new(0, 10, 0, 40)
            search.Size = UDim2.new(1, -20, 0, 28)
            search.PlaceholderText = "Search configs..."
            search.Text = ""
            search.ClearTextOnFocus = false
            search.BackgroundColor3 = Color3.fromRGB(38, 37, 44)
            search.TextColor3 = Color3.new(1, 1, 1)
            search.PlaceholderColor3 = Color3.fromRGB(132, 130, 140)
            search.Font = Enum.Font.Gotham
            search.TextSize = 11
            search.BorderSizePixel = 0
            search.ZIndex = 212
            search.Parent = panel

            local scroll = Instance.new("ScrollingFrame")
            scroll.Name = "ConfigListEntries"
            scroll.Position = UDim2.new(0, 10, 0, 76)
            scroll.Size = UDim2.new(1, -20, 1, -86)
            scroll.BackgroundColor3 = Color3.fromRGB(26, 25, 30)
            scroll.BorderSizePixel = 0
            scroll.ScrollBarThickness = 4
            scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
            scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
            scroll.ZIndex = 212
            scroll.Parent = panel
            local listLayout = Instance.new("UIListLayout")
            listLayout.Padding = UDim.new(0, 3)
            listLayout.SortOrder = Enum.SortOrder.LayoutOrder
            listLayout.Parent = scroll
            local listPadding = Instance.new("UIPadding")
            listPadding.PaddingTop = UDim.new(0, 4)
            listPadding.PaddingBottom = UDim.new(0, 4)
            listPadding.PaddingLeft = UDim.new(0, 4)
            listPadding.PaddingRight = UDim.new(0, 4)
            listPadding.Parent = scroll

            local function rebuildList()
                for _, child in ipairs(scroll:GetChildren()) do
                    if child:IsA("TextButton") or child.Name == "ConfigListEmpty" then
                        child:Destroy()
                    end
                end
                local query = tostring(search.Text or ""):lower()
                local shown = 0
                for _, configDisplayName in ipairs(options) do
                    configDisplayName = tostring(configDisplayName)
                    if query == "" or configDisplayName:lower():find(query, 1, true) then
                        shown += 1
                        local entry = Instance.new("TextButton")
                        entry.Name = "ConfigEntry_" .. configDisplayName:gsub("%W", "")
                        entry.Size = UDim2.new(1, -2, 0, 29)
                        entry.BackgroundColor3 = configDisplayName == selectedConfigName and Color3.fromRGB(58, 56, 66) or Color3.fromRGB(43, 42, 49)
                        entry.BorderSizePixel = 0
                        entry.AutoButtonColor = true
                        entry.Text = (configDisplayName == "Default" and "◈  " or "▤  ") .. configDisplayName
                        entry.TextColor3 = Color3.new(1, 1, 1)
                        entry.Font = Enum.Font.Gotham
                        entry.TextSize = 11
                        entry.TextXAlignment = Enum.TextXAlignment.Left
                        entry.LayoutOrder = shown
                        entry.ZIndex = 213
                        entry.Parent = scroll
                        local entryPadding = Instance.new("UIPadding")
                        entryPadding.PaddingLeft = UDim.new(0, 8)
                        entryPadding.Parent = entry
                        S.__helpers.connect(entry.Activated, function()
                            if overlay and overlay.Parent then overlay:Destroy() end
                            selectedConfigName = configDisplayName
                            configName.Text = configDisplayName == "Default" and "" or configDisplayName
                            refreshConfigListButton()
                            configStatus.Text = "Selected: " .. configDisplayName .. " (press Load Config to load)"
                            S.__helpers.notify("Config Selected", "Selected " .. configDisplayName .. ". Press Load Config to apply it.", 3.4)
                        end)
                    end
                end
                if shown == 0 then
                    local empty = Instance.new("TextLabel")
                    empty.Name = "ConfigListEmpty"
                    empty.Size = UDim2.new(1, -2, 0, 28)
                    empty.BackgroundTransparency = 1
                    empty.Text = type(listfiles) == "function" and "No matching configs" or "Executor file list API unavailable"
                    empty.TextColor3 = Color3.fromRGB(153, 151, 161)
                    empty.Font = Enum.Font.Gotham
                    empty.TextSize = 11
                    empty.ZIndex = 213
                    empty.Parent = scroll
                end
            end
            S.__helpers.connect(search:GetPropertyChangedSignal("Text"), rebuildList)
            rebuildList()
        end

        -- Open the searchable vertical config list instead of the shared dropdown.
        S.__helpers.connect(configListButton.Activated, showConfigListPopup)
    end
end

-- ================================================================
-- Minimal cleanup for the retained feature set.
_G.StaminaSettingsCleanup = function()
    S.roleGateRunning = false
    pcall(function() if S.__helpers.setAutoBlockEnabled then S.__helpers.setAutoBlockEnabled(false) end end)
    pcall(function() if S.__helpers.stopAutoBlockButtonClone then S.__helpers.stopAutoBlockButtonClone() end end)
    pcall(function() if S.applyShowChatState then S.applyShowChatState(false) end end)
    pcall(function() if S.__helpers.setChangeGameFontEnabled then S.__helpers.setChangeGameFontEnabled(false) end end)
    pcall(function() if S.setExtendedFOVEnabled then S.setExtendedFOVEnabled(false) end end)
    pcall(function() if S.setStretchEnabled then S.setStretchEnabled(false) end end)
    pcall(function() if S.__helpers.setHidePlayerIconEnabled then S.__helpers.setHidePlayerIconEnabled(false) end end)
    pcall(function()
        if S.__helpers.setDeviceSpoofEnabled then S.__helpers.setDeviceSpoofEnabled(false) end
        if S.lp then S.lp:SetAttribute("Device", S.deviceSpoofOriginalAttribute) end
    end)
    S.isAutoStudsEnabled = false
    S.isAutoStabEnabled = false
    S.doitmate = false
    S.isAntiBaitEnabled = false
    S.antiBaitActive = false
    S.antiBaitToken = (tonumber(S.antiBaitToken) or 0) + 1
    S.isHitboxDragEnabled = false
    pcall(function() S.__helpers.stopFile2Aim("AutoClone") end)
    pcall(function() S.__helpers.stopFile2Aim("HitboxDrag") end)
    S.hitboxDragToken = (tonumber(S.hitboxDragToken) or 0) + 1
    if S.hitboxDragSession and type(S.hitboxDragSession.cleanup) == "function" then
        pcall(S.hitboxDragSession.cleanup)
    end
    S.isDashstabEnabled = false
    S.isInfStaminaEnabled = false
    S.isLegitInfStaminaEnabled = false
    S.isMaxStaminaEnabled = false
    S.isMinStaminaEnabled = false
    S.isStaminaLossEnabled = false
    S.isStaminaGainEnabled = false
    S.isSprintSpeedEnabled = false
    S.isNoSprintTweeningEnabled = false
    S.isStaminaPresetEnabled = false
    S.isStaminaNumberEnabled = false
    S.staminaPreset = "Original"
    S.staminaManualValue = nil
    pcall(function() if S.__helpers.restoreLegitInfStaminaLoss then S.__helpers.restoreLegitInfStaminaLoss() end end)
    pcall(function() if S.__helpers.applyStaminaSettings then S.__helpers.applyStaminaSettings(S.SprintingModule) end end)
    pcall(function() if S.__helpers.updateStaminaPresetUI then S.__helpers.updateStaminaPresetUI() end end)
    pcall(function() if S.__helpers.updateStaminaBar then S.__helpers.updateStaminaBar() end end)
    pcall(function() if S.__helpers.setPrivacyBypass then S.__helpers.setPrivacyBypass(false) end end)
    -- Script reload must fully release temporary Equip Skin overrides. Calling
    -- deactivate while enabled would otherwise preserve the selected TwoTime
    -- Equip value and leave its private Heartbeat monitor running.
    if S.SkinChanger then
        S.SkinChanger.enabled = false
        if S.SkinChanger.genericEquipHeartbeatConnection then
            pcall(function() S.SkinChanger.genericEquipHeartbeatConnection:Disconnect() end)
            S.SkinChanger.genericEquipHeartbeatConnection = nil
        end
    end
    pcall(function() if S.SkinChanger and S.SkinChanger.deactivate then S.SkinChanger.deactivate() end end)
    pcall(function() if S.__helpers.setKillerOverlapNoclip then S.__helpers.setKillerOverlapNoclip(false) end end)

    -- Stop the Auto Generator hooks cleanly; module wrappers remain dormant while disabled.
    pcall(function() if S.AutoGenerator and S.AutoGenerator.setEnabled then S.AutoGenerator:setEnabled(false) end end)

    -- Clean up selectively imported File 2 features.
    pcall(function() if S.__helpers.setSprayESP then S.__helpers.setSprayESP(false) end end)
    pcall(function() if S.setVeeronicaAutoTrick then S.setVeeronicaAutoTrick(false) end end)
    pcall(function() if S.setVeeronicaFreeMove then S.setVeeronicaFreeMove(false) end end)
    pcall(function() if S.__helpers.setVeeronicaCollisionDamageDisabled then S.__helpers.setVeeronicaCollisionDamageDisabled(false) end end)
    pcall(function() if S.__helpers.setAutoLMSAbility then S.__helpers.setAutoLMSAbility(false) end end)
    pcall(function() if S.__helpers.setAutoInvisWhenUndetectable then S.__helpers.setAutoInvisWhenUndetectable(false) end end)
    pcall(function() if S.__helpers.stopChanceShoot360Spin then S.__helpers.stopChanceShoot360Spin() end end)
    pcall(function() if S.__helpers.setAutoSlashEnabled then S.__helpers.setAutoSlashEnabled(false) end end)
    pcall(function() if S.__helpers.setBetterVoidRush then S.__helpers.setBetterVoidRush(false) end end)
    pcall(function() if S.__helpers.setC00lkiddDashControl then S.__helpers.setC00lkiddDashControl(false) end end)
    pcall(function() if S.JaneDoeAutoHatchet and S.JaneDoeAutoHatchet.setEnabled then S.JaneDoeAutoHatchet.setEnabled(false) end end)
    pcall(function() if S.__helpers.setJaneDoeInstantThrow then S.__helpers.setJaneDoeInstantThrow(false) end end)
    pcall(function() if S.__helpers.setJaneDoeInfiniteCrystalHold then S.__helpers.setJaneDoeInfiniteCrystalHold(false) end end)
    pcall(function() if S.__helpers.setJaneAimbot then S.__helpers.setJaneAimbot(false) end end)
    pcall(function() if S.__helpers.setJaneAxeLock then S.__helpers.setJaneAxeLock(false) end end)
    pcall(function() if S.AutoBackstab and S.AutoBackstab.stop then S.AutoBackstab.stop() end end)
    pcall(function() if S.LMSChanger and S.LMSChanger.cleanup then S.LMSChanger.cleanup() end end)
    -- Stop the imported Animation Changer and restore any Ghost Ability callback hooks.
    pcall(function()
        if S.AnimationChanger and S.AnimationChanger.shutdown then
            S.AnimationChanger.shutdown()
        end
    end)
    pcall(function()
        local ghostState = S.GhostAbilities
        if ghostState and type(ghostState.hooks) == "table" then
            for key, hookState in pairs(ghostState.hooks) do
                if type(hookState) == "table" then
                    if type(hookfunction) == "function"
                        and type(hookState.callback) == "function"
                        and type(hookState.original) == "function" then
                        pcall(function() hookfunction(hookState.callback, hookState.original) end)
                    end
                    if hookState.ability and hookState.ability.Callback == hookState.callback then
                        pcall(function() hookState.ability.Callback = hookState.original end)
                    end
                end
                ghostState.hooks[key] = nil
            end
        end
    end)
    pcall(function() if S.AudioReplacementCleanup then S.AudioReplacementCleanup() end end)
    S.isMassInfectionAimbotEnabled = false
    S.isEntanglementAimbotEnabled = false
    S.isDusekkarSilentAimEnabled = false
    S.isDusekkarTargetSurvivorEnabled = false
    S.isEliotThrowPizzaAimbotEnabled = false
    S.isC00lkiddCorruptNatureSilentAimEnabled = false
    S.isNoliVoidStarSilentAimEnabled = false
    S.isNosferatuBloodHookAimbotEnabled = false
    S.isJohnDoeCorruptEnergyAimbotEnabled = false
    S.isNoliRushAutoTargetEnabled = false
    pcall(function() if S.AutoRagingPace and S.AutoRagingPace.setEnabled then S.AutoRagingPace.setEnabled(false) end end)
    pcall(function()
        if S.AzureQTE then
            S.AzureQTE.auto, S.AzureQTE.infinite = false, false
            if S.AzureQTE.stopManual then S.AzureQTE.stopManual() end
            if S.AzureQTE.refresh then S.AzureQTE.refresh() end
        end
    end)
    pcall(function()
        if S.AzureAim then
            S.AzureAim.tentacles, S.AzureAim.unearthing = false, false
            S.isAzureTentaclesAimEnabled, S.isAzureUnearthingAimEnabled = false, false
            if S.AzureAim.restoreHooks then S.AzureAim.restoreHooks() end
        end
    end)
    pcall(function()
        if S.NosferatuExtras then
            if S.NosferatuExtras.setHookEnabled then S.NosferatuExtras.setHookEnabled(false) end
            S.NosferatuExtras.unlimitedFly = false
            S.NosferatuExtras.diveControl = false
            S.NosferatuExtras.cataclysmControl = false
            S.NosferatuExtras.diveAimEnabled = false
            if S.NosferatuExtras.applyConfig then S.NosferatuExtras.applyConfig() end
            if S.NosferatuExtras.stopDiveAim then S.NosferatuExtras.stopDiveAim() end
            if S.NosferatuExtras.animationConnection then
                S.NosferatuExtras.animationConnection:Disconnect()
                S.NosferatuExtras.animationConnection = nil
            end
        end
    end)
    pcall(function()
        if S.SlasherExtras then
            S.SlasherExtras.customRagingPaceSpeed = false
            if S.SlasherExtras.apply then S.SlasherExtras.apply() end
        end
    end)
    pcall(function() if S.NoliRushAntiCrashState and S.NoliRushAntiCrashState.setEnabled then S.NoliRushAntiCrashState.setEnabled(false) end end)
    pcall(function() if S.__helpers.setNoclip then S.__helpers.setNoclip(false) end end)
    pcall(function() if S.__helpers.setEnableJumping then S.__helpers.setEnableJumping(false) end end)
    pcall(function() if S.__helpers.setJDDigitalFootprintsESP then S.__helpers.setJDDigitalFootprintsESP(false) end end)
    pcall(function() if S.__helpers.setInfBloxyColaEnabled then S.__helpers.setInfBloxyColaEnabled(false) end end)
    pcall(function() if S.__helpers.setHitboxExpanderEnabled then S.__helpers.setHitboxExpanderEnabled(false) end end)
    pcall(function()
        S.invisibilityEnabled = false
        if S.invisibilityTrack then
            S.invisibilityTrack:Stop(0.05)
            S.invisibilityTrack:Destroy()
            S.invisibilityTrack = nil
        end
    end)
    pcall(function()
        for _, state in ipairs(S.funEmoteButtonOrder or {}) do
            state.enabled = false
            if S.__helpers.stopFunEmoteTrack then S.__helpers.stopFunEmoteTrack(state, 0) end
        end
        S.funEmoteMotionBusy = false
    end)
    S.fakeBlockEnabled = false
    S.fakeBlockButtonEnabled = false
    pcall(function()
        if S.fakeBlockScreenButton then S.fakeBlockScreenButton.Visible = false end
        for _, state in ipairs(S.funEmoteButtonOrder or {}) do
            if state.screenButton then state.screenButton.Visible = false end
        end
    end)
    pcall(function() if S.__helpers.stopAzureTrapESP then S.__helpers.stopAzureTrapESP() end end)
    pcall(function() if S.__helpers.stopAzureTrapRadiusESP then S.__helpers.stopAzureTrapRadiusESP() end end)
    pcall(function() if S.__helpers.cleanupHitboxPreview then S.__helpers.cleanupHitboxPreview() end end)
    pcall(function()
        local root = workspace:FindFirstChild(S.ROOT_FOLDER_NAME)
        if root and root:IsA("Folder") then root:Destroy() end
    end)
    pcall(function()
        local root = S.CoreGui:FindFirstChild(S.ROOT_FOLDER_NAME)
        if root and root:IsA("Folder") then root:Destroy() end
    end)
    pcall(function() if S.setFullBright then S.setFullBright(false) end end)
    for key in pairs(S.E1LU4SAKENAimTokens or {}) do S.E1LU4SAKENAimTokens[key] += 1 end
    S.massInfectionAimbotToken = (S.massInfectionAimbotToken or 0) + 1
    S.entanglementAimbotToken = (S.entanglementAimbotToken or 0) + 1
    S.shedletskyAimbotToken = (S.shedletskyAimbotToken or 0) + 1
    for _, state in pairs(S.worldKeywordESPStates or {}) do
        pcall(function()
            state.enabled = false
            if state.addConnection then state.addConnection:Disconnect(); state.addConnection = nil end
            for target, entry in pairs(state.objects or {}) do
                if entry.ancestryConnection then entry.ancestryConnection:Disconnect() end
                if entry.highlight then entry.highlight:Destroy() end
                state.objects[target] = nil
            end
        end)
    end
    pcall(function()
        if S.__helpers.cleanupPreviewScrollLock then
            S.__helpers.cleanupPreviewScrollLock()
        end
    end)
    pcall(function() S.__helpers.disconnectAll() end)
end

task.defer(function()
    if S.__helpers.notify then
        S.__helpers.notify("E1LU4 HUB", "UI has been loaded.", 4.2, S.NOTIFICATION_SUCCESS_COLOR)
    end
end)

-- Move the requested Auto Block settings into the existing main AUTO BLOCK
-- card after the legacy controls have been distributed into section cards.
-- Keep the TOGGLE card and all unrelated controls in their original groups.
S.__helpers.moveAutoBlockSettingsIntoMainGroup = function()
    local masterToggle = S.autoBlockToggleButton
    if not (masterToggle and masterToggle.Parent) then
        return false
    end

    local targetParent = masterToggle.Parent
    local controls = {
        S.shakeCameraToggleButton,
        S.autoBlockDetectionModeButton,
        S.autoBlockRangeContainer,
        S.facingCheckToggleButton,
        S.facingCheckAngleContainer,
        S.facingCheckESPRangeContainer,
        S.autoBlockRangeESPToggleButton,
    }

    local maxOrder = 0
    for _, child in ipairs(targetParent:GetChildren()) do
        if child:IsA("GuiObject") then
            maxOrder = math.max(maxOrder, tonumber(child.LayoutOrder) or 0)
        end
    end

    for _, control in ipairs(controls) do
        if control and control:IsA("GuiObject") then
            control.Parent = targetParent
            maxOrder = maxOrder + 10
            control.LayoutOrder = maxOrder
        end
    end
    return true
end

pcall(function()
    if S.__helpers.moveAutoBlockSettingsIntoMainGroup then
        S.__helpers.moveAutoBlockSettingsIntoMainGroup()
    end
end)

-- Place the Auto Block Range preview immediately after SHOW AUTO BLOCK RANGE
-- inside the actual Auto Block section contents. By this point the legacy
-- staging frame has already been migrated into category pages and wrapped in
-- section cards, so using S.contentFrame here would target the wrong parent.
S.__helpers.placeAutoBlockRangePreviewAfterToggle = function()
    local card = S.autoBlockRangePreviewCard
    local anchorToggle = S.autoBlockRangeESPToggleButton
    if not (card and card.Parent and anchorToggle and anchorToggle.Parent) then
        return false
    end

    local targetParent = anchorToggle.Parent
    if card.Parent ~= targetParent then
        -- Both controls belong to the AUTO BLOCK section. Reparent explicitly
        -- so the preview participates in the same vertical UIListLayout.
        card.Parent = targetParent
    end

    local ordered = {}
    for childIndex, child in ipairs(targetParent:GetChildren()) do
        if child:IsA("GuiObject") and child ~= card then
            ordered[#ordered + 1] = {
                object = child,
                layoutOrder = tonumber(child.LayoutOrder) or 0,
                childIndex = childIndex,
            }
        end
    end
    table.sort(ordered, function(a, b)
        if a.layoutOrder == b.layoutOrder then
            return a.childIndex < b.childIndex
        end
        return a.layoutOrder < b.layoutOrder
    end)

    local rows = {}
    for _, entry in ipairs(ordered) do
        rows[#rows + 1] = entry.object
    end

    local anchorIndex = nil
    for index, object in ipairs(rows) do
        if object == anchorToggle then
            anchorIndex = index
            break
        end
    end
    if not anchorIndex then
        return false
    end

    -- Remove any old position for the preview, then insert it directly below
    -- the target toggle and before USE HITBOX / subsequent controls.
    for index = #rows, 1, -1 do
        if rows[index] == card then
            table.remove(rows, index)
        end
    end
    anchorIndex = nil
    for index, object in ipairs(rows) do
        if object == anchorToggle then
            anchorIndex = index
            break
        end
    end
    if not anchorIndex then
        return false
    end
    table.insert(rows, anchorIndex + 1, card)

    for index, object in ipairs(rows) do
        object.LayoutOrder = index * 10
    end
    return true
end

pcall(function()
    if S.__helpers.placeAutoBlockRangePreviewAfterToggle then
        S.__helpers.placeAutoBlockRangePreviewAfterToggle()
    end
end)

-- Reliable preview hover-scroll lock for the FINAL category-page layout.
-- The preview cards are initially created in the hidden legacy staging frame,
-- then migrated into Page_AutoBlock. Locking S.contentFrame therefore has no
-- effect on the page the user actually scrolls. Resolve the live ScrollingFrame
-- from the preview card's current ancestry and hit-test the cursor every frame.
S.previewScrollLockState = S.previewScrollLockState or {
    target = nil,
    originalEnabled = nil,
    lockedCanvasPosition = nil,
}
S.__helpers.isPreviewGuiVisible = function(gui)
    if not gui or not gui.Parent then return false end
    local node = gui
    while node do
        if node:IsA("GuiObject") and node.Visible ~= true then
            return false
        end
        if node:IsA("ScreenGui") and node.Enabled ~= true then
            return false
        end
        node = node.Parent
    end
    return true
end
S.__helpers.getPreviewAncestorScrollingFrame = function(gui)
    local node = gui
    while node do
        if node:IsA("ScrollingFrame") then
            return node
        end
        node = node.Parent
    end
    return nil
end
S.__helpers.isPointerInsidePreview = function(gui, pointer)
    if not S.__helpers.isPreviewGuiVisible(gui) then return false end
    local position = gui.AbsolutePosition
    local size = gui.AbsoluteSize
    return pointer.X >= position.X
        and pointer.X <= position.X + size.X
        and pointer.Y >= position.Y
        and pointer.Y <= position.Y + size.Y
end
S.__helpers.updatePreviewScrollLock = function()
    local content = S.previewScrollLockState
    if not content then return end

    local pointer = S.UserInputService:GetMouseLocation()
    local hoveredGui = nil
    if S.__helpers.isPointerInsidePreview(S.hitboxPreviewCard, pointer) then
        hoveredGui = S.hitboxPreviewCard
    elseif S.__helpers.isPointerInsidePreview(S.autoBlockRangePreviewCard, pointer) then
        hoveredGui = S.autoBlockRangePreviewCard
    end

    local desiredTarget = hoveredGui
        and S.__helpers.getPreviewAncestorScrollingFrame(hoveredGui)
        or nil

    if content.target ~= desiredTarget then
        local previous = content.target
        if previous and previous.Parent and content.originalEnabled ~= nil then
            pcall(function()
                previous.ScrollingEnabled = content.originalEnabled
            end)
        end
        content.target = desiredTarget
        content.originalEnabled = nil
        content.lockedCanvasPosition = nil
        if desiredTarget and desiredTarget.Parent then
            content.originalEnabled = desiredTarget.ScrollingEnabled
            content.lockedCanvasPosition = desiredTarget.CanvasPosition
        end
    end

    if desiredTarget and desiredTarget.Parent then
        -- Reassert while hovered in case the page or another UI callback
        -- attempts to restore scrolling during the same interaction. Keep the
        -- canvas position as a second guard against wheel/trackpad scroll leaks.
        desiredTarget.ScrollingEnabled = false
        if content.lockedCanvasPosition
            and desiredTarget.CanvasPosition ~= content.lockedCanvasPosition then
            desiredTarget.CanvasPosition = content.lockedCanvasPosition
        end
    end
end
S.previewScrollLockConnection = S.__helpers.connect(S.RunService.RenderStepped, function()
    pcall(S.__helpers.updatePreviewScrollLock)
end)
S.__helpers.cleanupPreviewScrollLock = function()
    local state = S.previewScrollLockState
    if state and state.target and state.target.Parent and state.originalEnabled ~= nil then
        pcall(function()
            state.target.ScrollingEnabled = state.originalEnabled
        end)
    end
    if state then
        state.target = nil
        state.originalEnabled = nil
        state.lockedCanvasPosition = nil
    end
end

